import {
  BookOpen,
  Check,
  Code2,
  Copy,
  Download,
  FileDown,
  FileUp,
  Image,
  Share2,
  Smartphone,
  Upload,
  X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { createPortal } from "react-dom";
import {
  LESSON_EXTENSION,
  LESSON_MIME,
  PORTABLE_WORKSPACE_LABELS,
  PORTABLE_WORKSPACE_ROUTES,
  WORKSPACE_EXTENSION,
  WORKSPACE_MIME,
  createDefaultLesson,
  createPortableMathFile,
  downloadPortableFile,
  parsePortableMathFile,
  portableFilename,
  sceneForLessonMode,
  serializePortableMathFile,
  type LessonOpenMode,
  type PortableMathFile,
  type PortableWorkspaceAdapter,
} from "../../workspace/portableWorkspace";
import {
  copyPreparedImage,
  downloadPreparedImage,
  imageFilename,
  nativeSharePreparedImage,
  prepareWorkspaceImage,
  releasePreparedImage,
  type ImageExportBackground,
  type ImageExportFormat,
  type ImageExportScale,
  type ImageExportScope,
  type PreparedWorkspaceImage,
} from "../../workspace/workspaceImageExport";
import EmbedCodePanel from "../../embed/EmbedCodePanel";
import { EMBED_KIND_FOR_WORKSPACE, embedSceneFromPortable } from "../../embed/fromWorkspace";
import type { EmbedScene } from "../../embed/engine";

const PENDING_IMPORT_KEY = "math-universe-portable-import";

type Props = { adapter: PortableWorkspaceAdapter; className?: string };
type PanelView = "menu" | "image" | "import" | "lesson";

export default function ShareExportControl({ adapter, className = "" }: Props) {
  const anchorRef=useRef<HTMLDivElement>(null);
  const overlay=(node:ReactNode)=>{
    if(typeof document==='undefined')return node;
    const root = anchorRef.current?.closest("[data-chrome-theme],[data-shapes-theme],[data-geometry-theme]");
    const theme = root?.getAttribute("data-chrome-theme")
      ?? root?.getAttribute("data-shapes-theme")
      ?? root?.getAttribute("data-geometry-theme")
      ?? "light";
    return createPortal(
      <div className="studio-themed-portal" data-chrome-theme={theme}>{node}</div>,
      document.body,
    );
  };
  const [open, setOpen] = useState(false);
  const [view, setView] = useState<PanelView>("menu");
  const [status, setStatus] = useState("Ready");
  const [embedScene, setEmbedScene] = useState<EmbedScene | null>(null);
  const canEmbed = Boolean(EMBED_KIND_FOR_WORKSPACE[adapter.workspaceType]);
  const [busy, setBusy] = useState(false);
  const [prepared, setPrepared] = useState<PreparedWorkspaceImage | null>(null);
  const [scope, setScope] = useState<ImageExportScope>(
    adapter.workspaceType === "cas" ? "entire" : "viewport",
  );
  const [background, setBackground] = useState<ImageExportBackground>("white");
  const [scale, setScale] = useState<ImageExportScale>(2);
  const [format, setFormat] = useState<ImageExportFormat>("png");
  const [imported, setImported] = useState<PortableMathFile | null>(null);
  const [importName, setImportName] = useState("");
  const [importWarnings, setImportWarnings] = useState<string[]>([]);
  const [lessonMode, setLessonMode] = useState<LessonOpenMode>("practice");
  const [lastSavedSnapshot, setLastSavedSnapshot] = useState(() =>
    safeSnapshot(adapter),
  );
  const fileInput = useRef<HTMLInputElement>(null);
  const initialScene = useRef<unknown>(null);
  const solutionScene = useRef<unknown>(null);
  const checkpointScenes = useRef<
    Array<{
      id: string;
      title: string;
      instructions: string;
      scene: unknown;
      validationRules: string[];
    }>
  >([]);
  const [lessonForm, setLessonForm] = useState({
    title: `${PORTABLE_WORKSPACE_LABELS[adapter.workspaceType]} lesson`,
    description: "",
    difficulty: "intermediate",
    grade: "",
    topic: "",
    instructions: "",
    tags: "",
    hints: "",
    steps: "",
    expected: "",
    teacherNotes: "",
  });
  const summary = useMemo(
    () => adapter.getSceneSummary(),
    [adapter, open, view],
  );
  const dirty = safeSnapshot(adapter) !== lastSavedSnapshot;

  useEffect(() => () => releasePreparedImage(prepared), [prepared]);

  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    if (!query.has("portableImport")) return;
    const raw = sessionStorage.getItem(PENDING_IMPORT_KEY);
    if (!raw) return;
    void parsePortableMathFile(raw).then((result) => {
      if (!result.ok || result.file.workspace.type !== adapter.workspaceType)
        return;
      const mode = result.file.lesson?.openMode ?? "practice";
      void adapter.deserializeScene(
        sceneForLessonMode(result.file, mode),
        "replace",
      );
      sessionStorage.removeItem(PENDING_IMPORT_KEY);
      query.delete("portableImport");
      const next = `${window.location.pathname}${query.size ? `?${query}` : ""}${window.location.hash}`;
      window.history.replaceState({}, "", next);
      setLastSavedSnapshot(safeSnapshot(adapter));
      setStatus(
        result.file.fileHeader.fileKind === "lesson"
          ? `Lesson opened in ${capital(mode)} Mode.`
          : `${result.file.preview.objectCount} objects imported successfully.`,
      );
    });
  }, [adapter]);

  useEffect(() => {
    const warn = (event: BeforeUnloadEvent) => {
      if (safeSnapshot(adapter) !== lastSavedSnapshot) {
        event.preventDefault();
        event.returnValue = "";
      }
    };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [adapter, lastSavedSnapshot]);

  const close = () => {
    setOpen(false);
    setView("menu");
    setImported(null);
    setImportWarnings([]);
    setStatus("Ready");
  };
  const show = (next: PanelView) => {
    setView(next);
    setOpen(true);
    setStatus("Ready");
  };

  async function prepareImage() {
    const target = adapter.getImageTarget(scope);
    if (!target) {
      setStatus("The workspace viewport is not available yet.");
      return;
    }
    setBusy(true);
    setStatus(scale === 1 ? "Preparing image…" : "Rendering HD output…");
    releasePreparedImage(prepared);
    setPrepared(null);
    try {
      const next = await prepareWorkspaceImage({
        target,
        scope,
        background,
        scale,
        format,
        filename: imageFilename(adapter.workspaceType, format),
      });
      setPrepared(next);
      setStatus("Image preview ready.");
    } catch (error) {
      setStatus(message(error, "The image could not be prepared."));
    } finally {
      setBusy(false);
    }
  }

  async function exportWorkspace() {
    setBusy(true);
    setStatus("Preparing workspace file…");
    try {
      const file = await createPortableMathFile({
        kind: "workspace",
        adapter,
        title: adapter.title(),
        scene: adapter.serializeScene(),
      });
      downloadPortableFile(file);
      setLastSavedSnapshot(safeSnapshot(adapter));
      setStatus("Workspace file exported.");
    } catch (error) {
      setStatus(message(error, "The workspace file could not be exported."));
    } finally {
      setBusy(false);
    }
  }

  async function readImport(file: File) {
    setBusy(true);
    setStatus("Importing objects…");
    setImported(null);
    setImportName(file.name);
    if (file.size > 25 * 1024 * 1024) {
      setStatus("This workspace file is too large to open safely.");
      setBusy(false);
      return;
    }
    const result = await parsePortableMathFile(
      await file.text(),
      file.name,
      file.type,
    );
    if (!result.ok) setStatus(result.error);
    else {
      setImported(result.file);
      setImportWarnings(result.warnings);
      setStatus("File validated. Review the preview before opening.");
    }
    setBusy(false);
  }

  async function applyImport(mode: "replace" | "merge" | "new") {
    if (!imported) return;
    const targetType = imported.workspace.type;
    const targetRoute = PORTABLE_WORKSPACE_ROUTES[targetType];
    const scene = sceneForLessonMode(imported, lessonMode);
    if (targetType !== adapter.workspaceType || mode === "new") {
      const payload = {
        ...imported,
        lesson: imported.lesson
          ? { ...imported.lesson, openMode: lessonMode }
          : undefined,
      };
      sessionStorage.setItem(
        PENDING_IMPORT_KEY,
        serializePortableMathFile(payload),
      );
      const url = `${targetRoute}?portableImport=1`;
      if (mode === "new") window.open(url, "_blank", "noopener");
      else window.location.assign(url);
      return;
    }
    if (
      mode === "replace" &&
      dirty &&
      !window.confirm(
        "Replace the current workspace? Export the existing work first if you need a portable copy.",
      )
    )
      return;
    setBusy(true);
    setStatus("Restoring workspace…");
    try {
      const warnings = adapter.validateScene?.(scene) ?? [];
      if (warnings.length) throw new Error(warnings[0]);
      await adapter.deserializeScene(scene, mode);
      setLastSavedSnapshot(safeSnapshot(adapter));
      setStatus(
        imported.fileHeader.fileKind === "lesson"
          ? `Lesson opened in ${capital(lessonMode)} Mode.`
          : `${imported.preview.objectCount} objects imported successfully.`,
      );
      setImported(null);
    } catch (error) {
      setStatus(message(error, "The workspace could not be restored."));
    } finally {
      setBusy(false);
    }
  }

  async function exportLesson() {
    setBusy(true);
    setStatus("Preparing workspace file…");
    try {
      const current = adapter.serializeScene();
      const lesson = createDefaultLesson(
        adapter.workspaceType,
        lessonForm.title,
        initialScene.current ?? current,
      );
      lesson.shortDescription = lessonForm.description;
      lesson.difficulty = lessonForm.difficulty as typeof lesson.difficulty;
      lesson.gradeLevel = splitComma(lessonForm.grade);
      lesson.topic = lessonForm.topic;
      lesson.instructions = splitLines(lessonForm.instructions);
      lesson.tags = splitComma(lessonForm.tags);
      lesson.hints = splitLines(lessonForm.hints);
      lesson.solutionSteps = splitLines(lessonForm.steps);
      lesson.expectedResult = lessonForm.expected;
      lesson.teacherNotes = lessonForm.teacherNotes;
      lesson.initialScene = initialScene.current ?? current;
      lesson.solutionScene = solutionScene.current ?? current;
      lesson.checkpoints = checkpointScenes.current;
      const file = await createPortableMathFile({
        kind: "lesson",
        adapter,
        title: lesson.title,
        description: lesson.shortDescription,
        tags: lesson.tags,
        difficulty: lesson.difficulty,
        gradeLevel: lesson.gradeLevel,
        topic: lesson.topic,
        scene: lesson.initialScene,
        lesson,
      });
      downloadPortableFile(file);
      setLastSavedSnapshot(safeSnapshot(adapter));
      setStatus("Lesson file exported.");
    } catch (error) {
      setStatus(message(error, "The lesson file could not be exported."));
    } finally {
      setBusy(false);
    }
  }

  return (
    <div
      ref={anchorRef}
      className={`portable-share-anchor ${className}`}
      data-portable-export-exclude
    >
      <button
        type="button"
        className="portable-share-trigger"
        onClick={() => setOpen(true)}
        title="Share or export"
        aria-label="Share or export"
        data-can-embed={canEmbed ? "true" : "false"}
      >
        <Share2 />
        <span>Share</span>
      </button>
      {embedScene &&
        overlay(
          <EmbedCodePanel scene={embedScene} onClose={() => setEmbedScene(null)} />,
        )}
      {open &&
        overlay(
        <div
          className="portable-modal-backdrop"
          data-share-export-dialog="true"
          onMouseDown={(event) =>
            event.target === event.currentTarget && close()
          }
        >
          <section
            className="portable-dialog"
            role="dialog"
            aria-modal="true"
            aria-label="Share & Export"
          >
            <header>
              <div>
                <span>{PORTABLE_WORKSPACE_LABELS[adapter.workspaceType]}</span>
                <h2>Share &amp; Export</h2>
              </div>
              <button
                type="button"
                onClick={close}
                aria-label="Close Share & Export"
              >
                <X />
              </button>
            </header>
            {view !== "menu" && (
              <button
                type="button"
                className="portable-back"
                onClick={() => setView("menu")}
              >
                ← Back to Share &amp; Export
              </button>
            )}
            {view === "menu" && (
              <div className="portable-action-grid">
                <Action
                  icon={<Share2 />}
                  title="Share as Image"
                  note="Prepare a preview for native sharing"
                  onClick={() => show("image")}
                />
                <Action
                  icon={<Image />}
                  title="Download HD Image"
                  note="PNG or JPEG, 2× HD by default"
                  onClick={() => show("image")}
                />
                <Action
                  icon={<Copy />}
                  title="Copy Image"
                  note="Available when the Clipboard API supports images"
                  onClick={() => show("image")}
                />
                <Action
                  icon={<FileDown />}
                  title="Export Workspace File"
                  note={`${portableFilename(adapter.title(), adapter.workspaceType, "workspace")}`}
                  onClick={() => void exportWorkspace()}
                />
                <Action
                  icon={<FileUp />}
                  title="Import Workspace File"
                  note={`${WORKSPACE_EXTENSION} or ${LESSON_EXTENSION}`}
                  onClick={() => show("import")}
                />
                <Action
                  icon={<BookOpen />}
                  title="Save as Lesson"
                  note="Starting scene, hints, checkpoints and solution"
                  onClick={() => show("lesson")}
                />
                {canEmbed && (
                  <Action
                    icon={<Code2 />}
                    title="Embed on a website"
                    note="iframe, script tag, and live preview"
                    onClick={() => {
