                    </select>
                  </label>
                  <label>
                    Background
                    <select
                      value={background}
                      onChange={(event) =>
                        setBackground(
                          event.target.value as ImageExportBackground,
                        )
                      }
                    >
                      <option value="transparent">Transparent</option>
                      <option value="white">White</option>
                      <option value="dark">Dark</option>
                    </select>
                  </label>
                  <label>
                    Resolution
                    <select
                      value={scale}
                      onChange={(event) =>
                        setScale(Number(event.target.value) as ImageExportScale)
                      }
                    >
                      <option value="1">1×</option>
