                      <option value="4">4× ultra-HD</option>
                    </select>
                  </label>
                  <label>
                    Format
                    <select
                      value={format}
                      onChange={(event) =>
                        setFormat(event.target.value as ImageExportFormat)
                      }
                    >
                      <option value="png">PNG</option>
                      <option value="jpeg">JPEG</option>
                    </select>
                  </label>
                </div>
                <button
                  type="button"
                  className="portable-primary"
                  onClick={() => void prepareImage()}
                  disabled={busy}
                >
                  {busy ? "Rendering HD output…" : "Prepare image preview"}
                </button>
                {prepared && (
                  <div className="portable-preview">
                    <img
                      src={prepared.previewUrl}
                      alt="Prepared workspace export preview"
                    />
                    <dl>
                      <div>
                        <dt>Filename</dt>
                        <dd>{prepared.filename}</dd>
                      </div>
                      <div>
                        <dt>Format</dt>
                        <dd>{prepared.format.toUpperCase()}</dd>
                      </div>
                      <div>
                        <dt>Resolution</dt>
                        <dd>
                          {prepared.scale}× · {prepared.width} ×{" "}
                          {prepared.height}px
                        </dd>
                      </div>
                      <div>
                        <dt>Background</dt>
                        <dd>{prepared.background}</dd>
                      </div>
                    </dl>
                    <div className="portable-preview-actions">
                      <button
                        type="button"
                        onClick={() => {
                          downloadPreparedImage(prepared);
                          setStatus("HD image downloaded.");
                        }}
                      >
                        <Download />
                        Download
                      </button>
                      <button
                        type="button"
                        onClick={() =>
                          void copyPreparedImage(prepared)
