                            .catch((error) =>
                              setStatus(
                                message(error, "Copy Image is unavailable."),
                              ),
                            )
                        }
                      >
                        <Copy />
                        Copy
                      </button>
                      <button
                        type="button"
                        onClick={() =>
                          void nativeSharePreparedImage(
                            prepared,
                            adapter.title(),
                          )
                            .then(() => setStatus("Native share opened."))
                            .catch((error) =>
                              setStatus(
                                message(error, "Image sharing is unavailable."),
                              ),
                            )
