                  event.preventDefault();
                  const file = event.dataTransfer.files[0];
                  if (file) void readImport(file);
                }}
              >
                <input
                  ref={fileInput}
                  hidden
                  type="file"
                  accept={`${WORKSPACE_EXTENSION},${LESSON_EXTENSION},${WORKSPACE_MIME},${LESSON_MIME}`}
                  onChange={(event) => {
                    const file = event.target.files?.[0];
                    if (file) void readImport(file);
                  }}
