                  <button
                    type="button"
                    className="portable-dropzone"
                    onClick={() => fileInput.current?.click()}
                  >
                    <Upload />
                    <strong>Choose or drop a workspace file</strong>
                    <span>Files are validated locally and never uploaded.</span>
                  </button>
