                      <div>
                        <dt>File</dt>
                        <dd>{importName}</dd>
                      </div>
                      <div>
                        <dt>Kind</dt>
                        <dd>{capital(imported.fileHeader.fileKind)}</dd>
                      </div>
                      <div>
                        <dt>Workspace</dt>
                        <dd>{imported.workspace.typeLabel}</dd>
                      </div>
                      <div>
                        <dt>Title</dt>
                        <dd>{imported.document.title}</dd>
                      </div>
                      <div>
                        <dt>Description</dt>
                        <dd>{imported.document.description || "—"}</dd>
                      </div>
                      <div>
                        <dt>Author</dt>
                        <dd>{imported.document.author.name || "—"}</dd>
                      </div>
                      <div>
                        <dt>Created</dt>
                        <dd>
