                            imported.document.createdAt,
                          ).toLocaleString()}
                        </dd>
                      </div>
                      <div>
                        <dt>Schema</dt>
                        <dd>
                          v{imported.fileHeader.schemaVersion} · app{" "}
                          {imported.fileHeader.createdByAppVersion}
                        </dd>
                      </div>
                      <div>
                        <dt>Content</dt>
                        <dd>
                          {imported.preview.objectCount} objects ·{" "}
                          {imported.preview.expressionCount} expressions
                        </dd>
                      </div>
                      {imported.lesson && (
                        <>
                          <div>
                            <dt>Difficulty</dt>
                            <dd>
                              {imported.lesson.difficulty} · grades{" "}
                              {imported.lesson.gradeLevel.join(", ") || "—"}
                            </dd>
                          </div>
                          <div>
                            <dt>Solutions</dt>
                            <dd>
                              {imported.lesson.hints.length} hints ·{" "}
                              {imported.lesson.solutionSteps.length} steps
                            </dd>
                          </div>
                        </>
                      )}
                    </dl>
                    {importWarnings.map((warning) => (
                      <p className="portable-warning" key={warning}>
                        {warning}
                      </p>
                    ))}
                    {imported.lesson && (
                      <label>
                        Open lesson mode
                        <select
                          value={lessonMode}
                          onChange={(event) =>
                            setLessonMode(event.target.value as LessonOpenMode)
                          }
                        >
                          <option value="practice">
                            Practice — solution hidden
                          </option>
                          <option value="guided">
                            Guided — progressive hints
                          </option>
                          {imported.lesson.allowSolutionView && (
                            <option value="solution">Solution</option>
                          )}
                          <option value="teacher">Teacher</option>
                        </select>
                      </label>
                    )}
                    <div className="portable-import-actions">
                      <button
                        type="button"
                        className="portable-primary"
                        onClick={() => void applyImport("replace")}
                      >
                        {imported.workspace.type === adapter.workspaceType
                          ? "Replace Current Workspace"
                          : `Open ${imported.workspace.typeLabel}`}
                      </button>
                      {adapter.canMerge &&
                        imported.workspace.type === adapter.workspaceType && (
                          <button
                            type="button"
                            onClick={() => void applyImport("merge")}
                          >
                            Merge into Current Workspace
                          </button>
                        )}
                      <button
                        type="button"
                        onClick={() => void applyImport("new")}
                      >
                        Open in a New Tab
                      </button>
                      {dirty && (
                        <button
                          type="button"
                          onClick={() => void exportWorkspace()}
                        >
                          Export Current First
                        </button>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}
            {view === "lesson" && (
              <div className="portable-lesson-panel">
                <div className="portable-settings-grid">
                  <label>
                    Title
                    <input
                      value={lessonForm.title}
                      onChange={(event) =>
                        setLessonForm({
                          ...lessonForm,
                          title: event.target.value,
                        })
                      }
                    />
                  </label>
                  <label>
                    Difficulty
                    <select
                      value={lessonForm.difficulty}
                      onChange={(event) =>
                        setLessonForm({
                          ...lessonForm,
                          difficulty: event.target.value,
                        })
                      }
                    >
                      <option>beginner</option>
                      <option>intermediate</option>
                      <option>advanced</option>
                      <option>mixed</option>
                    </select>
                  </label>
                  <label>
                    Grade/level
                    <input
                      value={lessonForm.grade}
                      onChange={(event) =>
                        setLessonForm({
                          ...lessonForm,
                          grade: event.target.value,
                        })
                      }
                      placeholder="8, 9"
                    />
                  </label>
                  <label>
                    Topic
                    <input
                      value={lessonForm.topic}
                      onChange={(event) =>
                        setLessonForm({
                          ...lessonForm,
                          topic: event.target.value,
                        })
                      }
                    />
                  </label>
                </div>
                <label>
                  Short description
                  <textarea
                    value={lessonForm.description}
                    onChange={(event) =>
                      setLessonForm({
                        ...lessonForm,
                        description: event.target.value,
                      })
                    }
                  />
                </label>
                <label>
                  Instructions — one per line
                  <textarea
                    value={lessonForm.instructions}
                    onChange={(event) =>
                      setLessonForm({
                        ...lessonForm,
                        instructions: event.target.value,
                      })
                    }
                  />
                </label>
                <label>
                  Hints — one per line
                  <textarea
                    value={lessonForm.hints}
                    onChange={(event) =>
                      setLessonForm({
                        ...lessonForm,
                        hints: event.target.value,
                      })
                    }
                  />
                </label>
                <label>
                  Solution steps — one per line
                  <textarea
                    value={lessonForm.steps}
                    onChange={(event) =>
                      setLessonForm({
                        ...lessonForm,
                        steps: event.target.value,
                      })
                    }
                  />
                </label>
                <label>
                  Expected result
                  <textarea
                    value={lessonForm.expected}
                    onChange={(event) =>
                      setLessonForm({
                        ...lessonForm,
                        expected: event.target.value,
                      })
                    }
                  />
                </label>
                <label>
                  Teacher notes
                  <textarea
                    value={lessonForm.teacherNotes}
                    onChange={(event) =>
                      setLessonForm({
                        ...lessonForm,
                        teacherNotes: event.target.value,
                      })
                    }
                  />
                </label>
                <label>
                  Tags
                  <input
                    value={lessonForm.tags}
                    onChange={(event) =>
                      setLessonForm({ ...lessonForm, tags: event.target.value })
                    }
                    placeholder="geometry, construction"
                  />
                </label>
                <div className="portable-scene-captures">
                  <button
                    type="button"
                    onClick={() => {
                      initialScene.current = adapter.serializeScene();
                      setStatus("Starting scene captured.");
                    }}
                  >
                    <Check />
                    Capture starting scene
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      solutionScene.current = adapter.serializeScene();
                      setStatus("Solution scene captured.");
                    }}
                  >
                    <Check />
                    Capture solution scene
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      checkpointScenes.current = [
                        ...checkpointScenes.current,
                        {
                          id: crypto.randomUUID(),
                          title: `Checkpoint ${checkpointScenes.current.length + 1}`,
                          instructions: "",
                          scene: adapter.serializeScene(),
                          validationRules: [],
                        },
                      ];
                      setStatus(
                        `Checkpoint ${checkpointScenes.current.length} captured.`,
                      );
                    }}
                  >
                    <Check />
                    Add checkpoint
                  </button>
                </div>
                <button
                  type="button"
                  className="portable-primary"
                  onClick={() => void exportLesson()}
                  disabled={busy}
                >
                  Export Lesson File
                </button>
              </div>
            )}
            <footer
              className={
                status.includes("could") ||
                status.includes("not") ||
                status.includes("failed")
                  ? "is-error"
                  : ""
              }
              aria-live="polite"
            >
              {busy && <span className="portable-spinner" />}
              {status}
              {dirty && !busy && <small>Unsaved portable-file changes</small>}
              <small>
                {summary.objectCount} objects · {summary.expressionCount}{" "}
                expressions
              </small>
            </footer>
          </section>
        </div>,
        )}
    </div>
  );
}


function Action({
  icon,
  title,
  note,
  onClick,
}: {
  icon: React.ReactNode;
  title: string;
  note: string;
  onClick: () => void;
}) {
  return (
    <button type="button" onClick={onClick}>
      {icon}
      <span>
        <strong>{title}</strong>
        <small>{note}</small>
      </span>
    </button>
  );
}
function safeSnapshot(adapter: PortableWorkspaceAdapter) {
  try {
    return JSON.stringify(adapter.serializeScene());
  } catch {
    return "";
  }
}
function splitComma(value: string) {
  return value
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}
function splitLines(value: string) {
  return value
    .split(/\r?\n/)
    .map((item) => item.trim())
    .filter(Boolean);
}
function capital(value: string) {
  return value.charAt(0).toUpperCase() + value.slice(1);
}
function message(error: unknown, fallback: string) {
  return error instanceof Error && error.message ? error.message : fallback;
}

