export function buildContextDataset():ContextRow[]{
 const actual=contextPages.filter(p=>p.definition&&p.formula).slice(0,32),rows:ContextRow[]=[];
 const contexts=[...meanings.slice(0,3).map(k=>({...k,route:'registered:'+k.id})),...actual];
 for(const [intent,templates] of Object.entries(phrases) as [ContextIntent,string[]][])for(const [index,question] of templates.entries())for(const [pageIndex,page] of contexts.entries()){
  const split=index<8?'train':index<10?'calibration':'test';
  if(split==='test'&&pageIndex>=11)continue;
  let meaning:ContextMeaning=intent==='unrelated'?'unknown':intent==='previous'?'previous':intent==='selected'?'selected':'active';
  rows.push({question,pageVocabulary:page.vocabulary,previousVocabulary:meanings[0].vocabulary,selectedTypes:intent==='selected'?['circle']:pageIndex%4===0?['rectangle']:[],simulation:page.id==='pigeonhole'?{n:10,k:3}:undefined,hasPrevious:['previous','followup','why','hint'].includes(intent)||pageIndex%2===0,intent,meaning,group:`${intent}:syntax-${index}`,split,pageId:page.id});
 }
 const termTemplates=['What is a {term}','Define {term}','Explain {term}','Tell me about {term}','What does {term} mean','Describe {term}','Give a definition of {term}','Help me understand {term}','Could you define {term}','Tell me the meaning of {term}','What exactly is meant by {term}','How would you describe {term} to someone','What kind of thing is {term}'];
 for(const [index,template] of termTemplates.entries())for(const context of [meanings[0],meanings[1],meanings[2],{id:'general',vocabulary:'',title:'General conversation'}])for(const term of ['tree','pigeon holes']){
  const meaning:ContextMeaning=term==='tree'?context.id==='graph-tree'?'graph-tree':context.id==='data-tree'?'data-tree':context.id==='general'?'real-tree':'unknown':context.id==='pigeonhole'?'pigeonhole':context.id==='general'?'ordinary-pigeonhole':'unknown';
  rows.push({question:template.replace('{term}',term),pageVocabulary:context.vocabulary,intent:'define',meaning,group:`term:syntax-${index}`,split:index<8?'train':index<10?'calibration':'test',pageId:context.id});
 }
 const overrides=['I mean real trees not mathematical trees','Tell me about biological trees','Explain living trees rather than graphs','I am asking about plants called trees','Define a real tree','What are real trees in nature','I want the biological meaning of tree','Describe a tree as a living plant','Explain trees as plants not graphs','Define biological tree','I am not asking about the mathematical tree tell me about real trees','By tree I mean an actual plant with leaves','Ignore the mathematical meaning explain real trees'];
 overrides.forEach((question,index)=>contexts.slice(0,12).forEach(page=>rows.push({question,pageVocabulary:page.vocabulary,intent:'define',meaning:'real-tree',group:`override:syntax-${index}`,split:index<8?'train':index<10?'calibration':'test',pageId:page.id})));
 const demonstrations=['Show {n} objects in {k} boxes','Demonstrate {n} objects in {k} containers','Visualize {n} items in {k} boxes','Show me {n} balls in {k} boxes','Put {n} objects into {k} boxes','Distribute {n} objects among {k} boxes','Show an example with {n} objects in {k} boxes','Can you demonstrate {n} objects in {k} boxes','Illustrate {n} objects distributed in {k} containers','Show how {n} items fit in {k} boxes','Use the simulation to show {n} objects in {k} boxes','Let me see {n} objects placed into {k} containers','Make a visual arrangement of {n} objects in {k} boxes'];
 demonstrations.forEach((template,index)=>{for(let n=4;n<=12;n++)rows.push({question:template.replace('{n}',String(n)).replace('{k}',String(n%3+2)),pageVocabulary:meanings[0].vocabulary,simulation:{n:5,k:4},intent:'demonstrate',meaning:'pigeonhole',group:`simulation:syntax-${index}`,split:index<8?'train':index<10?'calibration':'test',pageId:'pigeonhole'});});
 return rows;
}

