}) {
  const regexResult = useMemo(() => {
    try {
      return { machine: regexToNfa(regexPattern), error: "" };
    } catch (error) {
      return {
        machine: null,
        error:
          error instanceof Error ? error.message : "Invalid regular expression",
      };
