  const pda = useMemo(
    () => simulatePda(balancedParenthesesPda, pdaInput),
    [pdaInput],
  );
  return (
    <SectionCard
      title="Regex and Pushdown Automata"
      description="Thompson regex construction plus stack-based PDA recognition."
    >
