function CircleCanvas({
  centre,
  point,
  radius,
  visibility,
  locked,
  drag,
  onDrag,
  onUpdate,
}: {
  centre: Point;
  point: Point;
  radius: number;
  visibility: Visibility;
  locked: { centre: boolean; point: boolean };
  drag: Drag;
  onDrag: (drag: Drag) => void;
  onUpdate: (kind: "centre" | "point", point: Point) => void;
}) {
  const domain = (event: ReactPointerEvent<SVGSVGElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    return {
      x: -7 + ((event.clientX - box.left) / box.width) * 14,
      y: 7 - ((event.clientY - box.top) / box.height) * 14,
    };
  };
  const screen = (p: Point) => ({ x: 350 + p.x * 42, y: 294 - p.y * 42 });
  const c = screen(centre),
    p = screen(point);
  return (
    <svg
      role="img"
      aria-label="Interactive circle with draggable centre C and circumference point P"
      className="h-[410px] w-full touch-none"
      viewBox="0 0 700 588"
      onPointerMove={(event) => {
        if (drag) onUpdate(drag, domain(event));
      }}
      onPointerUp={() => onDrag(null)}
      onPointerCancel={() => onDrag(null)}
    >
      <defs>
        <pattern
          id="circle-point-grid"
          width="42"
          height="42"
          patternUnits="userSpaceOnUse"
        >
          <path d="M42 0H0V42" fill="none" stroke="#dbe7f2" />
        </pattern>
      </defs>
      {visibility.grid && (
        <rect width="700" height="588" fill="url(#circle-point-grid)" />
      )}
      {visibility.axes && (
        <>
          <line x1="0" y1="294" x2="700" y2="294" stroke="#475569" />
          <line x1="350" y1="0" x2="350" y2="588" stroke="#475569" />
        </>
      )}
      {visibility.circle && (
        <circle
          data-testid="centre-point-construction-circle"
          data-radius={radius.toFixed(4)}
          cx={c.x}
          cy={c.y}
          r={radius * 42}
          fill="none"
          stroke="#7c3aed"
          strokeWidth="2.5"
        />
      )}
      {visibility.radius && (
        <>
          <line
            x1={c.x}
            y1={c.y}
            x2={p.x}
            y2={p.y}
            stroke="#1398c3"
            strokeWidth="2"
            strokeDasharray="7 5"
          />
          <text
            x={(c.x + p.x) / 2}
            y={(c.y + p.y) / 2 - 10}
            fill="#0369a1"
            fontSize="13"
            fontStyle="italic"
          >
            r
          </text>
        </>
      )}
      {visibility.centre && (
        <g>
          <circle
            data-testid="circle-centre-handle"
            cx={c.x}
            cy={c.y}
            r="8"
            fill="#1683e6"
            className={locked.centre ? "cursor-not-allowed" : "cursor-move"}
            onPointerDown={(event) => {
              if (!locked.centre) {
                event.currentTarget.ownerSVGElement?.setPointerCapture(
                  event.pointerId,
                );
                onDrag("centre");
              }
            }}
          />
          <text x={c.x + 20} y={c.y + 12} fill="#1683e6" fontSize="15">
            C ({format(centre.x)}, {format(centre.y)})
          </text>
        </g>
      )}
      {visibility.point && (
        <g>
          <circle
            data-testid="circle-point-handle"
            cx={p.x}
            cy={p.y}
            r="8"
            fill="#7c3aed"
            className={locked.point ? "cursor-not-allowed" : "cursor-move"}
            onPointerDown={(event) => {
              if (!locked.point) {
                event.currentTarget.ownerSVGElement?.setPointerCapture(
                  event.pointerId,
                );
                onDrag("point");
              }
            }}
          />
          <text x={p.x + 16} y={p.y - 12} fill="#7c3aed" fontSize="15">
            P ({format(point.x)}, {format(point.y)})
          </text>
        </g>
      )}
    </svg>
  );
}
function ObjectRow({
