import {
  ArrowLeft,
  ArrowRight,
  Check,
  Compass,
  Move,
  MousePointer2,
  RotateCcw,
  Share2,
} from "lucide-react";
import {
  useEffect,
  useMemo,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import type { LessonAdapterProps } from "../types";
import { LessonTopicStudyBoard } from "../components/LessonTopicStudyBoard";

type Point = { x: number; y: number };
type Tool = "select" | "move" | "compass";
type Drag = "centre" | "radius" | null;
const initialCentre = { x: 2, y: 1 };
const initialRadius = 3.61;

export default function CircleCentreRadiusTargetLesson219({
  resetToken,
  onInteraction,
}: LessonAdapterProps) {
  const [centre, setCentre] = useState<Point>(initialCentre);
  const [radius, setRadius] = useState(initialRadius);
  const [angle, setAngle] = useState(45);
  const [tool, setTool] = useState<Tool>("select");
  const [drag, setDrag] = useState<Drag>(null);
  const [units, setUnits] = useState("units");
  const [feedback, setFeedback] = useState<"idle" | "correct" | "incorrect">(
    "idle",
  );
  const point = useMemo(
    () => ({
      x: centre.x + radius * Math.cos((angle * Math.PI) / 180),
      y: centre.y + radius * Math.sin((angle * Math.PI) / 180),
    }),
    [centre, radius, angle],
  );
  const reset = () => {
    setCentre(initialCentre);
    setRadius(initialRadius);
    setAngle(45);
    setTool("select");
    setUnits("units");
    setFeedback("idle");
    onInteraction();
  };
  useEffect(() => {
    setCentre(initialCentre);
    setRadius(initialRadius);
    setAngle(45);
    setTool("select");
    setUnits("units");
    setFeedback("idle");
  }, [resetToken]);
  const updateCentre = (next: Point) => {
    setCentre({ x: clamp(next.x, -6, 6), y: clamp(next.y, -5, 6) });
    setFeedback("idle");
    onInteraction();
  };
  const updateRadius = (next: number) => {
    setRadius(clamp(next, 0.1, 10));
    setFeedback("idle");
    onInteraction();
  };
  const check = () => {
    setFeedback(
      Math.hypot(centre.x + 3, centre.y - 2) < 0.16 &&
        Math.abs(radius - 4) < 0.08
        ? "correct"
        : "incorrect",
    );
    onInteraction();
  };

  return (
    <section
      className="space-y-3"
      style={{ marginTop: -27 }}
      data-testid="dynamic-geometry-mockup-0276"
      data-dedicated-lesson="219"
      data-object-model="circle-centre-fixed-radius"
      data-direct-interaction="true"
      aria-label="Circle Centre and Radius dedicated interactive geometry model"
    >
      <span className="sr-only">Live Verification. Check Construction.</span>
      <header className="px-1 py-2">
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className="text-[8px] font-black uppercase text-slate-600">
              Dynamic Geometry Constructions
            </p>
            <h1 className="mt-2 text-[27px] font-black leading-8 text-slate-950">
              Circle Centre and Radius
            </h1>
            <p className="mt-1 text-[9px] text-slate-600">
              Construct a circle by choosing its centre and radius. Observe how
              every point on the circle is the same distance from the centre.
            </p>
          </div>
          <div className="mt-10 flex gap-2">
            <button type="button" className="target-geometry-action">
              English (English)
            </button>
            <button
              type="button"
              className="target-geometry-action"
              onClick={reset}
            >
              <RotateCcw />
              Reset
            </button>
            <button
              type="button"
              className="target-geometry-action"
              onClick={() => {
                void navigator.clipboard?.writeText(location.href);
                onInteraction();
              }}
            >
              <Share2 />
              Share
            </button>
          </div>
        </div>
        <div className="mt-4 flex flex-wrap gap-2 text-[8px] font-bold">
          <span className="target-geometry-chip">Foundation-Advanced</span>
          <span className="target-geometry-chip">Construction Studio</span>
          <span className="target-geometry-chip">Geometry Tools</span>
          <span className="target-geometry-chip">6-10 min</span>
        </div>
      </header>
      <nav className="grid grid-cols-5 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
        {[
          ["Observe", "See it"],
          ["Manipulate", "Change it"],
          ["Pattern", "Notice it"],
          ["Rule", "Understand it"],
          ["Practice", "Try it"],
        ].map(([label, sub], index) => (
          <button
            type="button"
            key={label}
            className={`h-12 text-[9px] font-black ${index === 0 ? "bg-gradient-to-r from-cyan-500 to-blue-700 text-white" : "text-slate-700"}`}
            onClick={() => {
              document
                .getElementById(
                  index === 4 ? "radius-practice" : `radius-${index}`,
                )
                ?.scrollIntoView({ behavior: "smooth", block: "center" });
              onInteraction();
            }}
          >
            <span className="mr-1 rounded-full bg-white/25 px-1.5 py-1">
              {index + 1}
            </span>
            {label}
            <small className="block text-[7px] font-normal">{sub}</small>
          </button>
        ))}
      </nav>
      <nav className="flex gap-8 border-b border-slate-200 px-3 text-[9px] text-slate-600">
        {[
          "Construction",
          "Equation",
          "Properties",
          "Worked Example",
          "Practice",
        ].map((label, index) => (
          <button
            type="button"
            key={label}
            className={`pb-2 ${index === 0 ? "border-b-2 border-blue-600 font-black text-blue-700" : ""}`}
            onClick={() => {
              document
                .getElementById(
                  index === 0
                    ? "radius-0"
                    : index === 3
                      ? "radius-worked"
                      : index === 4
                        ? "radius-practice"
                        : "radius-2",
                )
                ?.scrollIntoView({ behavior: "smooth", block: "center" });
              onInteraction();
            }}
          >
            {label}
          </button>
        ))}
      </nav>

      <section id="radius-0" className="grid gap-3 md:grid-cols-[1.55fr_1fr]">
        <div className="rounded-xl border border-slate-200 bg-white p-3 shadow-sm">
          <h2 className="text-[12px] font-black text-blue-800">
            Interactive Construction
          </h2>
          <p className="mt-1 text-[8px] text-slate-600">
            Drag the centre or change the radius to see how the circle changes.
          </p>
          <div className="relative mt-3 rounded-lg border border-slate-200">
            <div className="absolute right-2 top-2 z-10 flex gap-2">
              <Tool
                active={tool === "select"}
                label="Select"
                icon={<MousePointer2 />}
                onClick={() => setTool("select")}
              />
              <Tool
                active={tool === "move"}
                label="Move circle"
                icon={<Move />}
                onClick={() => setTool("move")}
              />
              <Tool
                active={tool === "compass"}
                label="Adjust radius with compass"
                icon={<Compass />}
                onClick={() => setTool("compass")}
              />
            </div>
            <RadiusCanvas
              centre={centre}
              radius={radius}
              point={point}
              tool={tool}
              drag={drag}
              onDrag={setDrag}
              onCentre={updateCentre}
              onRadius={(value, newAngle) => {
                updateRadius(value);
                setAngle(newAngle);
              }}
            />
          </div>
        </div>
        <aside className="rounded-xl border border-slate-200 bg-white shadow-sm">
          <div className="p-4">
            <h2 className="text-[12px] font-black text-blue-800">Controls</h2>
            <p className="mt-5 text-[9px] font-black">Centre C (x, y)</p>
            <Stepper
              label="Centre x"
              value={centre.x}
              onChange={(x) => updateCentre({ ...centre, x })}
            />
            <Stepper
              label="Centre y"
              value={centre.y}
              onChange={(y) => updateCentre({ ...centre, y })}
            />
            <p className="mt-5 text-[9px] font-black">Radius r</p>
            <div className="mt-3 flex items-center gap-2">
              <input
                aria-label="Circle radius"
                className="min-w-0 flex-1 accent-blue-600"
                type="range"
                min="0.1"
                max="10"
                step="0.01"
                value={radius}
                onChange={(event) => updateRadius(Number(event.target.value))}
              />
              <input
                aria-label="Radius exact value"
                className="w-14 rounded-md border px-2 py-2 text-right text-[10px] font-bold"
                type="number"
                min="0.1"
                max="10"
                step="0.01"
                value={Number(radius.toFixed(2))}
                onChange={(event) => updateRadius(Number(event.target.value))}
              />
            </div>
            <div className="mt-3 grid grid-cols-[36px_1fr_36px] gap-2">
              <button
                type="button"
                className="target-radius-step"
                aria-label="Decrease radius"
                onClick={() => updateRadius(radius - 0.1)}
              >
                -
              </button>
              <select
                aria-label="Radius units"
                className="rounded-md border px-2 text-[9px]"
                value={units}
                onChange={(event) => {
                  setUnits(event.target.value);
                  onInteraction();
                }}
              >
                <option>units</option>
                <option>cm</option>
                <option>mm</option>
              </select>
              <button
                type="button"
                className="target-radius-step"
                aria-label="Increase radius"
                onClick={() => updateRadius(radius + 0.1)}
              >
                +
              </button>
            </div>
            <div className="mt-2 flex justify-between text-[7px] text-slate-500">
              <span>0.1</span>
              <span>10</span>
            </div>
          </div>
          <div className="border-t p-4">
            <p className="text-[9px] font-black">Live measurement</p>
            <p
              data-testid="fixed-radius-measurement"
              className="mt-4 rounded-lg border border-purple-400 bg-purple-50 px-4 py-5 text-center font-serif text-[16px] text-purple-700"
            >
              CP = r = {radius.toFixed(2)} {units}
            </p>
          </div>
        </aside>
      </section>

      <section
        id="radius-2"
        className="grid gap-3 md:grid-cols-[1.55fr_1fr]"
        style={{ marginTop: 10 }}
      >
        <article className="target-radius-card">
          <h2>Observe</h2>
          <p className="text-slate-500">What do you notice?</p>
          <div className="grid grid-cols-[1fr_135px]">
            <div>
              {[
                "The distance from the centre to any point on the circle is the same.",
                "Changing the centre moves the whole circle.",
                "Changing the radius makes the circle bigger or smaller.",
              ].map((text) => (
                <p key={text} className="mt-4 flex gap-2">
                  <Check className="h-4 w-4 shrink-0 rounded-full border border-emerald-400 p-0.5 text-emerald-600" />
                  {text}
                </p>
              ))}
            </div>
            <CompassDiagram />
          </div>
        </article>
        <article className="target-radius-card">
          <h2>Equation of the Circle</h2>
          <p>A circle with centre (h, k) and radius r has equation:</p>
          <p className="target-radius-formula">(x - h)^2 + (y - k)^2 = r^2</p>
          <p>For this construction:</p>
          <p className="mt-3 text-center font-serif text-[13px] italic">
            (x - {signed(centre.x)})^2 + (y - {signed(centre.y)})^2 = (
            {radius.toFixed(2)})^2
          </p>
        </article>
      </section>

      <section
        id="radius-worked"
        className="rounded-xl border border-slate-200 bg-white p-3 shadow-sm"
        style={{ marginTop: 10 }}
      >
        <h2 className="text-[11px] font-black text-blue-800">
          Worked Example: Construct the Circle
        </h2>
        <div className="mt-3 grid grid-cols-4 gap-3">
          <WorkStep
            number="1"
            title="Choose centre C"
            text="Place the centre at C (2, 1)."
            kind="point"
          />
          <WorkStep
            number="2"
            title="Set radius r"
            text="Set the radius to 3.61 units."
            kind="radius"
          />
          <WorkStep
            number="3"
            title="Draw the circle"
            text="The circle is drawn with centre C and radius r."
            kind="circle"
          />
          <WorkStep
            number="Result"
            title=""
            text="Every point P on the circle satisfies CP = r."
            kind="result"
          />
        </div>
      </section>
      <section
        id="radius-practice"
        className="grid h-[166px] gap-3 rounded-xl border border-slate-200 bg-white p-3 shadow-sm md:grid-cols-[1.3fr_1fr]"
        style={{ marginTop: 10 }}
      >
        <div>
          <h2 className="text-[11px] font-black text-blue-800">Try It</h2>
          <p className="mt-1 text-[8px]">
            Follow the instructions and check your result.
          </p>
          <div className="mt-4 grid grid-cols-[1fr_90px] gap-5">
            <div>
              <h3 className="font-black text-blue-700">Task</h3>
              <p className="mt-2 text-[8px]">
                Construct a circle with centre C(-3, 2) and radius r = 4 units.
                Drag the centre or adjust the radius to match the target values.
              </p>
              <div className="mt-3 flex gap-2">
                <button
                  type="button"
                  className="rounded-md bg-blue-700 px-4 py-2 text-[8px] font-black text-white"
                  onClick={check}
                >
                  <Check className="mr-1 inline h-3 w-3" />
                  Check Answer
                </button>
                <button
                  type="button"
                  className="target-geometry-action"
                  onClick={reset}
                >
                  <RotateCcw />
                  Reset
                </button>
              </div>
              {feedback !== "idle" && (
                <p
                  role="status"
                  className={`mt-2 font-black ${feedback === "correct" ? "text-emerald-700" : "text-rose-700"}`}
                >
                  {feedback === "correct"
                    ? "Correct centre and radius construction."
                    : "Set C to (-3, 2) and r to 4."}
                </p>
              )}
            </div>
            <div className="rounded-md border border-blue-200 bg-blue-50 p-3 text-[9px]">
              <b className="text-blue-700">Target</b>
              <p className="mt-2">C (-3, 2)</p>
              <p>r = 4 units</p>
            </div>
          </div>
        </div>
        <TargetPreview />
      </section>
      <nav
        className="grid grid-cols-2 gap-3"
        style={{ marginTop: 14 }}
        aria-label="Adjacent lessons"
      >
        <a
          className="target-radius-nav"
          href="/lessons/geometry/218-circle-centre-and-point"
        >
          <ArrowLeft />
          <span>
            <b>Previous</b>Circle: Centre and Point
          </span>
        </a>
        <a
          className="target-radius-nav justify-end text-right"
          href="/lessons/geometry/220-circle-through-three-points"
        >
          <span>
            <b>Next</b>Circle Through Three Points
          </span>
          <ArrowRight />
        </a>
      </nav>
      <LessonTopicStudyBoard lessonId={219} alwaysVisible onInteraction={onInteraction} />

    </section>
  );
}

function RadiusCanvas({
  centre,
  radius,
  point,
  tool,
  drag,
  onDrag,
  onCentre,
  onRadius,
}: {
  centre: Point;
  radius: number;
  point: Point;
  tool: Tool;
  drag: Drag;
  onDrag: (drag: Drag) => void;
  onCentre: (point: Point) => void;
  onRadius: (radius: number, angle: number) => void;
}) {
  const domain = (event: ReactPointerEvent<SVGSVGElement>) => {
    const matrix = event.currentTarget.getScreenCTM();
    if (!matrix) return centre;
    const local = new DOMPoint(event.clientX, event.clientY).matrixTransform(
      matrix.inverse(),
    );
    return { x: (local.x - 350) / 40, y: (313 - local.y) / 40 };
  };
  const screen = (p: Point) => ({ x: 350 + p.x * 40, y: 313 - p.y * 40 }),
    c = screen(centre),
    p = screen(point);
  return (
    <svg
      role="img"
      aria-label="Interactive fixed-radius circle with draggable centre and compass handle"
      className="h-[360px] w-full touch-none"
      viewBox="0 0 700 560"
      onPointerMove={(event) => {
        if (!drag) return;
        const next = domain(event);
        if (drag === "centre") onCentre(next);
        else
          onRadius(
            Math.hypot(next.x - centre.x, next.y - centre.y),
            (Math.atan2(next.y - centre.y, next.x - centre.x) * 180) / Math.PI,
          );
      }}
      onPointerUp={() => onDrag(null)}
      onPointerCancel={() => onDrag(null)}
    >
      <defs>
        <pattern
          id="fixed-radius-grid"
          width="40"
          height="40"
          patternUnits="userSpaceOnUse"
        >
          <path d="M40 0H0V40" fill="none" stroke="#dfe9f3" />
        </pattern>
      </defs>
      <rect width="700" height="560" fill="url(#fixed-radius-grid)" />
      <line x1="0" y1="313" x2="700" y2="313" stroke="#475569" />
      <line x1="350" y1="0" x2="350" y2="560" stroke="#475569" />
      <circle
        data-testid="fixed-radius-circle"
        data-radius={radius.toFixed(4)}
        cx={c.x}
        cy={c.y}
        r={radius * 40}
        fill="#eff8ff"
        fillOpacity=".4"
        stroke="#0d97ee"
        strokeWidth="2.5"
      />
      <line
        x1={c.x}
        y1={c.y}
        x2={p.x}
        y2={p.y}
        stroke="#7c3aed"
        strokeWidth="2"
      />
      <circle
        data-testid="fixed-radius-centre"
        cx={c.x}
        cy={c.y}
        r="7"
        fill="#1675d1"
        className="cursor-move"
        onPointerDown={(event) => {
          event.currentTarget.ownerSVGElement?.setPointerCapture(
            event.pointerId,
          );
          onDrag("centre");
        }}
      />
      <circle
        data-testid="fixed-radius-handle"
        cx={p.x}
        cy={p.y}
        r="7"
        fill="#2563eb"
        className="cursor-move"
        onPointerDown={(event) => {
          event.currentTarget.ownerSVGElement?.setPointerCapture(
            event.pointerId,
          );
          onDrag("radius");
        }}
      />
      <text x={c.x + 15} y={c.y + 22} fill="#175aa7" fontSize="14">
        C ({format(centre.x)}, {format(centre.y)})
      </text>
      <text x={p.x + 12} y={p.y - 12} fill="#1e3a8a" fontSize="14">
        P ({format(point.x)}, {format(point.y)})
      </text>
      <text
        x={(c.x + p.x) / 2}
        y={(c.y + p.y) / 2 - 10}
        fill="#7c3aed"
        fontSize="14"
      >
        r = {radius.toFixed(2)}
      </text>
    </svg>
  );
}
function Stepper({
  label,
  value,
  onChange,
}: {
  label: string;
  value: number;
  onChange: (value: number) => void;
}) {
  return (
    <div className="mt-2 grid grid-cols-[36px_1fr_36px]">
      <button
        type="button"
        className="target-radius-step rounded-r-none"
        aria-label={`Decrease ${label}`}
        onClick={() => onChange(value - 1)}
      >
        -
      </button>
      <input
        aria-label={label}
        type="number"
        step="1"
        className="min-w-0 border-y px-3 text-center text-[10px] font-bold"
        value={Number(value.toFixed(1))}
        onChange={(event) => onChange(Number(event.target.value))}
      />
      <button
        type="button"
        className="target-radius-step rounded-l-none"
        aria-label={`Increase ${label}`}
        onClick={() => onChange(value + 1)}
      >
        +
      </button>
    </div>
  );
}
