function GivenLengthGraph({
  start,
  end,
  length,
  grid,
  onPointer,
}: {
  start: { x: number; y: number };
  end: { x: number; y: number };
  length: number;
  grid: boolean;
  onPointer: (event: PointerEvent<SVGSVGElement>) => void;
}) {
  const sx = (x: number) => 310 + x * 30,
    sy = (y: number) => 260 - y * 30;
  return (
    <svg
      viewBox="0 0 620 520"
      className="h-[480px] w-full touch-none"
      role="img"
      aria-label="Fixed-length segment from A to constructed point B with draggable direction handle"
      onPointerDown={onPointer}
      onPointerMove={onPointer}
    >
      {grid
        ? Array.from({ length: 17 }, (_, i) => (
            <g key={i}>
              <line
                x1={40 + i * 34}
                x2={40 + i * 34}
                y1="20"
                y2="500"
                stroke="#dbe3ef"
                strokeDasharray="3 3"
              />
              <line
                y1={20 + i * 30}
                y2={20 + i * 30}
                x1="20"
                x2="600"
                stroke="#dbe3ef"
                strokeDasharray="3 3"
              />
            </g>
          ))
        : null}
      <line x1="20" x2="605" y1="260" y2="260" stroke="#64748b" />
      <line x1="310" x2="310" y1="15" y2="505" stroke="#64748b" />
      <line
        x1={sx(start.x)}
        y1={sy(start.y)}
        x2={sx(end.x)}
        y2={sy(end.y)}
        stroke="#7c3aed"
        strokeWidth="4"
      />
      <line
        x1={sx(start.x)}
        y1={sy(start.y)}
        x2={sx(end.x) + (sx(end.x) - sx(start.x)) * 0.55}
        y2={sy(end.y) + (sy(end.y) - sy(start.y)) * 0.55}
        stroke="#334155"
        strokeDasharray="6 5"
      />
      <circle cx={sx(start.x)} cy={sy(start.y)} r="7" fill="#2563eb" />
      <circle
        cx={sx(end.x)}
        cy={sy(end.y)}
        r="14"
        fill="white"
        stroke="#2563eb"
        strokeWidth="3"
      />
      <text
        x={sx(start.x) + 10}
        y={sy(start.y) - 8}
        fill="#2563eb"
        fontSize="14"
        fontWeight="800"
      >
        A ({start.x}, {start.y})
      </text>
      <text
        x={sx(end.x) + 18}
        y={sy(end.y) - 12}
        fill="#7c3aed"
        fontSize="13"
        fontWeight="800"
      >
        B
      </text>
      <text
        x={(sx(start.x) + sx(end.x)) / 2}
        y={(sy(start.y) + sy(end.y)) / 2 - 10}
        fill="#7c3aed"
        fontSize="12"
        fontWeight="800"
      >
        AB = {length}
      </text>
    </svg>
  );
}
function NumberField({
  label,
  value,
  onChange,
}: {
  label: string;
  value: number;
  onChange: (value: string) => void;
}) {
  return (
    <label className="mt-1 block text-[8px] font-bold text-slate-500">
