function FreePointCanvas({
  x,
  y,
  pointSize,
  snap,
  dragging,
  setDragging,
  updateCoordinates,
}: {
  x: number;
  y: number;
  pointSize: number;
  snap: boolean;
  dragging: boolean;
  setDragging: (value: boolean) => void;
  updateCoordinates: (x: number, y: number) => void;
}) {
  const px = 220 + x * 30,
    py = 220 - y * 30;
  return (
    <svg
      viewBox="0 0 440 440"
      className="block h-[442px] w-full bg-white touch-none"
      role="img"
      aria-label="Free point P coordinate plane"
      onPointerMove={(event) => {
        if (!dragging) return;
        const rect = event.currentTarget.getBoundingClientRect();
        const svgX = ((event.clientX - rect.left) * 440) / rect.width;
        const svgY = ((event.clientY - rect.top) * 440) / rect.height;
        updateCoordinates((svgX - 220) / 30, (220 - svgY) / 30);
      }}
      onPointerUp={() => setDragging(false)}
      onPointerLeave={() => setDragging(false)}
    >
      <defs>
        <pattern
          id="free-point-grid"
          width="30"
          height="30"
          patternUnits="userSpaceOnUse"
        >
          <path
            d="M30 0H0V30"
            fill="none"
            stroke="#e5edf8"
            strokeDasharray="3 3"
          />
        </pattern>
      </defs>
      <rect width="440" height="440" fill="url(#free-point-grid)" />
      <line
        x1="18"
        y1="220"
        x2="425"
        y2="220"
        stroke="#172033"
        strokeWidth="1.5"
      />
      <line
        x1="220"
        y1="15"
        x2="220"
        y2="425"
        stroke="#172033"
        strokeWidth="1.5"
      />
      <text x="416" y="210" fontSize="12" fontWeight="800">
        x
      </text>
      <text x="230" y="25" fontSize="12" fontWeight="800">
        y
      </text>
      {[-6, -4, -2, 2, 4, 6].map((t) => (
        <text
          key={`fx${t}`}
          x={220 + t * 30}
          y="238"
          textAnchor="middle"
          fontSize="10"
          fill="#52627e"
        >
          {t}
        </text>
      ))}
      {[-6, -4, -2, 2, 4, 6].map((t) => (
        <text
          key={`fy${t}`}
          x="206"
          y={224 - t * 30}
          textAnchor="end"
          fontSize="10"
          fill="#52627e"
        >
          {t}
        </text>
      ))}
      <g
        className="cursor-grab"
        onPointerDown={(event) => {
          event.currentTarget.setPointerCapture(event.pointerId);
          setDragging(true);
        }}
      >
        <circle
          cx={px}
          cy={py}
          r={pointSize + 2}
          fill="#1478e8"
          stroke="white"
          strokeWidth="2"
        />
        <text
          x={px + 14}
          y={py - 14}
          fontSize="18"
          fontWeight="900"
          fill="#1478e8"
        >
          P
        </text>
      </g>
      <foreignObject x="85" y="375" width="270" height="48">
        <div className="flex h-full items-center justify-center gap-3 rounded-lg border border-[#dbe6fb] bg-white/95 text-xs font-black text-[#152348] shadow">
          <span className="h-3 w-3 rounded-full bg-blue-600" />P{" "}
          <span className="rounded border px-2 py-1">x {x.toFixed(2)}</span>
          <span className="rounded border px-2 py-1">y {y.toFixed(2)}</span>
          <span>{snap ? "▣" : "□"}</span>
        </div>
      </foreignObject>
    </svg>
  );
}

