function IntersectionPointTargetLesson({
  lesson,
  resetToken,
  onInteraction,
}: LessonAdapterProps) {
  const [m1, setM1] = useState(1);
  const [c1, setC1] = useState(2);
  const [m2, setM2] = useState(-1);
  const [c2, setC2] = useState(2);
  const [answerX, setAnswerX] = useState("");
  const [answerY, setAnswerY] = useState("");
  const [answerState, setAnswerState] = useState<
    "idle" | "correct" | "incorrect"
  >("idle");
  const [activeTab, setActiveTab] = useState("1 Observe & Manipulate");
  const [graphTool, setGraphTool] = useState<"select" | "pan">("select");
  const [graphZoom, setGraphZoom] = useState(1);
  const [graphPan, setGraphPan] = useState({ x: 0, y: 0 });
  const [practiceLines, setPracticeLines] = useState<[number, number, number, number]>([2, -1, -3, 5]);
  const [showSteps, setShowSteps] = useState(false);

  useEffect(() => {
    setM1(1);
    setC1(2);
    setM2(-1);
    setC2(2);
    setAnswerX("");
    setAnswerY("");
    setAnswerState("idle");
    setActiveTab("1 Observe & Manipulate");
    setGraphTool("select");
    setGraphZoom(1);
    setGraphPan({ x: 0, y: 0 });
    setPracticeLines([2, -1, -3, 5]);
    setShowSteps(false);
  }, [resetToken]);

  const denominator = m1 - m2;
  const relation =
    Math.abs(denominator) < 0.001
      ? Math.abs(c1 - c2) < 0.001
        ? "Coincident"
        : "Parallel"
      : "Intersecting";
  const ix = relation === "Intersecting" ? (c2 - c1) / denominator : 0;
  const iy = relation === "Intersecting" ? m1 * ix + c1 : 0;
  const setLine = (setter: (value: number) => void, value: number) => {
    setter(value);
    onInteraction();
  };
  const reset = () => {
    setM1(1);
    setC1(2);
    setM2(-1);
    setC2(2);
    onInteraction();
  };
  const [pm1, pc1, pm2, pc2] = practiceLines;
  const practiceX = (pc2 - pc1) / (pm1 - pm2);
  const practiceY = pm1 * practiceX + pc1;
  const activityCount = [m1 !== 1 || c1 !== 2 || m2 !== -1 || c2 !== 2, relation !== "Intersecting", activeTab !== "1 Observe & Manipulate", answerState !== "idle", showSteps].filter(Boolean).length;
  const check = () => {
    setAnswerState(
      Math.abs(Number(answerX) - practiceX) < 0.01 &&
        Math.abs(Number(answerY) - practiceY) < 0.01
        ? "correct"
        : "incorrect",
    );
    onInteraction();
  };

  return (
    <section
      className="-mt-[7px] space-y-[10px]"
      data-testid="dynamic-geometry-mockup-0257"
      data-direct-interaction="true"
      data-dedicated-lesson="200"
      data-object-model="two-line-endpoints-exact-intersection-classification"
      data-relation={relation}
      data-intersection={`${ix.toFixed(2)}:${iy.toFixed(2)}`}
      data-graph-tool={graphTool}
      data-graph-zoom={graphZoom}
      data-answer={answerState}
      data-activities={activityCount}
    >
      <header className="h-[149px] overflow-hidden rounded-xl border border-[#dbe6fb] bg-white p-3 shadow-sm">
        <div className="grid items-center gap-4 lg:grid-cols-[1fr_140px]">
          <div>
            <div className="flex gap-2">
              <span className="rounded-full bg-cyan-50 px-3 py-1 text-[10px] font-black uppercase text-cyan-700">
                Geometry
              </span>
              <span className="rounded-full bg-slate-50 px-3 py-1 text-[10px] font-black uppercase text-[#52627e]">
                Coordinate Geometry
              </span>
            </div>
            <h1 className="mt-3 text-[30px] font-black leading-none text-[#142044]">
              Intersection Point <BookOpen className="ml-2 inline h-4 w-4" />
            </h1>
            <p className="mt-3 text-sm text-[#52627e]">
              Find the point where two lines meet.
            </p>
            <div className="mt-3 flex flex-wrap gap-2 text-[10px] font-black">
              <span className="rounded-lg border border-[#dbe6fb] px-3 py-2">
                Concept
              </span>
              <span className="rounded-lg border border-[#dbe6fb] px-3 py-2">
                Coordinate plane
              </span>
              <span className="rounded-lg border border-[#dbe6fb] px-3 py-2">
                Class 9-10
              </span>
              <span className="rounded-lg border border-[#dbe6fb] px-3 py-2">
                ~6-10 min
              </span>
            </div>
          </div>
          <div className="rounded-xl border border-[#dbe6fb] p-3 text-[10px] text-[#52627e]">
            <p>{activityCount * 20}% complete</p>
            <span className="my-2 block h-2 rounded-full bg-slate-200"><i className="block h-2 rounded-full bg-cyan-600" style={{ width: `${activityCount * 20}%` }} /></span>
            <p>{activityCount} / 5 activities</p>
          </div>
        </div>
      </header>
      <nav className="grid h-[43px] rounded-xl border border-[#dbe6fb] bg-white p-1 shadow-sm sm:grid-cols-5">
        {["1 Observe & Manipulate", "Pattern", "Rule", "Try", "Summary"].map(
          (tab) => (
            <button
              key={tab}
              type="button"
              onClick={() => {
                setActiveTab(tab);
                onInteraction();
              }}
              className={
                activeTab === tab
                  ? "h-[33px] rounded-lg bg-cyan-600 text-[10px] font-black text-white"
                  : "h-[33px] rounded-lg text-[10px] font-black text-[#263452] hover:bg-cyan-50"
              }
            >
              {tab}
            </button>
          ),
        )}
      </nav>

      <section className="grid h-[408px] overflow-hidden rounded-xl border border-[#dbe6fb] bg-white shadow-sm lg:grid-cols-[150px_minmax(0,1fr)_160px]">
        <aside className="border-r border-[#dbe6fb] p-3">
          <IntersectionLineControls
            color="cyan"
            title="Line 1"
            m={m1}
            c={c1}
            setM={(v) => setLine(setM1, v)}
            setC={(v) => setLine(setC1, v)}
          />
          <div className="my-3 h-3 w-3 rounded-full bg-cyan-500 shadow" />
          <IntersectionLineControls
            color="violet"
            title="Line 2"
            m={m2}
            c={c2}
            setM={(v) => setLine(setM2, v)}
            setC={(v) => setLine(setC2, v)}
          />
          <button
            type="button"
            onClick={reset}
            className="mt-3 inline-flex h-8 items-center gap-2 rounded-lg border border-[#dbe6fb] px-3 text-[10px] font-black"
          >
            <RotateCcw className="h-3.5 w-3.5" />
            Reset
          </button>
        </aside>
        <div className="relative">
          <div className="absolute left-3 top-3 z-10 flex gap-1">
            <button
              aria-label="Select line endpoints"
              onClick={() => { setGraphTool("select"); onInteraction(); }}
              className={`grid h-8 w-8 place-items-center rounded-lg ${graphTool === "select" ? "bg-cyan-600 text-white" : "border bg-white"}`}
            >
              <MousePointer2 className="h-4 w-4" />
            </button>
            <button
              aria-label="Pan intersection graph"
              onClick={() => { setGraphTool("pan"); onInteraction(); }}
              className={`grid h-8 w-8 place-items-center rounded-lg ${graphTool === "pan" ? "bg-cyan-600 text-white" : "border bg-white"}`}
            >
              <Hand className="h-4 w-4" />
            </button>
            <button
              aria-label="Zoom intersection graph"
              onClick={() => { setGraphZoom((value) => value >= 1.5 ? 0.75 : Number((value + 0.25).toFixed(2))); onInteraction(); }}
              className="grid h-8 w-8 place-items-center rounded-lg border bg-white"
            >
              <ZoomIn className="h-4 w-4" />
            </button>
          </div>
          <IntersectionGraph
            m1={m1}
            c1={c1}
            m2={m2}
            c2={c2}
            ix={ix}
            iy={iy}
            relation={relation}
            tool={graphTool}
            zoom={graphZoom}
            pan={graphPan}
            onPan={(next) => { setGraphPan(next); onInteraction(); }}
            onLine1={(m, c) => { setM1(m); setC1(c); onInteraction(); }}
            onLine2={(m, c) => { setM2(m); setC2(c); onInteraction(); }}
          />
        </div>
        <aside className="m-3 rounded-xl border border-[#dbe6fb] p-3">
          <h2 className="text-xs font-black text-cyan-700">Observation</h2>
