function MidpointCentreTargetLesson({
  lesson,
  resetToken,
  onInteraction,
}: LessonAdapterProps) {
  const [a, setA] = useState({ x: -4, y: 2 });
  const [b, setB] = useState({ x: 4, y: -1 });
  const [dragging, setDragging] = useState<"A" | "B" | null>(null);
  const [reverse, setReverse] = useState(false);
  const [answerX, setAnswerX] = useState("");
  const [answerY, setAnswerY] = useState("");
  const [answerState, setAnswerState] = useState<
    "idle" | "correct" | "incorrect"
  >("idle");
  const [activeMidpointTab, setActiveMidpointTab] = useState("Observe");
  const [showMidpointSolution, setShowMidpointSolution] = useState(false);
  const [midpointQuestion, setMidpointQuestion] = useState(0);
  const midpointQuestions = [
    { a: { x: -5, y: 4 }, b: { x: 3, y: -2 } },
    { a: { x: -6, y: -2 }, b: { x: 4, y: 6 } },
    { a: { x: 1, y: -5 }, b: { x: 7, y: 3 } },
  ];
  const challenge = midpointQuestions[midpointQuestion];
  const challengeMidpoint = { x: (challenge.a.x + challenge.b.x) / 2, y: (challenge.a.y + challenge.b.y) / 2 };
  const midpoint = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };

  useEffect(() => {
    setA({ x: -4, y: 2 });
    setB({ x: 4, y: -1 });
    setDragging(null);
    setReverse(false);
    setAnswerX("");
    setAnswerY("");
    setAnswerState("idle");
    setActiveMidpointTab("Observe");
    setShowMidpointSolution(false);
    setMidpointQuestion(0);
  }, [resetToken]);
  const update = (point: "A" | "B", axis: "x" | "y", value: number) => {
    (point === "A" ? setA : setB)((old) => ({ ...old, [axis]: value }));
    onInteraction();
  };
  const move = (point: "A" | "B", x: number, y: number) => {
    const next = {
      x: Math.max(-6, Math.min(6, Math.round(x * 2) / 2)),
      y: Math.max(-6, Math.min(6, Math.round(y * 2) / 2)),
    };
    (point === "A" ? setA : setB)(next);
    onInteraction();
  };
  const reset = () => {
    setA({ x: -4, y: 2 });
    setB({ x: 4, y: -1 });
    setReverse(false);
    onInteraction();
  };
  const toggleReverse = () => {
    setReverse((v) => !v);
    setA(b);
    setB(a);
    onInteraction();
  };
  const check = () => {
    setAnswerState(
      Number(answerX) === challengeMidpoint.x && Number(answerY) === challengeMidpoint.y ? "correct" : "incorrect",
    );
    onInteraction();
  };

  return (
    <section
      className="mid201-page space-y-[14px]"
      data-testid="dynamic-geometry-mockup-0258"
      data-direct-interaction="true"
      data-dedicated-lesson="201"
      data-object-model="two-endpoint-derived-midpoint-equal-distance-invariant"
      data-midpoint={`${midpoint.x}:${midpoint.y}`}
      data-tab={activeMidpointTab}
      data-question={midpointQuestion}
      data-answer={answerState}
      data-a={`${a.x}:${a.y}`}
      data-b={`${b.x}:${b.y}`}
      data-reverse={reverse}
      data-solution={showMidpointSolution}
    >
      <header className="h-[150px] overflow-hidden rounded-xl border border-[#dbe6fb] bg-white shadow-sm">
        <div className="flex h-[98px] items-center justify-between px-5">
          <div>
            <h1 className="text-[32px] font-black leading-none text-[#142044]">
              Midpoint or Centre
            </h1>
            <p className="mt-3 text-sm text-[#52627e]">
              Find the midpoint (centre) of a line segment using coordinates.
            </p>
          </div>
          <div className="flex gap-2 text-[10px] font-black">
            <span className="rounded-lg border border-violet-200 px-3 py-2 text-violet-700">
              Coordinate Geometry
            </span>
            <span className="rounded-lg border border-[#dbe6fb] px-3 py-2">
              <Clock3 className="mr-1 inline h-3 w-3" />
              6-10 min
            </span>
            <span className="rounded-lg border border-blue-200 px-3 py-2 text-blue-700">
              Construction &amp; Exploration
            </span>
          </div>
        </div>
        <nav className="grid h-[52px] border-t border-[#dbe6fb] sm:grid-cols-5">
          {[
            [Eye, "Observe"],
            [Hand, "Manipulate"],
            [Lightbulb, "Notice"],
            [BookOpen, "Understand"],
            [Pencil, "Try"],
          ].map(([Icon, label]) => (
            <button
              key={String(label)}
              className={
                activeMidpointTab === label
                  ? "border-b-2 border-blue-500 text-xs font-black text-blue-700"
                  : "text-xs font-black text-[#52627e]"
              }
              onClick={() => {
                const name = String(label);
                const target = name === "Notice" ? "mid201-notice" : name === "Understand" ? "mid201-rule" : name === "Try" ? "mid201-practice" : "mid201-model";
                setActiveMidpointTab(name);
                document.getElementById(target)?.scrollIntoView({ behavior: "smooth", block: "start" });
                onInteraction();
              }}
            >
              <Icon className="mr-2 inline h-4 w-4" />
              {label as string}
            </button>
          ))}
        </nav>
      </header>

      <section id="mid201-model" className="grid h-[510px] overflow-hidden rounded-xl border border-[#dbe6fb] bg-white p-3 shadow-sm lg:grid-cols-[minmax(0,1fr)_275px]">
        <div>
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-base font-black text-[#142044]">
                Interactive Model
              </h2>
              <p className="mt-1 text-xs text-[#52627e]">
                Drag the endpoints A and B.
              </p>
            </div>
            <button
              type="button"
              onClick={reset}
              className="inline-flex h-9 items-center gap-2 rounded-lg border border-[#dbe6fb] px-3 text-xs font-black"
            >
              <RotateCcw className="h-4 w-4" />
              Reset
