          </section>
          <section className="rounded-lg border border-[#dbe6fb] p-3">
            <div className="flex items-center justify-between">
              <p className="text-xs font-black">
                Reverse endpoints challenge{" "}
                <Info className="ml-1 inline h-3.5 w-3.5" />
              </p>
              <button
