              className="h-9 w-20 rounded-lg border text-center"
            />
            ,{" "}
            <input
              aria-label="Midpoint answer y"
              value={answerY}
              onChange={(e) => setAnswerY(e.target.value)}
              className="h-9 w-20 rounded-lg border text-center"
            />{" "}
            ){" "}
            <button
              type="button"
              onClick={check}
              className="h-9 rounded-lg bg-emerald-600 px-5 text-white"
