function renderGeometryShape(tool: GeometryTool, px: number, py: number) {
  if (tool === "point") return null;
  if (
    tool === "line" ||
    tool === "parallel" ||
    tool === "perpendicular" ||
    tool === "fit" ||
    tool === "relation"
  )
    return (
      <>
        <line
          x1="80"
          y1="360"
          x2="720"
          y2="220"
          stroke="#7c3aed"
          strokeWidth="4"
        />
        {tool === "perpendicular" ? (
          <>
            <line
              x1={px}
              y1="70"
              x2={px}
              y2="470"
              stroke="#0ea5e9"
              strokeWidth="3"
              strokeDasharray="8 7"
            />
            <path
              d={`M${px} 300 h30 v-30`}
              fill="none"
              stroke="#7c3aed"
              strokeWidth="3"
            />
            <text x={px - 38} y="290" fontSize="16" fill="#1e3a8a">
              90°
            </text>
          </>
        ) : null}
        {tool === "parallel" ? (
          <line
            x1="80"
            y1="300"
            x2="720"
            y2="160"
            stroke="#0ea5e9"
            strokeWidth="3"
            strokeDasharray="8 7"
          />
        ) : null}
      </>
    );
  if (tool === "segment" || tool === "ray" || tool === "polyline")
    return (
      <>
        <polyline
          points="170,365 330,205 510,285 640,160"
          fill="none"
          stroke="#7c3aed"
          strokeWidth="4"
        />
        <circle cx="170" cy="365" r="8" fill="#2563eb" />
        <circle cx="330" cy="205" r="8" fill="#2563eb" />
        <circle cx="510" cy="285" r="8" fill="#2563eb" />
        {tool === "ray" ? (
          <line
            x1="330"
            y1="205"
            x2="705"
            y2="86"
            stroke="#7c3aed"
            strokeWidth="3"
            strokeDasharray="8 7"
          />
        ) : null}
      </>
    );
  if (tool === "bisector")
    return (
      <>
        <line
          x1="160"
          y1="330"
          x2="620"
          y2="330"
          stroke="#7c3aed"
          strokeWidth="4"
        />
        <line
          x1="390"
          y1="80"
          x2="390"
          y2="480"
          stroke="#0ea5e9"
          strokeWidth="3"
          strokeDasharray="8 7"
        />
        <path
          d="M250 292 C320 250 460 250 530 292"
          fill="none"
          stroke="#f59e0b"
          strokeWidth="3"
        />
      </>
    );
  if (
    tool === "tangent" ||
    tool === "circle" ||
    tool === "arc" ||
    tool === "sector"
  )
    return (
      <>
        <circle
          cx="410"
          cy="260"
          r="128"
          fill={tool === "sector" ? "#cffafe" : "none"}
          stroke="#0ea5c9"
          strokeWidth="4"
        />
        <line
          x1="410"
          y1="260"
          x2="538"
          y2="260"
          stroke="#7c3aed"
          strokeWidth="3"
        />
        {tool === "tangent" ? (
          <line
            x1="538"
            y1="88"
            x2="538"
            y2="432"
            stroke="#7c3aed"
            strokeWidth="4"
          />
        ) : null}
        {tool === "arc" ? (
          <path
            d="M282 260 A128 128 0 0 1 504 162"
            fill="none"
            stroke="#f97316"
            strokeWidth="7"
          />
        ) : null}
        {tool === "sector" ? (
          <line
            x1="410"
            y1="260"
            x2="500"
            y2="168"
            stroke="#7c3aed"
            strokeWidth="3"
          />
        ) : null}
      </>
    );
  if (tool === "triangle" || tool === "polygon")
    return (
      <>
        <polygon
          points={
            tool === "triangle"
              ? "250,360 560,350 410,126"
              : "210,320 300,160 470,150 600,300 425,400"
          }
          fill="#dffafe"
          stroke="#0ea5c9"
          strokeWidth="4"
        />
        <path
          d="M250 360 L410 126 L560 350"
          fill="none"
          stroke="#7c3aed"
          strokeWidth="2"
          strokeDasharray="8 7"
        />
      </>
    );
  if (tool === "conic")
    return (
      <>
        <ellipse
          cx="410"
          cy="260"
          rx="190"
          ry="106"
          fill="none"
          stroke="#0ea5c9"
          strokeWidth="4"
        />
        <path
          d="M255 420 C380 70 485 70 620 420"
          fill="none"
          stroke="#7c3aed"
          strokeWidth="3"
          strokeDasharray="8 7"
        />
        {[
          [250, 260],
          [330, 165],
          [430, 154],
          [528, 202],
          [570, 310],
        ].map(([cx, cy], index) => (
          <circle key={index} cx={cx} cy={cy} r="7" fill="#f97316" />
        ))}
      </>
    );
  if (tool === "measure" || tool === "angle")
    return (
      <>
        <line
          x1="220"
          y1="360"
          x2="610"
          y2="190"
          stroke="#7c3aed"
          strokeWidth="4"
        />
        <path
          d="M220 360 A82 82 0 0 1 296 326"
          fill="none"
          stroke="#f97316"
          strokeWidth="5"
        />
        <text x="365" y="250" fontSize="22" fontWeight="900" fill="#0f766e">
          {tool === "angle" ? "48°" : "5.00 u"}
        </text>
      </>
    );
  return (
    <>
      <path
        d="M160 390 C260 160 392 410 520 164 S660 320 690 180"
        fill="none"
        stroke="#0ea5c9"
        strokeWidth="4"
      />
      <g stroke="#7c3aed" strokeWidth="2" opacity=".45">
        {Array.from({ length: 8 }, (_, i) => (
          <line key={i} x1={140 + i * 70} y1="110" x2={210 + i * 70} y2="430" />
        ))}
      </g>
    </>
  );
}

function UndoHistory({ spec }: { spec: GeometrySpec }) {
  return (
    <div className="mt-4 rounded-xl border border-[#dbe6fb] bg-[#f8fbff] p-3">
      <p className="text-sm font-black text-[#152348]">
        <RotateCcw className="mr-2 inline h-4 w-4" />
        Undo history
      </p>
      <div className="mt-3 flex items-center gap-3 overflow-x-auto text-xs font-bold text-[#53627f]">
        {[
          "Start",
          `Add ${spec.activeTool}`,
          "Move P",
          "Check relation",
          "Save construction",
        ].map((item, index) => (
          <div key={item} className="flex shrink-0 items-center gap-3">
            <span className="grid h-8 w-8 place-items-center rounded-full border border-[#dbe6fb] bg-white">
              {index ? "●" : "○"}
