    tool,
    activeTool,
    result,
    propertyTitle,
    step,
    checks,
    insight,
    rule,
    practice,
  };
}

function geometryParamsForLesson(
  lessonId: number,
  title: string,
): ReusableLessonEngineParams {
  const params = reusableEngineParamsFor("geometry-2d", title);
  return geometry2DVisualPresetForLesson(lessonId, params);
}

