    147: "outputs step up to integers",
    148: "outputs are -1, 0, or 1",
    149: "choose only the rule",
    150: "inner output becomes the outer input",
    151: "inputs and outputs reverse",
    152: "f(-x)=f(x)",
  } as Record<number, string>)[lessonId] ?? "Drag graph";
}

