function c(title:string,formula:string,note:string,expression:string|undefined,a:Config["a"],b?:Config["b"],n?:Config["n"]):Config{return{title,formula,note,expression,a,b,n}}

export default function CalculusConceptStudio({page,mode}:{page:ConceptPage;mode:string}) {
  const config=configs[page][mode]??Object.values(configs[page])[0];
  const [params,setParams]=useSearchParams();
  const [expression,setExpression]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:expression", config.expression??"");
  const [draft,setDraft]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:draft", config.expression??"");
  const [a,setA]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:a", config.a[1]); const [b,setB]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:b", config.b?.[1]??0); const [n,setN]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:n", config.n?.[1]??20);
  const [playing,setPlaying]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:playing", false); const [speed,setSpeed]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:speed", 1); const [grid,setGrid]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:grid", true); const [learning,setLearning]=useStudioState("CalculusConceptStudio:CalculusConceptStudio:learning", "Explore");
  useEffect(()=>{setExpression(config.expression??"");setDraft(config.expression??"");setA(config.a[1]);setB(config.b?.[1]??0);setN(config.n?.[1]??20);setPlaying(false);setLearning("Explore")},[config]);
  useEffect(()=>{const next=new URLSearchParams(params);next.set("mode",mode);next.set("v_a",tidy(a));next.set("v_b",tidy(b));next.set("v_n",String(Math.round(n)));if(expression)next.set("v_expression",expression);if(next.toString()!==params.toString())setParams(next,{replace:true})},[a,b,expression,mode,n,params,setParams]);
  useEffect(()=>{if(!playing)return;const timer=window.setInterval(()=>{if(config.n)setN(value=>value>=config.n![3]?config.n![2]:value+config.n![4]);else setA(value=>value>=config.a[3]?config.a[2]:round(value+config.a[4]*speed,3))},90);return()=>window.clearInterval(timer)},[config,playing,speed]);
  const compiled=useMemo(()=>compile1(expression),[expression]); const surface=useMemo(()=>compile2(expression),[expression]);
  const draftError=page==="multivariable-vector"?compile2(draft).error:compile1(draft).error;
  const results=useMemo(()=>calculate(page,mode,compiled.fn,surface.fn,a,b,n),[a,b,compiled.fn,mode,n,page,surface.fn]);
  const reset=()=>{setExpression(config.expression??"");setDraft(config.expression??"");setA(config.a[1]);setB(config.b?.[1]??0);setN(config.n?.[1]??20);setPlaying(false);setSpeed(1);setGrid(true)};
  return <div className="cc-studio" data-page={page} data-mode={mode} data-testid="calculus-concept-studio"><div className="cc-workspace"><aside className="cc-panel cc-controls"><h2>{config.title}</h2><p>{config.note}</p><div className="cc-formula"><span>Key relationship</span><strong>{config.formula}</strong></div>{config.expression&&<label className="cc-expression"><span>Function / model</span><div><input aria-label="Function or model" value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>e.key==="Enter"&&!draftError&&setExpression(draft)}/><button type="button" onClick={()=>!draftError&&setExpression(draft)}>Plot</button></div>{draftError&&<small>{draftError}</small>}</label>}<Control item={config.a} value={a} onChange={setA}/>{config.b&&<Control item={config.b} value={b} onChange={setB}/>} {config.n&&<Control item={config.n} value={n} onChange={value=>setN(Math.round(value))}/>}<label className="cc-check"><input type="checkbox" checked={grid} onChange={e=>setGrid(e.target.checked)}/>Show guides and grid</label><div className="cc-player"><button type="button" className="primary" onClick={()=>setPlaying(value=>!value)}>{playing?<Pause/>:<Play/>}<span>{playing?"Pause":"Animate"}</span></button><select aria-label="Animation speed" value={speed} onChange={e=>setSpeed(Number(e.target.value))}><option value={.5}>0.5x</option><option value={1}>1x</option><option value={2}>2x</option></select><button type="button" onClick={reset} title="Reset"><RotateCcw/></button></div></aside><section className="cc-panel cc-visual"><header><div><span>{pageLabel(page)}</span><h2>{config.title}</h2></div><button type="button" className={grid?"active":""} onClick={()=>setGrid(value=>!value)} title="Toggle guides"><Grid3X3/></button></header><ConceptVisual page={page} mode={mode} fn={compiled.fn} surface={surface.fn} a={a} b={b} n={n} grid={grid}/></section><aside className="cc-panel cc-results"><h2><Target/>Live analysis</h2>{results.map(([label,value,tone])=><div className={`cc-result ${tone}`} key={label}><span>{label}</span><strong>{value}</strong></div>)}<section><h3><CheckCircle2/>Concept check</h3><p>{resultInsight(page,mode,results)}</p></section></aside></div><Learning active={learning} onChange={setLearning} config={config} results={results}/></div>;
}

function Control({item,value,onChange}:{item:Config["a"];value:number;onChange:(value:number)=>void}){return <label className="cc-range"><span>{item[0]}<b>{tidy(value)}</b></span><input aria-label={item[0]} type="range" value={clamp(value,item[2],item[3])} min={item[2]} max={item[3]} step={item[4]} onChange={e=>onChange(Number(e.target.value))}/><small><span>{tidy(item[2])}</span><span>{tidy(item[3])}</span></small></label>}

function ConceptVisual({page,mode,fn,surface,a,b,n,grid}:{page:ConceptPage;mode:string;fn:((x:number)=>number)|null;surface:((x:number,y:number)=>number)|null;a:number;b:number;n:number;grid:boolean}){
  if(page==="integration-techniques")return <TechniqueVisual mode={mode} a={a}/>;
  if(page==="integral-applications")return <IntegralApplicationVisual mode={mode} a={a} b={b} n={n} grid={grid}/>;
  if(page==="differential-equations")return <OdeVisual mode={mode} a={a} b={b} n={n} grid={grid}/>;
  if(page==="series-parametric-polar")return <SeriesVisual mode={mode} a={a} n={n} grid={grid}/>;
  if(page==="multivariable-vector")return <MultiVisual mode={mode} fn={surface} a={a} b={b} n={n} grid={grid}/>;
  return <CalculusGraph page={page} mode={mode} fn={fn} a={a} b={b} n={n} grid={grid}/>;
}

function CalculusGraph({page,mode,fn,a,b,grid}:{page:ConceptPage;mode:string;fn:((x:number)=>number)|null;a:number;b:number;n:number;grid:boolean}){const W=820,H=500,P=52,x0=-4,x1=4,y0=-5,y1=8,sx=(x:number)=>P+(x-x0)/(x1-x0)*(W-2*P),sy=(y:number)=>H-P-(y-y0)/(y1-y0)*(H-2*P),points=fn?sample(fn,x0,x1,380):[],fa=fn?safe(fn,a):NaN,d=fn?derivative(fn,a):NaN;return <svg className="cc-graph" viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`${mode} calculus graph`}><rect width={W} height={H} fill="#071d35"/>{grid&&<SvgGrid W={W} H={H} P={P}/>}<line x1={P} x2={W-P} y1={sy(0)} y2={sy(0)} className="axis"/><line x1={sx(0)} x2={sx(0)} y1={P} y2={H-P} className="axis"/><path d={path(points,sx,sy,y0,y1)} className="curve"/>{page==="limits"&&fn&&<><line x1={sx(a)} x2={sx(a)} y1={P} y2={H-P} className="guide"/><circle cx={sx(a-b)} cy={sy(safe(fn,a-b))} r="8" className="left"/><circle cx={sx(a+b)} cy={sy(safe(fn,a+b))} r="8" className="right"/></>}{page==="derivatives"&&fn&&Number.isFinite(fa)&&<><line x1={sx(a-2)} x2={sx(a+2)} y1={sy(fa-2*d)} y2={sy(fa+2*d)} className="tangent"/><circle cx={sx(a)} cy={sy(fa)} r="8" className="point"/></>}<text x="70" y="38">{modeTitle(mode)}</text></svg>}

function TechniqueVisual({mode,a}:{mode:string;a:number}){const steps:Record<string,string[]>={substitution:["Integral x sqrt(x^2+1) dx","u=x^2+1, du=2x dx","(1/2) Integral u^(1/2) du"],parts:["Integral x e^x dx","u=x, dv=e^x dx","x e^x - Integral e^x dx"],partial:["1/(x^2-1)","A/(x-1)+B/(x+1)","(1/2)ln|x-1|-(1/2)ln|x+1|"],trig:["Integral sin^2 x dx","sin^2 x=(1-cos 2x)/2","x/2-sin(2x)/4+C"],"trig-sub":["Integral sqrt(9-x^2) dx","x=3 sin(theta)","9/2(theta+sin theta cos theta)+C"],improper:["Integral 1/x^2 from 1 to infinity","limit b->infinity [-1/x]_1^b",`1-1/${tidy(a)} = ${format(1-1/a,4)}`]};return <div className="cc-technique">{(steps[mode]??steps.substitution).map((step,index)=><div key={step}><b>{index+1}</b><span>{step}</span></div>)}<svg viewBox="0 0 760 240"><rect width="760" height="240" fill="#fff"/><path d="M70 190 C170 90 260 150 350 65 C450 165 560 75 690 110" fill="none" stroke="#09b8df" strokeWidth="5"/><path d="M70 190 L70 190 C170 90 260 150 350 65 L350 190 Z" fill="#f7c84b" opacity=".32"/><text x="70" y="42">Transformation preserves the integral value</text></svg></div>}

function IntegralApplicationVisual({mode,a,b,n,grid}:{mode:string;a:number;b:number;n:number;grid:boolean}){const W=820,H=500,P=50,sx=(x:number)=>P+(x+3)/6*(W-2*P),sy=(y:number)=>H-P-(y+1)/6*(H-2*P);if(mode==="volumes")return <svg className="cc-light" viewBox={`0 0 ${W} ${H}`}><rect width={W} height={H} fill="#fff"/><ellipse cx="410" cy="130" rx="240" ry="58" fill="#c4b5fd" opacity=".55" stroke="#7c3aed" strokeWidth="3"/><path d="M170 130 Q410 460 650 130 L650 250 Q410 530 170 250 Z" fill="#f5c56a" opacity=".35" stroke="#0ea5e9" strokeWidth="3"/><ellipse cx="410" cy={250+a*25} rx="170" ry="32" fill="none" stroke="#f59e0b" strokeWidth="8"/><text x="60" y="55">Washer method: rotate the region around the x-axis</text></svg>;if(mode==="work"||mode==="fluid")return <svg className="cc-light" viewBox={`0 0 ${W} ${H}`}><rect width={W} height={H} fill="#fff"/>{mode==="work"?<><path d="M100 250 h80 l20-45 35 90 35-90 35 90 35-90 35 90 20-45 h250" fill="none" stroke="#0ea5e9" strokeWidth="6"/><line x1="180" x2={180+b*220} y1="335" y2="335" stroke="#8b5cf6" strokeWidth="5"/><text x="90" y="70">Spring work: W = (1/2) k x^2</text></>:<><rect x="190" y="95" width="420" height={a*42} fill="#38bdf8" opacity=".42"/><rect x="300" y="125" width={b*70} height={a*36} fill="#f8c55b" opacity=".48" stroke="#d97706"/><path d="M635 115 v270" stroke="#1d4ed8" strokeWidth="5"/><text x="90" y="65">Hydrostatic pressure increases with depth</text></>}</svg>;const left=mode==="area"?a:0,right=mode==="area"?b:a,points=sample(x=>x*x,-2.5,2.5,260);return <svg className="cc-light" viewBox={`0 0 ${W} ${H}`}><rect width={W} height={H} fill="#fff"/>{grid&&<g opacity=".5"><SvgGrid W={W} H={H} P={P} light/></g>}<line x1={P} x2={W-P} y1={sy(0)} y2={sy(0)} className="axis light"/><path d={path(points,sx,sy,-1,5)} fill="none" stroke="#0ea5e9" strokeWidth="4"/><line x1={sx(-2)} x2={sx(2)} y1={sy(4)} y2={sy(4)} stroke="#8b5cf6" strokeWidth="4"/><path d={`M${sx(left)},${sy(4)} L${sx(right)},${sy(4)} ${sample(x=>x*x,left,right,100).reverse().map(p=>`L${sx(p.x)},${sy(p.y)}`).join(" ")} Z`} fill="#f5c453" opacity=".35"/>{Array.from({length:Math.min(80,Math.round(n))},(_,i)=>{const x=left+i/(n)*(right-left);return <line key={i} x1={sx(x)} x2={sx(x)} y1={sy(4)} y2={sy(x*x)} stroke="#f59e0b" opacity=".55"/>})}<text x="70" y="42">{mode==="arc"?"Arc length along y=x^2":mode==="surface"?"Surface generated by rotation":"Area between y=4 and y=x^2"}</text></svg>}

