function calculate(page:ConceptPage,mode:string,fn:((x:number)=>number)|null,surface:((x:number,y:number)=>number)|null,a:number,b:number,n:number):Array<[string,string,Tone]>{
  if(page==="limits"&&fn){const d=Math.max(.00001,Math.min(.005,Math.abs(b)*.02)),l=safe(fn,a-d),r=safe(fn,a+d),same=Math.abs(l-r)<Math.max(.02,d*50);return [["Left approach",format(l,5),"plain"],["Right approach",format(r,5),"plain"],[mode==="asymptotes"?"Magnitude":"Two-sided limit",mode==="asymptotes"?format(Math.max(Math.abs(l),Math.abs(r)),3):same?format((l+r)/2,5):"DNE",same?"good":"warn"],["Classification",!Number.isFinite(l)||!Number.isFinite(r)||Math.max(Math.abs(l),Math.abs(r))>20?"Infinite":same?"Limit exists":"Jump / mismatch",same?"good":"warn"]]}
  if(page==="derivatives"&&fn){const x=mode==="linearization"?b:a,d=derivative(fn,a),sec=b?((safe(fn,a+b)-safe(fn,a))/b):d,order=Math.max(1,Math.round(n)),higher=nthDerivative(fn,a,order),linear=safe(fn,a)+d*(x-a);return [["f(a)",format(safe(fn,a),5),"plain"],[mode==="higher"?`Derivative order ${order}`:"f'(a)",format(mode==="higher"?higher:d,5),"good"],[mode==="linearization"?"L(x)":"Comparison slope",format(mode==="linearization"?linear:sec,5),"plain"],[mode==="linearization"?"Approximation error":"Slope difference",format(Math.abs((mode==="linearization"?safe(fn,x):d)-(mode==="linearization"?linear:sec)),6),"good"]]}
  if(page==="integration-techniques"){const value=mode==="improper"?1-1/a:mode==="trig-sub"?.5*(a*Math.sqrt(Math.max(0,9-a*a))+9*Math.asin(a/3)):mode==="partial"?.5*Math.log(Math.abs((a-1)/(a+1))):mode==="trig"?a/2-Math.sin(2*a)/4:mode==="parts"?(a-1)*Math.exp(a)+1:(Math.pow(a*a+1,1.5)-1)/3;return [["Transformed value",format(value,6),"good"],["Upper / probe",tidy(a),"plain"],["Validation","Equivalent form","good"]]}
  if(page==="integral-applications"){const value=mode==="work"?.5*a*b*b:mode==="fluid"?1000*9.81*b*a*a/2:mode==="volumes"?Math.PI*(16-a**4):mode==="arc"?numeric(x=>Math.sqrt(1+4*x*x),0,a):mode==="surface"?numeric(x=>2*Math.PI*Math.sqrt(x)*Math.sqrt(1+1/(4*Math.max(x,.001))),.001,a):numeric(x=>4-x*x,a,b);return [["Computed quantity",format(value,5),"good"],["Current parameter",tidy(a),"plain"],["Resolution",String(Math.round(n)),"plain"]]}
