  if(page==="series-parametric-polar"){const value=mode==="sequences"?1/Math.max(1,a):mode==="convergence"?partialGeometric(a,n):mode==="power"?partialPower(a,n):mode==="taylor"?taylor(a,n):mode==="parametric"?Math.hypot(2*Math.cos(a),Math.sin(2*a)*2):1+Math.cos(a);const reference=mode==="convergence"?1/(1-a):mode==="power"?1/(1-a):mode==="taylor"?Math.sin(a):value;return [["Current value",format(value,7),"plain"],["Reference",format(reference,7),"good"],["Error",format(Math.abs(value-reference),8),Math.abs(value-reference)<.01?"good":"warn"],["Terms / samples",String(Math.round(n)),"plain"]]}
  if(page==="multivariable-vector"){const z=surface?safe2(surface,a,b):NaN,fx=surface?partialX(surface,a,b):2*a,fy=surface?partialY(surface,a,b):-2*b,value=mode==="multiple"?a*b*(a+b)/2:mode==="fields"?Math.hypot(-b,a):mode==="theorems"?2:z;return [[mode==="multiple"?"Double integral":mode==="fields"?"Field magnitude":mode==="theorems"?"Divergence":"Surface value",format(value,5),"good"],["Partial fx",format(fx,5),"plain"],["Partial fy",format(fy,5),"plain"],["Gradient magnitude",format(Math.hypot(fx,fy),5),"good"]]}
