}

function resultInsight(page:ConceptPage,mode:string,results:Array<[string,string,Tone]>){return `${modeTitle(mode)} is active. ${results.some(item=>item[2]==="warn")?"Adjust the controls to inspect the limiting or approximation behavior.":`The current ${pageLabel(page).toLowerCase()} state is numerically consistent.`}`}
