function sample(fn:(x:number)=>number,min:number,max:number,count:number){return Array.from({length:count},(_,i)=>{const x=min+i/(count-1)*(max-min);return{x,y:safe(fn,x)}})}function path(points:Array<{x:number;y:number}>,sx:(x:number)=>number,sy:(y:number)=>number,yMin:number,yMax:number){let open=false;return points.map(p=>{if(!Number.isFinite(p.y)||p.y<yMin-2||p.y>yMax+2){open=false;return""}const m=open?"L":"M";open=true;return`${m}${sx(p.x).toFixed(2)},${sy(p.y).toFixed(2)}`}).join(" ")}function graphPath(points:Array<{x:number;y:number}>,sx:(x:number)=>number,sy:(y:number)=>number){return points.map((p,i)=>`${i?"L":"M"}${sx(p.x).toFixed(2)},${sy(p.y).toFixed(2)}`).join(" ")}
function safe(fn:(x:number)=>number,x:number){try{const y=fn(x);return Number.isFinite(y)?y:NaN}catch{return NaN}}function safe2(fn:(x:number,y:number)=>number,x:number,y:number){try{const z=fn(x,y);return Number.isFinite(z)?z:NaN}catch{return NaN}}function derivative(fn:(x:number)=>number,x:number){const h=1e-4;return(safe(fn,x+h)-safe(fn,x-h))/(2*h)}function nthDerivative(fn:(x:number)=>number,x:number,n:number):number{return n<=1?derivative(fn,x):derivative(v=>nthDerivative(fn,v,n-1),x)}function partialX(fn:(x:number,y:number)=>number,x:number,y:number){const h=1e-4;return(safe2(fn,x+h,y)-safe2(fn,x-h,y))/(2*h)}function partialY(fn:(x:number,y:number)=>number,x:number,y:number){const h=1e-4;return(safe2(fn,x,y+h)-safe2(fn,x,y-h))/(2*h)}
