function eulerPoints(h:number,target:number,y0:number){let x=0,y=y0;const step=Math.max(.01,h),pts=[{x,y}];while(x+step<=target+.0001){y+=step*(x-y);x+=step;pts.push({x,y})}return pts}
function partialGeometric(r:number,n:number){return Math.abs(1-r)<1e-9?n:(1-r**Math.max(1,Math.round(n)))/(1-r)}function partialPower(x:number,n:number){let sum=0;for(let i=0;i<Math.max(1,Math.round(n));i++)sum+=x**i;return sum}function taylor(x:number,n:number){let sum=0;for(let k=0;2*k+1<=Math.max(1,Math.round(n));k++)sum+=(k%2?-1:1)*x**(2*k+1)/factorial(2*k+1);return sum}function factorial(n:number){let v=1;for(let i=2;i<=n;i++)v*=i;return v}
