export default function CalculusDerivativeApplicationsStudio({ mode }: Props) {
  const [params, setParams] = useSearchParams();
  const [time, setTime] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:time", numberParam(params.get("v_time"), 1.5));
  const [radius, setRadius] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:radius", numberParam(params.get("v_radius"), 3));
  const [radiusRate, setRadiusRate] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:radiusRate", numberParam(params.get("v_radius_rate"), 0.5));
  const [curveX, setCurveX] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:curveX", numberParam(params.get("v_curve_x"), 0.75));
  const [width, setWidth] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:width", numberParam(params.get("v_width"), 24));
  const [length, setLength] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:length", numberParam(params.get("v_length"), 36));
  const [cut, setCut] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:cut", numberParam(params.get("v_cut"), 4.2));
  const [mvtA, setMvtA] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:mvtA", numberParam(params.get("v_mvt_a"), 0));
  const [mvtB, setMvtB] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:mvtB", numberParam(params.get("v_mvt_b"), 3));
  const [playing, setPlaying] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:playing", false);
  const [speed, setSpeed] = useStudioState("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:speed", 1);
  const [learning, setLearning] = useStudioState<LearningMode>("CalculusDerivativeApplicationsStudio:CalculusDerivativeApplicationsStudio:learning", "Experiment");
  const info = modeInfo[mode] ?? modeInfo.optimization;
  const feasibleMax = Math.max(0.2, Math.min(width, length) / 2 - 0.1);
  const optimum = optimalCut(width, length);
  const safeCut = clamp(cut, 0.1, feasibleMax);

  useEffect(() => {
    setPlaying(false);
    setLearning("Experiment");
  }, [mode]);

  useEffect(() => {
    const next = new URLSearchParams(params);
    next.set("mode", mode);
    next.set("v_time", tidy(time));
    next.set("v_radius", tidy(radius));
    next.set("v_radius_rate", tidy(radiusRate));
    next.set("v_curve_x", tidy(curveX));
    next.set("v_width", tidy(width));
    next.set("v_length", tidy(length));
    next.set("v_cut", tidy(safeCut));
    next.set("v_mvt_a", tidy(mvtA));
    next.set("v_mvt_b", tidy(mvtB));
    if (next.toString() !== params.toString()) setParams(next, { replace: true });
  }, [curveX, length, mode, mvtA, mvtB, params, radius, radiusRate, safeCut, setParams, time, width]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => {
      if (mode === "motion") setTime((value) => value >= 6 ? 0 : round(value + 0.04 * speed, 2));
      else if (mode === "related") setRadius((value) => value >= 8 ? 1 : round(value + 0.035 * speed, 2));
      else if (mode === "curve") setCurveX((value) => value >= 3 ? -3 : round(value + 0.04 * speed, 2));
      else if (mode === "optimization") setCut((value) => value >= feasibleMax ? 0.1 : round(value + 0.04 * speed, 2));
      else setMvtB((value) => value >= 4.5 ? Math.max(mvtA + 0.5, 1) : round(value + 0.035 * speed, 2));
    }, 80);
    return () => window.clearInterval(timer);
  }, [feasibleMax, mode, mvtA, playing, speed]);

  const reset = () => {
    setTime(1.5);
    setRadius(3);
    setRadiusRate(0.5);
    setCurveX(0.75);
    setWidth(24);
    setLength(36);
    setCut(4.2);
    setMvtA(0);
    setMvtB(3);
    setPlaying(false);
    setSpeed(1);
  };

  return <div className="da-studio" data-mode={mode} data-testid="derivative-applications-studio">
    <div className="da-workspace">
      <aside className="da-panel da-controls">
        <header><span><Activity /></span><div><h2>{info.title}</h2><p>{info.subtitle}</p></div></header>
        <ModeControls mode={mode} time={time} radius={radius} radiusRate={radiusRate} curveX={curveX} width={width} length={length} cut={safeCut} feasibleMax={feasibleMax} mvtA={mvtA} mvtB={mvtB} onTime={setTime} onRadius={setRadius} onRadiusRate={setRadiusRate} onCurveX={setCurveX} onWidth={(value) => { setWidth(value); setCut((current) => Math.min(current, Math.min(value, length) / 2 - 0.1)); }} onLength={(value) => { setLength(value); setCut((current) => Math.min(current, Math.min(width, value) / 2 - 0.1)); }} onCut={setCut} onMvtA={(value) => { setMvtA(value); if (value >= mvtB) setMvtB(value + 0.5); }} onMvtB={(value) => setMvtB(Math.max(mvtA + 0.25, value))} onFindOptimum={() => setCut(optimum)} />
        <div className="da-player"><button type="button" className="primary" onClick={() => setPlaying((value) => !value)}>{playing ? <Pause /> : <Play />}<span>{playing ? "Pause" : mode === "optimization" ? "Animate search" : "Animate"}</span></button><select aria-label="Animation speed" value={speed} onChange={(event) => setSpeed(Number(event.target.value))}><option value={0.5}>0.5x</option><option value={1}>1x</option><option value={2}>2x</option></select><button type="button" onClick={reset} title="Reset controls"><RotateCcw /></button></div>
      </aside>

      <section className="da-center" aria-label={`${info.title} visualization`}>
        <ModeVisual mode={mode} time={time} radius={radius} radiusRate={radiusRate} curveX={curveX} width={width} length={length} cut={safeCut} optimum={optimum} mvtA={mvtA} mvtB={mvtB} />
      </section>

      <aside className="da-panel da-analysis" aria-live="polite">
        <ModeAnalysis mode={mode} time={time} radius={radius} radiusRate={radiusRate} curveX={curveX} width={width} length={length} cut={safeCut} optimum={optimum} mvtA={mvtA} mvtB={mvtB} />
      </aside>
    </div>
    <LearningPanel active={learning} onChange={setLearning} mode={mode} cut={safeCut} optimum={optimum} onFindOptimum={() => setCut(optimum)} />
  </div>;
}

type ControlProps = {
  mode: string; time: number; radius: number; radiusRate: number; curveX: number; width: number; length: number; cut: number; feasibleMax: number; mvtA: number; mvtB: number;
  onTime: (value: number) => void; onRadius: (value: number) => void; onRadiusRate: (value: number) => void; onCurveX: (value: number) => void; onWidth: (value: number) => void; onLength: (value: number) => void; onCut: (value: number) => void; onMvtA: (value: number) => void; onMvtB: (value: number) => void; onFindOptimum: () => void;
};

function ModeControls(props: ControlProps) {
  if (props.mode === "motion") return <><Formula label="Position model" value="s(t) = t^3 - 6t^2 + 9t" /><Slider label="Time t" value={props.time} min={0} max={6} step={0.05} onChange={props.onTime} unit="s" /></>;
  if (props.mode === "related") return <><Formula label="Sphere relationship" value="V = (4/3) pi r^3" /><Slider label="Radius r" value={props.radius} min={1} max={8} step={0.05} onChange={props.onRadius} unit="cm" /><Slider label="Radius rate dr/dt" value={props.radiusRate} min={0.1} max={2} step={0.05} onChange={props.onRadiusRate} unit="cm/s" /></>;
  if (props.mode === "curve") return <><Formula label="Function" value="f(x) = x^3 - 3x" /><Slider label="Analysis point x" value={props.curveX} min={-3} max={3} step={0.05} onChange={props.onCurveX} /></>;
  if (props.mode === "optimization") return <><Formula label="Scenario: Open-Top Box" value="A rectangular sheet has corners cut out and the sides folded up." /><svg className="da-sheet" viewBox="0 0 220 150" role="img" aria-label="Sheet net with corner squares x"><rect x="18" y="18" width="184" height="114" fill="#eef7ff" stroke="#163e73" strokeWidth="2" /><rect x="18" y="18" width="28" height="28" fill="#dbeafe" stroke="#163e73" /><rect x="174" y="18" width="28" height="28" fill="#dbeafe" stroke="#163e73" /><rect x="18" y="104" width="28" height="28" fill="#dbeafe" stroke="#163e73" /><rect x="174" y="104" width="28" height="28" fill="#dbeafe" stroke="#163e73" /><text x="100" y="88" textAnchor="middle" fontSize="14">L</text><text x="30" y="84" fontSize="12">W</text><text x="28" y="38" fontSize="11">x</text></svg><Slider label="Sheet width W" value={props.width} min={12} max={60} step={1} onChange={props.onWidth} unit="in" /><Slider label="Sheet length L" value={props.length} min={18} max={80} step={1} onChange={props.onLength} unit="in" /><Slider label="Cut size x" value={props.cut} min={0.1} max={props.feasibleMax} step={0.05} onChange={props.onCut} unit="in" /><div className="da-constraint"><CheckCircle2 /><span>Constraint: 0 &lt; x &lt; min(W/2, L/2)</span></div></>;
  return <><Formula label="Function" value="f(x) = x^2" /><Slider label="Interval start a" value={props.mvtA} min={-3} max={3.5} step={0.05} onChange={props.onMvtA} /><Slider label="Interval end b" value={props.mvtB} min={props.mvtA + 0.25} max={5} step={0.05} onChange={props.onMvtB} /></>;
}

function ModeVisual(props: { mode: string; time: number; radius: number; radiusRate: number; curveX: number; width: number; length: number; cut: number; optimum: number; mvtA: number; mvtB: number }) {
  if (props.mode === "motion") return <MotionVisual time={props.time} />;
  if (props.mode === "related") return <RelatedRatesVisual radius={props.radius} radiusRate={props.radiusRate} />;
  if (props.mode === "curve") return <CurveVisual x={props.curveX} />;
  if (props.mode === "optimization") return <OptimizationVisual width={props.width} length={props.length} cut={props.cut} optimum={props.optimum} />;
  return <MvtVisual a={props.mvtA} b={props.mvtB} />;
}

function MotionVisual({ time }: { time: number }) {
  const position = motionPosition(time), velocity = motionVelocity(time);
  return <div className="da-visual-stack"><article className="da-panel da-scene"><header><h2>Motion along a line</h2><span>t = {tidy(time)} s</span></header><svg viewBox="0 0 820 265" role="img" aria-label="Particle position on a number line"><defs><linearGradient id="motionTrail" x1="0" x2="1"><stop stopColor="#09b9df" /><stop offset="1" stopColor="#8b4df5" /></linearGradient></defs><line x1="70" x2="750" y1="155" y2="155" stroke="#91a6bd" strokeWidth="3" />{Array.from({ length: 7 }, (_, index) => <g key={index}><line x1={90 + index * 105} x2={90 + index * 105} y1="145" y2="165" stroke="#607892" /><text x={84 + index * 105} y="188">{index * 2}</text></g>)}<line x1="90" x2={90 + clamp(position, 0, 12) / 12 * 630} y1="155" y2="155" stroke="url(#motionTrail)" strokeWidth="10" strokeLinecap="round" /><circle cx={90 + clamp(position, 0, 12) / 12 * 630} cy="155" r="17" fill="#ff8a1f" stroke="#fff" strokeWidth="5" /><text x="55" y="54" className="title">s(t) = {format(position, 3)} m</text><text x="55" y="86" className="note">velocity {velocity >= 0 ? "points right" : "points left"}</text></svg></article><GraphCard title="Position and velocity" curves={[{ fn: motionPosition, color: "#09b9df" }, { fn: motionVelocity, color: "#8b4df5" }]} xMin={0} xMax={6} marker={time} /></div>;
}

function RelatedRatesVisual({ radius, radiusRate }: { radius: number; radiusRate: number }) {
  return <div className="da-visual-stack"><article className="da-panel da-scene"><header><h2>Linked rates in an expanding sphere</h2><span>dr/dt = {tidy(radiusRate)} cm/s</span></header><StudioMath3D label="Expanding sphere"><ExpandingSphere radius={radius} /></StudioMath3D></article><GraphCard title="Volume as radius changes" curves={[{ fn: (r) => 4 / 3 * Math.PI * r ** 3, color: "#09b9df" }]} xMin={0} xMax={8} marker={radius} /></div>;
}

function CurveVisual({ x }: { x: number }) { return <div className="da-visual-stack"><GraphCard title="Function, tangent, and critical behavior" curves={[{ fn: curveFunction, color: "#09b9df" }, { fn: curveDerivative, color: "#8b4df5" }]} xMin={-3} xMax={3} marker={x} tangent /><article className="da-panel da-band"><div><span>Increasing</span><b>x &lt; -1 and x &gt; 1</b></div><div><span>Decreasing</span><b>-1 &lt; x &lt; 1</b></div><div><span>Inflection</span><b>x = 0</b></div></article></div>; }

function OptimizationVisual({ width, length, cut, optimum }: { width: number; length: number; cut: number; optimum: number }) {
  return <div className="da-visual-stack"><article className="da-panel da-box-scene"><header><h2>3D box model</h2><span>x = {tidy(cut)} in</span></header><StudioMath3D label="Open top box model"><OpenBox width={Math.max(0.5, length - 2 * cut)} depth={Math.max(0.5, width - 2 * cut)} height={cut} /></StudioMath3D></article><VolumeGraph width={width} length={length} cut={cut} optimum={optimum} /></div>;
}

function MvtVisual({ a, b }: { a: number; b: number }) {
  const c = (a + b) / 2, slope = a + b;
  return <div className="da-visual-stack"><GraphCard title="Secant and matching tangent" curves={[{ fn: (x) => x * x, color: "#09b9df" }]} xMin={-3} xMax={5} marker={c} secant={{ a, b }} tangent /><article className="da-panel da-band"><div><span>Average slope</span><b>{format(slope, 4)}</b></div><div><span>MVT point c</span><b>{format(c, 4)}</b></div><div><span>f'(c)</span><b>{format(2 * c, 4)}</b></div></article></div>;
}

function GraphCard({ title, curves, xMin, xMax, marker, tangent = false, secant }: { title: string; curves: Array<{ fn: (x: number) => number; color: string }>; xMin: number; xMax: number; marker: number; tangent?: boolean; secant?: { a: number; b: number } }) {
  const width = 820, height = 430, pad = 48;
  const values = curves.flatMap((curve) => sample(curve.fn, xMin, xMax, 180).map((point) => point.y)).filter(Number.isFinite);
  const rawMin = Math.min(...values, -1), rawMax = Math.max(...values, 1), margin = Math.max(1, (rawMax - rawMin) * .12), yMin = rawMin - margin, yMax = rawMax + margin;
  const sx = (x: number) => pad + (x - xMin) / (xMax - xMin) * (width - pad * 2), sy = (y: number) => height - pad - (y - yMin) / (yMax - yMin) * (height - pad * 2);
  const primary = curves[0].fn, markerY = primary(marker), tangentSlope = derivative(primary, marker);
  return <article className="da-panel da-graph-card"><header><h2>{title}</h2><div>{curves.map((curve, index) => <span key={curve.color}><i style={{ background: curve.color }} />{index ? "derivative" : "function"}</span>)}</div></header><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label={title}><rect width={width} height={height} fill="#fff" />{Array.from({ length: 9 }, (_, index) => <line key={`v${index}`} x1={pad + index * (width-pad*2)/8} x2={pad + index*(width-pad*2)/8} y1={pad} y2={height-pad} className="grid" />)}{Array.from({ length: 7 }, (_, index) => <line key={`h${index}`} x1={pad} x2={width-pad} y1={pad+index*(height-pad*2)/6} y2={pad+index*(height-pad*2)/6} className="grid" />)}<line x1={pad} x2={width-pad} y1={sy(0)} y2={sy(0)} className="axis" /><line x1={sx(0)} x2={sx(0)} y1={pad} y2={height-pad} className="axis" />{curves.map((curve) => <path key={curve.color} d={graphPath(sample(curve.fn,xMin,xMax,280),sx,sy)} fill="none" stroke={curve.color} strokeWidth="4" />)}{secant && <line x1={sx(secant.a)} y1={sy(primary(secant.a))} x2={sx(secant.b)} y2={sy(primary(secant.b))} stroke="#f59e0b" strokeWidth="3" />}{tangent && <line x1={sx(xMin)} y1={sy(markerY+tangentSlope*(xMin-marker))} x2={sx(xMax)} y2={sy(markerY+tangentSlope*(xMax-marker))} stroke="#ef4444" strokeWidth="3" strokeDasharray="9 6" />}<line x1={sx(marker)} x2={sx(marker)} y1={pad} y2={height-pad} stroke="#8b5cf6" strokeDasharray="7 6" /><circle cx={sx(marker)} cy={sy(markerY)} r="8" fill="#8b5cf6" stroke="#fff" strokeWidth="3" /></svg></article>;
}

function VolumeGraph({ width: sheetW, length: sheetL, cut, optimum }: { width: number; length: number; cut: number; optimum: number }) {
  const width = 820, height = 330, pad = 48, xMax = Math.min(sheetW, sheetL) / 2, maxVolume = boxVolume(sheetW, sheetL, optimum) * 1.14;
  const sx = (x: number) => pad + x / xMax * (width - pad * 2), sy = (y: number) => height - pad - y / maxVolume * (height - pad * 2);
  const points = sample((x) => boxVolume(sheetW, sheetL, x), 0, xMax, 220);
  return <article className="da-panel da-volume"><header><h2>Volume V(x) vs cut size x</h2><span>Maximum at x = {format(optimum, 3)}</span></header><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Box volume optimization graph"><rect width={width} height={height} fill="#fff" /><rect x={pad} y={pad} width={width-pad*2} height={height-pad*2} fill="#effbef" /><line x1={pad} x2={width-pad} y1={height-pad} y2={height-pad} className="axis" /><path d={graphPath(points,sx,sy)} fill="none" stroke="#0aaed8" strokeWidth="4" /><line x1={sx(optimum)} x2={sx(optimum)} y1={pad} y2={height-pad} stroke="#159947" strokeDasharray="7 5" /><circle cx={sx(optimum)} cy={sy(boxVolume(sheetW,sheetL,optimum))} r="8" fill="#19b34b" /><circle cx={sx(cut)} cy={sy(boxVolume(sheetW,sheetL,cut))} r="7" fill="#ff8a1f" stroke="#fff" strokeWidth="2" /><text x={sx(optimum)-38} y={sy(boxVolume(sheetW,sheetL,optimum))-14}>maximum</text><text x={sx(cut)+10} y={sy(boxVolume(sheetW,sheetL,cut))+5}>x = {tidy(cut)}</text></svg></article>;
}

function ModeAnalysis(props: { mode: string; time: number; radius: number; radiusRate: number; curveX: number; width: number; length: number; cut: number; optimum: number; mvtA: number; mvtB: number }) {
  if (props.mode === "motion") { const s=motionPosition(props.time),v=motionVelocity(props.time),a=motionAcceleration(props.time); return <><AnalysisTitle title="Live motion" /><Metric label="Position s(t)" value={`${format(s,3)} m`} /><Metric label="Velocity v(t)" value={`${format(v,3)} m/s`} tone={v>=0?"green":"violet"} /><Metric label="Acceleration a(t)" value={`${format(a,3)} m/s^2`} /><Insight text={v*a>0?"Speed is increasing because velocity and acceleration have the same sign.":v*a<0?"Speed is decreasing because velocity and acceleration have opposite signs.":"The particle is at a turning or transition point."} /></>; }
  if (props.mode === "related") { const volume=4/3*Math.PI*props.radius**3,rate=4*Math.PI*props.radius**2*props.radiusRate; return <><AnalysisTitle title="Linked rates" /><Metric label="Current volume" value={`${format(volume,3)} cm^3`} /><Metric label="dV/dt" value={`${format(rate,3)} cm^3/s`} tone="green" /><Metric label="Surface area" value={`${format(4*Math.PI*props.radius**2,3)} cm^2`} /><section className="da-proof"><h3>Checklist</h3><p><CheckCircle2 /> Constraint V = 4/3 π r³</p><p><CheckCircle2 /> Objective dV/dt = 4π r² dr/dt</p></section><Insight text="Differentiate the relationship first, then substitute the current radius and its rate." /></>; }
  if (props.mode === "curve") { const first=curveDerivative(props.curveX),second=curveSecond(props.curveX); return <><AnalysisTitle title={`Local analysis at x = ${tidy(props.curveX)}`} /><Metric label="f(x)" value={format(curveFunction(props.curveX),4)} /><Metric label="f'(x)" value={format(first,4)} tone={first>=0?"green":"red"} /><Metric label="f''(x)" value={format(second,4)} tone={second>=0?"green":"violet"} /><Insight text={`${first>0?"Increasing":"Decreasing"} and ${second>0?"concave up":second<0?"concave down":"at an inflection point"}.`} /></>; }
  if (props.mode === "optimization") { const volume=boxVolume(props.width,props.length,props.cut), derivativeValue=boxDerivative(props.width,props.length,props.cut), x=props.cut; return <><AnalysisTitle title="Dimensions at Optimum" /><Metric label="x*" value={`${format(props.optimum,2)} in`} tone="green" /><Metric label="L − 2x*" value={`${format(props.length-2*props.optimum,2)} in`} /><Metric label="W − 2x*" value={`${format(props.width-2*props.optimum,2)} in`} /><Metric label="Height (x*)" value={`${format(props.optimum,2)} in`} /><Metric label="V(x)" value={`${format(volume,2)} in³`} tone="green" /><Metric label="V'(x)" value={format(derivativeValue,3)} tone={Math.abs(derivativeValue)<.1?"green":"plain"} /><Metric label="Feasible interval" value={`0 < x < ${format(Math.min(props.width,props.length)/2,2)}`} tone={x>0&&x<Math.min(props.width,props.length)/2?"green":"red"} /><section className="da-proof"><h3>Why this is a maximum</h3><p><CheckCircle2 /> V'(x*) = 0 at x* = {format(props.optimum,4)}</p><p><CheckCircle2 /> The graph of V(x) has a peak at x = {format(props.optimum,2)}</p><p><CheckCircle2 /> V''(x*) = {format(boxSecond(props.width,props.length,props.optimum),3)} &lt; 0 (concave down)</p></section></>; }
  const c=(props.mvtA+props.mvtB)/2,slope=props.mvtA+props.mvtB; return <><AnalysisTitle title="Mean Value check" /><Metric label="Average slope" value={format(slope,4)} /><Metric label="Theorem point c" value={format(c,4)} tone="violet" /><Metric label="Tangent slope f'(c)" value={format(2*c,4)} tone="green" /><section className="da-proof"><h3>Checklist</h3><p><CheckCircle2 /> Continuous on [a,b]</p><p><CheckCircle2 /> Differentiable on (a,b)</p><p><CheckCircle2 /> f'(c) equals the secant slope</p></section><Insight text="The secant and tangent slopes agree, so the Mean Value Theorem is verified on this interval." /></>;
}

function LearningPanel({ active, onChange, mode, cut: _cut, optimum, onFindOptimum }: { active: LearningMode; onChange: (value: LearningMode) => void; mode: string; cut: number; optimum: number; onFindOptimum: () => void }) {
  if (mode === "optimization") {
    return (
      <section className="da-guide-row">
        <article>
          <h3><Lightbulb /> Guided Experiment</h3>
          <ol>
            <li>Adjust x and watch the 3D box update.</li>
            <li>Notice how volume increases, reaches a peak, then decreases.</li>
            <li>Use the graph and derivative to justify the maximum.</li>
          </ol>
        </article>
        <article>
          <h3><Lightbulb /> Try this:</h3>
          <p>Set x to values below, near, and above {format(optimum, 2)}. What do you observe?</p>
        </article>
        <article>
          <h3><Trophy /> Challenge</h3>
          <p>Use a different sheet size and find the optimal box.</p>
          <button className="da-find" type="button" onClick={onFindOptimum}><Trophy /> Find optimum</button>
          <CheckChallenge pass={Math.abs(_cut - optimum) < 0.15} />
        </article>
      </section>
    );
  }
  const copy: Record<LearningMode,string> = { Experiment: modeInfo[mode]?.subtitle ?? "Explore the derivative model.", Reasoning: "Identify the changing quantity, write its relationship, differentiate, and only then substitute the current values.", Challenge: mode === "motion" ? "Challenge: stop the particle where v and a have opposite signs." : mode === "related" ? "Challenge: label the similar-triangle diagram so dV/dt matches 4πr² dr/dt." : mode === "curve" ? "Challenge: generate a sign chart from zeros of f′ and f″ on the graph." : "Challenge: place Rolle/MVT points so the tangent matches the secant slope." };
  return <section className="da-learning"><nav>{(["Experiment","Reasoning","Challenge"] as LearningMode[]).map((tab)=><button type="button" key={tab} className={active===tab?"active":""} onClick={()=>onChange(tab)}>{tab==="Experiment"?<Lightbulb />:tab==="Reasoning"?<Target />:<Trophy />}{tab}</button>)}</nav><p>{copy[active]}</p><CheckChallenge pass={mode === "mvt"} /></section>;
}

function CheckChallenge({ pass }: { pass: boolean }) {
  const [note, setNote] = useState("");
  return (
    <>
      <button className="da-find" type="button" onClick={() => setNote(pass ? "Challenge complete: the live model matches the target." : "Not yet. Adjust the controls toward the live target, then check again.")}>Check challenge</button>
      {note ? <p role="status">{note}</p> : null}
    </>
  );
}
function Slider({ label, value, min, max, step, onChange, unit = "" }: { label: string; value: number; min: number; max: number; step: number; onChange: (value: number) => void; unit?: string }) { return <label className="da-slider"><span>{label}<b>{tidy(value)} {unit}</b></span><input aria-label={label} type="range" min={min} max={max} step={step} value={clamp(value,min,max)} onChange={(event)=>onChange(Number(event.target.value))} /><small><span>{tidy(min)}</span><span>{tidy(max)}</span></small></label>; }
function Formula({ label, value }: { label: string; value: string }) { return <div className="da-formula"><span>{label}</span><strong>{value}</strong></div>; }
function Metric({ label, value, tone="plain" }: { label: string; value: string; tone?: string }) { return <div className={`da-metric ${tone}`}><span>{label}</span><strong>{value}</strong></div>; }
function Insight({ text }: { text: string }) { return <section className="da-insight"><Lightbulb /><p>{text}</p></section>; }
function AnalysisTitle({ title }: { title: string }) { return <h2 className="da-analysis-title"><Gauge />{title}</h2>; }

function motionPosition(t:number){return t**3-6*t**2+9*t} function motionVelocity(t:number){return 3*t**2-12*t+9} function motionAcceleration(t:number){return 6*t-12}
function curveFunction(x:number){return x**3-3*x} function curveDerivative(x:number){return 3*x**2-3} function curveSecond(x:number){return 6*x}
function boxVolume(width:number,length:number,x:number){return Math.max(0,x*(width-2*x)*(length-2*x))} function boxDerivative(width:number,length:number,x:number){return width*length-4*(width+length)*x+12*x*x} function boxSecond(width:number,length:number,x:number){return 24*x-4*(width+length)}
function optimalCut(width:number,length:number){return (width+length-Math.sqrt(width*width-width*length+length*length))/6}
function derivative(fn:(x:number)=>number,x:number){const h=.0001;return(fn(x+h)-fn(x-h))/(2*h)}
function sample(fn:(x:number)=>number,min:number,max:number,count:number){return Array.from({length:count},(_,index)=>{const x=min+index/(count-1)*(max-min);return{x,y:fn(x)}})}
function graphPath(points:Array<{x:number;y:number}>,sx:(value:number)=>number,sy:(value:number)=>number){return points.map((point,index)=>`${index?"L":"M"}${sx(point.x).toFixed(2)},${sy(point.y).toFixed(2)}`).join(" ")}
function numberParam(value:string|null,fallback:number){const parsed=Number(value);return value!==null&&Number.isFinite(parsed)?parsed:fallback} function clamp(value:number,min:number,max:number){return Math.min(max,Math.max(min,value))} function round(value:number,digits:number){const factor=10**digits;return Math.round(value*factor)/factor} function tidy(value:number){return Number.isFinite(value)?Number(value.toFixed(2)).toString():"--"} function format(value:number,digits:number){return Number.isFinite(value)?value.toFixed(digits):"--"}

import { useStudioState } from "../studios/phase1/StudioModelProvider";
import {
  Calculator,
  CheckCircle2,
  Grid3X3,
  Lightbulb,
  Minus,
  Move,
  Pause,
  Play,
  Plus,
  RotateCcw,
  Table2,
  Target,
  TrendingUp,
  ZoomIn,
  ZoomOut,
} from "lucide-react";
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { useSearchParams } from "react-router-dom";
import MathExpression from "../components/ui/MathExpression";
import { compileFunctionExpression } from "../utils/functionParser";
import "./CalculusDerivativesStudio.css";

export type DerivativeMode =
  "tangent" | "rules" | "chain" | "implicit" | "higher" | "linearization";
type BottomView = "graph" | "table" | "numerical" | "practice" | "insights";
type Viewport = { xMin: number; xMax: number; yMin: number; yMax: number };
type ModeConfig = {
  title: string;
  expression: string;
  derivative: string;
  secondDerivative: string;
  fn: (x: number) => number;
  df: (x: number) => number;
  d2f: (x: number) => number;
  range: Viewport;
  explanation: string;
  formula: string;
};

const modeConfigs: Record<DerivativeMode, ModeConfig> = {
  tangent: {
    title: "Tangent from secants",
    expression: "x^2",
    derivative: "2x",
    secondDerivative: "2",
    fn: (x) => x * x,
    df: (x) => 2 * x,
    d2f: () => 2,
    range: { xMin: -3.2, xMax: 3.4, yMin: -2.2, yMax: 8.8 },
    explanation:
      "As h approaches zero, the secant line approaches the tangent line and the difference quotient approaches f'(a).",
    formula: "f'(a)=\\lim_{h\\to0}\\frac{f(a+h)-f(a)}{h}",
  },
  rules: {
    title: "Derivative rules",
    expression: "x^4-3*x^2+2*x",
    derivative: "4x^3-6x+2",
    secondDerivative: "12x^2-6",
    fn: (x) => x ** 4 - 3 * x * x + 2 * x,
    df: (x) => 4 * x ** 3 - 6 * x + 2,
    d2f: (x) => 12 * x * x - 6,
    range: { xMin: -2.3, xMax: 2.5, yMin: -6, yMax: 10 },
    explanation:
      "The power, sum, and constant-multiple rules differentiate each polynomial term independently.",
    formula: "\\frac{d}{dx}x^n=nx^{n-1}",
  },
  chain: {
    title: "Chain rule",
    expression: "sin(x^2)",
    derivative: "2x\\cos(x^2)",
    secondDerivative: "2\\cos(x^2)-4x^2\\sin(x^2)",
    fn: (x) => Math.sin(x * x),
    df: (x) => 2 * x * Math.cos(x * x),
    d2f: (x) => 2 * Math.cos(x * x) - 4 * x * x * Math.sin(x * x),
    range: { xMin: -3.2, xMax: 3.2, yMin: -4, yMax: 4 },
    explanation:
      "Differentiate the outer function, keep the inside, then multiply by the inner derivative.",
    formula: "\\frac{d}{dx}f(g(x))=f'(g(x))g'(x)",
  },
  implicit: {
    title: "Implicit differentiation",
    expression: "sqrt(25-x^2)",
    derivative: "-x/\\sqrt{25-x^2}",
    secondDerivative: "-25/(25-x^2)^{3/2}",
    fn: (x) => Math.sqrt(Math.max(0, 25 - x * x)),
    df: (x) => -x / Math.sqrt(Math.max(0.0001, 25 - x * x)),
    d2f: (x) => -25 / Math.max(0.0001, 25 - x * x) ** 1.5,
    range: { xMin: -5.5, xMax: 5.5, yMin: -1, yMax: 6 },
    explanation:
      "Differentiate both sides of x²+y²=25 and solve 2x+2yy'=0 for y'.",
    formula: "x^2+y^2=25\\Rightarrow y'=-x/y",
  },
  higher: {
    title: "Higher derivatives",
    expression: "sin(x)",
    derivative: "\\cos x",
    secondDerivative: "-\\sin x",
    fn: Math.sin,
    df: Math.cos,
    d2f: (x) => -Math.sin(x),
    range: { xMin: -6.4, xMax: 6.4, yMin: -2, yMax: 2 },
    explanation:
      "Repeated differentiation reveals rate, concavity, and the four-step derivative cycle of sine.",
    formula: "f^{(n)}(x)=\\frac{d^n f}{dx^n}",
  },
  linearization: {
    title: "Linearization",
    expression: "exp(x)",
    derivative: "e^x",
    secondDerivative: "e^x",
    fn: Math.exp,
    df: Math.exp,
    d2f: Math.exp,
    range: { xMin: -3, xMax: 3, yMin: -2, yMax: 9 },
    explanation:
      "The tangent line L(x)=f(a)+f'(a)(x-a) is the best local linear approximation near a.",
    formula: "L(x)=f(a)+f'(a)(x-a)",
  },
};

const bottomTabs: Array<{
  id: BottomView;
  label: string;
  icon: typeof TrendingUp;
}> = [
  { id: "graph", label: "Graph", icon: TrendingUp },
  { id: "table", label: "Table", icon: Table2 },
  { id: "numerical", label: "Numerical Explorer", icon: Calculator },
  { id: "practice", label: "Practice", icon: Target },
  { id: "insights", label: "Insights", icon: Lightbulb },
];

export default function CalculusDerivativesStudio({ mode }: { mode: string }) {
  const [params, setParams] = useSearchParams();
  const activeMode = isDerivativeMode(mode) ? mode : "tangent";
  const config = modeConfigs[activeMode];
  const [expression, setExpression] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:expression",
    params.get("v_expression") || config.expression,
  );
  const [draft, setDraft] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:draft",
    params.get("v_expression") || config.expression,
  );
  const [a, setA] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:a", numberParam(params.get("v_a"), 1));
  const [h, setH] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:h", nonZero(numberParam(params.get("v_b"), 0.5)));
  const [samples, setSamples] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:samples",
    clamp(Math.round(numberParam(params.get("v_n"), 20)), 12, 120),
  );
  const [order, setOrder] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:order",
    clamp(Math.round(numberParam(params.get("v_order"), 2)), 1, 4),
  );
  const [showTangent, setShowTangent] = useState(true);
  const [showSecant, setShowSecant] = useState(true);
  const [showDerivative, setShowDerivative] = useState(true);
  const [showGrid, setShowGrid] = useState(true);
  const [playing, setPlaying] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:playing", false);
  const [speed, setSpeed] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:speed", 1);
  const [bottomView, setBottomView] = useStudioState<BottomView>("CalculusDerivativesStudio:CalculusDerivativesStudio:bottomView", "graph");
  const [viewport, setViewport] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:viewport", config.range);
  const [panMode, setPanMode] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:panMode", false);
  const [challengeNote, setChallengeNote] = useStudioState("CalculusDerivativesStudio:CalculusDerivativesStudio:challengeNote", "");
  const previousMode = useRef(activeMode);

  const compiled = useMemo(
    () => compileExpression(expression, config),
    [config, expression],
  );
  const analysis = useMemo(
    () => analyzeDerivative(compiled.fn, a, h),
    [a, compiled.fn, h],
  );
  const higherValue = useMemo(
    () => nthDerivative(compiled.fn, a, order),
    [a, compiled.fn, order],
  );

  useEffect(() => {
    const next = new URLSearchParams(params);
    next.set("v_a", trim(a));
    next.set("v_b", trim(h));
    next.set("v_n", String(samples));
    next.set("v_expression", expression);
    next.set("v_order", String(order));
    if (next.toString() !== params.toString())
      setParams(next, { replace: true });
  }, [a, expression, h, order, params, samples, setParams]);

  useEffect(() => {
    if (previousMode.current === activeMode) return;
    previousMode.current = activeMode;
    setExpression(config.expression);
    setDraft(config.expression);
    setA(activeMode === "implicit" ? 3 : 1);
    setH(0.5);
    setOrder(2);
    setViewport(config.range);
    setPlaying(false);
    setBottomView("graph");
  }, [activeMode, config]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => {
      setH((value) => {
        const next = Math.max(0.01, Math.abs(value) - 0.018 * speed);
        if (next <= 0.0101) setPlaying(false);
        return Math.sign(value || 1) * next;
      });
    }, 45);
    return () => window.clearInterval(timer);
  }, [playing, speed]);

  const applyExpression = () => {
    if (!compileExpression(draft, config).error) setExpression(draft);
  };
  const reset = () => {
    setExpression(config.expression);
    setDraft(config.expression);
    setA(activeMode === "implicit" ? 3 : 1);
    setH(0.5);
    setSamples(20);
    setOrder(2);
    setShowTangent(true);
    setShowSecant(true);
    setShowDerivative(true);
    setShowGrid(true);
    setPlaying(false);
    setSpeed(1);
    setViewport(config.range);
    setPanMode(false);
    setBottomView("graph");
  };
  const zoom = (factor: number) =>
    setViewport((view) => scaleViewport(view, factor));

  return (
    <section
      className="cds-studio"
      aria-label={`${config.title} derivative workspace`}
    >
      <div className="cds-workspace">
        <aside className="cds-panel cds-controls">
          <ControlSection title="Function">
            <div className="cds-expression">
              <span>f(x) =</span>
              <input
                aria-label="Function expression"
                value={draft}
                onChange={(event) => setDraft(event.target.value)}
                onKeyDown={(event) =>
                  event.key === "Enter" && applyExpression()
                }
              />
              <button
                type="button"
                onClick={applyExpression}
                disabled={Boolean(compileExpression(draft, config).error)}
                aria-label="Apply function"
              >
                f<sub>x</sub>
              </button>
            </div>
            {compiled.error && <p className="cds-error">{compiled.error}</p>}
          </ControlSection>

          <ControlSection title="Tangent point">
            <Stepper label="a" value={a} step={0.1} onChange={setA} />
          </ControlSection>
          <ControlSection
            title={
              activeMode === "linearization"
                ? "Approximation distance"
                : "Secant distance"
            }
          >
            <Stepper
              label="h"
              value={h}
              step={0.05}
              onChange={(value) => setH(nonZero(value))}
            />
          </ControlSection>
          {activeMode === "higher" && (
            <ControlSection title="Derivative order">
              <Stepper
                label="n"
                value={order}
                step={1}
                min={1}
                max={4}
                onChange={(value) => setOrder(clamp(Math.round(value), 1, 4))}
              />
            </ControlSection>
          )}
          <ControlSection title="Display">
            <Toggle
              label="Tangent line"
              color="orange"
              checked={showTangent}
              onChange={setShowTangent}
            />
            <Toggle
              label="Secant line"
              color="violet"
              checked={showSecant}
              onChange={setShowSecant}
            />
            <Toggle
              label={
                activeMode === "higher"
                  ? `Derivative f^(${order})(x)`
                  : "Derivative curve f'(x)"
              }
              color="cyan"
              checked={showDerivative}
              onChange={setShowDerivative}
            />
          </ControlSection>
          <ControlSection title="Animation">
            <Toggle
              label="Animate h → 0"
              color="cyan"
              checked={playing}
              onChange={setPlaying}
            />
            <div className="cds-animation">
              <button
                type="button"
                aria-label="Restart animation"
                onClick={() => {
                  setH(0.5);
                  setPlaying(false);
                }}
              >
                <RotateCcw />
              </button>
              <button
                type="button"
                aria-label={playing ? "Pause animation" : "Play animation"}
                onClick={() => setPlaying((value) => !value)}
              >
                {playing ? <Pause /> : <Play />}
              </button>
              <select
                aria-label="Animation speed"
                value={speed}
                onChange={(event) => setSpeed(Number(event.target.value))}
              >
                <option value="0.5">0.5x</option>
                <option value="1">1x</option>
                <option value="2">2x</option>
              </select>
            </div>
          </ControlSection>
          <div className="cds-tip">
            <Lightbulb />
            <p>
              {activeMode === "tangent" ? "Challenge: shrink h until the secant and tangent look identical." : activeMode === "rules" ? "Challenge: match the expression tree of f′ with the live slope at a." : activeMode === "chain" ? "Challenge: separate inner and outer slopes, then check their product equals f′(a)." : activeMode === "implicit" ? "Challenge: place a on the circle and confirm the tangent is perpendicular to the radius." : activeMode === "higher" ? "Challenge: overlay s, v, and a (f, f′, f″) and stop where velocity is zero." : "Challenge: shrink the error band between f and the linearization L(x)."}
            </p>
            <button type="button" onClick={() => setChallengeNote(analysis.difference < 0.08 ? "Challenge complete: secant and tangent slopes agree." : "Not yet. Shrink h until the live difference is under 0.08.")}>Check challenge</button>
            {challengeNote ? <p role="status">{challengeNote}</p> : null}
          </div>
        </aside>

        <main className="cds-panel cds-visual">
          <DerivativeGraph
            fn={compiled.fn}
            derivativeFn={
              activeMode === "higher"
                ? (x) => nthDerivative(compiled.fn, x, order)
                : compiled.df
            }
            expression={expression}
            derivativeLabel={
              activeMode === "higher"
                ? derivativeCycleLabel(expression, order)
                : compiled.derivativeLabel
            }
            a={a}
            h={h}
            analysis={analysis}
            viewport={viewport}
            samples={samples}
            showGrid={showGrid}
            showTangent={showTangent}
            showSecant={showSecant}
            showDerivative={showDerivative}
            panMode={panMode}
            onA={setA}
            onH={(value) => setH(nonZero(value))}
            onPan={setViewport}
          />
          <div className="cds-graph-tools">
            <button
              type="button"
              className={panMode ? "active" : ""}
              onClick={() => setPanMode((value) => !value)}
            >
              <Move /> Pan
            </button>
            <button type="button" onClick={() => zoom(0.82)}>
              <ZoomIn /> Zoom In
            </button>
            <button type="button" onClick={() => zoom(1.22)}>
              <ZoomOut /> Zoom Out
            </button>
            <button
              type="button"
              className={showGrid ? "active" : ""}
              onClick={() => setShowGrid((value) => !value)}
            >
              <Grid3X3 /> Grid
            </button>
            <button type="button" onClick={() => setViewport(config.range)}>
              <RotateCcw /> Reset View
            </button>
          </div>
        </main>

        <aside className="cds-panel cds-analysis">
          <AnalysisSection title="Live derivative">
            <MathExpression value={config.formula} display />
            <div className="cds-live-value">
              <MathExpression
                value={activeMode === "higher" ? `f^{(${order})}(a)` : "f'(a)"}
              />
              <span>=</span>
              <strong>
                {format(
                  activeMode === "higher" ? higherValue : analysis.tangentSlope,
                  4,
                )}
              </strong>
            </div>
            {activeMode === "chain" ? <p>Outer cosine slope times inner 2x at a.</p> : null}
            {activeMode === "implicit" ? <p>Circle constraint x² + y² = 25, so y′ = −x/y.</p> : null}
            {activeMode === "higher" ? <p>Compare f, f′, and the selected higher derivative on the graph.</p> : null}
          </AnalysisSection>
          <AnalysisSection title="Slope comparison">
            <div className="cds-comparison">
              <span>
                Secant slope <MathExpression value="m_{sec}" />
              </span>
              <strong>{format(analysis.secantSlope, 4)}</strong>
              <span>
                Tangent slope <MathExpression value="m_{tan}" />
              </span>
              <strong className="orange">
                {format(analysis.tangentSlope, 4)}
              </strong>
              <span>Difference</span>
              <strong className="red">{format(analysis.difference, 4)}</strong>
            </div>
          </AnalysisSection>
          <AnalysisSection
            title={
              activeMode === "linearization"
                ? "Linear approximation"
                : "Difference quotient"
            }
          >
            <MathExpression
              value={`\\frac{f(a+h)-f(a)}{h}=\\frac{${format(analysis.fb, 3)}-${format(analysis.fa, 3)}}{${trim(h)}}`}
              display
            />
            <div className="cds-quotient">
              = {format(analysis.secantSlope, 4)}
            </div>
          </AnalysisSection>
          <AnalysisSection title="Convergence (h → 0)">
            <div className="cds-convergence">
              <span
                style={{ left: `${convergencePercent(analysis.difference)}%` }}
              />
            </div>
            <div className="cds-convergence-copy">
              <MathExpression value="|m_{sec}-m_{tan}|" />
              <b>= {format(analysis.difference, 4)}</b>
              <strong>
                {analysis.difference < 0.05 ? "Converged" : "Converging"}
              </strong>
            </div>
          </AnalysisSection>
          <AnalysisSection title="Explanation">
            <div className="cds-explanation">
              <CheckCircle2 />
              <p>{config.explanation}</p>
            </div>
          </AnalysisSection>
        </aside>
      </div>

      <section className="cds-bottom">
        <nav role="tablist" aria-label="Derivative exploration views">
          {bottomTabs.map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              type="button"
              role="tab"
              aria-selected={bottomView === id}
              className={bottomView === id ? "active" : ""}
              onClick={() => setBottomView(id)}
            >
              <Icon />
              {label}
            </button>
          ))}
        </nav>
        {bottomView !== "graph" && (
          <BottomPanel
            view={bottomView}
            config={config}
            analysis={analysis}
            fn={compiled.fn}
            a={a}
            h={h}
            order={order}
            samples={samples}
            onSamples={setSamples}
          />
        )}
      </section>
      <button className="cds-reset" type="button" onClick={reset}>
        <RotateCcw /> Reset studio
      </button>
    </section>
  );
}

function DerivativeGraph({
  fn,
  derivativeFn,
  expression,
  derivativeLabel,
  a,
  h,
  analysis,
  viewport,
  samples,
  showGrid,
  showTangent,
  showSecant,
  showDerivative,
  panMode,
  onA,
  onH,
  onPan,
}: {
  fn: (x: number) => number;
  derivativeFn: (x: number) => number;
  expression: string;
  derivativeLabel: string;
  a: number;
  h: number;
  analysis: DerivativeAnalysis;
  viewport: Viewport;
  samples: number;
  showGrid: boolean;
  showTangent: boolean;
  showSecant: boolean;
  showDerivative: boolean;
  panMode: boolean;
  onA: (value: number) => void;
  onH: (value: number) => void;
  onPan: (value: Viewport) => void;
}) {
  const svgRef = useRef<SVGSVGElement>(null);
  const [dragging, setDragging] = useState<"a" | "b" | "pan" | null>(null);
  const panStart = useRef<{ x: number; y: number; view: Viewport } | null>(
    null,
  );
  const width = 850,
    height = 650,
    pad = 56;
  const sx = (x: number) =>
    pad +
    ((x - viewport.xMin) / (viewport.xMax - viewport.xMin)) * (width - pad * 2);
  const sy = (y: number) =>
    height -
    pad -
    ((y - viewport.yMin) / (viewport.yMax - viewport.yMin)) *
      (height - pad * 2);
  const pointFromEvent = (event: ReactPointerEvent<SVGSVGElement>) => {
    const box = svgRef.current?.getBoundingClientRect();
    if (!box) return { x: a, y: analysis.fa };
    return {
      x:
        viewport.xMin +
        ((event.clientX - box.left) / box.width) *
          (viewport.xMax - viewport.xMin),
      y:
        viewport.yMax -
        ((event.clientY - box.top) / box.height) *
          (viewport.yMax - viewport.yMin),
    };
  };
  const points = sampleFunction(
    fn,
    viewport.xMin,
    viewport.xMax,
    Math.max(160, samples * 18),
  );
  const derivativePoints = sampleFunction(
    derivativeFn,
    viewport.xMin,
    viewport.xMax,
    Math.max(160, samples * 14),
  );
  const tangent = (x: number) => analysis.fa + analysis.tangentSlope * (x - a);
  const secant = (x: number) => analysis.fa + analysis.secantSlope * (x - a);
  const move = (event: ReactPointerEvent<SVGSVGElement>) => {
    if (!dragging) return;
    const point = pointFromEvent(event);
    if (dragging === "a") onA(clamp(point.x, viewport.xMin, viewport.xMax));
    else if (dragging === "b") onH(clamp(point.x - a, -6, 6));
    else if (panStart.current) {
      const dx = point.x - panStart.current.x,
        dy = point.y - panStart.current.y,
        view = panStart.current.view;
      onPan({
        xMin: view.xMin - dx,
        xMax: view.xMax - dx,
        yMin: view.yMin - dy,
        yMax: view.yMax - dy,
      });
    }
  };
  return (
    <div className="cds-graph-wrap">
      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="Interactive derivative graph"
        className="is-interactive"
        onPointerMove={move}
        onPointerUp={() => setDragging(null)}
        onPointerLeave={() => setDragging(null)}
        onPointerDown={(event) => {
          const point = pointFromEvent(event);
          if (panMode) {
            panStart.current = { ...point, view: viewport };
            setDragging("pan");
            return;
          }
          onA(clamp(point.x, viewport.xMin, viewport.xMax));
          setDragging("a");
        }}
      >
        <rect width={width} height={height} rx="12" fill="#071d35" />
        {showGrid && (
          <GraphGrid
            viewport={viewport}
            sx={sx}
            sy={sy}
            width={width}
            height={height}
            pad={pad}
          />
        )}
        <line
          x1={pad}
          x2={width - pad}
          y1={sy(0)}
          y2={sy(0)}
          className="axis"
        />
        <line
          x1={sx(0)}
          x2={sx(0)}
          y1={pad}
          y2={height - pad}
          className="axis"
