        {showTangent && Number.isFinite(analysis.tangentSlope) && (
          <line
            x1={sx(viewport.xMin)}
            x2={sx(viewport.xMax)}
            y1={sy(tangent(viewport.xMin))}
            y2={sy(tangent(viewport.xMax))}
            className="tangent"
          />
        )}
        {showSecant && Number.isFinite(analysis.secantSlope) && (
          <line
            x1={sx(viewport.xMin)}
            x2={sx(viewport.xMax)}
            y1={sy(secant(viewport.xMin))}
            y2={sy(secant(viewport.xMax))}
            className="secant"
          />
        )}
        <line
          x1={sx(a)}
          x2={sx(a)}
          y1={sy(0)}
          y2={sy(analysis.fa)}
          className="guide"
        />
        <line
          x1={sx(a + h)}
          x2={sx(a + h)}
          y1={sy(0)}
          y2={sy(analysis.fb)}
          className="guide"
        />
        <g
          className="point-a"
          onPointerDown={(event) => {
            event.stopPropagation();
            setDragging("a");
          }}
        >
          <circle cx={sx(a)} cy={sy(analysis.fa)} r="9" />
          <text x={sx(a) + 14} y={sy(analysis.fa) + 24}>
