        </g>
        <g
          className="point-b"
          onPointerDown={(event) => {
            event.stopPropagation();
            setDragging("b");
          }}
        >
          <circle cx={sx(a + h)} cy={sy(analysis.fb)} r="9" />
          <text x={sx(a + h) + 14} y={sy(analysis.fb) + 7}>
            ({trim(a + h)}, {trim(analysis.fb)})
          </text>
        </g>
        <text x={width - 38} y={sy(0) - 9} className="axis-label">
          x
        </text>
        <text x={sx(0) + 9} y={34} className="axis-label">
          y
        </text>
      </svg>
      <div className="cds-legend">
        <span>
          <i className="cyan" />
          f(x) = {expression}
        </span>
        {showTangent && (
          <span>
            <i className="orange" />
            Tangent at x = {trim(a)}
          </span>
        )}
        {showSecant && (
          <span>
            <i className="violet" />
            Secant (h = {trim(h)})
          </span>
        )}
        {showDerivative && (
          <span>
            <i className="dashed" />
            {derivativeLabel}
          </span>
