          m<sub>sec</sub> = {format(analysis.secantSlope, 4)}
        </b>
      </div>
      <div className="cds-h-badge">
        <MathExpression value={`h=${trim(h)}\\quad(b=a+h=${trim(a + h)})`} />
      </div>
    </div>
  );
}

