export type DerivativeAnalysis = {
  fa: number;
  fb: number;
  tangentSlope: number;
  secantSlope: number;
  difference: number;
};
export function analyzeDerivative(
  fn: (x: number) => number,
  a: number,
  h: number,
): DerivativeAnalysis {
  const safeH = nonZero(h),
    fa = safe(fn, a),
    fb = safe(fn, a + safeH),
    tangentSlope = nthDerivative(fn, a, 1),
    secantSlope = (fb - fa) / safeH;
  return {
    fa,
    fb,
    tangentSlope,
    secantSlope,
    difference: Math.abs(secantSlope - tangentSlope),
  };
}
export function derivativeModeSnapshot(
  mode: DerivativeMode,
  a: number,
  h: number,
) {
  const config = modeConfigs[mode];
  return {
    ...analyzeDerivative(config.fn, a, h),
    expression: config.expression,
    derivative: config.derivative,
    secondDerivative: config.secondDerivative,
  };
}

function compileExpression(expression: string, config: ModeConfig) {
  try {
    const fn = compileFunctionExpression(expression);
    return {
      fn,
      df: (x: number) => nthDerivative(fn, x, 1),
      derivativeLabel:
        expression === config.expression
          ? `f'(x) = ${config.derivative}`
          : `f'(x) of ${expression}`,
      error: "",
    };
  } catch (error) {
    return {
      fn: config.fn,
      df: config.df,
      derivativeLabel: `f'(x) = ${config.derivative}`,
      error: error instanceof Error ? error.message : "Invalid function",
    };
  }
}
function nthDerivative(
  fn: (x: number) => number,
  x: number,
  order: number,
): number {
  if (order <= 0) return safe(fn, x);
  const h = order >= 3 ? 0.0025 : 0.0005;
  const lower = (value: number) =>
    order === 1 ? safe(fn, value) : nthDerivative(fn, value, order - 1);
  return (lower(x + h) - lower(x - h)) / (2 * h);
}
function derivativeCycleLabel(expression: string, order: number) {
  if (expression !== "sin(x)") return `f^(${order})(x)`;
  return ["sin x", "cos x", "-sin x", "-cos x", "sin x"][order];
}
function sampleFunction(
  fn: (x: number) => number,
  min: number,
  max: number,
  count: number,
) {
  return Array.from({ length: count }, (_, index) => {
    const x = min + (index / (count - 1)) * (max - min),
      y = safe(fn, x);
    return { x, y, ok: Number.isFinite(y) };
  });
}
function graphPath(
  points: Array<{ x: number; y: number; ok: boolean }>,
  sx: (x: number) => number,
  sy: (y: number) => number,
  view: Viewport,
) {
  let open = false;
  return points
    .map((point) => {
      if (!point.ok || point.y < view.yMin - 5 || point.y > view.yMax + 5) {
        open = false;
        return "";
      }
      const command = open ? "L" : "M";
      open = true;
      return `${command}${sx(point.x).toFixed(2)},${sy(point.y).toFixed(2)}`;
    })
    .join(" ");
}
function scaleViewport(view: Viewport, factor: number): Viewport {
  const x = (view.xMin + view.xMax) / 2,
    y = (view.yMin + view.yMax) / 2,
    width = (view.xMax - view.xMin) * factor,
    height = (view.yMax - view.yMin) * factor;
  return {
    xMin: x - width / 2,
    xMax: x + width / 2,
    yMin: y - height / 2,
    yMax: y + height / 2,
  };
}
function convergencePercent(difference: number) {
  return clamp(100 - Math.log10(1 + Math.max(0, difference) * 10) * 60, 4, 100);
}
function isDerivativeMode(value: string): value is DerivativeMode {
  return value in modeConfigs;
}
function safe(fn: (x: number) => number, x: number) {
  try {
    const value = fn(x);
    return Number.isFinite(value) ? value : NaN;
  } catch {
    return NaN;
  }
}
function numberParam(value: string | null, fallback: number) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}
function nonZero(value: number) {
  return Math.abs(value) < 0.0001 ? (value < 0 ? -0.01 : 0.01) : value;
}
function integerTicks(min: number, max: number) {
  const span = max - min,
    step = span > 14 ? 2 : span > 7 ? 1 : 0.5,
    values: number[] = [];
  for (let value = Math.ceil(min / step) * step; value <= max; value += step)
    values.push(Number(value.toFixed(4)));
  return values;
}
function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}
function trim(value: number) {
  return Number.isFinite(value) ? Number(value.toFixed(3)).toString() : "--";
}
function format(value: number, digits: number) {
  return Number.isFinite(value) ? value.toFixed(digits) : "--";
}

import { useStudioState } from "../studios/phase1/StudioModelProvider";
import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { Link } from "react-router-dom";
import {
  BookOpen,
  CircleHelp,
  Lightbulb,
  Pause,
  Play,
  RotateCcw,
  Search,
  Trophy,
} from "lucide-react";
import { compileTwoVariableExpression } from "../utils/functionParser";
import "./CalculusDifferentialEquationsStudio.css";

export type DeMode = "slope" | "ivp" | "separable" | "growth" | "euler" | "rk4";
type LearningTab = "Observe" | "Understand" | "Why" | "Try" | "Challenge";
type Tone = "plain" | "good" | "warn";

const MODES: DeMode[] = ["slope", "ivp", "separable", "growth", "euler", "rk4"];

const MODE_INFO: Record<DeMode, { title: string; formula: string; note: string; expression: string }> = {
  slope: {
    title: "Slope fields",
    formula: "y' = f(x, y)",
    note: "Each tick is the slope the solution must follow. Click the field to drop an initial condition.",
    expression: "x - y",
  },
  ivp: {
    title: "Initial value problem",
    formula: "y' = f(x, y),  y(x₀) = y₀",
    note: "One point (x₀, y₀) selects a unique solution curve from the family on the field.",
    expression: "x - y",
  },
  separable: {
    title: "Separable equations",
    formula: "dy/y = k dt  ⇒  y = y₀ e^{kt}",
    note: "Separate variables, integrate both sides, then apply y(0) = y₀.",
    expression: "k*y",
  },
  growth: {
    title: "Logistic growth",
    formula: "y' = r y (1 − y/K)",
    note: "Early growth is nearly exponential; the carrying capacity K flattens the curve.",
    expression: "r*y*(1-y/K)",
  },
  euler: {
    title: "Euler's method",
    formula: "yₙ₊₁ = yₙ + h f(xₙ, yₙ)",
    note: "Each step follows the tangent. Smaller h shortens the polygonal error versus the exact curve.",
    expression: "x - y",
  },
  rk4: {
    title: "Runge–Kutta 4",
    formula: "yₙ₊₁ = yₙ + (h/6)(k₁ + 2k₂ + 2k₃ + k₄)",
    note: "Four slope samples per step keep RK4 closer to the exact solution than Euler at the same h.",
    expression: "x - y",
  },
};

export default function CalculusDifferentialEquationsStudio({ mode }: { mode: string }) {
  const active = isDeMode(mode) ? mode : "slope";
  const info = MODE_INFO[active];
  const [expression, setExpression] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:expression", info.expression);
  const [draft, setDraft] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:draft", info.expression);
  const [x0, setX0] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:x0", 0);
  const [y0, setY0] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:y0", 1);
  const [h, setH] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:h", active === "euler" || active === "rk4" ? 0.25 : 0.2);
  const [k, setK] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:k", 0.6);
  const [rate, setRate] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:rate", 0.8);
  const [capacity, setCapacity] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:capacity", 10);
  const [time, setTime] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:time", active === "growth" ? 4 : 3);
  const [target, setTarget] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:target", 2);
  const [showGrid, setShowGrid] = useState(true);
  const [playing, setPlaying] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:playing", false);
  const [speed, setSpeed] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:speed", 1);
  const [learning, setLearning] = useStudioState<LearningTab>("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:learning", "Observe");
  const [challengeNote, setChallengeNote] = useStudioState("CalculusDifferentialEquationsStudio:CalculusDifferentialEquationsStudio:challengeNote", "");
  const previousMode = useRef(active);

  useEffect(() => {
    if (previousMode.current === active) return;
    previousMode.current = active;
    const next = MODE_INFO[active];
    setExpression(next.expression);
    setDraft(next.expression);
    setX0(0);
    setY0(1);
    setH(active === "euler" || active === "rk4" ? 0.25 : 0.2);
    setK(0.6);
    setRate(0.8);
    setCapacity(10);
    setTime(active === "growth" ? 4 : 3);
    setTarget(2);
    setPlaying(false);
    setLearning("Observe");
  }, [active]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => {
      if (active === "separable" || active === "growth") {
        setTime((value) => (value >= (active === "growth" ? 10 : 6) ? 0.2 : Number((value + 0.08 * speed).toFixed(2))));
      } else if (active === "euler" || active === "rk4") {
        setH((value) => (value <= 0.06 ? 0.5 : Number((value - 0.02 * speed).toFixed(2))));
      } else {
        setX0((value) => (value >= 3 ? -3 : Number((value + 0.05 * speed).toFixed(2))));
      }
    }, 90);
    return () => window.clearInterval(timer);
  }, [active, playing, speed]);

  const compiled = useMemo(() => compileField(expression), [expression]);
  const draftField = useMemo(() => compileField(draft), [draft]);
  const field = useMemo(() => {
    if (active === "separable") return (_x: number, y: number) => k * y;
    if (active === "growth") return (_x: number, y: number) => rate * y * (1 - y / Math.max(0.2, capacity));
    return compiled.fn;
  }, [active, capacity, compiled.fn, k, rate]);

  const analysis = useMemo(
    () => analyze(active, field, x0, y0, h, k, rate, capacity, time, target),
    [active, capacity, field, h, k, rate, target, time, x0, y0],
  );

  const plot = () => {
    if (!draftField.error) setExpression(draft);
  };

  const reset = () => {
    const next = MODE_INFO[active];
    setExpression(next.expression);
    setDraft(next.expression);
    setX0(0);
    setY0(1);
    setH(active === "euler" || active === "rk4" ? 0.25 : 0.2);
    setK(0.6);
    setRate(0.8);
    setCapacity(10);
    setTime(active === "growth" ? 4 : 3);
    setTarget(2);
    setPlaying(false);
    setShowGrid(true);
  };

  const onLearningKey = (event: KeyboardEvent<HTMLElement>) => {
    const tabs: LearningTab[] = ["Observe", "Understand", "Why", "Try", "Challenge"];
    const index = tabs.indexOf(learning);
    if (event.key === "ArrowRight") setLearning(tabs[(index + 1) % tabs.length]);
    if (event.key === "ArrowLeft") setLearning(tabs[(index - 1 + tabs.length) % tabs.length]);
  };

  return (
    <div className="de-studio" data-testid="de-studio" data-de-mode={active} data-lab-mode={active} data-mode-canvas={active}>
      <div className="de-workspace">
        <aside className="de-panel de-controls">
          <h2><span>1</span>{info.title}</h2>
          <p className="de-note">{info.note}</p>
          <div className="de-formula">
            <span>Key relationship</span>
            <strong>{info.formula}</strong>
          </div>
          {active === "separable" || active === "growth" ? (
            <p className="de-feedback" data-testid="de-equation">{active === "separable" ? `y' = ${fmt(k, 2)} y` : `y' = ${fmt(rate, 2)} y (1 − y/${fmt(capacity, 1)})`}</p>
          ) : (
            <label>
              Differential equation
              <input
                aria-label="Differential equation"
                value={draft}
                onChange={(event) => setDraft(event.target.value)}
                onKeyDown={(event) => event.key === "Enter" && plot()}
              />
            </label>
          )}
          {draftField.error && active !== "separable" && active !== "growth" ? <p className="de-error">{draftField.error}</p> : null}
          {active !== "separable" && active !== "growth" ? <p className="de-feedback" data-testid="de-equation">dy/dx = {expression}</p> : null}
          {active === "slope" || active === "ivp" ? <p className="de-hint">Click the slope field to set (x₀, y₀).</p> : null}
          <p className="de-hint"><Link to="/differential-equations">Open the full Differential Equations Studio.</Link></p>
          {active === "separable" ? (
            <>
              <Slider label="Rate k" value={k} min={-1.5} max={1.5} step={0.05} onChange={setK} />
              <Slider label="Initial y₀" value={y0} min={0.2} max={4} step={0.05} onChange={setY0} />
              <Slider label="Time t" value={time} min={0} max={6} step={0.05} onChange={setTime} />
            </>
          ) : null}
          {active === "growth" ? (
            <>
              <Slider label="Growth rate r" value={rate} min={0.1} max={2} step={0.05} onChange={setRate} />
              <Slider label="Capacity K" value={capacity} min={3} max={20} step={0.5} onChange={setCapacity} />
              <Slider label="Initial y₀" value={y0} min={0.2} max={Math.max(0.4, capacity - 0.2)} step={0.05} onChange={setY0} />
              <Slider label="Time t" value={time} min={0} max={10} step={0.05} onChange={setTime} />
            </>
          ) : null}
          {active === "slope" || active === "ivp" || active === "euler" || active === "rk4" ? (
            <>
              <Slider label="Initial x₀" value={x0} min={-4} max={4} step={0.05} onChange={setX0} />
              <Slider label="Initial y₀" value={y0} min={-3} max={4} step={0.05} onChange={setY0} />
              <Slider label="Step size h" value={h} min={0.05} max={0.8} step={0.01} onChange={setH} />
