    title: "Antiderivative family",
    eyebrow: "Reverse differentiation",
    explanation: "Every vertical shift has the same derivative. Move C to inspect the family F(x) + C.",
  },
  definite: {
    title: "Definite integral",
    eyebrow: "Signed accumulation",
    explanation: "The shaded region records signed accumulation between the selected bounds.",
  },
  ftc: {
    title: "Fundamental Theorem of Calculus",
    eyebrow: "Accumulation and rate",
    explanation: "Move x to build F(x) from the lower bound. The slope of F at x matches f(x).",
  },
  riemann: {
    title: "Riemann sum explorer",
    eyebrow: "From slices to area",
    explanation: "Compare sampling methods and increase n to watch the approximation converge.",
  },
  numerical: {
    title: "Numerical method comparison",
    eyebrow: "Accuracy at a glance",
    explanation: "All five methods use the same function, interval, and partition count for a fair comparison.",
  },
};

export default function CalculusIntegrationStudio({ mode }: Props) {
  const [params, setParams] = useSearchParams();
  const initialMethod = parseMethod(params.get("v_method"));
  const [expression, setExpression] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:expression", params.get("v_function") || "x^2");
  const [draft, setDraft] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:draft", params.get("v_function") || "x^2");
  const [lower, setLower] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:lower", numberParam(params.get("v_lower_a"), -2));
  const [upper, setUpper] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:upper", numberParam(params.get("v_upper_b"), 3));
  const [partitions, setPartitions] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:partitions", enforcePartitionCount(numberParam(params.get("v_partitions_n"), 12), initialMethod));
  const [method, setMethod] = useStudioState<IntegrationMethod>("CalculusIntegrationStudio:CalculusIntegrationStudio:method", initialMethod);
  const [constant, setConstant] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:constant", 0);
  const [probe, setProbe] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:probe", numberParam(params.get("v_probe_x"), 1));
  const [playing, setPlaying] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:playing", false);
  const [speed, setSpeed] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:speed", 1);
  const [showGrid, setShowGrid] = useState(true);
  const [expanded, setExpanded] = useStudioState("CalculusIntegrationStudio:CalculusIntegrationStudio:expanded", false);
  const [learning, setLearning] = useStudioState<LearningMode>("CalculusIntegrationStudio:CalculusIntegrationStudio:learning", "Observe");

  const compiled = useMemo(() => {
    try { return { fn: compileFunctionExpression(expression), error: "" }; }
    catch (error) { return { fn: null, error: error instanceof Error ? error.message : "Invalid function" }; }
  }, [expression]);
  const draftError = useMemo(() => {
    try { compileFunctionExpression(draft); return ""; }
    catch (error) { return error instanceof Error ? error.message : "Invalid function"; }
  }, [draft]);
  const intervalValid = lower < upper;
  const result = useMemo(() => safeResult(compiled.fn, lower, upper, partitions, method), [compiled.fn, lower, upper, partitions, method]);
  const comparison = useMemo(() => methods.map((item) => ({ ...item, result: safeResult(compiled.fn, lower, upper, partitions, item.id) })), [compiled.fn, lower, upper, partitions]);
  const info = modeCopy[mode] ?? modeCopy.definite;

  useEffect(() => {
    setPlaying(false);
    setLearning("Observe");
  }, [mode]);

  useEffect(() => {
    if (!expanded) return;
    const close = (event: KeyboardEvent) => event.key === "Escape" && setExpanded(false);
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [expanded]);

  useEffect(() => {
    const next = new URLSearchParams(params);
    next.set("mode", mode);
    next.set("v_function", expression);
    next.set("v_lower_a", tidy(lower));
    next.set("v_upper_b", tidy(upper));
    next.set("v_partitions_n", String(partitions));
    next.set("v_method", method);
    next.set("v_probe_x", tidy(probe));
    if (next.toString() !== params.toString()) setParams(next, { replace: true });
  }, [expression, lower, method, mode, params, partitions, probe, setParams, upper]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => {
      if (mode === "ftc") {
        setProbe((value) => value >= upper ? lower : Number(Math.min(upper, value + 0.04 * speed).toFixed(2)));
      } else if (mode === "antiderivative") {
        setConstant((value) => value >= 3 ? -3 : Number((value + 0.05 * speed).toFixed(2)));
      } else {
        setPartitions((value) => enforcePartitionCount(value >= 80 ? 2 : value + Math.max(1, Math.round(speed)), method));
      }
    }, 90);
    return () => window.clearInterval(timer);
  }, [lower, method, mode, playing, speed, upper]);

  const changeMethod = (next: IntegrationMethod) => {
    setMethod(next);
    setPartitions((value) => enforcePartitionCount(value, next));
  };
  const changePartitions = (value: number) => setPartitions(enforcePartitionCount(value, method));
  const plot = () => {
    if (!draftError) setExpression(draft);
  };
  const reset = () => {
    setExpression("x^2");
    setDraft("x^2");
    setLower(-2);
    setUpper(3);
    setPartitions(12);
    setMethod("midpoint");
    setConstant(0);
    setProbe(1);
    setPlaying(false);
    setSpeed(1);
    setShowGrid(true);
  };

  return (
    <div className="ci-studio" data-mode={mode} data-testid="calculus-integration-studio">
      <div className="ci-workspace">
        <aside className="ci-panel ci-controls" aria-label="Integration controls">
          <h2>Build the integral</h2>
          <label className="ci-function"><span>f(x) =</span><input aria-label="Function f of x" value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => event.key === "Enter" && plot()} /><button type="button" onClick={plot} disabled={Boolean(draftError)} aria-label="Plot function" title="Plot function"><Sigma /></button></label>
          {draftError && <p className="ci-error">{draftError}</p>}

          {mode === "antiderivative" ? (
            <RangeControl label="Constant C" value={constant} min={-4} max={4} step={0.1} onChange={setConstant} />
          ) : (
            <section className="ci-section">
              <h3>Bounds</h3>
              <div className="ci-bound-row">
                <label><span>a (lower)</span><input aria-label="Lower bound a" type="number" value={lower} step="0.25" onChange={(event) => setLower(Number(event.target.value))} /></label>
                <label><span>b (upper)</span><input aria-label="Upper bound b" type="number" value={upper} step="0.25" onChange={(event) => setUpper(Number(event.target.value))} /></label>
              </div>
              {!intervalValid && <p className="ci-error">Choose a lower bound smaller than the upper bound.</p>}
            </section>
          )}

          {mode === "ftc" && <RangeControl label="Accumulation point x" value={probe} min={lower} max={upper} step={0.05} onChange={setProbe} />}
          {mode !== "antiderivative" && mode !== "ftc" && <RangeControl label="Partitions (n)" value={partitions} min={2} max={100} step={1} onChange={changePartitions} integer />}

          {mode !== "antiderivative" && mode !== "numerical" && (
            <section className="ci-section">
              <h3>Method</h3>
              <div className="ci-methods">
                {methods.map((item) => <button type="button" key={item.id} className={method === item.id ? "active" : ""} aria-pressed={method === item.id} onClick={() => changeMethod(item.id)}>{item.label}</button>)}
              </div>
            </section>
          )}

          <label className="ci-toggle"><input type="checkbox" checked={showGrid} onChange={(event) => setShowGrid(event.target.checked)} /><span>Show graph grid</span></label>
          <div className="ci-player">
            <button type="button" className="primary" onClick={() => setPlaying((value) => !value)}>{playing ? <Pause /> : <Play />}<span>{playing ? "Pause" : "Animate"}</span></button>
            <select aria-label="Animation speed" value={speed} onChange={(event) => setSpeed(Number(event.target.value))}><option value={0.5}>0.5x</option><option value={1}>1x</option><option value={2}>2x</option></select>
            <button type="button" onClick={reset}><RotateCcw /><span>Reset</span></button>
          </div>
        </aside>

        <section className={`ci-panel ci-visual-panel ${expanded ? "is-expanded" : ""}`}>
          <header>
            <div><span>{info.eyebrow}</span><h2>{info.title}</h2></div>
            <div className="ci-visual-actions"><button type="button" className={showGrid ? "active" : ""} onClick={() => setShowGrid((value) => !value)} title="Toggle grid"><Grid3X3 /></button><button type="button" className={expanded ? "active" : ""} aria-pressed={expanded} onClick={() => setExpanded((value) => !value)} title={expanded ? "Exit full screen" : "Full screen"}><Expand /></button></div>
          </header>
          <IntegrationVisual mode={mode} fn={compiled.fn} result={result} lower={lower} upper={upper} probe={probe} constant={constant} showGrid={showGrid} onSlice={() => changePartitions(Math.min(100, partitions + 1))} />
          <p className="ci-visual-note">{info.explanation}</p>
        </section>

        <aside className="ci-panel ci-results" aria-live="polite">
          <h2><BarChart3 /> Live results</h2>
          {mode === "antiderivative" ? <AntiderivativeResults expression={expression} constant={constant} /> : mode === "ftc" ? <FtcResults fn={compiled.fn} lower={lower} probe={probe} /> : mode === "numerical" ? <NumericalResults comparison={comparison} reference={result?.reference ?? null} /> : <DefiniteResults result={result} method={method} />}
          <section className="ci-theory">
            <h3><CheckCircle2 /> {mode === "riemann" ? "Convergence check" : "Fundamental idea"}</h3>
            <p>{result ? result.absoluteError < 0.01 ? "The approximation is already close to the high-precision reference." : "Increase the partition count to reduce the discretization error." : compiled.error || "Enter a valid interval and function."}</p>
          </section>
        </aside>
      </div>
      <LearningBar active={learning} onChange={setLearning} mode={mode} result={result} />
    </div>
  );
}

function RangeControl({ label, value, min, max, step, onChange, integer = false }: { label: string; value: number; min: number; max: number; step: number; onChange: (value: number) => void; integer?: boolean }) {
  const update = (value: number) => onChange(integer ? Math.round(value) : value);
  return <label className="ci-range"><span>{label}<b>{integer ? Math.round(value) : tidy(value)}</b></span><div><button type="button" onClick={() => update(Math.max(min, value - step))} aria-label={`Decrease ${label}`}><Minus /></button><input aria-label={label} type="range" min={min} max={max} step={step} value={Math.min(max, Math.max(min, value))} onChange={(event) => update(Number(event.target.value))} /><button type="button" onClick={() => update(Math.min(max, value + step))} aria-label={`Increase ${label}`}><Plus /></button></div></label>;
}

function IntegrationVisual({ mode, fn, result, lower, upper, probe, constant, showGrid, onSlice }: { mode: string; fn: ((x: number) => number) | null; result: IntegrationResult | null; lower: number; upper: number; probe: number; constant: number; showGrid: boolean; onSlice?: () => void }) {
  if (mode === "ftc") {
    return (
      <div className="ci-ftc-split">
        <GraphPane title="f(x)" fn={fn} lower={lower} upper={upper} probe={probe} showGrid={showGrid} accumulation={false} />
        <GraphPane title="F(x)=∫_a^x f" fn={fn} lower={lower} upper={upper} probe={probe} showGrid={showGrid} accumulation />
      </div>
    );
  }
  const width = 860, height = mode === "definite" || mode === "riemann" ? 360 : 530, pad = 52, xMin = -4, xMax = 5, yMin = -3, yMax = 12;
  const sx = (x: number) => pad + (x - xMin) / (xMax - xMin) * (width - pad * 2);
  const sy = (y: number) => height - pad - (y - yMin) / (yMax - yMin) * (height - pad * 2);
  const curve = fn ? sample(fn, xMin, xMax, 440) : [];
  const activeUpper = mode === "ftc" ? Math.min(upper, Math.max(lower, probe)) : upper;
  const showSlices = mode === "definite" || mode === "riemann";
  const family = mode === "antiderivative" && fn ? [-2, 0, 2].map((shift) => sample((x) => primitive(fn, x) + constant + shift, xMin, xMax, 260)) : [];
  const accumulation = mode === "ftc" && fn ? sample((x) => x <= lower ? 0 : safeIntegral(fn, lower, Math.min(x, upper), 240), lower + 0.001, upper, 170) : [];
  const mainGraph = (
    <svg className="ci-graph" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${modeCopy[mode]?.title ?? "Integration"} graph`}>
      <rect width={width} height={height} rx="10" fill="#071d35" />
      {showGrid && <GraphGrid width={width} height={height} pad={pad} />}
      <line className="axis" x1={pad} x2={width - pad} y1={sy(0)} y2={sy(0)} /><line className="axis" x1={sx(0)} x2={sx(0)} y1={pad} y2={height - pad} />
      {fn && mode !== "antiderivative" && intervalPath(fn, lower, activeUpper, sx, sy)}
      {showSlices && result?.partitions.map((part) => <rect key={part.index} x={sx(part.x0)} y={sy(Math.max(0, part.sampleY))} width={Math.max(1, sx(part.x1) - sx(part.x0) - 1)} height={Math.abs(sy(part.sampleY) - sy(0))} className="slice" onClick={onSlice} />)}
      {mode === "antiderivative" ? family.map((points, index) => <path key={index} d={path(points, sx, sy, yMin, yMax)} className={index === 1 ? "family active" : "family"} />) : <path d={path(curve, sx, sy, yMin, yMax)} className="curve" />}
      {mode === "ftc" && <><path d={path(accumulation, sx, sy, yMin, yMax)} className="accumulation" /><line x1={sx(activeUpper)} x2={sx(activeUpper)} y1={pad} y2={height - pad} className="probe" /><circle cx={sx(activeUpper)} cy={sy(fn ? safeValue(fn, activeUpper) : 0)} r="7" className="probe-dot" /></>}
      {mode !== "antiderivative" && <><line x1={sx(lower)} x2={sx(lower)} y1={pad} y2={height - pad} className="bound lower" /><line x1={sx(activeUpper)} x2={sx(activeUpper)} y1={pad} y2={height - pad} className="bound upper" /><text x={sx(lower) - 20} y={sy(0) + 30}>a = {tidy(lower)}</text><text x={sx(activeUpper) - 18} y={sy(0) + 30}>{mode === "ftc" ? "x" : "b"} = {tidy(activeUpper)}</text></>}
      <text x="68" y="38" className="formula">{mode === "antiderivative" ? `F(x) + C, C = ${tidy(constant)}` : "f(x) and accumulated area"}</text>
    </svg>
  );
  if (mode === "definite" || mode === "riemann") {
    return (
      <div className="ci-definite-split">
        {mainGraph}
        <GraphPane title="Accumulation function F(x)" fn={fn} lower={lower} upper={upper} probe={upper} showGrid={showGrid} accumulation />
      </div>
    );
  }
  return mainGraph;
}

function GraphPane({ title, fn, lower, upper, probe, showGrid, accumulation }: { title: string; fn: ((x: number) => number) | null; lower: number; upper: number; probe: number; showGrid: boolean; accumulation: boolean }) {
  const width = 860, height = 260, pad = 42, xMin = -4, xMax = 5, yMin = -3, yMax = 12;
  const sx = (x: number) => pad + (x - xMin) / (xMax - xMin) * (width - pad * 2);
  const sy = (y: number) => height - pad - (y - yMin) / (yMax - yMin) * (height - pad * 2);
  const activeUpper = Math.min(upper, Math.max(lower, probe));
  const curve = fn ? sample(accumulation ? (x) => x <= lower ? 0 : safeIntegral(fn, lower, Math.min(x, upper), 160) : fn, xMin, xMax, 280) : [];
  return <svg className="ci-graph" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={title}>
    <rect width={width} height={height} rx="10" fill="#071d35" />
    {showGrid && <GraphGrid width={width} height={height} pad={pad} />}
    <line className="axis" x1={pad} x2={width - pad} y1={sy(0)} y2={sy(0)} /><line className="axis" x1={sx(0)} x2={sx(0)} y1={pad} y2={height - pad} />
    {fn && !accumulation && intervalPath(fn, lower, activeUpper, sx, sy)}
    <path d={path(curve, sx, sy, yMin, yMax)} className={accumulation ? "accumulation" : "curve"} />
    <line x1={sx(activeUpper)} x2={sx(activeUpper)} y1={pad} y2={height - pad} className="probe" />
    <text x="68" y="32" className="formula">{title}</text>
  </svg>;
}

function DefiniteResults({ result, method }: { result: IntegrationResult | null; method: IntegrationMethod }) {
  return <>{result ? <><ResultCard label={`${labelMethod(method)} approximation`} value={format(result.approximation, 4)} tone="amber" /><ResultCard label="High-precision integral" value={format(result.reference, 4)} tone="green" /><div className="ci-stat-grid"><ResultCard label="Absolute error" value={format(result.absoluteError, 5)} tone={result.absoluteError < 0.01 ? "green" : "red"} /><ResultCard label="Relative error" value={`${format(result.relativeError, 3)}%`} /></div><div className="ci-area-list"><p><span>Positive area</span><b>{format(result.positiveArea, 4)}</b></p><p><span>Negative area</span><b>{format(result.negativeArea, 4)}</b></p><p><span>Net area</span><b>{format(result.signedArea, 4)}</b></p></div></> : <EmptyResults />}</>;
}

function AntiderivativeResults({ expression, constant }: { expression: string; constant: number }) {
  const familiar = expression.replace(/\s/g, "") === "x^2";
  return <><ResultCard label="Integrand" value={`f(x) = ${expression}`} /><ResultCard label="One antiderivative" value={familiar ? "F(x) = x^3 / 3" : "F'(x) = f(x)"} tone="green" /><ResultCard label="Current family member" value={familiar ? `x^3 / 3 ${constant < 0 ? "-" : "+"} ${tidy(Math.abs(constant))}` : `F(x) + ${tidy(constant)}`} tone="violet" /><p className="ci-callout">Changing C shifts the graph vertically without changing its derivative.</p></>;
}

function FtcResults({ fn, lower, probe }: { fn: ((x: number) => number) | null; lower: number; probe: number }) {
  if (!fn || probe <= lower) return <EmptyResults />;
  const accumulation = safeIntegral(fn, lower, probe, 800);
  const derivative = safeValue(fn, probe);
  if (!Number.isFinite(accumulation) || !Number.isFinite(derivative)) return <EmptyResults />;
  return <><ResultCard label={`F(${tidy(probe)}) = integral from ${tidy(lower)} to ${tidy(probe)}`} value={format(accumulation, 5)} tone="green" /><ResultCard label="F'(x)" value={format(derivative, 5)} tone="violet" /><ResultCard label="f(x)" value={format(derivative, 5)} tone="amber" /><p className="ci-callout success">F'(x) and f(x) agree at the selected point.</p></>;
}

function NumericalResults({ comparison, reference }: { comparison: Array<{ id: IntegrationMethod; label: string; result: IntegrationResult | null }>; reference: number | null }) {
  return <><ResultCard label="Reference value" value={reference === null ? "Unavailable" : format(reference, 6)} tone="green" /><div className="ci-comparison">{comparison.map((item) => <div key={item.id}><span>{item.label}</span><b>{item.result ? format(item.result.approximation, 5) : "--"}</b><small>{item.result ? `error ${format(item.result.absoluteError, 5)}` : "invalid"}</small></div>)}</div></>;
}

function ResultCard({ label, value, tone = "plain" }: { label: string; value: string; tone?: string }) { return <div className={`ci-result-card ${tone}`}><span>{label}</span><strong>{value}</strong></div>; }
function EmptyResults() { return <p className="ci-empty">Results appear when the function and interval are valid.</p>; }

function LearningBar({ active, onChange, mode, result }: { active: LearningMode; onChange: (value: LearningMode) => void; mode: string; result: IntegrationResult | null }) {
  const [challengeNote, setChallengeNote] = useStudioState("CalculusIntegrationStudio:LearningBar:challengeNote", "");
  const tabs: LearningMode[] = ["Observe", "Understand", "Why", "Try", "Challenge"];
  const copy: Record<LearningMode, string> = {
    Observe: modeCopy[mode]?.explanation ?? modeCopy.definite.explanation,
    Understand: "The integral combines many small signed contributions over an interval.",
    Why: "As slice width approaches zero, the numerical sum approaches the definite integral.",
    Try: "Change the function, bounds, method, and partition count. Every result uses the current state.",
    Challenge:
      mode === "antiderivative"
        ? "Challenge: slide C and confirm the derivative of every family member is still f."
        : mode === "ftc"
          ? "Challenge: move the accumulation point until F'(x) visibly matches f(x)."
          : mode === "riemann"
            ? "Challenge: raise n until left, right, mid, and trap agree to two decimals."
            : mode === "numerical"
              ? "Challenge: compare methods at the same n and pick the smallest error."
              : result
                ? `Challenge: make the signed-area error smaller than ${format(Math.max(result.absoluteError / 2, 0.00001), 5)}.`
                : "Challenge: choose a valid function and interval to begin.",
  };
  return <section className="ci-learning"><nav>{tabs.map((tab) => <button type="button" key={tab} className={active === tab ? "active" : ""} onClick={() => onChange(tab)}>{tab}</button>)}</nav><p>{copy[active]}</p><button type="button" className="primary" onClick={() => setChallengeNote(result && result.absoluteError < 0.05 ? "Challenge complete: the signed-area error is small enough." : "Not yet. Raise n or switch methods until the live error drops.")}>Check challenge</button>{challengeNote ? <p role="status">{challengeNote}</p> : null}</section>;
}

function GraphGrid({ width, height, pad }: { width: number; height: number; pad: number }) { return <g>{Array.from({ length: 10 }, (_, index) => <line key={`v-${index}`} x1={pad + index * ((width - pad * 2) / 9)} x2={pad + index * ((width - pad * 2) / 9)} y1={pad} y2={height - pad} className="grid" />)}{Array.from({ length: 8 }, (_, index) => <line key={`h-${index}`} x1={pad} x2={width - pad} y1={pad + index * ((height - pad * 2) / 7)} y2={pad + index * ((height - pad * 2) / 7)} className="grid" />)}</g>; }

function intervalPath(fn: (x: number) => number, lower: number, upper: number, sx: (value: number) => number, sy: (value: number) => number) {
  if (!(lower < upper)) return null;
  const points = sample(fn, lower, upper, 180);
  const d = points.map((point, index) => `${index ? "L" : "M"}${sx(point.x)},${sy(point.y)}`).join(" ");
  return <path d={`${d} L${sx(upper)},${sy(0)} L${sx(lower)},${sy(0)} Z`} className="area" />;
}

function sample(fn: (x: number) => number, min: number, max: number, count: number) { return Array.from({ length: count }, (_, index) => { const x = min + index / (count - 1) * (max - min); try { return { x, y: finite(fn(x)) }; } catch { return { x, y: NaN }; } }); }
function path(points: Array<{ x: number; y: number }>, sx: (value: number) => number, sy: (value: number) => number, yMin: number, yMax: number) { let open = false; return points.map((point) => { if (!Number.isFinite(point.y) || point.y < yMin - 2 || point.y > yMax + 2) { open = false; return ""; } const command = open ? "L" : "M"; open = true; return `${command}${sx(point.x).toFixed(2)},${sy(point.y).toFixed(2)}`; }).join(" "); }
function primitive(fn: (x: number) => number, x: number) { if (Math.abs(x) < 0.001) return 0; return x > 0 ? safeIntegral(fn, 0, x, 160) : -safeIntegral(fn, x, 0, 160); }
function safeIntegral(fn: (x: number) => number, lower: number, upper: number, slices: number) { try { return highPrecisionIntegral(fn, lower, upper, slices); } catch { return NaN; } }
function safeValue(fn: (x: number) => number, x: number) { try { return finite(fn(x)); } catch { return NaN; } }
function safeResult(fn: ((x: number) => number) | null, lower: number, upper: number, partitions: number, method: IntegrationMethod) { if (!fn || !(lower < upper)) return null; try { return calculateIntegration(fn, lower, upper, partitions, method); } catch { return null; } }
function parseMethod(value: string | null): IntegrationMethod { return value === "left" || value === "right" || value === "trapezoid" || value === "simpson" ? value : "midpoint"; }
function numberParam(value: string | null, fallback: number) { const parsed = Number(value); return value !== null && Number.isFinite(parsed) ? parsed : fallback; }
function finite(value: number) { return Number.isFinite(value) ? value : NaN; }
function format(value: number, digits: number) { return Number.isFinite(value) ? value.toFixed(digits) : "--"; }
function tidy(value: number) { return Number.isFinite(value) ? Number(value.toFixed(2)).toString() : "--"; }
function labelMethod(method: IntegrationMethod) { return methods.find((item) => item.id === method)?.label ?? method; }

import { useStudioState } from "../studios/phase1/StudioModelProvider";
import {
  ArrowLeft,
  ArrowRight,
  Check,
  ChevronLeft,
  ChevronRight,
  Expand,
  Lightbulb,
  RefreshCw,
  RotateCcw,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import MathExpression from "../components/ui/MathExpression";
import StudioGraphWidget from "../studios/phase1/StudioGraphWidget";
import "./CalculusIntegrationTechniquesStudio.css";

type Props = { mode: string };
export type TechniqueId =
  "substitution" | "parts" | "partial" | "trig" | "trig-sub" | "improper";
type TechniqueConfig = {
  title: string;
  problem: string;
  original: string;
  choiceTitle: string;
  choice: string;
  differential: string;
  transformed: string;
  evaluation: string;
  result: string;
  numeric: (lower: number, upper: number) => number;
  xCurve: (x: number) => number;
  uCurve: (u: number) => number;
  xLabel: string;
  uLabel: string;
  mapBound: (x: number) => number;
  parts: Array<{ formula: string; tone: "cyan" | "violet" }>;
  scaling: string;
  insight: string;
  defaults: [number, number];
};

const techniques: Record<TechniqueId, TechniqueConfig> = {
  substitution: {
    title: "Substitution",
    problem: "\\int_0^2 x\\sqrt{x^2+1}\\,dx",
    original: "I=\\int_0^2 x\\sqrt{x^2+1}\\,dx",
    choiceTitle: "Suggested substitution",
    choice: "u=x^2+1",
    differential: "du=2x\\,dx\\quad\\Rightarrow\\quad x\\,dx=\\frac12du",
    transformed: "I=\\frac12\\int_1^5 u^{1/2}\\,du",
    evaluation:
      "\\frac12\\left[\\frac23u^{3/2}\\right]_1^5=\\frac13(5\\sqrt5-1)",
    result: "3.3939",
    numeric: (lower, upper) =>
      (Math.pow(upper * upper + 1, 1.5) - Math.pow(lower * lower + 1, 1.5)) / 3,
    xCurve: (x) => x * Math.sqrt(x * x + 1),
    uCurve: (u) => 0.5 * Math.sqrt(Math.max(0, u)),
    xLabel: "y=x\\sqrt{x^2+1}",
    uLabel: "y=\\frac12\\sqrt{u}",
    mapBound: (x) => x * x + 1,
    parts: [
      { formula: "x", tone: "cyan" },
      { formula: "\\sqrt{x^2+1}", tone: "violet" },
    ],
    scaling: "du=2x\\,dx\\quad\\Rightarrow\\quad x\\,dx=\\frac12du",
    insight:
      "Substitution simplifies the integrand by changing variables. The bounds and differential are transformed together, preserving the integral value.",
    defaults: [0, 2],
  },
  parts: {
    title: "Integration by parts",
    problem: "\\int_0^2 xe^x\\,dx",
    original: "I=\\int_0^2 xe^x\\,dx",
    choiceTitle: "Choose the product split",
    choice: "u=x,\\quad dv=e^x\\,dx",
    differential: "du=dx,\\quad v=e^x",
    transformed: "I=[xe^x]_0^2-\\int_0^2e^x\\,dx",
    evaluation: "[e^x(x-1)]_0^2=e^2+1",
    result: "8.3891",
    numeric: (lower, upper) =>
      Math.exp(upper) * (upper - 1) - Math.exp(lower) * (lower - 1),
    xCurve: (x) => Math.max(0, x * Math.exp(x)),
    uCurve: (u) => Math.exp(u),
    xLabel: "y=xe^x",
    uLabel: "v=e^x",
    mapBound: (x) => x,
    parts: [
      { formula: "x", tone: "cyan" },
      { formula: "e^x", tone: "violet" },
    ],
    scaling: "\\int u\\,dv=uv-\\int v\\,du",
    insight:
      "Integration by parts reverses the product rule. Choose u to simplify when differentiated and dv to remain easy to integrate.",
    defaults: [0, 2],
  },
  partial: {
    title: "Partial fractions",
    problem: "\\int_2^4\\frac{dx}{x^2-1}",
    original: "I=\\int_2^4\\frac{dx}{(x-1)(x+1)}",
    choiceTitle: "Decompose the rational function",
    choice: "\\frac1{x^2-1}=\\frac12\\left(\\frac1{x-1}-\\frac1{x+1}\\right)",
    differential: "A=\\frac12,\\quad B=-\\frac12",
    transformed:
      "I=\\frac12\\int_2^4\\left(\\frac1{x-1}-\\frac1{x+1}\\right)dx",
    evaluation: "\\frac12\\left[\\ln|x-1|-\\ln|x+1|\\right]_2^4",
    result: "0.2939",
    numeric: (lower, upper) =>
      0.5 *
      Math.log(
        Math.abs(((upper - 1) * (lower + 1)) / ((upper + 1) * (lower - 1))),
      ),
    xCurve: (x) => 1 / Math.max(0.08, Math.abs(x * x - 1)),
    uCurve: (u) => 0.5 / Math.max(0.08, Math.abs(u - 1)),
    xLabel: "y=1/(x^2-1)",
    uLabel: "A/(x-1)+B/(x+1)",
    mapBound: (x) => x,
    parts: [
      { formula: "x-1", tone: "cyan" },
      { formula: "x+1", tone: "violet" },
    ],
    scaling: "\\frac{A}{x-1}+\\frac{B}{x+1}",
    insight:
      "Partial fractions replace one rational expression with simpler fractions whose antiderivatives are logarithms.",
    defaults: [2, 4],
  },
  trig: {
    title: "Trigonometric integrals",
    problem: "\\int_0^{\\pi/2}\\sin^2x\\,dx",
    original: "I=\\int_0^{\\pi/2}\\sin^2x\\,dx",
    choiceTitle: "Apply a power-reduction identity",
    choice: "\\sin^2x=\\frac{1-\\cos2x}{2}",
    differential: "\\int\\sin^2x\\,dx=\\frac{x}{2}-\\frac{\\sin2x}{4}",
    transformed: "I=\\frac12\\int_0^{\\pi/2}(1-\\cos2x)\\,dx",
    evaluation:
      "\\left[\\frac{x}{2}-\\frac{\\sin2x}{4}\\right]_0^{\\pi/2}=\\frac\\pi4",
    result: "0.7854",
    numeric: (lower, upper) =>
      upper / 2 -
      Math.sin(2 * upper) / 4 -
      (lower / 2 - Math.sin(2 * lower) / 4),
    xCurve: (x) => Math.sin(x) ** 2,
    uCurve: (u) => (1 - Math.cos(2 * u)) / 2,
    xLabel: "y=\\sin^2x",
    uLabel: "y=(1-\\cos2x)/2",
    mapBound: (x) => x,
    parts: [
      { formula: "\\sin x", tone: "cyan" },
      { formula: "\\sin x", tone: "violet" },
    ],
    scaling: "\\sin^2x=\\frac{1-\\cos2x}{2}",
    insight:
      "Power-reduction identities turn even trigonometric powers into sums that integrate term by term.",
    defaults: [0, Math.PI / 2],
  },
  "trig-sub": {
    title: "Trigonometric substitution",
    problem: "\\int_0^2\\sqrt{9-x^2}\\,dx",
    original: "I=\\int_0^2\\sqrt{9-x^2}\\,dx",
    choiceTitle: "Match the radical to an identity",
    choice: "x=3\\sin\\theta",
    differential: "dx=3\\cos\\theta\\,d\\theta",
    transformed: "I=9\\int_0^{\\sin^{-1}(2/3)}\\cos^2\\theta\\,d\\theta",
    evaluation: "\\frac12[x\\sqrt{9-x^2}+9\\sin^{-1}(x/3)]_0^2",
    result: "5.4789",
    numeric: (lower, upper) => primitiveCircle(upper) - primitiveCircle(lower),
    xCurve: (x) => Math.sqrt(Math.max(0, 9 - x * x)),
    uCurve: (u) => 9 * Math.cos(u) ** 2,
    xLabel: "y=\\sqrt{9-x^2}",
    uLabel: "y=9\\cos^2\\theta",
    mapBound: (x) => Math.asin(clamp(x / 3, -1, 1)),
    parts: [
      { formula: "x", tone: "cyan" },
      { formula: "\\sqrt{9-x^2}", tone: "violet" },
    ],
    scaling: "9-x^2=9(1-\\sin^2\\theta)=9\\cos^2\\theta",
    insight:
      "A trigonometric substitution replaces a radical with a Pythagorean identity and transforms both dx and the bounds.",
    defaults: [0, 2],
  },
  improper: {
    title: "Improper integrals",
    problem: "\\int_1^\\infty\\frac1{x^2}\\,dx",
    original: "I=\\int_1^\\infty x^{-2}\\,dx",
    choiceTitle: "Replace infinity with a limit",
    choice: "I=\\lim_{b\\to\\infty}\\int_1^b x^{-2}\\,dx",
    differential: "\\int x^{-2}dx=-x^{-1}",
    transformed: "I=\\lim_{b\\to\\infty}[-1/x]_1^b",
    evaluation: "\\lim_{b\\to\\infty}(1-1/b)=1",
    result: "1.0000",
    numeric: (lower, upper) =>
      1 / Math.max(0.1, lower) - 1 / Math.max(0.1, upper),
    xCurve: (x) => 1 / Math.max(0.1, x * x),
    uCurve: (u) => 1 - 1 / Math.max(1, u),
    xLabel: "y=1/x^2",
    uLabel: "A(b)=1-1/b",
    mapBound: (x) => x,
    parts: [
      { formula: "1", tone: "cyan" },
      { formula: "x^2", tone: "violet" },
    ],
    scaling: "\\int_a^\\infty f(x)dx=\\lim_{b\\to\\infty}\\int_a^bf(x)dx",
    insight:
      "An improper integral is defined by a limit. Convergence means the finite-bound areas approach a finite value.",
    defaults: [1, 8],
  },
};

const workflow = [
  "Choose Technique",
  "Set Up",
  "Transform Integral",
  "Evaluate",
  "Verify",
];

export default function CalculusIntegrationTechniquesStudio({ mode }: Props) {
  const [params, setParams] = useSearchParams();
  const technique = isTechnique(mode) ? mode : "substitution";
  const config = techniques[technique];
  const initialLower = numberParam(params.get("v_b"), config.defaults[0]);
  const initialUpper = numberParam(params.get("v_a"), config.defaults[1]);
  const [lower, setLower] = useStudioState("CalculusIntegrationTechniquesStudio:CalculusIntegrationTechniquesStudio:lower", Math.min(initialLower, initialUpper));
  const [upper, setUpper] = useStudioState("CalculusIntegrationTechniquesStudio:CalculusIntegrationTechniquesStudio:upper", Math.max(initialLower, initialUpper));
  const [resolution, setResolution] = useStudioState("CalculusIntegrationTechniquesStudio:CalculusIntegrationTechniquesStudio:resolution",
    clamp(Math.round(numberParam(params.get("v_n"), 20)), 8, 80),
  );
  const [step, setStep] = useStudioState("CalculusIntegrationTechniquesStudio:CalculusIntegrationTechniquesStudio:step",
    clamp(Math.round(numberParam(params.get("v_step"), 2)), 1, 6),
  );
  const [showBounds, setShowBounds] = useState(true);
  const [selectedPart, setSelectedPart] = useStudioState("CalculusIntegrationTechniquesStudio:CalculusIntegrationTechniquesStudio:selectedPart", 0);
  const [tipsOpen, setTipsOpen] = useStudioState("CalculusIntegrationTechniquesStudio:CalculusIntegrationTechniquesStudio:tipsOpen", false);
  const [challengeNote, setChallengeNote] = useStudioState("CalculusIntegrationTechniquesStudio:CalculusIntegrationTechniquesStudio:challengeNote", "");
  const previousTechnique = useRef(technique);

  useEffect(() => {
    const next = new URLSearchParams(params);
    next.set("v_a", trim(upper));
    next.set("v_b", trim(lower));
    next.set("v_n", String(resolution));
    next.set("v_step", String(step));
    if (next.toString() !== params.toString())
      setParams(next, { replace: true });
  }, [lower, params, resolution, setParams, step, upper]);

  useEffect(() => {
    if (previousTechnique.current === technique) return;
    previousTechnique.current = technique;
    setLower(config.defaults[0]);
    setUpper(config.defaults[1]);
    setStep(2);
    setSelectedPart(0);
    setTipsOpen(false);
  }, [config, technique]);

  const mappedLower = config.mapBound(lower);
  const mappedUpper = config.mapBound(upper);
  const currentValue = useMemo(
    () => config.numeric(lower, upper),
    [config, lower, upper],
  );
  const validValue = Number.isFinite(currentValue);
  const nextExample = () => {
    const [baseLower, baseUpper] = config.defaults;
    const shiftedUpper =
      technique === "improper"
        ? upper >= 16
          ? 6
          : upper + 2
        : upper >= baseUpper + 1
          ? baseUpper
          : upper + 0.5;
    setLower(baseLower);
    setUpper(Math.max(baseLower + 0.25, shiftedUpper));
    setStep(1);
  };
  const reset = () => {
    setLower(config.defaults[0]);
    setUpper(config.defaults[1]);
    setResolution(20);
    setStep(2);
    setShowBounds(true);
    setSelectedPart(0);
    setTipsOpen(false);
  };

  return (
    <section className="its-studio" aria-label={`${config.title} workspace`}>
      <div className="its-screen-badge">Screen 6 of 10</div>
      <div className="its-layout">
        <aside className="its-left">
          <Panel title="Problem">
            <p>Evaluate the integral</p>
            <MathExpression value={config.problem} display />
          </Panel>
          <Panel title={config.choiceTitle} tone="success">
            <MathExpression value={config.choice} display />
            <span className="its-valid">
              <Check /> Valid transformation
            </span>
            <MathExpression value={config.differential} display />
          </Panel>
          <Panel title="Expression parts">
            <p>Click to highlight matching parts</p>
            <div
              className="its-parts"
              role="group"
              aria-label="Expression parts"
            >
              {config.parts.map((part, index) => (
                <button
                  key={`${part.formula}-${index}`}
                  type="button"
                  className={`${part.tone} ${selectedPart === index ? "active" : ""}`}
                  aria-pressed={selectedPart === index}
                  onClick={() => setSelectedPart(index)}
                >
                  <MathExpression value={part.formula} />
                </button>
              ))}
              <MathExpression value="dx" />
            </div>
            <div className="its-part-key">
              <i className="cyan" /> matches the differential{" "}
              <i className="violet" /> becomes the transformed power
            </div>
          </Panel>
          <Panel
            title="Bounds transformation"
            action={
              <Toggle
                checked={showBounds}
                onChange={setShowBounds}
                label="Show transformed bounds"
              />
            }
          >
            {showBounds ? (
              <div className="its-bound-table">
                <div>
                  <span>x</span>
                  <span>
                    {technique === "trig-sub"
                      ? "theta"
                      : technique === "improper"
                        ? "b"
                        : "u"}
                  </span>
                </div>
                <label>
                  <input
                    aria-label="Lower bound"
                    type="number"
                    step="0.1"
                    value={lower}
                    onChange={(event) =>
                      setLower(
                        Math.min(Number(event.target.value), upper - 0.1),
                      )
                    }
                  />
                  <ArrowRight />
                  <b>{trim(mappedLower)}</b>
                </label>
                <label>
                  <input
                    aria-label="Upper bound"
                    type="number"
                    step="0.1"
                    value={upper}
                    onChange={(event) =>
                      setUpper(
                        Math.max(Number(event.target.value), lower + 0.1),
                      )
                    }
                  />
                  <ArrowRight />
                  <b>{trim(mappedUpper)}</b>
                </label>
              </div>
            ) : (
              <p className="its-muted">
                Original bounds remain visible on the graphs.
              </p>
            )}
          </Panel>
          <Panel title="Step controls">
            <div className="its-stepper">
              <button
                type="button"
                aria-label="First step"
                onClick={() => setStep(1)}
              >
                <ChevronLeft />
                <ChevronLeft />
              </button>
              <button
                type="button"
                aria-label="Previous step"
                onClick={() => setStep((value) => Math.max(1, value - 1))}
              >
                <ChevronLeft />
              </button>
              <strong>Step {step} of 6</strong>
              <button
                type="button"
                aria-label="Next step"
                onClick={() => setStep((value) => Math.min(6, value + 1))}
              >
                <ChevronRight />
              </button>
              <button
                type="button"
                aria-label="Last step"
                onClick={() => setStep(6)}
              >
                <ChevronRight />
                <ChevronRight />
              </button>
            </div>
            <button
              className="its-outline-command"
              type="button"
              onClick={nextExample}
            >
              <RefreshCw /> Try another{" "}
              {technique === "substitution" ? "substitution" : "example"}
            </button>
          </Panel>
        </aside>

        <main className="its-main">
          <section className="its-panel its-symbolic">
            <header>
              <PanelHeading title="Symbolic Transformation" />
              <button
                type="button"
                aria-label="Fullscreen transformation"
                onClick={() => void toggleFullscreen()}
              >
                <Expand />
              </button>
            </header>
            <div className="its-flow">
              <FormulaStage
                title="Original Integral"
                formula={config.original}
                active={step <= 2}
              />
              <ArrowRight />
              <FormulaStage
                title={technique === "parts" ? "Choose u and dv" : "Transform"}
                formula={[config.choice, config.differential]}
              />
              <ArrowRight />
              <FormulaStage
                title="Transformed Integral"
                formula={config.transformed}
                active={step >= 3}
                violet
              />
            </div>
          </section>
          <section className="its-panel its-geometry">
            <h2>Geometric View: Region Before and After {config.title}</h2>
            <div className="its-graphs">
              <StudioGraphWidget expressions={[config.xLabel.includes("x") ? "x*sqrt(x^2+1)" : "sin(x)^2"]} labels={[config.xLabel]} />
              <TechniqueGraph
                title="x-space (original)"
                label={config.xLabel}
                curve={config.xCurve}
                lower={lower}
                upper={upper}
                resolution={resolution}
                color="#06aeda"
              />
              <div className="its-map-arrow">
                <ArrowLeft />
                <ArrowRight />
              </div>
              <TechniqueGraph
                title={
                  technique === "trig-sub"
                    ? "theta-space (transformed)"
                    : technique === "improper"
                      ? "limit view"
                      : "u-space (transformed)"
                }
                label={config.uLabel}
                curve={config.uCurve}
                lower={mappedLower}
                upper={mappedUpper}
                resolution={resolution}
                color="#7c3aed"
              />
            </div>
            <div className="its-graph-meta">
              <span>
                <i className="cyan" /> {trim(lower)}
              </span>
              <span>
                <i className="cyan" /> {trim(upper)}
              </span>
              <strong>
                Area = {validValue ? Math.abs(currentValue).toFixed(3) : "--"}
              </strong>
              <span>
                <i className="violet" /> {trim(mappedLower)}
              </span>
              <span>
                <i className="violet" /> {trim(mappedUpper)}
              </span>
              <strong>
                Area = {validValue ? Math.abs(currentValue).toFixed(3) : "--"}
              </strong>
            </div>
          </section>
          <section className="its-insight">
            <Lightbulb />
            <p>
              The transformation maps the original interval to its new variable
              while preserving the integral value.{" "}
              <MathExpression value={config.scaling} />
            </p>
          </section>
        </main>

        <aside className="its-right">
          <Panel
            title={
              technique === "substitution"
                ? "Live substitution values"
                : "Live transformation values"
            }
          >
            <div className="its-live-bounds">
              <span>When x = {trim(lower)}</span>
              <ArrowRight />
              <MathExpression value={`u=${trim(mappedLower)}`} />
              <span>When x = {trim(upper)}</span>
              <ArrowRight />
              <MathExpression value={`u=${trim(mappedUpper)}`} />
            </div>
            <span className="its-valid">
              Bounds transformed <Check />
            </span>
          </Panel>
          <Panel title="Transformed integral">
            <div className="its-result-formula">
              <MathExpression value={config.transformed} display />
            </div>
            <b>Evaluate</b>
            <MathExpression value={config.evaluation} display />
            <b>Numeric value</b>
            <div className="its-numeric">
              = {validValue ? currentValue.toFixed(4) : config.result}
              <Check />
            </div>
          </Panel>
          <Panel title="Step validation">
            <span className="its-valid">
              {step === 6 ? "All steps complete" : `Step ${step} is valid`}
            </span>
            <div className="its-validation">
              {Array.from({ length: 6 }, (_, index) => (
                <button
                  type="button"
                  key={index}
                  className={index + 1 <= step ? "done" : ""}
                  onClick={() => setStep(index + 1)}
                >
                  {index + 1}
                </button>
              ))}
            </div>
          </Panel>
          <Panel title="Jacobian scaling insight">
            <MathExpression value={config.scaling} display />
            <p>
              This factor accounts for the change in the differential and keeps
              both integral values equal.
            </p>
          </Panel>
          <Panel title="Why this works">
            <p>{config.insight}</p>
            <p><strong>Challenge.</strong> {technique === "substitution" ? "Watch the interval map from x to u and match the transformed bounds." : technique === "parts" ? "Highlight u and dv, then complete one tabular step." : technique === "partial" ? "Use cover-up constants and check them on the integrand graph." : technique === "trig" || technique === "trig-sub" ? "Build the reference triangle from the radical, then substitute." : "Raise the cutoff b until the tail looks converged."}</p>
            <p>
              {technique === "substitution"
                ? "Challenge: map the x-interval onto the u-interval and match the transformed area."
                : technique === "parts"
                  ? "Challenge: choose u and dv so the tabular highlight matches the remaining integral."
                  : technique === "partial"
                    ? "Challenge: cover-up constants until the graph of the sum matches the integrand."
                    : technique === "trig" || technique === "trig-sub"
                      ? "Challenge: build the reference triangle from the radical and check the substitution."
                      : "Challenge: raise the cutoff b until the improper integral visibly converges or diverges."}
            </p>
            <button type="button" onClick={() => setChallengeNote(step >= 4 ? "Challenge complete: the transformation steps are far enough to check the graph." : "Not yet. Advance the step cards, then check again.")}>Check challenge</button>
            {challengeNote ? <p role="status">{challengeNote}</p> : null}
          </Panel>
          <Panel title="Resolution">
            <label className="its-resolution">
              <span>Graph samples</span>
              <b>{resolution}</b>
              <input
                aria-label="Graph samples"
                type="range"
                min="8"
                max="80"
                step="1"
                value={resolution}
                onChange={(event) => setResolution(Number(event.target.value))}
              />
            </label>
          </Panel>
        </aside>
      </div>

      <footer className="its-guided">
        <strong>
          <RefreshCw /> Guided Learning
        </strong>
        {workflow.map((label, index) => (
          <button
            type="button"
            key={label}
            className={
              step === index + 1 ? "active" : step > index + 1 ? "done" : ""
            }
            onClick={() => setStep(index + 1)}
          >
            <span>{index + 1}</span>
            {label}
            {step > index + 1 && <Check />}
          </button>
        ))}
        <button
          type="button"
          className={tipsOpen ? "active" : ""}
          aria-expanded={tipsOpen}
          onClick={() => setTipsOpen((value) => !value)}
        >
          <Lightbulb /> Tips
        </button>
      </footer>
      {tipsOpen && (
        <div className="its-tip" role="status">
          Track the differential first, then transform the bounds before
          evaluating. Both graphs should report the same shaded area.
        </div>
      )}
      <button className="its-reset" type="button" onClick={reset}>
        <RotateCcw /> Reset studio
      </button>
    </section>
  );
}

function Panel({
  title,
  children,
  action,
  tone = "plain",
}: {
  title: string;
  children: React.ReactNode;
  action?: React.ReactNode;
  tone?: "plain" | "success";
}) {
  return (
    <section
      className={`its-panel its-small-panel ${tone === "success" ? "success" : ""}`}
    >
      <header>
        <PanelHeading title={title} />
        {action}
      </header>
      {children}
    </section>
  );
}

function PanelHeading({ title }: { title: string }) {
  return (
    <h2>
      <i />
      {title}
    </h2>
  );
}

function FormulaStage({
  title,
  formula,
  active = false,
  violet = false,
}: {
  title: string;
  formula: string | string[];
  active?: boolean;
  violet?: boolean;
}) {
  return (
    <div
      className={`its-formula-stage ${active ? "active" : ""} ${violet ? "violet" : ""}`}
    >
      <strong>{title}</strong>
      {(Array.isArray(formula) ? formula : [formula]).map((value) => (
        <MathExpression key={value} value={value} display />
      ))}
    </div>
  );
}

function Toggle({
  checked,
  onChange,
  label,
}: {
  checked: boolean;
  onChange: (value: boolean) => void;
  label: string;
}) {
  return (
    <button
      className={`its-toggle ${checked ? "on" : ""}`}
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
    >
      <span />
    </button>
  );
}

function TechniqueGraph({
  title,
  label,
  curve,
  lower,
  upper,
  resolution,
  color,
}: {
  title: string;
  label: string;
  curve: (x: number) => number;
  lower: number;
  upper: number;
  resolution: number;
  color: string;
}) {
  const width = 360,
    height = 270,
    pad = 38;
  const lo = Math.min(lower, upper),
    hi = Math.max(lower, upper);
  const span = Math.max(0.2, hi - lo),
    xMin = lo - span * 0.32,
    xMax = hi + span * 0.32;
  const points = Array.from(
    { length: Math.max(16, resolution) },
    (_, index) => {
      const x = xMin + (index / (Math.max(16, resolution) - 1)) * (xMax - xMin);
      return { x, y: safe(curve, x) };
    },
  );
  const finite = points.map((point) => point.y).filter(Number.isFinite);
  const yMax = Math.max(1, Math.min(20, Math.max(...finite)));
  const sx = (x: number) =>
    pad + ((x - xMin) / (xMax - xMin)) * (width - pad * 2);
  const sy = (y: number) =>
    height - pad - (clamp(y, 0, yMax) / yMax) * (height - pad * 2);
  const curvePath = path(points, sx, sy);
  const areaPoints = points.filter(
    (point) => point.x >= lo && point.x <= hi && Number.isFinite(point.y),
  );
  const areaPath = areaPoints.length
    ? `M${sx(areaPoints[0].x)},${sy(0)} ${areaPoints.map((point) => `L${sx(point.x)},${sy(point.y)}`).join(" ")} L${sx(areaPoints.at(-1)?.x ?? hi)},${sy(0)} Z`
    : "";
  return (
    <figure className="its-graph-card">
      <figcaption>{title}</figcaption>
      <MathExpression value={label} />
      <svg
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label={`${title} graph`}
      >
        <defs>
          <clipPath id={`its-clip-${title.replace(/[^a-z]/gi, "-")}`}>
            <rect x={pad} y={pad} width={width-pad*2} height={height-pad*2} />
          </clipPath>
        </defs>
        <rect width={width} height={height} fill="#fff" />
        {Array.from({ length: 7 }, (_, index) => (
          <line
            key={`v${index}`}
            x1={pad + (index * (width - pad * 2)) / 6}
            x2={pad + (index * (width - pad * 2)) / 6}
            y1={pad}
            y2={height - pad}
            className="grid"
          />
        ))}
        {Array.from({ length: 6 }, (_, index) => (
          <line
            key={`h${index}`}
            x1={pad}
            x2={width - pad}
            y1={pad + (index * (height - pad * 2)) / 5}
            y2={pad + (index * (height - pad * 2)) / 5}
            className="grid"
          />
        ))}
        <line
          x1={pad}
          x2={width - pad}
          y1={sy(0)}
          y2={sy(0)}
          className="axis"
        />
        <line
          x1={sx(0)}
          x2={sx(0)}
          y1={pad}
          y2={height - pad}
          className="axis"
        />
        <g clipPath={`url(#its-clip-${title.replace(/[^a-z]/gi, "-")})`}>
          <path d={areaPath} fill="#f7c64a" opacity=".42" />
          <path d={curvePath} fill="none" stroke={color} strokeWidth="3" />
        </g>
        <line
          x1={sx(lo)}
          x2={sx(lo)}
          y1={sy(0)}
          y2={sy(safe(curve, lo))}
          className="bound"
        />
        <line
          x1={sx(hi)}
          x2={sx(hi)}
          y1={sy(0)}
          y2={sy(safe(curve, hi))}
          className="bound"
        />
        <circle cx={sx(lo)} cy={sy(safe(curve, lo))} r="4" fill={color} />
        <circle cx={sx(hi)} cy={sy(safe(curve, hi))} r="4" fill={color} />
        <text className="tick-label" x={sx(lo)} y={height-pad+18}>{trim(lo)}</text>
        <text className="tick-label" x={sx(hi)} y={height-pad+18}>{trim(hi)}</text>
        <text className="axis-label" x={width-pad+8} y={height-pad+4}>{title.startsWith("x-") ? "x" : title.startsWith("theta-") ? "θ" : title.startsWith("limit") ? "b" : "u"}</text>
        <text className="axis-label" x={sx(0)+7} y={pad-8}>y</text>
      </svg>
    </figure>
  );
}

function isTechnique(value: string): value is TechniqueId {
  return value in techniques;
}

export function evaluateTechnique(
  technique: TechniqueId,
  lower: number,
  upper: number,
) {
  const config = techniques[technique];
  return {
    value: config.numeric(lower, upper),
    mappedBounds: [config.mapBound(lower), config.mapBound(upper)] as const,
    original: config.original,
    transformed: config.transformed,
  };
}

function primitiveCircle(x: number) {
  const value = clamp(x, -3, 3);
  return (
    0.5 *
    (value * Math.sqrt(Math.max(0, 9 - value * value)) +
      9 * Math.asin(value / 3))
  );
}

function numberParam(value: string | null, fallback: number) {
  if (value === null || value.trim() === "") return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function safe(fn: (x: number) => number, x: number) {
  try {
    const value = fn(x);
    return Number.isFinite(value) ? value : NaN;
  } catch {
    return NaN;
  }
}

function path(
  points: Array<{ x: number; y: number }>,
  sx: (x: number) => number,
  sy: (y: number) => number,
) {
  let open = false;
  return points
    .map((point) => {
      if (!Number.isFinite(point.y)) {
        open = false;
        return "";
      }
      const command = open ? "L" : "M";
      open = true;
      return `${command}${sx(point.x).toFixed(2)},${sy(point.y).toFixed(2)}`;
    })
    .join(" ");
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function trim(value: number) {
  return Number.isFinite(value) ? Number(value.toFixed(3)).toString() : "--";
}

async function toggleFullscreen() {
  const target = document.querySelector(".its-main");
  if (!target) return;
  if (document.fullscreenElement) await document.exitFullscreen();
  else await target.requestFullscreen();
}

import { useStudioState } from "../studios/phase1/StudioModelProvider";
import {
  Check,
  ChevronRight,
  CircleAlert,
  Eye,
  Lightbulb,
  Maximize2,
  Minus,
  Pause,
  Play,
  Plus,
  RotateCcw,
  StepForward,
  Target,
  Trophy,
  X,
  ZoomIn,
} from "lucide-react";
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { useSearchParams } from "react-router-dom";
import MathExpression from "../components/ui/MathExpression";
import { compileFunctionExpression } from "../utils/functionParser";
import { repairedLimitExpression } from "./calculusStudioSession";
import "./CalculusLimitsStudio.css";

export type LimitMode =
  | "limits"
  | "continuity"
  | "discontinuities"
  | "asymptotes"
  | "lhopital";

type Viewport = { xMin: number; xMax: number; yMin: number; yMax: number };
type LimitAnalysis = {
  left: number;
  right: number;
  limit: number;
  value: number;
  defined: boolean;
  limitExists: boolean;
  continuous: boolean;
  classification: string;
};

type ModeConfig = {
  expression: string;
  point: number;
  distance: number;
  viewport: Viewport;
  summary: string;
  explanation: string;
};

const modeConfigs: Record<LimitMode, ModeConfig> = {
  limits: {
    expression: "sin(x)/x",
    point: 0,
    distance: 0.5,
    viewport: { xMin: -3.3, xMax: 3.3, yMin: -1.5, yMax: 1.5 },
    summary: "Compare both one-sided approaches to determine the limit.",
    explanation:
      "A two-sided limit exists only when the left-hand and right-hand limits approach the same value.",
  },
  continuity: {
    expression: "(x^2-1)/(x-1)",
    point: 1,
    distance: 0.4,
    viewport: { xMin: -3.2, xMax: 4.2, yMin: -2, yMax: 5 },
    summary: "Test the three conditions required for continuity at a point.",
    explanation:
      "Continuity at a requires f(a) to exist, the two-sided limit to exist, and those two values to agree.",
  },
  discontinuities: {
    expression: "1/x",
    point: 0,
    distance: 0.4,
    viewport: { xMin: -4, xMax: 4, yMin: -8, yMax: 8 },
    summary: "Classify removable, jump, infinite, and oscillatory behavior.",
    explanation:
      "A discontinuity is classified by how the function behaves from the left and right of the selected point.",
  },
  asymptotes: {
    expression: "1/(x-1)",
    point: 1,
    distance: 0.4,
    viewport: { xMin: -3, xMax: 5, yMin: -8, yMax: 8 },
    summary: "Inspect unbounded behavior near a vertical asymptote.",
    explanation:
      "A vertical asymptote occurs when function values grow without bound as x approaches a fixed value.",
  },
  lhopital: {
    expression: "sin(x)/x",
    point: 0,
    distance: 0.5,
    viewport: { xMin: -3.3, xMax: 3.3, yMin: -1.5, yMax: 1.5 },
    summary: "Resolve an indeterminate quotient using derivatives.",
    explanation:
      "For a 0/0 indeterminate form, L'Hopital's Rule replaces the quotient by the quotient of its derivatives.",
  },
};

const examples = [
  { expression: "sin(x)/x", label: "\\frac{\\sin(x)}{x}", point: 0 },
  { expression: "1/x", label: "\\frac{1}{x}", point: 0 },
  { expression: "(x^2-1)/(x-1)", label: "\\frac{x^2-1}{x-1}", point: 1 },
  { expression: "sqrt(x)", label: "\\sqrt{x}", point: 0 },
  { expression: "abs(x)", label: "|x|", point: 0 },
  { expression: "1/(x^2+1)", label: "\\frac{1}{x^2+1}", point: 0 },
];

const learningTabs: Array<{
  id: string;
  label: string;
  subtitle: string;
  icon: typeof Eye;
}> = [
  { id: "observe", label: "Observe", subtitle: "What happens?", icon: Eye },
  { id: "understand", label: "Understand", subtitle: "Key idea", icon: Lightbulb },
  { id: "why", label: "Why", subtitle: "The reasoning", icon: CircleAlert },
  { id: "try", label: "Try", subtitle: "Practice it", icon: Target },
  { id: "challenge", label: "Challenge", subtitle: "Take it further", icon: Trophy },
];

export default function CalculusLimitsStudio({ mode }: { mode: string }) {
  const [params, setParams] = useSearchParams();
  const activeMode = isLimitMode(mode) ? mode : "limits";
  const config = modeConfigs[activeMode];
  const initialExpression = params.get("v_expression") || config.expression;
  const [expression, setExpression] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:expression", initialExpression);
  const [draft, setDraft] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:draft", initialExpression);
  const [a, setA] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:a", numberParam(params.get("v_a"), config.point));
  const initialDistance = clamp(numberParam(params.get("v_b"), config.distance), 0.01, 2);
  const [leftDistance, setLeftDistance] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:leftDistance", clamp(numberParam(params.get("v_left"), initialDistance), 0.01, 2));
  const [rightDistance, setRightDistance] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:rightDistance", clamp(numberParam(params.get("v_right"), initialDistance), 0.01, 2));
  const [samples, setSamples] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:samples", clamp(Math.round(numberParam(params.get("v_n"), 20)), 20, 200));
  const [showArrows, setShowArrows] = useState(true);
  const [tracePath, setTracePath] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:tracePath", false);
  const [playing, setPlaying] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:playing", false);
  const [speed, setSpeed] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:speed", 1);
  const [definedValue, setDefinedValue] = useStudioState<number | null>("CalculusLimitsStudio:CalculusLimitsStudio:definedValue", () => {
    const value = params.get("v_defined");
    return value === null ? null : numberParam(value, 0);
  });
  const [lockDelta, setLockDelta] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:lockDelta", true);
  const [epsilon, setEpsilon] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:epsilon", 0.25);
  const [viewport, setViewport] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:viewport", config.viewport);
  const [trace, setTrace] = useStudioState<{ x: number; y: number } | null>("CalculusLimitsStudio:CalculusLimitsStudio:trace", null);
  const [challengeNote, setChallengeNote] = useStudioState("CalculusLimitsStudio:CalculusLimitsStudio:challengeNote", "");
  const previousMode = useRef(activeMode);

  const compiled = useMemo(() => compileExpression(expression), [expression]);
  const draftError = useMemo(() => compileExpression(draft).error, [draft]);
  const analysis = useMemo(
    () => analyzeLimit(compiled.fn, a, definedValue),
    [a, compiled.fn, definedValue],
  );

  useEffect(() => {
    const next = new URLSearchParams(params);
    next.set("v_a", trim(a));
    next.set("v_b", trim(Math.max(leftDistance, rightDistance)));
    next.set("v_left", trim(leftDistance));
    next.set("v_right", trim(rightDistance));
    next.set("v_n", String(samples));
    next.set("v_expression", expression);
    if (definedValue === null) next.delete("v_defined");
    else next.set("v_defined", trim(definedValue));
    if (next.toString() !== params.toString()) setParams(next, { replace: true });
  }, [a, definedValue, expression, leftDistance, params, rightDistance, samples, setParams]);

  useEffect(() => {
    if (previousMode.current === activeMode) return;
    previousMode.current = activeMode;
    setExpression(config.expression);
    setDraft(config.expression);
    setA(config.point);
    setLeftDistance(config.distance);
    setRightDistance(config.distance);
    setDefinedValue(null);
    setViewport(config.viewport);
    setPlaying(false);
  }, [activeMode, config]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => {
      let stopped = false;
      const advance = (value: number) => {
        const next = value - 0.012 * speed;
        if (next <= 0.012) stopped = true;
        return next <= 0.012 ? 0.01 : next;
      };
      setLeftDistance(advance);
      setRightDistance(advance);
      if (stopped) setPlaying(false);
    }, 40);
    return () => window.clearInterval(timer);
  }, [playing, speed]);

  const applyExpression = () => {
    if (draftError) return;
    setExpression(draft);
    setDefinedValue(null);
  };
  const selectExample = (item: (typeof examples)[number]) => {
    setExpression(item.expression);
    setDraft(item.expression);
    setA(item.point);
    setDefinedValue(null);
    setPlaying(false);
  };
  const reset = () => {
    setExpression(config.expression);
    setDraft(config.expression);
    setA(config.point);
    setLeftDistance(config.distance);
    setRightDistance(config.distance);
    setSamples(20);
    setDefinedValue(null);
    setViewport(config.viewport);
    setPlaying(false);
    setTrace(null);
  };
  useEffect(() => {
    window.addEventListener("calculus-lab-reset", reset);
    return () => window.removeEventListener("calculus-lab-reset", reset);
  });
  const step = () => {
    setLeftDistance((value) => Math.max(0.01, value * 0.72));
    setRightDistance((value) => Math.max(0.01, value * 0.72));
  };
  const zoom = (factor: number) => setViewport((value) => zoomViewport(value, factor));

  return (
    <div className="cls-studio">
      <div className="cls-context" role="status">
        <span>{config.summary}</span>
        <button type="button" onClick={reset}><RotateCcw /> Reset experiment</button>
      </div>

      <div className="cls-workspace">
        <aside className="cls-controls" aria-label="Limit controls">
          <NumberedPanel number={1} title="Function">
            <div className="cls-expression-row">
              <span>f(x) =</span>
              <input aria-label="Function expression" value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => event.key === "Enter" && applyExpression()} />
              <button type="button" onClick={applyExpression} disabled={Boolean(draftError)} aria-label="Apply function"><ChevronRight /></button>
            </div>
            {draftError && <p className="cls-error">{draftError}</p>}
            <span className="cls-small-label">Examples</span>
            <div className="cls-examples">
              {examples.map((item) => (
                <button type="button" key={item.expression} className={expression === item.expression ? "active" : ""} onClick={() => selectExample(item)}>
                  <MathExpression value={item.label} />
                </button>
              ))}
            </div>
          </NumberedPanel>

          <NumberedPanel number={2} title="Limit point a">
            <label className="cls-range orange">
              <input aria-label="Limit point" type="range" min="-5" max="5" step="0.05" value={a} onChange={(event) => { setA(Number(event.target.value)); setDefinedValue(null); }} />
              <span><i>-5</i><b>a = {trim(a)}</b><i>5</i></span>
            </label>
            <input className="cls-number-input" aria-label="Limit point value" type="number" step="0.05" value={a} onChange={(event) => { setA(Number(event.target.value)); setDefinedValue(null); }} />
          </NumberedPanel>

          <NumberedPanel number={3} title="Approach distance δ">
            <CheckControl label="Lock left and right δ" checked={lockDelta} onChange={(value) => {
              setLockDelta(value);
              if (value) setRightDistance(leftDistance);
            }} />
            <DistanceControl side="Left" color="orange" value={leftDistance} onChange={(value) => {
              setLeftDistance(value);
              if (lockDelta) setRightDistance(value);
            }} />
            <DistanceControl side="Right" color="violet" value={rightDistance} onChange={(value) => {
              setRightDistance(value);
              if (lockDelta) setLeftDistance(value);
            }} />
            <label className="cls-distance orange"><span>ε band</span><div><input aria-label="Epsilon" type="range" min="0.05" max="1.5" step="0.01" value={epsilon} onChange={(event) => setEpsilon(Number(event.target.value))} /><output>{epsilon.toFixed(2)}</output></div></label>
          </NumberedPanel>

          <NumberedPanel number={4} title="Animate">
            <div className="cls-play-controls">
              <button className="primary" type="button" onClick={() => setPlaying(true)} disabled={playing}><Play /> Play</button>
              <button type="button" onClick={() => setPlaying(false)} disabled={!playing}><Pause /> Pause</button>
              <button type="button" onClick={step}><StepForward /> Step</button>
            </div>
            <label className="cls-speed">Speed <input aria-label="Animation speed" type="range" min="0.5" max="2" step="0.5" value={speed} onChange={(event) => setSpeed(Number(event.target.value))} /><b>{speed.toFixed(1)}x</b></label>
            <CheckControl label="Show approach arrows" checked={showArrows} onChange={setShowArrows} />
            <CheckControl label="Trace path" checked={tracePath} onChange={setTracePath} />
          </NumberedPanel>
        </aside>

        <LimitGraph
          fn={compiled.fn}
          expression={expression}
          a={a}
          leftDistance={leftDistance}
          rightDistance={rightDistance}
          analysis={analysis}
          viewport={viewport}
          samples={samples}
          showArrows={showArrows}
          tracePath={tracePath}
          trace={trace}
          onTrace={setTrace}
          onZoom={zoom}
          onResetView={() => setViewport(config.viewport)}
          epsilon={epsilon}
          onEpsilon={setEpsilon}
          mode={activeMode}
        />

        <aside className="cls-results" aria-label="Live limit analysis">
          <NumberedPanel number={5} title="Live Results">
            <div className="cls-result-list">
              <ResultLine tone="orange" formula={`\\lim_{x\\to ${trim(a)}^-}f(x)`} value={formatLimit(analysis.left)} passed={Number.isFinite(analysis.left) || !Number.isNaN(analysis.left)} />
              <ResultLine tone="violet" formula={`\\lim_{x\\to ${trim(a)}^+}f(x)`} value={formatLimit(analysis.right)} passed={Number.isFinite(analysis.right) || !Number.isNaN(analysis.right)} />
              <ResultLine tone="cyan" formula={`\\lim_{x\\to ${trim(a)}}f(x)`} value={formatLimit(analysis.limit)} passed={analysis.limitExists} />
              <ResultLine tone="red" formula={`f(${trim(a)})`} value={analysis.defined ? formatLimit(analysis.value) : "undefined"} passed={analysis.defined} />
            </div>
          </NumberedPanel>

          <NumberedPanel number={6} title={`Continuity Check at a = ${trim(a)}`}>
            <CheckRow passed={analysis.defined} label={`f(${trim(a)}) is defined`} />
            <CheckRow passed={analysis.limitExists} label="The two-sided limit exists" />
            <CheckRow passed={analysis.continuous} label={`The limit equals f(${trim(a)})`} />
            <p className={analysis.continuous ? "cls-conclusion pass" : "cls-conclusion"}>
              Conclusion: {analysis.continuous ? "Continuous" : analysis.classification} at x = {trim(a)}
            </p>
            {!analysis.defined && analysis.limitExists ? <p className="cls-explanation">Undefined at a, but the two-sided limit exists. This is a removable discontinuity if we define f(a) = {formatLimit(analysis.limit)}.</p> : null}
          </NumberedPanel>

          <NumberedPanel number={7} title="Explanation">
            {activeMode === "lhopital" && (
              <div className="cls-lhopital">
                <MathExpression value="\\frac{0}{0}\\Rightarrow\\lim_{x\\to0}\\frac{\\cos x}{1}=1" display />
              </div>
            )}
            <p className="cls-explanation">{explainAnalysis(analysis, a, config.explanation)}</p>
          </NumberedPanel>

          <NumberedPanel number={8} title="Make continuous">
            {analysis.limitExists && Number.isFinite(analysis.limit) && !analysis.continuous ? (
              <>
                <p>Define <MathExpression value={`f(${trim(a)})=${formatLimit(analysis.limit)}`} /> to remove the hole.</p>
                <button className="cls-repair" type="button" onClick={() => {
                  const repaired = repairedLimitExpression(expression, a, analysis.limit);
                  setDefinedValue(analysis.limit);
                  setExpression(repaired);
                  setDraft(repaired);
                }}>Set <MathExpression value={`f(${trim(a)})=${formatLimit(analysis.limit)}`} /></button>
              </>
            ) : (
              <p>{analysis.continuous ? "All three continuity conditions now pass." : "A point value cannot repair this type of discontinuity."}</p>
            )}
          </NumberedPanel>
        </aside>
      </div>

      <section className="cls-learning" aria-label="Learning loop">
        <div className="cls-learning-tabs">
          {learningTabs.map(({ id, label, subtitle, icon: Icon }) => (
            <div key={id}>
              <Icon /><span><b>{label}</b><small>{id === "challenge" ? limitChallenge(activeMode) : subtitle}</small></span>
            </div>
          ))}
        </div>
        <button className="cls-repair" type="button" onClick={() => {
          const pass = activeMode === "continuity" ? analysis.continuous : activeMode === "discontinuities" ? !analysis.continuous : analysis.limitExists;
          setChallengeNote(pass ? "Challenge complete: the live limit checklist matches the graph." : "Not yet. Adjust δ, repair the hole, or switch examples, then check again.");
        }}>Check challenge</button>
        {challengeNote ? <p className="cls-explanation" role="status">{challengeNote}</p> : null}
      </section>
    </div>
  );
}

function NumberedPanel({ number, title, children }: { number: number; title: string; children: React.ReactNode }) {
  return <section className="cls-panel"><h2><span>{number}</span>{title}</h2><div className="cls-panel-body">{children}</div></section>;
}

