function VectorField({
  density,
  theorem,
}: {
  density: number;
  theorem: boolean;
}) {
  const count = Math.max(5, Math.min(11, Math.round(density / 2.5)));
  const arrows = Array.from({ length: count * count }, (_, index) => {
    const ix = index % count,
      iy = Math.floor(index / count);
    const x = -2.6 + (ix * 5.2) / (count - 1),
      y = -2.6 + (iy * 5.2) / (count - 1);
    const direction = new THREE.Vector3(-y, 0, x).normalize();
    return (
      <arrowHelper
        key={index}
        args={[
          direction,
          new THREE.Vector3(x, -0.6, y),
          0.34,
          theorem ? 0x8b5cf6 : 0x0ea5e9,
          0.1,
          0.06,
        ]}
      />
    );
  });
  return (
    <>
      {arrows}
      {theorem ? <MovingTheoremRegion /> : null}
    </>
  );
}

function MovingTheoremRegion() {
  const group = useRef<THREE.Group>(null);
  useFrame((_, delta) => {
    if (!group.current) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    group.current.rotation.y += delta * 0.35;
    const s = 1.05 + 0.12 * Math.sin(performance.now() / 700);
    group.current.scale.set(s, 1, s);
  });
  const circle = Array.from(
    { length: 65 },
    (_, index): [number, number, number] => {
      const t = (index / 64) * Math.PI * 2;
      return [2.15 * Math.cos(t), -0.57, 2.15 * Math.sin(t)];
    },
  );
  return (
    <group ref={group}>
      <Line points={circle} color="#f59e0b" lineWidth={4} />
      {Array.from({ length: 12 }, (_, index) => {
        const t = (index / 12) * Math.PI * 2;
        const x = 1.1 * Math.cos(t);
        const z = 1.1 * Math.sin(t);
        return <Line key={index} points={[[x, -0.2, z], [x * 1.35, 0.2, z * 1.35]]} color="#22c55e" lineWidth={2} />;
      })}
    </group>
  );
}

