      const [, name, xRaw, yRaw, zRaw] = point3dMatch;
      const position: [number, number, number] = [Number(xRaw), Number(yRaw), Number(zRaw)];
      recordWorkspaceStep("Define 3D point", `${name}=(${position.join(", ")})`);
      setSelected3d("point");
      setShowSurface(true);
      setDeletedBase3dIds((current) => current.filter((id) => id !== "point"));
      setTransforms3d((current) => ({ ...current, point: { ...current.point, name, position, visible: true } }));
      addResultCard({
        id: crypto.randomUUID(),
        input: raw,
        interpretation: "Live 3D point definition",
        result: `${name}=(${position.join(", ")})`,
        detail: "The 3D point is now selectable, draggable, editable, and linked to the 3D inspector.",
      });
      setProjectStatus(`${name} created as a live 3D object.`);
      return true;
    }

    const point2dMatch = raw.match(/^([A-Z]\w*)\s*=\s*\(\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*\)$/);
    if (point2dMatch) {
      const [, label, xRaw, yRaw] = point2dMatch;
      const math = { x: Number(xRaw), y: Number(yRaw) };
      const board = mathToBoardPoint(math.x, math.y);
      const id = crypto.randomUUID();
      recordWorkspaceStep("Define point", `${label}=(${math.x}, ${math.y})`);
      setConstruction((current) => solveConstruction({ ...current, points: [...current.points, { id, ...board, label }] }, id));
      setSelectedGeometry({ type: "point", id });
      addResultCard({
        id: crypto.randomUUID(),
        input: raw,
        interpretation: "Live point definition",
        result: `${label}=(${math.x}, ${math.y})`,
        detail: "The point was placed on the geometry board and can be edited from the algebra panel or inspector.",
      });
      setProjectStatus(`${label} created as a live geometry point.`);
      return true;
    }

    const circleEquationMatch = raw.match(/^([a-z]\w*)\s*:\s*x\^2\s*\+\s*y\^2\s*=\s*(\d+(?:\.\d+)?)$/i);
    if (circleEquationMatch) {
      const [, name, radiusSquaredRaw] = circleEquationMatch;
      const radius = Math.sqrt(Number(radiusSquaredRaw));
      const center = crypto.randomUUID();
      const edge = crypto.randomUUID();
      const circle = crypto.randomUUID();
      recordWorkspaceStep("Define circle equation", `${name}: x^2+y^2=${radiusSquaredRaw}`);
      setConstruction((current) => solveConstruction({
        ...current,
        points: [
          ...current.points,
          { id: center, ...mathToBoardPoint(0, 0), label: "O" },
          { id: edge, ...mathToBoardPoint(radius, 0), label: "R" },
        ],
        circles: [...current.circles, { id: circle, center, edge, style: { label: name } }],
      }));
      setSelectedGeometry({ type: "circle", id: circle });
      addResultCard({
        id: crypto.randomUUID(),
        input: raw,
        interpretation: "Live circle definition",
        result: `${name}: center=(0,0), r=${roundTo(radius, 4)}`,
        detail: "The equation became a selectable circle with editable radius, style, and algebra definition.",
      });
      setProjectStatus(`${name} created as a live circle object.`);
      return true;
    }

    const surfaceMatch = raw.match(/^(?:surface\s+)?z\s*=\s*(.+)$/i);
    if (surfaceMatch) {
      const expression = surfaceMatch[1].trim();
      recordWorkspaceStep("Define 3D surface", `z = ${expression}`);
      setSurface("custom-z");
      setSurfaceExpression(expression);
      setShowSurface(true);
      setSelected3d("surface");
      addResultCard({
        id: crypto.randomUUID(),
        input: raw,
        interpretation: "Live 3D surface definition",
        result: `z = ${expression}`,
        detail: "The expression is rendered as an editable browser-only 3D surface.",
      });
      setProjectStatus("Custom 3D surface linked to the 3D scene and inspector.");
      return true;
    }

    return false;
  };

  const executeWorkspaceCommand = (rawInput: string) => {
    const raw = rawInput.trim();
    if (!raw) return;
    if (applyDirectDefinitionCommand(raw)) return;
    const analysis = interpretInput(raw);
    if (analysis.interpretation === "2D plot") {
      const expression = normalizePlotExpression(raw);
      const validation = validateGraphExpression(expression);
      if (isGraphValidationBlocking(validation)) {
        const unsupported = createUnsupportedWorkspaceAction("Graph expression", validation.message, validation.suggestions);
        addResultCard(unsupportedActionResultCard(raw, unsupported));
        setProjectStatus(unsupported.message);
        return;
      }
      addResultCard(analysis);
      recordWorkspaceStep("Add function", raw);
      setPlots((current) => [{ id: crypto.randomUUID(), expression, name: nextFunctionName(current), color: colors[current.length % colors.length], kind: inferPlotKind(expression), visible: true }, ...current].slice(0, 8));
      return;
    }
    addResultCard(analysis);
    if (analysis.graphExpression) {
      recordWorkspaceStep("Add CAS graph link", analysis.graphExpression);
      const validation = validateGraphExpression(analysis.graphExpression);
      if (isGraphValidationBlocking(validation)) {
        const unsupported = createUnsupportedWorkspaceAction("CAS graph link", validation.message, validation.suggestions);
        addResultCard(unsupportedActionResultCard(raw, unsupported));
        setProjectStatus(unsupported.message);
        return;
      }
      setPlots((current) => [{ id: crypto.randomUUID(), expression: analysis.graphExpression!, name: nextFunctionName(current), color: colors[current.length % colors.length], kind: inferPlotKind(analysis.graphExpression!), visible: true }, ...current].slice(0, 10));
    }
  };

  const runInput = () => executeWorkspaceCommand(input);

  const addPoint = (x: number, y: number) => {
    const snapped = snapBoardPoint({ x, y }, construction, geometryGraphSettings);
    const result = buildPointCreation(construction, snapped);
    const point = result.construction.points[result.construction.points.length - 1];
    recordWorkspaceStep("Create point", `${point.label} = (${roundTo(point.x, 1)}, ${roundTo(point.y, 1)})`);
    setConstruction((current) => solveConstruction({ ...current, points: [...current.points, point] }, result.createdPointId));
    return result.createdPointId;
  };

  const selectGeometryTool = (nextTool: GeometryTool) => {
    const transformMode = geometryTransformToolMode(nextTool);
    if (transformMode) {
      const applied = applyGeometryFigureTransform(transformMode);
      if (applied) {
        setTool("select");
        return;
      }
      setTool(nextTool);
      setSelectedPointIds([]);
      setPolygonDraft([]);
      setGeometryObjectPicks([]);
      setProjectStatus(`${geometryToolLabel(nextTool)} ready. Click a shape, or pick points on the board.`);
      return;
    }
    setTool(nextTool);
    setSelectedPointIds([]);
    setPolygonDraft([]);
    setGeometryObjectPicks([]);
    if (nextTool !== "select") setProjectStatus(`${geometryToolLabel(nextTool)} ready.`);
  };

  const applyGeometryFigureTransform = (mode: GeometryTransformMode, explicitPointIds?: string[]) => {
    const request = createGeometryTransformRequest(construction, selectedGeometry, selectedPointIds, mode);
    const uniqueIds = explicitPointIds?.length
      ? Array.from(new Set(explicitPointIds))
      : request.ok
        ? request.value.pointIds
        : construction.points.map((point) => point.id);
    if (!uniqueIds.length) {
      setProjectStatus("Create or select a shape first, then use Rotate 45, Mirror, Dilate, or Translate.");
      return false;
    }
    recordWorkspaceStep(`Transform selected ${mode}`, `${uniqueIds.length} point${uniqueIds.length === 1 ? "" : "s"} updated.`);
    setConstruction((current) => solveConstruction(buildSelectedPointsTransform(current, uniqueIds, mode).construction));
    setSelectedPointIds(uniqueIds);
    const transformedObject = selectedGeometry ?? geometryObjectForPointIds(construction, uniqueIds);
    if (transformedObject) setSelectedGeometry(transformedObject);
    setProjectStatus(`${geometryToolLabel(mode === "mirror" ? "mirror" : mode)} applied to ${uniqueIds.length} point${uniqueIds.length === 1 ? "" : "s"}.`);
    return true;
  };

  const handleImageUpload = (fileList: FileList | null) => {
    const file = fileList?.[0];
    if (!file) return;
    if (!file.type.startsWith("image/")) {
      setProjectStatus("Choose a PNG, JPG, GIF, SVG, or WebP image.");
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const src = String(reader.result ?? "");
      const image = new Image();
      image.onload = () => {
        const maxWidth = 240;
        const ratio = image.width > 0 ? image.height / image.width : 0.65;
        const width = Math.min(maxWidth, Math.max(120, image.width || maxWidth));
        const next: WorkspaceImage = {
          id: crypto.randomUUID(),
          name: file.name.replace(/\.[^.]+$/, "") || "Image",
          src,
          x: 200,
          y: 120,
          width,
          height: Math.max(80, width * ratio),
          opacity: 0.92,
          visible: true,
        };
        recordWorkspaceStep("Add image", `${next.name} added to geometry board.`);
        setWorkspaceImages((current) => [next, ...current]);
        setSelectedImageId(next.id);
        setSelectedGeometry(null);
        setProjectStatus(`${next.name} added to the geometry board.`);
      };
      image.onerror = () => setProjectStatus("Could not read that image file.");
      image.src = src;
    };
    reader.readAsDataURL(file);
    if (imageInputRef.current) imageInputRef.current.value = "";
  };

  const handleBoardPointerDown = (event: PointerEvent<SVGSVGElement>) => {
    if (controlsLocked) return;
    setContextMenu(null);
    if (event.button === 2) return;
    event.currentTarget.setPointerCapture(event.pointerId);
    if (event.pointerType === "touch") event.preventDefault();
    if (tool === "move-canvas") {
      geometryPanRef.current = { clientX: event.clientX, clientY: event.clientY, camera: geometryCamera };
      return;
    }
    if (tool === "zoom") {
      const anchor = clientToBoard(event);
      zoomGeometry("in", anchor ?? undefined);
      return;
    }
    if (tool === "freehand") {
      const point = clientToBoard(event);
      if (!point) return;
      const id = crypto.randomUUID();
      geometryFreehandRef.current = id;
      setConstruction((current) => ({
        ...current,
        loci: [...current.loci, { id, label: "freehand", points: [point], style: { color: "#f97316", strokeWidth: 4 } }],
      }));
      recordWorkspaceStep("Draw freehand path", "Pointer sketch added to the board.");
      return;
    }
    const target = event.target as Element;
    const imageId = target.getAttribute("data-image-id");
    if (imageId) {
      setSelectedImageId(imageId);
      setSelectedGeometry(null);
      const image = workspaceImages.find((item) => item.id === imageId);
      if (image?.locked) return;
      recordWorkspaceStep("Move image", `${image?.name ?? "Image"} dragged on geometry board.`);
      setDragImageId(imageId);
      return;
    }
    const pointId = target.getAttribute("data-point-id");
    if (pointId) {
      setSelectedGeometry({ type: "point", id: pointId });
      if (lockedGeometryIds.includes(pointId)) return;
      if (tool === "select") {
        recordWorkspaceStep("Move point", `${labelForPoint(construction, pointId)} dragged on geometry board.`);
        setDragPointId(pointId);
      }
      else handlePointPick(pointId);
      return;
    }
    const objectType = target.getAttribute("data-object-type") as GeometryObjectType | null;
    const objectId = target.getAttribute("data-object-id");
    if (objectType && objectId && tool !== "select") {
      consumeGeometryToolObject(tool, { type: objectType, id: objectId }, construction);
      return;
    }
    if (objectType && objectId && tool === "select") {
      const object = { type: objectType, id: objectId };
      setSelectedGeometry(object);
      const point = clientToBoard(event);
      if (point && !lockedGeometryIds.includes(objectId)) {
        recordWorkspaceStep("Move object", `${objectType} moved on geometry board.`);
        setDragGeometry({ object, last: point });
      }
      return;
    }
    if (["image", "delete", "redo", "reset", "save", "load"].includes(tool)) return;
    const quickCreateTools: GeometryTool[] = ["text", "triangle", "rectangle", "square", "pentagon-shape", "hexagon", "parallelogram", "trapezoid", "rhombus", "kite", "shape-circle", "semicircle", "parabola", "ellipse", "hyperbola"];
    if (quickCreateTools.includes(tool)) {
      const point = clientToBoard(event);
      if (point) createQuickGeometryObject(tool, point.x, point.y);
      return;
    }
    const point = clientToBoard(event);
    if (!point) return;
    if (tool === "point") {
      addPoint(point.x, point.y);
      return;
    }
    createPointForActiveGeometryTool(tool, point.x, point.y);
  };

  const createPointForActiveGeometryTool = (activeTool: GeometryTool, x: number, y: number) => {
    if (activeTool === "freehand") {
      createDefaultGeometryToolObject(activeTool, x, y);
      return;
    }
    const pickTools: GeometryTool[] = [
      "segment",
      "line",
      "ray",
      "vector",
      "circle",
      "polygon",
      "triangle",
      "angle",
      "parallel",
      "perpendicular",
      "midpoint",
      "fixed-length",
      "circle-radius",
      "circle-3-points",
      "on-circle",
      "intersect",
      "perpendicular-bisector",
      "angle-bisector",
      "tangent",
      "polar",
      "locus",
      "regular-polygon",
      "arc",
      "sector",
      "compass",
      "mirror",
      "reflect",
      "rotate",
      "dilate",
      "translate",
    ];
    if (!pickTools.includes(activeTool)) return;
    const snapped = snapBoardPoint({ x, y }, construction, geometryGraphSettings);
    const result = buildPointCreation(construction, snapped, { round: (value) => roundTo(value, 2) });
    const newPoint = result.construction.points[result.construction.points.length - 1];
    setConstruction((current) => solveConstruction({ ...current, points: [...current.points, newPoint] }, result.createdPointId));
    if (result.createdPointId) consumeGeometryToolPoint(activeTool, result.createdPointId, result.construction);
  };

  const createDefaultGeometryToolObject = (activeTool: GeometryTool, x: number, y: number) => {
    const supportedTools: GeometryTool[] = [
      "segment",
      "line",
      "ray",
      "vector",
      "circle",
      "polygon",
      "angle",
      "parallel",
      "perpendicular",
      "midpoint",
      "fixed-length",
      "circle-radius",
      "circle-3-points",
      "on-circle",
      "intersect",
      "perpendicular-bisector",
      "angle-bisector",
      "tangent",
      "polar",
      "locus",
      "regular-polygon",
      "arc",
      "sector",
      "compass",
      "mirror",
      "reflect",
      "rotate",
      "dilate",
      "translate",
      "freehand",
      "move-canvas",
      "zoom",
    ];
    if (!supportedTools.includes(activeTool)) return;
    recordWorkspaceStep("Create geometry tool object", `${activeTool} added from the board.`);
    setConstruction((current) => createGeometryObjectForTool(current, activeTool, x, y));
    setSelectedPointIds([]);
    setPolygonDraft([]);
    if (!["move-canvas", "zoom"].includes(activeTool)) setTool("select");
  };

  const createQuickGeometryObject = (shapeTool: GeometryTool, x: number, y: number) => {
    recordWorkspaceStep("Create geometry tool object", `${shapeTool} added from tool plate.`);
    setConstruction((current) => {
      const next = ((): Construction => {
      const base = current.points.length;
      const makePoint = (px: number, py: number, offset: number, style?: GeoStyle): GeoPoint => ({
        id: crypto.randomUUID(),
        x: roundTo(px, 2),
        y: roundTo(py, 2),
        label: shapeTool === "text" ? "Text" : nextPointLabel(current.points, base + offset - current.points.length),
        style,
      });
      if (shapeTool === "text") {
        return solveConstruction({ ...current, points: [...current.points, makePoint(x, y, 0, { label: "Text", color: "#f59e0b", size: 10 })] });
      }
      if (shapeTool === "triangle") {
        const points = [makePoint(x, y - 58, 0), makePoint(x - 64, y + 52, 1), makePoint(x + 64, y + 52, 2)];
        return solveConstruction({ ...current, points: [...current.points, ...points], polygons: [...current.polygons, { id: crypto.randomUUID(), points: points.map((point) => point.id) }] });
      }
      if (shapeTool === "rectangle") {
        const points = [makePoint(x - 70, y - 45, 0), makePoint(x + 70, y - 45, 1), makePoint(x + 70, y + 45, 2), makePoint(x - 70, y + 45, 3)];
        return solveConstruction({ ...current, points: [...current.points, ...points], polygons: [...current.polygons, { id: crypto.randomUUID(), points: points.map((point) => point.id), style: { fill: "rgba(14,165,233,.16)", color: "#22d3ee" } }] });
      }
      const polygonStyles: Partial<Record<GeometryTool, GeoStyle>> = {
        square: { fill: "rgba(34,197,94,.16)", color: "#22c55e" },
        "pentagon-shape": { fill: "rgba(168,85,247,.16)", color: "#a855f7" },
        hexagon: { fill: "rgba(20,184,166,.16)", color: "#14b8a6" },
        parallelogram: { fill: "rgba(249,115,22,.16)", color: "#f97316" },
        trapezoid: { fill: "rgba(234,179,8,.18)", color: "#eab308" },
        rhombus: { fill: "rgba(236,72,153,.16)", color: "#ec4899" },
        kite: { fill: "rgba(99,102,241,.16)", color: "#6366f1" },
      };
      const createPolygon = (offsets: Array<[number, number]>, label: string) => {
        const points = offsets.map(([dx, dy], index) => makePoint(x + dx, y + dy, index));
        return solveConstruction({
          ...current,
          points: [...current.points, ...points],
          polygons: [...current.polygons, { id: crypto.randomUUID(), points: points.map((point) => point.id), style: { ...polygonStyles[shapeTool], label } }],
        });
      };
      if (shapeTool === "square") {
        return createPolygon([[-58, -58], [58, -58], [58, 58], [-58, 58]], "square");
      }
      if (shapeTool === "pentagon-shape" || shapeTool === "hexagon") {
        const sides = shapeTool === "pentagon-shape" ? 5 : 6;
        const radius = shapeTool === "pentagon-shape" ? 72 : 78;
        const offsets = Array.from({ length: sides }, (_, index): [number, number] => {
          const angle = -Math.PI / 2 + index / sides * Math.PI * 2;
          return [Math.cos(angle) * radius, Math.sin(angle) * radius];
        });
        return createPolygon(offsets, shapeTool === "pentagon-shape" ? "pentagon" : "hexagon");
      }
      if (shapeTool === "parallelogram") {
        return createPolygon([[-76, -46], [52, -46], [76, 46], [-52, 46]], "parallelogram");
      }
      if (shapeTool === "trapezoid") {
        return createPolygon([[-48, -52], [48, -52], [86, 52], [-86, 52]], "trapezoid");
      }
      if (shapeTool === "rhombus") {
        return createPolygon([[0, -72], [82, 0], [0, 72], [-82, 0]], "rhombus");
      }
      if (shapeTool === "kite") {
        return createPolygon([[0, -86], [58, -10], [0, 82], [-38, -10]], "kite");
      }
      if (shapeTool === "shape-circle") {
        const center = makePoint(x, y, 0);
        const edge = makePoint(x + 72, y, 1);
        return solveConstruction({ ...current, points: [...current.points, center, edge], circles: [...current.circles, { id: crypto.randomUUID(), center: center.id, edge: edge.id }] });
      }
      const curvePoints = Array.from({ length: 48 }, (_, index) => {
        const t = ((index / 47) * 2 - 1);
        if (shapeTool === "semicircle") return { x: x + t * 96, y: y - Math.sqrt(Math.max(0, 1 - t * t)) * 72 + 36 };
        if (shapeTool === "parabola") return { x: x + t * 120, y: y + t * t * 90 - 60 };
        if (shapeTool === "ellipse") return { x: x + Math.cos(index / 47 * Math.PI * 2) * 110, y: y + Math.sin(index / 47 * Math.PI * 2) * 62 };
        return { x: x + t * 125, y: y + (t === 0 ? 0 : 42 / t) };
      });
      return solveConstruction({ ...current, loci: [...current.loci, { id: crypto.randomUUID(), label: shapeTool, points: curvePoints, style: { color: shapeTool === "ellipse" ? "#22d3ee" : shapeTool === "hyperbola" ? "#f97316" : shapeTool === "semicircle" ? "#10b981" : "#a78bfa", strokeWidth: 4 } }] });
      })();
      const created = createdGeometryFromDelta(current, next);
      Promise.resolve().then(() => {
        if (created.object) setSelectedGeometry(created.object);
        if (created.pointIds.length) setSelectedPointIds(created.pointIds);
      });
      return next;
    });
    setTool("select");
  };

  const handleGeometryContextMenu = (event: PointerEvent<SVGSVGElement>) => {
    if (controlsLocked) return;
    const target = event.target as Element;
    const pointId = target.getAttribute("data-point-id");
    const objectType = (target.getAttribute("data-object-type") as GeometryObjectType | null) ?? (pointId ? "point" : null);
    const objectId = target.getAttribute("data-object-id") ?? pointId;
    if (!objectType || !objectId) return;
    event.preventDefault();
    const targetObject = { type: objectType, id: objectId };
    setSelectedGeometry(targetObject);
    setContextMenu({ x: event.clientX, y: event.clientY, target: targetObject });
  };

  const handlePointPick = (pointId: string) => {
    if (consumeGeometryToolPointWithObjectPick(tool, pointId, construction)) return;
    consumeGeometryToolPoint(tool, pointId, construction);
  };

  const consumeGeometryToolPointWithObjectPick = (activeTool: GeometryTool, pointId: string, constructionContext: Construction) => {
    const pickedObject = geometryObjectPicks[0];
    if (!pickedObject) return false;
    if ((activeTool === "parallel" || activeTool === "perpendicular") && pickedObject.type === "line") {
      recordWorkspaceStep(`Create ${activeTool}`, `${geometryObjectLabel(constructionContext, pickedObject)} through ${labelForPoint(constructionContext, pointId)}`);
      setConstruction((current) => {
        const result = activeTool === "parallel"
          ? buildParallelConstruction(current, pickedObject.id, pointId)
          : buildPerpendicularConstruction(current, pickedObject.id, pointId);
        return solveConstruction(result.construction);
      });
      setGeometryObjectPicks([]);
      setSelectedPointIds([]);
      return true;
    }
    if (activeTool === "on-circle" && pickedObject.type === "circle") {
      recordWorkspaceStep("Constrain point to circle", `${labelForPoint(constructionContext, pointId)} on ${geometryObjectLabel(constructionContext, pickedObject)}`);
      setConstruction((current) => solveConstruction(buildPointOnCircleConstraint(current, pointId, pickedObject.id).construction, pointId));
      setGeometryObjectPicks([]);
      setSelectedPointIds([]);
      return true;
    }
    if ((activeTool === "tangent" || activeTool === "polar") && pickedObject.type === "circle") {
      recordWorkspaceStep(`Create ${activeTool}`, `${labelForPoint(constructionContext, pointId)} with ${geometryObjectLabel(constructionContext, pickedObject)}`);
      setConstruction((current) => activeTool === "tangent" ? addTangentAtPoint(current, pointId, pickedObject.id) : addPolarLine(current, pointId, pickedObject.id));
      setGeometryObjectPicks([]);
      setSelectedPointIds([]);
      return true;
    }
    return false;
  };

  const consumeGeometryToolObject = (activeTool: GeometryTool, object: SelectedGeometryObject, constructionContext: Construction) => {
    setSelectedGeometry(object);
    const transformMode = geometryTransformToolMode(activeTool);
    if (transformMode) {
      const ids = pointIdsForObject(constructionContext, object);
      if (ids.length && applyGeometryFigureTransform(transformMode, ids)) {
        setTool("select");
        return;
      }
    }
    if (activeTool === "intersect" && (object.type === "line" || object.type === "circle")) {
      const next = [...geometryObjectPicks.filter((item) => !(item.type === object.type && item.id === object.id)), object].slice(-2);
      setGeometryObjectPicks(next);
      if (next.length === 2) {
        recordWorkspaceStep("Create selected intersections", `${geometryObjectLabel(constructionContext, next[0])} with ${geometryObjectLabel(constructionContext, next[1])}`);
        setConstruction((current) => solveConstruction(buildIntersectionConstruction(current, next[0].id, next[1].id, { firstType: next[0].type as "line" | "circle", secondType: next[1].type as "line" | "circle" }).construction));
        setGeometryObjectPicks([]);
      }
      return;
    }
    if ((activeTool === "parallel" || activeTool === "perpendicular") && object.type === "line") {
      setGeometryObjectPicks([object]);
      setSelectedPointIds([]);
      setProjectStatus(`${geometryObjectLabel(constructionContext, object)} picked. Pick a point for the through-point.`);
      return;
    }
    if (activeTool === "on-circle" && object.type === "circle") {
      setGeometryObjectPicks([object]);
      setSelectedPointIds([]);
      setProjectStatus(`${geometryObjectLabel(constructionContext, object)} picked. Pick a point to constrain on it.`);
      return;
    }
    if ((activeTool === "tangent" || activeTool === "polar") && object.type === "circle") {
      setGeometryObjectPicks([object]);
      setSelectedPointIds([]);
      setProjectStatus(`${geometryObjectLabel(constructionContext, object)} picked. Pick a point for ${activeTool}.`);
      return;
    }
    setProjectStatus(`${geometryToolLabel(activeTool)} needs a ${geometryToolExpectedPick(activeTool)}.`);
  };

  const consumeGeometryToolPoint = (activeTool: GeometryTool, pointId: string, constructionContext: Construction) => {
