  };

  const activeFunctionPlot = plots.find((plot) => plot.visible !== false && (plot.kind ?? inferPlotKind(plot.expression)) === "function") ?? plots[0];
  const selectedCasCell = casNotebookState.cells.find((cell) => cell.id === selectedCasCellId) ?? casNotebookState.cells.find((cell) => cell.output) ?? casNotebookState.cells[0];
  const casNotebookExport = useMemo(() => serializeCasNotebookMarkdown(casNotebookState), [casNotebookState]);
  const commitCasNotebook = (next: NotebookState) => {
    setCasUndoStack((current) => [casNotebookState, ...current].slice(0, 40));
    setCasRedoStack([]);
    setCasNotebookState(next);
  };
  const updateCasCell = (id: string, patch: Partial<NotebookCell>) => {
    const cells = casNotebookState.cells.map((cell) => (cell.id === id ? { ...cell, ...patch } : cell));
    commitCasNotebook({ ...casNotebookState, cells: evaluateNotebookCells(cells, casNotebookState.assumptions, casNotebookState.mode) });
  };
  const runCasCell = (id: string) => {
    setSelectedCasCellId(id);
    commitCasNotebook({ ...casNotebookState, cells: evaluateNotebookCellInState(id, casNotebookState.cells, casNotebookState.assumptions, casNotebookState.mode) });
  };
  const runCasNotebook = () => {
    commitCasNotebook({ ...casNotebookState, cells: evaluateNotebookCells(casNotebookState.cells, casNotebookState.assumptions, casNotebookState.mode) });
  };
  const addCasCell = (input = casComposerInput, operation = casComposerOperation) => {
    const nextCell = createNotebookCell(input, operation);
    setSelectedCasCellId(nextCell.id);
    const cells = [nextCell, ...casNotebookState.cells].slice(0, 40);
    commitCasNotebook({ ...casNotebookState, cells: evaluateNotebookCells(cells, casNotebookState.assumptions, casNotebookState.mode) });
  };
  const duplicateCasCell = (cell: NotebookCell) => addCasCell(cell.input, cell.operation);
  const deleteCasCell = (id: string) => {
    commitCasNotebook({ ...casNotebookState, cells: casNotebookState.cells.filter((cell) => cell.id !== id) });
    setSelectedCasCellId((current) => current === id ? null : current);
  };
  const reorderCasCells = (orderedIds: string[]) => {
    const byId = new Map(casNotebookState.cells.map((cell) => [cell.id, cell]));
    const cells = orderedIds.map((id) => byId.get(id)).filter((cell): cell is NotebookCell => Boolean(cell));
    if (cells.length === casNotebookState.cells.length) commitCasNotebook({ ...casNotebookState, cells });
  };
  const resetCasNotebook = () => {
    const next = createDefaultCasNotebookState();
    commitCasNotebook(next);
    setSelectedCasCellId(next.cells[0]?.id ?? null);
  };
  const setCasMode = (mode: EvaluationMode) => commitCasNotebook({ ...casNotebookState, mode, cells: evaluateNotebookCells(casNotebookState.cells, casNotebookState.assumptions, mode) });
  const setCasAssumptions = (assumptions: string) => commitCasNotebook({ ...casNotebookState, assumptions, cells: evaluateNotebookCells(casNotebookState.cells, assumptions, casNotebookState.mode) });
  const sendCasCellToGraph = (cell: NotebookCell) => {
    const expression = graphableExpressionFromCasCell(cell);
    const payload = createMathWorkspacePayload({
      sourceWorkspace: "cas",
      objectType: "expression",
      label: cell.input || "CAS expression",
      value: expression,
      metadata: { operation: cell.operation },
    });
    saveWorkspaceTransfer(payload, "graphs");
    navigate("/workspace/graph", {
      state: { mathWorkspacePayload: payload },
    });
  };

  const resizeSelectedGeometry = (direction: "increase" | "decrease") => {
    const selection = resolveSelectedGeometryObject();
    if (!selection) {
      setProjectStatus("Select a 2D geometry object before resizing.");
      return;
    }
    if (lockedGeometryIds.includes(selection.id)) {
      setProjectStatus("Selected geometry object is locked.");
      return;
    }
    setSelectedGeometry(selection);
    const factor = direction === "increase" ? 1.12 : 0.88;
    recordWorkspaceStep("Resize geometry object", `${geometryObjectLabel(construction, selection)} ${direction === "increase" ? "enlarged" : "reduced"}.`);
    if (selection.type === "point") {
      const point = pointById(construction.points, selection.id);
      const currentSize = point?.style?.size ?? 1;
      updateSelectedGeometryStyle({ ...(point?.style ?? {}), size: roundTo(Math.max(0.4, Math.min(3.5, currentSize * factor)), 2) });
      setProjectStatus(`${point?.label ?? "Point"} marker resized.`);
      return;
    }
    setConstruction((current) => resizeGeometryObjectInConstruction(current, selection, factor));
    setProjectStatus(`${geometryObjectLabel(construction, selection)} resized.`);
  };
  const exportCasNotebook = () => {
    const blob = new Blob([casNotebookExport], { type: "text/markdown;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "computer-algebra-studio.md";
    link.click();
    URL.revokeObjectURL(url);
  };
  const runDataCommand = (command: string) => {
    setInput(command);
    const analysis = interpretInput(command);
    setResults((current) => [analysis, ...current].slice(0, 12));
    if (analysis.graphExpression) {
      setCasExpression(stripInequality(analysis.graphExpression));
      setPlots((current) => [{ id: crypto.randomUUID(), expression: analysis.graphExpression!, color: colors[current.length % colors.length], kind: inferPlotKind(analysis.graphExpression!), visible: true }, ...current].slice(0, 10));
    }
  };
  const _addSpreadsheetScatter = (points: ResultTableRow[]) => {
    recordWorkspaceStep("Add spreadsheet scatter", `${points.length} spreadsheet points linked to graph.`);
    setPlots((current) => [{ id: crypto.randomUUID(), expression: "spreadsheet data", color: "#ec4899", kind: "scatter" as PlotKind, points, visible: true }, ...current].slice(0, 10));
  };
  const _addSpreadsheetRegression = (model: RegressionModel, points: ResultTableRow[]) => {
    const regression = regressionModel(points, model);
    recordWorkspaceStep("Add spreadsheet regression", `${model} regression from spreadsheet.`);
    setPlots((current) => [{ id: crypto.randomUUID(), expression: regression.expression, color: "#14b8a6", kind: "regression" as PlotKind, points, visible: true }, ...current].slice(0, 10));
    setResults((current) => [{ id: crypto.randomUUID(), input: `${model} regression`, interpretation: "Spreadsheet regression", result: regression.expression, detail: regression.detail, table: points.slice(0, 12), graphExpression: regression.expression }, ...current].slice(0, 12));
  };
  const dataOverviewCards = [
    { title: "Spreadsheet", text: "Editable cells, formulas, scatter plots, and regression.", route: "/workspace/data/spreadsheet", concept: "Tables" },
    { title: "Function Analysis", text: "Roots, extrema, intercepts, derivative, integral, and table commands.", route: "/workspace/data/analysis", concept: "Functions" },
    { title: "CAS Workbench", text: "Exact algebra actions for simplify, factor, solve, limits, substitution, and systems.", route: "/workspace/data/cas", concept: "Algebra" },
    { title: "Results", text: "Exact results, numeric checks, and generated tables.", route: "/workspace/data/results", concept: "Solutions" },
    { title: "Object Registry", text: "Shared graph, CAS, table, spreadsheet, geometry, and 3D objects.", route: "/workspace/data/objects", concept: "Linked Objects" },
  ];

  const singleViewCasStudio = singleView && workspaceView === "data" && dataPage === "cas";
  const singleViewSpreadsheetStudio = singleView && workspaceView === "data" && dataPage === "spreadsheet";
  const singleViewStudio = singleView && (workspaceView === "graph" || workspaceView === "3d" || workspaceView === "geometry" || singleViewCasStudio || singleViewSpreadsheetStudio);
  const workspaceRootClass = `relative ${singleViewStudio ? `${workspaceView === "graph" ? "math-workspace-single-graph min-h-full" : "h-full min-h-0 overflow-hidden"}` : singleView ? "space-y-2 pt-0" : "space-y-2 pt-14 xl:pt-12"}`;
  const portableWorkspaceType: PortableWorkspaceType = workspaceView === "geometry" ? "2d-geometry" : workspaceView === "3d" ? "3d-geometry" : singleViewCasStudio ? "cas" : "2d-graph";
  const portableAdapter: PortableWorkspaceAdapter = {
    workspaceType: portableWorkspaceType,
    engine: portableWorkspaceType === "cas" ? "math-universe-symbolic-notebook" : portableWorkspaceType === "2d-graph" ? "math-universe-graph-workspace" : portableWorkspaceType === "3d-geometry" ? "math-universe-three-workspace" : "math-universe-geometry-workspace",
    engineVersion: "1.0.2",
    title: () => portableWorkspaceType === "cas" ? "Computer Algebra Studio" : portableWorkspaceType === "2d-graph" ? "2D Graph Workspace" : portableWorkspaceType === "3d-geometry" ? "3D Geometry Workspace" : "2D Geometry Workspace",
    serializeScene: () => ({
      workspaceSnapshot: snapshot(),
      ...(portableWorkspaceType === "2d-geometry" ? { geometryCamera } : {}),
      ...(portableWorkspaceType === "2d-graph" ? { linkedParameters: readLinkedParameters() } : {}),
      ...(portableWorkspaceType === "cas" ? { casNotebookState, selectedCasCellId, composerInput: casComposerInput, composerOperation: casComposerOperation } : {}),
      workspaceType: portableWorkspaceType,
    }),
    deserializeScene: (scene) => {
      if (!scene || typeof scene !== "object") throw new Error("The imported scene is missing or invalid.");
      const record = scene as { workspaceSnapshot?: WorkspaceSnapshot; linkedParameters?: Record<string, { name?: string; value?: number; min?: number; max?: number; step?: number; integer?: boolean }>; casNotebookState?: NotebookState; selectedCasCellId?: string | null; composerInput?: string; composerOperation?: NotebookOperation };
      if (!record.workspaceSnapshot) throw new Error("The imported scene does not contain a compatible workspace snapshot.");
      restoreWorkspaceSnapshot(record.workspaceSnapshot);
      if (portableWorkspaceType === "2d-graph" && record.linkedParameters && typeof record.linkedParameters === "object") {
        Object.entries(record.linkedParameters).slice(0, 100).forEach(([key, parameter]) => {
          const name = String(parameter.name ?? key).replace(/[^A-Za-z0-9_]/g, "").slice(0, 32);
          const value = Number(parameter.value), min = Number(parameter.min), max = Number(parameter.max), step = Number(parameter.step);
          if (name && [value, min, max, step].every(Number.isFinite) && min <= max && step > 0) saveLinkedParameter({ name, value: Math.min(max, Math.max(min, value)), min, max, step, integer: Boolean(parameter.integer) });
        });
      }
      if (portableWorkspaceType === "cas" && record.casNotebookState?.cells && Array.isArray(record.casNotebookState.cells)) {
        const assumptions = String(record.casNotebookState.assumptions ?? "").slice(0, 2_000);
        const mode: EvaluationMode = record.casNotebookState.mode === "numeric" ? "numeric" : "exact";
        const cells = record.casNotebookState.cells.slice(0, 200).map(cell => ({ ...cell, input: String(cell.input ?? "").slice(0, 20_000) }));
        setCasNotebookState({ assumptions, mode, cells: evaluateNotebookCells(cells, assumptions, mode) });
        setSelectedCasCellId(record.selectedCasCellId ?? cells[0]?.id ?? null);
        setCasComposerInput(String(record.composerInput ?? "").slice(0, 20_000));
        if (record.composerOperation && operationOptions.some(option => option.value === record.composerOperation)) setCasComposerOperation(record.composerOperation);
      }
      setProjectStatus("Portable workspace restored.");
    },
    validateScene: (scene) => !scene || typeof scene !== "object" || !("workspaceSnapshot" in scene) ? ["The imported scene does not contain a compatible workspace snapshot."] : [],
    getImageTarget: (scope) => {
      if (portableWorkspaceType === "2d-geometry") return geometryExportRef.current ?? workspaceRef.current;
      if (portableWorkspaceType === "2d-graph") return graphExportRef.current ?? workspaceRef.current;
      if (portableWorkspaceType === "cas") return workspaceRef.current?.querySelector(scope === "entire" ? ".cas-notebook-scroll" : ".cas-studio-center") as HTMLElement | null;
      const canvas = workspaceRef.current?.querySelector("canvas");
      return canvas?.parentElement ?? workspaceRef.current;
    },
    getSceneSummary: () => portableWorkspaceType === "cas"
      ? { objectCount: casNotebookState.cells.length, expressionCount: casNotebookState.cells.length, description: `${casNotebookState.cells.length} CAS calculations` }
      : portableWorkspaceType === "2d-graph"
        ? { objectCount: plots.length, expressionCount: plots.length, description: `${plots.length} plotted expressions` }
        : portableWorkspaceType === "3d-geometry"
          ? { objectCount: Object.keys(transforms3d).length + added3dObjects.length - deletedBase3dIds.length, expressionCount: showSurface ? 1 : 0, description: `${added3dObjects.length} added 3D objects` }
          : { objectCount: construction.points.length + construction.lines.length + construction.circles.length + construction.polygons.length, expressionCount: 0, description: `${construction.points.length} points and ${construction.lines.length + construction.circles.length + construction.polygons.length} constructions` },
    canMerge: false,
  };

  // Embedded activities hydrate only their own scene and never consume another
  // workspace's pending transfer or save over the standalone project.
  const embeddedHydrated = useRef(false);
  const embeddedCallback = useRef(embedded?.onSceneChange);
  embeddedCallback.current = embedded?.onSceneChange;
  useEffect(() => {
    const routeScene = (location.state as { embeddedWorkspaceScene?: unknown } | null)?.embeddedWorkspaceScene;
    if (!embedded && !routeScene) return;
    let scene = embedded?.initialScene ?? routeScene;
    if (embedded) {
      try { const saved = localStorage.getItem(`geometry-studio-workspace:${embedded.activityId}`); if (saved) scene = JSON.parse(saved); } catch { /* Use the supplied example if storage is unavailable or invalid. */ }
    }
    if (!scene || typeof scene !== "object" || !("workspaceSnapshot" in scene)) return;
    const record = scene as { workspaceSnapshot: WorkspaceSnapshot; geometryCamera?: GeometryCamera };
    if (!record.workspaceSnapshot || typeof record.workspaceSnapshot !== "object") return;
    restoreWorkspaceSnapshot(record.workspaceSnapshot);
    if (record.geometryCamera) setGeometryCamera(record.geometryCamera);
    embeddedHydrated.current = true;
    // The host remounts the workspace when changing activities or resetting.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [embedded?.activityId]);
  useEffect(() => {
    if (!embedded || !embeddedHydrated.current) return;
    const timeout = window.setTimeout(() => {
      const scene = { workspaceSnapshot: snapshot(), geometryCamera, workspaceType: portableWorkspaceType };
      try { localStorage.setItem(`geometry-studio-workspace:${embedded.activityId}`, JSON.stringify(scene)); } catch { /* The workspace remains editable without storage. */ }
      embeddedCallback.current?.(scene);
    }, 120);
    return () => window.clearTimeout(timeout);
    // Persist the scene fields used by geometry activities, including clearing.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [embedded?.activityId, construction, geometryCamera, geometryGraphSettings, workspaceImages, transforms3d, solid, surface, surfaceExpression, surfaceScale, height3d, crossSection, showSurface, showSolid, added3dObjects, deletedBase3dIds]);

  const openPortableWorkspaceImport = () => {
    if (portableImportInputRef.current) portableImportInputRef.current.value = "";
    portableImportInputRef.current?.click();
  };

  const importPortableWorkspaceFile = async (file: File | null) => {
    if (!file) return;
    setProjectStatus("Validating workspace file…");
    try {
      const result = await parsePortableMathFile(await file.text(), file.name, file.type);
      if (!result.ok) {
        setProjectStatus(result.error);
        return;
      }
      if (result.file.workspace.type !== portableAdapter.workspaceType) {
        setProjectStatus(`This file belongs to ${result.file.workspace.type}, not ${portableAdapter.workspaceType}.`);
        return;
      }
      const mode = result.file.lesson?.openMode ?? "practice";
      const scene = sceneForLessonMode(result.file, mode);
      const warnings = portableAdapter.validateScene?.(scene) ?? [];
      if (warnings.length) {
        setProjectStatus(warnings[0]);
        return;
      }
      await portableAdapter.deserializeScene(scene, "replace");
      setProjectStatus(`${result.file.document.title} imported successfully${result.warnings.length ? ` with ${result.warnings.length} warning${result.warnings.length === 1 ? "" : "s"}` : ""}.`);
    } catch (error) {
      setProjectStatus(error instanceof Error ? error.message : "The workspace file could not be imported.");
    } finally {
      if (portableImportInputRef.current) portableImportInputRef.current.value = "";
    }
  };

  return (
    <div ref={workspaceRef} className={workspaceRootClass}>
      <input
        ref={portableImportInputRef}
        type="file"
        className="hidden"
        accept={`${WORKSPACE_EXTENSION},${LESSON_EXTENSION},application/vnd.mathapp.workspace,application/vnd.mathapp.lesson,application/json`}
        aria-label="Import workspace file"
        onChange={(event) => void importPortableWorkspaceFile(event.target.files?.[0] ?? null)}
      />

      {!singleViewStudio && <WorkspaceMainMenu active={workspaceView} onChange={setWorkspaceView} docked={singleView} />}
      {!singleView && <TopicHeader title="Math Workspace" subtitle="A unified workspace for graphing, commands, results, and dynamic geometric construction." difficulty="All levels" estimatedMinutes={45} />}

      {!singleView && <WorkspaceModeTabs active={workspaceView} onChange={setWorkspaceView} />}
      {!singleViewStudio && <CompactWorkspaceBar
        activeTemplate={activeTemplate}
        teachingMode={teachingMode}
        compact={singleView}
        onSave={saveWorkspace}
        onLoad={loadWorkspace}
        onUndo={undoWorkspace}
        onRedo={redoWorkspace}
        onExportJson={exportWorkspaceJson}
        onExportPng={exportGeometryPng}
        onShare={exportShareUrl}
        onToggleTeach={() => {
          setTeachingMode((value) => !value);
          setWorkspaceView("teach");
        }}
      />}
      {!singleView && workspaceView !== "3d" && <WorkspaceShortcutStrip />}

      {workspaceView === "teach" && <SectionCard title="Teaching, Library, And Export" description="Launch syllabus workspaces, guide students, present steps, and manage browser-only projects.">
        <div data-testid="workspace-teacher-surface">
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]">
          <div className="space-y-4">
            <div className="flex flex-wrap gap-2">
              <button type="button" onClick={saveWorkspace} className="action-secondary"><Save className="h-4 w-4" />Save workspace</button>
              <button type="button" onClick={loadWorkspace} className="action-secondary"><Download className="h-4 w-4" />Load workspace</button>
              <button type="button" onClick={saveProjectToLibrary} className="action-secondary"><Save className="h-4 w-4" />Save offline</button>
              <button type="button" onClick={exportWorkspaceJson} className="action-secondary"><Download className="h-4 w-4" />Export JSON</button>
              <button type="button" onClick={exportResultsCsv} className="action-secondary"><Download className="h-4 w-4" />Export CSV</button>
              <button type="button" onClick={exportGeometryPng} className="action-secondary"><Download className="h-4 w-4" />Export PNG</button>
              <button type="button" onClick={exportGeometrySvg} className="action-secondary"><Download className="h-4 w-4" />Export geometry SVG</button>
              <button type="button" onClick={exportWorksheetPdf} className="action-secondary"><Download className="h-4 w-4" />Worksheet PDF</button>
              <button type="button" onClick={exportLessonPack} className="action-secondary"><Download className="h-4 w-4" />Lesson pack</button>
              <button type="button" onClick={exportActivityJournal} className="action-secondary"><Download className="h-4 w-4" />Journal CSV</button>
              <button type="button" onClick={exportShareUrl} className="action-secondary"><Download className="h-4 w-4" />Share URL</button>
              <button type="button" onClick={copyTeacherPresentationUrl} className="action-secondary"><Presentation className="h-4 w-4" />Teacher link</button>
              <button type="button" onClick={() => setTeachingMode((value) => !value)} className={teachingMode ? "action-primary" : "action-secondary"}><Presentation className="h-4 w-4" />Teaching mode</button>
              <button type="button" onClick={undoWorkspace} className="action-secondary"><RotateCcw className="h-4 w-4" />Undo {undoStack[0]?.label ?? "change"}</button>
              <button type="button" onClick={redoWorkspace} className="action-secondary"><RotateCcw className="h-4 w-4" />Redo {redoStack[0]?.label ?? "change"}</button>
            </div>
            <SyllabusTemplatePanel templates={syllabusWorkspaceTemplates} active={activeTemplate.id} onApply={applyTemplate} />
            <GuidedActivityPanel active={guidedMode} phase={guidedPhase} template={activeTemplate} journal={activityJournal} onToggle={() => setGuidedMode((value) => !value)} onPhase={setGuidedPhase} onJournal={updateGuidedActivityEntry} onCompletePhase={markGuidedPhaseComplete} />
            <TeacherLessonStudio
              lesson={classroomLesson}
              report={practiceReport}
              responses={practiceResponses}
              onLessonChange={updateLesson}
              onStepChange={updateLessonStep}
              onResponseChange={(stepId, answer) => setPracticeResponses((current) => ({ ...current, [stepId]: { stepId, answer } }))}
              onCheck={checkLessonStep}
              onLaunchCommand={runGuidedExample}
              onAddStep={addLessonStep}
              onDuplicateStep={duplicateLessonStep}
              onRemoveStep={removeLessonStep}
              onExport={exportPracticeReport}
            />
            <TeacherPresentationPanel active={teachingMode} locked={controlsLocked} revealStep={revealStep} lesson={classroomLesson} template={activeTemplate} notes={presentationNotes} responses={practiceResponses} report={practiceReport} journal={activityJournal} onToggle={setTeachingMode} onLock={setControlsLocked} onReveal={setRevealStep} onNotes={setPresentationNotes} onCopyLink={copyTeacherPresentationUrl} />
            <OfflineProjectLibraryPanel projects={projectLibrary} onSave={saveProjectToLibrary} onRestore={restoreProject} onDelete={deleteProject} onClear={clearProjects} />
            {teachingMode && (
              <div className="rounded-2xl bg-cyan-50 p-4 text-sm leading-6 text-slate-700 dark:bg-cyan-400/10 dark:text-cyan-50">
                <p className="font-bold">Teacher presentation mode is active</p>
                <p>{controlsLocked ? "Student-facing controls are locked for explanation and reveal steps." : "Controls are open for live manipulation and discussion."}</p>
              </div>
            )}
            <div>
              <h3 className="font-bold">Guided Examples</h3>
              <div className="mt-3 grid gap-2 md:grid-cols-2">
                {guidedExamples.map((example) => <button key={example.title} type="button" onClick={() => runGuidedExample(example.command)} className="rounded-2xl border border-slate-200 bg-white/70 p-4 text-left transition hover:border-cyan-300 dark:border-white/10 dark:bg-white/5"><p className="font-semibold">{example.title}</p><p className="mt-1 font-mono text-xs text-slate-500 dark:text-slate-400">{example.command}</p></button>)}
              </div>
            </div>
          </div>
          <div>
            <label className="block">
              <span className="flex items-center gap-2 text-sm font-semibold"><Search className="h-4 w-4 text-cyan-500" />Formula Library</span>
              <input value={formulaSearch} onChange={(event) => setFormulaSearch(event.target.value)} className="mt-2 w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm dark:border-white/10 dark:bg-slate-950" placeholder="Search formula, topic, command..." />
            </label>
            <div className="mt-3 max-h-[360px] space-y-2 overflow-y-auto pr-1">
              {filteredFormulas.map((item) => (
                <button key={item.title} type="button" onClick={() => setInput(item.command)} className="w-full rounded-2xl bg-slate-100 p-3 text-left transition hover:bg-cyan-100 dark:bg-white/10 dark:hover:bg-cyan-300/15">
                  <p className="text-xs font-bold uppercase text-cyan-600 dark:text-cyan-300">{item.topic}</p>
                  <p className="mt-1 font-semibold">{item.title}</p>
                  <p className="mt-1 text-xs font-semibold text-slate-600 dark:text-slate-300">
                    <MathExpression value={item.formula} />
                  </p>
                </button>
              ))}
            </div>
          </div>
        </div>
        </div>
      </SectionCard>}

      {workspaceView === "graph" && <SectionCard title="Graph, CAS, And Algebra" description="Type commands, graph expressions, inspect results, and manage objects in focused tabs." compact={singleView} className={singleView ? "graph-workspace-card" : undefined} visualizationTools={singleView ? false : "auto"}>
        <div className="graph-workspace-tabs mb-3 mobile-safe-scroll thin-scrollbar">
          <span className="sr-only">Workspace command keyboard</span>
          <div className="inline-flex min-w-full gap-1.5 rounded-xl border border-slate-200 bg-white/80 p-1 dark:border-white/10 dark:bg-white/5 md:min-w-0">
            {[
              { id: "graph" as const, label: "Graph", icon: <LineChart className="h-4 w-4" /> },
              { id: "command" as const, label: "Command", icon: <FunctionSquare className="h-4 w-4" /> },
              { id: "results" as const, label: `Results ${results.length}`, icon: <Search className="h-4 w-4" /> },
              { id: "objects" as const, label: `${unifiedWorkspaceObjects.length} Objects`, icon: <Box className="h-4 w-4" /> },
              { id: "algebra" as const, label: "Algebra", icon: <ListTree className="h-4 w-4" /> },
            ].map((tab) => (
              <button
                key={tab.id}
                type="button"
                onClick={() => setGraphWorkspaceTab(tab.id)}
                className={`inline-flex min-h-10 shrink-0 items-center justify-center gap-2 rounded-lg px-3 text-sm font-black transition ${graphWorkspaceTab === tab.id ? "bg-cyan-500 text-white shadow-sm dark:bg-cyan-300 dark:text-slate-950" : "text-slate-500 hover:bg-cyan-50 hover:text-cyan-800 dark:text-slate-300 dark:hover:bg-cyan-300/10 dark:hover:text-cyan-100"}`}
              >
                {tab.icon}
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        {graphWorkspaceTab === "graph" && (
          <div ref={graphExportRef} className="graph-workspace-panel-host">
            <GraphWorkspacePanel
              plots={plots}
              colors={colors}
              regressionSeed={regressionSeed}
              onChange={handlePlotsChange}
              tableRange={{ start: tableStart, end: tableEnd, step: tableStep }}
              onTableRangeChange={({ start, end, step }) => {
                setTableStart(start);
                setTableEnd(end);
                setTableStep(step);
