function setGeometryTrace(construction: Construction, object: SelectedGeometryObject, enabled: boolean): Construction {
  const styled = patchGeometryObject(construction, object, { style: { ...(geometryObjectBySelection(construction, object)?.style ?? {}), trace: enabled } });
  if (object.type !== "point") return styled;
  const point = pointById(styled.points, object.id);
  if (!point) return styled;
  if (!enabled) {
    return {
      ...styled,
      loci: styled.loci.map((locus) => locus.sourcePointId === object.id && locus.mode === "trace" ? { ...locus, style: { ...(locus.style ?? {}), trace: false } } : locus),
    };
  }
  const existingIndex = styled.loci.findIndex((locus) => locus.sourcePointId === object.id && locus.mode === "trace");
  if (existingIndex >= 0) {
    return {
      ...styled,
      loci: styled.loci.map((locus, index) => index === existingIndex ? {
        ...locus,
        points: appendTraceSample(locus.points, point, { maxSamples: locus.maxSamples }),
        style: { ...(locus.style ?? {}), trace: true, visible: true },
      } : locus),
    };
  }
  const traceLocus: GeoLocus = {
    id: crypto.randomUUID(),
    label: nextTraceLabel(styled.loci.filter((locus) => locus.mode === "trace").length, point.label),
    sourcePointId: point.id,
    mode: "trace",
    maxSamples: DEFAULT_TRACE_MAX_SAMPLES,
    points: seedTraceSamples(point),
    style: { color: point.style?.color ?? "#ec4899", strokeWidth: 4, trace: true, opacity: 0.82 },
  };
  return {
    ...styled,
    loci: [...styled.loci, traceLocus],
  };
}

function recordTraceSampleForPoint(construction: Construction, pointId: string): Construction {
  const point = pointById(construction.points, pointId);
  if (!point?.style?.trace) return construction;
  const traceExists = construction.loci.some((locus) => locus.sourcePointId === pointId && locus.mode === "trace");
  const withTrace = traceExists ? construction : setGeometryTrace(construction, { type: "point", id: pointId }, true);
  return {
    ...withTrace,
    loci: withTrace.loci.map((locus) => locus.sourcePointId === pointId && locus.mode === "trace" && locus.style?.trace !== false ? {
      ...locus,
      points: appendTraceSample(locus.points, point, { maxSamples: locus.maxSamples }),
      style: { ...(locus.style ?? {}), visible: true },
    } : locus),
  };
}

function clearTracePaths(construction: Construction): Construction {
  return {
    ...construction,
    points: construction.points.map((point) => ({ ...point, style: { ...(point.style ?? {}), trace: false } })),
    lines: construction.lines.map((line) => ({ ...line, style: { ...(line.style ?? {}), trace: false } })),
    circles: construction.circles.map((circle) => ({ ...circle, style: { ...(circle.style ?? {}), trace: false } })),
    polygons: construction.polygons.map((polygon) => ({ ...polygon, style: { ...(polygon.style ?? {}), trace: false } })),
    arcs: construction.arcs.map((arc) => ({ ...arc, style: { ...(arc.style ?? {}), trace: false } })),
    loci: construction.loci.filter((locus) => locus.mode !== "trace").map((locus) => ({ ...locus, style: { ...(locus.style ?? {}), trace: false } })),
  };
}

function duplicateGeometryObjectInConstruction(construction: Construction, object: SelectedGeometryObject) {
  const sourcePointIds = pointIdsForObject(construction, object);
  const pointMap = new Map<string, string>();
  const copiedPoints = sourcePointIds.map((id, index) => {
    const point = pointById(construction.points, id);
    if (!point) return null;
    const nextId = crypto.randomUUID();
    pointMap.set(id, nextId);
    return { ...point, id: nextId, x: point.x + 28, y: point.y + 28, label: nextPointLabel(construction.points, index), style: { ...(point.style ?? {}) } };
  }).filter(Boolean) as GeoPoint[];
  if (object.type === "point") return solveConstruction({ ...construction, points: [...construction.points, ...copiedPoints] });
  if (object.type === "line") {
    const line = construction.lines.find((item) => item.id === object.id);
    if (!line) return construction;
    return solveConstruction({ ...construction, points: [...construction.points, ...copiedPoints], lines: [...construction.lines, { ...line, id: crypto.randomUUID(), a: pointMap.get(line.a) ?? line.a, b: pointMap.get(line.b) ?? line.b, style: { ...(line.style ?? {}) } }] });
  }
  if (object.type === "circle") {
    const circle = construction.circles.find((item) => item.id === object.id);
    if (!circle) return construction;
    return solveConstruction({ ...construction, points: [...construction.points, ...copiedPoints], circles: [...construction.circles, { ...circle, id: crypto.randomUUID(), center: pointMap.get(circle.center) ?? circle.center, edge: pointMap.get(circle.edge) ?? circle.edge, style: { ...(circle.style ?? {}) } }] });
  }
  if (object.type === "arc") {
    const arc = construction.arcs.find((item) => item.id === object.id);
    if (!arc) return construction;
    return solveConstruction({ ...construction, points: [...construction.points, ...copiedPoints], arcs: [...construction.arcs, { ...arc, id: crypto.randomUUID(), center: pointMap.get(arc.center) ?? arc.center, start: pointMap.get(arc.start) ?? arc.start, end: pointMap.get(arc.end) ?? arc.end, style: { ...(arc.style ?? {}) } }] });
  }
  if (object.type === "locus") {
    const locus = construction.loci.find((item) => item.id === object.id);
    const copiedLocus: GeoLocus | null = locus ? {
      ...locus,
      id: crypto.randomUUID(),
      label: `${locus.label}'`,
      mode: "static",
      sourcePointId: undefined,
      points: locus.points.map((point) => ({ x: point.x + 24, y: point.y + 24 })),
      style: { ...(locus.style ?? {}), trace: false },
    } : null;
    return locus ? {
      ...construction,
      loci: copiedLocus ? [...construction.loci, copiedLocus] : construction.loci,
    } : construction;
  }
  const polygon = construction.polygons.find((item) => item.id === object.id);
  if (!polygon) return construction;
  return solveConstruction({ ...construction, points: [...construction.points, ...copiedPoints], polygons: [...construction.polygons, { ...polygon, id: crypto.randomUUID(), points: polygon.points.map((id) => pointMap.get(id) ?? id), style: { ...(polygon.style ?? {}) } }] });
}

function circleRadiusUnits(construction: Construction, circleId: string) {
  const circle = construction.circles.find((item) => item.id === circleId);
  const center = circle ? pointById(construction.points, circle.center) : null;
  const edge = circle ? pointById(construction.points, circle.edge) : null;
  return center && edge ? roundTo(distance(center, edge) / 40, 2) : null;
}

function resizeGeometryObjectInConstruction(construction: Construction, object: SelectedGeometryObject, factor: number): Construction {
  const pointIds = pointIdsForObject(construction, object);
  if (!pointIds.length) {
    if (object.type !== "locus") return construction;
    return {
      ...construction,
      loci: construction.loci.map((locus) => {
        if (locus.id !== object.id || !locus.points.length) return locus;
        const center = centroid(locus.points);
        return { ...locus, points: locus.points.map((point) => scalePointAround(point, center, factor)) };
      }),
    };
  }
  const points = pointIds.map((id) => pointById(construction.points, id)).filter((point): point is GeoPoint => Boolean(point));
  if (!points.length) return construction;
  const center = object.type === "circle" || object.type === "arc"
    ? points[0]
    : centroid(points);
  const anchorId = object.type === "circle" || object.type === "arc" ? points[0].id : "";
  return solveConstruction({
    ...construction,
    points: construction.points.map((point) => {
      if (!pointIds.includes(point.id) || point.id === anchorId) return point;
      return { ...point, ...scalePointAround(point, center, factor) };
    }),
  });
}

function centroid(points: Array<{ x: number; y: number }>) {
  const total = points.reduce((sum, point) => ({ x: sum.x + point.x, y: sum.y + point.y }), { x: 0, y: 0 });
  return { x: total.x / points.length, y: total.y / points.length };
}

function scalePointAround(point: { x: number; y: number }, center: { x: number; y: number }, factor: number) {
  return { x: center.x + (point.x - center.x) * factor, y: center.y + (point.y - center.y) * factor };
}

