      <text x="470" y="227" fill="#a78bfa" fontSize="28" fontWeight="900">b</text>
      <text x="380" y="214" fill="#fbbf24" fontSize="28" fontWeight="900">c</text>
      <text x="300" y="238" fill="#67e8f9" fontSize="30" fontWeight="900">a^2</text>
