export function CasGateway() {
  const modes = ["Solve", "Simplify", "Factor", "Expand", "Substitute", "Differentiate"];
  const [mode, setMode] = useStudioMode("mode", modes, "Solve");
  const history = useAlgebraHistory({ draft: "2*x^2-8*x-10", x: 2, y: 1, result: "", entries: [] as Array<{ mode: string; input: string; output: string }> }, "AlgebraInteractiveLabs.tsx:CasGateway");
  const { draft, x, y, result, entries } = history.state;
  const [focus, setFocus] = useStudioState("AlgebraInteractiveLabs:CasGateway:focus", "Each operation rewrites the expression.");
  const [candidate, setCandidate] = useStudioState("AlgebraInteractiveLabs:CasGateway:candidate", "");
  const residual = (value: number) => {
    const left = draft.split("=")[0] ?? draft;
    const evaluated = evaluateAlgebraExpression(left, { x: value, y });
    return evaluated.ok ? evaluated.value : Number.NaN;
  };
  const figureOk = candidate.trim() !== "" && (
    mode === "Solve"
      ? Number.isFinite(Number(candidate)) && Math.abs(residual(Number(candidate))) <= 1e-6
      : expressionsEquivalent(draft.split("=")[0] || draft, candidate) || (result ? expressionsEquivalent(result, candidate) : false)
  );
  const residualTone = !candidate.trim() || mode !== "Solve" || !Number.isFinite(Number(candidate)) ? "" : Math.abs(residual(Number(candidate))) <= 1e-6 ? "is-pass" : Math.abs(residual(Number(candidate))) < 0.2 ? "is-near" : "is-fail";
  const compute = () => {
    if (!draft.trim()) return;
    const substituted = mode === "Substitute" ? evaluateAlgebraExpression(draft, { x, y }) : null;
    const answer = mode === "Substitute"
      ? substituted && substituted.ok ? { ok: true as const, output: formatAlgebraNumber(substituted.value) } : { ok: false as const, output: substituted?.error ?? "Invalid expression." }
      : runCasOperation(draft, (mode === "Differentiate" ? "differentiate" : mode.toLowerCase()) as CasOperation);
    const output = answer.ok ? answer.output : `Check input near “${draft.slice(0, 24)}”: ${answer.output}`;
    history.commit({ ...history.state, result: output, entries: [...entries, { mode, input: draft, output }].slice(-8) });
  };
  const casChallenge = (() => {
    const source = draft.split("=")[0] || draft;
    if (mode === "Solve") {
      const solved = runCasOperation(draft.includes("=") ? draft : `${draft}=0`, "solve");
      return { expected: solved.ok ? solved.output : "0", prompt: `Solve ${draft} and enter a root or the CAS solution.` };
    }
    if (mode === "Simplify") {
      const simplified = runCasOperation(source, "simplify");
      return { expected: simplified.ok ? simplified.output : source, prompt: `Simplify ${draft}.` };
    }
    if (mode === "Expand") {
      const expanded = runCasOperation(source, "expand");
      return { expected: expanded.ok ? expanded.output : source, prompt: `Expand ${draft}.` };
    }
    if (mode === "Substitute") {
      const value = evaluateAlgebraExpression(source, { x, y });
      return { expected: value.ok ? value.value : 0, prompt: `Substitute x=${x}, y=${y} into ${draft}.` };
    }
    if (mode === "Differentiate") {
      const derivative = runCasOperation(source, "differentiate");
      return { expected: derivative.ok ? derivative.output : source, prompt: `Differentiate ${draft} with respect to x.` };
    }
    const factored = runCasOperation(source, "factor");
    return { expected: factored.ok ? factored.output : "2*(x-5)*(x+1)", prompt: `Factor ${draft}, or enter an equivalent form.` };
  })();
  return <div className="alg-page alg-dash-page" data-mode-canvas={mode}><AlgebraLabHeading labId="cas" subtitle="Computer Algebra System — step-by-step transformations and verification." modes={modes} mode={mode} onMode={(next) => { setMode(next); history.replace({ ...history.state, result: "" }); }} onUndo={history.undo} onRedo={history.redo} canUndo={history.canUndo} canRedo={history.canRedo} onReset={() => history.reset()} helpTitle={`${mode} help`} helpBody="The CAS never uses eval(). Invalid expressions return an error. History stores each successful or failed compute.">CAS Step Explorer — candidate verification</AlgebraLabHeading><p role="status">{focus}</p><div className="alg-cas-notice"><b>Connected to the existing CAS workspace</b><p>Check candidates against the live graph — not a Wolfram language.</p><Link to="/workspace/data/cas">Open CAS Workspace</Link></div><div className="alg-dash-banner" data-lab-mode={mode}><b>CAS Step Explorer · {mode}</b><small>Each compute rewrites the expression with the same engine as the CAS workspace. Click a history row to restore it.</small></div><div className="alg-dash-layout alg-cas-layout"><Card title="CAS expression"><label className="alg-field">CAS expression<input value={draft} placeholder={mode === "Solve" ? "2x+3=7" : mode === "Differentiate" ? "x^2" : "(x-1)*(x+2)"} onChange={(e) => history.replace({ ...history.state, draft: e.target.value, result: "" })} onKeyDown={(e) => { if (e.key === "Enter") compute(); }} /></label><p>Use * for multiply and ^ for powers. Plotting uses the left of “=” when present.</p>{mode === "Substitute" && <><Numeric label="Substitute x" value={x} onChange={(v) => history.replace({ ...history.state, x: v, result: "" })} /><Numeric label="Substitute y" value={y} onChange={(v) => history.replace({ ...history.state, y: v, result: "" })} /></>}<button type="button" className="alg-gradient-button" disabled={!draft.trim()} onClick={compute}>Compute {mode}</button><label className="alg-field">Candidate to check against the figure<input value={candidate} onChange={(e) => setCandidate(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") setFocus(figureOk ? "Candidate pass." : "Candidate fail."); }} placeholder="2*(x-5)*(x+1)" /></label><p className={residualTone} role="status">{candidate ? (figureOk ? "Candidate matches the figure." : "Not equivalent to the current expression.") : "Enter a candidate to check against the graph."}</p><Link className="alg-soft" to="/algebra/advanced?tool=ALG-25">Open workbench tool 25</Link></Card><Card title={`${mode} result`}><Result>{result || "Enter an expression and compute."}</Result><ol className="alg-cas-steps">{entries.map((entry) => <li key={`${entry.mode}-${entry.input}-${entry.output}`}><button type="button" onClick={() => history.replace({ ...history.state, draft: entry.input, result: entry.output })}>{entry.mode}: {entry.input} → {entry.output}</button></li>)}</ol><button type="button" onClick={() => history.commit({ ...history.state, entries: [], result: "" })}>Clear history</button></Card><Card title="Expression graph"><Plot expressions={[draft.split("=")[0] || "0", ...(candidate.trim() ? [candidate.split("=")[0] ?? candidate] : [])]} dashed={[false, true]} /></Card></div><Challenge expected={casChallenge.expected} prompt={casChallenge.prompt} onNew={() => history.commit({ ...history.state, draft: mode === "Solve" ? "2*x+6=0" : mode === "Differentiate" ? "x^3" : "x^2-5*x+6" })} /><LabStrip onSelect={(title) => { if (title === "Try") { const answer = runCasOperation("2*x^2-8*x-10", "factor"); history.commit({ ...history.state, draft: "2*x^2-8*x-10", result: answer.ok ? answer.output : answer.output }); } setFocus(title === "Challenge" ? "Check a candidate by substituting." : title === "Try" ? "Factor 2x²−8x−10." : title === "Why" ? "Equivalent forms share values." : title === "Understand" ? "CAS applies the same algebra laws." : "Each operation rewrites the expression."); }} items={[["Observe", "Each operation rewrites the expression."], ["Understand", "CAS applies the same algebra laws."], ["Why", "Equivalent forms share values."], ["Try", "Factor 2x²−8x−10."], ["Challenge", "Check a candidate by substituting."]]} /></div>;
}

import { useStudioState } from "../phase1/StudioModelProvider";
import { AlertTriangle, Check, Eye, FlaskConical, HelpCircle, Lightbulb, Maximize2, RotateCcw, RotateCw, Sparkles, Trophy } from "lucide-react";
import { useMemo, type CSSProperties } from "react";
import AlgebraLabHeading from "./AlgebraLabHeading";
import { useStudioMode } from "../../hooks/useStudioMode";
import {
  answersMatchChallenge,
  classifyProofReason,
  evaluateAlgebraExpression,
  expressionsEquivalent,
  formatAlgebraNumber,
  reasonMatchesStep,
} from "./algebraStudioMath";
import { useAlgebraHistory } from "./useAlgebraHistory";

const modes = ["Identities", "Equation Proof", "Induction", "Inequality", "Counterexample"] as const;
type ProofMode = (typeof modes)[number];

type ProofStep = { statement: string; reason: string };

type ProofState = {
  steps: ProofStep[];
  draft: string;
  template: string;
  selected: number;
  a: number;
  b: number;
  n: number;
  numeric: string;
  challengeOn: boolean;
  challengeAnswer: string;
  challengeChecked: boolean;
};

const REASONS = [
  { id: "commutative", label: "Commutative Property", color: "#0891b2" },
  { id: "associative", label: "Associative Property", color: "#8b5cf6" },
  { id: "combine", label: "Combine like terms", color: "#f59e0b" },
  { id: "distributive", label: "Distributive Property", color: "#2563eb" },
  { id: "square", label: "Definition of square", color: "#0ea5e9" },
  { id: "given", label: "Given", color: "#64748b" },
] as const;

const TEMPLATES: Record<string, string> = {
  "Expand using distributive property": "a(a+b)+b(a+b)",
  "Write as a product": "(a+b)(a+b)",
  "Expand both factors": "a^2+ab+ab+b^2",
  "Combine like terms": "a^2+2*a*b+b^2",
  "Start from the square": "(a+b)^2",
};

function pretty(expr: string) {
  return expr
    .replace(/\*/g, "")
    .replace(/\^2/g, "²")
    .replace(/\^3/g, "³")
    .replace(/-/g, "−")
    .replace(/\+/g, " + ")
    .replace(/−/g, " − ")
    .replace(/\s+/g, " ")
    .trim();
}

function seed(mode: ProofMode): ProofStep[] {
  if (mode === "Equation Proof") {
    return [
      { statement: "2*x+6=0", reason: "Given" },
      { statement: "2*x=-6", reason: "Subtract 6 from both sides" },
      { statement: "x=-3", reason: "Divide both sides by 2" },
    ];
  }
  if (mode === "Induction") {
    return [
      { statement: "1=1*(1+1)/2", reason: "Base case n=1" },
      { statement: "S_k=k*(k+1)/2", reason: "Induction hypothesis" },
      { statement: "S_(k+1)=k*(k+1)/2+(k+1)", reason: "Add the next term" },
      { statement: "S_(k+1)=(k+1)*(k+2)/2", reason: "Factor (k+1)" },
    ];
  }
  if (mode === "Inequality") {
    return [
      { statement: "(a-b)^2>=0", reason: "Squares of reals are nonnegative" },
      { statement: "a^2-2*a*b+b^2>=0", reason: "Expand the square" },
      { statement: "a^2+b^2>=2*a*b", reason: "Add 2ab to both sides" },
    ];
  }
  if (mode === "Counterexample") {
    return [
      { statement: "(a+b)^2=a^2+b^2", reason: "Claim (to disprove)" },
      { statement: "(a+b)^2=a^2+2*a*b+b^2", reason: "Definition of square and distribute" },
      { statement: "a=2, b=3: 25 ≠ 13", reason: "Numerical counterexample" },
    ];
  }
  return [
    { statement: "(a+b)^2", reason: "Given" },
    { statement: "(a+b)(a+b)", reason: "Definition of square: x² = x · x" },
    { statement: "a(a+b)+b(a+b)", reason: "Distributive Property" },
      { statement: "a^2+a*b+a*b+b^2", reason: "Distributive Property" },
      { statement: "a^2+2*a*b+b^2", reason: "" },
  ];
}

function goalCopy(mode: ProofMode) {
  if (mode === "Equation Proof") return { label: "Prove the solution", math: "2x + 6 = 0  ⇒  x = −3" };
  if (mode === "Induction") return { label: "Prove by induction", math: "1 + 2 + ⋯ + n = n(n+1)/2" };
  if (mode === "Inequality") return { label: "Prove the inequality", math: "a² + b² ≥ 2ab" };
  if (mode === "Counterexample") return { label: "Disprove the claim", math: "(a+b)² = a² + b²" };
  return { label: "Prove the identity", math: "(a+b)² = a² + 2ab + b²" };
}

function withTimes(expr: string) {
  return expr.replace(/ab/gi, "a*b").replace(/ba/gi, "b*a");
}

function identityHoldsAtSamples(left: string, right: string) {
  const a = withTimes(left);
  const b = withTimes(right);
  if (expressionsEquivalent(a, b)) return true;
  const samples = [[1, 1], [2, 3], [-1, 4], [0, 2], [5, -2]] as const;
  return samples.every(([av, bv]) => {
    const L = evaluateAlgebraExpression(a, { a: av, b: bv });
    const R = evaluateAlgebraExpression(b, { a: av, b: bv });
    return L.ok && R.ok && Math.abs(L.value - R.value) < 1e-6;
  });
}

function identityTarget(statement: string, previous: string, index: number) {
  const normalized = withTimes(statement);
  if (!expressionsEquivalent(normalized, "(a+b)^2") && !expressionsEquivalent(normalized, "a^2+2*a*b+b^2")) {
    return { valid: false as const, suggested: "", reason: "not-equivalent" as const };
  }
  if (index === 0 || normalized.replace(/\s/g, "") === "(a+b)^2") {
    return { valid: true as const, suggested: "Given", reason: "given" as const };
  }
  const classified = classifyProofReason(normalized, withTimes(previous) || "(a+b)^2");
  if (classified.valid) return classified;
  return classifyProofReason(normalized, "(a+b)^2");
}

function stepStatus(step: ProofStep, previous: string, mode: ProofMode, index: number) {
  if (!step.statement.trim()) return { ok: false, note: "Missing statement" };
  if (!step.reason.trim()) return { ok: false, note: "Check reason" };
  if (mode === "Identities") {
    const classified = identityTarget(step.statement, previous, index);
    if (!classified.valid) return { ok: false, note: "Not equivalent" };
    const reason = step.reason.toLowerCase();
    if (index === 0) return { ok: reason.includes("given"), note: reason.includes("given") ? "Given" : "Use Given" };
    if (reason.includes("square")) return { ok: true, note: "Definition of square" };
    if (reason.includes("distribut")) return { ok: true, note: "Distributive Property" };
    if (reason.includes("like") || reason.includes("combin")) return { ok: true, note: "Combine like terms" };
    if (reason.includes("commut") || reason.includes("assoc")) return { ok: true, note: classified.suggested || "Valid" };
    if (reasonMatchesStep(step.reason, classified)) return { ok: true, note: classified.suggested };
    return { ok: false, note: `Use ${classified.suggested}` };
  }
  return { ok: true, note: "Recorded" };
}

function fmt(n: number) {
  return formatAlgebraNumber(n);
}

export default function ProofLab() {
  const [mode, setMode] = useStudioMode("mode", modes, "Identities");
  const history = useAlgebraHistory<ProofState>({
    steps: seed("Identities"),
    draft: "",
    template: "Expand using distributive property",
    selected: 4,
    a: 2,
    b: 3,
    n: 5,
    numeric: "",
    challengeOn: false,
    challengeAnswer: "",
    challengeChecked: false,
  }, "AlgebraProofLab.tsx:ProofLab");
  const { steps, draft, template, selected, a, b, n, numeric, challengeOn, challengeAnswer, challengeChecked } = history.state;
  const [focusTile, setFocusTile] = useStudioState<"a2" | "ab" | "b2" | null>("AlgebraProofLab:ProofLab:focusTile", null);
  const [expanded, setExpanded] = useStudioState("AlgebraProofLab:ProofLab:expanded", false);

  const patch = (next: Partial<ProofState>, commit = true) => {
    const value = { ...history.state, ...next };
    if (commit) history.commit(value);
    else history.replace(value);
  };

  const statuses = steps.map((step, index) => stepStatus(step, steps[index - 1]?.statement ?? "", mode as ProofMode, index));
  const complete = statuses.filter((item) => item.ok).length;
  const expected = Math.max(steps.length, 1);
  const percent = Math.round((complete / expected) * 100);
  const goal = goalCopy(mode as ProofMode);
  const selectedStatus = statuses[selected];
  const lhs = (a + b) ** 2;
  const rhs = a * a + 2 * a * b + b * b;
  const identityHolds = Math.abs(lhs - rhs) < 1e-9;
  const counterLeft = (a + b) ** 2;
  const counterRight = a * a + b * b;
  const sumCheck = n * (n + 1) / 2;
  const sumDirect = (n * (n + 1)) / 2;
  const challengeExpected = (a + b) ** 2;
  const challengeOk = answersMatchChallenge(challengeAnswer, challengeExpected);

  const explanation = useMemo(() => {
    if (mode === "Equation Proof") return "The same operation on both sides preserves equality. Subtracting 6 isolates 2x; dividing by 2 isolates x. Substituting x = −3 recovers 0 = 0.";
    if (mode === "Induction") return "The base case holds at n = 1. Adding (k+1) to the inductive formula factors as (k+1)(k+2)/2, so the statement advances to every next integer.";
    if (mode === "Inequality") return "(a−b)² is never negative. Expanding and rearranging immediately gives a² + b² ≥ 2ab, with equality exactly when a = b.";
    if (mode === "Counterexample") return "The missing 2ab rectangle is why (a+b)² is not a²+b². Any pair with ab ≠ 0, such as a=2, b=3, is a counterexample: 25 ≠ 13.";
    return "We expanded (a+b)² using the distributive property to get four terms, then combined the like terms ab and ab to obtain 2ab.";
  }, [mode]);

  const addStep = () => {
    const statement = draft.trim() || TEMPLATES[template] || "";
    if (!statement) return;
    const previous = steps.at(-1)?.statement ?? "(a+b)^2";
    const classified = identityTarget(statement, previous, steps.length);
    const reason = classified.valid ? classified.suggested : "";
    patch({ steps: [...steps, { statement, reason }], draft: "", selected: steps.length });
  };

  const dropReason = (index: number, reason: string) => {
    patch({ steps: steps.map((step, i) => i === index ? { ...step, reason } : step), selected: index });
  };

  const dropStatement = (statement: string) => {
    if (selected >= 0 && selected < steps.length && !steps[selected]!.statement) {
      patch({ steps: steps.map((step, i) => i === selected ? { ...step, statement } : step) });
      return;
    }
    patch({ steps: [...steps, { statement, reason: "" }], selected: steps.length });
  };

  const insertSymbol = (symbol: string) => patch({ draft: `${draft}${symbol}` }, false);

  const verifyNumeric = () => {
    if (mode === "Counterexample") {
      patch({ numeric: `(${fmt(a)}+${fmt(b)})² = ${fmt(counterLeft)}, but ${fmt(a)}²+${fmt(b)}² = ${fmt(counterRight)}. ${counterLeft !== counterRight ? "Claim fails." : "Pick nonzero a and b."}` }, false);
      return;
    }
    patch({ numeric: identityHolds ? `LHS = RHS = ${fmt(lhs)} at a=${fmt(a)}, b=${fmt(b)}.` : `Mismatch: ${fmt(lhs)} ≠ ${fmt(rhs)}.` }, false);
  };

  const switchMode = (next: string) => {
    if (!modes.includes(next as ProofMode)) return;
    setMode(next as ProofMode);
    history.reset({ ...history.state, steps: seed(next as ProofMode), selected: 0, numeric: "", challengeOn: false, challengeChecked: false, challengeAnswer: "" });
  };

  return (
    <div className="alg-page alg-proof-page" data-mode-canvas={mode}>
      <AlgebraLabHeading
        subtitle="Build and validate algebraic proofs with interactive visual models."
        labId="proof"
        modes={modes}
        mode={mode}
        onMode={switchMode}
        onUndo={history.undo}
        onRedo={history.redo}
        canUndo={history.canUndo}
        canRedo={history.canRedo}
        onReset={() => history.reset()}
        helpTitle={`${mode} help`}
        helpBody="Drag a reason chip onto a row. Identity lines must stay equivalent to (a+b)². Click an area-model tile to see which terms it names."
      >
        Algebraic Proof Lab
      </AlgebraLabHeading>

      <section className="alg-proof-goal" aria-label="Proof goal">
        <span>Goal</span>
        <p>{goal.label} <strong>{goal.math}</strong></p>
        <div>
          <small>Proof progress</small>
          <progress max={expected} value={complete} />
          <b>{complete} / {expected} steps · {percent}%</b>
        </div>
      </section>

      <div className="alg-proof-shell">
        <div className="alg-proof-main">
          <section className="alg-card alg-proof-builder">
            <h2>Two-Column Proof Builder</h2>
            <p>Drag steps or reasons to build your proof.</p>
            <table className="alg-proof-table">
              <thead>
                <tr><th>Statements</th><th>Reasons</th></tr>
              </thead>
              <tbody>
                {steps.map((step, index) => {
                  const status = statuses[index]!;
                  const lit = focusTile && mode === "Identities" && (index >= 3);
                  return (
                    <tr key={`${step.statement}-${index}`} className={`${selected === index ? "is-on" : ""} ${lit ? "is-lit" : ""}`} onClick={() => patch({ selected: index }, false)}>
                      <td>
                        <span>{index + 1}</span>
                        <em>{pretty(step.statement) || "…"}</em>
                      </td>
                      <td
                        onDragOver={(event) => event.preventDefault()}
                        onDrop={(event) => {
                          event.preventDefault();
                          const reason = event.dataTransfer.getData("text/proof-reason");
                          if (reason) dropReason(index, reason);
                        }}
                      >
                        <span>{index + 1}</span>
                        {step.reason || <i>Drop a reason</i>}
                        {status.ok ? <Check aria-label="Valid step" /> : <AlertTriangle aria-label={status.note} />}
                        {!status.ok ? <small>{status.note}</small> : null}
                        <button type="button" aria-label="Move step up" disabled={index === 0} onClick={(event) => { event.stopPropagation(); if (index === 0) return; const next = [...steps]; const swap = next[index - 1]!; next[index - 1] = next[index]!; next[index] = swap; patch({ steps: next, selected: index - 1 }); }}>↑</button>
                        <button type="button" aria-label="Move step down" disabled={index === steps.length - 1} onClick={(event) => { event.stopPropagation(); if (index >= steps.length - 1) return; const next = [...steps]; const swap = next[index + 1]!; next[index + 1] = next[index]!; next[index] = swap; patch({ steps: next, selected: index + 1 }); }}>↓</button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            <div className="alg-proof-drop">
              <button
                type="button"
                onDragOver={(event) => event.preventDefault()}
                onDrop={(event) => {
                  event.preventDefault();
                  const statement = event.dataTransfer.getData("text/proof-statement");
                  if (statement) dropStatement(statement);
                }}
              >
                Drag a statement here
              </button>
              {selectedStatus && !selectedStatus.ok ? (
                <p role="status"><AlertTriangle /> Invalid or missing reason: {selectedStatus.note}</p>
              ) : null}
            </div>
            <div className="alg-proof-chips">
              {REASONS.map((reason) => (
                <button
                  key={reason.id}
                  type="button"
                  draggable
                  style={{ "--chip": reason.color } as CSSProperties}
                  onDragStart={(event) => event.dataTransfer.setData("text/proof-reason", reason.label)}
                  onClick={() => dropReason(selected, reason.label)}
                >
                  {reason.label}
                </button>
              ))}
            </div>
          </section>

          <div className="alg-proof-tools">
            <section className="alg-card">
              <h2>Add Step</h2>
              <label className="alg-field">Select a statement template
                <select value={template} onChange={(event) => patch({ template: event.target.value, draft: TEMPLATES[event.target.value] ?? draft }, false)}>
                  {Object.keys(TEMPLATES).map((item) => <option key={item}>{item}</option>)}
                </select>
              </label>
              <label className="alg-field">Enter your statement
                <input
                  value={draft}
                  placeholder="e.g., a(a+b)+b(a+b)"
                  onChange={(event) => patch({ draft: event.target.value }, false)}
                  onKeyDown={(event) => { if (event.key === "Enter") addStep(); }}
                />
              </label>
              <button type="button" className="alg-gradient-button" onClick={addStep}>Add to proof</button>
            </section>
            <section className="alg-card">
              <h2>Symbol Palette</h2>
              <div className="alg-symbols">
                {["a", "b", "a²", "b²", "(", ")", "+", "−", "·", "=", "^2"].map((symbol) => (
                  <button
                    type="button"
                    key={symbol}
                    draggable
                    onDragStart={(event) => event.dataTransfer.setData("text/proof-statement", symbol.replace("²", "^2").replace("·", "*").replace("−", "-"))}
                    onClick={() => insertSymbol(symbol.replace("²", "^2").replace("·", "*").replace("−", "-"))}
                  >
                    {symbol}
                  </button>
                ))}
              </div>
            </section>
            <section className="alg-card alg-proof-status">
              <h2>Quick Actions</h2>
              <div className="alg-proof-actions">
                <button type="button" disabled={!history.canUndo} onClick={history.undo}><RotateCcw /> Undo</button>
                <button type="button" disabled={!history.canRedo} onClick={history.redo}><RotateCw /> Redo</button>
                <button type="button" onClick={() => patch({ steps: steps.slice(0, 1), selected: 0 })}>Clear proof</button>
                <button type="button" onClick={() => history.reset()}>Start over</button>
              </div>
              <div className="alg-proof-meter" style={{ "--pct": `${percent}` } as CSSProperties}>
                <strong>{percent}%</strong>
                <small>{percent >= 100 ? "Proven" : percent >= 80 ? "Almost there!" : "Keep going"}</small>
                <p>{percent >= 100 ? "Every line is justified." : `Fix the reason for Step ${(statuses.findIndex((item) => !item.ok) + 1) || expected} to complete the proof.`}</p>
              </div>
            </section>
          </div>
        </div>

        <aside className="alg-proof-rail">
          <section className={`alg-card alg-proof-visual${expanded ? " is-wide" : ""}`}>
            <header>
              <h2>{mode === "Identities" ? "Visual Model: Area Model" : mode === "Equation Proof" ? "Visual Model: Balance" : mode === "Induction" ? "Visual Model: Staircase" : mode === "Inequality" ? "Visual Model: Nonnegative Square" : "Visual Model: Missing 2ab"}</h2>
              <button type="button" aria-label="Expand visual" onClick={() => setExpanded((value) => !value)}><Maximize2 /></button>
            </header>
            {mode === "Induction" ? (
              <div className="alg-proof-regions">
                <p><b>P(n)</b> {goal.math}</p>
                <p><b>Base</b> n = 1</p>
                <p><b>Hypothesis</b> assume P(k)</p>
                <p><b>Step</b> prove P(k+1)</p>
              </div>
            ) : null}
            <p>
              {mode === "Identities" && "(a+b)² as the area of a square."}
              {mode === "Equation Proof" && "Same operation on both pans keeps the scale level."}
              {mode === "Induction" && `Check n = ${n}: ${sumDirect} = ${n}(${n}+1)/2.`}
              {mode === "Inequality" && `(a−b)² = ${fmt((a - b) ** 2)} ≥ 0.`}
              {mode === "Counterexample" && "The orange rectangles are the 2ab the false claim forgets."}
            </p>
            {mode === "Identities" || mode === "Counterexample" ? (
              <div className="alg-proof-area-wrap">
                <small className="is-top">a + b</small>
                <div className="alg-proof-area">
                  <button type="button" className={focusTile === "a2" ? "is-on" : ""} onClick={() => setFocusTile(focusTile === "a2" ? null : "a2")}><b>a²</b></button>
                  <button type="button" className={focusTile === "ab" ? "is-on" : ""} onClick={() => setFocusTile(focusTile === "ab" ? null : "ab")}><b>ab</b></button>
                  <button type="button" className={focusTile === "ab" ? "is-on" : ""} onClick={() => setFocusTile(focusTile === "ab" ? null : "ab")}><b>ab</b></button>
                  <button type="button" className={focusTile === "b2" ? "is-on" : ""} onClick={() => setFocusTile(focusTile === "b2" ? null : "b2")}><b>b²</b></button>
                </div>
                <small className="is-left-a">a</small>
                <small className="is-left-b">b</small>
                <small className="is-bottom-a">a</small>
                <small className="is-bottom-b">b</small>
              </div>
            ) : mode === "Induction" ? (
              <svg className="alg-proof-stairs" viewBox="0 0 280 160" role="img" aria-label="Induction staircase">
                {Array.from({ length: n }, (_, row) => Array.from({ length: row + 1 }, (_, col) => (
                  <rect key={`${row}-${col}`} x={24 + col * 18} y={130 - row * 18} width="16" height="16" rx="3" fill={row === n - 1 ? "#8b5cf6" : "#22d3ee"} />
                )))}
              </svg>
            ) : mode === "Inequality" ? (
              <svg className="alg-proof-stairs" viewBox="0 0 240 160" role="img" aria-label="Nonnegative square">
                <rect x="40" y="20" width="120" height="120" rx="10" fill="#dbeafe" stroke="#2563eb" />
                <text x="100" y="88" textAnchor="middle" fill="#1d4ed8" fontSize="18" fontWeight="800">(a−b)²</text>
              </svg>
            ) : (
              <svg className="alg-proof-stairs" viewBox="0 0 280 140" role="img" aria-label="Equation balance">
                <line x1="40" y1="70" x2="240" y2="70" stroke="#64748b" strokeWidth="8" />
                <rect x="50" y="28" width="70" height="36" rx="8" fill="#22d3ee" />
                <rect x="160" y="28" width="70" height="36" rx="8" fill="#c084fc" />
                <text x="85" y="52" textAnchor="middle" fill="#fff" fontWeight="800">2x</text>
                <text x="195" y="52" textAnchor="middle" fill="#fff" fontWeight="800">−6</text>
                <text x="140" y="120" textAnchor="middle" fill="#059669" fontWeight="800">Balanced</text>
              </svg>
            )}
            <p className="alg-proof-total">
              {mode === "Identities" && `Total area = a² + ab + ab + b² = a² + 2ab + b²`}
              {mode === "Counterexample" && `True area ${fmt(counterLeft)} vs claimed ${fmt(counterRight)}`}
              {mode === "Induction" && `Sₙ = ${fmt(sumCheck)}`}
              {mode === "Inequality" && `${fmt(a * a + b * b)} ≥ ${fmt(2 * a * b)}`}
              {mode === "Equation Proof" && `x = −3 checks: 2(−3)+6 = 0`}
            </p>
          </section>

          <section className="alg-card">
            <h2>Assumptions</h2>
            <ul>
              <li>a, b ∈ ℝ</li>
              <li>All expressions are defined.</li>
              {mode === "Induction" && <li>n is a positive integer.</li>}
            </ul>
          </section>

          <section className="alg-card alg-proof-equiv">
            <h2>Equivalence Check</h2>
            <p className={identityHolds ? "ok" : "bad"}>{mode === "Counterexample" ? "Claim is false" : "LHS = RHS"}</p>
            <strong>{mode === "Counterexample" ? `${pretty("(a+b)^2")} ≢ ${pretty("a^2+b^2")}` : `${pretty("(a+b)^2")} ≡ ${pretty("a^2+2*a*b+b^2")}`}</strong>
            <div className="alg-slider-row">
              <label className="alg-field">a<input type="number" value={a} onChange={(event) => patch({ a: Number(event.target.value) || 0 }, false)} /></label>
              <label className="alg-field">b<input type="number" value={b} onChange={(event) => patch({ b: Number(event.target.value) || 0 }, false)} /></label>
            </div>
            <button type="button" className="alg-soft-button" onClick={verifyNumeric}>Verify numerically</button>
            {numeric ? <p role="status">{numeric}</p> : null}
          </section>

          <section className="alg-card">
            <h2>Step Validation</h2>
            <ol className="alg-proof-validate">
              {statuses.map((status, index) => (
                <li key={index} className={status.ok ? "ok" : "bad"}>
                  <b>{index + 1}</b>
                  {status.ok ? <Check /> : <AlertTriangle />}
                  <span>{status.note}</span>
                </li>
              ))}
            </ol>
          </section>

          <section className="alg-card">
            <h2>Explanation</h2>
            <p>{explanation}</p>
          </section>
        </aside>
      </div>

      <section className="alg-eq-learn" aria-label="Learning loop">
        <div role="button" tabIndex={0} onClick={() => setFocusTile("ab")}><Eye /><div><b>Observe</b><small>Explore the expression and its visual representation.</small></div></div>
        <div role="button" tabIndex={0} onClick={() => dropReason(selected, "Distributive Property")}><Lightbulb /><div><b>Understand</b><small>Learn the properties and rules used in proofs.</small></div></div>
        <div role="button" tabIndex={0} onClick={verifyNumeric}><HelpCircle /><div><b>Why</b><small>See why each step is valid and necessary.</small></div></div>
        <div>
          <FlaskConical />
          <div>
            <b>Try</b>
            <small>Build your own proof and check your reasoning.</small>
            <button type="button" onClick={() => patch({ draft: "a^2+2*a*b+b^2", template: "Combine like terms" }, false)}>Fill final line</button>
          </div>
        </div>
        <div>
          <Trophy />
          <div>
            <b>Challenge</b>
            <small>Attempt variations and strengthen your skills.</small>
            <button type="button" className="alg-eq-challenge" onClick={() => patch({ challengeOn: true })}>If a={fmt(a)}, b={fmt(b)}, (a+b)² = ?</button>
            {challengeOn && (
              <label className="alg-field">Your answer
                <input value={challengeAnswer} onChange={(event) => patch({ challengeAnswer: event.target.value, challengeChecked: false }, false)} />
                <button type="button" className="alg-gradient-button" onClick={() => patch({ challengeChecked: true }, false)}>Check</button>
                {challengeChecked && <p role="status">{challengeOk ? `Correct: ${fmt(challengeExpected)}.` : `Expand: ${fmt(a * a)} + ${fmt(2 * a * b)} + ${fmt(b * b)}.`}</p>}
              </label>
            )}
          </div>
        </div>
      </section>
    </div>
  );
}

import { useStudioState, useStudioModel } from "../phase1/StudioModelProvider";
import { Eye, HelpCircle, Lightbulb, Pencil, Sparkles } from "lucide-react";
import { useEffect, useState } from "react";
import AlgebraLabHeading from "./AlgebraLabHeading";
import { useStudioMode } from "../../hooks/useStudioMode";
import {
  answersMatchChallenge,
  applyBalanceOperation,
  autoBalanceLinear,
  completeSquareText,
  describeLinearSolution,
  formatAlgebraNumber,
  formatBalanceTerm,
  formatInequalitySolution,
  formatLinearSide,
  parseBalanceOperand,
  parseLinearEquation,
  polynomialCoefficients,
  quadraticVertex,
  snapNearZero,
  solveAbsoluteEquation,
  solveQuadraticEquation,
} from "./algebraStudioMath";
import { factorIntegerQuadratic } from "./algebraEnhancementEngine";
import { useAlgebraHistory } from "./useAlgebraHistory";

const fmt = (n: number) => formatAlgebraNumber(n);

function Numeric({ label, value, onChange, min = -20, max = 20, step = 1, onCommit }: { label: string; value: number; onChange: (n: number) => void; min?: number; max?: number; step?: number; onCommit?: (n: number) => void }) {
  const model = useStudioModel();
  const [draft, setDraft] = useState(String(value));
  useEffect(() => { setDraft(String(value)); }, [value]);
  return (
    <label className="alg-field">{label}
      <input type="number" min={min} max={max} step={step} value={draft} onFocus={() => model?.ledger.beginGesture()} onChange={(e) => {
        setDraft(e.target.value);
        if (e.target.value === "" || !Number.isFinite(Number(e.target.value))) return;
        onChange(Math.max(min, Math.min(max, Number(e.target.value))));
      }} onBlur={() => { if (draft === "" || !Number.isFinite(Number(draft))) setDraft(String(value)); else onCommit?.(Number(draft)); model?.ledger.endGesture(); }} />
    </label>
  );
}

export default function EquationsLab() {
  const modes = ["Linear", "Quadratic", "Absolute Value", "Inequalities"];
  const [mode, setMode] = useStudioMode("mode", modes, "Linear");
  const history = useAlgebraHistory({
    a: 3,
    b: 5,
    c: 2,
    d: -1,
    origA: 3,
    origB: 5,
    origC: 2,
    origD: -1,
    operand: "-2x",
    activeOp: "Subtract" as "Add" | "Subtract" | "Multiply" | "Divide",
    relation: ">" as "<" | "<=" | ">" | ">=",
    autoBalance: true,
    notice: "",
    steps: [] as string[],
    showValues: true,
    goal: "Solve for x",
    draft: "3x + 5 = 2x - 1",
    challengeOn: false,
    challengeAnswer: "",
    challengeChecked: false,
    quadraticMethod: "Quadratic formula",
    infoOpen: false,
  }, "EquationsLab.tsx:EquationsLab");
  const { a, b, c, d, operand, activeOp, relation, autoBalance, notice, steps, showValues, goal, draft, challengeOn, challengeAnswer, challengeChecked, origA, origB, origC, origD, quadraticMethod, infoOpen } = history.state;
  const linear = describeLinearSolution(a, b, c, d);
  const left = formatLinearSide(a, b);
  const right = formatLinearSide(c, d);
  const equation = mode === "Quadratic" ? `${fmt(a)}x² + (${fmt(b)})x + (${fmt(c)}) = 0`
    : mode === "Absolute Value" ? `|${formatLinearSide(a, b)}| = ${fmt(d)}`
    : mode === "Inequalities" ? `${formatLinearSide(a, b)} ${relation} ${fmt(d)}`
    : `${left} = ${right}`;
  const quadratic = solveQuadraticEquation(a, b, c);
  const vertex = quadraticVertex(a, b, c);
  const absolute = solveAbsoluteEquation(a, b, d);
  const inequality = formatInequalitySolution(a, b, relation, d);
  const result = mode === "Quadratic" ? quadratic.text : mode === "Absolute Value" ? absolute.text : mode === "Inequalities" ? inequality.text : linear.text;
  const balanced = mode === "Linear"
    ? linear.kind !== "none"
    : mode === "Inequalities"
      ? inequality.kind === "constant" ? inequality.truth !== false : true
      : true;
  const parsedOp = parseBalanceOperand(operand);
  const opTerm = parsedOp.ok ? parsedOp.term : { x: 0, n: 0 };
  const startEquation = mode === "Linear"
    ? `${formatLinearSide(origA, origB)} = ${formatLinearSide(origC, origD)}`
    : equation;
  const setCoeff = (patch: Partial<typeof history.state>) => history.replace({ ...history.state, ...patch });
  const commitEq = (state: { a: number; b: number; c: number; d: number }, step: string, extra: Partial<typeof history.state> = {}) => {
    history.commit({
      ...history.state,
      ...state,
      ...extra,
      steps: [...steps, step].slice(-6),
    });
  };
  const operate = (operation: "Add" | "Subtract" | "Multiply" | "Divide") => {
    const applied = applyBalanceOperation({ a, b, c, d }, operation, operand, relation);
    if (!applied.ok) { setCoeff({ notice: applied.error, activeOp: operation }); return; }
    const label = applied.delta !== undefined ? formatBalanceTerm(applied.delta) : formatBalanceTerm(applied.term);
    commitEq(applied.state, `${operation} ${formatBalanceTerm(applied.term)} from both sides → ${formatLinearSide(applied.state.a, applied.state.b)} = ${formatLinearSide(applied.state.c, applied.state.d)}`, {
      activeOp: operation,
      relation: mode === "Inequalities" ? applied.relation : relation,
      notice: `Applied ${label} to both sides.${applied.flipped ? " Inequality sign flipped." : ""}`,
    });
  };
  const applyDraft = () => {
    if (mode === "Quadratic") {
      const left = draft.split("=")[0] ?? draft;
      const parsed = polynomialCoefficients(left);
      if (!parsed.ok) { setCoeff({ notice: parsed.error }); return; }
      const coeffs = parsed.coeffs;
      const nextA = parsed.degree >= 2 ? coeffs[coeffs.length - 3] ?? 0 : 0;
      const nextB = parsed.degree >= 1 ? coeffs[coeffs.length - 2] ?? 0 : 0;
      const nextC = coeffs[coeffs.length - 1] ?? 0;
      history.reset({ ...history.state, a: nextA, b: nextB, c: nextC, draft, steps: [], notice: "Loaded quadratic." });
      return;
    }
    if (mode === "Absolute Value") {
      const normalized = draft.replace(/abs\(([^)]+)\)/i, "|$1|");
      const match = normalized.match(/^\s*\|(.+)\|\s*=\s*(.+)\s*$/);
      if (!match) { setCoeff({ notice: "Enter an equation like |2x+1| = 5." }); return; }
      const inside = parseBalanceOperand(match[1] ?? "");
      const right = parseBalanceOperand(match[2] ?? "");
      if (!inside.ok) { setCoeff({ notice: inside.error }); return; }
      if (!right.ok || right.term.x !== 0) { setCoeff({ notice: "The right side of an absolute-value equation must be a constant." }); return; }
      history.reset({ ...history.state, a: inside.term.x, b: inside.term.n, d: right.term.n, draft, steps: [], notice: "Loaded absolute-value equation." });
      return;
    }
    if (mode === "Inequalities") {
      const match = draft.match(/^(.*)(<=|>=|<|>)(.*)$/);
      if (!match) { setCoeff({ notice: "Enter an inequality such as 2x+1 > 5." }); return; }
      const left = parseBalanceOperand(match[1] ?? "");
      const right = parseBalanceOperand(match[3] ?? "");
      if (!left.ok) { setCoeff({ notice: left.error }); return; }
      if (!right.ok || right.term.x !== 0) { setCoeff({ notice: "Keep the right side a constant." }); return; }
      history.reset({ ...history.state, a: left.term.x, b: left.term.n, d: right.term.n, relation: match[2] as typeof relation, draft, steps: [], notice: "Loaded inequality." });
      return;
    }
    const parsed = parseLinearEquation(draft);
    if (!parsed.ok) { setCoeff({ notice: parsed.error }); return; }
    history.reset({ ...history.state, ...parsed.state, origA: parsed.state.a, origB: parsed.state.b, origC: parsed.state.c, origD: parsed.state.d, draft, steps: [], notice: "Loaded equation." });
  };
  const applyGoal = () => {
    if (goal === "Move x terms left") {
      const applied = applyBalanceOperation({ a, b, c, d }, "Subtract", `${c}x`, relation);
      if (applied.ok) commitEq(applied.state, `Move x terms left → ${formatLinearSide(applied.state.a, applied.state.b)} = ${formatLinearSide(applied.state.c, applied.state.d)}`);
    } else if (goal === "Move constants right") {
      const applied = applyBalanceOperation({ a, b, c, d }, "Subtract", b, relation);
      if (applied.ok) commitEq(applied.state, `Move constants right → ${formatLinearSide(applied.state.a, applied.state.b)} = ${formatLinearSide(applied.state.c, applied.state.d)}`);
    } else if (goal === "Simplify") {
      commitEq({ a, b, c, d }, `Simplified: ${formatLinearSide(a, b)} = ${formatLinearSide(c, d)}`);
    } else {
      const next = autoBalanceLinear({ a, b, c, d });
      commitEq(next, `Solve: ${formatLinearSide(next.a, next.b)} = ${formatLinearSide(next.c, next.d)}`);
    }
  };
  const newEquation = (asChallenge = false) => {
    const aa = 1 + Math.floor(Math.random() * 4);
    const cc = Math.floor(Math.random() * 3);
    const bb = Math.floor(Math.random() * 9) - 4;
    const x = Math.floor(Math.random() * 7) - 3;
    const dd = aa * x + bb - cc * x;
    history.reset({ ...history.state, a: aa, b: bb, c: cc, d: dd, origA: aa, origB: bb, origC: cc, origD: dd, draft: `${formatLinearSide(aa, bb)} = ${formatLinearSide(cc, dd)}`, steps: [], notice: asChallenge ? "Challenge loaded. Isolate x, then check." : "New equation loaded.", operand: cc ? `${cc}x` : String(bb || 1), activeOp: "Subtract", challengeOn: asChallenge || history.state.challengeOn, challengeAnswer: "", challengeChecked: false });
  };
  const marks = mode === "Quadratic" ? quadratic.roots.filter((root) => snapNearZero(root.imaginary) === 0).map((root) => root.real)
    : mode === "Absolute Value" ? absolute.values
    : mode === "Inequalities" && inequality.kind === "interval" ? [inequality.boundary]
    : linear.kind === "one" ? [linear.value] : [];
  const lineMin = -6;
  const lineMax = 6;
  const xTiles = (count: number, label: string) => Array.from({ length: Math.min(5, Math.max(0, Math.abs(Math.round(count)))) }, (_, i) => (
    <i key={`${label}${i}`} className="alg-eq-x">{showValues ? label : ""}</i>
  ));
  const challengeTarget = describeLinearSolution(origA, origB, origC, origD);
  const realQuadraticRoot = quadratic.roots.find((root) => snapNearZero(root.imaginary) === 0)?.real;
  const challengeExpected = mode === "Quadratic"
    ? (typeof realQuadraticRoot === "number" ? realQuadraticRoot : quadratic.text)
    : mode === "Absolute Value"
      ? (absolute.values[0] ?? absolute.text)
      : mode === "Inequalities"
        ? inequality.text
        : challengeTarget.kind === "one" ? challengeTarget.value : linear.text;
  const challengeOk = answersMatchChallenge(challengeAnswer, challengeExpected);
  const challengePrompt = mode === "Quadratic"
    ? `Solve ${equation}. Enter a real root.`
    : mode === "Absolute Value"
      ? `Solve ${equation}. Enter one real solution.`
      : mode === "Inequalities"
        ? `Describe the live inequality solution.`
        : `Solve and check: ${formatLinearSide(origA, origB)} = ${formatLinearSide(origC, origD)}`;
  const factoredQuad = factorIntegerQuadratic(Math.round(a), Math.round(b), Math.round(c));
  const quadraticRewrite = quadraticMethod === "Completing the square"
    ? completeSquareText(a, b, c)
    : quadraticMethod === "Factoring"
      ? (factoredQuad
        ? `(${factoredQuad.left[0] === 1 ? "" : factoredQuad.left[0]}x ${factoredQuad.left[1] >= 0 ? "+" : "−"} ${Math.abs(factoredQuad.left[1])})(${factoredQuad.right[0] === 1 ? "" : factoredQuad.right[0]}x ${factoredQuad.right[1] >= 0 ? "+" : "−"} ${Math.abs(factoredQuad.right[1])}) = 0`
        : "No integer factorization; the quadratic formula still applies.")
      : `x = (−b ± √D) / 2a → ${quadratic.text}`;
  return (
    <div className="alg-page alg-eq-page" data-mode-canvas={mode}>
      <AlgebraLabHeading labId="equations" subtitle="Solve equations and inequalities using the balance model. Explore operations, preserve equality, and check solutions." modes={modes} mode={mode} onMode={(next) => {
        setMode(next);
        const nextEquation = next === "Quadratic" ? `${fmt(a)}x² + (${fmt(b)})x + (${fmt(c)}) = 0`
          : next === "Absolute Value" ? `|${formatLinearSide(a, b)}| = ${fmt(d)}`
          : next === "Inequalities" ? `${formatLinearSide(a, b)} ${relation} ${fmt(d)}`
          : `${formatLinearSide(a, b)} = ${formatLinearSide(c, d)}`;
        history.replace({ ...history.state, draft: nextEquation, challengeChecked: false });
      }} onUndo={history.undo} onRedo={history.redo} canUndo={history.canUndo} canRedo={history.canRedo} onReset={() => history.reset()} helpTitle={`${mode} help`} helpBody="Operations always apply to both sides. Enter 2x then Subtract to remove x terms. Auto-balance does not skip steps. 0x=0 is all reals; 0x=nonzero has no solution.">Equations &amp; Inequalities Lab</AlgebraLabHeading>
      <p className="sr-only" role="status">{notice || "Watch how the scale stays balanced at every step."}</p>
      <div className="alg-eq-layout">
        <section className="alg-card alg-eq-equation" id="algebra-lab-main">
          <h2>Equation</h2>
          <p>Original: {startEquation}</p>
          <p>Current: {equation}</p>
          <p className="alg-kind-badge">{mode === "Linear" ? linear.kind === "one" ? "one solution" : linear.kind === "all" ? "all real numbers" : "no solution" : mode === "Quadratic" ? (quadratic.roots.some((root) => snapNearZero(root.imaginary) !== 0) ? "complex roots — not on the real line" : "real roots") : result}</p>
          <label className="alg-field">Equation
            <span className="alg-eq-input">
              <input value={draft} onChange={(e) => setCoeff({ draft: e.target.value })} onKeyDown={(e) => { if (e.key === "Enter") applyDraft(); }} />
              <button type="button" aria-label="Load equation" onClick={applyDraft}>▶</button>
            </span>
          </label>
          <label className="alg-field">Goal
            <select value={goal} onChange={(e) => setCoeff({ goal: e.target.value })}>
              <option>Solve for x</option>
              <option>Move x terms left</option>
              <option>Move constants right</option>
              <option>Simplify</option>
            </select>
          </label>
          {mode === "Linear" && <>
            <Numeric label="Left x coeff" value={a} onChange={(value) => setCoeff({ a: value, draft: `${formatLinearSide(value, b)} = ${formatLinearSide(c, d)}` })} onCommit={(value) => history.commit({ ...history.state, a: value, origA: value, draft: `${formatLinearSide(value, b)} = ${formatLinearSide(c, d)}` })} />
            <Numeric label="Left constant" value={b} onChange={(value) => setCoeff({ b: value, draft: `${formatLinearSide(a, value)} = ${formatLinearSide(c, d)}` })} onCommit={(value) => history.commit({ ...history.state, b: value, origB: value, draft: `${formatLinearSide(a, value)} = ${formatLinearSide(c, d)}` })} />
            <Numeric label="Right x coeff" value={c} onChange={(value) => setCoeff({ c: value, draft: `${formatLinearSide(a, b)} = ${formatLinearSide(value, d)}` })} onCommit={(value) => history.commit({ ...history.state, c: value, origC: value, draft: `${formatLinearSide(a, b)} = ${formatLinearSide(value, d)}` })} />
            <Numeric label="Right constant" value={d} onChange={(value) => setCoeff({ d: value, draft: `${formatLinearSide(a, b)} = ${formatLinearSide(c, value)}` })} onCommit={(value) => history.commit({ ...history.state, d: value, origD: value, draft: `${formatLinearSide(a, b)} = ${formatLinearSide(c, value)}` })} />
          </>}
          {mode === "Quadratic" && <>
            <Numeric label="a" value={a} onChange={(value) => setCoeff({ a: value, draft: `${fmt(value)}x² + (${fmt(b)})x + (${fmt(c)}) = 0` })} onCommit={(value) => history.commit({ ...history.state, a: value, draft: `${fmt(value)}x² + (${fmt(b)})x + (${fmt(c)}) = 0` })} />
            <Numeric label="b" value={b} onChange={(value) => setCoeff({ b: value, draft: `${fmt(a)}x² + (${fmt(value)})x + (${fmt(c)}) = 0` })} onCommit={(value) => history.commit({ ...history.state, b: value, draft: `${fmt(a)}x² + (${fmt(value)})x + (${fmt(c)}) = 0` })} />
            <Numeric label="c" value={c} onChange={(value) => setCoeff({ c: value, draft: `${fmt(a)}x² + (${fmt(b)})x + (${fmt(value)}) = 0` })} onCommit={(value) => history.commit({ ...history.state, c: value, draft: `${fmt(a)}x² + (${fmt(b)})x + (${fmt(value)}) = 0` })} />
            <label className="alg-field">Method<select value={quadraticMethod} onChange={(e) => setCoeff({ quadraticMethod: e.target.value })}>
              <option>Quadratic formula</option>
              <option>Factoring</option>
              <option>Completing the square</option>
            </select></label>
          </>}
          {mode === "Absolute Value" && <>
            <Numeric label="Inside x coeff" value={a} onChange={(value) => setCoeff({ a: value })} onCommit={(value) => history.commit({ ...history.state, a: value })} />
            <Numeric label="Inside constant" value={b} onChange={(value) => setCoeff({ b: value })} onCommit={(value) => history.commit({ ...history.state, b: value })} />
            <Numeric label="Right side" value={d} onChange={(value) => setCoeff({ d: value })} onCommit={(value) => history.commit({ ...history.state, d: value })} />
          </>}
          {mode === "Inequalities" && <>
            <Numeric label="x coeff" value={a} onChange={(value) => setCoeff({ a: value })} onCommit={(value) => history.commit({ ...history.state, a: value })} />
            <Numeric label="Constant" value={b} onChange={(value) => setCoeff({ b: value })} onCommit={(value) => history.commit({ ...history.state, b: value })} />
            <label className="alg-field">Relation<select value={relation} onChange={(e) => setCoeff({ relation: e.target.value as typeof relation })}>{["<", "<=", ">", ">="].map((r) => <option key={r}>{r}</option>)}</select></label>
            <Numeric label="Right side" value={d} onChange={(value) => setCoeff({ d: value })} onCommit={(value) => history.commit({ ...history.state, d: value })} />
          </>}
        </section>

        <section className="alg-card alg-eq-balance">
          <h2>
            Balance Model
            <button type="button" className="alg-eq-info" aria-label="Balance help" onClick={() => setCoeff({ infoOpen: !infoOpen, notice: "The same operation is applied to both sides, so equivalent equations stay balanced." })}>i</button>
            <label className="alg-toggle alg-eq-show"><span>Show values</span><input type="checkbox" checked={showValues} onChange={(e) => setCoeff({ showValues: e.target.checked })} /></label>
            <button type="button" className="alg-eq-reset" onClick={() => history.commit({ ...history.state, a: origA, b: origB, c: origC, d: origD, steps: [], notice: "Reset to the original equation." })}>↺ Reset</button>
          </h2>
          <div className="alg-eq-scale" aria-label="Balance scale">
            <div className="alg-eq-pan">
              <b>{showValues ? (mode === "Linear" ? left : equation.split("=")[0]) : ""}</b>
              <div>{mode === "Linear" ? <>{xTiles(a, "x")}{b !== 0 ? <i className="alg-eq-n">{showValues ? (b > 0 ? `+${fmt(b)}` : fmt(b)) : ""}</i> : null}</> : <small>{mode}</small>}</div>
            </div>
            <svg viewBox="0 0 90 140" className="alg-eq-post" aria-hidden="true">
              <circle cx="45" cy="18" r="16" fill="#fff" stroke="#94a3b8" strokeWidth="4" />
              <path d="M45 8v6M45 34v12" stroke="#64748b" strokeWidth="3" />
              <path d="M12 52h66" stroke="#94a3b8" strokeWidth="7" strokeLinecap="round" />
              <polygon points="32,62 45,132 58,62" fill="#e2e8f0" stroke="#94a3b8" />
              <circle cx="45" cy="18" r="5" fill={balanced ? "#22c55e" : "#ef4444"} />
            </svg>
            <div className="alg-eq-pan">
              <b>{showValues ? (mode === "Linear" ? right : equation.split("=")[1]) : ""}</b>
              <div>{mode === "Linear" ? <>{xTiles(c, "x")}{d !== 0 ? <i className="alg-eq-n">{showValues ? (d > 0 ? `+${fmt(d)}` : fmt(d)) : ""}</i> : null}</> : <small>{result}</small>}</div>
            </div>
          </div>
          <strong className={balanced ? "alg-balanced" : "alg-balanced is-off"}>{balanced ? "Balanced ✓" : "Not balanced"}</strong>
          {notice.includes("flipped") ? <p className="alg-eq-flip" role="status">Inequality sign reversed because both sides were multiplied or divided by a negative number. Check: 2 &gt; 1, but −2 &lt; −1.</p> : mode === "Inequalities" ? <p className="alg-eq-flip">Multiplying 2 &gt; 1 by −1 yields −2 &lt; −1 — the inequality flips.</p> : null}
          {infoOpen ? <p>Adding, subtracting, multiplying, or dividing both sides by the same nonzero value preserves equality. 0x = 0 is all reals; 0x = nonzero has no solution.</p> : null}
        </section>

        <section className="alg-card alg-eq-steps">
          <h2>Steps <small>{Math.min(steps.length + 1, 6)} / 6</small></h2>
          <ol className="alg-eq-step-list">
            <li><span>1</span><div><b>Start</b><p>{startEquation}</p></div></li>
            {steps.map((step, i) => (
              <li key={`${step}-${i}`}><span>{i + 2}</span><div><p>{step}</p><em>Preserves equality ✓</em></div></li>
            ))}
          </ol>
          <p className="alg-success">All operations applied to both sides. Equality preserved ✓</p>
        </section>

        <section className="alg-card alg-eq-ops">
          <h2>Operations</h2>
          <div className="alg-eq-op-row">
            {([["Add", "+"], ["Subtract", "−"], ["Multiply", "×"], ["Divide", "÷"]] as const).map(([operation, mark]) => (
              <button type="button" key={operation} className={activeOp === operation ? "is-on" : ""} aria-pressed={activeOp === operation} onClick={() => operate(operation)}>{mark} {operation}</button>
            ))}
            <button type="button" aria-label="Undo" onClick={history.undo} disabled={!history.canUndo}>↩ Undo</button>
          </div>
          <div className="alg-apply-row">
            <span>Apply the same operation to both sides</span>
            <label className="alg-eq-op-input">
              <input aria-label="Operand" value={operand} onChange={(e) => setCoeff({ operand: e.target.value })} />
            </label>
            <i>×</i>
            <output>{linear.kind === "one" ? fmt(linear.value) : "—"}</output>
            <i>=</i>
            <output className="is-empty">{linear.kind === "one" ? fmt(opTerm.x * linear.value + opTerm.n) : ""}</output>
            <label className="alg-toggle"><span>Auto-balance</span><input type="checkbox" checked={autoBalance} onChange={(e) => history.commit({ ...history.state, autoBalance: e.target.checked })} /></label>
          </div>
        </section>

        <section className="alg-card alg-eq-line">
          <h2>Solution on Number Line {linear.kind === "one" && mode === "Linear" ? <b>x = {fmt(linear.value)}</b> : null}</h2>
          <div className="alg-eq-numberline" aria-label="Number line">
            <i className="alg-eq-axis" />
            {Array.from({ length: lineMax - lineMin + 1 }, (_, i) => lineMin + i).map((n) => (
              <span key={n} style={{ left: `${((n - lineMin) / (lineMax - lineMin)) * 100}%` }}>{n}</span>
            ))}
            {mode === "Inequalities" && inequality.kind === "interval" && (
              <b className="alg-eq-ray" style={{
                left: inequality.relation.includes(">") ? `${((Math.max(inequality.boundary, lineMin) - lineMin) / (lineMax - lineMin)) * 100}%` : 0,
                width: inequality.relation.includes(">")
                  ? `${((lineMax - Math.max(inequality.boundary, lineMin)) / (lineMax - lineMin)) * 100}%`
                  : `${((Math.min(inequality.boundary, lineMax) - lineMin) / (lineMax - lineMin)) * 100}%`,
              }} />
            )}
            {marks.filter((value) => value >= lineMin && value <= lineMax).map((value) => (
              <em key={value} className={mode === "Inequalities" && inequality.kind === "interval" && !inequality.relation.includes("=") ? "is-out" : undefined} style={{ left: `${((value - lineMin) / (lineMax - lineMin)) * 100}%` }} />
            ))}
          </div>
          <div className="alg-eq-interval">
            <small>Solution (in interval notation)</small>
            <output>{mode === "Inequalities" ? inequality.text : linear.kind === "one" && mode === "Linear" ? `{${fmt(linear.value)}}` : result}</output>
            <p><i /> Solution <i className="is-out" /> Not included</p>
          </div>
        </section>

        <section className="alg-card alg-eq-validate">
          <h2>Solution &amp; Validation</h2>
          <p>Candidate <strong>{result}</strong></p>
          {mode === "Quadratic" && vertex && (
            <div className="alg-eq-check">
              <p>D = {fmt(b * b - 4 * a * c)}. Vertex ({fmt(vertex.x)}, {fmt(vertex.y)}). Axis x = {fmt(vertex.x)}. y-intercept {fmt(c)}.</p>
              <p>{quadraticRewrite}</p>
              <svg className="alg-graph" viewBox="0 0 700 220" role="img" aria-label="Quadratic graph">
                <path d="M30 110H670M350 10V210" stroke="currentColor" fill="none" />
                <path d={Array.from({ length: 80 }, (_, i) => {
                  const x = -6 + i * 12 / 79;
                  const y = a * x * x + b * x + c;
                  const px = 350 + x * 50;
                  const py = 110 - y * 8;
                  return `${i === 0 ? "M" : "L"}${px},${py}`;
                }).join(" ")} fill="none" stroke="#0891b2" strokeWidth="3" />
              </svg>
            </div>
          )}
          {linear.kind === "one" && mode === "Linear" && (
            <div className="alg-eq-check">
              <p>Check in original equation</p>
              <p>{formatLinearSide(origA, 0) ? `${origA}(${fmt(linear.value)})` : ""} {origB >= 0 ? "+" : "−"} {fmt(Math.abs(origB))} ≟ {formatLinearSide(origC, 0) ? `${origC}(${fmt(linear.value)})` : ""} {origD >= 0 ? "+" : "−"} {fmt(Math.abs(origD))}</p>
              <p className="ok">{fmt(origA * linear.value + origB)} = {fmt(origC * linear.value + origD)} Valid solution ✓</p>
            </div>
          )}
          <p className="alg-eq-extra">Extraneous check {mode === "Absolute Value" && d < 0 ? "Right side is negative, so there is no real solution." : "No restrictions detected. ✓"}</p>
          {mode === "Quadratic" ? <p>Discriminant D = {fmt(b * b - 4 * a * c)}{b * b - 4 * a * c > 0 ? " (two real roots)" : b * b - 4 * a * c === 0 ? " (one real root)" : " (complex roots — use Argand, not this number line)"}</p> : null}
          {mode === "Linear" && linear.kind === "one" ? <p>Check candidate in the original {formatLinearSide(origA, origB)} = {formatLinearSide(origC, origD)} at x = {fmt(linear.value)}.</p> : null}
        </section>

        <section className="alg-card alg-eq-why">
          <h2>Why it works</h2>
          <p>We applied the same operations to both sides of the equation, which preserves equality at every step. The balance stayed level, so both sides remained equivalent. Substituting back confirms the solution.</p>
        </section>
      </div>

      <section className="alg-eq-learn" aria-label="Learning loop">
        <div role="button" tabIndex={0} onClick={() => setCoeff({ notice: "Watch both pans stay equivalent after each operation." })} onKeyDown={(e) => { if (e.key === "Enter") setCoeff({ notice: "Watch both pans stay equivalent after each operation." }); }}><Eye /><div><b>Observe</b><small>Watch how the scale stays balanced at every step.</small></div></div>
        <div role="button" tabIndex={0} onClick={() => setCoeff({ notice: "If a = b then a + c = b + c. The same is true for −, ×, and ÷ (except ÷ 0)." })} onKeyDown={(e) => { if (e.key === "Enter") setCoeff({ notice: "If a = b then a + c = b + c." }); }}><Lightbulb /><div><b>Understand</b><small>Operations done to one side must be done to the other. a = b ⇒ a + c = b + c</small></div></div>
        <div role="button" tabIndex={0} onClick={() => applyGoal()} onKeyDown={(e) => { if (e.key === "Enter") applyGoal(); }}><HelpCircle /><div><b>Why</b><small>Equality is preserved by applying inverse operations to isolate x.</small></div></div>
        <div>
          <Pencil />
          <div>
            <b>Try</b>
            <small>Create your own equation and solve it step by step.</small>
            <button type="button" onClick={() => newEquation()}>New Equation</button>
          </div>
        </div>
        <div>
          <Sparkles />
          <div>
            <b>Challenge</b>
            <small>{challengePrompt}</small>
            <button type="button" className="alg-eq-challenge" onClick={() => newEquation(true)}>Challenge Me</button>
          {challengeOn && (
            <label className="alg-field">Your answer
              <input value={challengeAnswer} onChange={(e) => setCoeff({ challengeAnswer: e.target.value, challengeChecked: false })} />
              <button type="button" className="alg-gradient-button" onClick={() => setCoeff({ challengeChecked: true })}>Check answer</button>
              {challengeChecked && <p role="status">{challengeOk ? "Correct." : `Not yet. Current ${mode.toLowerCase()} solution: ${typeof challengeExpected === "number" ? fmt(challengeExpected) : challengeExpected}.`}</p>}
            </label>
          )}
          </div>
        </div>
      </section>
    </div>
  );
}

