import { ComplexLabChrome, CxCol, CxLive, CxSlider, CxStepper, CxToggle } from "./ComplexLabChrome";
import { ComplexPlane, CxDot, CxRay, CX_R, CX_W, CX_Z } from "./complexArgandCanvas";
import {
  addC, argC, divC, fmtC, fromPolar, invertC, mobius, modC, mulC, quadraticRoots, seriesRLC, subC, taylorExpITheta, type C,
} from "./complexLabMath";
import { EulerHelix, StudioMath3D } from "../shared/studioMath3D";

export function EulerLab({ page }: { page: StudioMockupPage }) {
  const [theta, setTheta] = useStudioState("ComplexAdvancedLabs:EulerLab:theta", Math.PI);
  const [playing, setPlaying] = useStudioState("ComplexAdvancedLabs:EulerLab:playing", false);
  const [speed, setSpeed] = useStudioState("ComplexAdvancedLabs:EulerLab:speed", 1);
  const [cycles, setCycles] = useStudioState("ComplexAdvancedLabs:EulerLab:cycles", 3);
  const [terms, setTerms] = useStudioState("ComplexAdvancedLabs:EulerLab:terms", 7);
  const [showCircle, setShowCircle] = useState(true);
  const [showHelix, setShowHelix] = useState(true);
  const [showPoint, setShowPoint] = useState(true);
  const [showAxes, setShowAxes] = useState(true);
  const [grid, setGrid] = useStudioState("ComplexAdvancedLabs:EulerLab:grid", true);
  useEffect(() => {
    if (!playing) return undefined;
    const id = window.setInterval(() => setTheta((t) => (t + 0.04 * speed) % (Math.PI * 2)), 40);
    return () => window.clearInterval(id);
  }, [playing, speed]);
  useEffect(() => {
    const reset = () => {
      setTheta(Math.PI);
      setPlaying(false);
      setSpeed(1);
      setCycles(3);
      setTerms(7);
    };
    window.addEventListener("cx-lab-reset", reset);
    return () => window.removeEventListener("cx-lab-reset", reset);
  }, []);
  const c = Math.cos(theta);
  const s = Math.sin(theta);
  const approx = taylorExpITheta(theta, terms);
  const err = Math.hypot(approx.re - c, approx.im - s);
  const identity = Math.hypot(Math.cos(Math.PI) + 1, Math.sin(Math.PI));

  return (
    <ComplexLabChrome page={page} className="is-euler">
      {() => (
        <>
          <CxCol>
            <div className="cx-card">
              <div className="cx-kicker">Parameters</div>
              <CxSlider label="Angle θ (radians)" value={theta} min={0} max={Math.PI * 2} step={0.01} display={`${fmt(theta, 6)}`} onChange={setTheta} />
              <div className="cx-pi-marks" aria-hidden="true"><span>0</span><span>π</span><span>2π</span></div>
            </div>
            <div className="cx-card">
              <div className="cx-kicker">Animate e<sup>iθ</sup></div>
              <div className="cx-play">
                <button type="button" aria-pressed={playing} onClick={() => setPlaying((v) => !v)}>{playing ? "Pause" : "Play"}</button>
                <select aria-label="Animation speed" value={speed} onChange={(event) => setSpeed(Number(event.target.value))}>
                  <option value={0.5}>0.5×</option>
                  <option value={1}>1.0×</option>
                  <option value={2}>2.0×</option>
                </select>
              </div>
            </div>
            <div className="cx-card">
              <div className="cx-kicker">Display options</div>
              <CxToggle label="Unit circle & projections" on={showCircle} onChange={setShowCircle} />
              <CxToggle label="Complex exponential (helix)" on={showHelix} onChange={setShowHelix} />
              <CxToggle label="Terminal point & trace" on={showPoint} onChange={setShowPoint} />
              <CxToggle label="Real & Imag axes" on={showAxes} onChange={setShowAxes} />
              <CxToggle label="Show grid" on={grid} onChange={setGrid} />
            </div>
            <div className="cx-card">
              <CxSlider label="Trace length" value={cycles} min={1} max={5} step={0.5} display={`${fmt(cycles, 1)} cycles`} onChange={setCycles} />
            </div>
            <div className="cx-card">
              <div className="cx-kicker">Approximation terms (Taylor series)</div>
              <CxStepper label="Terms" value={terms} min={1} max={16} step={1} digits={0} onChange={setTerms} />
            </div>
          </CxCol>
          <div className="cx-euler-grid">
            <figure className="cx-mini">
              <figcaption>1. Unit circle &amp; Argand plane</figcaption>
              <UnitCirclePanel theta={theta} c={c} s={s} showCircle={showCircle} showPoint={showPoint} showAxes={showAxes} grid={grid} />
            </figure>
            <figure className="cx-mini">
              <figcaption>2. Complex exponential helix</figcaption>
              <HelixPanel theta={theta} cycles={cycles} show={showHelix} />
            </figure>
            <figure className="cx-mini">
              <figcaption>3. Real &amp; imaginary projections</figcaption>
              <ProjectionPanel theta={theta} />
            </figure>
            <figure className="cx-mini">
              <figcaption>4. Trace on Argand plane</figcaption>
              <TracePanel theta={theta} cycles={cycles} showPoint={showPoint} />
            </figure>
          </div>
          <CxLive title="Live values">
            <p className="cx-eq">e<sup>iθ</sup></p>
            <p className="cx-eq is-ans">{fmt(c, 4)} + {fmt(s, 4)}i</p>
            <div className="cx-split">
              <p>Re<br /><strong>{fmt(c, 4)}</strong></p>
              <p>Im<br /><strong>{fmt(s, 4)}</strong></p>
            </div>
            <div className="cx-split">
              <p>|e<sup>iθ</sup>|<br /><strong>{fmt(Math.hypot(c, s), 4)}</strong></p>
              <p>arg(e<sup>iθ</sup>)<br /><strong>{Math.abs(theta - Math.PI) < 0.02 ? "π rad" : `${fmt(theta, 4)} rad`}</strong></p>
            </div>
            <h3>Polar form</h3>
            <p className="cx-eq">e<sup>iθ</sup> = 1 cis({Math.abs(theta - Math.PI) < 0.02 ? "π" : fmt(theta, 2)}) = cos({Math.abs(theta - Math.PI) < 0.02 ? "π" : fmt(theta, 2)}) + i sin({Math.abs(theta - Math.PI) < 0.02 ? "π" : fmt(theta, 2)})</p>
            <h3>Taylor series (about 0)</h3>
            <p className="cx-eq">e<sup>iθ</sup> = Σ (iθ)<sup>n</sup> / n!</p>
            <p className="cx-meta">{terms} terms · Error {err < 1e-8 ? "< 1.1 × 10⁻⁸" : fmt(err, 8)}</p>
            <p className="cx-eq">≈ {fmtC(approx, 4)}</p>
            <h3>Euler identity</h3>
            <p className="cx-ok">e<sup>iπ</sup> + 1 = {fmt(Math.cos(Math.PI) + 1, 4)} + {fmt(Math.sin(Math.PI), 4)}i = 0 · Verified {identity < 1e-10 ? "✓" : ""}</p>
            <h3>Key relationships</h3>
            <p className="cx-eq">cos θ = (e<sup>iθ</sup> + e<sup>−iθ</sup>) / 2</p>
            <p className="cx-eq">sin θ = (e<sup>iθ</sup> − e<sup>−iθ</sup>) / 2i</p>
          </CxLive>
        </>
      )}
    </ComplexLabChrome>
  );
}

function UnitCirclePanel({ theta, c, s, showCircle, showPoint, showAxes, grid }: { theta: number; c: number; s: number; showCircle: boolean; showPoint: boolean; showAxes: boolean; grid: boolean }) {
  return (
    <ComplexPlane label="Unit circle" width={320} height={280} xmin={-1.4} xmax={1.4} ymin={-1.4} ymax={1.4} showGrid={grid} showAxes={showAxes} showTicks>
      {({ x, y, u }) => (
        <>
          {showCircle ? <circle cx={x(0)} cy={y(0)} r={u} fill="none" stroke="#22d3ee" strokeWidth="2.4" /> : null}
          <CxRay x1={x(0)} y1={y(0)} x2={x(c)} y2={y(0)} color="#fb923c" width={3} />
          <CxRay x1={x(c)} y1={y(0)} x2={x(c)} y2={y(s)} color="#38bdf8" width={2} dashed />
          <CxRay x1={x(0)} y1={y(0)} x2={x(c)} y2={y(s)} color="#6366f1" width={2.4} />
          <text x={x(c / 2)} y={y(0) + 14} fontSize="11" fill="#ea580c">cos θ</text>
          <text x={x(0) - 28} y={y(s / 2)} fontSize="11" fill="#0284c7">sin θ</text>
          <text x={x(0.35 * Math.cos(theta / 2))} y={y(0.35 * Math.sin(theta / 2))} fontSize="12" fill="#f59e0b">θ</text>
          {showPoint ? <CxDot x={x(c)} y={y(s)} fill="#0ea5e9" label="e^{iθ}" /> : null}
        </>
      )}
    </ComplexPlane>
  );
}

function HelixPanel({ theta, show }: { theta: number; cycles?: number; show: boolean }) {
  return (
    <StudioMath3D label="Complex exponential helix" compact camera={[3.4, 2.6, 4.6]}>
      {show ? <EulerHelix theta={theta} /> : null}
    </StudioMath3D>
  );
}

function ProjectionPanel({ theta }: { theta: number }) {
  const w = 320;
  const plot = (fn: (t: number) => number, color: string, y0: number) => {
    const pts = Array.from({ length: 80 }, (_, i) => {
      const t = (i / 79) * Math.PI * 3;
      return `${20 + (t / (Math.PI * 3)) * 280},${y0 - fn(t) * 28}`;
    });
    const x = 20 + (theta / (Math.PI * 3)) * 280;
    const y = y0 - fn(theta) * 28;
    return (
      <>
        <polyline points={pts.join(" ")} fill="none" stroke={color} strokeWidth="2.2" />
        <circle cx={x} cy={y} r="5" fill={color} />
      </>
    );
  };
  return (
    <svg className="cx-plane" viewBox="0 0 320 280" role="img" aria-label="Real and imaginary projections">
      <rect width="320" height="280" fill="#f7fbff" rx="18" />
      <text x="16" y="22" fontSize="12" fill="#0ea5e9">cos θ</text>
      <line x1="20" y1="70" x2="300" y2="70" stroke="#cbd5e1" />
      {plot(Math.cos, "#22d3ee", 70)}
      <text x="16" y="150" fontSize="12" fill="#8b5cf6">sin θ</text>
      <line x1="20" y1="200" x2="300" y2="200" stroke="#cbd5e1" />
      {plot(Math.sin, "#8b5cf6", 200)}
      <text x="18" y="268" fontSize="10" fill="#94a3b8">0</text>
      <text x="108" y="268" fontSize="10" fill="#94a3b8">π</text>
      <text x="198" y="268" fontSize="10" fill="#94a3b8">2π</text>
      <text x="278" y="268" fontSize="10" fill="#94a3b8">3π</text>
    </svg>
  );
}

function TracePanel({ theta, cycles, showPoint }: { theta: number; cycles: number; showPoint: boolean }) {
  const trail = Array.from({ length: 80 }, (_, i) => {
    const t = theta - ((79 - i) / 79) * Math.min(theta, cycles * 0.4);
    return t;
  }).filter((t) => t >= 0);
  return (
    <ComplexPlane label="Trace on Argand plane" width={320} height={280} xmin={-1.4} xmax={1.4} ymin={-1.4} ymax={1.4}>
      {({ x, y, u }) => (
        <>
          <circle cx={x(0)} cy={y(0)} r={u} fill="none" stroke="#22d3ee" strokeWidth="2.4" />
          <polyline
            fill="none"
            stroke="#93c5fd"
            strokeWidth="2"
            points={trail.map((t) => `${x(Math.cos(t))},${y(Math.sin(t))}`).join(" ")}
          />
          {showPoint ? <CxDot x={x(Math.cos(theta))} y={y(Math.sin(theta))} fill="#0ea5e9" /> : null}
        </>
      )}
    </ComplexPlane>
  );
}

const LOCUS_MODES = ["Circle Loci", "Line Loci", "Möbius", "Inversion", "Affine Map"] as const;

export function LociLab({ page }: { page: StudioMockupPage }) {
  const [cx, setCx] = useStudioState("ComplexAdvancedLabs:LociLab:cx", 1);
  const [cy, setCy] = useStudioState("ComplexAdvancedLabs:LociLab:cy", -1);
  const [r, setR] = useStudioState("ComplexAdvancedLabs:LociLab:r", 2);
  const [th, setTh] = useStudioState("ComplexAdvancedLabs:LociLab:th", 1.23);
  const [playing, setPlaying] = useStudioState("ComplexAdvancedLabs:LociLab:playing", false);
  const [showLocus, setShowLocus] = useState(true);
  const [showCenter, setShowCenter] = useState(true);
  const [showGrid, setShowGrid] = useState(true);
  const [trail, setTrail] = useStudioState("ComplexAdvancedLabs:LociLab:trail", 8);
  const [a, setA] = useStudioState<C>("ComplexAdvancedLabs:LociLab:a", { re: 1, im: 1 });
  const [b, setB] = useStudioState<C>("ComplexAdvancedLabs:LociLab:b", { re: 1, im: 0 });
  const [c, setC] = useStudioState<C>("ComplexAdvancedLabs:LociLab:c", { re: 0, im: 1 });
  const [d, setD] = useStudioState<C>("ComplexAdvancedLabs:LociLab:d", { re: 1, im: -1 });
  const [kind, setKind] = useStudioState<"Möbius" | "Inversion" | "Affine" | "Rotation" | "Scaling">("ComplexAdvancedLabs:LociLab:kind", "Möbius");
  useEffect(() => {
    if (!playing) return undefined;
    const id = window.setInterval(() => setTh((t) => (t + 0.04) % (Math.PI * 2)), 40);
    return () => window.clearInterval(id);
  }, [playing]);
  useEffect(() => {
    const toggle = () => setPlaying((v) => !v);
    const reset = () => { setCx(1); setCy(-1); setR(2); setTh(1.23); setPlaying(false); };
    window.addEventListener("cx-lab-animate", toggle);
    window.addEventListener("cx-lab-reset", reset);
    return () => {
      window.removeEventListener("cx-lab-animate", toggle);
      window.removeEventListener("cx-lab-reset", reset);
    };
  }, []);

  const map = (z: C): C => {
    if (kind === "Inversion") return invertC(z);
    if (kind === "Affine") return addC(mulC(a, z), b);
    if (kind === "Rotation") return mulC(fromPolar(1, (th * 180) / Math.PI), z);
    if (kind === "Scaling") return mulC({ re: r / 2, im: 0 }, z);
    return mobius(z, a, b, c, d);
  };

  return (
    <ComplexLabChrome page={page} pills className="is-loci">
      {(mode, setMode) => {
        const circle = mode === "Circle Loci" || mode === "Möbius" || mode === "Inversion" || mode === "Affine Map";
        const z: C = circle
          ? { re: cx + r * Math.cos(th), im: cy + r * Math.sin(th) }
          : { re: -2 + th, im: cy + 0.4 * th };
        const w = map(z);
        const samples = Array.from({ length: 64 }, (_, i) => {
          const t = (i / 64) * Math.PI * 2;
          const p = circle ? { re: cx + r * Math.cos(t), im: cy + r * Math.sin(t) } : { re: -2.2 + (i / 63) * 4.4, im: cy };
          return { z: p, w: map(p) };
        });
        const pole = c.re === 0 && c.im === 0 ? { re: Number.NaN, im: Number.NaN } : divC({ re: -d.re, im: -d.im }, c);
        const det = subC(mulC(a, d), mulC(b, c));
        const fixed = kind === "Möbius" ? quadraticRoots(c, addC(d, { re: -a.re, im: -a.im }), { re: -b.re, im: -b.im }) : [];
        return (
          <>
            <CxCol>
              <div className="cx-card">
                <div className="cx-kicker">Loci controls</div>
                <label className="cx-select">Locus type
                  <select aria-label="Locus type" value={mode} onChange={(event) => setMode(event.target.value)}>
                    {LOCUS_MODES.map((item) => <option key={item} value={item}>{item}</option>)}
                  </select>
                </label>
                <CxStepper label="Center a" value={cx} min={-3} max={3} onChange={setCx} />
                <CxStepper label="Center b" value={cy} min={-3} max={3} onChange={setCy} />
                <CxSlider label="Radius (r)" value={r} min={0.4} max={3} step={0.05} display={fmt(r, 2)} onChange={setR} />
                <CxSlider label="Parametric point z(θ)" value={th} min={0} max={Math.PI * 2} step={0.01} display={`${fmt(th, 2)} rad`} onChange={setTh} />
                <p className="cx-eq">z = c + r e<sup>iθ</sup></p>
                <div className="cx-ops">
                  <button type="button" aria-pressed={playing} onClick={() => setPlaying((v) => !v)}>{playing ? "Pause" : "Play"}</button>
                  <button type="button" onClick={() => { setCx(1); setCy(-1); setR(2); setTh(1.23); }}>Reset</button>
                </div>
              </div>
              <div className="cx-card">
                <div className="cx-kicker">Display</div>
                <CxToggle label="Show locus" on={showLocus} onChange={setShowLocus} />
                <CxToggle label="Show center" on={showCenter} onChange={setShowCenter} />
                <CxToggle label="Show mapping grid" on={showGrid} onChange={setShowGrid} />
                <CxSlider label="Trail length" value={trail} min={2} max={16} step={1} display={String(trail)} onChange={setTrail} />
              </div>
            </CxCol>
            <div className="cx-loci-planes">
              <figure className="cx-mini">
                <figcaption>Before (z-plane)</figcaption>
                <ComplexPlane label="z-plane" width={360} height={280} xmin={-2.6} xmax={3.2} ymin={-3} ymax={2.4} showGrid onPick={(re, im) => {
                    if (circle) setTh(Math.atan2(im - cy, re - cx));
                    else setTh(clamp(re + 2, 0, Math.PI * 2));
                  }}>
                  {({ x, y, u }) => (
                    <>
                      {showLocus && circle ? (
                        <circle cx={x(cx)} cy={y(cy)} r={r * u} fill="none" stroke="#22d3ee" strokeDasharray="6 5" />
                      ) : null}
                      {showLocus && !circle ? (
                        <line x1={x(-2.4)} y1={y(cy)} x2={x(3)} y2={y(cy)} stroke="#22d3ee" strokeDasharray="6 5" />
                      ) : null}
                      {showCenter && circle ? <CxDot x={x(cx)} y={y(cy)} fill="#147df2" label="c" /> : null}
                      <CxDot x={x(z.re)} y={y(z.im)} fill={CX_R} label="z" />
                    </>
                  )}
                </ComplexPlane>
              </figure>
              <figure className="cx-mini">
                <figcaption>After (w-plane)  w = f(z)</figcaption>
                <ComplexPlane label="w-plane" width={360} height={280} xmin={-3.2} xmax={3.6} ymin={-2.6} ymax={3.2} showGrid>
                  {({ x, y }) => (
                    <>
                      {showLocus ? (
                        <polyline fill="none" stroke="#8b5cf6" strokeWidth="2.2" points={samples.map((p) => `${x(p.w.re)},${y(p.w.im)}`).join(" ")} />
                      ) : null}
                      <CxDot x={x(w.re)} y={y(w.im)} fill={CX_W} label="w = f(z)" />
                    </>
                  )}
                </ComplexPlane>
              </figure>
              {showGrid ? (
                <svg className="cx-map-grid" viewBox="0 0 640 140" role="img" aria-label="Mapping grid">
                  {Array.from({ length: 16 * 2 }, (_, i) => {
                    const col = i % 16;
                    const row = Math.floor(i / 16);
                    const zx = -1.6 + col * 0.22;
                    const zy = row === 0 ? 0.45 : -0.45;
                    const wz = map({ re: zx, im: zy });
                    const x0 = 18 + col * 18;
                    const y0 = 36 + row * 48;
                    return (
                      <g key={i}>
                        <circle cx={x0} cy={y0} r="3" fill="#0ea5e9" />
                        <line x1={x0} y1={y0} x2={360 + wz.re * 22} y2={60 - wz.im * 14} stroke="#c4b5fd" strokeDasharray="3 3" />
                        <circle cx={360 + wz.re * 22} cy={60 - wz.im * 14} r="3" fill="#8b5cf6" />
                      </g>
                    );
                  })}
                  <text x="8" y="16" fontSize="11" fill="#64748b">Mapping Grid (sample points)</text>
                  <text x="560" y="130" fontSize="10" fill="#94a3b8">16 × 16 grid</text>
                </svg>
              ) : null}
            </div>
            <CxLive title="Live values">
              <p className="cx-eq">z = {fmtC(z, 3)}</p>
              <p className="cx-eq is-ans">w = f(z) = {fmtC(w, 3)}</p>
              <p className="cx-meta">|z| = {fmt(modC(z), 3)} · |w| = {fmt(modC(w), 3)}</p>
              <p className="cx-meta">arg(z) = {fmt((argC(z) * 180) / Math.PI, 1)}° · arg(w) = {fmt((argC(w) * 180) / Math.PI, 1)}°</p>
              <h3>Polar forms</h3>
              <p className="cx-eq">z = {fmt(modC(z), 3)} ∠ {fmt((argC(z) * 180) / Math.PI, 1)}°</p>
              <p className="cx-eq">w = {fmt(modC(w), 3)} ∠ {fmt((argC(w) * 180) / Math.PI, 1)}°</p>
              <h3>Fixed points</h3>
              {fixed.map((p, i) => <p key={i} className="cx-eq">z<sub>{i + 1}</sub> = {fmtC(p, 3)}</p>)}
              <h3>Domain check</h3>
              <p className={modC(addC(mulC(c, z), d)) < 1e-6 ? "cx-warn" : "cx-ok"}>
                Denominator (cz + d) = {fmtC(addC(mulC(c, z), d), 3)} {modC(addC(mulC(c, z), d)) < 1e-6 ? "= 0 pole" : "≠ 0"}
              </p>
              <p className="cx-meta">Pole at z = −d/c ≈ {Number.isFinite(pole.re) ? fmtC(pole, 3) : "∞"}</p>
              <h3>Explanation</h3>
              <p className="cx-note">Möbius transformations map circles and lines to circles and lines (or vice versa). Distances and angles are not preserved, but cross-ratios are.</p>
              <p className="cx-meta">Learn more</p>
            </CxLive>
            <section className="cx-xform">
              <h3>Transformation f(z)</h3>
              <div className="cx-ops">
                {(["Möbius", "Inversion", "Affine", "Rotation", "Scaling"] as const).map((item) => (
                  <button key={item} type="button" className={kind === item ? "active" : ""} onClick={() => setKind(item)}>
                    {item === "Möbius" ? "w = (az+b)/(cz+d)" : item === "Inversion" ? "w = 1/z" : item === "Affine" ? "w = αz + β" : item === "Rotation" ? "w = e^{iθ} z" : "w = kz"}
                  </button>
                ))}
              </div>
              <div className="cx-coeff">
                <CxStepper label="a" value={a.re} min={-3} max={3} onChange={(re) => setA({ ...a, re })} />
                <CxStepper label="ai" value={a.im} min={-3} max={3} onChange={(im) => setA({ ...a, im })} />
                <CxStepper label="b" value={b.re} min={-3} max={3} onChange={(re) => setB({ ...b, re })} />
                <CxStepper label="bi" value={b.im} min={-3} max={3} onChange={(im) => setB({ ...b, im })} />
                <CxStepper label="c" value={c.re} min={-3} max={3} onChange={(re) => setC({ ...c, re })} />
                <CxStepper label="ci" value={c.im} min={-3} max={3} onChange={(im) => setC({ ...c, im })} />
                <CxStepper label="d" value={d.re} min={-3} max={3} onChange={(re) => setD({ ...d, re })} />
                <CxStepper label="di" value={d.im} min={-3} max={3} onChange={(im) => setD({ ...d, im })} />
              </div>
              <p className="cx-eq">Determinant ad − bc = {fmtC(det, 3)} {modC(det) > 1e-8 ? "Valid (ad − bc ≠ 0)" : "Singular"}</p>
              <p className="cx-eq">w = (({fmtC(a, 2)})z + ({fmtC(b, 2)})) / (({fmtC(c, 2)})z + ({fmtC(d, 2)}))</p>
            </section>
          </>
        );
      }}
    </ComplexLabChrome>
  );
}

export function CircuitsLab({ page }: { page: StudioMockupPage }) {
  const [f, setF] = useStudioState("ComplexAdvancedLabs:CircuitsLab:f", 60);
  const [R, setR] = useStudioState("ComplexAdvancedLabs:CircuitsLab:R", 100);
  const [L, setL] = useStudioState("ComplexAdvancedLabs:CircuitsLab:L", 0.15);
  const [Ccap, setCcap] = useStudioState("ComplexAdvancedLabs:CircuitsLab:Ccap", 0.0001);
  const [Vrms, setVrms] = useStudioState("ComplexAdvancedLabs:CircuitsLab:Vrms", 10);
  const [phiV, setPhiV] = useStudioState("ComplexAdvancedLabs:CircuitsLab:phiV", 0);
  const [wt, setWt] = useStudioState("ComplexAdvancedLabs:CircuitsLab:wt", 45);
  const [cycles, setCycles] = useStudioState("ComplexAdvancedLabs:CircuitsLab:cycles", 2);
  const [playing, setPlaying] = useStudioState("ComplexAdvancedLabs:CircuitsLab:playing", false);
  const [grid, setGrid] = useStudioState("ComplexAdvancedLabs:CircuitsLab:grid", true);
  const [labels, setLabels] = useStudioState("ComplexAdvancedLabs:CircuitsLab:labels", true);
  useEffect(() => {
    if (!playing) return undefined;
    const id = window.setInterval(() => setWt((t) => (t + 3) % 360), 40);
    return () => window.clearInterval(id);
  }, [playing]);
  const { w, xl, xc, X, zMag, phi, pf } = seriesRLC(f, R, L, Ccap);
  const Irms = Vrms / zMag;
  const vInst = Vrms * Math.SQRT2 * Math.sin((wt * Math.PI) / 180 + (phiV * Math.PI) / 180);
  const iInst = Irms * Math.SQRT2 * Math.sin((wt * Math.PI) / 180 + (phiV * Math.PI) / 180 - phi);
  const pInst = vInst * iInst;
  const energyL = 0.5 * L * (iInst ** 2);
  const energyC = 0.5 * Ccap * (vInst ** 2);

  return (
    <ComplexLabChrome page={page} className="is-waves">
      {(mode) => (
        <>
          <div className="cx-waves-top">
            <CxSlider label="Frequency f" value={f} min={10} max={1000} step={1} display={`${fmt(f, 0)} Hz`} onChange={setF} />
            <CxSlider label="R" value={R} min={1} max={1000} step={1} display={`${fmt(R, 0)} Ω`} onChange={setR} />
            <CxSlider label="L" value={L} min={0.001} max={1} step={0.001} display={`${fmt(L * 1000, 0)} mH`} onChange={setL} />
            <CxSlider label="C" value={Ccap} min={1e-6} max={0.001} step={1e-6} display={`${fmt(Ccap * 1e6, 0)} μF`} onChange={setCcap} />
            <div>
              <CxStepper label="Source Vrms" value={Vrms} min={1} max={50} step={1} digits={0} onChange={setVrms} />
              <CxStepper label="∠ V" value={phiV} min={-180} max={180} step={1} digits={0} onChange={setPhiV} />
            </div>
          </div>
          <section className="cx-waves-phasor">
            <h2>Phasor diagram</h2>
            <CxToggle label="Show grid" on={grid} onChange={setGrid} />
            <CxToggle label="Show values" on={labels} onChange={setLabels} />
            <PhasorFigure R={R} xl={xl} xc={xc} I={Irms} V={Vrms} phi={phi} grid={grid} labels={labels} wt={wt} />
          </section>
          <section className="cx-waves-time">
            <h2>Time-domain waves</h2>
            <p className="cx-meta">φ = {fmt((phi * 180) / Math.PI, 2)}° (current {phi > 0 ? "lags" : "leads"} voltage)</p>
            <WavePlot Vrms={Vrms} Irms={Irms} phi={phi} wt={wt} cycles={cycles} />
            <div className="cx-play">
              <CxSlider label="ωt" value={wt} min={0} max={360} step={1} display={`${fmt(wt, 1)}°`} onChange={setWt} />
              <select aria-label="Cycles" value={cycles} onChange={(event) => setCycles(Number(event.target.value))}>
                <option value={1}>1</option>
                <option value={2}>2</option>
                <option value={3}>3</option>
              </select>
              <button type="button" aria-pressed={playing} onClick={() => setPlaying((v) => !v)}>{playing ? "Pause" : "Play"}</button>
            </div>
          </section>
          <CxLive title="Live complex values">
            <p>Impedance Z <strong>{fmt(R, 2)} {X < 0 ? "−" : "+"} j{fmt(Math.abs(X), 2)} Ω</strong></p>
            <p>|Z| <strong>{fmt(zMag, 2)} Ω</strong></p>
            <p>Angle ∠Z <strong>{fmt((phi * 180) / Math.PI, 2)}°</strong></p>
            <p>Current I <strong>{fmt(Irms, 2)} ∠ {fmt(phiV - (phi * 180) / Math.PI, 2)}° A</strong></p>
            <p>Voltage V <strong>{fmt(Vrms, 2)} ∠ {fmt(phiV, 1)}° V</strong></p>
            <p>Power (complex) S <strong>{fmt(Vrms * Irms, 2)} ∠ {fmt((phi * 180) / Math.PI, 2)}° VA</strong></p>
            <p>Real Power P <strong>{fmt(Vrms * Irms * pf, 2)} W</strong></p>
            <p>Reactive Power Q <strong>{fmt(Vrms * Irms * Math.sin(phi), 2)} var</strong></p>
            <p>Power Factor <strong>{fmt(pf, 3)} ({phi > 0 ? "lagging" : "leading"})</strong></p>
            <h3>Explanation</h3>
            <p className="cx-note">The current {phi > 0 ? "lags" : "leads"} the voltage by the impedance angle ∠Z = {fmt((phi * 180) / Math.PI, 2)}° because {Math.abs(xl) > Math.abs(xc) ? "inductive reactance is larger than capacitive" : "capacitive reactance is larger than inductive"}.</p>
            <p className="cx-note">Power factor = cos(∠Z) = {fmt(pf, 3)} {phi > 0 ? "lagging" : "leading"}.</p>
            <h3>Key formulas</h3>
            <p className="cx-eq">Z = R + j(ωL − 1/ωC)</p>
            <p className="cx-eq">I = V / Z</p>
            <p className="cx-eq">S = VI* = P + jQ</p>
            {mode === "Impedance" ? <p className="cx-meta">Impedance mode isolates Z, XL and XC.</p> : null}
            {mode === "AC Circuits" ? <p className="cx-meta">Series RLC: one current through R, L and C.</p> : null}
            {mode === "Signal Rotation" ? <p className="cx-meta">ωt rotates every phasor together on the Argand plane.</p> : null}
          </CxLive>
          <section className="cx-waves-rlc">
            <h2>RLC circuit (series)</h2>
            <svg viewBox="0 0 420 140" className="cx-plane" role="img" aria-label="Series RLC">
              <rect x="20" y="40" width="70" height="36" rx="8" fill="#fff" stroke="#94a3b8" />
              <text x="34" y="62" fontSize="12">V∠0°</text>
              <line x1="90" y1="58" x2="130" y2="58" stroke="#0f172a" />
              <rect x="130" y="46" width="70" height="24" fill="none" stroke="#0ea5e9" strokeWidth="2" />
              <text x="156" y="40" fontSize="12">R</text>
              <text x="148" y="86" fontSize="11">{fmt(R, 0)} Ω</text>
              <line x1="200" y1="58" x2="230" y2="58" stroke="#0f172a" />
              <path d="M230 58 h8 l6 -14 8 28 8 -28 8 28 6 -14 h8" fill="none" stroke="#8b5cf6" strokeWidth="2" />
              <text x="248" y="40" fontSize="12">L</text>
              <text x="236" y="86" fontSize="11">{fmt(L * 1000, 0)} mH</text>
              <line x1="282" y1="58" x2="310" y2="58" stroke="#0f172a" />
              <line x1="318" y1="40" x2="318" y2="76" stroke="#f59e0b" strokeWidth="2" />
              <line x1="328" y1="40" x2="328" y2="76" stroke="#f59e0b" strokeWidth="2" />
              <text x="316" y="34" fontSize="12">C</text>
              <text x="300" y="96" fontSize="11">{fmt(Ccap * 1e6, 0)} μF</text>
              <line x1="328" y1="58" x2="380" y2="58" stroke="#0f172a" />
              <line x1="380" y1="58" x2="380" y2="110" stroke="#0f172a" />
              <line x1="380" y1="110" x2="20" y2="110" stroke="#0f172a" />
              <line x1="20" y1="110" x2="20" y2="58" stroke="#0f172a" />
              <text x="140" y="128" fontSize="12">ω = 2πf = {fmt(w, 0)} rad/s</text>
            </svg>
          </section>
          <section className="cx-waves-tri">
            <h2>Impedance triangle</h2>
            <svg viewBox="0 0 320 160" className="cx-plane" role="img" aria-label="Impedance triangle">
              <polygon points="40,130 240,130 240,40" fill="rgba(251,191,36,.2)" stroke="#f59e0b" strokeWidth="2" />
              <text x="110" y="148" fontSize="12">R = {fmt(R, 2)} Ω</text>
              <text x="248" y="90" fontSize="12">X = {fmt(X, 2)} Ω</text>
              <text x="90" y="70" fontSize="12">|Z| = {fmt(zMag, 2)} Ω</text>
              <text x="150" y="122" fontSize="12">{fmt((phi * 180) / Math.PI, 2)}°</text>
              <text x="16" y="20" fontSize="12">X_L = ωL = {fmt(xl, 2)}</text>
              <text x="16" y="36" fontSize="12">X_C = 1/ωC = {fmt(xc, 2)}</text>
            </svg>
          </section>
          <div className="cx-waves-inst">
            <h2>Instantaneous values (at ωt = {fmt(wt, 1)}°)</h2>
            <p>v(t) <strong>{fmt(vInst, 3)} V</strong></p>
            <p>i(t) <strong>{fmt(iInst, 3)} A</strong></p>
            <p>Instantaneous Power p(t) <strong>{fmt(pInst, 2)} W</strong></p>
            <p>Energy in L <strong>{fmt(energyL * 1000, 2)} mJ</strong></p>
            <p>Energy in C <strong>{fmt(energyC * 1000, 2)} mJ</strong></p>
          </div>
        </>
      )}
    </ComplexLabChrome>
  );
}

function PhasorFigure({ R, xl, xc, I, V, phi, grid, labels, wt }: { R: number; xl: number; xc: number; I: number; V: number; phi: number; grid: boolean; labels: boolean; wt: number }) {
  const rot = (wt * Math.PI) / 180;
  const scale = 6;
  const VR = I * R;
  const VL = I * xl;
  const VC = I * xc;
  const pt = (mag: number, ang: number) => {
    const a = ang + rot;
    return { x: 210 + mag * scale * Math.cos(a), y: 150 - mag * scale * Math.sin(a) };
  };
  const v = pt(V, 0);
  const i = pt(I * 8, -phi);
  const jxl = pt(VL, Math.PI / 2);
  const jxc = pt(VC, -Math.PI / 2);
  return (
    <svg className="cx-plane" viewBox="0 0 420 300" role="img" aria-label="Phasor diagram">
      <rect width="420" height="300" fill="#f7fbff" rx="18" />
      {grid ? Array.from({ length: 7 }, (_, n) => <circle key={n} cx="210" cy="150" r={(n + 1) * 18} fill="none" stroke="#e2e8f0" />) : null}
      <line x1="20" y1="150" x2="400" y2="150" stroke="#94a3b8" />
      <line x1="210" y1="16" x2="210" y2="284" stroke="#94a3b8" />
      <text x="392" y="144" fontSize="12">Re</text>
      <text x="216" y="22" fontSize="12">Im</text>
      <line x1="210" y1="150" x2={v.x} y2={v.y} stroke="#fb923c" strokeWidth="2.6" markerEnd="url(#cx-r)" />
      <line x1="210" y1="150" x2={i.x} y2={i.y} stroke="#f59e0b" strokeWidth="2.6" />
      <line x1="210" y1="150" x2={jxl.x} y2={jxl.y} stroke="#8b5cf6" strokeWidth="2.2" />
      <line x1="210" y1="150" x2={jxc.x} y2={jxc.y} stroke="#22d3ee" strokeWidth="2.2" />
      {labels ? (
        <>
          <text x={v.x + 6} y={v.y} fontSize="11" fill="#ea580c">V {fmt(V, 2)}∠0°</text>
          <text x={i.x + 6} y={i.y} fontSize="11" fill="#d97706">I {fmt(I, 2)}∠{fmt((-phi * 180) / Math.PI, 2)}°</text>
          <text x={jxl.x + 4} y={jxl.y} fontSize="11" fill="#7c3aed">jX_L I</text>
          <text x={jxc.x + 4} y={jxc.y} fontSize="11" fill="#0e7490">−jX_C I</text>
        </>
      ) : null}
      <text x="300" y="28" fontSize="12">ωt = {fmt(wt, 1)}°</text>
    </svg>
  );
}

function WavePlot({ Vrms, Irms, phi, wt, cycles }: { Vrms: number; Irms: number; phi: number; wt: number; cycles: number }) {
  const vp = Vrms * Math.SQRT2;
  const ip = Irms * Math.SQRT2 * 8;
  const pts = (amp: number, shift: number) => Array.from({ length: 120 }, (_, i) => {
    const t = (i / 119) * cycles * Math.PI * 2;
    return `${20 + (i / 119) * 360},${80 - Math.sin(t + shift) * amp}`;
  }).join(" ");
  const cursor = 20 + (wt / 360) * 360;
  return (
    <svg className="cx-plane" viewBox="0 0 400 160" role="img" aria-label="Voltage and current waves">
      <rect width="400" height="160" fill="#f7fbff" rx="16" />
      <line x1="20" y1="80" x2="380" y2="80" stroke="#cbd5e1" />
      <polyline points={pts(vp * 3.2, 0)} fill="none" stroke="#22d3ee" strokeWidth="2.2" />
      <polyline points={pts(Math.min(48, ip), -phi)} fill="none" stroke="#fb923c" strokeWidth="2.2" />
      <line x1={cursor} y1="16" x2={cursor} y2="144" stroke="#94a3b8" strokeDasharray="4 3" />
      <text x="24" y="18" fontSize="11" fill="#0ea5e9">Voltage v(t)</text>
      <text x="120" y="18" fontSize="11" fill="#ea580c">Current i(t)</text>
    </svg>
  );
}

import { useStudioState } from "../phase1/StudioModelProvider";
import { useEffect, useState } from "react";
import type { StudioMockupPage } from "../mockup/studioMockupCatalog";
import { clamp, fmt } from "../mockup/studioLabKit";
import { ComplexLabChrome, CxCanvas, CxCol, CxLive, CxSlider, CxStepper, CxToggle } from "./ComplexLabChrome";
import { ComplexPlane, CxDot, CxRay, CX_R, CX_W, CX_Z } from "./complexArgandCanvas";
import { addC, argC, conjC, divC, fmtC, fmtSigned, fromPolar, modC, mulC, nthRoots, subC, wrapDeg, type C } from "./complexLabMath";

const OPS = ["Add", "Subtract", "Multiply", "Divide", "Conj"] as const;

function resultOf(mode: string, z1: C, z2: C): C {
  if (mode === "Subtract") return subC(z1, z2);
  if (mode === "Multiply") return mulC(z1, z2);
  if (mode === "Divide") return divC(z1, z2);
  if (mode === "Conjugate" || mode === "Conj") return conjC(z1);
  return addC(z1, z2);
}

function nearZero(z: C) {
  return modC(z) < 1e-9;
}

export function ComplexArithmeticLab({ page }: { page: StudioMockupPage }) {
  const [z1, setZ1] = useStudioState<C>("ComplexTargetLabs:ComplexArithmeticLab:z1", { re: 2.5, im: 1.5 });
  const [z2, setZ2] = useStudioState<C>("ComplexTargetLabs:ComplexArithmeticLab:z2", { re: -1, im: 2 });
  const [grid, setGrid] = useStudioState("ComplexTargetLabs:ComplexArithmeticLab:grid", true);
  const [axes, setAxes] = useStudioState("ComplexTargetLabs:ComplexArithmeticLab:axes", true);
  const [ticks, setTicks] = useStudioState("ComplexTargetLabs:ComplexArithmeticLab:ticks", true);
  const [para, setPara] = useStudioState("ComplexTargetLabs:ComplexArithmeticLab:para", true);
  const [proj, setProj] = useStudioState("ComplexTargetLabs:ComplexArithmeticLab:proj", true);
  const [playing, setPlaying] = useStudioState("ComplexTargetLabs:ComplexArithmeticLab:playing", false);
  const [speed, setSpeed] = useStudioState("ComplexTargetLabs:ComplexArithmeticLab:speed", 1);

  return (
    <ComplexLabChrome page={page}>
      {(mode, setMode) => {
        const op = OPS.includes(mode as typeof OPS[number]) || mode === "Conjugate" ? mode : "Add";
        const divideError = op === "Divide" && nearZero(z2);
        const res = divideError ? { re: Number.NaN, im: Number.NaN } : resultOf(op, z1, z2);
        const showPara = para && (op === "Add" || op === "Subtract");
        return (
          <>
            <CxCol>
              <div className="cx-card">
                <div className="cx-kicker">Operation</div>
                <div className="cx-ops" role="group" aria-label="Complex operation">
                  {OPS.map((item) => {
                    const key = item === "Conj" ? "Conjugate" : item;
                    const on = key === op || item === op;
                    return (
                      <button key={item} type="button" className={on ? "active" : ""} aria-pressed={on} onClick={() => setMode(key)}>
                        {item === "Add" ? "+ Add" : item === "Subtract" ? "− Subtract" : item === "Multiply" ? "× Multiply" : item === "Divide" ? "÷ Divide" : "Conj"}
                      </button>
                    );
                  })}
                </div>
              </div>
              <div className="cx-card">
                <div className="cx-kicker">Vectors (drag points)</div>
                <div className="cx-vec" data-tone="z">
                  <strong>z₁ = a + bi</strong>
                  <CxStepper label="a" value={z1.re} min={-4} max={4} onChange={(re) => setZ1({ ...z1, re })} />
                  <CxStepper label="b" value={z1.im} min={-4} max={4} onChange={(im) => setZ1({ ...z1, im })} />
                </div>
                {op === "Conjugate" ? (
                  <p className="cx-note">z₂ is hidden in conjugate mode; the result is conj(z₁).</p>
                ) : (
                  <div className="cx-vec" data-tone="w">
                    <strong>z₂ = c + di</strong>
                    <CxStepper label="c" value={z2.re} min={-4} max={4} onChange={(re) => setZ2({ ...z2, re })} />
                    <CxStepper label="d" value={z2.im} min={-4} max={4} onChange={(im) => setZ2({ ...z2, im })} />
                  </div>
                )}
              </div>
              <div className="cx-card">
                <div className="cx-kicker">Visual options</div>
                <CxToggle label="Show grid" on={grid} onChange={setGrid} />
                <CxToggle label="Show labels" on={ticks} onChange={setTicks} />
                <CxToggle label="Show parallelogram (sum)" on={para} onChange={setPara} />
                <CxToggle label="Show component projections" on={proj} onChange={setProj} />
                <CxToggle label="Show axes" on={axes} onChange={setAxes} />
              </div>
              <div className="cx-card">
                <div className="cx-kicker">Animation</div>
                <div className="cx-play">
                  <button type="button" aria-pressed={playing} onClick={() => setPlaying((v) => !v)}>{playing ? "Pause" : "Play"}</button>
                  <input type="range" min={0.25} max={2} step={0.25} value={speed} aria-label="Animation speed" onChange={(event) => setSpeed(Number(event.target.value))} />
                  <span>{speed.toFixed(1)} ×</span>
                </div>
              </div>
            </CxCol>
            <CxCanvas
              title="Argand Plane"
              tools={(
                <span className="cx-canvas-tools">
                  <button type="button" className={grid ? "active" : ""} onClick={() => setGrid((v) => !v)}>Grid</button>
                  <button type="button" className={axes ? "active" : ""} onClick={() => setAxes((v) => !v)}>Axes</button>
                  <button type="button" className={ticks ? "active" : ""} onClick={() => setTicks((v) => !v)}>Ticks</button>
                  <button type="button" aria-label="Zoom fit" onClick={() => { setZ1({ re: 2.5, im: 1.5 }); setZ2({ re: -1, im: 2 }); }}>Zoom fit</button>
                </span>
              )}
            >
              <ArithmeticFigure z1={z1} z2={z2} res={res} op={op} showGrid={grid} showAxes={axes} showTicks={ticks} showPara={showPara} showProj={proj} onZ1={setZ1} onZ2={setZ2} />
              <ul className="cx-legend">
                <li><i style={{ background: CX_Z }} />z₁</li>
                {op === "Conjugate" ? null : <li><i style={{ background: CX_W }} />z₂</li>}
                <li><i style={{ background: CX_R }} />{op === "Add" ? "z₁ + z₂" : op === "Subtract" ? "z₁ − z₂" : op === "Multiply" ? "z₁ × z₂" : op === "Divide" ? "z₁ ÷ z₂" : "conjugate"}</li>
                <li><i className="is-dash" />Parallelogram</li>
              </ul>
            </CxCanvas>
            <CxLive title={`Result (${op === "Conjugate" ? "conjugate" : op.toLowerCase()})`} badge={<span className="cx-badge">Exact</span>}>
              <p className="cx-eq">{op === "Add" ? "z₁ + z₂" : op === "Subtract" ? "z₁ − z₂" : op === "Multiply" ? "z₁ × z₂" : op === "Divide" ? "z₁ ÷ z₂" : "conj(z₁)"} = ({fmt(z1.re, 2)} + {fmt(z1.im, 2)}i) {op === "Add" ? "+" : op === "Subtract" ? "−" : op === "Multiply" ? "×" : op === "Divide" ? "÷" : ""} {op === "Conjugate" ? "" : `(${fmt(z2.re, 2)} + ${fmt(z2.im, 2)}i)`}</p>
              {divideError
                ? <p className="cx-eq is-ans">undefined (divide by 0)</p>
                : <p className="cx-eq is-ans">= {fmtC(res)}</p>}
              <h3>Polar form</h3>
              {divideError ? (
                <p className="cx-note">Cannot divide: |z₂| ≈ 0.</p>
              ) : (
                <>
                  <p className="cx-eq">r = √({fmt(res.re, 2)}² + {fmt(res.im, 2)}²) = {fmt(modC(res), 4)}</p>
                  <p className="cx-eq">θ = atan2({fmt(res.im, 2)}, {fmt(res.re, 2)}) = {fmt(wrapDeg(argC(res) * 180 / Math.PI), 4)}°</p>
                  <p className="cx-eq">{fmt(argC(res), 4)} rad</p>
                </>
              )}
              <h3>Interpretation</h3>
              <p className="cx-note">{op === "Add" ? "The sum is the diagonal of the parallelogram formed by z₁ and z₂." : op === "Multiply" ? "Multiply moduli and add arguments." : op === "Divide" ? (divideError ? "Cannot divide: |z₂| ≈ 0." : "Divide moduli and subtract arguments.") : op === "Subtract" ? "Subtraction is the vector from z₂ to z₁." : "Conjugation reflects across the real axis."}</p>
              {op === "Conjugate" || divideError ? null : <MiniSum z1={z1} z2={z2} res={res} />}
              <h3>Algebra (component form)</h3>
              <p className="cx-eq">(a + bi) + (c + di) = (a + c) + (b + d)i</p>
              <p className="cx-eq">= ({fmt(z1.re, 2)} + ({fmt(z2.re, 2)})) + ({fmt(z1.im, 2)} + {fmt(z2.im, 2)})i</p>
              <p className="cx-eq is-ans">= {fmtC(addC(z1, z2))}</p>
            </CxLive>
          </>
        );
      }}
    </ComplexLabChrome>
  );
}

function MiniSum({ z1, z2, res }: { z1: C; z2: C; res: C }) {
  return (
    <svg className="cx-mini-sum" viewBox="0 0 220 90" aria-hidden="true">
      <line x1="20" y1="70" x2="200" y2="70" stroke="#cbd5e1" />
      <line x1="30" y1="80" x2="30" y2="12" stroke="#cbd5e1" />
      <line x1="30" y1="70" x2={30 + z1.re * 18} y2={70 - z1.im * 18} stroke={CX_Z} strokeWidth="2.2" />
      <line x1="30" y1="70" x2={30 + z2.re * 18} y2={70 - z2.im * 18} stroke={CX_W} strokeWidth="2.2" />
      <line x1="30" y1="70" x2={30 + res.re * 18} y2={70 - res.im * 18} stroke={CX_R} strokeWidth="2.2" />
      <text x="160" y="22" fontSize="11" fill={CX_W}>z₂</text>
      <text x="150" y="48" fontSize="11" fill={CX_R}>z₁ + z₂</text>
      <text x="110" y="82" fontSize="11" fill={CX_Z}>z₁</text>
    </svg>
  );
}

function ArithmeticFigure({
  z1, z2, res, op, showGrid, showAxes, showTicks, showPara, showProj, onZ1, onZ2,
}: {
  z1: C; z2: C; res: C; op: string; showGrid: boolean; showAxes: boolean; showTicks: boolean; showPara: boolean; showProj: boolean;
  onZ1: (z: C) => void; onZ2: (z: C) => void;
}) {
  return (
    <ComplexPlane
      label="Argand plane parallelogram"
      showGrid={showGrid}
      showAxes={showAxes}
      showTicks={showTicks}
      onPick={(re, im) => {
        const p = { re: clamp(re, -4, 4), im: clamp(im, -4, 4) };
        if (op === "Conjugate" || Math.hypot(p.re - z1.re, p.im - z1.im) <= Math.hypot(p.re - z2.re, p.im - z2.im)) onZ1(p);
        else onZ2(p);
      }}
    >
      {({ x, y }) => (
        <>
          {showProj ? (
            <>
              <CxRay x1={x(z1.re)} y1={y(z1.im)} x2={x(z1.re)} y2={y(0)} color="#94a3b8" dashed />
              <CxRay x1={x(0)} y1={y(z1.im)} x2={x(z1.re)} y2={y(z1.im)} color="#94a3b8" dashed />
              <CxRay x1={x(z2.re)} y1={y(z2.im)} x2={x(z2.re)} y2={y(0)} color="#c4b5fd" dashed />
              <CxRay x1={x(0)} y1={y(z2.im)} x2={x(z2.re)} y2={y(z2.im)} color="#c4b5fd" dashed />
              <CxRay x1={x(res.re)} y1={y(res.im)} x2={x(res.re)} y2={y(0)} color="#fcd34d" dashed />
              <text x={x(z1.re / 2)} y={y(0) + 14} fontSize="11" fill={CX_Z}>{fmtSigned(z1.re)}</text>
              <text x={x(0) - 28} y={y(z1.im / 2)} fontSize="11" fill={CX_Z}>{fmtSigned(z1.im)}</text>
              <text x={x(z2.re) + 6} y={y(z2.im / 2)} fontSize="11" fill={CX_W}>{fmtSigned(z2.im)}</text>
              <text x={x(z2.re / 2)} y={y(0) - 8} fontSize="11" fill={CX_W}>{fmtSigned(z2.re)}</text>
            </>
          ) : null}
          {showPara ? (
            <polygon
              points={`${x(0)},${y(0)} ${x(z1.re)},${y(z1.im)} ${x(res.re)},${y(res.im)} ${x(z2.re)},${y(z2.im)}`}
              fill="rgba(245,158,11,.08)"
              stroke={CX_R}
              strokeDasharray="6 5"
              fillOpacity={0.12}
            />
          ) : null}
          <CxRay x1={x(0)} y1={y(0)} x2={x(z1.re)} y2={y(z1.im)} color={CX_Z} marker="cx-z" width={3} />
          {op !== "Conjugate" ? <CxRay x1={x(0)} y1={y(0)} x2={x(z2.re)} y2={y(z2.im)} color={CX_W} marker="cx-w" width={3} /> : null}
          {Number.isFinite(res.re) && Number.isFinite(res.im) ? (
            <>
              <CxRay x1={x(0)} y1={y(0)} x2={x(res.re)} y2={y(res.im)} color={CX_R} marker="cx-r" width={2.8} />
              <CxDot x={x(res.re)} y={y(res.im)} fill={CX_R} label={`R = ${op === "Add" ? "z₁ + z₂" : "result"}`} sub={fmtC(res)} />
            </>
          ) : null}
          <CxDot x={x(z1.re)} y={y(z1.im)} fill={CX_Z} label={`P  z₁ = ${fmtC(z1)}`} />
          {op !== "Conjugate" ? <CxDot x={x(z2.re)} y={y(z2.im)} fill={CX_W} label={`Q  z₂ = ${fmtC(z2)}`} /> : null}
        </>
      )}
    </ComplexPlane>
  );
}

export function PolarLab({ page }: { page: StudioMockupPage }) {
  const [re, setRe] = useStudioState("ComplexTargetLabs:PolarLab:re", 2);
  const [im, setIm] = useStudioState("ComplexTargetLabs:PolarLab:im", 1.5);
  const [linked, setLinked] = useStudioState("ComplexTargetLabs:PolarLab:linked", true);
  const [branch, setBranch] = useStudioState("ComplexTargetLabs:PolarLab:branch", -180);
  const [grid, setGrid] = useStudioState("ComplexTargetLabs:PolarLab:grid", true);
  const [axes, setAxes] = useStudioState("ComplexTargetLabs:PolarLab:axes", true);
  const [playing, setPlaying] = useStudioState("ComplexTargetLabs:PolarLab:playing", false);
  const [speed, setSpeed] = useStudioState("ComplexTargetLabs:PolarLab:speed", 1);
  const r = Math.hypot(re, im);
  const th = wrapDeg((Math.atan2(im, re) * 180) / Math.PI, branch);
  const setPolar = (nr: number, nth: number) => {
    const next = fromPolar(nr, nth);
    setRe(next.re);
    setIm(next.im);
  };
  useEffect(() => {
    if (!playing) return undefined;
    const id = window.setInterval(() => {
      setPolar(r, th + 2 * speed);
    }, 40);
    return () => window.clearInterval(id);
  }, [playing, r, speed, th]);
  const exactRe = re === 2 && Math.abs(im - 1.5) < 1e-6;

  return (
    <ComplexLabChrome page={page}>
      {(mode) => (
        <>
          <CxCol>
            <div className="cx-card">
              <div className="cx-step-title">1. Rectangular Form  a + bi</div>
              <CxStepper label="a =" value={re} min={-4} max={4} onChange={setRe} />
              <CxStepper label="b =" value={im} min={-4} max={4} onChange={setIm} />
              <output className="cx-form-pill">z = {fmt(re, 4)} + {fmt(im, 4)}i</output>
            </div>
            <div className="cx-card">
              <div className="cx-step-title">2. Polar Form  r ∠ θ</div>
              <CxSlider label="Modulus r" value={r} min={0.2} max={4} step={0.05} display={fmt(r, 4)} onChange={(nr) => setPolar(nr, th)} />
              <CxSlider label="Argument θ (degrees)" value={th} min={branch} max={branch + 359} step={0.1} display={fmt(th, 4)} onChange={(nth) => setPolar(r, nth)} />
              <output className="cx-form-pill">z = {fmt(r, 4)} ∠ {fmt(th, 4)}°</output>
            </div>
            <div className="cx-card">
              <div className="cx-step-title">3. Exponential Form  re<sup>iθ</sup></div>
              <CxSlider label="r =" value={r} min={0.2} max={4} step={0.05} display={fmt(r, 4)} onChange={(nr) => setPolar(nr, th)} />
              <CxSlider label="θ =" value={th} min={branch} max={branch + 359} step={0.1} display={`${fmt(th, 4)}°`} onChange={(nth) => setPolar(r, nth)} />
              <output className="cx-form-pill">z = {fmt(r, 4)} e<sup>i({fmt(th, 4)}°)</sup></output>
            </div>
            <div className="cx-card">
              <div className="cx-kicker">Link controls</div>
              <CxToggle label="Keep rectangular, polar, and exponential in sync." on={linked && Boolean(mode)} onChange={setLinked} />
            </div>
          </CxCol>
          <CxCanvas
            title="Argand Plane"
            tools={(
              <span className="cx-canvas-tools">
                <button type="button" className={grid ? "active" : ""} onClick={() => setGrid((v) => !v)}>Grid</button>
                <button type="button" className={axes ? "active" : ""} onClick={() => setAxes((v) => !v)}>Axes</button>
              </span>
            )}
          >
            <ComplexPlane label="Polar Argand plane" xmin={-4.4} xmax={4.4} ymin={-4.4} ymax={4.4} showGrid={grid} showAxes={axes} onPick={(x, y) => { setRe(clamp(x, -4, 4)); setIm(clamp(y, -4, 4)); }}>
              {({ x, y, u }) => {
                const rad = (th * Math.PI) / 180;
                const px = x(re);
                const py = y(im);
                const arc = Array.from({ length: 24 }, (_, i) => {
                  const a = (rad * i) / 23;
                  return `${x(0.55 * Math.cos(a))} ${y(0.55 * Math.sin(a))}`;
                }).join(" L ");
                return (
                  <>
                    <circle cx={x(0)} cy={y(0)} r={u} fill="none" stroke="#f59e0b" strokeDasharray="5 5" />
                    <circle cx={x(0)} cy={y(0)} r={r * u} fill="none" stroke="#f59e0b" />
                    <path d={`M ${x(0.55)} ${y(0)} L ${arc}`} fill="rgba(251,146,60,.35)" stroke="#fb923c" />
                    <CxRay x1={x(0)} y1={y(0)} x2={px} y2={py} color="#fb923c" width={3} />
                    <text x={x(0) + 8} y={y(r) - 8} fontSize="12" fill="#f59e0b">r = {fmt(r, 4)}</text>
                    <text x={x(0.7 * Math.cos(rad / 2))} y={y(0.7 * Math.sin(rad / 2))} fontSize="12" fill="#ea580c">θ = {fmt(th, 4)}°</text>
                    {[["0°", 0], ["90°", 90], ["180°", 180], ["−90°", -90]].map(([lab, deg]) => {
                      const a = (Number(deg) * Math.PI) / 180;
                      return <text key={lab} x={x(4.05 * Math.cos(a))} y={y(4.05 * Math.sin(a))} fontSize="11" fill="#94a3b8">{lab}</text>;
                    })}
                    <CxDot x={px} y={py} fill="#0ea5e9" label={`z = ${fmt(re, 1)} + ${fmt(im, 1)}i`} />
                  </>
                );
              }}
            </ComplexPlane>
            <ul className="cx-legend">
              <li><i style={{ background: "#0ea5e9" }} />Point z</li>
              <li><i style={{ background: "#f59e0b" }} />Radius r</li>
              <li><i style={{ background: "#fb923c" }} />Angle θ</li>
              <li><i className="is-dash" />Grid</li>
              <li><i style={{ background: "#fcd34d" }} />Unit circle</li>
            </ul>
            <div className="cx-play">
              <button type="button" aria-pressed={playing} onClick={() => setPlaying((v) => !v)}>{playing ? "Pause conversion" : "Animate conversion"}</button>
              <input type="range" min={0.25} max={2} step={0.25} value={speed} aria-label="Speed" onChange={(event) => setSpeed(Number(event.target.value))} />
              <span>Speed {speed.toFixed(1)}x</span>
            </div>
          </CxCanvas>
          <CxLive title="Live Values (Exact)" badge={linked ? <span className="cx-badge">Linked</span> : null}>
            <h3>Rectangular</h3>
            <p className="cx-eq is-ans">z = {exactRe ? "2 + 3/2 i" : fmtC({ re, im }, 4)}</p>
            <h3>Polar</h3>
            <p className="cx-eq is-ans">z = {exactRe ? "5/2 ∠ 36.86989765°" : `${fmt(r, 8)} ∠ ${fmt(th, 8)}°`}</p>
            <h3>Exponential (Euler)</h3>
            <p className="cx-eq is-ans">z = {exactRe ? "5/2 e^{i(36.86989765°)}" : `${fmt(r, 4)} e^{i(${fmt(th, 4)}°)}`}</p>
            <p className="cx-meta">|z| = {exactRe ? "5/2" : fmt(r, 4)}   Re(z) = {fmt(re, 2)}   Im(z) = {exactRe ? "3/2" : fmt(im, 2)}</p>
            <h3>Euler’s Representation</h3>
            <p className="cx-eq">e<sup>iθ</sup> = cos θ + i sin θ</p>
            <p className="cx-eq">e<sup>i({fmt(th, 4)}°)</sup> = {fmt(Math.cos(th * Math.PI / 180), 4)} + {fmt(Math.sin(th * Math.PI / 180), 4)} i</p>
            <h3>Branch of Argument</h3>
            <label className="cx-select">
              Principal Value
              <select aria-label="Argument branch" value={branch} onChange={(event) => setBranch(Number(event.target.value))}>
                <option value={-180}>θ ∈ (−180°, 180°]</option>
                <option value={0}>θ ∈ [0°, 360°)</option>
              </select>
            </label>
            <p className="cx-ok">θ = {fmt(th, 8)}°  Valid</p>
            <p className="cx-warn">Other values: θ + k·360°,  k ∈ ℤ</p>
            <h3>Identity Check</h3>
            <p className="cx-eq">e<sup>iθ</sup>(cos θ − i sin θ) = 1</p>
            <p className="cx-ok">Holds (within tolerance)</p>
          </CxLive>
        </>
      )}
    </ComplexLabChrome>
  );
}

export function RotationLab({ page }: { page: StudioMockupPage }) {
  const [a, setA] = useStudioState("ComplexTargetLabs:RotationLab:a", 1.5);
  const [b, setB] = useStudioState("ComplexTargetLabs:RotationLab:b", 1);
  const [r, setR] = useStudioState("ComplexTargetLabs:RotationLab:r", 1.4);
  const [th, setTh] = useStudioState("ComplexTargetLabs:RotationLab:th", 60);
  const [n, setN] = useStudioState("ComplexTargetLabs:RotationLab:n", 8);
  const [showSeq, setShowSeq] = useState(true);
  const [showCircles, setShowCircles] = useState(true);
  const [showPath, setShowPath] = useState(true);
  const [axes, setAxes] = useStudioState("ComplexTargetLabs:RotationLab:axes", true);
  const [grid, setGrid] = useStudioState("ComplexTargetLabs:RotationLab:grid", true);
  const [labels, setLabels] = useStudioState("ComplexTargetLabs:RotationLab:labels", true);
  const z: C = { re: a, im: b };
  const w = fromPolar(r, th);
  const wz = mulC(z, w);
  const seq = Array.from({ length: n }, (_, k) => {
    let p = z;
    for (let i = 0; i < k; i += 1) p = mulC(p, w);
    return p;
  });
  const magZ = modC(z);
  const argZ = wrapDeg((argC(z) * 180) / Math.PI);
  const magW = modC(w);
  const magWz = modC(wz);

  return (
    <ComplexLabChrome page={page}>
      {() => (
        <>
          <CxCol>
            <div className="cx-card">
              <strong className="cx-dot-title" data-tone="z">Complex number z (input)</strong>
              <p className="cx-eq">z = a + bi</p>
              <CxStepper label="a" value={a} min={-3} max={3} onChange={setA} />
              <CxStepper label="b" value={b} min={-3} max={3} onChange={setB} />
              <p className="cx-meta">|z| = {fmt(magZ, 3)}   arg z = {fmt(argZ, 2)}°</p>
            </div>
            <div className="cx-card">
              <strong className="cx-dot-title" data-tone="w">Multiplier w</strong>
              <p className="cx-eq">w = r e<sup>iθ</sup></p>
              <CxSlider label="Modulus r" value={r} min={0.1} max={3} step={0.05} display={fmt(r, 2)} onChange={setR} />
              <CxSlider label="Argument θ" value={th} min={-180} max={180} step={1} display={`${fmt(th, 0)}°`} onChange={setTh} />
              <div className="cx-snaps">
                {[-90, -45, 45, 90, 180].map((d) => (
                  <button key={d} type="button" className={th === d ? "active" : ""} onClick={() => setTh(d)}>{d > 0 ? `+${d}°` : `${d}°`}</button>
                ))}
              </div>
              <p className="cx-eq">w (rectangular) {fmtC(w)}</p>
              <p className="cx-meta">|w| = {fmt(magW, 3)}   arg w = {fmt(th, 2)}°</p>
            </div>
            <div className="cx-card">
              <strong>Repeated multiplication</strong>
              <CxSlider label="n (steps)" value={n} min={1} max={24} step={1} display={String(n)} onChange={setN} />
              <CxToggle label="Show sequence" on={showSeq} onChange={setShowSeq} />
              <CxToggle label="Show scale circles" on={showCircles} onChange={setShowCircles} />
              <CxToggle label="Show path" on={showPath} onChange={setShowPath} />
            </div>
          </CxCol>
          <CxCanvas
            title="Argand Plane"
            tools={(
              <span className="cx-canvas-tools">
                <button type="button" className={axes ? "active" : ""} onClick={() => setAxes((v) => !v)}>Axes</button>
                <button type="button" className={grid ? "active" : ""} onClick={() => setGrid((v) => !v)}>Grid</button>
                <button type="button" className={labels ? "active" : ""} onClick={() => setLabels((v) => !v)}>Labels</button>
                <button type="button" className="active">Equal scale</button>
                <button type="button" onClick={() => { setA(1.5); setB(1); setR(1.4); setTh(60); }}>Reset view</button>
              </span>
            )}
          >
            <ComplexPlane label="Multiplication as rotation" xmin={-3.4} xmax={3.4} ymin={-3.4} ymax={3.4} showGrid={grid} showAxes={axes} showTicks={labels}>
              {({ x, y, u }) => {
                const rad = (th * Math.PI) / 180;
                return (
                  <>
                    {showCircles ? seq.map((p, i) => <circle key={`c${i}`} cx={x(0)} cy={y(0)} r={Math.max(4, modC(p) * u)} fill="none" stroke="#fbbf24" strokeDasharray="4 6" />) : null}
                    {showPath ? <polyline fill="none" stroke="#c4b5fd" strokeWidth="1.6" points={seq.map((p) => `${x(p.re)},${y(p.im)}`).join(" ")} /> : null}
                    <path d={`M ${x(0.5)} ${y(0)} A 40 40 0 ${th < 0 ? 0 : 0} 1 ${x(0.5 * Math.cos(rad))} ${y(0.5 * Math.sin(rad))}`} fill="rgba(251,146,60,.35)" stroke="#fb923c" />
                    <text x={x(0.7 * Math.cos(rad / 2))} y={y(0.7 * Math.sin(rad / 2))} fontSize="12" fill="#ea580c">θ = {fmt(th, 0)}°</text>
                    <CxRay x1={x(0)} y1={y(0)} x2={x(z.re)} y2={y(z.im)} color={CX_Z} marker="cx-z" />
                    <CxRay x1={x(0)} y1={y(0)} x2={x(wz.re)} y2={y(wz.im)} color={CX_W} marker="cx-w" />
                    {showSeq ? seq.map((p, i) => (
                      <g key={i}>
                        <circle cx={x(p.re)} cy={y(p.im)} r={i === 0 ? 6 : 4} fill={i === 0 ? CX_Z : i === 1 ? CX_W : "#a78bfa"} stroke="#fff" />
                        {labels && (i === 0 || i === 1 || i === 2 || i === 3) ? <text x={x(p.re) + 8} y={y(p.im) - 8} fontSize="11" fontWeight={800} fill="#0f172a">{i === 0 ? "z" : i === 1 ? "wz" : `|w|${i === 2 ? "²" : "³"}`}</text> : null}
                      </g>
                    )) : null}
                    <CxDot x={x(z.re)} y={y(z.im)} fill={CX_Z} label={`${fmtC(z)}`} />
                    <CxDot x={x(wz.re)} y={y(wz.im)} fill={CX_W} label={`${fmtC(wz, 3)}`} />
                  </>
                );
              }}
            </ComplexPlane>
            <ul className="cx-legend">
              <li><i style={{ background: CX_Z }} />z (input)</li>
              <li><i style={{ background: CX_W }} />wz (product)</li>
              <li><i className="is-dash" />Rotation by θ</li>
              <li><i style={{ background: CX_R }} />|w| scale</li>
              <li><i style={{ background: "#c4b5fd" }} />Sequence (n = {n})</li>
            </ul>
          </CxCanvas>
          <CxLive title="Product">
            <p className="cx-eq is-ans">wz {fmtC(wz, 3)}</p>
            <p className="cx-meta">|wz| = {fmt(magWz, 3)}   arg(wz) = {fmt(wrapDeg(argC(wz) * 180 / Math.PI), 2)}°</p>
            <h3>Polar form</h3>
            <p className="cx-eq">wz = {fmt(magWz, 3)} e<sup>i{fmt(wrapDeg(argC(wz) * 180 / Math.PI), 2)}°</sup></p>
            <h3>Rotation &amp; scaling</h3>
            <p className="cx-meta">|w| = {fmt(magW, 3)} (scale {fmt(magW, 3)})</p>
            <p className="cx-meta">arg w = {fmt(th, 2)}° (rotate {th >= 0 ? "+" : ""}{fmt(th, 2)}°)</p>
            <h3>Transformation matrix</h3>
            <p className="cx-eq">z ↦ wz</p>
            <p className="cx-eq">M = [ {fmt(w.re, 3)}  {fmt(-w.im, 3)} ; {fmt(w.im, 3)}  {fmt(w.re, 3)} ]</p>
            <h3>Explanation</h3>
            <p className="cx-note">Multiplying by w = r e<sup>iθ</sup> rotates by θ and scales by r. Each step: multiply by w. After n steps: w<sup>n</sup> z.</p>
          </CxLive>
        </>
      )}
    </ComplexLabChrome>
  );
}

export function RootsLab({ page }: { page: StudioMockupPage }) {
  const [r, setR] = useStudioState("ComplexTargetLabs:RootsLab:r", 8);
  const [th, setTh] = useStudioState("ComplexTargetLabs:RootsLab:th", 40);
  const [n, setN] = useStudioState("ComplexTargetLabs:RootsLab:n", 6);
  const [all, setAll] = useStudioState("ComplexTargetLabs:RootsLab:all", true);
  const [principal, setPrincipal] = useStudioState("ComplexTargetLabs:RootsLab:principal", false);
  const [polygon, setPolygon] = useStudioState("ComplexTargetLabs:RootsLab:polygon", true);
  const [rotate, setRotate] = useStudioState("ComplexTargetLabs:RootsLab:rotate", false);
  const [speed, setSpeed] = useStudioState("ComplexTargetLabs:RootsLab:speed", 1);
  const [form, setForm] = useStudioState<"Polar" | "Rectangular">("ComplexTargetLabs:RootsLab:form", "Polar");
  useEffect(() => {
    if (!rotate) return undefined;
    const id = window.setInterval(() => setTh((v) => wrapDeg(v + speed)), 40);
    return () => window.clearInterval(id);
  }, [rotate, speed]);
  const z = fromPolar(r, th);

  return (
    <ComplexLabChrome page={page} pills>
      {(mode) => {
        const unity = mode === "Roots of Unity";
        const square = mode === "Square Roots";
        const degree = square ? 2 : n;
        const source = unity ? { re: 1, im: 0 } : z;
        const pts = nthRoots(source, degree);
        const vis = principal ? pts.slice(0, 1) : pts;
        const span = Math.max(1.6, modC(pts[0] ?? { re: 1, im: 0 }) * 1.35);
        const rr = modC(pts[0] ?? { re: 1, im: 0 });
        const polyPts = vis.map((p) => p);
        return (
          <>
            <CxCol>
              <div className="cx-card">
                <div className="cx-step-title">1. Choose complex number z</div>
                <select aria-label="Choose z" value={`${r}|${th}`} onChange={(event) => {
                  const [nr, nt] = event.target.value.split("|").map(Number);
                  setR(nr ?? 8);
                  setTh(nt ?? 40);
                }}>
                  <option value="8|40">z = 8 ∠ 40°</option>
                  <option value="1|0">z = 1</option>
                  <option value="4|90">z = 4 ∠ 90°</option>
                  <option value="9|180">z = 9 ∠ 180°</option>
                </select>
                <div className="cx-ops">
                  <button type="button" className={form === "Polar" ? "active" : ""} onClick={() => setForm("Polar")}>Polar</button>
                  <button type="button" className={form === "Rectangular" ? "active" : ""} onClick={() => setForm("Rectangular")}>Rectangular</button>
                </div>
                <p className="cx-eq">{form === "Polar" ? `r = ${fmt(r, 0)}   θ = ${fmt(th, 0)}°` : fmtC(z, 2)}</p>
              </div>
              <div className="cx-card">
                <div className="cx-step-title">2. Degree of roots (n)</div>
                <CxSlider label="n =" value={square ? 2 : n} min={2} max={20} step={1} display={String(degree)} onChange={setN} />
              </div>
              <div className="cx-card">
                <div className="cx-step-title">3. Mode options</div>
                <CxToggle label="All roots" on={all && !principal} onChange={(v) => { setAll(v); if (v) setPrincipal(false); }} />
                <CxToggle label="Principal root only" on={principal} onChange={(v) => { setPrincipal(v); if (v) setAll(false); }} />
                <CxToggle label="Vertex sequence" on={!principal} onChange={(v) => setPrincipal(!v)} />
                <CxToggle label="Show polygon" on={polygon} onChange={setPolygon} />
              </div>
              <div className="cx-card">
                <div className="cx-step-title">4. Animation</div>
                <CxToggle label="Rotate roots" on={rotate} onChange={setRotate} />
                <CxSlider label="Speed" value={speed} min={0.25} max={2} step={0.25} display={`${speed.toFixed(1)}x`} onChange={setSpeed} />
                <div className="cx-ops">
                  <button type="button" onClick={() => { setR(8); setTh(40); setN(6); }}>Reset</button>
                  <button type="button" onClick={() => { setR(1 + Math.round(Math.random() * 8)); setTh(Math.round(Math.random() * 360 - 180)); }}>Random z</button>
                </div>
              </div>
            </CxCol>
            <CxCanvas
              title="Argand plane (Unit Circle)"
              tools={(
                <span className="cx-canvas-tools">
                  <button type="button" className="active">Grid</button>
                  <button type="button" className="active">Axes</button>
                  <button type="button">Pan</button>
                  <button type="button">Zoom in</button>
                  <button type="button">Zoom out</button>
                  <button type="button">Reset view</button>
                </span>
              )}
            >
              <ComplexPlane label="nth roots" xmin={-span} xmax={span} ymin={-span} ymax={span}>
                {({ x, y, u }) => {
                  const poly = polyPts.map((p) => `${x(p.re)},${y(p.im)}`).join(" ");
                  const arg0 = argC(source);
                  return (
                    <>
                      <circle cx={x(0)} cy={y(0)} r={u} fill="rgba(148,163,184,.18)" stroke="#cbd5e1" />
                      <circle cx={x(0)} cy={y(0)} r={rr * u} fill="none" stroke="#f59e0b" strokeDasharray="5 5" />
                      {polygon && vis.length > 1 ? <polygon points={poly} fill="none" stroke={CX_R} strokeWidth="2.4" /> : null}
                      <CxRay x1={x(0)} y1={y(0)} x2={x(vis[0]?.re ?? 0)} y2={y(vis[0]?.im ?? 0)} color="#6366f1" marker="cx-w" />
                      <path d={`M ${x(0.35)} ${y(0)} A 24 24 0 0 1 ${x(0.35 * Math.cos(arg0 / degree))} ${y(0.35 * Math.sin(arg0 / degree))}`} fill="rgba(99,102,241,.2)" stroke="#6366f1" />
                      <text x={x(0.55 * Math.cos(arg0 / (2 * degree)))} y={y(0.55 * Math.sin(arg0 / (2 * degree)))} fontSize="12" fill="#4f46e5">{fmt((arg0 * 180) / Math.PI / degree, 0)}°</text>
                      {vis.map((p, i) => (
                        <g key={i}>
                          <circle cx={x(p.re)} cy={y(p.im)} r="7" fill={i === 0 ? CX_W : CX_R} stroke="#fff" strokeWidth="2" />
                          <text x={x(p.re) + 10} y={y(p.im) - 8} fontSize="11" fontWeight={800} fill="#0f172a">{`z${i === 0 ? "₀" : `_${i}`}^{1/${degree}`}</text>
                          <text x={x(p.re) + 10} y={y(p.im) + 8} fontSize="10" fill="#64748b">{`${fmt(modC(p), 4)} ∠ ${fmt(wrapDeg(argC(p) * 180 / Math.PI), 0)}°`}</text>
                        </g>
                      ))}
                      <CxDot x={x(source.re > 3 ? 1 : source.re)} y={y(source.im > 3 ? 0 : source.im)} fill={CX_W} label={`z = ${fmt(unity ? 1 : r, 0)} ∠ ${fmt(unity ? 0 : th, 0)}°`} />
                    </>
                  );
                }}
              </ComplexPlane>
              <ul className="cx-legend">
                <li><i style={{ background: CX_W }} />z (given)</li>
                <li><i style={{ background: CX_R }} />Roots</li>
                <li><i className="is-dash" />Unit circle (|z| = 1)</li>
                <li><i style={{ background: "#6366f1" }} />Angle θ / n</li>
              </ul>
            </CxCanvas>
            <CxLive title="Live values">
              <p className="cx-eq">z = {fmt(unity ? 1 : r, 0)} ∠ {fmt(unity ? 0 : th, 0)}°</p>
              <p className="cx-meta">|z| = {fmt(unity ? 1 : r, 0)}   n = {degree}   arg(z) = {fmt(unity ? 0 : th, 0)}°</p>
              <h3>Principal root (k = 0)</h3>
              <p className="cx-eq is-ans">z<sup>1/{degree}</sup>₀ = {fmt(rr, 4)} ∠ {fmt(wrapDeg(argC(pts[0] ?? { re: 1, im: 0 }) * 180 / Math.PI), 4)}°</p>
              <p className="cx-eq">= {fmtC(pts[0] ?? { re: 1, im: 0 }, 4)}</p>
              <h3>De Moivre’s theorem</h3>
              <p className="cx-eq">If z = r∠θ, then the n nth roots are</p>
              <p className="cx-eq">z<sup>1/n</sup><sub>k</sub> = r<sup>1/n</sup> ∠ (θ + 360° k) / n , k = 0, 1, …, n − 1</p>
              <ol className="cx-steps">
                <li>Write z in polar form: z = {fmt(unity ? 1 : r, 0)} ∠ {fmt(unity ? 0 : th, 0)}°</li>
                <li>Compute r<sup>1/n</sup> = {fmt(unity ? 1 : r, 0)}<sup>1/{degree}</sup> = {fmt(rr, 4)}</li>
                <li>Angles: ({fmt(unity ? 0 : th, 0)}° + 360° k) / {degree} , k = 0, …, {degree - 1}</li>
                <li>Plot each root on the Argand plane.</li>
              </ol>
              <p className="cx-ok">Identity verified</p>
              <h3>All roots table</h3>
              <table className="cx-table">
                <thead><tr><th>k</th><th>z<sub>k</sub><sup>1/n</sup> (Polar)</th><th>z<sub>k</sub> (Rectangular)</th></tr></thead>
                <tbody>
                  {pts.map((p, k) => (
                    <tr key={k}>
                      <td>{k}</td>
                      <td>{fmt(modC(p), 4)} ∠ {fmt(wrapDeg(argC(p) * 180 / Math.PI), 4)}°</td>
                      <td>{fmtC(p, 4)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </CxLive>
          </>
        );
      }}
    </ComplexLabChrome>
  );
}

import { useLayoutEffect, useRef } from 'react';
import { Link, Outlet, useLocation } from 'react-router-dom';
import { studioForPath, curriculumStudios } from './curriculumCatalog';
import { useStudioModel } from '../phase1/StudioModelProvider';
import FocusedLab from './FocusedLab';
import { useSetTheoryStore } from '../../modules/set-theory/setTheoryStore';
import { useGraphTheoryStore } from '../../modules/graph-theory/graphTheoryStore';
import './studioLearning.css';
const dataOnly=(state:Record<string,unknown>)=>Object.fromEntries(Object.entries(state).filter(([,v])=>typeof v!=='function'));
/** Store-backed labs participate in the same figure history without duplicating their engines. */
function StoreBridge({id}:{id:string}){
  const context=useStudioModel(),initial=useRef<Record<string,unknown>|null>(null);
  useLayoutEffect(()=>{
    if(!context||!['set-theory','graph-theory'].includes(id))return;
    const store=id==='set-theory'?useSetTheoryStore:useGraphTheoryStore;
    const key=`store:${id}`,state=dataOnly(store.getState());initial.current=state;
    const restored=context.ledger.initial(key,state);
    const apply=(value:unknown)=>{if(id==='set-theory')useSetTheoryStore.setState(value as Partial<ReturnType<typeof useSetTheoryStore.getState>>);else useGraphTheoryStore.setState(value as Partial<ReturnType<typeof useGraphTheoryStore.getState>>);};
    apply(restored);
    const unregister=context.ledger.register(key,state,restored,apply);
    const unsubscribe=store.subscribe(current=>context.ledger.commit(key,dataOnly(current)));
    return ()=>{unsubscribe();unregister();};
  },[context?.ledger,id]);
  return null;
}
export default function StudioLearningOutlet(){
  const {pathname}=useLocation();
  const curriculumId=/^\/studios\/([^/]+)\/curriculum/.exec(pathname)?.[1];
  const studio=studioForPath(pathname)||curriculumStudios.find(s=>s.id===curriculumId);
  if(!studio)return <Outlet/>;
  const lab=pathname.replace(/\/$/,'')!==studio.base&&!pathname.startsWith('/studios/');
  return <div className="studio-learning-host" data-studio-home={pathname.replace(/\/$/,'') === studio.base ? studio.id : undefined}><StoreBridge id={studio.id}/><nav className="studio-learning-nav" aria-label="Studio learning and model controls"><Link to={studio.base}>Studio Home Page</Link><Link to="/">Main App Home Page</Link></nav><div className="studio-learning-content">{lab?<FocusedLab key={pathname}><Outlet/></FocusedLab>:<Outlet/>}</div></div>;
}

import { useStudioState } from "../phase1/StudioModelProvider";
import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
