        : mode === "Coloring"
          ? "coloring"
          : mode === "Spanning Trees"
            ? "trees"
            : mode === "Flows"
              ? "flow"
              : "build";
    return (GRAPH_TABS as readonly string[]).includes(preferred) ? preferred : "algorithms";
  };
  return (
    <Phase1LabChrome page={page}>
      {(mode) => (
        <>
          <Panel title={mode}>
            <p className="msk-note">Graph networks in Discrete World open the Graph Theory engine so Dijkstra, MST, and coloring stay one product.</p>
            <Link className="msk-cta" to={`/graph-theory?tab=${tab(mode)}`}>Open Graph Theory · {mode}</Link>
          </Panel>
          <section className="msk-panel msk-canvas" data-mode-canvas={mode}>
            <h2>Algorithm race: shortest paths and minimum spanning tree</h2>
            <div className="msk-seg"><button type="button" disabled={step === 0} onClick={() => setStep((n) => n - 1)}>Previous step</button><button type="button" disabled={step >= Math.max(shortest.length, spanning.length) - 1} onClick={() => setStep((n) => n + 1)}>Next step</button><button type="button" onClick={() => setStep(0)}>Restart</button></div>
            <p className="msk-note">Step {step} of {Math.max(shortest.length, spanning.length) - 1}. Blue = Dijkstra from A; purple = Kruskal spanning tree; dashed = candidate.</p>
            {([shortest, spanning] as const).map((steps, race) => { const current = steps[Math.min(step, steps.length - 1)]; const color = race ? "#8b45f4" : "#147df2"; return <div key={race}>
              <h3>{race ? "Kruskal · minimum spanning tree" : "Dijkstra · shortest paths from A"}</h3>
              <svg className="msk-graph" viewBox="0 0 360 180" role="img" aria-label={race ? "Kruskal spanning tree step" : "Dijkstra shortest path step"}>
              <rect width="360" height="180" fill="#f8fbff" />
              {raceEdges.map((edge) => { const [x1, y1] = positions[edge.a], [x2, y2] = positions[edge.b]; const id = edgeId(edge); return <g key={id}><line x1={x1} y1={y1} x2={x2} y2={y2} stroke={current.chosen.includes(id) ? color : "#94a3b8"} strokeWidth={current.chosen.includes(id) ? 4 : 2} strokeDasharray={current.candidates.includes(id) && !current.chosen.includes(id) ? "4 3" : undefined} /><text x={(x1 + x2) / 2} y={(y1 + y2) / 2 - 4} fill="#334155" fontSize="11">{edge.w}</text></g>; })}
              {Object.entries(positions).map(([node, [x, y]]) => <g key={node}><circle cx={x} cy={y} r="13" fill={current.visited.includes(node) ? color : "#fff"} stroke={color} strokeWidth="2" /><text x={x} y={y + 4} textAnchor="middle" fontSize="12" fill={current.visited.includes(node) ? "#fff" : "#1e293b"}>{node}</text></g>)}
              </svg><p className="msk-note">{current.reason} Cost: {current.cost}. Visited: {current.visited.join(", ") || "none"}. Candidate edges: {current.candidates.join(", ") || "none"}.</p>
            </div>; })}
          </section>
          <aside className="msk-panel msk-live">
            <LiveRow color="#147df2" label="Dijkstra current distance" value={String(shortest[Math.min(step, shortest.length - 1)].cost)} />
            <LiveRow color="#8b45f4" label="Kruskal tree cost" value={String(spanning[Math.min(step, spanning.length - 1)].cost)} />
            <StatusOk>A tree with n vertices has n−1 edges. Prove it on a graph you build.</StatusOk>
            <StepList items={["Open Graph Theory.", "Run Dijkstra on your graph.", "Return via Discrete World when hopping topics."]} />
          </aside>
        </>
      )}
    </Phase1LabChrome>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useState } from "react";
import {
  ENUM_DISPLAY_CAP,
  ENUM_PERM_LIMIT,
  factorial,
  generatePermutations,
  generatePermutationsWithRep,
  letters,
  nextPermutation,
  permutation,
  power,
  prevPermutation,
  uniqueArrangementCount,
} from "./combinatoricsMath";
import { parseArrKind, type ArrKind } from "./combinatoricsMode";
import {
  ChallengeCard,
  ComboWorkspace,
  FormulaCard,
  LiveRow,
  ProductPath,
  Seg,
  Slider,
  Slot,
  Token,
  tokenColor,
} from "./combinatoricsUi";

const CHALLENGES = [
  { prompt: "How many ways to arrange 5 distinct objects?", expected: 120, hint: "5! = 5×4×3×2×1.", proof: "5! = 120" },
  { prompt: "P(6,3) = ?", expected: 120, hint: "6×5×4.", proof: "P(6,3) = 6!/(6−3)! = 120" },
  { prompt: "Circular arrangements of 5 distinct people?", expected: 24, hint: "Fix one person: (5−1)!.", proof: "(5−1)! = 24" },
  { prompt: "Unique arrangements of BANANA?", expected: 60, hint: "6! / (3! 2!).", proof: "6!/(3!2!) = 60" },
];

export default function ArrangementsLab({
  kindRaw,
  setKind,
  pulse,
}: {
  kindRaw: string | null;
  setKind: (id: string) => void;
  pulse: string;
}) {
  const kind = parseArrKind(kindRaw);
  const [collapsed, setCollapsed] = useStudioState("ArrangementsLab:ArrangementsLab:collapsed", false);
  const [n, setN] = useStudioState("ArrangementsLab:ArrangementsLab:n", 4);
  const [r, setR] = useStudioState("ArrangementsLab:ArrangementsLab:r", 3);
  const [word, setWord] = useStudioState("ArrangementsLab:ArrangementsLab:word", "BANANA");
  const [playing, setPlaying] = useStudioState("ArrangementsLab:ArrangementsLab:playing", false);
  const [highlight, setHighlight] = useStudioState("ArrangementsLab:ArrangementsLab:highlight", 0);
  const [ch, setCh] = useStudioState("ArrangementsLab:ArrangementsLab:ch", 0);
  const items = letters(kind === "repetition" ? Math.min(n, 4) : n);
  const [order, setOrder] = useStudioState<string[]>("ArrangementsLab:ArrangementsLab:order", () => [...items]);
  const [slots, setSlots] = useStudioState<(string | null)[]>("ArrangementsLab:ArrangementsLab:slots", () => items.map(() => null));
  const [drag, setDrag] = useState<string | null>(null);
  const [rotation, setRotation] = useStudioState("ArrangementsLab:ArrangementsLab:rotation", 0);
  const [lockA, setLockA] = useStudioState("ArrangementsLab:ArrangementsLab:lockA", true);
  const [listMode, setListMode] = useStudioState<"grid" | "sequence" | "tree">("ArrangementsLab:ArrangementsLab:listMode", "grid");
  const [repeatOn, setRepeatOn] = useStudioState("ArrangementsLab:ArrangementsLab:repeatOn", true);

  useEffect(() => {
    if (kind === "all") {
      setN(4); setOrder(["A", "B", "C", "D"]); setSlots([null, null, null, null]);
    }
    if (kind === "npr") { setN(6); setR(3); setSlots([null, null, null]); }
    if (kind === "repetition") { setN(3); setR(4); setSlots([null, null, null, null]); }
    if (kind === "circular") { setN(5); setRotation(0); }
    if (kind === "repeated") setWord("BANANA");
  }, [kind]);

  useEffect(() => {
    if (!playing) return;
    const id = window.setInterval(() => {
      setOrder((current) => {
        const next = [...current];
        if (!nextPermutation(next)) next.sort();
        setSlots(next.slice(0, slotCount));
        return next;
      });
      setHighlight((h) => h + 1);
    }, 650);
    return () => window.clearInterval(id);
  }, [playing]);

  const pool = kind === "repeated" ? word.split("") : items;
  const slotCount = kind === "npr" || kind === "repetition" ? r : kind === "all" ? n : n;
  const placed = slots.filter(Boolean) as string[];
  const remainingChoices = kind === "repetition" && repeatOn
    ? Array.from({ length: slotCount }, () => n)
    : Array.from({ length: slotCount }, (_, i) => Math.max(0, (kind === "npr" ? n : n) - i));
  const totalAll = factorial(n);
  const totalNpr = permutation(n, r);
  const totalRep = power(n, r);
  const totalCirc = factorial(Math.max(0, n - 1));
  const totalWord = uniqueArrangementCount(word);
  const listed = useMemo(() => {
    if (kind === "repetition") return generatePermutationsWithRep(letters(n), r, ENUM_DISPLAY_CAP);
    if (n > ENUM_PERM_LIMIT) return [];
    return kind === "npr" ? generatePermutations(items, r, ENUM_DISPLAY_CAP) : generatePermutations(items, n, ENUM_DISPLAY_CAP);
  }, [kind, items, n, r]);
  const listedTotal = kind === "repetition" ? totalRep : kind === "npr" ? totalNpr : totalAll;
  const challenge = CHALLENGES[ch % CHALLENGES.length]!;

  const dropAt = (index: number) => {
    if (!drag) return;
    setSlots((current) => {
      const next = [...current];
      const used = next.indexOf(drag);
      if (used >= 0 && !(kind === "repetition" && repeatOn)) next[used] = null;
      next[index] = drag;
      return next;
    });
  };

  const shuffle = () => {
    const copy = [...pool];
    for (let i = copy.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      [copy[i], copy[j]] = [copy[j]!, copy[i]!];
    }
    setOrder(copy);
    setSlots(copy.slice(0, slotCount));
  };

  const people = letters(n);
  const rotated = people.map((_, i) => people[(i + rotation) % n]!);

  const applyPerm = (perm: string[]) => {
    setOrder(perm);
    setSlots(perm.slice(0, slotCount));
    setHighlight((h) => h + 1);
  };

  return (
    <ComboWorkspace
      theme="arr"
      collapsed={collapsed}
      onToggle={() => setCollapsed((v) => !v)}
      controls={
        <>
          <h2>Arrangement setup</h2>
          <Seg
            label="Arrangement type"
            value={kind}
            onChange={(id) => setKind(id)}
            options={[
              { id: "all", label: "Arrange all" },
              { id: "npr", label: "P(n,r)" },
              { id: "repetition", label: "Repetition" },
              { id: "circular", label: "Circular" },
              { id: "repeated", label: "Repeated objects" },
            ]}
          />
          {kind !== "repeated" ? <Slider label="Objects n" value={n} min={kind === "repetition" ? 2 : 3} max={kind === "repetition" ? 4 : 7} onChange={(v) => { setN(v); setSlots(Array.from({ length: kind === "npr" || kind === "repetition" ? r : v }, () => null)); setOrder(letters(v)); }} /> : null}
          {kind === "npr" || kind === "repetition" ? <Slider label="Positions r" value={r} min={1} max={kind === "repetition" ? 5 : n} onChange={(v) => { setR(v); setSlots(Array.from({ length: v }, () => null)); }} /> : null}
          {kind === "repetition" ? (
            <label className="combo-note"><input type="checkbox" checked={repeatOn} onChange={(e) => setRepeatOn(e.target.checked)} /> Repetition ON</label>
          ) : null}
          {kind === "repeated" ? (
            <div className="combo-btn-row">
              {["BANANA", "BOOK", "MISS"].map((w) => (
                <button key={w} type="button" className={`combo-ghost${word === w ? " is-on" : ""}`} onClick={() => setWord(w)}>{w}</button>
              ))}
            </div>
          ) : null}
          <div className="combo-btn-row">
            <button type="button" className="combo-ghost" onClick={shuffle}>Shuffle</button>
            <button type="button" className="combo-ghost" onClick={() => { const next = [...order]; if (!nextPermutation(next)) next.sort(); applyPerm(next); }}>Next</button>
            <button type="button" className="combo-ghost" onClick={() => { const next = [...order]; if (!prevPermutation(next)) next.sort().reverse(); applyPerm(next); }}>Previous</button>
            <button type="button" className="combo-primary" onClick={() => setPlaying((p) => !p)}>{playing ? "Pause" : "Animate"}</button>
            <button type="button" className="combo-ghost" onClick={() => { setPlaying(false); setSlots(Array.from({ length: slotCount }, () => null)); setOrder(letters(n)); setDrag(null); }}>Reset</button>
          </div>
          <p className="combo-note">Click a token, then click a numbered slot — or drag. Order creates a new outcome.</p>
        </>
      }
      viz={
        <>
          <h2 className={pulse === "observe" ? "combo-focus" : undefined}>Arrangement stage</h2>
          {kind !== "circular" ? (
            <>
              <p className="combo-note">Object pool</p>
              <div className="combo-tokens" aria-label="Object pool">
                {(kind === "repeated" ? word.split("") : items).map((label, i) => {
                  const used = !(kind === "repetition" && repeatOn) && slots.includes(label);
                  return (
                    <Token
                      key={`${label}-${i}`}
                      label={label}
                      color={tokenColor(label, i)}
                      draggable
                      muted={used}
                      selected={drag === label}
                      onDragStart={() => setDrag(label)}
                      onClick={() => setDrag(label)}
                    />
                  );
                })}
              </div>
              {kind !== "repeated" ? (
                <div className={`combo-stage${pulse === "understand" ? " combo-focus" : ""}`} aria-label="Ordered slots">
                  {Array.from({ length: slotCount }, (_, i) => (
                    <Slot
                      key={i}
                      index={i}
                      value={slots[i] ?? null}
                      choices={remainingChoices[i]}
                      color={tokenColor(slots[i] ?? "A", i)}
                      onDrop={() => dropAt(i)}
                    />
                  ))}
                </div>
              ) : (
                <div className="combo-stage">
                  {word.split("").map((label, i) => <Token key={`${label}${i}`} label={label} color={tokenColor(label)} muted={label === "A" && i > 0} />)}
                </div>
              )}
              {kind === "repeated" ? <p className="combo-note">Identical letters share a color family. Swapping two A’s leaves the word unchanged, so we divide by 3! × 2! for BANANA.</p> : null}
              {kind !== "repeated" && kind !== "circular" ? (
                <div>
                  <p className="combo-note">Why the product works</p>
                  <ProductPath factors={remainingChoices} total={kind === "repetition" && repeatOn ? totalRep : kind === "npr" ? totalNpr : totalAll} />
                </div>
              ) : null}
              {kind !== "circular" && kind !== "repeated" ? (
                <>
                  <Seg value={listMode} onChange={(id) => setListMode(id as typeof listMode)} options={[{ id: "grid", label: "Grid" }, { id: "sequence", label: "Sequence" }, { id: "tree", label: "Tree" }]} />
                  {n > ENUM_PERM_LIMIT ? <p className="combo-note">{listedTotal} total — showing first {ENUM_DISPLAY_CAP} would overflow; count only.</p> : listMode === "tree" ? (
                    <div className="combo-tree-list" aria-label="Arrangement tree">
                      {listed.map((row, i) => (
                        <div key={row.join("") + i} className={i === highlight % listed.length ? "combo-focus" : undefined}>
                          {row.map((ch, d) => <span key={d}>{"· ".repeat(d)}<b>{ch}</b></span>)}
                          {" → "}{row.join("")}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className={`combo-list${listMode === "sequence" ? " is-seq" : ""}`} aria-label="Enumerated arrangements">
                      {listed.map((row, i) => <span key={row.join("") + i} className={i === highlight % listed.length ? "is-on" : ""}>{row.join("")}</span>)}
                    </div>
                  )}
                  {listedTotal > listed.length ? <p className="combo-note">{listedTotal} total — showing first {listed.length}.</p> : null}
                </>
              ) : null}
            </>
          ) : (
            <>
              <CircularTable people={rotated} lockA={lockA} rotation={rotation} />
              <p className="combo-note">These linear strings are the same circular seating — rotate until A is first.</p>
              <div className="combo-rotations">
                {people.map((_, i) => {
                  const rot = people.map((__, j) => people[(j + i) % n]!).join("");
                  return <span key={rot} className={i === rotation ? "is-on" : ""}>{rot}</span>;
                })}
              </div>
              <div className="combo-btn-row">
                <button type="button" className="combo-ghost" onClick={() => setRotation((v) => (v + 1) % n)}>Rotate table</button>
                <label className="combo-note"><input type="checkbox" checked={lockA} onChange={(e) => setLockA(e.target.checked)} /> Lock A at top</label>
              </div>
            </>
          )}
        </>
      }
      insights={
        <>
          <h2>Live values</h2>
          {kind === "all" ? <LiveRow color="#147df2" label="n!" value={totalAll} /> : null}
          {kind === "npr" ? <><LiveRow color="#147df2" label="n" value={n} /><LiveRow color="#8b45f4" label="r" value={r} /><LiveRow color="#10b981" label="P(n,r)" value={totalNpr} /></> : null}
          {kind === "repetition" ? <LiveRow color="#08b9dd" label={repeatOn ? "n^r" : "P(n,r)"} value={repeatOn ? totalRep : permutation(n, r)} /> : null}
          {kind === "circular" ? <LiveRow color="#f59e0b" label="(n−1)!" value={totalCirc} /> : null}
          {kind === "repeated" ? <LiveRow color="#8b45f4" label="unique" value={totalWord} /> : null}
          <LiveRow color="#64748b" label="Current arrangement" value={(kind === "circular" ? rotated : kind === "repeated" ? word.split("") : (placed.length ? placed : order)).join("")} />
          <LiveRow color="#0ea5e9" label="Index" value={String((highlight % Math.max(1, listedTotal)) + 1)} />
          {kind === "all" ? <FormulaCard title="Formula" formula="n! = n × (n−1) × ⋯ × 1" note="Each filled slot removes one remaining choice." /> : null}
          {kind === "npr" ? <FormulaCard title="Formula" formula="P(n,r) = n! / (n−r)!" note={`${n} × ${n - 1} × … for ${r} slots.`} /> : null}
          {kind === "repetition" ? <FormulaCard title="Formula" formula={repeatOn ? "n^r" : "P(n,r) = n!/(n−r)!"} note={repeatOn ? "Each slot independently chooses among n symbols." : "Without repetition, later slots have fewer choices."} /> : null}
          {kind === "circular" ? <FormulaCard title="Formula" formula="(n − 1)!" note="Rotations of the same seating are equivalent. Fix A at the top, then arrange the rest." /> : null}
          {kind === "repeated" ? <FormulaCard title="Formula" formula="n! / (n₁! n₂! ⋯)" note={`${word}: ${word.length}! / (${Object.entries(word.split("").reduce<Record<string, number>>((a, ch) => { a[ch] = (a[ch] ?? 0) + 1; return a; }, {})).map(([k, v]) => `${v} ${k}`).join(", ")}) = ${totalWord}. Swapping identical letters does not create a new word.`} /> : null}
          <ChallengeCard {...challenge} onNew={() => setCh((c) => c + 1)} />
        </>
      }
    />
  );
}

function CircularTable({
  people,
  lockA,
  rotation,
}: {
  people: string[];
  lockA: boolean;
  rotation: number;
}) {
  const n = people.length;
  const shown = lockA ? ["A", ...people.filter((p) => p !== "A")] : people;
  return (
    <svg className="combo-circle" viewBox="0 0 420 340" role="img" aria-label="Circular table">
      <circle cx="210" cy="160" r="104" fill="#fff" stroke="#dce7f4" strokeWidth="22" />
      <circle cx="210" cy="160" r="58" fill="#f8fbff" stroke="#e2e8f0" />
      {shown.map((p, i) => {
        const a = -Math.PI / 2 + (i / n) * Math.PI * 2;
        const x = 210 + Math.cos(a) * 104;
        const y = 160 + Math.sin(a) * 104;
        return (
          <g key={`${p}${i}`}>
            <circle cx={x} cy={y} r="20" fill={tokenColor(p, i)} />
            <text x={x} y={y + 5} textAnchor="middle" fill="#fff" fontSize="13" fontWeight="800">{p}</text>
          </g>
        );
      })}
      <text x="210" y="156" textAnchor="middle" fontSize="12" fill="#64748b">{lockA ? "A fixed" : "free rotate"}</text>
      <text x="210" y="176" textAnchor="middle" fontSize="12" fill="#40516d">step {rotation}</text>
      <text x="210" y="318" textAnchor="middle" fontSize="13" fill="#40516d">Linear {n}! = {n === 5 ? 120 : ""} · circular ({n}−1)! = {n === 5 ? 24 : ""}</text>
    </svg>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useState } from "react";
import {
  combination,
  countLeaves,
  countNodes,
  generateBinaryTree,
  generateCombinationTree,
  generateDiceTree,
  generatePathTree,
  generatePermutationTree,
  layoutTree,
  letters,
  permutation,
  power,
  treeDepth,
  type TreeNode,
} from "./combinatoricsMath";
import { parseTreeKind } from "./combinatoricsMode";
import { ChallengeCard, ComboWorkspace, FormulaCard, LiveRow, Seg, Slider } from "./combinatoricsUi";

const CHALLENGES = [
  { prompt: "How many binary strings of length 5?", expected: 32, hint: "2⁵.", proof: "2^5=32" },
  { prompt: "Leaves in the permutation tree of ABC?", expected: 6, hint: "3×2×1.", proof: "3!=6" },
  { prompt: "Choose 2 from A B C D. How many leaves?", expected: 6, hint: "C(4,2).", proof: "C(4,2)=6" },
];

export default function GeneratingTreeLab({
  kindRaw,
  setKind,
  pulse,
}: {
  kindRaw: string | null;
  setKind: (id: string) => void;
  pulse: string;
}) {
  const kind = parseTreeKind(kindRaw);
  const [collapsed, setCollapsed] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:collapsed", false);
  const [depth, setDepth] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:depth", 3);
  const [visible, setVisible] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:visible", 1);
  const [playing, setPlaying] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:playing", false);
  const [hover, setHover] = useState("");
  const [hideInvalid, setHideInvalid] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:hideInvalid", true);
  const [pan, setPan] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:pan", { x: 0, y: 0 });
  const [zoom, setZoom] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:zoom", 1);
  const [n, setN] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:n", 3);
  const [r, setR] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:r", 2);
  const [ch, setCh] = useStudioState("GeneratingTreeLab:GeneratingTreeLab:ch", 0);

  useEffect(() => {
    if (kind === "binary" || kind === "restricted") { setDepth(3); setVisible(1); }
    if (kind === "permutation") { setN(3); setVisible(1); }
    if (kind === "selection") { setN(4); setR(2); setVisible(1); }
    if (kind === "dice") { setN(2); setDepth(2); }
    if (kind === "paths") { setN(2); setR(2); }
    setPlaying(false);
    setVisible(1);
  }, [kind]);

  useEffect(() => {
    if (!playing) return;
    const id = window.setInterval(() => {
      setVisible((v) => {
        if (v >= 8) { setPlaying(false); return v; }
        return v + 1;
      });
    }, 500);
    return () => window.clearInterval(id);
  }, [playing]);

  const root = useMemo(() => {
    if (kind === "binary") return generateBinaryTree(depth, false);
    if (kind === "restricted") return generateBinaryTree(depth, true);
    if (kind === "permutation") return generatePermutationTree(letters(n));
    if (kind === "selection") return generateCombinationTree(letters(n), r);
    if (kind === "dice") return generateDiceTree(Math.min(n, 3), 6);
    return generatePathTree(n, r);
  }, [kind, depth, n, r]);

  const maxD = treeDepth(root);
  const leaves = countLeaves(root, true);
  const nodes = countNodes(root);
  const challenge = CHALLENGES[ch % CHALLENGES.length]!;
  const branching = kind === "binary" || kind === "restricted" ? 2 : kind === "dice" ? 6 : kind === "permutation" ? n : kind === "selection" ? "include path" : "R/D";

  const clip = (node: TreeNode, d: number): TreeNode => ({
    ...node,
    children: d >= visible ? [] : node.children.filter((c) => !(hideInvalid && c.blocked)).map((child) => clip(child, d + 1)),
  });
  const clipped = clip(root, 0);
  const drawn = layoutTree(clipped, 640, 420);

  return (
    <ComboWorkspace
      theme="tree"
      collapsed={collapsed}
      onToggle={() => setCollapsed((v) => !v)}
      controls={
        <>
          <h2>Tree scenario</h2>
          <Seg
            value={kind}
            onChange={setKind}
            options={[
              { id: "binary", label: "Binary strings" },
              { id: "permutation", label: "Permutations" },
              { id: "selection", label: "Selections" },
              { id: "restricted", label: "Restricted" },
              { id: "dice", label: "Dice" },
              { id: "paths", label: "Paths" },
            ]}
          />
          {kind === "binary" || kind === "restricted" ? <Slider label="Length" value={depth} min={2} max={4} onChange={setDepth} /> : null}
          {kind === "permutation" ? <Slider label="Items n" value={n} min={2} max={4} onChange={setN} /> : null}
          {kind === "selection" ? <><Slider label="n" value={n} min={3} max={5} onChange={setN} /><Slider label="Choose r" value={r} min={1} max={n} onChange={setR} /></> : null}
          {kind === "dice" ? <Slider label="Dice" value={n} min={1} max={3} onChange={setN} /> : null}
          {kind === "paths" ? <><Slider label="Down" value={n} min={1} max={3} onChange={setN} /><Slider label="Right" value={r} min={1} max={3} onChange={setR} /></> : null}
          <div className="combo-btn-row">
            <button type="button" className="combo-ghost" onClick={() => setVisible(0)}>Reset</button>
            <button type="button" className="combo-ghost" onClick={() => setVisible((v) => Math.min(8, v + 1))}>Step level</button>
            <button type="button" className="combo-primary" onClick={() => setPlaying((p) => !p)}>{playing ? "Pause" : "Play"}</button>
            <button type="button" className="combo-ghost" onClick={() => setVisible(8)}>Expand all</button>
            <button type="button" className="combo-ghost" onClick={() => setVisible(0)}>Collapse all</button>
            <button type="button" className="combo-ghost" onClick={() => { setPan({ x: 0, y: 0 }); setZoom(1); }}>Fit tree</button>
          </div>
          <label className="combo-note"><input type="checkbox" checked={hideInvalid} onChange={(e) => setHideInvalid(e.target.checked)} /> Hide invalid branches</label>
          <p className="combo-note">Hover a node to highlight its path. Restricted mode blocks consecutive 1s.</p>
        </>
      }
      viz={
        <>
          <h2 className={pulse === "observe" ? "combo-focus" : undefined}>Generating tree</h2>
          <svg
            className="combo-tree"
            viewBox="0 0 640 420"
            role="img"
            aria-label="Generating tree"
            onPointerDown={(e) => {
              const origin = { x: e.clientX - pan.x, y: e.clientY - pan.y };
              const move = (ev: PointerEvent) => setPan({ x: ev.clientX - origin.x, y: ev.clientY - origin.y });
              const up = () => { window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up); };
              window.addEventListener("pointermove", move);
              window.addEventListener("pointerup", up);
            }}
          >
            <rect width="640" height="420" fill="#f7fbff" />
            <g transform={`translate(${pan.x} ${pan.y}) scale(${zoom})`}>
              {drawn.map((node) =>
                node.children.map((child) => {
                  const to = drawn.find((d) => d.id === child.id);
                  if (!to) return null;
                  return <line key={`${node.id}-${child.id}`} x1={node.x} y1={node.y} x2={to.x} y2={to.y} stroke={child.blocked ? "#fca5a5" : hover && (hover.startsWith(child.path) || child.path.startsWith(hover)) ? "#147df2" : "#94a3b8"} strokeWidth="1.6" />;
                }),
              )}
              {drawn.map((node) => (
                <g key={node.id} onMouseEnter={() => setHover(node.path)} onMouseLeave={() => setHover("")}>
                  <circle cx={node.x} cy={node.y} r="14" fill={node.blocked ? "#fecaca" : hover && (hover === node.path || hover.startsWith(node.path) && node.path) ? "#147df2" : node.valid && !node.children.length ? "#10b981" : "#8b45f4"} />
                  <text x={node.x} y={node.y + 4} textAnchor="middle" fill="#fff" fontSize="9" fontWeight="800">{node.label}</text>
                </g>
              ))}
            </g>
          </svg>
          <div className="combo-btn-row">
            <button type="button" className="combo-ghost" onClick={() => setZoom((z) => Math.min(2, z + 0.15))}>Zoom +</button>
            <button type="button" className="combo-ghost" onClick={() => setZoom((z) => Math.max(0.6, z - 0.15))}>Zoom −</button>
          </div>
        </>
      }
      insights={
        <>
          <h2>Tree census</h2>
          <LiveRow color="#147df2" label="Branching" value={String(branching)} />
          <LiveRow color="#8b45f4" label="Depth" value={maxD} />
          <LiveRow color="#08b9dd" label="Nodes" value={nodes} />
          <LiveRow color="#10b981" label="Valid leaves" value={leaves} />
          <LiveRow color="#f59e0b" label="Visible levels" value={visible} />
          {kind === "binary" ? <FormulaCard title="Independent choices" formula="2ⁿ leaves" note={`${power(2, depth)} binary strings of length ${depth}.`} /> : null}
          {kind === "permutation" ? <FormulaCard title="Permutation tree" formula="n × (n−1) × ⋯ × 1" note={`P(${n},${n}) = ${permutation(n, n)}.`} /> : null}
          {kind === "selection" ? <FormulaCard title="Increasing choices" formula="C(n,r)" note={`No order duplicates. C(${n},${r}) = ${combination(n, r)}.`} /> : null}
          {kind === "restricted" ? <FormulaCard title="Blocked branches" formula="count only valid leaves" note="Consecutive 1s are muted red and excluded from the leaf count." /> : null}
          {kind === "dice" ? <FormulaCard title="Dice" formula="6ⁿ" note={`${power(6, n)} outcomes.`} /> : null}
          {kind === "paths" ? <FormulaCard title="Grid paths" formula="C(rows+cols, rows)" note={`${combination(n + r, n)} paths using only Right and Down.`} /> : null}
          <ChallengeCard {...challenge} onNew={() => setCh((c) => c + 1)} />
        </>
      }
    />
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useState } from "react";
import { regionTotals, surveyToRegions, threeSetUnion, twoSetUnion } from "./combinatoricsMath";
import { parseIeKind } from "./combinatoricsMode";
import { ChallengeCard, ComboWorkspace, FormulaCard, LiveRow, Seg, Slider } from "./combinatoricsUi";

const CHALLENGES = [
  { prompt: "A=30, B=25, overlap=8. Find |A ∪ B|.", expected: 47, hint: "30+25−8.", proof: "30+25−8=47" },
  { prompt: "A=20, B=15, A∩B=5. Union?", expected: 30, hint: "Add then subtract the overlap.", proof: "20+15−5=30" },
  { prompt: "Survey: 40+35+30−15−12−10+5. At least one subject?", expected: 73, hint: "Inclusion–exclusion with three sets.", proof: "73" },
];

const SURVEY = { math: 40, physics: 35, cs: 30, mp: 15, mc: 12, pc: 10, all: 5 };

export default function InclusionExclusionLab({
  kindRaw,
  setKind,
  pulse,
}: {
  kindRaw: string | null;
  setKind: (id: string) => void;
  pulse: string;
}) {
  const kind = parseIeKind(kindRaw);
  const [collapsed, setCollapsed] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:collapsed", false);
  const [a, setA] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:a", 20);
  const [b, setB] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:b", 15);
  const [c, setC] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:c", 18);
  const [ab, setAb] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:ab", 5);
  const [ac, setAc] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:ac", 4);
  const [bc, setBc] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:bc", 3);
  const [abc, setAbc] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:abc", 2);
  const [universe, setU] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:universe", 50);
  const [regions, setRegions] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:regions", { a: 12, b: 8, c: 6, ab: 4, ac: 3, bc: 2, abc: 2 });
  const [step, setStep] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:step", 0);
  const [showCounts, setShowCounts] = useState(true);
  const [ch, setCh] = useStudioState("InclusionExclusionLab:InclusionExclusionLab:ch", 0);

  useEffect(() => {
    if (kind === "two") { setA(20); setB(15); setAb(5); setU(50); setStep(0); }
    if (kind === "three") { setA(20); setB(15); setC(18); setAb(6); setAc(5); setBc(4); setAbc(2); }
    if (kind === "survey") {
      const r = surveyToRegions(SURVEY);
      setRegions(r);
      setA(SURVEY.math); setB(SURVEY.physics); setC(SURVEY.cs); setAb(SURVEY.mp); setAc(SURVEY.mc); setBc(SURVEY.pc); setAbc(SURVEY.all);
    }
    if (kind === "regions") setRegions({ a: 12, b: 8, c: 6, ab: 4, ac: 3, bc: 2, abc: 2 });
    if (kind === "complement") { setA(20); setB(15); setAb(5); setU(50); }
  }, [kind]);

  const twoUnion = twoSetUnion(a, b, ab);
  const threeUnion = threeSetUnion(a, b, c, ab, ac, bc, abc);
  const totals = regionTotals(regions);
  const none = Math.max(0, universe - (kind === "three" || kind === "survey" ? threeUnion : twoUnion));
  const challenge = CHALLENGES[ch % CHALLENGES.length]!;

  const union = kind === "regions" || kind === "survey" ? totals.union : kind === "two" || kind === "complement" ? twoUnion : threeUnion;

  return (
    <ComboWorkspace
      theme="ie"
      collapsed={collapsed}
      onToggle={() => setCollapsed((v) => !v)}
      controls={
        <>
          <h2>Set counting</h2>
          <Seg
            value={kind}
            onChange={setKind}
            options={[
              { id: "two", label: "Two sets" },
              { id: "three", label: "Three sets" },
              { id: "survey", label: "Survey" },
              { id: "complement", label: "Complement" },
              { id: "regions", label: "Region-first" },
            ]}
          />
          {kind === "regions" ? (
            <>
              {(["a", "b", "c", "ab", "ac", "bc", "abc"] as const).map((key) => (
                <Slider key={key} label={key.toUpperCase()} value={regions[key]} min={0} max={20} onChange={(v) => setRegions((cur) => ({ ...cur, [key]: v }))} />
              ))}
            </>
          ) : kind === "survey" ? (
            <p className="combo-note">40 Math · 35 Physics · 30 CS · 15 M∩P · 12 M∩CS · 10 P∩CS · 5 all three.</p>
          ) : (
            <>
              <Slider label="|A|" value={a} min={0} max={40} onChange={setA} />
              <Slider label="|B|" value={b} min={0} max={40} onChange={setB} />
              {kind === "three" ? <Slider label="|C|" value={c} min={0} max={40} onChange={setC} /> : null}
              <Slider label="|A ∩ B|" value={ab} min={0} max={Math.min(a, b)} onChange={setAb} />
              {kind === "three" ? (
                <>
                  <Slider label="|A ∩ C|" value={ac} min={0} max={Math.min(a, c)} onChange={setAc} />
                  <Slider label="|B ∩ C|" value={bc} min={0} max={Math.min(b, c)} onChange={setBc} />
                  <Slider label="|A ∩ B ∩ C|" value={abc} min={0} max={Math.min(ab, ac, bc)} onChange={setAbc} />
                </>
              ) : null}
              {kind === "complement" || kind === "two" ? <Slider label="Universe" value={universe} min={union} max={80} onChange={setU} /> : null}
            </>
          )}
          <label className="combo-note"><input type="checkbox" checked={showCounts} onChange={(e) => setShowCounts(e.target.checked)} /> Show region counts</label>
          <div className="combo-btn-row">
            <button type="button" className="combo-ghost" onClick={() => setStep(0)}>Reset shade</button>
            <button type="button" className="combo-primary" onClick={() => setStep((s) => (s + 1) % 5)}>Animate step</button>
          </div>
        </>
      }
      viz={
        <>
          <h2 className={pulse === "observe" ? "combo-focus" : undefined}>Venn diagram</h2>
          <Venn
            two={kind === "two" || kind === "complement"}
            step={step}
            showCounts={showCounts}
            labels={kind === "survey" ? ["Math", "Physics", "CS"] : ["A", "B", "C"]}
            counts={kind === "regions" || kind === "survey" ? regions : {
              a: Math.max(0, a - ab - (kind === "three" ? ac - abc : 0)),
              b: Math.max(0, b - ab - (kind === "three" ? bc - abc : 0)),
              c: kind === "three" ? Math.max(0, c - ac - bc + abc) : 0,
              ab: Math.max(0, ab - (kind === "three" ? abc : 0)),
              ac: kind === "three" ? Math.max(0, ac - abc) : 0,
              bc: kind === "three" ? Math.max(0, bc - abc) : 0,
              abc: kind === "three" ? abc : 0,
            }}
            highlightNone={kind === "complement"}
          />
          <ol className="combo-note">
            {kind === "two" || kind === "complement" ? (
              <>
                <li>Shade A ({a})</li>
                <li>Shade B ({b}) — overlap counted twice</li>
                <li>Subtract |A ∩ B| = {ab}</li>
                <li>|A ∪ B| = {a} + {b} − {ab} = {twoUnion}</li>
              </>
            ) : (
              <>
                <li>Add |A|+|B|+|C| = {a + b + c}</li>
                <li>Subtract pairwise overlaps {ab}+{ac}+{bc}</li>
                <li>Add triple {abc} back</li>
                <li>Union = {threeUnion}</li>
              </>
            )}
          </ol>
        </>
      }
      insights={
        <>
          <h2>Live values</h2>
          <LiveRow color="#147df2" label="|A|" value={kind === "regions" || kind === "survey" ? totals.A : a} />
          <LiveRow color="#8b45f4" label="|B|" value={kind === "regions" || kind === "survey" ? totals.B : b} />
          {kind !== "two" && kind !== "complement" ? <LiveRow color="#10b981" label="|C|" value={kind === "regions" || kind === "survey" ? totals.C : c} /> : null}
          <LiveRow color="#f59e0b" label="Union" value={union} />
          {kind === "complement" ? <LiveRow color="#64748b" label="None" value={none} /> : null}
          {kind === "two" || kind === "complement" ? <FormulaCard title="Two sets" formula="|A ∪ B| = |A| + |B| − |A ∩ B|" note="Intersection is counted twice before subtraction." /> : null}
          {kind === "three" || kind === "survey" ? <FormulaCard title="Three sets" formula="|A∪B∪C| = |A|+|B|+|C| − |A∩B|−|A∩C|−|B∩C| + |A∩B∩C|" /> : null}
          {kind === "complement" ? <FormulaCard title="Complement" formula="desired = total − none" note={`${universe} − ${none} people in at least one set = ${universe - none}.`} /> : null}
          {kind === "regions" ? <FormulaCard title="Region-first" formula="Set totals are sums of disjoint regions" note="Impossible overlaps cannot occur because you edit atoms directly." /> : null}
          <ChallengeCard {...challenge} onNew={() => setCh((c) => c + 1)} />
        </>
      }
    />
  );
}

function Venn({
  two,
  step,
  showCounts,
  labels,
  counts,
  highlightNone,
}: {
  two: boolean;
  step: number;
  showCounts: boolean;
  labels: string[];
  counts: { a: number; b: number; c: number; ab: number; ac: number; bc: number; abc: number };
  highlightNone: boolean;
}) {
  const aFill = step >= 1 ? "rgba(20,125,242,.28)" : "rgba(20,125,242,.12)";
  const bFill = step >= 2 ? "rgba(139,69,244,.28)" : "rgba(139,69,244,.12)";
  const cFill = step >= 1 && !two ? "rgba(16,185,129,.22)" : "rgba(16,185,129,.1)";
  return (
    <svg className="combo-venn" viewBox="0 0 420 320" role="img" aria-label="Venn diagram">
      <rect width="420" height="320" fill={highlightNone ? "#eef6ff" : "#f7fbff"} />
      <rect x="18" y="18" width="384" height="284" rx="16" fill={highlightNone && step >= 3 ? "#dbeafe" : "#fff"} stroke="#dce7f4" />
      <circle cx={two ? 168 : 150} cy="150" r="88" fill={aFill} stroke="#147df2" strokeWidth="2" />
      <circle cx={two ? 252 : 250} cy="150" r="88" fill={bFill} stroke="#8b45f4" strokeWidth="2" />
      {!two ? <circle cx="200" cy="220" r="88" fill={cFill} stroke="#10b981" strokeWidth="2" /> : null}
      {step >= 3 ? <circle cx={two ? 210 : 200} cy={two ? 150 : 175} r="28" fill="rgba(245,158,11,.45)" /> : null}
      <text x="110" y="80" fill="#147df2" fontWeight="800">{labels[0]}</text>
      <text x="290" y="80" fill="#8b45f4" fontWeight="800">{labels[1]}</text>
      {!two ? <text x="188" y="300" fill="#10b981" fontWeight="800">{labels[2]}</text> : null}
      {showCounts ? (
        <>
          <text x={two ? 118 : 108} y="148" fontSize="13" fontWeight="800" fill="#147df2">{showCounts ? counts.a : ""}</text>
          <text x={two ? 292 : 298} y="148" fontSize="13" fontWeight="800" fill="#8b45f4">{showCounts ? counts.b : ""}</text>
          {two ? <text x="198" y="154" fontSize="13" fontWeight="800" fill="#b45309">{showCounts ? counts.ab : ""}</text> : (
            <>
              <text x="198" y="258" fontSize="13" fontWeight="800" fill="#047857">{showCounts ? counts.c : ""}</text>
              <text x="198" y="138" fontSize="12" fontWeight="800">{showCounts ? counts.ab : ""}</text>
              <text x="142" y="204" fontSize="12" fontWeight="800">{showCounts ? counts.ac : ""}</text>
              <text x="252" y="204" fontSize="12" fontWeight="800">{showCounts ? counts.bc : ""}</text>
              <text x="194" y="186" fontSize="12" fontWeight="800" fill="#b45309">{showCounts ? counts.abc : ""}</text>
            </>
          )}
        </>
      ) : null}
    </svg>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useState, useRef } from "react";
import {registerPageCapability} from '../../../math-robo/intelligence/pageCapabilities';
import { ceilDivision, evenOccupancy, occupancyMax, randomOccupancy, worstOccupancy } from "./combinatoricsMath";
import { parsePigKind } from "./combinatoricsMode";
import { ChallengeCard, ComboWorkspace, FormulaCard, LiveRow, Seg, Slider, tokenColor } from "./combinatoricsUi";

const PRESETS = [
  { id: "months", label: "Birth months", n: 13, m: 12, note: "13 people, 12 months → at least two share a month." },
  { id: "socks", label: "Sock colors", n: 11, m: 5, note: "11 socks, 5 colors. Guaranteed occupancy ceil(11/5)=3." },
  { id: "birthdays", label: "Birthdays", n: 366, m: 365, note: "366 people, 365 dates → at least two share a birthday." },
  { id: "remainders", label: "Remainders", n: 7, m: 3, note: "7 integers into 3 residue classes. ceil(7/3)=3." },
];

const CHALLENGES = [
  { prompt: "17 objects in 5 boxes. What occupancy is guaranteed?", expected: 4, hint: "ceil(17/5).", proof: "ceil(17/5)=4" },
  { prompt: "How many students guarantee at least 3 share a birth month?", expected: 25, hint: "Worst case 2×12=24, then +1.", proof: "12×2+1=25" },
  { prompt: "13 objects, 4 boxes. Guaranteed max occupancy?", expected: 4, hint: "ceil(13/4).", proof: "Even split 4,3,3,3." },
];

export default function PigeonholeLab({
  kindRaw,
  setKind,
  pulse,
}: {
  kindRaw: string | null;
  setKind: (id: string) => void;
  pulse: string;
}) {
  const kind = parsePigKind(kindRaw);
  const [collapsed, setCollapsed] = useStudioState("PigeonholeLab:PigeonholeLab:collapsed", false);
  const [n, setN] = useStudioState("PigeonholeLab:PigeonholeLab:n", 5);
  const [m, setM] = useStudioState("PigeonholeLab:PigeonholeLab:m", 4);
  const [dist, setDist] = useStudioState<number[]>("PigeonholeLab:PigeonholeLab:dist", [2, 1, 1, 1]);
  const [mode, setMode] = useState("manual");
  const [unplaced, setUnplaced] = useStudioState("PigeonholeLab:PigeonholeLab:unplaced", 0);
  const [drag, setDrag] = useState<"tray" | number | null>(null);
  const [ch, setCh] = useStudioState("PigeonholeLab:PigeonholeLab:ch", 0);
  const [preset, setPreset] = useStudioState("PigeonholeLab:PigeonholeLab:preset", "months");
  const roboState=useRef({n,k:m,distribution:dist});roboState.current={n,k:m,distribution:dist};
  useEffect(()=>registerPageCapability({knowledgeId:'pigeonhole',read:()=>roboState.current,apply:async(objects,boxes)=>{setN(objects);setM(boxes);setDist(evenOccupancy(objects,boxes));setUnplaced(0);setMode('even');await new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())));}}),[setN,setM,setDist,setUnplaced]);

  const applyDist = (next: number[]) => {
    setDist(next);
    setUnplaced(0);
  };

  useEffect(() => {
    if (kind === "basic") { setN(5); setM(4); applyDist(worstOccupancy(5, 4)); }
    if (kind === "generalized") { setN(13); setM(4); applyDist(evenOccupancy(13, 4)); }
    if (kind === "examples") {
      const p = PRESETS[0]!;
      setN(p.n); setM(p.m); applyDist(evenOccupancy(Math.min(p.n, 24), p.m));
    }
    if (kind === "challenge") { setN(17); setM(5); applyDist(evenOccupancy(17, 5)); }
  }, [kind]);

  const guaranteed = ceilDivision(n, m);
  const maxOcc = occupancyMax(dist);
  const displayN = Math.min(n, 36);
  const displayM = Math.min(m, 12);
  const challenge = CHALLENGES[ch % CHALLENGES.length]!;

  const redistribute = (style: string) => {
    setMode(style);
    const boxes = Math.max(1, displayM);
    if (style === "even") applyDist(evenOccupancy(displayN, boxes));
    if (style === "worst") applyDist(worstOccupancy(displayN, boxes));
    if (style === "random") applyDist(randomOccupancy(displayN, boxes));
  };

  const moveTo = (box: number) => {
    if (drag === "tray") {
      if (unplaced <= 0) return;
      setUnplaced((u) => u - 1);
      setDist((current) => {
        const next = [...current];
        next[box] = (next[box] ?? 0) + 1;
        return next;
      });
      setDrag(null);
      return;
    }
    if (drag == null) return;
    setDist((current) => {
      const next = [...current];
      if (next[drag]! > 0) next[drag] -= 1;
      next[box] = (next[box] ?? 0) + 1;
      return next;
    });
    setDrag(null);
  };

  return (
    <ComboWorkspace
      theme="pig"
      collapsed={collapsed}
      onToggle={() => setCollapsed((v) => !v)}
      controls={
        <>
          <h2>Pigeonhole setup</h2>
          <Seg
            value={kind}
            onChange={setKind}
            options={[
              { id: "basic", label: "Basic demo" },
              { id: "generalized", label: "Generalized" },
              { id: "examples", label: "Examples" },
              { id: "challenge", label: "Challenge" },
            ]}
          />
          <Slider label="Objects n" value={n} min={2} max={kind === "examples" ? 366 : 24} onChange={(v) => { setN(v); applyDist(evenOccupancy(Math.min(v, 36), displayM)); }} />
          <Slider label="Containers m" value={m} min={2} max={12} onChange={(v) => { setM(v); applyDist(evenOccupancy(displayN, Math.min(v, 12))); }} />
          <Seg
            label="Distribution"
            value={mode}
            onChange={redistribute}
            options={[
              { id: "random", label: "Random" },
              { id: "even", label: "Even" },
              { id: "manual", label: "Manual" },
              { id: "worst", label: "Worst-case" },
            ]}
          />
          {kind === "examples" ? (
            <div className="combo-btn-row">
              {PRESETS.map((item) => (
                <button key={item.id} type="button" className={`combo-ghost${preset === item.id ? " is-on" : ""}`} onClick={() => { setPreset(item.id); setN(item.n); setM(item.m); applyDist(evenOccupancy(Math.min(item.n, 24), Math.min(item.m, 12))); }}>{item.label}</button>
              ))}
            </div>
          ) : null}
          <button type="button" className="combo-ghost" onClick={() => { setUnplaced(displayN); setDist(Array.from({ length: displayM }, () => 0)); setMode("manual"); }}>Empty boxes</button>
          <p className="combo-note">Click a tray ball, then a box. Overloaded boxes highlight amber.</p>
        </>
      }
      viz={
        <>
          <h2 className={pulse === "observe" ? "combo-focus" : undefined}>Containers</h2>
          <p className="combo-note">Unplaced objects</p>
          <div className="combo-tray" aria-label="Unplaced objects">
            {Array.from({ length: unplaced }, (_, i) => (
              <button
                key={i}
                type="button"
                className="combo-ball"
                style={{ background: "#147df2", outline: drag === "tray" ? "2px solid #071641" : undefined }}
                onClick={() => setDrag("tray")}
                draggable
                onDragStart={() => setDrag("tray")}
              />
            ))}
            {unplaced === 0 ? <span className="combo-note">All objects placed.</span> : null}
          </div>
          <div className="combo-bins" aria-label="Pigeonholes">
            {Array.from({ length: displayM }, (_, i) => {
              const count = dist[i] ?? 0;
              const hot = count >= 2 && kind === "basic";
              const isMax = count === guaranteed && count === maxOcc;
              return (
                <button
                  key={i}
                  type="button"
                  className={`combo-bin${hot ? " is-hot" : ""}${isMax ? " is-max" : ""}`}
                  onClick={() => moveTo(i)}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={() => moveTo(i)}
                >
                  <b>Box {i + 1}</b>
                  <div className="combo-balls">
                    {Array.from({ length: count }, (_, j) => (
                      <span
                        key={j}
                        className="combo-ball"
                        style={{ background: tokenColor("B", i) }}
                        draggable
                        onDragStart={() => setDrag(i)}
                        onClick={(e) => { e.stopPropagation(); setDrag(i); }}
                      />
                    ))}
                  </div>
                  <small>{count}</small>
                </button>
              );
            })}
          </div>
          {n > 36 ? <p className="combo-note">Showing 36 of {n} objects. Counts still use n={n}.</p> : null}
          {kind === "examples" ? <p className="combo-note">{PRESETS.find((p) => p.id === preset)?.note}</p> : null}
        </>
      }
      insights={
        <>
          <h2>Live occupancy</h2>
          <LiveRow color="#147df2" label="Objects" value={n} />
          <LiveRow color="#8b45f4" label="Boxes" value={m} />
          <LiveRow color="#f59e0b" label="ceil(n/m)" value={guaranteed} />
          <LiveRow color="#ef4444" label="Current max" value={maxOcc} />
          <LiveRow color="#10b981" label="Distribution" value={dist.slice(0, displayM).join(" · ")} />
          <FormulaCard title="Pigeonhole" formula="guaranteed occupancy = ⌈n/m⌉" note={n > m ? "More objects than boxes forces at least one box with ≥ 2 in the basic case." : "Increase n past m to force a collision."} />
          <p className="combo-note">{kind === "generalized" ? `Even split cannot keep every box below ${guaranteed}.` : "At least one box must contain ≥ 2 when n > m."}</p>
          <ChallengeCard {...challenge} proof={challenge.proof} onNew={() => setCh((c) => c + 1)} />
        </>
      }
    />
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useState } from "react";
import {
  combination,
  combinationWithRepetition,
  factorial,
  generateCombinations,
  generatePermutations,
  generateSubsets,
  letters,
  pascalTriangle,
  permutation,
  starsAndBars,
} from "./combinatoricsMath";
import { parseSelKind } from "./combinatoricsMode";
import {
  ChallengeCard,
  ComboWorkspace,
  FormulaCard,
  LiveRow,
  ProductPath,
  Seg,
  Slider,
  Token,
  tokenColor,
} from "./combinatoricsUi";

const CHALLENGES = [
  { prompt: "Choose 3 from 8. How many selections?", expected: 56, hint: "C(8,3) = 8!/(3!5!).", proof: "C(8,3)=56" },
  { prompt: "C(6,3) = ?", expected: 20, hint: "Row 6 of Pascal, entry 3.", proof: "C(5,2)+C(5,3)=10+10=20" },
  { prompt: "Subsets of a 3-element set?", expected: 8, hint: "2³.", proof: "C(3,0)+…+C(3,3)=8" },
  { prompt: "Scoops: 4 from 3 flavors, repetition allowed?", expected: 15, hint: "C(3+4−1,4).", proof: "C(6,4)=15" },
];

export default function SelectionsLab({
  kindRaw,
  setKind,
  pulse,
}: {
  kindRaw: string | null;
  setKind: (id: string) => void;
  pulse: string;
}) {
  const kind = parseSelKind(kindRaw);
  const [collapsed, setCollapsed] = useStudioState("SelectionsLab:SelectionsLab:collapsed", false);
  const [n, setN] = useStudioState("SelectionsLab:SelectionsLab:n", 6);
  const [r, setR] = useStudioState("SelectionsLab:SelectionsLab:r", 3);
  const [picked, setPicked] = useStudioState<string[]>("SelectionsLab:SelectionsLab:picked", ["A", "C", "E"]);
  const [hover, setHover] = useState<{ n: number; k: number } | null>({ n: 6, k: 3 });
  const [orderMatters, setOrderMatters] = useStudioState("SelectionsLab:SelectionsLab:orderMatters", false);
  const [scoops, setScoops] = useStudioState("SelectionsLab:SelectionsLab:scoops", [2, 1, 1]);
  const [ch, setCh] = useStudioState("SelectionsLab:SelectionsLab:ch", 0);
  const items = letters(n);
  const pascal = useMemo(() => pascalTriangle(8), []);

  useEffect(() => {
    if (kind === "ncr") { setN(6); setR(3); setPicked(["A", "C", "E"]); }
    if (kind === "compare") { setN(3); setR(2); }
    if (kind === "pascal") { setN(6); setR(3); setHover({ n: 6, k: 3 }); }
    if (kind === "repetition") { setN(3); setR(4); setScoops([2, 1, 1]); }
    if (kind === "subsets") setN(3);
  }, [kind]);

  const toggle = (label: string) => {
    setPicked((current) => {
      if (current.includes(label)) return current.filter((x) => x !== label);
      if (current.length >= r) return [...current.slice(1), label];
      return [...current, label];
    });
  };

  const c = combination(n, r);
  const p = permutation(n, r);
  const combos = generateCombinations(items, Math.min(r, n));
  const perms = generatePermutations(items, Math.min(r, n), 60);
  const subsets = generateSubsets(letters(Math.min(n, 4)));
  const flavors = ["V", "C", "S"];
  const bars = starsAndBars(scoops);
  const withRep = combinationWithRepetition(n, r);
  const challenge = CHALLENGES[ch % CHALLENGES.length]!;
  const scoopTotal = scoops.reduce((s, v) => s + v, 0);

  return (
    <ComboWorkspace
      theme="sel"
      collapsed={collapsed}
      onToggle={() => setCollapsed((v) => !v)}
      controls={
        <>
          <h2>Selection setup</h2>
          <Seg
            label="Selection type"
            value={kind}
            onChange={setKind}
            options={[
              { id: "ncr", label: "Choose k from n" },
              { id: "compare", label: "Order vs not" },
              { id: "pascal", label: "Pascal" },
              { id: "repetition", label: "With repetition" },
              { id: "subsets", label: "Subsets" },
            ]}
          />
          {kind !== "repetition" ? <Slider label="n" value={n} min={3} max={kind === "subsets" ? 4 : 8} onChange={setN} /> : <Slider label="Flavors n" value={n} min={2} max={4} onChange={setN} />}
          {kind !== "subsets" ? <Slider label="Choose r" value={r} min={0} max={kind === "repetition" ? 6 : n} onChange={setR} /> : null}
          {kind === "compare" || kind === "ncr" ? (
            <label className="combo-note">
              <input type="checkbox" checked={orderMatters} onChange={(e) => setOrderMatters(e.target.checked)} /> Order matters
            </label>
          ) : null}
          <p className="combo-note">Click tokens to select a subset. Order does not matter unless the comparison toggle is on.</p>
        </>
      }
      viz={
        <>
          {kind === "pascal" ? (
            <>
              <h2>Pascal connection</h2>
              <div className="combo-pascal" aria-label="Pascal triangle">
                {pascal.map((row, i) => (
                  <span key={i}>
                    {row.map((value, k) => {
                      const on = hover?.n === i && hover?.k === k;
                      const parent = hover && i === hover.n - 1 && (k === hover.k - 1 || k === hover.k);
                      return (
                        <i
                          key={`${i}-${k}`}
                          className={on ? "is-on" : parent ? "is-parent" : ""}
                          onMouseEnter={() => setHover({ n: i, k })}
                        >
                          {value}
                        </i>
                      );
                    })}
                  </span>
                ))}
              </div>
              {hover ? (
                <p className="combo-formula">
                  C({hover.n},{hover.k}) = {combination(hover.n, hover.k)}
                  {hover.n > 0 && hover.k > 0 && hover.k < hover.n
                    ? ` = C(${hover.n - 1},${hover.k - 1}) + C(${hover.n - 1},${hover.k}) = ${combination(hover.n - 1, hover.k - 1)} + ${combination(hover.n - 1, hover.k)}`
                    : ""}
                </p>
              ) : null}
            </>
          ) : null}
          {kind === "ncr" || kind === "compare" ? (
            <>
              <h2 className={pulse === "observe" ? "combo-focus" : undefined}>Objects</h2>
              <div className="combo-tokens">
                {items.map((label, i) => (
                  <Token key={label} label={label} color={tokenColor(label, i)} selected={picked.includes(label)} onClick={() => toggle(label)} />
                ))}
              </div>
              <p className="combo-note">Selection tray (unordered)</p>
              <div className="combo-stage">
                {picked.map((label, i) => <Token key={label} label={label} color={tokenColor(label, i)} />)}
              </div>
              {kind === "compare" ? (
                <div className="combo-compare">
                  <div className="combo-card">
                    <h3>Order matters · P({n},{r}) = {p}</h3>
                    <div className="combo-list">{perms.slice(0, 12).map((row) => <span key={row.join("")}>{row.join("")}</span>)}</div>
                  </div>
                  <div className="combo-card">
                    <h3>Order does not · C({n},{r}) = {c}</h3>
                    <div className="combo-list">{combos.map((row) => <span key={row.join("")} className={picked.slice().sort().join("") === row.slice().sort().join("") ? "is-on" : ""}>{row.join("")}</span>)}</div>
                    <p className="combo-note">ABC, ACB, BAC collapse into one combination.</p>
                  </div>
                </div>
              ) : (
                <>
                  <p className="combo-note">{orderMatters ? `Those ${picked.length} items would count as ${factorial(picked.length)} ordered lists.` : "ABC, ACB, and BAC are the same selection."}</p>
                  {picked.length >= 2 && !orderMatters ? (
                    <div className="combo-collapse" aria-label="Orders collapse">
                      {generatePermutations(picked, picked.length, 12).map((row) => <s key={row.join("")}>{row.join("")}</s>)}
                      <span>→</span>
                      <strong>{[...picked].sort().join("")}</strong>
                    </div>
                  ) : null}
                </>
              )}
            </>
          ) : null}
          {kind === "subsets" ? (
            <>
              <h2>Power set of {`{${letters(n).join(",")}}`}</h2>
              <div className="combo-subset">
                {[0, 1, 2, 3, 4].filter((size) => size <= n).map((size) => (
                  <div key={size}>
                    <em>C({n},{size})={combination(n, size)}</em>
                    {subsets.filter((s) => s.length === size).map((s) => <span key={s.join("") || "empty"} className="combo-list"><span>{s.length ? `{${s.join(",")}}` : "∅"}</span></span>)}
                  </div>
                ))}
              </div>
              <ProductPath factors={Array.from({ length: n + 1 }, (_, k) => combination(n, k))} total={2 ** n} />
            </>
          ) : null}
          {kind === "repetition" ? (
            <>
              <h2>Stars and bars</h2>
              <p className="combo-note">4 scoops from vanilla, chocolate, strawberry.</p>
              {flavors.map((f, i) => (
                <Slider key={f} label={`${f} scoops`} value={scoops[i] ?? 0} min={0} max={r} onChange={(v) => setScoops((cur) => { const next = [...cur]; next[i] = v; return next; })} />
              ))}
              <p className="combo-stars">{bars}</p>
              <p className="combo-formula">C(n+r−1, r) = C({n}+{r}−1, {r}) = {withRep}</p>
              <p className="combo-note">Current composition uses {scoopTotal} scoops. Stars are scoops; bars separate flavors.</p>
            </>
          ) : null}
        </>
      }
      insights={
        <>
          <h2>Live values</h2>
          <LiveRow color="#147df2" label="n" value={n} />
          <LiveRow color="#8b45f4" label="r" value={r} />
          <LiveRow color="#10b981" label="C(n,r)" value={c} />
          {kind === "compare" ? <LiveRow color="#f59e0b" label="P(n,r)" value={p} /> : null}
          <LiveRow color="#08b9dd" label="Selected" value={picked.join("") || "—"} />
          {kind === "subsets" ? <LiveRow color="#0ea5e9" label="2ⁿ" value={2 ** n} /> : null}
          {kind === "repetition" ? <LiveRow color="#f59e0b" label="C(n+r−1,r)" value={withRep} /> : null}
          {kind === "ncr" || kind === "compare" ? <FormulaCard title="Formula" formula="C(n,r) = n! / [r!(n−r)!]" note="Order does not matter. C(n,r)=C(n,n−r)." /> : null}
          {kind === "pascal" ? <FormulaCard title="Pascal identity" formula="C(n,k)=C(n−1,k−1)+C(n−1,k)" note="Hover a cell to see its two parents flow into it." /> : null}
          {kind === "repetition" ? <FormulaCard title="With repetition" formula="C(n+r−1, r)" note="Stars and bars counts flavor compositions." /> : null}
          {kind === "subsets" ? <FormulaCard title="Power set" formula="2ⁿ = Σ C(n,k)" note="Group subsets by size." /> : null}
          <ChallengeCard {...challenge} onNew={() => setCh((c) => c + 1)} />
        </>
      }
    />
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect } from "react";
import type { StudioMockupPage } from "../../mockup/studioMockupCatalog";
import { ChallengeBox, LiveRow, Panel, SliderRow, StatusOk } from "../../mockup/studioLabKit";
import { FigureToolbar, Phase1LabChrome } from "../../phase1/Phase1LabChrome";
import { useStudioFigure } from "../../phase1/useStudioFigure";
import { affine, avalancheBits, caesar, dhMix, letterFreq, modInverse, modPow, toyHash, vigenere } from "./cryptoMath";

type Fig = { p: number; q: number; e: number; m: number; shift: number; a: number; b: number };
const initial: Fig = { p: 61, q: 53, e: 17, m: 72, shift: 3, a: 5, b: 8 };

export default function CryptographyLab({ page }: { page: StudioMockupPage }) {
  const fig = useStudioFigure(initial);
  const [plain, setPlain] = useStudioState("CryptographyLab:CryptographyLab:plain", "HELLO MATH");
  const [key, setKey] = useStudioState("CryptographyLab:CryptographyLab:key", "KEY");
  const [rsaMessage, setRsaMessage] = useStudioState("CryptographyLab:CryptographyLab:rsaMessage", "MATH");
  const [rsaStage, setRsaStage] = useStudioState("CryptographyLab:CryptographyLab:rsaStage", 0);
  const [rsaPlaying, setRsaPlaying] = useStudioState("CryptographyLab:CryptographyLab:rsaPlaying", false);
  const [challengeE, setChallengeE] = useStudioState("CryptographyLab:CryptographyLab:challengeE", 7);
  const n = fig.state.p * fig.state.q;
  const phi = (fig.state.p - 1) * (fig.state.q - 1);
  const d = modInverse(fig.state.e, phi);
  const pow = modPow(fig.state.m, fig.state.e, n);
  const recovered = modPow(pow.value, d, n).value;
  const isPrime = (value: number) => Number.isInteger(value) && value > 1 && Array.from({ length: Math.floor(Math.sqrt(value)) - 1 }, (_, i) => i + 2).every((divisor) => value % divisor !== 0);
  const gcd = (a: number, b: number): number => b ? gcd(b, a % b) : a;
  const validKeys = isPrime(fig.state.p) && isPrime(fig.state.q) && fig.state.p !== fig.state.q && gcd(fig.state.e, phi) === 1;
  const codes = [...rsaMessage.toUpperCase().replace(/[^A-Z ]/g, "").slice(0, 8)].map((char) => char.charCodeAt(0));
  const encrypted = validKeys ? codes.map((code) => modPow(code, fig.state.e, n).value) : [];
  const decrypted = validKeys ? encrypted.map((code) => modPow(code, d, n).value) : [];
  const freq = letterFreq(plain);
  const mix = dhMix(6, 15, 5, 23);
  useEffect(() => {
    if (!rsaPlaying || rsaStage >= 3) return;
    const timer = window.setTimeout(() => setRsaStage((stage) => stage + 1), 850);
    return () => window.clearTimeout(timer);
  }, [rsaPlaying, rsaStage]);

  return (
    <Phase1LabChrome
      page={page}
      toolbar={
        <FigureToolbar
          canUndo={fig.canUndo}
          canRedo={fig.canRedo}
          exact={fig.exact}
          onUndo={fig.undo}
          onRedo={fig.redo}
          onReset={fig.reset}
          onShare={() => void fig.share()}
          onExact={fig.setExact}
        />
      }
    >
      {(mode) => (
        <>
          <Panel title={mode === "RSA Concept" ? "1. Key generation (RSA concept)" : mode}>
            {mode === "RSA Concept" ? (
              <>
                <SliderRow label="Prime p" value={fig.state.p} min={11} max={97} step={2} onChange={(p) => fig.commit({ ...fig.state, p })} />
                <SliderRow label="Prime q" value={fig.state.q} min={11} max={97} step={2} onChange={(q) => fig.commit({ ...fig.state, q })} />
                <SliderRow label="Public exponent e" value={fig.state.e} min={3} max={19} step={2} onChange={(e) => fig.commit({ ...fig.state, e })} />
                <SliderRow label="Plaintext m" value={fig.state.m} min={2} max={200} step={1} onChange={(m) => fig.commit({ ...fig.state, m })} />
                <label className="msk-note">Short message <input aria-label="RSA short message" maxLength={8} value={rsaMessage} onChange={(event) => { setRsaMessage(event.target.value.toUpperCase()); setRsaStage(0); }} /></label>
                <p className="msk-note">{validKeys ? `Valid toy keys: gcd(${fig.state.e}, ${phi}) = 1.` : "Choose distinct primes p, q and an exponent coprime to φ(n)."}</p>
                <p className="msk-note">Educational keys only — no real secrets.</p>
              </>
            ) : mode === "Caesar" || mode === "Affine" || mode === "Vigenère" ? (
              <>
                <label className="msk-note">Plaintext <input value={plain} onChange={(e) => setPlain(e.target.value.toUpperCase())} /></label>
                {mode === "Caesar" ? <SliderRow label="Shift" value={fig.state.shift} min={0} max={25} step={1} onChange={(shift) => fig.commit({ ...fig.state, shift })} /> : null}
                {mode === "Affine" ? (
                  <>
                    <SliderRow label="a" value={fig.state.a} min={1} max={25} step={2} onChange={(a) => fig.commit({ ...fig.state, a })} />
                    <SliderRow label="b" value={fig.state.b} min={0} max={25} step={1} onChange={(b) => fig.commit({ ...fig.state, b })} />
                  </>
                ) : null}
                {mode === "Vigenère" ? <label className="msk-note">Key <input value={key} onChange={(e) => setKey(e.target.value)} /></label> : null}
              </>
            ) : mode === "Diffie-Hellman" ? (
              <p className="msk-note">Paint-mix metaphor: Alice mixes yellow+secret, Bob mixes cyan+secret, they swap public paints and both reach the same brown (shared secret {mix.shared}).</p>
            ) : (
              <p className="msk-note">Flip one letter. The toy hash should avalanche.</p>
            )}
          </Panel>
          <section className="msk-panel msk-canvas" data-mode-canvas={mode}>
            {mode === "RSA Concept" ? (
              <>
                <svg className="msk-graph" viewBox="0 0 360 220" role="img" aria-label="Modular exponentiation clock">
                  <rect width="360" height="220" fill="#f8fbff" />
                  <circle cx="180" cy="110" r="78" fill="none" stroke="#147df2" />
                  {pow.trail.slice(0, 8).map((v, i) => {
                    const a = (i / 8) * Math.PI * 2 - Math.PI / 2;
                    return <circle key={i} cx={180 + Math.cos(a) * 78} cy={110 + Math.sin(a) * 78} r={i === pow.trail.length - 1 ? 7 : 4} fill={i === 3 ? "#f59e0b" : "#8b45f4"} />;
                  })}
                  <text x="150" y="114" fontSize="12">mᵉ mod n</text>
                </svg>
                <p className="msk-formula">plaintext m={fig.state.m} → c = mᵉ mod n = {pow.value} → recovered m = cᵈ mod n = {recovered}</p>
                <div className="msk-seg"><button type="button" disabled={rsaStage === 0} onClick={() => { setRsaPlaying(false); setRsaStage((stage) => stage - 1); }}>Previous</button><button type="button" disabled={rsaStage === 3 || !validKeys} onClick={() => setRsaStage((stage) => stage + 1)}>Next RSA step</button><button type="button" disabled={!validKeys} onClick={() => { setRsaStage(0); setRsaPlaying(true); }}>{rsaPlaying && rsaStage < 3 ? "Playing…" : "Play message"}</button><button type="button" onClick={() => { setRsaPlaying(false); setRsaStage(0); }}>Restart</button></div>
                <h3>{["1. Create keys", "2. Encode letters", "3. Encrypt each code", "4. Decrypt and read"][rsaStage]}</h3>
                <p className="msk-formula">{rsaStage === 0 ? `n = ${fig.state.p} × ${fig.state.q} = ${n}; φ(n) = ${phi}; e × d = ${fig.state.e} × ${d} ≡ 1 (mod ${phi})` : rsaStage === 1 ? `${rsaMessage} → ${codes.join(" · ")} (character codes)` : rsaStage === 2 ? codes.map((code, index) => `${code}^${fig.state.e} mod ${n} = ${encrypted[index]}`).join("; ") : encrypted.map((code, index) => `${code}^${d} mod ${n} = ${decrypted[index]}`).join("; ") + ` → ${String.fromCharCode(...decrypted)}`}</p>
              </>
            ) : mode === "Caesar" || mode === "Affine" || mode === "Vigenère" ? (
              <>
                <p className="msk-formula">{mode === "Affine" ? affine(plain, fig.state.a, fig.state.b) : mode === "Vigenère" ? vigenere(plain, key) : caesar(plain, fig.state.shift)}</p>
                <svg className="msk-graph" viewBox="0 0 360 120" aria-label="Frequency">
                  <rect width="360" height="120" fill="#f8fbff" />
                  {freq.map((c, i) => <rect key={i} x={8 + i * 13} y={110 - c * 12} width="11" height={c * 12} fill="#147df2" />)}
                </svg>
              </>
            ) : mode === "Diffie-Hellman" ? (
              <svg className="msk-graph" viewBox="0 0 360 180" aria-label="Paint mix">
                <rect width="360" height="180" fill="#f8fbff" />
                <circle cx="80" cy="90" r="40" fill="#facc15" />
                <circle cx="180" cy="90" r="40" fill="#22d3ee" />
