          <Field label="Compare GCD with B">
            <input value={gcdB} onChange={(e) => setGcdB(e.target.value)} />
          </Field>
          <button type="button" className="msk-soft" onClick={() => {
            const B = parseStudioInt(gcdB, 1, 1000, "B");
