  return <div><svg viewBox={`${minX} ${minY} ${maxX - minX} ${maxY - minY}`} role="img" aria-label={`${solid} net`} style={{ width: "100%", minHeight: 180 }}>{faces.map((face, i) => <polygon key={face.name} points={face.points} fill={selected === i ? "#8b5cf666" : "#06b6d433"} stroke="#0891b2" strokeWidth=".06" />)}</svg><div className="gu-filter-row">{faces.map((face, i) => <button type="button" key={face.name} aria-pressed={i === selected} onClick={() => setSelected(i)}>{face.name}</button>)}</div><output>{faces[selected]?.name}: area {faces[selected]?.area.toFixed(3)} square units</output></div>;
