  const sub = parseAngleKind(kind || "inscribed");
  const [aDeg, setA] = usePersisted("ang.a", 20);
  const [bDeg, setB] = usePersisted("ang.b", 120);
  const [cDeg, setC] = usePersisted("ang.c", 220);
  const [dDeg, setD] = usePersisted("ang.d", 300);
  const [showArc, setShowArc] = usePersisted("ang.arc", true);
  const [showThm, setShowThm] = usePersisted("ang.thm", true);
  const [showMeas, setShowMeas] = usePersisted("ang.meas", true);
  const [lockSeg, setLock] = usePersisted("ang.lock", true);
  const [animate, setAnimate] = usePersisted("ang.anim", false);
  const [preset, setPreset] = usePersisted("ang.preset", "same");
  const [status, setStatus] = useState<"idle" | "pass" | "fail">("idle");
  const [collapsed, setCollapsed] = useStudioState("AnglesLab:AnglesLab:collapsed", false);
  const [focused, setFocused] = useStudioState<string | null>("AnglesLab:AnglesLab:focused", "C");
  const [px, setPx] = usePersisted("ang.px", 8.4);
  const [py, setPy] = usePersisted("ang.py", 1.6);

  useEffect(() => {
    if (!animate || !active) return;
    let frame = 0;
    const tick = () => {
      setC((value) => stepOnComplementaryArc(aDeg, bDeg, value, 0.7));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [active, animate, aDeg, bDeg, setC]);

  useEffect(() => { registerUndo(() => apply("same")); }, [registerUndo]);

  const A = pointOnCircle(origin, r, toRad(aDeg));
  const B = pointOnCircle(origin, r, toRad(bDeg));
  const C = pointOnCircle(origin, r, toRad(lockSeg ? clampToComplementaryArc(aDeg, bDeg, cDeg) : cDeg));
  const D = pointOnCircle(origin, r, toRad(dDeg));
  const Pext = { x: origin.x + px, y: origin.y + py };
  const chordHit = lineIntersection(A, B, C, D);
  const central = minorArcDeg(aDeg, bDeg);
  const inscribed = toDeg(angleBetween(A, C, B));
  const angA = toDeg(angleBetween(B, A, D));
  const angB = toDeg(angleBetween(A, B, C));
  const angC = toDeg(angleBetween(B, C, D));
  const angD = toDeg(angleBetween(C, D, A));
  const expectedInscribed = central / 2;
  const tanDir = perp({ x: A.x - origin.x, y: A.y - origin.y });

  const apply = (id: string) => {
    setPreset(id);
    if (id === "semi") { setKind("semi"); setA(0); setB(180); setC(90); }
    if (id === "same") { setKind("inscribed"); setA(20); setB(120); setC(220); }
    if (id === "chords") { setKind("chords"); setA(30); setB(200); setC(110); setD(300); }
    if (id === "external") { setKind("secants"); setA(50); setB(130); setC(200); setD(320); }
    if (id === "cyclic") { setKind("cyclic"); setA(20); setB(100); setC(200); setD(300); }
  };

  const movePoint = (id: string, math: Vec) => {
    if (id === "O") setOrigin(math);
    if (id === "A") setA(snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin))));
    if (id === "B") setB(snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin))));
    if (id === "C") {
      const ang = snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin)));
      setC(lockSeg ? clampToComplementaryArc(aDeg, bDeg, ang) : ang);
    }
    if (id === "D") setD(snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin))));
    if (id === "P") {
      const q = constrainOutside(origin, r, math);
      setPx(q.x - origin.x); setPy(q.y - origin.y);
    }
    if (id === "R") setR(clamp(dist(origin, math), 2.5, 7));
  };

  const { svgRef, onPointerDown, onPointerMove, onPointerUp } = useSvgDrag((id, math) => movePoint(id, math), setFocused);
  const stayNote = lockSeg ? `∠ACB stays ${fmt(inscribed, 1)}° on this arc.` : "";

  return (
    <div className="clab-workspace">
      <aside className={`clab-col clab-controls ${collapsed ? "is-collapsed" : ""}`}>
        <button type="button" className="clab-mobile-toggle" onClick={() => setCollapsed((v) => !v)}>{collapsed ? "Show controls" : "Hide controls"}</button>
        <h2>Angle controls</h2>
        <div className="clab-seg" role="group" aria-label="Angle type">
          {SUB.map((item) => (
            <button key={item.id} type="button" className={sub === item.id ? "is-on" : ""} onClick={() => setKind(item.id)}>{item.label}</button>
          ))}
        </div>
        <Slider label={`Radius (${unitLabel})`} value={r} min={2.5} max={7} step={0.1} onChange={setR} />
        <Slider label="Point A" value={aDeg} min={-180} max={180} step={1} unit="°" onChange={(n) => setA(snapA(n))} />
        <Slider label="Point B" value={bDeg} min={-180} max={180} step={1} unit="°" onChange={(n) => setB(snapA(n))} />
        <Slider label="Point C" value={cDeg} min={-180} max={180} step={1} unit="°" onChange={(n) => setC(snapA(n))} />
        <Toggle label="Show intercepted arc" checked={showArc} onChange={setShowArc} />
        <Toggle label="Show theorem" checked={showThm} onChange={setShowThm} />
        <Toggle label="Show measurements" checked={showMeas} onChange={setShowMeas} />
        <Toggle label="Same-segment lock for C" checked={lockSeg} onChange={setLock} />
        <Toggle label="Animate C on the same arc" checked={animate} onChange={setAnimate} />
        <div className="clab-presets">
          <PresetButton label="Semicircle" active={preset === "semi"} onClick={() => apply("semi")} />
          <PresetButton label="Same Segment" active={preset === "same"} onClick={() => apply("same")} />
          <PresetButton label="Intersecting Chords" active={preset === "chords"} onClick={() => apply("chords")} />
          <PresetButton label="External Angle" active={preset === "external"} onClick={() => apply("external")} />
          <PresetButton label="Cyclic quad" active={preset === "cyclic"} onClick={() => apply("cyclic")} />
        </div>
      </aside>
      <section className="clab-col clab-viz">
        <CircleSvg ariaLabel="Circle angle explorer" svgRef={svgRef} unitLabel={unitLabel} focused={focused} onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onKeyMove={(id, dx, dy) => {
          const p = id === "A" ? A : id === "B" ? B : id === "C" ? C : id === "D" ? D : origin;
          movePoint(id, { x: p.x + dx, y: p.y + dy });
        }}>
          <CircleOutline origin={origin} radius={r} />
          {showArc && sub !== "cyclic" ? <ArcPath origin={origin} radius={r} startRad={toRad(aDeg)} endRad={toRad(bDeg)} fill="rgba(139,69,244,.14)" /> : null}
          {sub === "central" || sub === "inscribed" || sub === "semi" ? (
            <>
              <RadiusLine origin={origin} point={A} />
              <RadiusLine origin={origin} point={B} />
              {sub !== "central" ? <ChordLine a={A} b={C} /> : null}
              {sub !== "central" ? <ChordLine b={B} a={C} /> : null}
              {sub === "semi" ? <ChordLine a={A} b={B} color="#0f2747" /> : null}
              <AngleMarker vertex={origin} from={A} to={B} color="#8b45f4" />
              {sub !== "central" ? <AngleMarker vertex={C} from={A} to={B} radius={0.9} color="#147df2" /> : null}
            </>
          ) : null}
          {sub === "chords" ? (
            <>
              <ChordLine a={A} b={B} />
              <ChordLine a={C} b={D} color="#f59e0b" />
              {chordHit ? <AngleMarker vertex={chordHit} from={A} to={C} color="#8b45f4" /> : null}
            </>
          ) : null}
          {sub === "secants" ? (
            <>
              <ChordLine a={Pext} b={B} color="#147df2" />
              <ChordLine a={Pext} b={D} color="#8b45f4" />
              <AngleMarker vertex={Pext} from={A} to={C} color="#f59e0b" />
              <DraggablePoint point={Pext} label="P" color="#8b45f4" dragId="P" />
            </>
          ) : null}
          {sub === "tangent" ? (
            <>
              <TangentLine point={A} direction={tanDir} />
              <ChordLine a={A} b={B} />
              <ChordLine a={B} b={C} color="#8b45f4" />
              <AngleMarker vertex={A} from={{ x: A.x + tanDir.x, y: A.y + tanDir.y }} to={B} color="#f59e0b" />
              <AngleMarker vertex={C} from={A} to={B} color="#8b45f4" />
            </>
          ) : null}
          {sub === "cyclic" ? (
            <>
              <ChordLine a={A} b={B} />
              <ChordLine a={B} b={C} />
              <ChordLine a={C} b={D} color="#8b45f4" />
              <ChordLine a={D} b={A} color="#8b45f4" />
              <AngleMarker vertex={A} from={B} to={D} color="#147df2" />
              <AngleMarker vertex={C} from={B} to={D} color="#8b45f4" />
            </>
          ) : null}
          <DraggablePoint point={origin} label="O" color="#0f2747" dragId="O" />
          <DraggablePoint point={A} label="A" dragId="A" />
          <DraggablePoint point={B} label="B" color="#f59e0b" dragId="B" />
          <DraggablePoint point={C} label="C" color="#8b45f4" dragId="C" />
          {sub === "chords" || sub === "cyclic" || sub === "secants" ? <DraggablePoint point={D} label="D" color="#10b981" dragId="D" /> : null}
          <DraggablePoint point={{ x: origin.x + r, y: origin.y }} dragId="R" color="#08b9dd" title="Radius handle" />
        </CircleSvg>
      </section>
      <aside className="clab-col clab-insights">
        <h2>Live relationship</h2>
        {showMeas && sub !== "cyclic" ? (
          <>
            <LiveRow color="#8b45f4" label="Intercepted arc AB" value={`${fmt(central, 1)}°`} hidden={teacher} />
            <LiveRow color="#8b45f4" label="Central ∠AOB" value={`${fmt(central, 1)}°`} hidden={teacher} />
            <LiveRow color="#147df2" label="Inscribed ∠ACB" value={`${fmt(inscribed, 1)}°`} hidden={teacher} />
            <LiveRow color="#10b981" label="Half of central" value={`${fmt(expectedInscribed, 1)}°`} hidden={teacher} />
          </>
        ) : null}
        {sub === "cyclic" ? (
          <>
            <LiveRow color="#147df2" label="∠A + ∠C" value={`${fmt(angA, 1)}° + ${fmt(angC, 1)}° = ${fmt(angA + angC, 1)}°`} hidden={teacher} />
            <LiveRow color="#8b45f4" label="∠B + ∠D" value={`${fmt(angB, 1)}° + ${fmt(angD, 1)}° = ${fmt(angB + angD, 1)}°`} hidden={teacher} />
          </>
        ) : null}
        {showThm ? (
          <FormulaCard title="Key relationship" hidden={teacher}>
            {sub === "cyclic" ? "Opposite angles of a cyclic quadrilateral sum to 180°." : "Central angle = 2 × inscribed angle when both subtend the same arc."}
            {sub !== "cyclic" ? <MathLine tex="\angle AOB = 2\,\angle ACB" /> : <MathLine tex="\angle A + \angle C = 180^\circ" />}
            <div className="clab-note">{stayNote}{sub === "semi" ? " Thales: angle in a semicircle is 90°." : ""}</div>
          </FormulaCard>
        ) : null}
        <WorkedCard hidden={teacher} lines={sub === "cyclic"
          ? [`∠A+∠C = ${fmt(angA + angC, 1)}°`, `∠B+∠D = ${fmt(angB + angD, 1)}°`]
          : [`${fmt(central, 1)}° = 2 × ${fmt(inscribed, 1)}°`]} />
        <PropertyCard title="Angle theorems" items={[
          "An inscribed angle is half the central angle that subtends the same arc.",
          "Angles in the same segment are equal — keep C on the complementary arc.",
          "An angle in a semicircle is a right angle (Thales).",
          "The angle between a tangent and a chord equals the angle in the alternate segment.",
          "Opposite angles of a cyclic quadrilateral add to 180°.",
        ]} />
        <p className="clab-why">Why it works: isosceles radii make the exterior central angle twice each inscribed base angle.</p>
        <p className="clab-world">Surveying uses inscribed-angle invariance: any viewpoint on the same arc sees a chord under the same angle.</p>
        <ChallengeCard
          prompt="Construct an inscribed angle of 35° (within 1.5°)."
          status={status}
          onCheck={() => { const ok = nearlyEqual(inscribed, 35, 1.5); setStatus(ok ? "pass" : "fail"); setAnnounce(ok ? "35° constructed" : "Not yet"); }}
          onReset={() => { apply("same"); setStatus("idle"); }}
          onNew={() => { setA(10); setB(80); setC(200); setStatus("idle"); }}
        />
      </aside>
    </div>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useState } from "react";
import {
  arcLength, chordLengthFromCentral, circumference, constrainOnCircle, dist, fmt, nearlyEqual, pointOnCircle, sectorArea, segmentArea, toDeg, toRad, type Vec,
} from "./circleMath";
import { useCircleSession, usePersisted } from "./CircleSession";
import {
  ArcPath, ChallengeCard, ChordLine, CircleOutline, CircleSvg, DraggablePoint, FormulaCard, LiveRow, MathLine, PresetButton, PropertyCard, RadiusLine, Slider, Toggle, WorkedCard, useSvgDrag,
} from "./primitives";

export default function ArcsSectorsLab({ active }: { active: boolean }) {
  const { r, setR, origin, setOrigin, snapA, teacher, unitLabel, registerUndo } = useCircleSession();
  const [theta, setTheta] = usePersisted("arc.th", 120);
  const [a0, setA0] = usePersisted("arc.a0", 20);
  const [major, setMajor] = usePersisted("arc.maj", false);
  const [degUnits, setDegUnits] = usePersisted("arc.du", true);
  const [showFormula, setShowFormula] = usePersisted("arc.f", true);
  const [labels, setLabels] = usePersisted("arc.lab", true);
  const [showBoth, setBoth] = usePersisted("arc.both", true);
  const [sweep, setSweep] = usePersisted("arc.sw", false);
  const [display, setDisplay] = useStudioState("ArcsSectorsLab:ArcsSectorsLab:display", 120);
  const [status, setStatus] = useState<"idle" | "pass" | "fail">("idle");
  const [collapsed, setCollapsed] = useStudioState("ArcsSectorsLab:ArcsSectorsLab:collapsed", false);
  const [challenge, setChallenge] = usePersisted("arc.ch", 0);
  const [focused, setFocused] = useStudioState<string | null>("ArcsSectorsLab:ArcsSectorsLab:focused", "B");

  useEffect(() => {
    if (!sweep || !active) { setDisplay(theta); return; }
    let frame = 0;
    const tick = () => {
      setDisplay((value) => {
        const next = value + 1.2;
        return next >= theta ? theta : next;
      });
      frame = requestAnimationFrame(tick);
    };
    setDisplay(8);
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [sweep, theta, active]);

  useEffect(() => { registerUndo(() => { setTheta(120); setR(5); }); }, [registerUndo, setR, setTheta]);

  const shown = major ? 360 - Math.abs(display) : Math.abs(display);
  const A = pointOnCircle(origin, r, toRad(a0));
  const B = pointOnCircle(origin, r, toRad(a0 + shown));
  const circ = circumference(r);
  const s = arcLength(r, shown);
  const area = sectorArea(r, shown);
  const chord = chordLengthFromCentral(r, toRad(shown));
  const segment = segmentArea(r, shown);
  const majorTheta = 360 - shown;
  const sMaj = arcLength(r, majorTheta);
  const areaMaj = sectorArea(r, majorTheta);

  const { svgRef, onPointerDown, onPointerMove, onPointerUp } = useSvgDrag((id, math) => {
    if (id === "O") setOrigin(math);
    if (id === "A") setA0(snapA(toDeg(Math.atan2(math.y - origin.y, math.x - origin.x))));
    if (id === "B") {
      const ang = toDeg(Math.atan2(math.y - origin.y, math.x - origin.x));
      let d = ang - a0;
      while (d < 0) d += 360;
      while (d > 360) d -= 360;
      setTheta(Math.max(8, Math.min(350, d)));
      setMajor(d > 180);
    }
    if (id === "R") setR(Math.max(2.4, Math.min(7.2, dist(origin, math))));
  }, setFocused);

  const challenges = [
    { prompt: "Create a sector with central angle 120°.", check: () => nearlyEqual(Math.abs(theta), 120, 2) },
    { prompt: "Create a sector with area ≈ 25π (r²θ/360 ≈ 25π).", check: () => nearlyEqual(area / Math.PI, 25, 0.8) },
  ];

  return (
    <div className="clab-workspace">
      <aside className={`clab-col clab-controls ${collapsed ? "is-collapsed" : ""}`}>
        <button type="button" className="clab-mobile-toggle" onClick={() => setCollapsed((v) => !v)}>{collapsed ? "Show controls" : "Hide controls"}</button>
        <h2>Arc & sector controls</h2>
        <Slider label={`Radius r (${unitLabel})`} value={r} min={2.4} max={7.2} step={0.1} onChange={setR} />
        <Slider label="Central angle θ" value={theta} min={8} max={350} step={1} unit={degUnits ? "°" : ""} onChange={setTheta} />
        <div className="clab-seg" role="group" aria-label="Minor or major">
          <button type="button" className={!major ? "is-on" : ""} onClick={() => setMajor(false)}>Minor</button>
          <button type="button" className={major ? "is-on" : ""} onClick={() => setMajor(true)}>Major</button>
        </div>
        <div className="clab-seg" role="group" aria-label="Angle units">
          <button type="button" className={degUnits ? "is-on" : ""} onClick={() => setDegUnits(true)}>Degrees</button>
          <button type="button" className={!degUnits ? "is-on" : ""} onClick={() => setDegUnits(false)}>Radians</button>
        </div>
        <Toggle label="Show formula" checked={showFormula} onChange={setShowFormula} />
        <Toggle label="Show labels" checked={labels} onChange={setLabels} />
        <Toggle label="Show complementary sector" checked={showBoth} onChange={setBoth} />
        <Toggle label="Animate sector sweep" checked={sweep} onChange={setSweep} />
        <div className="clab-presets">
          <PresetButton label="Semicircle" onClick={() => { setTheta(180); setMajor(false); }} />
          <PresetButton label="Quarter Circle" onClick={() => { setTheta(90); setMajor(false); }} />
          <PresetButton label="60° Sector" onClick={() => { setTheta(60); setMajor(false); }} />
          <PresetButton label="120° Sector" onClick={() => { setTheta(120); setMajor(false); }} />
          <PresetButton label="Major Sector" onClick={() => { setTheta(240); setMajor(true); }} />
        </div>
      </aside>
      <section className="clab-col clab-viz">
        <CircleSvg ariaLabel="Arc and sector explorer" svgRef={svgRef} unitLabel={unitLabel} focused={focused} onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onKeyMove={(id, dx, dy) => {
          const p = id === "A" ? A : id === "B" ? B : origin;
          const hit = constrainOnCircle(origin, r, { x: p.x + dx, y: p.y + dy });
          if (id === "A" || id === "B") {
            const ang = toDeg(Math.atan2(hit.y - origin.y, hit.x - origin.x));
            if (id === "A") setA0(snapA(ang));
            else {
              let d = ang - a0; while (d < 0) d += 360; setTheta(Math.max(8, Math.min(350, d)));
            }
          }
        }}>
          <CircleOutline origin={origin} radius={r} />
          {showBoth ? <ArcPath origin={origin} radius={r} startRad={toRad(a0 + shown)} endRad={toRad(a0 + 360)} fill="rgba(148,163,184,.12)" /> : null}
          <ArcPath origin={origin} radius={r} startRad={toRad(a0)} endRad={toRad(a0 + shown)} fill="rgba(8,185,221,.22)" />
          <ArcPath origin={origin} radius={r} startRad={toRad(a0)} endRad={toRad(a0 + shown)} color="#8b45f4" width={4} />
          <RadiusLine origin={origin} point={A} />
          <RadiusLine origin={origin} point={B} />
          <ChordLine a={A} b={B} color="#147df2" />
          <DraggablePoint point={origin} label="O" color="#0f2747" dragId="O" />
          <DraggablePoint point={A} label={labels ? "A" : undefined} dragId="A" />
          <DraggablePoint point={B} label={labels ? "B" : undefined} color="#f59e0b" dragId="B" />
          <DraggablePoint point={{ x: origin.x + r, y: origin.y }} dragId="R" color="#08b9dd" title="Radius handle" />
        </CircleSvg>
      </section>
      <aside className="clab-col clab-insights">
        <h2>Live calculations</h2>
        <LiveRow color="#08b9dd" label="Circumference 2πr" value={fmt(circ)} hidden={teacher} />
        <LiveRow color="#8b45f4" label="Arc length s" value={fmt(s)} hidden={teacher} />
        <LiveRow color="#147df2" label="Sector area" value={fmt(area)} hidden={teacher} />
        <LiveRow color="#f59e0b" label="Chord AB" value={fmt(chord)} hidden={teacher} />
        <LiveRow color="#10b981" label="Segment area" value={fmt(segment)} hidden={teacher} />
        <LiveRow color="#536381" label="θ" value={degUnits ? `${fmt(shown, 1)}°` : `${fmt(toRad(shown), 3)} rad`} hidden={teacher} />
        {showBoth ? <LiveRow color="#94a3b8" label="Complementary arc / area" value={`${fmt(sMaj)} / ${fmt(areaMaj)}`} hidden={teacher} /> : null}
        {showFormula ? (
          <FormulaCard title="Formulas" hidden={teacher}>
            <MathLine tex="C = 2\pi r" />
            <MathLine tex="s = \dfrac{\theta}{360^\circ}\cdot 2\pi r" />
            <MathLine tex="A = \dfrac{\theta}{360^\circ}\cdot \pi r^2" />
            <MathLine tex="c = 2r\sin(\tfrac{\theta}{2})" />
          </FormulaCard>
        ) : null}
        <WorkedCard hidden={teacher} lines={[
          `s = (${fmt(shown, 0)}/360)·2π·${fmt(r)} = ${fmt(s)}`,
          `A = (${fmt(shown, 0)}/360)·π·${fmt(r)}² = ${fmt(area)}`,
          `major = 360° − ${fmt(shown, 0)}° = ${fmt(majorTheta, 0)}°`,
        ]} />
        <PropertyCard title="Arc facts" items={[
          "Arc measure equals the central angle.",
          "Arc length is the fraction of the circumference.",
          "Sector area is the same fraction of the disk.",
          "A major sector is the complement of the minor sector.",
        ]} />
        <p className="clab-why">Why it works: a full turn is 360° of circumference 2πr and area πr². A sector is that proportional slice.</p>
        <p className="clab-world">Satellite footprints and circular-track lane distances are sector and arc-length calculations on a known radius.</p>
        <ChallengeCard
          prompt={challenges[challenge].prompt}
          status={status}
          onCheck={() => setStatus(challenges[challenge].check() ? "pass" : "fail")}
          onReset={() => { setTheta(120); setR(5); setStatus("idle"); }}
          onNew={() => { setChallenge((i) => (i + 1) % challenges.length); setStatus("idle"); }}
        />
      </aside>
    </div>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useState } from "react";
import {
  angleOf, chordLengthFromCentral, clamp, constrainOnCircle, dist, fmt, midpoint, minorArcDeg, nearlyEqual, pointOnCircle, toDeg, toRad, type Vec,
} from "./circleMath";
import { useCircleSession, usePersisted } from "./CircleSession";
import {
  LengthBadge, ChallengeCard, ChordLine, CircleOutline, CircleSvg, DraggablePoint, FilledTriangle, FormulaCard, GhostChord, LiveRow, MathLine, PresetButton, PropertyCard, RadiusLine, Slider, Toggle, WorkedCard, useSvgDrag,
} from "./primitives";

type Live = { r: number; ab: number; cd: number; om: number; on: number; arc: number; showSecond: boolean };

const CHALLENGES = [
  { id: "len8", prompt: "Create chord AB of length 8 units.", check: (m: Live) => nearlyEqual(m.ab, 8, 0.15) },
  { id: "equal", prompt: "Make AB = CD (turn on the second chord).", check: (m: Live) => m.showSecond && nearlyEqual(m.ab, m.cd, 0.12) },
  { id: "equidist", prompt: "Place two chords equidistant from O.", check: (m: Live) => m.showSecond && nearlyEqual(m.om, m.on, 0.12) },
];

export default function ChordsLab() {
  const { r, setR, origin, setOrigin, snapA, teacher, unitLabel, pushUndo, registerUndo, setAnnounce } = useCircleSession();
  const [aDeg, setA] = usePersisted("chords.a", 28);
  const [bDeg, setB] = usePersisted("chords.b", 148);
  const [cDeg, setC] = usePersisted("chords.c", 210);
  const [dDeg, setD] = usePersisted("chords.d", 300);
  const [showM, setShowM] = usePersisted("chords.m", true);
  const [showPerp, setShowPerp] = usePersisted("chords.perp", true);
  const [showSecond, setShowSecond] = usePersisted("chords.second", true);
  const [showMeas, setShowMeas] = usePersisted("chords.meas", true);
  const [lockEqual, setLock] = usePersisted("chords.lock", false);
  const [showLocus, setLocus] = usePersisted("chords.locus", true);
  const [showPy, setPy] = usePersisted("chords.py", true);
  const [showSteps, setSteps] = usePersisted("chords.steps", true);
  const [preset, setPreset] = usePersisted("chords.preset", "compare");
  const [challenge, setChallenge] = usePersisted("chords.ch", 0);
  const [status, setStatus] = useState<"idle" | "pass" | "fail">("idle");
  const [collapsed, setCollapsed] = useStudioState("ChordsLab:ChordsLab:collapsed", false);
  const [focused, setFocused] = useStudioState<string | null>("ChordsLab:ChordsLab:focused", "A");

  const snapshot = () => {
    const s = { aDeg, bDeg, cDeg, dDeg, origin, r };
    pushUndo(() => { setA(s.aDeg); setB(s.bDeg); setC(s.cDeg); setD(s.dDeg); setOrigin(s.origin); setR(s.r); });
  };
  useEffect(() => { registerUndo(() => apply("compare")); }, [registerUndo]);

  const A = pointOnCircle(origin, r, toRad(aDeg));
  const B = pointOnCircle(origin, r, toRad(bDeg));
  let C = pointOnCircle(origin, r, toRad(cDeg));
  let D = pointOnCircle(origin, r, toRad(dDeg));
  const M = midpoint(A, B);
  const om = dist(origin, M);
  const ab = dist(A, B);
  if (lockEqual) {
    const nDir = { x: Math.cos(toRad((cDeg + dDeg) / 2)), y: Math.sin(toRad((cDeg + dDeg) / 2)) };
    const Npt = { x: origin.x + nDir.x * om, y: origin.y + nDir.y * om };
    const half = ab / 2;
    C = { x: Npt.x - nDir.y * half, y: Npt.y + nDir.x * half };
    D = { x: Npt.x + nDir.y * half, y: Npt.y - nDir.x * half };
  }
  const N = midpoint(C, D);
  const cd = dist(C, D);
  const on = dist(origin, N);
  const arc = minorArcDeg(aDeg, bDeg);
  const live: Live = { r, ab, cd, om, on, arc, showSecond };
  const ghostHalf = 4;
  const ghostD = Math.sqrt(Math.max(0, r * r - ghostHalf * ghostHalf));
  const gDir = { x: Math.cos(toRad(90)), y: Math.sin(toRad(90)) };
  const gM = { x: origin.x + gDir.x * ghostD, y: origin.y + gDir.y * ghostD };
  const gA = { x: gM.x - gDir.y * ghostHalf, y: gM.y + gDir.x * ghostHalf };
  const gB = { x: gM.x + gDir.y * ghostHalf, y: gM.y - gDir.x * ghostHalf };

  const apply = (id: string) => {
    snapshot();
    setPreset(id);
    if (id === "equal") { setA(40); setB(140); setC(220); setD(320); setShowSecond(true); setLock(true); }
    if (id === "diameter") { setA(0); setB(180); setShowSecond(false); setLock(false); }
    if (id === "short") { setA(70); setB(110); setShowSecond(false); }
    if (id === "compare") { setA(20); setB(160); setC(200); setD(250); setShowSecond(true); setLock(false); }
  };

  const movePoint = (id: string, math: Vec) => {
    if (id === "O") setOrigin(math);
    if (id === "A") setA(snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin))));
    if (id === "B") setB(snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin))));
    if (id === "C") setC(snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin))));
    if (id === "D") setD(snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin))));
    if (id === "R") setR(clamp(dist(origin, math), 2.4, 7.2));
    if (id === "M") {
      const d = clamp(dist(origin, math), 0.05, r - 0.2);
      const theta = angleOf(math, origin);
      const half = Math.acos(clamp(d / r, 0, 1));
      setA(snapA(toDeg(theta + half)));
      setB(snapA(toDeg(theta - half)));
    }
  };

  const { svgRef, onPointerDown, onPointerMove, onPointerUp } = useSvgDrag((id, math) => movePoint(id, math), setFocused);

  return (
    <div className="clab-workspace">
      <aside className={`clab-col clab-controls ${collapsed ? "is-collapsed" : ""}`}>
        <button type="button" className="clab-mobile-toggle" onClick={() => setCollapsed((v) => !v)}>{collapsed ? "Show controls" : "Hide controls"}</button>
        <h2>Chord controls</h2>
        <Slider label={`Radius (${unitLabel})`} value={r} min={2.5} max={7.2} step={0.1} onChange={setR} />
        <Slider label="Endpoint A" value={aDeg} min={-180} max={180} step={1} unit="°" onChange={(n) => setA(snapA(n))} />
        <Slider label="Endpoint B" value={bDeg} min={-180} max={180} step={1} unit="°" onChange={(n) => setB(snapA(n))} />
        <Toggle label="Show midpoint M" checked={showM} onChange={setShowM} />
        <Toggle label="Show perpendicular OM" checked={showPerp} onChange={setShowPerp} />
        <Toggle label="Show second chord CD" checked={showSecond} onChange={setShowSecond} />
        <Toggle label="Show measurements" checked={showMeas} onChange={setShowMeas} />
        <Toggle label="Lock equal chords" checked={lockEqual} onChange={setLock} />
        <Toggle label="Locus of equal chords" checked={showLocus} onChange={setLocus} />
        <Toggle label="Pythagoras overlay" checked={showPy} onChange={setPy} />
        <Toggle label="Construction steps" checked={showSteps} onChange={setSteps} />
        <div className="clab-presets">
          <PresetButton label="Equal Chords" active={preset === "equal"} onClick={() => apply("equal")} />
          <PresetButton label="Diameter as Chord" active={preset === "diameter"} onClick={() => apply("diameter")} />
          <PresetButton label="Short Chord" active={preset === "short"} onClick={() => apply("short")} />
          <PresetButton label="Compare Two Chords" active={preset === "compare"} onClick={() => apply("compare")} />
        </div>
      </aside>
      <section className="clab-col clab-viz">
        <CircleSvg ariaLabel="Chord construction with circle centre O" svgRef={svgRef} unitLabel={unitLabel} focused={focused} onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onKeyMove={(id, dx, dy) => {
          const p = id === "A" ? A : id === "B" ? B : id === "C" ? C : id === "D" ? D : id === "M" ? M : id === "O" ? origin : { x: origin.x + r, y: origin.y };
          movePoint(id, { x: p.x + dx, y: p.y + dy });
          setAnnounce(`${id} moved`);
        }}>
          <CircleOutline origin={origin} radius={r} />
          {showLocus ? <CircleOutline origin={origin} radius={om} dashed color="#10b981" /> : null}
          {challenge === 0 ? <GhostChord a={gA} b={gB} /> : null}
          {showPy ? <FilledTriangle a={origin} b={A} c={M} color="rgba(16,185,129,.14)" /> : null}
          <RadiusLine origin={origin} point={A} />
          <RadiusLine origin={origin} point={B} />
          <ChordLine a={A} b={B} />
          {showPerp ? <ChordLine a={origin} b={M} color="#10b981" dashed /> : null}
          {showSecond ? <ChordLine a={C} b={D} color="#8b45f4" /> : null}
          {showSecond && showPerp ? <ChordLine a={origin} b={N} color="#94a3b8" dashed /> : null}
          {showMeas && !teacher ? <>
            <LengthBadge a={A} b={B} text={`AB = ${fmt(ab)} ${unitLabel}`} offsetY={-25} />
            {showPerp ? <LengthBadge a={origin} b={M} text={`OM = ${fmt(om)} ${unitLabel}`} color="#047857"/> : null}
            {showSecond ? <LengthBadge a={C} b={D} text={`CD = ${fmt(cd)} ${unitLabel}`} color="#7c3aed"/> : null}
          </> : null}
          <DraggablePoint point={origin} label="O" color="#0f2747" dragId="O" title="Centre O" />
          <DraggablePoint point={A} label="A" dragId="A" />
          <DraggablePoint point={B} label="B" color="#f59e0b" dragId="B" />
          {showM ? <DraggablePoint point={M} label="M" color="#10b981" dragId="M" title="Midpoint M — drag along the perpendicular" /> : null}
          {showSecond ? <><DraggablePoint point={C} label="C" color="#8b45f4" dragId="C" /><DraggablePoint point={D} label="D" color="#8b45f4" dragId="D" /></> : null}
          <DraggablePoint point={{ x: origin.x + r, y: origin.y }} dragId="R" color="#08b9dd" title="Radius handle" />
        </CircleSvg>
      </section>
      <aside className="clab-col clab-insights">
        <h2>Live measurements</h2>
        <LiveRow color="#08b9dd" label={`Radius r (${unitLabel})`} value={fmt(r)} hidden={teacher} />
        <LiveRow color="#147df2" label="Chord AB" value={fmt(ab)} hidden={teacher} />
        <LiveRow color="#10b981" label="Distance OM" value={fmt(om)} hidden={teacher} />
        {showMeas ? <LiveRow color="#8b45f4" label="Arc AB" value={`${fmt(arc, 1)}°`} hidden={teacher} /> : null}
        {showSecond ? <LiveRow color="#8b45f4" label="Chord CD" value={fmt(cd)} hidden={teacher} /> : null}
        {showSecond ? <LiveRow color="#94a3b8" label="Distance ON" value={fmt(on)} hidden={teacher} /> : null}
        <FormulaCard title="Key relationship" hidden={teacher}>
          If OM ⟂ AB, then AM = MB.
          <MathLine tex="OM^2 + (AB/2)^2 = r^2" />
        </FormulaCard>
        <WorkedCard hidden={teacher} lines={[
          `AM = ${fmt(dist(A, M))}, MB = ${fmt(dist(M, B))}`,
          `${fmt(om)}² + ${fmt(ab / 2)}² = ${fmt(om * om + (ab / 2) ** 2)} = ${fmt(r * r)} = r²`,
          `AB = 2r sin(θ/2) = ${fmt(chordLengthFromCentral(r, toRad(arc)))}`,
        ]} />
        <PropertyCard title="Chord properties" items={[
          "Equal chords are equidistant from the centre.",
          "The perpendicular from the centre bisects a chord.",
          "Equal chords subtend equal central angles.",
          "The larger chord is closer to the centre.",
        ]} />
        <p className="clab-why">Why it works: radii OA and OB are equal, so triangle OAM is congruent to OBM when OM ⟂ AB.</p>
        <p className="clab-world">Real world: a circular track’s shorter chord sits farther from the stadium centre than a longer chord.</p>
        <ChallengeCard
          prompt={CHALLENGES[challenge].prompt}
          status={status}
          onCheck={() => { const ok = CHALLENGES[challenge].check(live); setStatus(ok ? "pass" : "fail"); setAnnounce(ok ? "Challenge passed" : "Not yet"); }}
          onReset={() => { apply("compare"); setStatus("idle"); }}
          onNew={() => { setChallenge((i) => (i + 1) % CHALLENGES.length); setStatus("idle"); }}
        />
      </aside>
    </div>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useState } from "react";
import {
  angleBetween, angleOf, clamp, constrainOnCircle, constrainOutside, dist, fmt, nearlyEqual, perp, pointOnCircle, tangentContactPoints, tangentLength, toDeg, toRad, type Vec,
} from "./circleMath";
import { useCircleSession, usePersisted } from "./CircleSession";
import {
  AngleMarker, ChallengeCard, ChordLine, CircleOutline, CircleSvg, DraggablePoint, FormulaCard, LiveRow, MathLine, PresetButton, PropertyCard, RadiusLine, RightAngleMarker, Slider, TangentLine, Toggle, WorkedCard, useSvgDrag,
} from "./primitives";

export default function TangentsLab() {
  const { r, setR, origin, setOrigin, snapA, teacher, unitLabel, pushUndo, registerUndo, setAnnounce } = useCircleSession();
  const [tDeg, setT] = usePersisted("tan.t", 40);
  const [px, setPx] = usePersisted("tan.px", 8.2);
  const [py, setPy] = usePersisted("tan.py", 2.4);
  const [showRadius, setShowRadius] = usePersisted("tan.sr", true);
  const [showRight, setShowRight] = usePersisted("tan.right", true);
  const [external, setExternal] = usePersisted("tan.ext", true);
  const [showSecond, setShowSecond] = usePersisted("tan.s2", true);
  const [showLen, setShowLen] = usePersisted("tan.len", true);
  const [showSteps, setShowSteps] = usePersisted("tan.steps", true);
  const [altSeg, setAlt] = usePersisted("tan.alt", false);
  const [preset, setPreset] = usePersisted("tan.preset", "two");
  const [status, setStatus] = useState<"idle" | "pass" | "fail">("idle");
  const [challenge, setChallenge] = usePersisted("tan.ch", 0);
  const [collapsed, setCollapsed] = useStudioState("TangentsLab:TangentsLab:collapsed", false);
  const [focused, setFocused] = useStudioState<string | null>("TangentsLab:TangentsLab:focused", "P");

  const T = pointOnCircle(origin, r, toRad(tDeg));
  const tanDir = perp({ x: T.x - origin.x, y: T.y - origin.y });
  const P = { x: origin.x + px, y: origin.y + py };
  const op = dist(origin, P);
  const contacts = external ? tangentContactPoints(origin, r, P) : [];
  const A = contacts[0];
  const B = contacts[1];
  const contact = external && A ? A : T;
  const pt = tangentLength(r, op);
  const pa = A ? dist(P, A) : 0;
  const pb = B ? dist(P, B) : 0;
  const chordPt = pointOnCircle(origin, r, toRad(tDeg + 70));
  const tanChord = toDeg(angleBetween(P, T, chordPt));
  const altAngle = toDeg(angleBetween(T, chordPt, pointOnCircle(origin, r, toRad(tDeg + 200))));

  const apply = (id: string) => {
    pushUndo(() => { setT(40); setPx(8.2); setPy(2.4); setExternal(true); });
    setPreset(id);
    if (id === "basic") { setExternal(false); setShowSecond(false); setAlt(false); setT(35); }
    if (id === "external") { setExternal(true); setShowSecond(false); setAlt(false); setPx(8.4); setPy(1.2); }
    if (id === "two") { setExternal(true); setShowSecond(true); setAlt(false); setPx(8.2); setPy(2.4); }
    if (id === "chord") { setExternal(false); setAlt(true); setT(55); setShowRadius(true); }
  };
  useEffect(() => { registerUndo(() => apply("two")); }, [registerUndo]);

  const movePoint = (id: string, math: Vec) => {
    if (id === "O") setOrigin(math);
    if (id === "T") setT(snapA(toDeg(angleOf(constrainOnCircle(origin, r, math), origin))));
    if (id === "P") {
      const q = constrainOutside(origin, r, math);
      setPx(q.x - origin.x); setPy(q.y - origin.y); setExternal(true);
    }
    if (id === "R") setR(clamp(dist(origin, math), 2.4, 6.8));
  };

  const { svgRef, onPointerDown, onPointerMove, onPointerUp } = useSvgDrag((id, math) => movePoint(id, math), setFocused);
  const ghostR = Math.sqrt(r * r + 36);

  const challenges = [
    { prompt: "Place P so the tangent length PT = 6.", check: () => nearlyEqual(pt, 6, 0.2) && op > r },
    { prompt: "Move T until OT is horizontal (angle ≈ 0°).", check: () => nearlyEqual(tDeg, 0, 6) || nearlyEqual(Math.abs(tDeg), 360, 6) },
  ];

  return (
    <div className="clab-workspace">
      <aside className={`clab-col clab-controls ${collapsed ? "is-collapsed" : ""}`}>
        <button type="button" className="clab-mobile-toggle" onClick={() => setCollapsed((v) => !v)}>{collapsed ? "Show controls" : "Hide controls"}</button>
        <h2>Tangent controls</h2>
        <Slider label={`Radius (${unitLabel})`} value={r} min={2.5} max={6.8} step={0.1} onChange={setR} />
        <Slider label="Tangency point" value={tDeg} min={-180} max={180} step={1} unit="°" onChange={(n) => setT(snapA(n))} />
        <Toggle label="Show radius OT" checked={showRadius} onChange={setShowRadius} />
        <Toggle label="Show 90° marker" checked={showRight} onChange={setShowRight} />
        <Toggle label="External point mode" checked={external} onChange={setExternal} />
        <Toggle label="Show second tangent" checked={showSecond} onChange={setShowSecond} />
        <Toggle label="Show tangent lengths" checked={showLen} onChange={setShowLen} />
        <Toggle label="Alternate-segment theorem" checked={altSeg} onChange={setAlt} />
        <Toggle label="Show construction steps" checked={showSteps} onChange={setShowSteps} />
        <div className="clab-presets">
          <PresetButton label="Basic Tangent" active={preset === "basic"} onClick={() => apply("basic")} />
          <PresetButton label="Tangent from External Point" active={preset === "external"} onClick={() => apply("external")} />
          <PresetButton label="Two Tangents" active={preset === "two"} onClick={() => apply("two")} />
          <PresetButton label="Tangent–Chord Angle" active={preset === "chord"} onClick={() => apply("chord")} />
        </div>
      </aside>
      <section className="clab-col clab-viz">
        <CircleSvg ariaLabel="Tangent construction with contact point T" svgRef={svgRef} unitLabel={unitLabel} focused={focused} onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onKeyMove={(id, dx, dy) => {
          const p = id === "T" ? T : id === "P" ? P : id === "O" ? origin : { x: origin.x + r, y: origin.y };
          movePoint(id, { x: p.x + dx, y: p.y + dy });
        }}>
          <CircleOutline origin={origin} radius={r} />
          {challenge === 0 ? <CircleOutline origin={origin} radius={ghostR} dashed color="#f59e0b" /> : null}
          {showRadius ? <RadiusLine origin={origin} point={contact} /> : null}
          {!external ? <TangentLine point={T} direction={tanDir} /> : null}
          {!external && showRight ? <RightAngleMarker origin={origin} point={T} tangentDir={tanDir} /> : null}
          {external && A ? <RadiusLine origin={origin} point={A} color="#94a3b8" /> : null}
          {external && A ? <ChordLine a={P} b={A} color="#f59e0b" /> : null}
          {external && showSecond && B ? <ChordLine a={P} b={B} color="#f59e0b" /> : null}
          {external && A && showRight ? <RightAngleMarker origin={origin} point={A} tangentDir={perp({ x: A.x - origin.x, y: A.y - origin.y })} /> : null}
          {altSeg ? <ChordLine a={T} b={chordPt} color="#8b45f4" /> : null}
          {altSeg ? <AngleMarker vertex={T} from={P} to={chordPt} color="#f59e0b" /> : null}
          {altSeg ? <AngleMarker vertex={chordPt} from={T} to={pointOnCircle(origin, r, toRad(tDeg + 200))} color="#8b45f4" /> : null}
          <DraggablePoint point={origin} label="O" color="#0f2747" dragId="O" />
          <DraggablePoint point={T} label="T" color="#f59e0b" dragId="T" />
          {external ? <DraggablePoint point={P} label="P" color="#8b45f4" dragId="P" /> : null}
          {external && A ? <DraggablePoint point={A} label="A" color="#147df2" dragId="A" /> : null}
          {external && showSecond && B ? <DraggablePoint point={B} label="B" color="#147df2" dragId="B" /> : null}
          <DraggablePoint point={{ x: origin.x + r, y: origin.y }} dragId="R" color="#08b9dd" title="Radius handle" />
        </CircleSvg>
      </section>
      <aside className="clab-col clab-insights">
        <h2>Live values</h2>
        <LiveRow color="#08b9dd" label={`Radius r (${unitLabel})`} value={fmt(r)} hidden={teacher} />
        <LiveRow color="#f59e0b" label="Tangent angle" value={`${fmt(tDeg, 1)}°`} hidden={teacher} />
        {external ? <LiveRow color="#8b45f4" label="Distance OP" value={fmt(op)} hidden={teacher} /> : null}
        {showLen ? <LiveRow color="#f59e0b" label="Tangent length" value={fmt(pt)} hidden={teacher} /> : null}
        {external && A && showLen ? <LiveRow color="#147df2" label="PA" value={fmt(pa)} hidden={teacher} /> : null}
        {external && B && showLen ? <LiveRow color="#147df2" label="PB" value={fmt(pb)} hidden={teacher} /> : null}
        <FormulaCard title="Key relationship" hidden={teacher}>
          Radius at the point of contact is perpendicular to the tangent.
          <MathLine tex="PT = \sqrt{OP^2 - r^2}" />
          {altSeg ? <div className="clab-note">Tangent–chord {fmt(tanChord, 1)}° vs alternate segment {fmt(altAngle, 1)}°.</div> : null}
        </FormulaCard>
        <WorkedCard hidden={teacher} lines={external ? [
          `PA = ${fmt(pa)}, PB = ${fmt(pb)}`,
          `√(OP² − r²) = ${fmt(pt)}`,
        ] : [`OT ⟂ tangent at T`]} />
        <PropertyCard title="Tangent properties" items={[
          "A tangent touches the circle at exactly one point.",
          "The radius at the point of contact is perpendicular to the tangent.",
          "Tangents from the same external point are equal.",
          "Tangent–chord theorem: the angle between tangent and chord equals the angle in the alternate segment.",
        ]} />
        {showSteps ? <p className="clab-why">Why it works: OT ⟂ tangent, and right triangles OAP and OBP share hypotenuse OP and leg r, so PA = PB.</p> : null}
        <p className="clab-world">Real world: belt drives meet a wheel along a tangent; belt length uses √(d² − r²).</p>
        <ChallengeCard
          prompt={challenges[challenge].prompt}
          status={status}
          onCheck={() => setStatus(challenges[challenge].check() ? "pass" : "fail")}
          onReset={() => { apply("two"); setStatus("idle"); }}
          onNew={() => { setChallenge((i) => (i + 1) % challenges.length); setStatus("idle"); }}
        />
      </aside>
    </div>
  );
}

import { Children, isValidElement, useCallback, useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode, type RefObject } from "react";
import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { lessonScene, type LessonPoint } from "../geometryLessonScene";
import MathExpression from "../../../components/ui/MathExpression";
import { dist, fmt, midpoint, type Vec } from "./circleMath";

export const CIRCLE_VB = { w: 560, h: 500, cx: 280, cy: 252, scale: 34 };

export function mathToSvg(p: Vec, frame = CIRCLE_VB) {
  return { x: frame.cx + p.x * frame.scale, y: frame.cy - p.y * frame.scale };
}

export function svgToMath(p: Vec, frame = CIRCLE_VB): Vec {
  return { x: (p.x - frame.cx) / frame.scale, y: (frame.cy - p.y) / frame.scale };
}

export function clientToSvg(svg: SVGSVGElement, event: PointerEvent, frame = CIRCLE_VB): Vec {
  const matrix = svg.getScreenCTM();
  if (!matrix) return { x: 0, y: 0 };
  const point = svg.createSVGPoint(); point.x = event.clientX; point.y = event.clientY;
  const local = point.matrixTransform(matrix.inverse());
  return { x: local.x, y: local.y };
}

export function useSvgDrag(onMove: (id: string, math: Vec, fine: boolean) => void, onSelect?: (id: string) => void) {
  const svgRef = useRef<SVGSVGElement>(null);
  const dragging = useRef<string | null>(null);

  const onPointerDown = useCallback((event: PointerEvent<SVGSVGElement>) => {
    const hit = (event.target as Element).closest("[data-drag]");
    if (!hit) return;
    const id = hit.getAttribute("data-drag");
    dragging.current = id;
    if (id) onSelect?.(id);
    event.currentTarget.setPointerCapture(event.pointerId);
  }, [onSelect]);

  const onPointerMove = useCallback((event: PointerEvent<SVGSVGElement>) => {
    if (!dragging.current || !svgRef.current) return;
    onMove(dragging.current, svgToMath(clientToSvg(svgRef.current, event)), event.shiftKey);
  }, [onMove]);

  const onPointerUp = useCallback(() => {
    dragging.current = null;
  }, []);

  return { svgRef, onPointerDown, onPointerMove, onPointerUp };
}

export function CircleSvg({
  children,
  ariaLabel,
  svgRef,
  unitLabel = "u",
  focused,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onKeyMove,
}: {
  children: ReactNode;
  ariaLabel: string;
  svgRef?: RefObject<SVGSVGElement>;
  unitLabel?: string;
  focused?: string | null;
  onPointerDown?: (event: PointerEvent<SVGSVGElement>) => void;
  onPointerMove?: (event: PointerEvent<SVGSVGElement>) => void;
  onPointerUp?: (event: PointerEvent<SVGSVGElement>) => void;
  onKeyMove?: (id: string, dx: number, dy: number) => void;
}) {
  const { w, h, cx, cy, scale } = CIRCLE_VB;
  const onKeyDown = (event: KeyboardEvent<SVGSVGElement>) => {
    if (!focused || !onKeyMove) return;
    const step = event.shiftKey ? 0.08 : 0.22;
    if (event.key === "ArrowLeft") { event.preventDefault(); onKeyMove(focused, -step, 0); }
    if (event.key === "ArrowRight") { event.preventDefault(); onKeyMove(focused, step, 0); }
    if (event.key === "ArrowUp") { event.preventDefault(); onKeyMove(focused, 0, step); }
    if (event.key === "ArrowDown") { event.preventDefault(); onKeyMove(focused, 0, -step); }
  };
  return (
    <GeometryLessonCanvas scene={circleLessonScene(children)} onPointChange={(id, screen) => {
      if (!onKeyMove) return;
      const original = circleLessonScene(children).construction.points.find(p => p.id === id);
      if (original) onKeyMove(id, (screen.x - original.x) / scale, (original.y - screen.y) / scale);
    }}
      ref={svgRef}
      className="clab-svg is-interactive"
      viewBox={`0 0 ${w} ${h}`}
      role="application"
      aria-label={ariaLabel}
      tabIndex={0}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerLeave={onPointerUp}
      onPointerCancel={onPointerUp}
      onKeyDown={onKeyDown}
    >
      <rect width={w} height={h} fill="#f7fbff" />
      <g stroke="#e4eef7" strokeWidth="1">
        {[-6, -4, -2, 2, 4, 6].map((n) => (
          <g key={n}>
            <line x1={cx + n * scale} y1={24} x2={cx + n * scale} y2={h - 28} />
            <line x1={36} y1={cy - n * scale} x2={w - 28} y2={cy - n * scale} />
            <text x={cx + n * scale} y={h - 10} fontSize="9" fill="#8aa0b8" textAnchor="middle">{n}{unitLabel === "cm" ? "cm" : ""}</text>
          </g>
        ))}
      </g>
      {children}
    </GeometryLessonCanvas>
  );
}

/** Adapt the declarative circle geometry; keep teaching overlays in lesson view. */
export function circleLessonScene(children: ReactNode) {
  const scene = lessonScene(CIRCLE_VB.w, CIRCLE_VB.h, mathToSvg, CIRCLE_VB.scale);
  const elements: Array<{ type: unknown; props: Record<string, unknown> }> = [];
  const visit = (nodes: ReactNode) => Children.forEach(nodes, node => {
    if (!isValidElement<Record<string, unknown>>(node)) return;
    elements.push({ type: node.type, props: node.props });
    if (node.props.children) visit(node.props.children as ReactNode);
  });
  visit(children);
  const named = elements.filter(e => e.type === DraggablePoint).map(e => ({ ...(e.props.point as Vec), id: String(e.props.dragId ?? e.props.label ?? ""), label: String(e.props.label ?? ""), color: e.props.color as string | undefined }));
  const point = (value: Vec): LessonPoint => named.find(p => dist(p, value) < 1e-7) ?? value;
  named.forEach(p => scene.point(p));
  let primaryCircle: string | undefined;
  let primary: { origin: Vec; radius: number } | undefined;
  elements.forEach(({ type, props: p }) => {
    const style = { color: p.color as string | undefined, strokeWidth: Number(p.width ?? 2.3), dashArray: p.dashed ? "6 4" : undefined };
    if (type === CircleOutline) {
      const id = scene.circle(point(p.origin as Vec), Number(p.radius), style);
      if (!primaryCircle) { primaryCircle = id; primary = { origin: p.origin as Vec, radius: Number(p.radius) }; }
    } else if (type === ChordLine || type === GhostChord) {
      scene.line(point(p.a as Vec), point(p.b as Vec), type === GhostChord ? { color: "#94a3b8", dashArray: "6 4" } : style);
    } else if (type === RadiusLine) {
      scene.line(point(p.origin as Vec), point(p.point as Vec), style);
    } else if (type === FilledTriangle) {
      scene.polygon([point(p.a as Vec), point(p.b as Vec), point(p.c as Vec)], { fill: p.color as string, color: "transparent" });
    } else if (type === TangentLine) {
      const origin = p.point as Vec, dir = p.direction as Vec;
      const k = Number(p.length ?? 4.6) / (Math.hypot(dir.x, dir.y) || 1);
      scene.line({ x: origin.x - dir.x * k, y: origin.y - dir.y * k }, { x: origin.x + dir.x * k, y: origin.y + dir.y * k }, style);
    } else if (type === ArcPath) {
      const origin = p.origin as Vec, r = Number(p.radius);
      const at = (angle: number) => ({ x: origin.x + r * Math.cos(angle), y: origin.y + r * Math.sin(angle) });
      scene.construction.arcs.push({ id: `lesson-arc-${scene.construction.arcs.length}`, center: scene.point(point(origin)), start: scene.point(point(at(Number(p.startRad)))), end: scene.point(point(at(Number(p.endRad)))), sector: Boolean(p.fill), style: { ...style, fill: p.fill as string | undefined } });
    }
  });
  if (primaryCircle && primary) {
    const radiusHandle = named.find(p => p.id === "R");
    const circle = scene.construction.circles.find(c => c.id === primaryCircle);
    if (circle && radiusHandle) circle.edge = radiusHandle.id!;
  }
  if (primaryCircle && primary) named.forEach(p => {
    if (Math.abs(dist(p, primary!.origin) - primary!.radius) < 1e-7 && p.id !== "R") scene.construction.constraints.push({ id: `on-circle-${p.id}`, type: "on-circle", point: p.id!, circle: primaryCircle! });
  });
  if (named.some(p => p.id === "M") && named.some(p => p.id === "A") && named.some(p => p.id === "B")) scene.construction.constraints.push({ id: "chord-midpoint", type: "midpoint", a: "A", b: "B", point: "M" });
  return scene.result();
}

export function CircleOutline({ origin, radius, dashed, color = "#08b9dd" }: { origin: Vec; radius: number; dashed?: boolean; color?: string }) {
  const p = mathToSvg(origin);
  return <circle cx={p.x} cy={p.y} r={radius * CIRCLE_VB.scale} fill="rgba(8,185,221,.07)" stroke={color} strokeWidth="2.2" strokeDasharray={dashed ? "6 4" : undefined} />;
}

export function ChordLine({ a, b, color = "#147df2", dashed, width = 2.3 }: { a: Vec; b: Vec; color?: string; dashed?: boolean; width?: number }) {
  const A = mathToSvg(a);
  const B = mathToSvg(b);
  return <line x1={A.x} y1={A.y} x2={B.x} y2={B.y} stroke={color} strokeWidth={width} strokeDasharray={dashed ? "6 4" : undefined} />;
}

export function RadiusLine({ origin, point, color = "#147df2" }: { origin: Vec; point: Vec; color?: string }) {
  const O = mathToSvg(origin);
  const P = mathToSvg(point);
  return <line x1={O.x} y1={O.y} x2={P.x} y2={P.y} stroke={color} strokeWidth="1.8" />;
}

export function TangentLine({ point, direction, length = 4.6, color = "#f59e0b" }: { point: Vec; direction: Vec; length?: number; color?: string }) {
  const dirLen = Math.hypot(direction.x, direction.y) || 1;
  const ux = (direction.x / dirLen) * length;
  const uy = (direction.y / dirLen) * length;
  const a = mathToSvg({ x: point.x - ux, y: point.y - uy });
  const b = mathToSvg({ x: point.x + ux, y: point.y + uy });
  return <line x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke={color} strokeWidth="2.2" />;
}

export function FilledTriangle({ a, b, c, color }: { a: Vec; b: Vec; c: Vec; color: string }) {
  const A = mathToSvg(a); const B = mathToSvg(b); const C = mathToSvg(c);
  return <polygon points={`${A.x},${A.y} ${B.x},${B.y} ${C.x},${C.y}`} fill={color} stroke="none" />;
}

export function ArcPath({
  origin, radius, startRad, endRad, color = "#8b45f4", fill, width = 3, dashed,
}: {
  origin: Vec; radius: number; startRad: number; endRad: number; color?: string; fill?: string; width?: number; dashed?: boolean;
}) {
  const sweep = ((endRad - startRad) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2);
  const large = sweep > Math.PI ? 1 : 0;
  const start = mathToSvg({ x: origin.x + radius * Math.cos(startRad), y: origin.y + radius * Math.sin(startRad) });
  const end = mathToSvg({ x: origin.x + radius * Math.cos(endRad), y: origin.y + radius * Math.sin(endRad) });
  const r = radius * CIRCLE_VB.scale;
  const o = mathToSvg(origin);
  if (fill) {
    return <path d={`M ${o.x} ${o.y} L ${start.x} ${start.y} A ${r} ${r} 0 ${large} 0 ${end.x} ${end.y} Z`} fill={fill} stroke="none" />;
  }
  return <path d={`M ${start.x} ${start.y} A ${r} ${r} 0 ${large} 0 ${end.x} ${end.y}`} fill="none" stroke={color} strokeWidth={width} strokeDasharray={dashed ? "6 4" : undefined} />;
}

export function AngleMarker({ vertex, from, to, radius = 0.72, color = "#8b45f4" }: { vertex: Vec; from: Vec; to: Vec; radius?: number; color?: string }) {
  const a0 = Math.atan2(from.y - vertex.y, from.x - vertex.x);
  const a1 = Math.atan2(to.y - vertex.y, to.x - vertex.x);
  return <ArcPath origin={vertex} radius={radius} startRad={a0} endRad={a1} color={color} />;
}

export function RightAngleMarker({ origin, point, tangentDir }: { origin: Vec; point: Vec; tangentDir: Vec }) {
  const n = { x: point.x - origin.x, y: point.y - origin.y };
  const nLen = Math.hypot(n.x, n.y) || 1;
  const tLen = Math.hypot(tangentDir.x, tangentDir.y) || 1;
  const s = 0.42;
  const nx = (n.x / nLen) * s;
  const ny = (n.y / nLen) * s;
  const tx = (tangentDir.x / tLen) * s;
  const ty = (tangentDir.y / tLen) * s;
  const p1 = mathToSvg({ x: point.x - nx, y: point.y - ny });
  const p2 = mathToSvg({ x: point.x - nx + tx, y: point.y - ny + ty });
  const p3 = mathToSvg({ x: point.x + tx, y: point.y + ty });
  return <polyline points={`${p1.x},${p1.y} ${p2.x},${p2.y} ${p3.x},${p3.y}`} fill="none" stroke="#10b981" strokeWidth="2" />;
}

export function LengthBadge({ a, b, text, color = "#0f2747", offsetY = 0 }: { a: Vec; b: Vec; text: string; color?: string; offsetY?: number }) {
  const m = mathToSvg(midpoint(a, b));
  const w = Math.max(36, text.length * 9);
  return (
    <g>
      <rect x={m.x - w / 2} y={m.y - 24 + offsetY} width={w} height="24" rx="7" fill="#ffffffee" stroke="#dce7f4" />
      <text x={m.x} y={m.y - 7 + offsetY} fontSize="13" fontWeight="800" fill={color} textAnchor="middle">{text}</text>
    </g>
  );
}

export function GhostChord({ a, b }: { a: Vec; b: Vec; label?: string }) {
