            <code>{measures.formsM.standard}</code>
            {parallel ? <span className="coord-warn">No unique intersection — the lines are parallel.</span> : <span>→ P ( {fmtPretty(measures.P!.x)}, {fmtPretty(measures.P!.y)} )</span>}
