  useEffect(() => onGeoSession(() => setLargeLabels(readGeoSession().largeLabels)), []);
  const [compact] = useStudioState("geometryLabUx:GeometryLabShell:compact", false);
  const [inspectorOpen, setInspectorOpen] = useStudioState("geometryLabUx:GeometryLabShell:inspectorOpen", false);
  const [helpOpen, setHelpOpen] = useState(false);
  const [status, setStatus] = useState("");
  const [, setUnitHint] = useStudioState<"deg" | "rad">("geometryLabUx:GeometryLabShell:unitHint", "deg");
  const [highlight, setHighlight] = useStudioState<string | null>("geometryLabUx:GeometryLabShell:highlight", null);
  const [challengeFlash, setChallengeFlash] = useStudioState("geometryLabUx:GeometryLabShell:challengeFlash", false);

  const announce = useCallback((text: string) => {
    setStatus(text);
  }, []);

  const toggleLargeLabels = useCallback(() => {
    setLargeLabels((value) => {
      const next = !value;
      writeGeoSession({ largeLabels: next });
      return next;
    });
  }, []);

  const index = Math.max(0, modes.findIndex((item) => item.id === mode));
  const go = useCallback((nextIndex: number) => {
    const wrapped = (nextIndex + modes.length) % modes.length;
    const next = modes[wrapped];
    if (next) onChange(next.id);
  }, [modes, onChange]);

  const copyText = async (text: string, ok: string) => {
    try {
      await navigator.clipboard.writeText(text);
      announce(ok);
    } catch {
      announce("Clipboard is blocked in this browser. Copy the URL from the address bar.");
    }
  };

  const copyMeasurements = useCallback(() => {
    const nodes = Array.from(document.querySelectorAll<HTMLElement>(lab === "triangles" ? ".tri-metric" : ".poly-measure"));
    const lines = nodes.map((row) => row.innerText.replace(/\s+/g, " ").trim()).filter(Boolean);
    void copyText(lines.join("\n") || liveSummary, "Live measurements copied.");
  }, [announce, lab, liveSummary]);

  const shareSetup = useCallback(() => {
    const href = typeof window === "undefined" ? "" : window.location.href;
    void copyText(href, "Shareable lab URL copied.");
  }, [announce]);

  const fit = () => {
    setZoom(1);
    setPanX(0);
    setPanY(0);
  };

  useEffect(() => {
    const onKey = (event: globalThis.KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (target && /input|textarea|select/i.test(target.tagName)) return;
      if (event.key === "?" || (event.shiftKey && event.key === "/")) {
        event.preventDefault();
        setHelpOpen((open) => !open);
        return;
      }
      if (event.key === "Escape") {
        setHelpOpen(false);
        return;
      }
      if (event.key >= "1" && event.key <= "5") {
        const next = modes[Number(event.key) - 1];
        if (next) onChange(next.id);
        return;
      }
      if (lab === "polygons" && event.key === "ArrowRight") { event.preventDefault(); go(index + 1); }
      if (lab === "polygons" && event.key === "ArrowLeft") { event.preventDefault(); go(index - 1); }
      if (event.key === "=" || event.key === "+") setZoom((value) => Math.min(2.2, Math.round((value + 0.1) * 10) / 10));
      if (event.key === "-" || event.key === "_") setZoom((value) => Math.max(0.7, Math.round((value - 0.1) * 10) / 10));
      if (event.key === "0") fit();
      if (event.key.toLowerCase() === "c" && !event.metaKey && !event.ctrlKey) copyMeasurements();
      if (event.key.toLowerCase() === "s" && !event.metaKey && !event.ctrlKey) {
        event.preventDefault();
        shareSetup();
      }
      if (event.key.toLowerCase() === "l") toggleLargeLabels();
      if (event.key.toLowerCase() === "h") setContrast((value) => !value);
      if (event.key.toLowerCase() === "i") setInspectorOpen((value) => !value);
      if (lab === "polygons" && event.key.toLowerCase() === "d") setUnitHint((value) => (value === "deg" ? "rad" : "deg"));
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [copyMeasurements, go, index, lab, modes, onChange, shareSetup, toggleLargeLabels]);

  const onTabKey = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key !== "ArrowRight" && event.key !== "ArrowLeft" && event.key !== "Home" && event.key !== "End") return;
    const target = event.target as HTMLElement;
    if (!target.closest("[role='tablist']")) return;
    event.preventDefault();
    if (event.key === "ArrowRight") go(index + 1);
    if (event.key === "ArrowLeft") go(index - 1);
    if (event.key === "Home") go(0);
    if (event.key === "End") go(modes.length - 1);
  };

  const classes = [
    "geo-lab-ux",
    `geo-lab-ux--${lab}`,
    contrast ? "is-contrast" : "",
    largeLabels ? "has-large-labels" : "",
    compact ? "is-compact" : "",
    inspectorOpen ? "is-inspector-open" : "",
    reducedMotion ? "is-reduced-motion" : "",
  ].filter(Boolean).join(" ");

  const setPan = useCallback((x: number, y: number) => {
    setPanX(x);
    setPanY(y);
  }, []);

  const ui = useMemo<GeoLabUi>(() => ({
    zoom, panX, panY, setPan, highlight, setHighlight, announce, challengeFlash, setChallengeFlash,
  }), [announce, challengeFlash, highlight, panX, panY, setPan, zoom]);

  return (
    <GeoLabUiContext.Provider value={ui}>
      <div className={classes} data-lab={lab} data-lab-mode={mode} data-zoom={zoom} data-pan-x={panX} data-pan-y={panY} style={{ ["--geo-zoom" as string]: String(zoom) }}>
        <a className="geo-skip" href="#lab-canvas">Skip to figure</a>
        <p className="geo-live-summary vis-hidden" aria-live="polite">{liveSummary}</p>
        <div className="geo-lab-body" onKeyDown={onTabKey}>
          {children}
        </div>
        <aside className="geo-related geo-next-rail" aria-label="Related labs">
          {RELATED[lab].map((item) => (
            <Link key={item.to} to={item.to}>
              <b>{item.label}</b>
              <small>{item.why}</small>
            </Link>
          ))}
        </aside>
        <p className="geo-legend" id="geo-legend">
          {lab === "triangles"
            ? "Hover a measurement to highlight the matching side or angle. Cyan sides · violet ∠B · amber ∠C · teal height."
            : "Legend: blue sides · violet interiors · amber exteriors · teal apothem"}
        </p>
        {helpOpen ? (
          <div className="geo-help" id={helpId} role="dialog" aria-modal="true" aria-label="Keyboard shortcuts">
            <h2>Shortcuts</h2>
            <ul>
              {SHORTCUTS[lab].map((item) => (
                <li key={item.keys}><kbd>{item.keys}</kbd> {item.action}</li>
              ))}
            </ul>
            <button type="button" onClick={() => setHelpOpen(false)}>Close</button>
          </div>
        ) : null}
        <p className="geo-status" role="status">{status}</p>
        <p className="geo-print-prompt" hidden>Find ∠C. Show your working.</p>
      </div>
    </GeoLabUiContext.Provider>
  );
}

export function shapesExplorerPathFromSolidMode(mode: string | null | undefined): string {
  const token = (mode ?? "").trim().toLowerCase().replace(/[_+]+/g, " ").replace(/\s+/g, " ");
  const map: Record<string, string> = {
    prisms: "triangular-prism",
    prism: "triangular-prism",
    pyramids: "square-pyramid",
    pyramid: "square-pyramid",
    cylinders: "cylinder",
    cone: "cone",
    cones: "cone",
    sphere: "sphere",
    spheres: "sphere",
    nets: "cube",
    "cross-sections": "cube",
    "cross sections": "cube",
    cube: "cube",
    cuboid: "cuboid",
    tetrahedron: "tetrahedron",
  };
  const shape = map[token];
  return shape ? `/shapes?shape=${shape}` : "/shapes";
}

import { Children, isValidElement, type ReactNode } from "react";
import { type LessonScene } from "./geometryLessonScene";

/** Carry visible teaching overlays into the editable snapshot without executing components. */
export function withLessonOverlays(scene: LessonScene, children: ReactNode): LessonScene {
  const construction = { ...scene.construction, points: [...scene.construction.points], lines: [...scene.construction.lines], circles: [...scene.construction.circles], polygons: [...scene.construction.polygons] };
  let serial = 0;
  const point = (x: number, y: number, label = "", color = "#64748b") => {
    const existing = construction.points.find(p => Math.hypot(p.x - x, p.y - y) < 1e-6);
    if (existing) return existing.id;
    const id = `overlay-point-${++serial}`;
    construction.points.push({ id, x, y, label, style: { color, size: label ? 5 : 0, labelMode: label ? "name" : "hidden" } });
    return id;
  };
  const visit = (nodes: ReactNode) => Children.forEach(nodes, node => {
    if (!isValidElement(node)) return;
    const p = node.props as Record<string, any>;
    const name = typeof node.type === "function" ? node.type.name : node.type;
    const project = (v: { x: number; y: number }) => p.plane ? { x: p.plane.ox + v.x * p.plane.unit, y: p.plane.oy - v.y * p.plane.unit } : v;
    if ((name === "SolidLine" || name === "DashedLine") && p.a && p.b) {
      const a = project(p.a), b = project(p.b);
      construction.lines.push({ id: `overlay-line-${++serial}`, a: point(a.x, a.y), b: point(b.x, b.y), style: { color: p.color ?? "#94a3b8", dashArray: name === "DashedLine" ? "6 4" : undefined } });
    } else if (name === "line" && [p.x1,p.y1,p.x2,p.y2].every(Number.isFinite)) {
      construction.lines.push({ id: `overlay-line-${++serial}`, a: point(p.x1,p.y1), b: point(p.x2,p.y2), style: { color: p.stroke ?? "#64748b", dashArray: p.strokeDasharray } });
    } else if (name === "polygon" && typeof p.points === "string") {
      const vertices = p.points.trim().split(/\s+/).map((pair: string) => pair.split(",").map(Number));
      if (vertices.length >= 3 && vertices.every((v: number[]) => v.length === 2 && v.every(Number.isFinite))) {
        const ids = vertices.map(([x,y]: number[]) => point(x,y));
        if (!construction.polygons.some(poly => poly.points.length === ids.length && poly.points.every((id,i) => id === ids[i]))) construction.polygons.push({ id: `overlay-polygon-${++serial}`, points: ids, style: { color: p.stroke ?? "#147df2", fill: p.fill?.startsWith("url(") ? "rgba(20,125,242,.12)" : p.fill } });
      }
    } else if (name === "CenterDot" && p.p) {
      const v = project(p.p); point(v.x, v.y, p.label, p.color);
    } else if (name === "circle" && Number.isFinite(p.cx) && Number.isFinite(p.cy) && Number.isFinite(p.r) && p.r > 8) {
      const center = point(p.cx, p.cy), edge = point(p.cx + p.r, p.cy);
      if (!construction.circles.some(c => c.center === center && c.edge === edge)) construction.circles.push({ id: `overlay-circle-${++serial}`, center, edge, style: { color: p.stroke ?? "#147df2", fill: p.fill === "none" ? undefined : p.fill, dashArray: p.strokeDasharray } });
    }
    if (p.children) visit(p.children);
  });
  visit(children);
  return { ...scene, construction };
}

import GeometryEmbeddedGraph from "../GeometryEmbeddedGraph";
