const PX = 26;
const PAD = 56;
const VIEW = { w: 700, h: 560 };
const MODE_ICON: Record<MeasureModeId, ReactNode> = {
  length: <Ruler size={15} />,
  angle: <Triangle size={15} />,
  area: <Square size={15} />,
  perimeter: <CircleDashed size={15} />,
  scale: <Scaling size={15} />,
  error: <AlertTriangle size={15} />,
};

function toPx(n: number) {
  return PAD + n * PX;
}

function worldFromSvg(x: number, y: number) {
  return { x: (x - PAD) / PX, y: (y - PAD) / PX };
}

function cornerTick(x: number, y: number, dx: 1 | -1, dy: 1 | -1, color: string) {
  const px = toPx(x);
  const py = toPx(y);
  const s = 9;
  return <path d={`M ${px + dx * s} ${py} H ${px} V ${py + dy * s}`} fill="none" stroke={color} strokeWidth="1.6" />;
}

export default function MeasurementLab({ page }: { page: StudioMockupPage }) {
  const { mode, panel, setMode, setPanel } = useMeasurementWorkspace();
  const [rects, setRects] = useStudioState<AaRect[]>("MeasurementLab:MeasurementLab:rects", defaultRects);
  const [selected, setSelected] = useStudioState("MeasurementLab:MeasurementLab:selected", "r1");
  const [unit, setUnit] = useStudioState<UnitId>("MeasurementLab:MeasurementLab:unit", "cm");
  const [precision, setPrecision] = useStudioState("MeasurementLab:MeasurementLab:precision", 0.01);
  const [snap, setSnap] = useStudioState<"grid" | "point" | "off">("MeasurementLab:MeasurementLab:snap", "grid");
  const [rulers, setRulers] = useStudioState("MeasurementLab:MeasurementLab:rulers", true);
  const [showDecomp, setShowDecomp] = useState(true);
  const [showDims, setShowDims] = useState(true);
  const [showProtractor, setShowProtractor] = useState(true);
  const [showGrid, setShowGrid] = useState(true);
  const [showConstruction, setShowConstruction] = useState(false);
  const [decompose, setDecompose] = useStudioState<"auto" | "manual">("MeasurementLab:MeasurementLab:decompose", "auto");
  const [scaleK, setScaleK] = useStudioState("MeasurementLab:MeasurementLab:scaleK", 1);
  const [zoom, setZoom] = useStudioState("MeasurementLab:MeasurementLab:zoom", 1);
  const [tool, setTool] = useStudioState<"select" | "measure" | "shape" | "text">("MeasurementLab:MeasurementLab:tool", "select");
  const [headerHost, setHeaderHost] = useStudioState<HTMLElement | null>("MeasurementLab:MeasurementLab:headerHost", null);
  const [hoverId, setHoverId] = useState<string | null>(null);
  const [convKind, setConvKind] = useStudioState<"area" | "length">("MeasurementLab:MeasurementLab:convKind", "area");
  const drag = useRef<Handle | { type: "move"; rectId: string; x0: number; y0: number; rx: number; ry: number } | null>(null);

  useEffect(() => { setHeaderHost(document.getElementById("msk-lab-tools")); }, []);

  const display = useMemo(() => scaleRects(rects, scaleK), [rects, scaleK]);
  const areaCm = unionArea(display);
  const periCm = unionPerimeter(display);
  const parts = display.map((r) => ({ ...r, area: rectArea(r), peri: rectPerimeter(r) }));
  const area = convertAreaFromCm2(areaCm, unit);
  const peri = convertFromCm(periCm, unit);
  const absErr = convertFromCm(areaUncertainty(areaCm, periCm, precision), unit);
  const rel = relativeError(area, convertAreaFromCm2(areaUncertainty(areaCm, periCm, precision), unit));
  const snapStep = snap === "grid" ? 0.2 : 0;
  const selectedRect = display.find((r) => r.id === selected) ?? display[0];

  const onDown = (event: ReactPointerEvent<SVGSVGElement>) => {
    const svg = event.currentTarget;
    const pt = svg.createSVGPoint();
    pt.x = event.clientX;
    pt.y = event.clientY;
    const ctm = svg.getScreenCTM();
    if (!ctm) return;
    const p = pt.matrixTransform(ctm.inverse());
    const { x, y } = worldFromSvg(p.x, p.y);
    const handle = handlesFor(display).find((h) => Math.hypot(h.x - x, h.y - y) < 0.28);
    if (handle && tool !== "text") {
      drag.current = handle;
      setSelected(handle.rectId);
      svg.setPointerCapture(event.pointerId);
      return;
    }
    const hit = hitRect(display, x, y);
    setSelected(hit?.id ?? "");
    if (hit && (tool === "select" || tool === "measure")) {
      drag.current = { type: "move", rectId: hit.id, x0: x, y0: y, rx: hit.x, ry: hit.y };
      svg.setPointerCapture(event.pointerId);
    }
  };

  const onMove = (event: ReactPointerEvent<SVGSVGElement>) => {
    const svg = event.currentTarget;
    const pt = svg.createSVGPoint();
    pt.x = event.clientX;
    pt.y = event.clientY;
    const ctm = svg.getScreenCTM();
    if (!ctm) return;
    const p = pt.matrixTransform(ctm.inverse());
    const { x, y } = worldFromSvg(p.x, p.y);
    const handle = handlesFor(display).find((h) => Math.hypot(h.x - x, h.y - y) < 0.28);
    setHoverId(handle?.rectId ?? hitRect(display, x, y)?.id ?? null);
    if (!drag.current) return;
    const k = scaleK || 1;
    const origin = { x: 2, y: 1.8 };
    const session = drag.current;
    setRects((prev) => prev.map((r) => {
      if (r.id !== session.rectId) return r;
      if ("type" in session && session.type === "move") {
        const nx = session.rx + (x - session.x0) / k;
        const ny = session.ry + (y - session.y0) / k;
        const sx = snapStep > 0 ? Math.round(nx / snapStep) * snapStep : nx;
        const sy = snapStep > 0 ? Math.round(ny / snapStep) * snapStep : ny;
        return { ...r, x: sx, y: sy };
      }
      if (!("corner" in session)) return r;
      return resizeRect(r, session.corner, origin.x + (x - origin.x) / k, origin.y + (y - origin.y) / k, snapStep);
    }));
  };

  const header = (
    <>
      <label className="mlab-head-field">
        <span className="sr-only">Unit</span>
        <select aria-label="Unit" value={unit} onChange={(e) => setUnit(e.target.value as UnitId)}>
          <option value="mm">mm</option>
          <option value="cm">cm</option>
          <option value="m">m</option>
          <option value="in">in</option>
        </select>
      </label>
      <label className="mlab-head-field">
        <span className="sr-only">Precision</span>
        <select aria-label="Precision" value={String(precision)} onChange={(e) => setPrecision(Number(e.target.value))}>
          <option value="0.1">Precision: 0.1</option>
          <option value="0.01">Precision: 0.01</option>
          <option value="0.001">Precision: 0.001</option>
        </select>
      </label>
    </>
  );

  const dim = (value: number, x1: number, y1: number, x2: number, y2: number, side: "top" | "bottom" | "left" | "right", gap = 18, labelAt?: { x: number; y: number }) => {
    const ax = toPx(x1);
    const ay = toPx(y1);
    const bx = toPx(x2);
    const by = toPx(y2);
    const ox = side === "left" ? -gap : side === "right" ? gap : 0;
    const oy = side === "top" ? -gap : side === "bottom" ? gap : 0;
    const mx = labelAt ? toPx(labelAt.x) : (ax + bx) / 2 + ox + (side === "left" ? -16 : side === "right" ? 16 : 0);
    const my = labelAt ? toPx(labelAt.y) : (ay + by) / 2 + oy + (side === "top" ? -2 : side === "bottom" ? 12 : 4);
    return (
      <g className="mlab-dim">
        <line x1={ax} y1={ay} x2={ax + ox} y2={ay + oy} />
        <line x1={bx} y1={by} x2={bx + ox} y2={by + oy} />
        <line x1={ax + ox} y1={ay + oy} x2={bx + ox} y2={by + oy} />
        <circle cx={ax + ox} cy={ay + oy} r="2.2" fill="#f59e0b" />
        <circle cx={bx + ox} cy={by + oy} r="2.2" fill="#f59e0b" />
        <text x={mx} y={my} textAnchor="middle" paintOrder="stroke" stroke="#fff" strokeWidth="3">{fmt(convertFromCm(value, unit), precision)} {unit}</text>
      </g>
    );
  };

  const protractor = (cx: number, cy: number, r: number) => {
    const ticks = Array.from({ length: 19 }, (_, i) => {
      const deg = i * 10;
      const rad = (deg * Math.PI) / 180;
      const inner = deg % 30 === 0 ? r - 16 : r - 9;
      const x1 = cx + r * Math.cos(Math.PI - rad);
      const y1 = cy - r * Math.sin(rad);
      const x2 = cx + inner * Math.cos(Math.PI - rad);
      const y2 = cy - inner * Math.sin(rad);
      const lx = cx + (r - 26) * Math.cos(Math.PI - rad);
      const ly = cy - (r - 26) * Math.sin(rad);
      return (
        <g key={deg}>
          <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="#64748b" strokeWidth={deg % 30 === 0 ? 1.4 : 0.8} />
          {deg % 30 === 0 ? <text x={lx} y={ly + 3} textAnchor="middle" fontSize="8" fill="#64748b">{deg}</text> : null}
        </g>
      );
    });
    const ray = (135 * Math.PI) / 180;
    return (
      <g className="mlab-protractor">
        <path d={`M ${cx - r} ${cy} A ${r} ${r} 0 0 1 ${cx + r} ${cy} L ${cx - r} ${cy} Z`} fill="#fff" fillOpacity="0.92" stroke="#94a3b8" />
        {ticks}
        <line x1={cx - r} y1={cy} x2={cx + r} y2={cy} stroke="#94a3b8" />
        <line x1={cx} y1={cy} x2={cx + (r - 8) * Math.cos(Math.PI - ray)} y2={cy - (r - 8) * Math.sin(ray)} stroke="#f59e0b" strokeWidth="2" />
        <circle cx={cx} cy={cy} r="3" fill="#f59e0b" />
        <text x={cx + 18} y={cy - 22} fill="#f59e0b" fontSize="11" fontWeight="800">135.00°</text>
      </g>
    );
  };

  const r1 = display[0]!;
  const r2 = display[1]!;
  const r3 = display[2]!;
  const r4 = display[3]!;

  return (
    <div className="mlab">
      {headerHost ? createPortal(header, headerHost) : <div className="mlab-inline-head">{header}</div>}
      <nav className="mlab-modes" aria-label="Measurement modes">
        {MEASURE_MODES.map((item) => (
          <button key={item.id} type="button" className={mode === item.id ? "is-on" : ""} onClick={() => setMode(item.id)}>
            {MODE_ICON[item.id]}
            {item.label}
          </button>
        ))}
      </nav>

      <div className="mlab-workspace">
        <aside className="mlab-card" aria-label="Measurement controls">
          <h2>Measurement controls</h2>
          <p className="mlab-kicker">Select</p>
          <div className="mlab-icon-row">
            <button type="button" className={tool === "select" ? "is-on" : ""} aria-label="Select" onClick={() => setTool("select")}><MousePointer2 size={16} /></button>
            <button type="button" className={tool === "measure" ? "is-on" : ""} aria-label="Measure" onClick={() => setTool("measure")}><Pencil size={16} /></button>
            <button type="button" className={tool === "shape" ? "is-on" : ""} aria-label="Shape" onClick={() => setTool("shape")}><Home size={16} /></button>
            <button type="button" className={tool === "text" ? "is-on" : ""} aria-label="Label" onClick={() => setTool("text")}><Type size={16} /></button>
          </div>
          <p className="mlab-kicker">Snap</p>
          <div className="mlab-icon-row">
            <button type="button" className={snap === "grid" ? "is-on" : ""} aria-label="Snap to grid" onClick={() => setSnap("grid")}><Grid3X3 size={16} /></button>
            <button type="button" className={snap === "point" ? "is-on" : ""} aria-label="Snap to point" onClick={() => setSnap("point")}><Magnet size={16} /></button>
            <button type="button" className={snap === "off" ? "is-on" : ""} aria-label="No snap" onClick={() => setSnap("off")}><Spline size={16} /></button>
          </div>
          <label className="mlab-toggle">
            <span>Show rulers</span>
            <input type="checkbox" checked={rulers} onChange={(e) => setRulers(e.target.checked)} />
          </label>
          <p className="mlab-kicker">Display</p>
          <label className="mlab-check"><input type="checkbox" checked={showDecomp} onChange={(e) => setShowDecomp(e.target.checked)} /> Decomposition</label>
          <label className="mlab-check"><input type="checkbox" checked={showDims} onChange={(e) => setShowDims(e.target.checked)} /> Dimensions</label>
          <label className="mlab-check"><input type="checkbox" checked={showProtractor} onChange={(e) => setShowProtractor(e.target.checked)} /> Protractor</label>
          <label className="mlab-check"><input type="checkbox" checked={showGrid} onChange={(e) => setShowGrid(e.target.checked)} /> Grid</label>
          <label className="mlab-check"><input type="checkbox" checked={showConstruction} onChange={(e) => setShowConstruction(e.target.checked)} /> Construction</label>
          <p className="mlab-kicker">Decompose shape</p>
          <div className="mlab-seg">
            <button type="button" className={decompose === "auto" ? "is-on" : ""} onClick={() => setDecompose("auto")}>Auto</button>
            <button type="button" className={decompose === "manual" ? "is-on" : ""} onClick={() => setDecompose("manual")}>Manual</button>
          </div>
          {mode === "scale" ? (
            <label className="mlab-scale">
              Scale k = {fmt(scaleK, 0.01)}
              <input type="range" min={0.5} max={1.8} step={0.01} value={scaleK} onChange={(e) => setScaleK(Number(e.target.value))} />
            </label>
          ) : null}
          <button type="button" className="mlab-primary" onClick={() => {
            const step = snap === "grid" ? 0.2 : snap === "point" ? 0.1 : 0.01;
            setRects((prev) => prev.map((r) => {
              const snapN = (n: number) => Math.round(n / step) * step;
              return { ...r, x: snapN(r.x), y: snapN(r.y), w: Math.max(0.4, snapN(r.w)), h: Math.max(0.4, snapN(r.h)) };
            }));
          }}>Recalculate</button>
          <button type="button" className="mlab-ghost" onClick={() => { setRects(defaultRects()); setScaleK(1); setSelected("r1"); }}><Trash2 size={14} /> Clear All</button>
        </aside>

        <section className="mlab-stage">
          <GeometryLessonCanvas showFullWorkspace={false} pointStep={(snapStep || 0.1) * (scaleK || 1)} onPointChange={(id, point) => {
            const match = /^(.*)-([ABCD])$/.exec(id); if (!match) return;
            const world = worldFromSvg(point.x, point.y), origin = { x: 2, y: 1.8 }, k = scaleK || 1;
            const corners = { A: "nw", B: "ne", C: "se", D: "sw" } as const;
            setRects(previous => previous.map(r => r.id === match[1] ? resizeRect(r, corners[match[2] as keyof typeof corners], origin.x + (world.x-origin.x)/k, origin.y + (world.y-origin.y)/k, snapStep) : r));
          }} scene={measurementLessonScene(display, VIEW.w, VIEW.h, toPx)}
            className="mlab-svg"
            viewBox={`0 0 ${VIEW.w} ${VIEW.h}`}
            role="img"
            aria-label="Composite shape measurement canvas"
            style={{ transform: `scale(${zoom})` }}
            onPointerDown={onDown}
            onPointerMove={onMove}
            onPointerUp={() => { drag.current = null; }}
          >
            <rect width={VIEW.w} height={VIEW.h} fill="#f7fbff" />
            {showGrid ? Array.from({ length: 22 }, (_, i) => (
              <g key={i} stroke="#e6eef6">
                <line x1={toPx(i)} y1={toPx(0)} x2={toPx(i)} y2={toPx(16)} />
                <line x1={toPx(0)} y1={toPx(i)} x2={toPx(20)} y2={toPx(i)} />
              </g>
            )) : null}
            {rulers ? (
              <g className="mlab-ruler">
                {Array.from({ length: 21 }, (_, i) => (
                  <g key={`x${i}`}>
                    <line x1={toPx(i)} y1={PAD - 8} x2={toPx(i)} y2={PAD - (i % 2 === 0 ? 16 : 11)} stroke="#cbd5e1" />
                    <text x={toPx(i)} y={PAD - 20} textAnchor="middle">{i}</text>
                  </g>
                ))}
                {Array.from({ length: 17 }, (_, i) => (
                  <g key={`y${i}`}>
                    <line x1={PAD - 8} y1={toPx(i)} x2={PAD - (i % 2 === 0 ? 16 : 11)} y2={toPx(i)} stroke="#cbd5e1" />
                    <text x={PAD - 22} y={toPx(i) + 3} textAnchor="end">{i}</text>
                  </g>
                ))}
                <text x={toPx(20) + 14} y={PAD - 20}>{unit}</text>
                <text x="16" y={toPx(8)} transform={`rotate(-90 16 ${toPx(8)})`}>{unit}</text>
              </g>
            ) : null}
            {display.map((r) => (
              <g key={r.id} opacity={selected && selected !== r.id && mode === "area" ? 0.72 : 1}>
                <rect
                  x={toPx(r.x)}
                  y={toPx(r.y)}
                  width={r.w * PX}
                  height={r.h * PX}
                  fill={mode === "perimeter" ? `${r.fill}55` : r.fill}
                  stroke={selected === r.id || hoverId === r.id ? "#147df2" : r.stroke}
                  strokeWidth={mode === "perimeter" ? 3 : 2}
                />
                {cornerTick(r.x, r.y, 1, 1, r.stroke)}
                {cornerTick(r.x + r.w, r.y, -1, 1, r.stroke)}
                {cornerTick(r.x, r.y + r.h, 1, -1, r.stroke)}
                {cornerTick(r.x + r.w, r.y + r.h, -1, -1, r.stroke)}
                {showDecomp || showConstruction ? (
                  <g>
                    <circle cx={toPx(r.x + r.w / 2)} cy={toPx(r.y + r.h / 2)} r="12" fill="#fff" stroke={r.stroke} />
                    <text x={toPx(r.x + r.w / 2)} y={toPx(r.y + r.h / 2) + 4} textAnchor="middle" fontSize="11" fontWeight="800">{r.label}</text>
                  </g>
                ) : null}
              </g>
            ))}
            {showDims && (mode === "length" || mode === "scale" || mode === "error") ? (
              <g>
                {dim(r1.w + r2.w, r1.x, r1.y, r2.x + r2.w, r1.y, "top", 20)}
                {dim(r1.h, r1.x, r1.y, r1.x, r1.y + r1.h, "left", 22)}
                {dim(r2.h, r2.x + r2.w, r2.y, r2.x + r2.w, r2.y + r2.h, "right", 22)}
                {dim(r4.h, r4.x + r4.w, r4.y, r4.x + r4.w, r4.y + r4.h, "right", 22)}
                {dim(r3.w, r3.x, r3.y + r3.h, r3.x + r3.w, r3.y + r3.h, "bottom", 16)}
                {dim(r4.x + r4.w - r3.x, r3.x, r4.y + r4.h, r4.x + r4.w, r4.y + r4.h, "bottom", 36)}
                {dim(r1.w, r1.x, r1.y + r1.h, r1.x + r1.w, r1.y + r1.h, "bottom", 12, { x: r1.x + r1.w - 0.2, y: r1.y + r1.h + 0.7 })}
                {dim(r1.y + r1.h - (r2.y + r2.h), r1.x + r1.w, r2.y + r2.h, r1.x + r1.w, r1.y + r1.h, "left", 14)}
              </g>
            ) : null}
            {showProtractor ? protractor(toPx(r3.x) + 8, toPx(r3.y + r3.h) + 6, 72) : null}
            {handlesFor(display).map((h) => (
              <circle key={h.id} className="mlab-handle" cx={toPx(h.x)} cy={toPx(h.y)} r="5" fill="#f59e0b" stroke="#fff" />
            ))}
          </GeometryLessonCanvas>
          <div className="mlab-zoom">
            <button type="button" aria-label="Zoom in" onClick={() => setZoom((z) => Math.min(1.6, z + 0.1))}><ZoomIn size={16} /></button>
            <button type="button" aria-label="Zoom out" onClick={() => setZoom((z) => Math.max(0.7, z - 0.1))}><ZoomOut size={16} /></button>
            <button type="button" aria-label="Fit view" onClick={() => setZoom(1)}><Maximize2 size={16} /></button>
          </div>
        </section>

        <aside className="mlab-card mlab-inspector">
          <div className="mlab-panels" role="tablist" aria-label="Measurement inspector">
            {MEASURE_PANELS.map((item) => (
              <button key={item.id} type="button" role="tab" aria-selected={panel === item.id} className={panel === item.id ? "is-on" : ""} onClick={() => setPanel(item.id)}>
                {item.label}
              </button>
            ))}
          </div>

          {panel === "objects" ? (
            <div>
              <h2>Live object tree</h2>
              <ul className="mlab-tree">
                <li>
                  Composite shape
                  <ul>
                    {display.map((r) => (
                      <li key={r.id}>
                        <button type="button" className={selected === r.id ? "is-on" : ""} onClick={() => setSelected(r.id)}>
                          Rectangle {r.label}
                        </button>
                      </li>
                    ))}
                    <li>Outer boundary</li>
                    <li>Dimension set</li>
                  </ul>
                </li>
              </ul>
              {selectedRect ? <p className="mlab-note">Selected rectangle {selectedRect.label}: {fmt(convertFromCm(selectedRect.w, unit), precision)} × {fmt(convertFromCm(selectedRect.h, unit), precision)} {unit}.</p> : null}
            </div>
          ) : null}

          {panel === "measurements" ? (
            <div>
              <h2>Composite shape summary</h2>
              <div className="mlab-summary">
                <span>Total Area</span><strong>{fmt(area, precision)} {unit}²</strong>
                <span>Total Perimeter</span><strong>{fmt(peri, precision)} {unit}</strong>
                <span>Total Edge Length</span><strong>{fmt(peri, precision)} {unit}</strong>
              </div>
              <h2>Decomposition ({parts.length} parts)</h2>
              <table className="mlab-table">
                <thead><tr><th>#</th><th>Shape</th><th>Area ({unit}²)</th><th>Perimeter ({unit})</th></tr></thead>
                <tbody>
                  {parts.map((r) => (
                    <tr key={r.id} className={selected === r.id ? "is-on" : ""} onClick={() => setSelected(r.id)}>
                      <td><i style={{ background: r.stroke }} />{r.label}</td>
                      <td>Rectangle</td>
                      <td>{fmt(convertAreaFromCm2(r.area, unit), precision)}</td>
                      <td>{fmt(convertFromCm(r.peri, unit), precision)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <h2>Unit conversions</h2>
              <label className="mlab-kicker">
                <select aria-label="Conversion quantity" value={convKind} onChange={(e) => setConvKind(e.target.value as "area" | "length")}>
                  <option value="area">Area</option>
                  <option value="length">Length</option>
                </select>
              </label>
              {convKind === "area" ? (
                <>
                  <p className="mlab-conv">{fmt(area, precision)} {unit}² &nbsp;≡&nbsp; {fmt(convertAreaFromCm2(areaCm, "m"), 0.000001)} m²</p>
                  <p className="mlab-conv">{fmt(convertAreaFromCm2(areaCm, "mm"), 0.01)} mm² &nbsp;≡&nbsp; {fmt(convertAreaFromCm2(areaCm, "m") * 100, 0.01)} dm²</p>
                </>
              ) : (
                <>
                  <p className="mlab-conv">{fmt(peri, precision)} {unit} &nbsp;≡&nbsp; {fmt(convertFromCm(periCm, "m"), 0.000001)} m</p>
                  <p className="mlab-conv">{fmt(convertFromCm(periCm, "mm"), 0.01)} mm &nbsp;≡&nbsp; {fmt(convertFromCm(periCm, "m") * 10, 0.01)} dm</p>
                </>
              )}
              <h2>Uncertainty & error</h2>
              <div className="mlab-summary is-error">
                <span>Instrument Precision</span><strong>± {fmt(precision, precision)} {unit}</strong>
                <span>Area Uncertainty</span><strong>± {fmt(absErr, precision)} {unit}²</strong>
                <span>Perimeter Uncertainty</span><strong>± {fmt(convertFromCm(8 * precision, unit), precision)} {unit}</strong>
                <span>Relative Error</span><strong>{fmt(rel, 0.01)} %</strong>
              </div>
            </div>
          ) : null}

          {panel === "dependencies" ? (
            <div>
              <h2>Dependencies</h2>
              <p className="mlab-note">The composite region is the disjoint union of four rectangles. Outer perimeter depends on exposed edges only — shared internal edges cancel.</p>
              <svg viewBox="0 0 280 160" className="mlab-graph" aria-label="Measurement dependency graph">
                {["R1", "R2", "R3", "R4"].map((label, i) => (
                  <g key={label}>
                    <rect x={12 + (i % 2) * 80} y={12 + Math.floor(i / 2) * 54} width="64" height="32" rx="8" fill="#e8f7ff" stroke="#7dd3ea" />
                    <text x={44 + (i % 2) * 80} y={32 + Math.floor(i / 2) * 54} textAnchor="middle" fontSize="11">{label}</text>
                  </g>
                ))}
                <rect x="176" y="40" width="90" height="70" rx="10" fill="#efe4ff" stroke="#c4b5fd" />
                <text x="221" y="70" textAnchor="middle" fontSize="11">Composite</text>
                <text x="221" y="88" textAnchor="middle" fontSize="10">area + peri</text>
                <line x1="76" y1="28" x2="176" y2="60" stroke="#94a3b8" />
                <line x1="156" y1="28" x2="176" y2="60" stroke="#94a3b8" />
                <line x1="76" y1="82" x2="176" y2="90" stroke="#94a3b8" />
                <line x1="156" y1="82" x2="176" y2="90" stroke="#94a3b8" />
              </svg>
            </div>
          ) : null}

          {panel === "proof" ? (
            <div>
              <h2>Proof explanation</h2>
              <p className="mlab-goal"><b>Goal</b> Area(composite) = Σ Area(rectangles)</p>
              <p className="mlab-note"><b>Given / construction.</b> The figure is partitioned into four axis-aligned rectangles with disjoint interiors.</p>
              <p className="mlab-note"><b>Known property.</b> Area is finitely additive on non-overlapping regions: if A ∩ B has area 0, then Area(A ∪ B) = Area(A) + Area(B).</p>
              <p className="mlab-note"><b>Reasoning.</b> {fmt(area, precision)} {unit}² = {parts.map((r) => fmt(convertAreaFromCm2(r.area, unit), precision)).join(" + ")}.</p>
              <p className="mlab-ok">✓ Proven for this decomposition. Perimeter is not the sum of part perimeters, because internal edges are not on the outer boundary.</p>
              <ol className="mlab-steps">
                <li>Partition the composite into four rectangles.</li>
                <li>Compute each rectangle as width × height.</li>
                <li>Add the four areas.</li>
                <li>Outer perimeter keeps only uncovered edges.</li>
              </ol>
            </div>
          ) : null}
        </aside>
      </div>
      <GeometryEmbeddedGraph showFullWorkspace={false} activityId="measurement:area-perimeter" title="Area for a rectangle with perimeter 20" expressions={["x*(10-x) {0 <= x <= 10}", "(6,24)"]} />
      <MockupLearningStrip page={page} />
    </div>
  );
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { polygonLessonScene } from "../geometryLessonScene";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useCallback, useEffect, useMemo } from "react";
import { SliderRow } from "../../mockup/studioLabKit";
import {
  allDiagonals,
  combinations,
  diagonalCount,
  diagonalsFromVertex,
  fanDiagonals,
  fanTriangles,
  genericDiagonalIntersections,
  interiorDiagonalIntersections,
  isConvexPolygon,
  regularPolygonName,
  regularPolygonVertices,
  vertexLabel,
} from "./polygonMath";
import {
  ChallengePanel,
  Controls,
  FormulaCard,
  LivePanel,
  MeasureRow,
  PropertyCard,
  Toggle,
  VIEW,
  fmt,
  pointsAttr,
  toScreen,
  useRaf,
} from "./polygonUi";

type DiagSub = "from-vertex" | "all" | "triangulation" | "intersections";

const PALETTE = ["#147df2", "#8b45f4", "#08b9dd", "#f59e0b", "#10b981", "#ef4444", "#6366f1", "#0f766e"];

export default function DiagonalsLab({ pulse = "observe" }: { pulse?: string }) {
  const [n, setN] = useStudioState("DiagonalsLab:DiagonalsLab:n", 8);
  const [vertex, setVertex] = useStudioState("DiagonalsLab:DiagonalsLab:vertex", 0);
  const [sub, setSub] = useStudioState<DiagSub>("DiagonalsLab:DiagonalsLab:sub", "from-vertex");
  const [animate, setAnimate] = useStudioState("DiagonalsLab:DiagonalsLab:animate", true);
  const [progress, setProgress] = useStudioState("DiagonalsLab:DiagonalsLab:progress", 1);
  const [colorByVertex, setColorByVertex] = useStudioState("DiagonalsLab:DiagonalsLab:colorByVertex", true);
  const [labelHits, setLabelHits] = useStudioState("DiagonalsLab:DiagonalsLab:labelHits", false);

  const verts = useMemo(() => regularPolygonVertices(n, 3.6, 0), [n]);
  const screen = verts.map((p) => toScreen(p, 50));
  const fromV = diagonalsFromVertex(n);
  const total = diagonalCount(n);
  const diagsFrom = fanDiagonals(verts, vertex);
  const all = allDiagonals(verts);
  const triangles = fanTriangles(verts, vertex);
  const hits = useMemo(() => interiorDiagonalIntersections(verts), [verts]);
  const convex = isConvexPolygon(verts);

  const step = useCallback((dt: number) => {
    setProgress((value) => Math.min(1, value + dt * 0.00045));
  }, []);
  useRaf(animate && progress < 1, step);

  const shownFrom = Math.max(0, Math.round(progress * fromV));
  const shownAll = Math.max(0, Math.round(progress * all.length));
  const shownTri = Math.max(0, Math.round(progress * triangles.length));

  useEffect(() => {
    if (pulse === "try") { setSub("all"); setProgress(0.08); setAnimate(true); }
    if (pulse === "challenge") { setN(8); setSub("from-vertex"); }
    if (pulse === "observe") setSub("from-vertex");
    if (pulse === "understand") setSub("triangulation");
  }, [pulse]);

  return (
    <div className="poly-lab poly-lab--diagonals">
      <Controls title="Diagonals">
        <div className="poly-sub">
          {([["from-vertex", "From one vertex"], ["all", "All diagonals"], ["triangulation", "Triangulation"], ["intersections", "Intersections"]] as const).map(([id, label]) => (
            <button key={id} type="button" className={sub === id ? "active" : ""} onClick={() => { setSub(id); setProgress(0.08); }}>{label}</button>
          ))}
        </div>
        <SliderRow label="Sides n" value={n} min={3} max={16} step={1} onChange={(value) => { setN(value); setVertex((v) => Math.min(v, value - 1)); setProgress(0.08); }} />
        <SliderRow label="Selected vertex" value={vertex} min={0} max={n - 1} step={1} onChange={setVertex} />
        <Toggle checked={animate} onChange={(on) => { setAnimate(on); if (on) setProgress(0.08); }}>Animate drawing</Toggle>
        <Toggle checked={colorByVertex} onChange={setColorByVertex}>Color by vertex</Toggle>
        <Toggle checked={labelHits} onChange={setLabelHits}>Label intersections</Toggle>
        <button type="button" className="poly-ghost" onClick={() => setProgress(0.08)}>Replay animation</button>
      </Controls>

      <section className="msk-panel msk-canvas poly-stage">
        <GeometryLessonCanvas scene={polygonLessonScene(VIEW.w, VIEW.h, [screen])} className="msk-graph poly-svg" viewBox={`0 0 ${VIEW.w} ${VIEW.h}`} role="img" aria-label="Diagonals explorer">
          <rect width={VIEW.w} height={VIEW.h} fill="none" />
          <polygon points={pointsAttr(screen)} fill="rgba(20,125,242,.07)" stroke="#147df2" strokeWidth="2.2" />
          {sub === "from-vertex" ? diagsFrom.slice(0, shownFrom).map((line, i) => {
            const a = toScreen(line[0], 50);
            const b = toScreen(line[1], 50);
            return <line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke={PALETTE[vertex % PALETTE.length]} strokeWidth="2" />;
          }) : null}
          {sub === "all" ? all.slice(0, shownAll).map((line, i) => {
            const a = toScreen(line[2], 50);
            const b = toScreen(line[3], 50);
            const color = colorByVertex ? PALETTE[line[0] % PALETTE.length] : "#8b45f4";
            const duplicate = progress > 0.72;
            return <line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke={color} strokeOpacity={duplicate ? 0.85 : 0.4} strokeWidth={duplicate ? 1.6 : 2.4} />;
          }) : null}
          {sub === "triangulation" ? triangles.slice(0, shownTri).map((tri, i) => (
            <polygon key={i} points={pointsAttr(tri.map((p) => toScreen(p, 50)))} fill={`rgba(139,69,244,${0.1 + i * 0.05})`} stroke="#8b45f4" />
          )) : null}
          {sub === "triangulation" ? fanDiagonals(verts, vertex).map((line, i) => {
            const a = toScreen(line[0], 50);
            const b = toScreen(line[1], 50);
            return <line key={`td${i}`} x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke="#8b45f4" strokeDasharray="5 4" />;
          }) : null}
          {sub === "intersections" ? all.map((line, i) => {
            const a = toScreen(line[2], 50);
            const b = toScreen(line[3], 50);
            return <line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke="#94a3b8" />;
          }) : null}
          {sub === "intersections" ? hits.map((p, i) => {
            const s = toScreen(p, 50);
            return (
              <g key={i}>
                <circle cx={s.x} cy={s.y} r="3.5" fill="#f59e0b" />
                {labelHits ? <text x={s.x + 5} y={s.y - 5} fontSize="9" fill="#b45309">{i + 1}</text> : null}
              </g>
            );
          }) : null}
          {screen.map((p, i) => (
            <g key={i}>
              <circle cx={p.x} cy={p.y} r={i === vertex ? 8 : 5} fill={i === vertex ? "#8b45f4" : "#08b9dd"} stroke="#fff" />
              <text x={p.x + 8} y={p.y - 8} fontSize="11" fontWeight="800">{vertexLabel(i)}</text>
            </g>
          ))}
          <text x="20" y="28" fontSize="14" fontWeight="800" fill="#0f172a">
            {sub === "from-vertex" ? `Diagonals from ${vertexLabel(vertex)}` : sub === "all" ? "Every diagonal counted twice, then halved" : sub === "triangulation" ? "Fan triangulation" : "Interior intersections"}
          </text>
        </GeometryLessonCanvas>
      </section>

      <LivePanel title="Diagonal counts">
        <MeasureRow color="#8b45f4" label={`From ${vertexLabel(vertex)}`} value={fromV} />
        <MeasureRow color="#147df2" label="Total diagonals" value={total} />
        <MeasureRow color="#8b45f4" label="Fan triangles" value={n - 2} />
        <MeasureRow color="#0f766e" label="Fan diagonals" value={n - 3} />
        <FormulaCard title="Counting">
          Each vertex joins n − 3 non-adjacent vertices, giving n(n − 3) connections. Each diagonal has two ends, so total = n(n − 3)/2.
        </FormulaCard>
        <FormulaCard title="Fan triangulation">
          From one vertex, n − 3 diagonals create n − 2 triangles. Pentagon: 2 diagonals, 3 triangles. Octagon: {fromV} diagonals from one vertex.
        </FormulaCard>
        {sub === "intersections" ? (
          <>
            <MeasureRow color="#f59e0b" label="Drawn crossings" value={hits.length} />
            <MeasureRow color="#f59e0b" label="C(n,4) generic" value={genericDiagonalIntersections(n)} />
            <p className="poly-warn">
              Generic convex polygon — no three diagonals concurrent. Regular polygons can have extra concurrencies, so drawn crossings ({hits.length}) may be fewer than C({n},4) = {combinations(n, 4)}.
            </p>
          </>
        ) : null}
        <PropertyCard title="Networks">
          Diagonals are the bracing of a polygon frame and the edges of a complete graph minus the boundary cycle — used in meshes and structural trusses.
        </PropertyCard>
        <p className="poly-world"><b>Real world</b> Structural bracing, polygon meshes, and network connections all count non-adjacent vertex pairs the same way.</p>
        {convex ? <p className="poly-ok">Convex {regularPolygonName(n)} — every diagonal lies inside.</p> : null}
        <ChallengePanel
          prompt="Find a polygon with exactly 20 diagonals."
          hint="n(n − 3)/2 = 20 ⇒ n(n − 3) = 40 ⇒ n = 8."
          check={() => ({
            ok: n === 8,
            detail: n === 8 ? "Octagon: 8×5/2 = 20." : `Current count is ${total}.`,
          })}
          onReset={() => { setN(5); setVertex(0); setSub("from-vertex"); setProgress(1); }}
        />
      </LivePanel>
    </div>
  );
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { polygonLessonScene } from "../geometryLessonScene";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useCallback, useEffect, useMemo, useRef } from "react";
import { SliderRow } from "../../mockup/studioLabKit";
import {
  fanDiagonals,
  fanTriangles,
  interiorAngleSum,
  interiorAngles,
  interiorAngleRegular,
  exteriorAngleRegular,
  isSelfIntersecting,
  regularPolygonVertices,
  vertexLabel,
  type Vec,
} from "./polygonMath";
import {
  AngleArc,
  ChallengePanel,
  Controls,
  FormulaCard,
  LivePanel,
  MeasureRow,
  PropertyCard,
  Toggle,
  VIEW,
  clientToSvg,
  fmt,
  fmtDeg,
  fromScreen,
  pointsAttr,
  toScreen,
  useRaf,
} from "./polygonUi";

type AngleSub = "sum" | "regular" | "exterior" | "irregular";

export default function InteriorAnglesLab({ pulse = "observe" }: { pulse?: string }) {
  const [n, setN] = useStudioState("InteriorAnglesLab:InteriorAnglesLab:n", 5);
  const [sub, setSub] = useStudioState<AngleSub>("InteriorAnglesLab:InteriorAnglesLab:sub", "sum");
  const [regular, setRegular] = useStudioState("InteriorAnglesLab:InteriorAnglesLab:regular", true);
  const [fan, setFan] = useStudioState("InteriorAnglesLab:InteriorAnglesLab:fan", 0);
  const [walk, setWalk] = useStudioState("InteriorAnglesLab:InteriorAnglesLab:walk", false);
  const [progress, setProgress] = useStudioState("InteriorAnglesLab:InteriorAnglesLab:progress", 0);
  const [verts, setVerts] = useStudioState<Vec[]>("InteriorAnglesLab:InteriorAnglesLab:verts", () => regularPolygonVertices(5, 3.4, 0));
  const svgRef = useRef<SVGSVGElement | null>(null);
  const drag = useRef<number | null>(null);

  const syncRegular = (nextN: number, keepIrregular: boolean) => {
    setN(nextN);
    setFan((v) => Math.min(v, nextN - 1));
    if (!keepIrregular) setVerts(regularPolygonVertices(nextN, 3.4, 0));
    else {
      setVerts((current) => {
        if (current.length === nextN) return current;
        return regularPolygonVertices(nextN, 3.4, 0);
      });
    }
  };

  const geometry = useMemo(() => {
    const points = regular ? regularPolygonVertices(n, 3.4, 0) : verts;
    const screen = points.map((p) => toScreen(p, 48));
    const angles = interiorAngles(points);
    const crossed = isSelfIntersecting(points);
    const triangles = fanTriangles(points, fan);
    const diagonals = fanDiagonals(points, fan);
    return { points, screen, angles, crossed, triangles, diagonals };
  }, [fan, n, regular, verts]);

  const step = useCallback((dt: number) => {
    setProgress((value) => (value + dt * 0.00035) % 1);
  }, []);
  useRaf(walk && sub === "exterior", step);

  const walkInfo = useMemo(() => {
    const edges = geometry.screen;
    const total = edges.length;
    const t = progress * total;
    const i = Math.min(total - 1, Math.floor(t));
    const local = t - i;
    const a = edges[i]!;
    const b = edges[(i + 1) % total]!;
    const x = a.x + (b.x - a.x) * local;
    const y = a.y + (b.y - a.y) * local;
    const turned = Math.min(total, Math.floor(t + 0.02) + (local > 0.92 ? 1 : 0));
    const exterior = exteriorAngleRegular(n);
    return { x, y, turned, cumulative: turned * exterior, exterior, i };
  }, [geometry.screen, n, progress]);

  const dragVertex = (index: number, event: { clientX: number; clientY: number }) => {
    const svg = svgRef.current;
    if (!svg) return;
    const s = clientToSvg(svg, event);
    const math = fromScreen(s.x, s.y, 48);
    setRegular(false);
    setSub("irregular");
    setVerts((current) => current.map((p, i) => (i === index ? math : p)));
  };

  const sum = interiorAngleSum(n);
  const each = interiorAngleRegular(n);

  useEffect(() => {
    if (pulse === "try") { setSub("exterior"); setWalk(true); }
    if (pulse === "challenge") syncRegular(7, false);
    if (pulse === "observe") setSub("sum");
  }, [pulse]);

  return (
    <div className="poly-lab poly-lab--angles">
      <Controls title="Interior angles">
        <div className="poly-sub">
          {([
            ["sum", "Interior Angle Sum"],
            ["regular", "Regular Interior"],
            ["exterior", "Exterior Angles"],
            ["irregular", "Irregular Angles"],
          ] as const).map(([id, label]) => (
            <button key={id} type="button" className={sub === id ? "active" : ""} onClick={() => {
              setSub(id);
              if (id === "irregular") setRegular(false);
              if (id === "regular" || id === "sum") setRegular(true);
            }}>{label}</button>
          ))}
        </div>
        <SliderRow label="Sides n" value={n} min={3} max={12} step={1} onChange={(value) => syncRegular(value, !regular)} />
        <Toggle checked={regular} onChange={(on) => { setRegular(on); if (on) setVerts(regularPolygonVertices(n, 3.4, 0)); }}>Regular polygon</Toggle>
        <SliderRow label="Triangulation vertex" value={fan} min={0} max={n - 1} step={1} onChange={setFan} />
        {sub === "exterior" ? (
          <Toggle checked={walk} onChange={setWalk}>Walk around polygon</Toggle>
        ) : null}
        <p className="msk-note">Choose a vertex to fan-triangulate. Diagonals from that vertex split the n-gon into n − 2 triangles.</p>
      </Controls>

      <section className="msk-panel msk-canvas poly-stage">
        <GeometryLessonCanvas onPointChange={(id, point) => { const index = Number(id.split("-v")[1]); if (!Number.isInteger(index)) return; setRegular(false); setVerts(geometry.points.map((p, i) => i === index ? fromScreen(point.x, point.y, 48) : p)); }} scene={polygonLessonScene(VIEW.w, VIEW.h, [geometry.screen])} ref={svgRef} className="msk-graph poly-svg" viewBox={`0 0 ${VIEW.w} ${VIEW.h}`} role="img" aria-label="Interior angles lab">
          <rect width={VIEW.w} height={VIEW.h} fill="none" />
          {sub === "sum" || sub === "regular" ? geometry.triangles.map((tri, i) => {
            const pts = tri.map((p) => toScreen(p, 48));
            return <polygon key={`t${i}`} points={pointsAttr(pts)} fill={`rgba(139,69,244,${0.08 + (i % 3) * 0.05})`} stroke="#8b45f4" strokeWidth="1" />;
          }) : null}
          {geometry.diagonals.map((line, i) => {
            const a = toScreen(line[0], 48);
            const b = toScreen(line[1], 48);
            return <line key={`d${i}`} x1={a.x} y1={a.y} x2={b.x} y2={b.y} stroke="#8b45f4" strokeDasharray="6 4" />;
          })}
          <polygon points={pointsAttr(geometry.screen)} fill="rgba(20,125,242,.08)" stroke="#147df2" strokeWidth="2.2" />
          {geometry.screen.map((p, i) => {
            const prev = geometry.screen[(i - 1 + n) % n]!;
            const next = screenNext(geometry.screen, i);
            const show = sub !== "exterior" || i === walkInfo.i;
            return show ? <AngleArc key={`a${i}`} center={p} from={prev} to={next} radius={20} color="#8b45f4" label={fmtDeg(geometry.angles[i] ?? 0, 0)} /> : null;
          })}
          {sub === "exterior" ? geometry.screen.map((p, i) => {
            const next = geometry.screen[(i + 1) % n]!;
            const dx = next.x - p.x;
            const dy = next.y - p.y;
            return <line key={`ray${i}`} x1={next.x} y1={next.y} x2={next.x + dx * 0.28} y2={next.y + dy * 0.28} stroke="#f59e0b" />;
          }) : null}
          {sub === "exterior" ? (
            <g>
              <circle cx={walkInfo.x} cy={walkInfo.y} r="7" fill="#f59e0b" />
              <polygon points={`${walkInfo.x + 10},${walkInfo.y} ${walkInfo.x},${walkInfo.y - 6} ${walkInfo.x},${walkInfo.y + 6}`} fill="#f59e0b" />
            </g>
          ) : null}
          {geometry.screen.map((p, i) => (
            <g key={i} className="poly-handle" style={{ cursor: regular ? "default" : "grab" }}>
              <circle cx={p.x} cy={p.y} r="14" fill="transparent" onPointerDown={(event) => {
                if (regular) return;
                drag.current = i;
                event.currentTarget.setPointerCapture(event.pointerId);
              }} onPointerMove={(event) => {
                if (drag.current !== i) return;
                dragVertex(i, event);
              }} onPointerUp={() => { drag.current = null; }} />
              <circle cx={p.x} cy={p.y} r={fan === i ? 7 : 5.5} fill={fan === i ? "#8b45f4" : "#08b9dd"} stroke="#fff" />
              <text x={p.x + 9} y={p.y - 8} fontSize="11" fontWeight="800">{vertexLabel(i)}</text>
            </g>
          ))}
          <text x="20" y="28" fill="#0f172a" fontSize="14" fontWeight="800">
            {sub === "sum" ? "Triangulation proof" : sub === "exterior" ? "Walking exterior angles" : sub === "irregular" ? "Irregular interior angles" : "Equal interior angles"}
          </text>
        </GeometryLessonCanvas>
      </section>

      <LivePanel title="Angle investigation">
        {geometry.crossed ? <p className="poly-warn">Self-intersecting polygon — interior angles are not well-defined for a simple region.</p> : null}
        <MeasureRow color="#8b45f4" label="Triangles" value={n - 2} />
        <MeasureRow color="#147df2" label="Interior sum" value={fmtDeg(sum, 0)} />
        <MeasureRow color="#8b45f4" label="Regular interior" value={fmtDeg(each)} />
        <MeasureRow color="#f59e0b" label="Exterior each" value={fmtDeg(exteriorAngleRegular(n))} />
        <MeasureRow color="#f59e0b" label="Exterior sum" value="360°" />
        <MeasureRow color="#0f766e" label="Selected vertex" value={vertexLabel(fan)} />
        {!regular ? (
          <MeasureRow
            color="#147df2"
            label={geometry.angles.map((_, i) => vertexLabel(i)).join(" + ")}
            value={`${fmt(geometry.angles.reduce((s, a) => s + a, 0), 1)}°`}
          />
        ) : null}
        {sub === "exterior" ? (
          <MeasureRow color="#f59e0b" label="Cumulative turn" value={fmtDeg(Math.min(360, walkInfo.cumulative), 0)} />
        ) : null}
        <FormulaCard title="Interior angle sum">
          n − 2 triangles × 180° = {n - 2} × 180° = {sum}°. Pentagon: 3 triangles → 540°. Hexagon: 4 × 180° = 720°.
        </FormulaCard>
        <PropertyCard title="Exterior walk">
          One full circuit turns through 360°, so exterior angles always sum to 360°. Regular case: each turn is 360°/n.
        </PropertyCard>
        <p className="poly-world"><b>Real world</b> Surveyors close a traverse when turning angles around a parcel sum to a full turn — the same exterior-angle fact.</p>
        <ChallengePanel
          prompt="Create a polygon whose interior angle sum is 900°."
          hint="(n − 2) × 180° = 900 ⇒ n − 2 = 5 ⇒ n = 7."
          check={() => ({
            ok: n === 7,
            detail: n === 7 ? "Heptagon: 5 × 180° = 900°." : `Current sum is ${sum}°.`,
          })}
          onReset={() => syncRegular(5, false)}
        />
      </LivePanel>
    </div>
  );
}

function screenNext(screen: Array<{ x: number; y: number }>, i: number) {
  return screen[(i + 1) % screen.length]!;
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { polygonLessonScene } from "../geometryLessonScene";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useRef, useState } from "react";
import { SliderRow } from "../../mockup/studioLabKit";
import {
  COMPOSITE_PRESETS,
  fanTriangles,
  isSelfIntersecting,
  polygonArea,
  polygonPerimeter,
  regularMetrics,
  regularPolygonVertices,
  shoelaceTable,
  vertexLabel,
  type Vec,
} from "./polygonMath";
import {
  ChallengePanel,
  Controls,
  FormulaCard,
  LivePanel,
  MeasureRow,
  PresetGrid,
  PropertyCard,
  Toggle,
  VIEW,
  clientToSvg,
  fmt,
  fromScreen,
  pointsAttr,
  toScreen,
} from "./polygonUi";

type AreaSub = "regular" | "decomposition" | "composite" | "coordinate";

export default function PolygonAreaLab({ pulse = "observe" }: { pulse?: string }) {
  const [sub, setSub] = useStudioState<AreaSub>("PolygonAreaLab:PolygonAreaLab:sub", "regular");
  const [n, setN] = useStudioState("PolygonAreaLab:PolygonAreaLab:n", 6);
  const [R, setR] = useStudioState("PolygonAreaLab:PolygonAreaLab:R", 3.6);
  const [showApothem, setShowApothem] = useState(true);
  const [wedges, setWedges] = useStudioState("PolygonAreaLab:PolygonAreaLab:wedges", 6);
  const [shape, setShape] = useStudioState("PolygonAreaLab:PolygonAreaLab:shape", "l-shape");
  const [showParts, setShowParts] = useState(true);
  const [showDims, setShowDims] = useState(true);
  const [tableOpen, setTableOpen] = useState(false);
  const [verts, setVerts] = useStudioState<Vec[]>("PolygonAreaLab:PolygonAreaLab:verts", () => [
    { x: -3, y: -2 }, { x: 3, y: -2 }, { x: 2.2, y: 2.4 }, { x: -0.4, y: 3.1 }, { x: -3.2, y: 1.2 },
  ]);
  const [grid, setGrid] = useStudioState<Vec[]>("PolygonAreaLab:PolygonAreaLab:grid", () => [
    { x: -2, y: -2 }, { x: 3, y: -2 }, { x: 3, y: 1 }, { x: 0, y: 3 }, { x: -2, y: 2 },
  ]);
  const drag = useRef<number | null>(null);
  const svgRef = useRef<SVGSVGElement | null>(null);

  const m = regularMetrics(n, R);
  const regularVerts = regularPolygonVertices(n, R, 0);
  const regularScreen = regularVerts.map((p) => toScreen(p, 48));
  const origin = toScreen({ x: 0, y: 0 }, 48);
  const irrScreen = verts.map((p) => toScreen(p, 42));
  const irrArea = polygonArea(verts);
  const irrPeri = polygonPerimeter(verts);
  const triangles = fanTriangles(verts, 0);
  const crossed = isSelfIntersecting(verts);
  const composite = COMPOSITE_PRESETS.find((item) => item.id === shape) ?? COMPOSITE_PRESETS[0]!;
  const partAreas = composite.parts.map((part) => ({ ...part, area: polygonArea(part.points) }));
  const compositeTotal = partAreas.reduce((s, p) => s + p.area, 0);
  const gridArea = polygonArea(grid);
  const rows = shoelaceTable(grid);

  const dragIrr = (index: number, event: { clientX: number; clientY: number }) => {
    const svg = svgRef.current;
    if (!svg) return;
    const s = clientToSvg(svg, event);
    const math = fromScreen(s.x, s.y, 42);
    setVerts((current) => current.map((p, i) => (i === index ? math : p)));
  };

  const dragGrid = (index: number, event: { clientX: number; clientY: number }) => {
    const svg = svgRef.current;
    if (!svg) return;
    const s = clientToSvg(svg, event);
    const math = fromScreen(s.x, s.y, 36);
    setGrid((current) => current.map((p, i) => (i === index ? { x: Math.round(math.x), y: Math.round(math.y) } : p)));
  };

  const wedgeCount = Math.min(n, Math.max(1, wedges));

  const target = useMemo(() => 50, []);

  useEffect(() => {
    if (pulse === "try") setSub("composite");
    if (pulse === "why") { setSub("coordinate"); setTableOpen(true); }
    if (pulse === "observe" || pulse === "challenge") setSub("regular");
  }, [pulse]);

  return (
    <div className="poly-lab poly-lab--area">
      <Controls title="Area explorer">
        <div className="poly-sub">
          {([["regular", "Regular area"], ["decomposition", "Decomposition"], ["composite", "Composite"], ["coordinate", "Coordinate"]] as const).map(([id, label]) => (
            <button key={id} type="button" className={sub === id ? "active" : ""} onClick={() => setSub(id)}>{label}</button>
          ))}
        </div>
        {sub === "regular" ? (
          <>
            <SliderRow label="Sides n" value={n} min={3} max={16} step={1} onChange={(value) => { setN(value); setWedges(value); }} />
            <SliderRow label="Radius R" value={R} min={1.5} max={6} step={0.05} onChange={setR} />
            <SliderRow label="Wedges shown" value={wedgeCount} min={1} max={n} step={1} onChange={setWedges} />
            <Toggle checked={showApothem} onChange={setShowApothem}>Apothem visibility</Toggle>
          </>
        ) : null}
        {sub === "decomposition" ? (
          <p className="msk-note">Drag vertices. Area is the sum of fan triangles from vertex A.</p>
        ) : null}
        {sub === "composite" ? (
          <>
            <PresetGrid value={shape} items={COMPOSITE_PRESETS.map((item) => ({ id: item.id, label: item.name }))} onChange={setShape} />
            <Toggle checked={showParts} onChange={setShowParts}>Show decomposition</Toggle>
            <Toggle checked={showDims} onChange={setShowDims}>Show dimensions</Toggle>
          </>
        ) : null}
        {sub === "coordinate" ? (
          <Toggle checked={tableOpen} onChange={setTableOpen}>Show shoelace table</Toggle>
        ) : null}
      </Controls>

      <section className="msk-panel msk-canvas poly-stage">
        <GeometryLessonCanvas activityId={`area-${sub}`} scene={polygonLessonScene(VIEW.w, VIEW.h, (sub === "regular" || sub === "decomposition") ? [regularScreen] : sub === "composite" ? composite.parts.map(part => part.points.map(p => toScreen({ x: p.x - 3, y: p.y - 3 }, 38))) : sub === "coordinate" ? [grid.map(p => toScreen(p, 36))] : [irrScreen], sub === "regular" || sub === "decomposition" ? 48 : sub === "composite" ? 38 : sub === "coordinate" ? 36 : 42)} ref={svgRef} className="msk-graph poly-svg" viewBox={`0 0 ${VIEW.w} ${VIEW.h}`} role="img" aria-label="Area lab">
          <rect width={VIEW.w} height={VIEW.h} fill="none" />
          {sub === "regular" ? (
            <g>
              {regularVerts.slice(0, wedgeCount).map((_, i) => {
                const a = regularScreen[i]!;
                const b = regularScreen[(i + 1) % n]!;
                return <polygon key={i} points={`${origin.x},${origin.y} ${a.x},${a.y} ${b.x},${b.y}`} fill={`rgba(20,125,242,${0.08 + (i % 4) * 0.04})`} stroke="#147df2" />;
              })}
              <polygon points={pointsAttr(regularScreen)} fill="none" stroke="#0f172a" strokeWidth="1.4" />
              {showApothem && regularScreen[0] && regularScreen[1] ? (
                <line x1={origin.x} y1={origin.y} x2={(regularScreen[0].x + regularScreen[1].x) / 2} y2={(regularScreen[0].y + regularScreen[1].y) / 2} stroke="#0f766e" strokeWidth="2" />
              ) : null}
              <circle cx={origin.x} cy={origin.y} r="4" fill="#8b45f4" />
              <text x="20" y="28" fontSize="14" fontWeight="800" fill="#0f172a">n congruent triangles from O</text>
            </g>
          ) : null}
          {sub === "decomposition" ? (
            <g>
              {triangles.map((tri, i) => (
                <polygon key={i} points={pointsAttr(tri.map((p) => toScreen(p, 42)))} fill={`rgba(139,69,244,${0.1 + (i % 3) * 0.06})`} stroke="#8b45f4" />
              ))}
              {irrScreen.map((p, i) => (
                <g key={i} className="poly-handle">
                  <circle cx={p.x} cy={p.y} r="14" fill="transparent" onPointerDown={(e) => { drag.current = i; e.currentTarget.setPointerCapture(eventPointer(e)); }} onPointerMove={(e) => { if (drag.current === i) dragIrr(i, e); }} onPointerUp={() => { drag.current = null; }} />
                  <circle cx={p.x} cy={p.y} r="6" fill="#08b9dd" stroke="#fff" />
                  <text x={p.x + 8} y={p.y - 8} fontSize="11" fontWeight="800">{vertexLabel(i)}</text>
                </g>
              ))}
              <text x="20" y="28" fontSize="14" fontWeight="800">Fan triangulation</text>
            </g>
          ) : null}
          {sub === "composite" ? (
            <g>
              {partAreas.map((part, i) => {
                const pts = part.points.map((p) => toScreen({ x: p.x - 3, y: p.y - 3 }, 38));
                return (
                  <g key={part.id}>
                    <polygon points={pointsAttr(pts)} fill={showParts ? (i === 0 ? "rgba(20,125,242,.16)" : "rgba(245,158,11,.16)") : "rgba(20,125,242,.12)"} stroke="#147df2" />
                    {showDims ? <text x={pts[0]!.x + 12} y={pts[0]!.y + 18} fontSize="11" fill="#0f172a">{part.label}</text> : null}
                  </g>
                );
              })}
              <text x="20" y="28" fontSize="14" fontWeight="800">{composite.name} floor plan</text>
            </g>
          ) : null}
          {sub === "coordinate" ? (
            <g>
              {Array.from({ length: 13 }, (_, i) => (
                <g key={i}>
                  <line x1={80 + i * 36} y1="40" x2={80 + i * 36} y2="420" stroke="#e8eef6" />
                  <line x1="80" y1={40 + i * 36} x2="560" y2={40 + i * 36} stroke="#e8eef6" />
                </g>
              ))}
              <polygon points={pointsAttr(grid.map((p) => toScreen(p, 36)))} fill="rgba(20,125,242,.12)" stroke="#147df2" strokeWidth="2" />
              {grid.map((p, i) => {
                const s = toScreen(p, 36);
                return (
                  <g key={i} className="poly-handle">
                    <circle cx={s.x} cy={s.y} r="14" fill="transparent" onPointerDown={(e) => { drag.current = i; e.currentTarget.setPointerCapture(eventPointer(e)); }} onPointerMove={(e) => { if (drag.current === i) dragGrid(i, e); }} onPointerUp={() => { drag.current = null; }} />
                    <circle cx={s.x} cy={s.y} r="6" fill="#8b45f4" stroke="#fff" />
                    <text x={s.x + 8} y={s.y - 8} fontSize="11">{vertexLabel(i)} ({p.x},{p.y})</text>
                  </g>
                );
              })}
              <text x="20" y="28" fontSize="14" fontWeight="800">Shoelace on a coordinate grid</text>
            </g>
          ) : null}
        </GeometryLessonCanvas>
      </section>

      <LivePanel title="Area">
        {sub === "regular" ? (
          <>
            <MeasureRow color="#0ea5e9" label="Perimeter" value={fmt(m.perimeter, 3)} />
            <MeasureRow color="#0f766e" label="Apothem" value={fmt(m.apothem, 3)} />
            <MeasureRow color="#147df2" label="One triangle" value={fmt(m.area / n, 3)} />
            <MeasureRow color="#147df2" label="Total area" value={fmt(m.area, 3)} />
            <FormulaCard title="Regular area">
              One triangle = ½ × side × apothem. Total = n × that = ½ P a = ½ n R² sin(2π/n).
            </FormulaCard>
          </>
        ) : null}
        {sub === "decomposition" ? (
          <>
            {crossed ? <p className="poly-warn">Self-intersecting — shoelace still runs, but the region is not simple.</p> : null}
            {triangles.map((tri, i) => (
              <MeasureRow key={i} color="#8b45f4" label={`Area ${i + 1}`} value={fmt(polygonArea(tri), 3)} />
            ))}
            <MeasureRow color="#147df2" label="Total area" value={fmt(irrArea, 3)} />
            <MeasureRow color="#0ea5e9" label="Perimeter" value={fmt(irrPeri, 3)} />
          </>
        ) : null}
        {sub === "composite" ? (
          <>
            {partAreas.map((part) => (
              <MeasureRow key={part.id} color="#f59e0b" label={part.label} value={fmt(part.area, 2)} />
            ))}
            <MeasureRow color="#147df2" label="Total area" value={fmt(compositeTotal, 2)} />
            <p className="msk-note">Find the total without opening this panel, then Check.</p>
          </>
        ) : null}
        {sub === "coordinate" ? (
          <>
            <MeasureRow color="#147df2" label="Shoelace area" value={fmt(gridArea, 3)} />
            <FormulaCard title="Shoelace">A = ½ |Σ (xᵢ yᵢ₊₁ − yᵢ xᵢ₊₁)|</FormulaCard>
            {tableOpen ? (
              <div className="poly-table-wrap">
                <table>
                  <thead><tr><th>Vertex</th><th>x</th><th>y</th><th>xᵢyᵢ₊₁</th><th>yᵢxᵢ₊₁</th></tr></thead>
                  <tbody>
                    {rows.map((row) => (
                      <tr key={row.label}><td>{row.label}</td><td>{fmt(row.x, 2)}</td><td>{fmt(row.y, 2)}</td><td>{fmt(row.xyNext, 2)}</td><td>{fmt(row.yxNext, 2)}</td></tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : null}
          </>
        ) : null}
        <PropertyCard title="Why decompose?">
          Land parcels, floor plans, and fabrication layouts are usually unions of triangles and rectangles — never one mystery formula.
        </PropertyCard>
        <ChallengePanel
          prompt="Create a regular polygon with area approximately 50 square units."
          hint="Area = ½ n R² sin(2π/n). Try a hexagon with R near 4.4, or change n."
          check={() => ({
            ok: Math.abs(m.area - target) <= 4,
            detail: `Current regular area is ${fmt(m.area, 2)} (target ≈ ${target}).`,
          })}
          onReset={() => { setN(6); setR(3.6); setSub("regular"); }}
        />
      </LivePanel>
    </div>
  );
}

function eventPointer(event: { pointerId: number }) {
  return event.pointerId;
}

