function nearestVertex(pt: { x: number; y: number }, vertices: VertexRecord[], maxDist: number) {
  let best: VertexRecord | null = null;
  let bestD = maxDist;
  for (const v of vertices) {
    const d = dist(pt, v.point);
    if (d < bestD) {
      best = v;
      bestD = d;
    }
  }
  return best;
}

function nearestEdge(pt: { x: number; y: number }, edges: Array<{ key: string; a: { x: number; y: number }; b: { x: number; y: number } }>, maxDist: number) {
  let best: (typeof edges)[number] | null = null;
  let bestD = maxDist;
  for (const edge of edges) {
    const d = dist(pt, nearestPointOnSegment(pt, edge.a, edge.b));
    if (d < bestD) {
      best = edge;
      bestD = d;
    }
  }
  return best;
}

function AngleSectors({
  vertex,
  tiles,
  interior,
  zoom,
}: {
  vertex: VertexRecord;
  tiles: Tile[];
  interior: number;
  zoom: number;
}) {
  const r = 18 / zoom;
  const meeting = tiles.filter((t) => vertex.tileIds.includes(t.id));
  const angles = meeting.map((tile) => {
    const c = tile.center;
    return Math.atan2(c.y - vertex.point.y, c.x - vertex.point.x);
  }).sort((a, b) => a - b);
  const start = (angles[0] ?? 0) * (180 / Math.PI) - interior / 2;
  return (
    <g>
      {meeting.map((_, i) => (
        <path
          key={i}
          d={sectorPath(vertex.point, r, start + i * interior, interior)}
          fill={i % 2 ? "rgba(8,185,221,.22)" : "rgba(20,125,242,.16)"}
          stroke="#147df2"
          strokeWidth={0.6 / zoom}
        />
      ))}
      <text x={vertex.point.x + r + 6 / zoom} y={vertex.point.y} fill="#0f2747" fontSize={11 / zoom} fontWeight={700}>
        {meeting.length} × {fmt(interior, 0)}° = {fmt(meeting.length * interior, 0)}°
      </text>
    </g>
  );
}

function ExperimentView({ n, overlap, onToggleOverlap }: { n: number; overlap: boolean; onToggleOverlap: () => void }) {
  const check = regularTessellationCheck(n);
  const count = overlap ? check.floorCount + 1 : check.floorCount;
  const side = 72;
  const origin = { x: 210, y: 210 };
  const polys = Array.from({ length: count }, (_, i) => regularPolygonAtVertex(n, side, origin, i * check.interior));
  const gapStart = check.floorCount * check.interior;
  return (
    <div style={{ height: "100%", display: "grid", gridTemplateRows: "1fr auto" }}>
      <GeometryLessonCanvas activityId={`packing-${n}`} scene={polygonLessonScene(420, 420, polys)} className="tlab-svg" viewBox="0 0 420 420" role="img" aria-label="Vertex packing experiment">
        <rect width="420" height="420" fill="#f7fbff" />
        {polys.map((verts, i) => (
          <polygon key={i} points={verts.map((p) => `${p.x},${p.y}`).join(" ")} fill={overlap && i === count - 1 ? "rgba(244,63,94,.18)" : "rgba(20,125,242,.12)"} stroke="#147df2" strokeWidth="1.4" />
        ))}
        {!check.tessellates && !overlap && (
          <path d={sectorPath(origin, 88, gapStart, check.gapDeg)} fill="rgba(245,158,11,.35)" stroke="#d97706" />
        )}
        <circle cx={origin.x} cy={origin.y} r="4" fill="#147df2" />
        {!check.tessellates && !overlap && (
          <text x="210" y="28" textAnchor="middle" fontSize="13" fill="#b45309" fontWeight={800}>
            Gap = {fmt(check.gapDeg, 1)}°
          </text>
        )}
        {overlap && !check.tessellates && (
          <text x="210" y="28" textAnchor="middle" fontSize="13" fill="#b45309" fontWeight={800}>
            Overlap = {fmt(check.overlapDeg, 1)}°
          </text>
        )}
        {check.tessellates && (
          <text x="210" y="28" textAnchor="middle" fontSize="13" fill="#07893d" fontWeight={800}>
            {check.meetingCount} × {fmt(check.interior, 0)}° = 360°
          </text>
        )}
      </GeometryLessonCanvas>
      <div className="tlab-btn-row" style={{ padding: 8 }}>
        <button type="button" className={!overlap ? "is-on" : ""} onClick={onToggleOverlap}>{overlap ? "Show gap" : "Show overlap"}</button>
        <span className="tlab-note">{check.tessellates ? "This n tiles the plane." : "Not a regular monohedral tessellation."}</span>
      </div>
    </div>
  );
}

function ComparePanels({ size, n }: { size: number; n: number }) {
  return (
    <div className="tlab-compare">
      <NeighborhoodPane kind="triangle" size={size} title="Triangle" formula="6 × 60° = 360°" />
      <NeighborhoodPane kind="square" size={size} title="Square" formula="4 × 90° = 360°" />
      <NeighborhoodPane kind="hexagon" size={size} title="Hexagon" formula="3 × 120° = 360°" />
      <div className="tlab-compare-pane">
        <b>Pentagon n={n >= 5 ? 5 : n}</b>
        <ExperimentView n={5} overlap={false} onToggleOverlap={() => undefined} />
        <small>3 × 108° = 324° · gap 36°</small>
      </div>
    </div>
  );
}

function NeighborhoodPane({ kind, size, title, formula }: { kind: TileKind; size: number; title: string; formula: string }) {
  const s = kind === "hexagon" ? Math.max(22, size * 0.7) : Math.max(28, size * 0.7);
  const tiles = useMemo(() => {
    const raw = generateKind(kind, { minX: -s * 4, minY: -s * 4, maxX: s * 4, maxY: s * 4 }, s);
    return assignGenerations(raw, kind, "expand").filter((t) => t.generation <= 1);
  }, [kind, s]);
  const verts = indexVertices(tiles, s);
  const v = verts.find((item) => item.tileIds.length === expectedMeetCount(kind)) ?? verts[0];
  const interior = regularInteriorAngle(sidesOf(kind, 3));
  return (
    <div className="tlab-compare-pane">
      <b>{title}</b>
      <svg viewBox="-90 -90 180 180" aria-label={title}>
        {tiles.map((tile) => (
          <polygon
            key={tile.id}
            points={inflateVertices(tile.vertices, 0.4).map((p) => `${p.x},${p.y}`).join(" ")}
            fill={fillFor(tile, "alternating", v ? !v.tileIds.includes(tile.id) : false)}
            stroke="#8aa0b8"
            strokeWidth="0.8"
          />
        ))}
        {v && <AngleSectors vertex={v} tiles={tiles} interior={interior} zoom={1} />}
      </svg>
      <small>{formula}</small>
    </div>
  );
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { proofLessonScene } from "../geometryStudioScenes";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useState } from "react";
import type { StudioMockupPage } from "../../mockup/studioMockupCatalog";
import { ChallengeBox, LiveRow, Panel, SliderRow, StatusOk, StepList, clamp } from "../../mockup/studioLabKit";
import { FigureToolbar, Phase1LabChrome } from "../../phase1/Phase1LabChrome";
import { useStudioFigure } from "../../phase1/useStudioFigure";
import { angleSum, inscribedVsCentral, pythagorasTiles, similarScale, twoColumnClaims } from "./proofMath";

type Fig = { a: number; b: number; tear: number; arc: number; k: number };
const initial: Fig = { a: 3, b: 4, tear: 0.4, arc: 80, k: 2 };

export default function ProofsLab({ page }: { page: StudioMockupPage }) {
  const fig = useStudioFigure(initial);
  const [checked, setChecked] = useStudioState<Record<string, boolean>>("ProofsLab:ProofsLab:checked", {});
  return (
    <Phase1LabChrome
      page={page}
      toolbar={
        <FigureToolbar
          canUndo={fig.canUndo}
          canRedo={fig.canRedo}
          exact={fig.exact}
          onUndo={fig.undo}
          onRedo={fig.redo}
          onReset={fig.reset}
          onShare={() => void fig.share()}
          onExact={fig.setExact}
        />
      }
    >
      {(mode) => {
        const tiles = pythagorasTiles(fig.state.a, fig.state.b);
        const torn = angleSum(fig.state.tear);
        const circle = inscribedVsCentral(fig.state.arc);
        const sim = similarScale(fig.state.k);
        const expected = mode === "Pythagoras" ? 5 : mode === "Angle Sum" ? 180 : mode === "Circle Theorems" ? circle.inscribed : mode === "Similarity" ? sim.area : fig.state.a * fig.state.b;
        return (
          <>
            <Panel title={mode}>
              {mode === "Pythagoras" || mode === "Area Proofs" ? (
                <>
                  <SliderRow label="Leg a" value={fig.state.a} min={1} max={8} step={0.1} onChange={(a) => fig.commit({ ...fig.state, a })} />
                  <SliderRow label="Leg b" value={fig.state.b} min={1} max={8} step={0.1} onChange={(b) => fig.commit({ ...fig.state, b })} />
                </>
              ) : null}
              {mode === "Angle Sum" ? <SliderRow label="Tear onto a line" value={fig.state.tear} min={0} max={1} step={0.02} onChange={(tear) => fig.commit({ ...fig.state, tear })} /> : null}
              {mode === "Circle Theorems" ? <SliderRow label="Central arc °" value={fig.state.arc} min={20} max={160} step={1} onChange={(arc) => fig.commit({ ...fig.state, arc })} /> : null}
              {mode === "Similarity" ? <SliderRow label="Scale k" value={fig.state.k} min={0.5} max={3} step={0.05} onChange={(k) => fig.commit({ ...fig.state, k })} /> : null}
            </Panel>
            <section className="msk-panel msk-canvas">
              <GeometryLessonCanvas scene={proofLessonScene(mode, fig.state)}
                className="msk-graph is-interactive"
                viewBox="0 0 420 240"
                role="img"
                aria-label={mode}
                data-mode-canvas={mode}
                onPointerMove={(event: PointerEvent<SVGSVGElement>) => {
                  if (event.buttons === 0) return;
                  const box = event.currentTarget.getBoundingClientRect();
                  fig.commit({ ...fig.state, a: clamp((event.clientX - box.left) / box.width * 8, 1, 8), b: clamp(8 - (event.clientY - box.top) / box.height * 8, 1, 8) });
                }}
              >
                <rect width="420" height="240" fill="#f8fbff" />
                {mode === "Pythagoras" || mode === "Area Proofs" ? (
                  <>
                    <polygon points={`80,200 ${80 + tiles.a * 18},200 ${80 + tiles.a * 18},${200 - tiles.b * 18} 80,${200 - tiles.b * 18}`} fill="rgba(20,125,242,.16)" stroke="#147df2" />
                    <rect x={80 + tiles.a * 18} y={200 - tiles.a * 18} width={tiles.a * 18} height={tiles.a * 18} fill="rgba(8,185,221,.2)" stroke="#08b9dd" />
                    <rect x={80 - tiles.b * 18} y={200 - tiles.b * 18} width={tiles.b * 18} height={tiles.b * 18} fill="rgba(139,69,244,.16)" stroke="#8b45f4" />
                    <text x="70" y="28" fill="#0f172a" fontSize="13">{fig.format(tiles.a, 2)}² + {fig.format(tiles.b, 2)}² = {fig.format(tiles.c, 2)}²</text>
                  </>
                ) : null}
                {mode === "Angle Sum" ? (
                  <>
                    <polygon points="80,190 260,190 150,70" fill="rgba(20,125,242,.12)" stroke="#147df2" />
                    <line x1="40" y1="210" x2={40 + torn.torn * 300} y2="210" stroke="#f59e0b" strokeWidth="6" />
                    <text x="48" y="34" fill="#0f172a" fontSize="13">Tear progress {fig.format(torn.torn * 100, 0)}% · sum {torn.sum}°</text>
                  </>
                ) : null}
                {mode === "Circle Theorems" ? (
                  <>
                    <circle cx="200" cy="120" r="78" fill="none" stroke="#147df2" />
                    <path d={`M200,120 L278,120 A78,78 0 0 ${circle.central > 180 ? 1 : 0} ${200 + 78 * Math.cos((circle.central * Math.PI) / 180)},${120 - 78 * Math.sin((circle.central * Math.PI) / 180)}`} fill="rgba(139,69,244,.2)" stroke="#8b45f4" />
                    <text x="40" y="28" fill="#0f172a" fontSize="13">Inscribed {fig.format(circle.inscribed, 1)}° = ½ · central {fig.format(circle.central, 1)}°</text>
                  </>
                ) : null}
                {mode === "Similarity" ? (
                  <>
                    <polygon points="70,200 190,200 70,90" fill="rgba(20,125,242,.14)" stroke="#147df2" />
                    <polygon points={`230,200 ${230 + 120 * sim.k / 2},200 230,${200 - 110 * sim.k / 2}`} fill="rgba(139,69,244,.12)" stroke="#8b45f4" />
                    <text x="40" y="28" fill="#0f172a" fontSize="13">Area scale k² = {fig.format(sim.area, 2)}</text>
                  </>
                ) : null}
              </GeometryLessonCanvas>
            </section>
            <aside className="msk-panel msk-live">
              {mode === "Pythagoras" || mode === "Area Proofs" ? (
                <>
                  <LiveRow color="#08b9dd" label="a²" value={fig.format(tiles.a2)} />
                  <LiveRow color="#8b45f4" label="b²" value={fig.format(tiles.b2)} />
                  <LiveRow color="#f59e0b" label="c²" value={fig.format(tiles.c2)} />
                </>
              ) : null}
              {mode === "Angle Sum" ? <LiveRow color="#f59e0b" label="∠A+∠B+∠C" value={`${torn.sum}°`} /> : null}
              {mode === "Circle Theorems" ? <LiveRow color="#8b45f4" label="Inscribed" value={`${fig.format(circle.inscribed, 1)}°`} /> : null}
              {mode === "Similarity" ? <LiveRow color="#147df2" label="k² (area)" value={fig.format(sim.area, 2)} /> : null}
              <StatusOk>
                {mode === "Angle Sum" ? "∠A+∠B+∠C = 180°" : mode === "Circle Theorems" ? "Inscribed angle is half the centre" : "a² + b² = c²"}
              </StatusOk>
              <StepList items={["Watch the figure respond.", "Name the invariant.", "Tick the two-column step that matches this figure."]} />
              <ol className="msk-mini-table" aria-label="Two-column proof from this figure">
                {twoColumnClaims(mode, fig.state).map((row) => {
                  const key = `${mode}:${row.conclude}`;
                  const on = checked[key] ?? (mode === "Pythagoras" ? tiles.holds : false);
                  return (
                    <li key={row.conclude}>
                      <label>
                        <input
                          type="checkbox"
                          checked={on}
                          onChange={(event) => setChecked((prev) => ({ ...prev, [key]: event.target.checked }))}
                        />
                        {" "}Given {row.given} → {row.conclude} (live {row.live})
                      </label>
                    </li>
                  );
                })}
              </ol>
              <ChallengeBox kind="live"
                prompt={mode === "Pythagoras" ? "In a 3-4-5 triangle, hypotenuse is?" : mode === "Angle Sum" ? "Angle sum of a triangle (degrees)?" : "Read the live value for this proof."}
                expected={expected}
                hint="Match the live figure, not a remembered slogan."
              />
            </aside>
          </>
        );
      }}
    </Phase1LabChrome>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useState } from "react";
import { Link } from "react-router-dom";
import type { StudioMockupPage } from "../../mockup/studioMockupCatalog";
import { LiveRow, Panel, SliderRow, StatusOk, fmt } from "../../mockup/studioLabKit";
import { Phase1LabChrome } from "../../phase1/Phase1LabChrome";
import { SolidKind, StudioMath3D } from "../../shared/studioMath3D";

const SHAPE: Record<string, { href: string; label: string; formula: string }> = {
  Cylinders: { href: "/shapes?shape=cylinder", label: "Cylinder", formula: "V = πr²h" },
  Cones: { href: "/shapes?shape=cone", label: "Cone", formula: "V = ⅓πr²h" },
  Spheres: { href: "/shapes?shape=sphere", label: "Sphere", formula: "V = ⁴⁄₃πr³" },
  Nets: { href: "/shapes?shape=cube", label: "Cube net", formula: "Unfold without overlap" },
  "Cross-sections": { href: "/shapes?shape=cylinder", label: "Cross-section", formula: "Plane ∩ solid" },
};

function solidMeasures(kind: string, r: number, h: number) {
  if (kind === "Spheres") {
    return { V: (4 / 3) * Math.PI * r ** 3, SA: 4 * Math.PI * r ** 2 };
  }
  if (kind === "Cones") {
    const slant = Math.hypot(r, h);
    return { V: (1 / 3) * Math.PI * r * r * h, SA: Math.PI * r * r + Math.PI * r * slant };
  }
  if (kind === "Nets") {
    const s = r;
    return { V: s ** 3, SA: 6 * s * s };
  }
  return { V: Math.PI * r * r * h, SA: 2 * Math.PI * r * r + 2 * Math.PI * r * h };
}

export default function SolidsStudioLab({ page }: { page: StudioMockupPage }) {
  const [r, setR] = useStudioState("SolidsStudioLab:SolidsStudioLab:r", 1);
  const [h, setH] = useStudioState("SolidsStudioLab:SolidsStudioLab:h", 2);
  return (
    <Phase1LabChrome page={page}>
      {(mode) => {
        const spec = SHAPE[mode] ?? SHAPE.Cylinders!;
        const measures = solidMeasures(mode, r, h);
        const needsHeight = mode !== "Spheres";
        return (
          <>
            <Panel title={mode}>
              <p className="msk-note">Solid geometry uses the same Three.js engine as Linear Algebra. Orbit the solid, then open Shapes Explorer for nets and measurements.</p>
              <SliderRow label={mode === "Nets" ? "Side s" : "Radius r"} value={r} min={0.4} max={3} step={0.05} onChange={setR} />
              {needsHeight ? <SliderRow label="Height h" value={h} min={0.4} max={4} step={0.05} onChange={setH} /> : null}
              <Link className="msk-cta" to={spec.href}>Open {spec.label} in Shapes Explorer</Link>
            </Panel>
            <section className="msk-panel msk-canvas" data-mode-canvas={mode}>
              <StudioMath3D label={mode}>
                <SolidKind kind={mode} />
              </StudioMath3D>
              <p className="msk-formula">{spec.formula}</p>
            </section>
            <aside className="msk-panel msk-live">
              <LiveRow color="#147df2" label="Opens" value={spec.href} />
              <LiveRow color="#8b45f4" label="Volume V" value={fmt(measures.V, 3)} />
              <LiveRow color="#f59e0b" label="Surface area SA" value={fmt(measures.SA, 3)} />
              <StatusOk>Rotate the solid, read surface area and volume, then unfold a net that does not overlap.</StatusOk>
            </aside>
          </>
        );
      }}
    </Phase1LabChrome>
  );
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { triangleLessonScene } from "../geometryLessonScene";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useRef } from "react";
import { ChipRow, Field, Panel, SliderRow, StatusOk } from "../../mockup/studioLabKit";
import {
  almostEqual,
  clampPoint,
  constructAAS,
  constructASAc,
  constructRHS,
  constructSAS,
  constructSSS,
  defaultPlane,
  toSvg,
  fromSvg,
  measureTriangle,
  ssaSolutions,
  triangleAngles,
  triangleArea,
  type Pt,
} from "./triangleGeometry";
import { ChallengeCard, FormulaCard, InsightStack, LabFrame, MeasureRow, Toggle, okNum } from "./triangleLabKit";
import {
  AngleArc,
  DraggableVertex,
  RightAngleMarker,
  SideMeasurement,
  SideTickMark,
  bindSvgDrag,
  pointerToSvg,
  polyPoints,
} from "./triangleSvgPrimitives";

type Test = "SSS" | "SAS" | "ASA" | "AAS" | "RHS" | "SSA";

function swapMap(swap: boolean) {
  return swap
    ? { A: "D", B: "F", C: "E", AB: "DF", BC: "FE", CA: "ED" }
    : { A: "D", B: "E", C: "F", AB: "DE", BC: "EF", CA: "FD" };
}

export default function CongruenceLab({ pulse = "observe" }: { pulse?: string }) {
  const plane = defaultPlane(720, 460);
  const svgRef = useRef<SVGSVGElement>(null);
  const drag = useRef<"A" | "B" | "C" | null>(null);
  const [test, setTest] = useStudioState<Test>("CongruenceLab:CongruenceLab:test", "SSS");
  const [swap, setSwap] = useStudioState("CongruenceLab:CongruenceLab:swap", false);
  const [ab, setAb] = useStudioState("CongruenceLab:CongruenceLab:ab", 5.2);
  const [bc, setBc] = useStudioState("CongruenceLab:CongruenceLab:bc", 6.4);
  const [ca, setCa] = useStudioState("CongruenceLab:CongruenceLab:ca", 4.8);
  const [angA, setAngA] = useStudioState("CongruenceLab:CongruenceLab:angA", 52);
  const [angB, setAngB] = useStudioState("CongruenceLab:CongruenceLab:angB", 58);
  const [hyp, setHyp] = useStudioState("CongruenceLab:CongruenceLab:hyp", 6.5);
  const [leg, setLeg] = useStudioState("CongruenceLab:CongruenceLab:leg", 3.9);
  const [rot, setRot] = useStudioState("CongruenceLab:CongruenceLab:rot", 8);
  const [ssaA, setSsaA] = useStudioState("CongruenceLab:CongruenceLab:ssaA", 40);
  const [ssaAopp, setSsaAopp] = useStudioState("CongruenceLab:CongruenceLab:ssaAopp", 3.1);
  const [ssaB, setSsaB] = useStudioState("CongruenceLab:CongruenceLab:ssaB", 4.4);
  const [labels, setLabels] = useStudioState("CongruenceLab:CongruenceLab:labels", true);
  const [free, setFree] = useStudioState("CongruenceLab:CongruenceLab:free", { A: { x: 2.4, y: 6.6 }, B: { x: 1.5, y: 1.5 }, C: { x: 7.2, y: 1.6 } });

  const map = swapMap(swap);
  const leftOrigin = { x: 1.2, y: 1.5 };
  const rightOrigin = { x: 10.3, y: 1.5 };

  const pair = useMemo(() => {
    if (test === "SSS") return { L: constructSSS(bc, ca, ab, leftOrigin), R: constructSSS(bc, ca, ab, rightOrigin, rot) };
    if (test === "SAS") return { L: constructSAS(ab, angA, ca, leftOrigin), R: constructSAS(ab, angA, ca, rightOrigin, rot) };
    if (test === "ASA") return { L: constructASAc(angA, ab, angB, leftOrigin), R: constructASAc(angA, ab, angB, rightOrigin, rot) };
    if (test === "AAS") return { L: constructAAS(angA, angB, bc, leftOrigin), R: constructAAS(angA, angB, bc, rightOrigin, rot) };
    if (test === "RHS") return { L: constructRHS(hyp, leg, leftOrigin), R: constructRHS(hyp, leg, rightOrigin, rot) };
    const sols = ssaSolutions(ssaA, ssaAopp, ssaB, { x: 0, y: 0 });
    const place = (tri: { A: Pt; B: Pt; C: Pt }, origin: Pt) => ({
      A: { x: tri.A.x + origin.x, y: tri.A.y + origin.y },
      B: { x: tri.B.x + origin.x, y: tri.B.y + origin.y },
      C: { x: tri.C.x + origin.x, y: tri.C.y + origin.y },
      ok: true,
    });
    if (sols.length >= 2) return { L: place(sols[0], leftOrigin), R: place(sols[1], { x: 9.6, y: 1.5 }) };
    if (sols.length === 1) return { L: place(sols[0], leftOrigin), R: place(sols[0], rightOrigin) };
    return { L: constructSAS(ssaB, ssaA, 2.2, leftOrigin), R: constructSAS(ssaB, ssaA, 2.2, rightOrigin) };
  }, [ab, angA, angB, bc, ca, hyp, leg, rot, ssaA, ssaAopp, ssaB, test]);

  const L = pair.L;
  const R = pair.R;
  const mL = measureTriangle(L.A, L.B, L.C);
  const mR = measureTriangle(R.A, R.B, R.C);
  const sidesEq = almostEqual(mL.sides.AB, mR.sides.AB) && almostEqual(mL.sides.BC, mR.sides.BC) && almostEqual(mL.sides.CA, mR.sides.CA);
  const anglesEq = almostEqual(mL.angles.A, mR.angles.A, 0.8) && almostEqual(mL.angles.B, mR.angles.B, 0.8) && almostEqual(mL.angles.C, mR.angles.C, 0.8);
  const congruent = test !== "SSA" && sidesEq && anglesEq;

  const startDrag = (who: "A" | "B" | "C") => (event: React.PointerEvent) => {
    event.preventDefault();
    drag.current = who;
    bindSvgDrag(svgRef, (ev) => {
      const svg = svgRef.current;
      if (!svg || !drag.current) return;
      const s = pointerToSvg(svg, ev);
      const next = clampPoint(fromSvg(plane, s.x, s.y), 0.5, 9.2, 0.4, 11);
      setFree((prev) => {
        const draft = { ...prev, [drag.current!]: next };
        if (triangleArea(draft.A, draft.B, draft.C) < 0.4) return prev;
        setAb(Math.hypot(draft.A.x - draft.B.x, draft.A.y - draft.B.y));
        setBc(Math.hypot(draft.B.x - draft.C.x, draft.B.y - draft.C.y));
        setCa(Math.hypot(draft.C.x - draft.A.x, draft.C.y - draft.A.y));
        return draft;
      });
    }, () => { drag.current = null; });
  };

  const proof = () => {
    if (test === "SSS") return [`AB = ${map.AB} = ${okNum(mL.sides.AB)}`, `BC = ${map.BC} = ${okNum(mL.sides.BC)}`, `CA = ${map.CA} = ${okNum(mL.sides.CA)}`, `△ABC ≅ △${map.A}${map.B}${map.C} by SSS.`];
    if (test === "SAS") return [`AB = ${map.AB} = ${okNum(mL.sides.AB)}`, `AC = ${swap ? "DE" : "DF"} = ${okNum(mL.sides.CA)}`, `Included ∠A = ∠${map.A} = ${okNum(mL.angles.A, 1)}°`, `△ABC ≅ △${map.A}${map.B}${map.C} by SAS.`];
    if (test === "ASA") return [`∠B = ∠${map.B} = ${okNum(mL.angles.B, 1)}°`, `Included AB = ${map.AB}`, `∠A = ∠${map.A} = ${okNum(mL.angles.A, 1)}°`, `△ABC ≅ △${map.A}${map.B}${map.C} by ASA.`];
    if (test === "AAS") return [`∠A = ∠${map.A}`, `∠B = ∠${map.B}`, `Non-included BC = ${map.BC}`, `△ABC ≅ △${map.A}${map.B}${map.C} by AAS.`];
    if (test === "RHS") return [`Right angles at C and ${map.C}`, `Hypotenuse AB = ${map.AB} = ${okNum(mL.sides.AB)}`, `Leg BC = ${map.BC} = ${okNum(mL.sides.BC)}`, `△ABC ≅ △${map.A}${map.B}${map.C} by RHS.`];
    return ["Two sides and a non-included angle (SSA) can yield 0, 1, or 2 triangles.", "This is the ambiguous case — not a congruence test."];
  };

  const reset = () => {
    setTest("SSS"); setAb(5.2); setBc(6.4); setCa(4.8); setAngA(52); setAngB(58); setHyp(6.5); setLeg(3.9); setRot(8); setSwap(false);
    setFree({ A: { x: 2.4, y: 6.6 }, B: { x: 1.5, y: 1.5 }, C: { x: 7.2, y: 1.6 } });
  };

  useEffect(() => {
    if (pulse === "observe") setTest("SSS");
    if (pulse === "understand") setTest("SAS");
    if (pulse === "why") setTest("SSA");
    if (pulse === "try" || pulse === "challenge") setTest("SAS");
  }, [pulse]);

  return (
    <LabFrame
      theme="congruence"
      ariaLabel="Congruence laboratory"
      controls={
        <Panel title="Congruence test">
          <Field label="Criterion">
            <ChipRow value={test} onChange={(id) => setTest(id as Test)} options={[
              { id: "SSS", label: "SSS" }, { id: "SAS", label: "SAS" }, { id: "ASA", label: "ASA" },
              { id: "AAS", label: "AAS" }, { id: "RHS", label: "RHS" }, { id: "SSA", label: "SSA (not a test)" },
            ]} />
          </Field>
          {test === "SSS" ? (
            <>
              <SliderRow label="AB = DE" value={ab} min={2} max={8} step={0.1} onChange={setAb} />
              <SliderRow label="BC = EF" value={bc} min={2} max={8} step={0.1} onChange={setBc} />
              <SliderRow label="CA = FD" value={ca} min={2} max={8} step={0.1} onChange={setCa} />
            </>
          ) : null}
          {test === "SAS" ? (
            <>
              <SliderRow label="AB = DE" value={ab} min={2} max={8} step={0.1} onChange={setAb} />
              <SliderRow label="Included ∠A = ∠D" value={angA} min={20} max={120} step={1} onChange={setAngA} unit="°" />
              <SliderRow label="AC = DF" value={ca} min={2} max={8} step={0.1} onChange={setCa} />
            </>
          ) : null}
          {test === "ASA" ? (
            <>
              <SliderRow label="∠B = ∠E" value={angB} min={20} max={80} step={1} onChange={setAngB} unit="°" />
              <SliderRow label="Included AB = DE" value={ab} min={2} max={8} step={0.1} onChange={setAb} />
              <SliderRow label="∠A = ∠D" value={angA} min={20} max={80} step={1} onChange={setAngA} unit="°" />
            </>
          ) : null}
          {test === "AAS" ? (
            <>
              <SliderRow label="∠A = ∠D" value={angA} min={20} max={80} step={1} onChange={setAngA} unit="°" />
              <SliderRow label="∠B = ∠E" value={angB} min={20} max={80} step={1} onChange={setAngB} unit="°" />
              <SliderRow label="Non-included BC = EF" value={bc} min={2} max={8} step={0.1} onChange={setBc} />
            </>
          ) : null}
          {test === "RHS" ? (
            <>
              <SliderRow label="Hypotenuse" value={hyp} min={4} max={9} step={0.1} onChange={setHyp} />
              <SliderRow label="Leg" value={leg} min={1.5} max={Math.max(2, hyp - 0.4)} step={0.1} onChange={setLeg} />
            </>
          ) : null}
          {test === "SSA" ? (
            <>
              <SliderRow label="Non-included ∠A" value={ssaA} min={20} max={70} step={1} onChange={setSsaA} unit="°" />
              <SliderRow label="Opposite side a = BC" value={ssaAopp} min={1.6} max={6} step={0.1} onChange={setSsaAopp} />
              <SliderRow label="Adjacent side b = AC" value={ssaB} min={2} max={7} step={0.1} onChange={setSsaB} />
            </>
          ) : null}
          {test !== "SSA" ? <SliderRow label="Rotate △DEF" value={rot} min={-40} max={40} step={1} onChange={setRot} unit="°" /> : null}
          <Toggle checked={swap} onChange={setSwap}>Swap correspondence</Toggle>
          <Toggle checked={labels} onChange={setLabels}>Show measures</Toggle>
          {test === "SSA"
            ? <p className="tri-warn">SSA is not a congruence criterion. Two different triangles can share those data.</p>
            : <StatusOk>{congruent ? `△ABC ≅ △${map.A}${map.B}${map.C} by ${test}.` : "Adjust the given parts until the triangles match."}</StatusOk>}
        </Panel>
      }
      canvas={
        <GeometryLessonCanvas scene={triangleLessonScene(plane, [L, R], p => toSvg(plane, p))} ref={svgRef} viewBox={`0 0 ${plane.width} ${plane.height}`} role="img" aria-label={`Two corresponding triangles. ${test}${test === "SSA" ? " is not a congruence test." : congruent ? ` match.` : " parts not yet equal."}`}>
          <polygon points={polyPoints(plane, [L.A, L.B, L.C])} fill="rgba(20,125,242,.10)" stroke="#147df2" strokeWidth="2.1" />
          <polygon points={polyPoints(plane, [R.A, R.B, R.C])} fill="rgba(139,69,244,.10)" stroke="#8b45f4" strokeWidth="2.1" />
          <SideTickMark plane={plane} a={L.A} b={L.B} count={1} color="#147df2" />
          <SideTickMark plane={plane} a={R.A} b={R.B} count={1} color="#8b45f4" />
          <SideTickMark plane={plane} a={L.B} b={L.C} count={2} color="#147df2" />
          <SideTickMark plane={plane} a={R.B} b={R.C} count={2} color="#8b45f4" />
          <SideTickMark plane={plane} a={L.C} b={L.A} count={3} color="#147df2" />
          <SideTickMark plane={plane} a={R.C} b={R.A} count={3} color="#8b45f4" />
          <AngleArc plane={plane} vertex={L.A} p={L.B} q={L.C} ticks={1} color="#08b9dd" radius={20} />
          <AngleArc plane={plane} vertex={R.A} p={R.B} q={R.C} ticks={1} color="#c084fc" radius={20} />
          <AngleArc plane={plane} vertex={L.B} p={L.A} q={L.C} ticks={2} color="#147df2" radius={16} />
          <AngleArc plane={plane} vertex={R.B} p={R.A} q={R.C} ticks={2} color="#8b45f4" radius={16} />
          {test === "RHS" || Math.abs(triangleAngles(L.A, L.B, L.C).C - 90) < 2 ? (
            <>
              <RightAngleMarker plane={plane} vertex={L.C} p={L.A} q={L.B} />
              <RightAngleMarker plane={plane} vertex={R.C} p={R.A} q={R.B} />
            </>
          ) : null}
          {labels ? (
            <>
              <SideMeasurement plane={plane} a={L.A} b={L.B} text={`AB=${okNum(mL.sides.AB)}`} color="#147df2" />
              <SideMeasurement plane={plane} a={R.A} b={R.B} text={`${map.AB}=${okNum(mR.sides.AB)}`} color="#8b45f4" />
            </>
          ) : null}
          <g onPointerDown={startDrag("A")}><DraggableVertex plane={plane} p={L.A} label="A" /></g>
          <g onPointerDown={startDrag("B")}><DraggableVertex plane={plane} p={L.B} label="B" /></g>
          <g onPointerDown={startDrag("C")}><DraggableVertex plane={plane} p={L.C} label="C" /></g>
          <DraggableVertex plane={plane} p={R.A} label={map.A} color="#8b45f4" />
          <DraggableVertex plane={plane} p={R.B} label={map.B} color="#8b45f4" />
          <DraggableVertex plane={plane} p={R.C} label={map.C} color="#8b45f4" />
        </GeometryLessonCanvas>
      }
      insights={
        <InsightStack
          measurements={
            <>
              <MeasureRow label={`A ↔ ${map.A}`} value={`${okNum(mL.angles.A, 1)}° = ${okNum(mR.angles.A, 1)}°`} />
              <MeasureRow label={`B ↔ ${map.B}`} value={`${okNum(mL.angles.B, 1)}° = ${okNum(mR.angles.B, 1)}°`} color="#8b45f4" />
              <MeasureRow label={`C ↔ ${map.C}`} value={`${okNum(mL.angles.C, 1)}° = ${okNum(mR.angles.C, 1)}°`} color="#0f766e" />
              <MeasureRow label={`AB ↔ ${map.AB}`} value={`${okNum(mL.sides.AB)} = ${okNum(mR.sides.AB)}`} />
              <MeasureRow label={`BC ↔ ${map.BC}`} value={`${okNum(mL.sides.BC)} = ${okNum(mR.sides.BC)}`} color="#8b45f4" />
              <MeasureRow label={`CA ↔ ${map.CA}`} value={`${okNum(mL.sides.CA)} = ${okNum(mR.sides.CA)}`} color="#f59e0b" />
              <p className={test === "SSA" || !congruent ? "tri-warn" : "tri-ok"}>{test === "SSA" ? "SSA does not prove congruence." : congruent ? `Congruent by ${test}.` : "Not yet congruent."}</p>
            </>
          }
          property={<p className="tri-note">Corresponding vertices stay in order. Tick marks and arcs — not color alone — show which parts match.</p>}
          steps={proof()}
          formula={
            <FormulaCard
              title={test === "SSA" ? "Ambiguous case" : `${test} congruence`}
              formula={test === "SSA" ? "SSA ⇏ congruence" : `△ABC ≅ △${map.A}${map.B}${map.C}`}
              why={test === "SSA" ? "The opposite side can swing to a second intersection on the ray, so two non-congruent triangles can share the same SSA data." : "The listed parts determine a unique triangle up to rigid motion, so a matching copy is congruent."}
              tryThis={test === "SSA" ? "Change a until two distinct triangles appear." : "Rotate △DEF and watch the marked parts stay equal."}
            />
          }
          challenge={
            <ChallengeCard
              prompt="Construct a pair congruent by SAS."
              hint="Switch to SAS and keep the included angle between the two given sides."
              check={() => test === "SAS" && congruent}
              onReset={reset}
            />
          }
        />
      }
    />
  );
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { triangleLessonScene } from "../geometryLessonScene";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useRef, useState } from "react";
import { ChipRow, Field, Panel, Segmented, SliderRow } from "../../mockup/studioLabKit";
import {
  clampPoint,
  defaultPlane,
  toSvg,
  fromSvg,
  measureTriangle,
  rotateTriangle,
  scaleTriangle,
  sideRatios,
  translateTriangle,
  triangleArea,
} from "./triangleGeometry";
import { ChallengeCard, FormulaCard, InsightStack, LabFrame, MeasureRow, Toggle, okNum } from "./triangleLabKit";
import {
  AngleArc,
  DraggableVertex,
  SideMeasurement,
  SideTickMark,
  bindSvgDrag,
  pointerToSvg,
  polyPoints,
} from "./triangleSvgPrimitives";

type Crit = "AA" | "SAS" | "SSS";

export default function SimilarityLab({ pulse = "observe" }: { pulse?: string }) {
  const plane = defaultPlane();
  const svgRef = useRef<SVGSVGElement>(null);
  const drag = useRef<"A" | "B" | "C" | null>(null);
  const [base, setBase] = useStudioState("SimilarityLab:SimilarityLab:base", { A: { x: 3.4, y: 5.4 }, B: { x: 1.5, y: 1.5 }, C: { x: 6.6, y: 1.7 } });
  const [k, setK] = useStudioState("SimilarityLab:SimilarityLab:k", 1.5);
  const [rot, setRot] = useStudioState("SimilarityLab:SimilarityLab:rot", 12);
  const [shiftX, setShiftX] = useStudioState("SimilarityLab:SimilarityLab:shiftX", 8.4);
  const [shiftY, setShiftY] = useStudioState("SimilarityLab:SimilarityLab:shiftY", 0.15);
  const [crit, setCrit] = useStudioState<Crit>("SimilarityLab:SimilarityLab:crit", "AA");
  const [showRatios, setShowRatios] = useState(true);

  const def = useMemo(() => {
    const scaled = scaleTriangle(base, k, base.B);
    const rotated = rotateTriangle(scaled, scaled.B, rot);
    return translateTriangle(rotated, { x: shiftX - scaled.B.x + base.B.x, y: shiftY });
  }, [base, k, rot, shiftX, shiftY]);

  const m1 = measureTriangle(base.A, base.B, base.C);
  const m2 = measureTriangle(def.A, def.B, def.C);
  const ratios = sideRatios(base, def);
  const kind = k === 1 ? "Congruent" : k > 1 ? "Enlargement" : "Reduction";

  const startDrag = (who: "A" | "B" | "C") => (event: React.PointerEvent) => {
    event.preventDefault();
    drag.current = who;
    bindSvgDrag(svgRef, (ev) => {
      const svg = svgRef.current;
      if (!svg || !drag.current) return;
      const s = pointerToSvg(svg, ev);
      const next = clampPoint(fromSvg(plane, s.x, s.y), 0.5, 9.4, 0.4, 11);
      setBase((prev) => {
        const draft = { ...prev, [drag.current!]: next };
        return triangleArea(draft.A, draft.B, draft.C) < 0.4 ? prev : draft;
      });
    }, () => { drag.current = null; });
  };

  const reset = () => {
    setBase({ A: { x: 3.4, y: 5.4 }, B: { x: 1.5, y: 1.5 }, C: { x: 6.6, y: 1.7 } }); setK(1.5); setRot(12); setShiftX(8.4); setShiftY(0.15); setCrit("AA");
  };

  useEffect(() => {
    if (pulse === "observe") setCrit("AA");
    if (pulse === "understand") setCrit("SSS");
    if (pulse === "why") { setShowRatios(true); setK(2); }
    if (pulse === "try" || pulse === "challenge") setK(1.5);
  }, [pulse]);

  return (
    <LabFrame
      theme="similarity"
      ariaLabel="Similarity laboratory"
      controls={
        <Panel title="Similarity controls">
          <Field label="Criterion">
            <Segmented value={crit} onChange={(id) => setCrit(id as Crit)} options={[
              { id: "AA", label: "AA" }, { id: "SAS", label: "SAS ~" }, { id: "SSS", label: "SSS ~" },
            ]} />
          </Field>
          <SliderRow label="Scale factor k" value={k} min={0.25} max={3} step={0.05} onChange={setK} />
          <Field label="Presets">
            <ChipRow value={String(k)} onChange={(id) => setK(Number(id))} options={[
              { id: "0.5", label: "Half" }, { id: "1", label: "Same size" }, { id: "1.5", label: "1.5×" }, { id: "2", label: "Double" },
            ]} />
          </Field>
          <SliderRow label="Rotation" value={rot} min={-60} max={60} step={1} onChange={setRot} unit="°" />
          <SliderRow label="Translate x" value={shiftX} min={6} max={12} step={0.1} onChange={setShiftX} />
          <Toggle checked={showRatios} onChange={setShowRatios}>Show ratios</Toggle>
          <p className="tri-note">{kind}: k = {okNum(k, 2)}. Perimeter ratio = k. Area ratio = k² = {okNum(k * k, 2)}.</p>
        </Panel>
      }
      canvas={
        <GeometryLessonCanvas onPointChange={(id, point) => { if (id === "A" || id === "B" || id === "C") setBase(current => ({ ...current, [id]: fromSvg(plane, point.x, point.y) })); }} scene={triangleLessonScene(plane, [base, def], p => toSvg(plane, p))} ref={svgRef} viewBox={`0 0 ${plane.width} ${plane.height}`} role="img" aria-label="Similar triangles ABC and DEF">
          <polygon points={polyPoints(plane, [base.A, base.B, base.C])} fill="rgba(20,125,242,.10)" stroke="#147df2" strokeWidth="2.1" />
          <polygon points={polyPoints(plane, [def.A, def.B, def.C])} fill="rgba(139,69,244,.10)" stroke="#8b45f4" strokeWidth="2.1" />
          <SideTickMark plane={plane} a={base.A} b={base.B} count={1} />
          <SideTickMark plane={plane} a={def.A} b={def.B} count={1} color="#8b45f4" />
          <SideTickMark plane={plane} a={base.B} b={base.C} count={2} />
          <SideTickMark plane={plane} a={def.B} b={def.C} count={2} color="#8b45f4" />
          <AngleArc plane={plane} vertex={base.A} p={base.B} q={base.C} color="#08b9dd" />
          <AngleArc plane={plane} vertex={def.A} p={def.B} q={def.C} color="#c084fc" />
          {showRatios ? (
            <>
              <SideMeasurement plane={plane} a={base.A} b={base.B} text={`AB=${okNum(m1.sides.AB)}`} color="#147df2" />
              <SideMeasurement plane={plane} a={def.A} b={def.B} text={`DE=${okNum(m2.sides.AB)}`} color="#8b45f4" />
            </>
          ) : null}
          <g onPointerDown={startDrag("A")}><DraggableVertex plane={plane} p={base.A} label="A" /></g>
          <g onPointerDown={startDrag("B")}><DraggableVertex plane={plane} p={base.B} label="B" /></g>
          <g onPointerDown={startDrag("C")}><DraggableVertex plane={plane} p={base.C} label="C" /></g>
          <DraggableVertex plane={plane} p={def.A} label="D" color="#8b45f4" />
          <DraggableVertex plane={plane} p={def.B} label="E" color="#8b45f4" />
          <DraggableVertex plane={plane} p={def.C} label="F" color="#8b45f4" />
        </GeometryLessonCanvas>
      }
      insights={
        <InsightStack
          measurements={
            <>
              <MeasureRow label="k = DE/AB" value={okNum(ratios.DE_AB, 3)} />
              <MeasureRow label="EF/BC" value={okNum(ratios.EF_BC, 3)} color="#8b45f4" />
              <MeasureRow label="DF/AC" value={okNum(ratios.DF_AC, 3)} color="#0f766e" />
              <MeasureRow label="Perimeter ratio" value={okNum(m2.perimeter / m1.perimeter, 3)} />
              <MeasureRow label="Area ratio" value={okNum(m2.area / m1.area, 3)} color="#f59e0b" />
              <MeasureRow label="∠A = ∠D" value={`${okNum(m1.angles.A, 1)}° = ${okNum(m2.angles.A, 1)}°`} />
              <MeasureRow label="∠B = ∠E" value={`${okNum(m1.angles.B, 1)}° = ${okNum(m2.angles.B, 1)}°`} color="#8b45f4" />
              <MeasureRow label="∠C = ∠F" value={`${okNum(m1.angles.C, 1)}° = ${okNum(m2.angles.C, 1)}°`} color="#f59e0b" />
              <p className="tri-ok">△ABC ~ △DEF by {crit === "AA" ? "AA" : crit === "SAS" ? "SAS similarity" : "SSS similarity"}.</p>
            </>
          }
          property={<p className="tri-note">Corresponding angles stay equal. All three side ratios converge to the same k. Area scales by k².</p>}
          formula={
            <FormulaCard
              title="Similarity"
              formula="Area ratio = k²"
              why="Each linear size is multiplied by k, so the parallelogram (or ½bh) area is multiplied by k·k."
              tryThis="Set k = 1.5 and confirm DE/AB = EF/BC = DF/AC."
            />
          }
          challenge={
            <ChallengeCard
              prompt="Make △DEF exactly 1.5× △ABC."
              hint="Use the 1.5× preset, then drag ABC if you want a new base triangle."
              check={() => Math.abs(k - 1.5) < 0.03 && Math.abs(ratios.DE_AB - 1.5) < 0.05}
              onReset={reset}
            />
          }
        />
      }
    />
  );
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { triangleLessonScene } from "../geometryLessonScene";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useRef, useState } from "react";
import { ChipRow, Field, Panel } from "../../mockup/studioLabKit";
import {
  EXPLORER_PRESETS,
  altitudeFoot,
  angleBisectorDir,
  centroid,
  circumcenter,
  circumcenterLocation,
  clampPoint,
  defaultPlane,
  dist,
  fromSvg,
  incenter,
  inradius,
  lineIntersection,
  measureTriangle,
  midpoint,
  orthocenter,
  orthocenterLocation,
  perpDistance,
  perpendicularBisector,
  toSvg,
  triangleArea,
  add,
  scale,
  unit,
} from "./triangleGeometry";
import { ChallengeCard, FormulaCard, InsightStack, LabFrame, MeasureRow, Toggle, okNum } from "./triangleLabKit";
import {
  CenterDot,
  DashedLine,
  DraggableVertex,
  GridLayer,
  RightAngleMarker,
  SolidLine,
  bindSvgDrag,
  pointerToSvg,
  polyPoints,
} from "./triangleSvgPrimitives";

type CenterMode = "centroid" | "circumcenter" | "incenter" | "orthocenter" | "all";

export default function TriangleCentersLab({ pulse = "observe" }: { pulse?: string }) {
  const plane = defaultPlane();
  const svgRef = useRef<SVGSVGElement>(null);
  const drag = useRef<"A" | "B" | "C" | null>(null);
  const [tri, setTri] = useStudioState("TriangleCentersLab:TriangleCentersLab:tri", EXPLORER_PRESETS.acute);
  const [mode, setMode] = useState<CenterMode>("centroid");
  const [advanced, setAdvanced] = useStudioState("TriangleCentersLab:TriangleCentersLab:advanced", false);
  const [grid, setGrid] = useStudioState("TriangleCentersLab:TriangleCentersLab:grid", false);
  const [showCircle, setShowCircle] = useState(true);
  const [showIncircle, setShowIncircle] = useState(true);

  const geo = useMemo(() => {
    const { A, B, C } = tri;
    const G = centroid(A, B, C);
    const O = circumcenter(A, B, C);
    const I = incenter(A, B, C);
    const H = orthocenter(A, B, C);
    const Ma = midpoint(B, C);
    const Mb = midpoint(A, C);
    const Mc = midpoint(A, B);
    const Fa = altitudeFoot(A, B, C);
    const Fb = altitudeFoot(B, A, C);
    const Fc = altitudeFoot(C, A, B);
    const r = inradius(A, B, C);
    return { A, B, C, G, O, I, H, Ma, Mb, Mc, Fa, Fb, Fc, r, m: measureTriangle(A, B, C) };
  }, [tri]);

  const startDrag = (who: "A" | "B" | "C") => (event: React.PointerEvent) => {
    event.preventDefault();
    drag.current = who;
    bindSvgDrag(svgRef, (ev) => {
      const svg = svgRef.current;
      if (!svg || !drag.current) return;
      const s = pointerToSvg(svg, ev);
      const next = clampPoint(fromSvg(plane, s.x, s.y));
      setTri((prev) => {
        const draft = { ...prev, [drag.current!]: next };
        return triangleArea(draft.A, draft.B, draft.C) < 0.4 ? prev : draft;
      });
    }, () => { drag.current = null; });
  };

  const show = (id: CenterMode) => mode === "all" || mode === id;
  const N = geo.O && geo.H ? { x: (geo.O.x + geo.H.x) / 2, y: (geo.O.y + geo.H.y) / 2 } : null;
  const og = geo.O ? dist(geo.O, geo.G) : 0;
  const gh = geo.H ? dist(geo.G, geo.H) : 0;
  const circLoc = circumcenterLocation(geo.A, geo.B, geo.C);
  const orthLoc = orthocenterLocation(geo.A, geo.B, geo.C);
  const oSvg = geo.O ? toSvg(plane, geo.O) : null;
  const iSvg = toSvg(plane, geo.I);
  const R = geo.O ? dist(geo.O, geo.A) : 0;
  const bisA = lineIntersection(geo.A, angleBisectorDir(geo.A, geo.B, geo.C), geo.B, { x: geo.C.x - geo.B.x, y: geo.C.y - geo.B.y });
  const bisB = lineIntersection(geo.B, angleBisectorDir(geo.B, geo.A, geo.C), geo.C, { x: geo.A.x - geo.C.x, y: geo.A.y - geo.C.y });
  const bisC = lineIntersection(geo.C, angleBisectorDir(geo.C, geo.A, geo.B), geo.A, { x: geo.B.x - geo.A.x, y: geo.B.y - geo.A.y });
  const pbAB = perpendicularBisector(geo.A, geo.B);
  const pbBC = perpendicularBisector(geo.B, geo.C);
  const pbCA = perpendicularBisector(geo.C, geo.A);
  const ray = (pb: { point: { x: number; y: number }; dir: { x: number; y: number } }) => {
    const u = unit(pb.dir);
    return { a: add(pb.point, scale(u, -8)), b: add(pb.point, scale(u, 8)) };
  };
  const pAB = ray(pbAB);
  const pBC = ray(pbBC);
  const pCA = ray(pbCA);
  const footIbc = altitudeFoot(geo.I, geo.B, geo.C);
  const footIca = altitudeFoot(geo.I, geo.C, geo.A);
  const footIab = altitudeFoot(geo.I, geo.A, geo.B);

  const reset = () => { setTri(EXPLORER_PRESETS.acute); setMode("centroid"); setAdvanced(false); };

  useEffect(() => {
    if (pulse === "observe") setMode("centroid");
    if (pulse === "understand") setMode("circumcenter");
    if (pulse === "why") { setMode("all"); setAdvanced(true); }
    if (pulse === "try" || pulse === "challenge") {
      setMode("circumcenter");
      setTri(EXPLORER_PRESETS.obtuse ?? EXPLORER_PRESETS.acute);
    }
  }, [pulse]);

  return (
    <LabFrame
      theme="centers"
      ariaLabel="Triangle centers laboratory"
      controls={
        <Panel title="Centers">
          <Field label="Construction">
            <ChipRow value={mode} onChange={(id) => setMode(id as CenterMode)} options={[
              { id: "centroid", label: "Centroid" },
              { id: "circumcenter", label: "Circumcenter" },
              { id: "incenter", label: "Incenter" },
              { id: "orthocenter", label: "Orthocenter" },
              { id: "all", label: "All / Euler" },
            ]} />
          </Field>
          <Field label="Presets">
            <ChipRow value="" onChange={(id) => setTri(EXPLORER_PRESETS[id])} options={["acute", "right", "obtuse", "equilateral"].map((id) => ({ id, label: id[0].toUpperCase() + id.slice(1) }))} />
          </Field>
          <Toggle checked={showCircle} onChange={setShowCircle}>Circumcircle</Toggle>
          <Toggle checked={showIncircle} onChange={setShowIncircle}>Incircle</Toggle>
          <Toggle checked={grid} onChange={setGrid}>Grid</Toggle>
          <Toggle checked={advanced} onChange={setAdvanced}>Show advanced construction</Toggle>
        </Panel>
      }
      canvas={
        <GeometryLessonCanvas activityId={`centers-${mode}`} onPointChange={(id, point) => { if (id === "A" || id === "B" || id === "C") setTri(current => ({ ...current, [id]: fromSvg(plane, point.x, point.y) })); }} scene={triangleLessonScene(plane, [tri], p => toSvg(plane, p))} ref={svgRef} viewBox={`0 0 ${plane.width} ${plane.height}`} role="img" aria-label={`Triangle centers construction. Circumcenter O is ${circLoc}.`}>
          {grid ? <GridLayer plane={plane} /> : null}
          <polygon points={polyPoints(plane, [geo.A, geo.B, geo.C])} fill="rgba(20,125,242,.08)" stroke="#147df2" strokeWidth="2.1" />
          {show("centroid") ? (
            <>
              <SolidLine plane={plane} a={geo.A} b={geo.Ma} color="#10b981" />
              <SolidLine plane={plane} a={geo.B} b={geo.Mb} color="#10b981" />
              <SolidLine plane={plane} a={geo.C} b={geo.Mc} color="#10b981" />
              <CenterDot plane={plane} p={geo.G} label="G" color="#10b981" />
            </>
          ) : null}
          {show("circumcenter") && geo.O ? (
            <>
              <DashedLine plane={plane} a={pAB.a} b={pAB.b} color="#64748b" />
              <DashedLine plane={plane} a={pBC.a} b={pBC.b} color="#64748b" />
              <DashedLine plane={plane} a={pCA.a} b={pCA.b} color="#64748b" />
              {showCircle && oSvg ? <circle cx={oSvg.x} cy={oSvg.y} r={R * plane.unit} fill="none" stroke="#147df2" strokeWidth="1.3" /> : null}
              <CenterDot plane={plane} p={geo.O} label="O" color="#147df2" />
            </>
          ) : null}
          {show("incenter") ? (
            <>
              {bisA ? <SolidLine plane={plane} a={geo.A} b={bisA} color="#d97706" width={1.3} /> : null}
              {bisB ? <SolidLine plane={plane} a={geo.B} b={bisB} color="#d97706" width={1.3} /> : null}
              {bisC ? <SolidLine plane={plane} a={geo.C} b={bisC} color="#d97706" width={1.3} /> : null}
              <DashedLine plane={plane} a={geo.I} b={footIbc} color="#d97706" />
              <DashedLine plane={plane} a={geo.I} b={footIca} color="#d97706" />
              <DashedLine plane={plane} a={geo.I} b={footIab} color="#d97706" />
              {showIncircle ? <circle cx={iSvg.x} cy={iSvg.y} r={geo.r * plane.unit} fill="rgba(245,158,11,.08)" stroke="#d97706" strokeWidth="1.4" /> : null}
              <CenterDot plane={plane} p={footIbc} label="" color="#d97706" />
              <CenterDot plane={plane} p={footIca} label="" color="#d97706" />
              <CenterDot plane={plane} p={footIab} label="" color="#d97706" />
              <CenterDot plane={plane} p={geo.I} label="I" color="#d97706" />
            </>
          ) : null}
          {show("orthocenter") ? (
            <>
              <DashedLine plane={plane} a={geo.A} b={geo.Fa} />
              <DashedLine plane={plane} a={geo.B} b={geo.Fb} />
              <DashedLine plane={plane} a={geo.C} b={geo.Fc} />
              <RightAngleMarker plane={plane} vertex={geo.Fa} p={geo.A} q={geo.B} />
              <RightAngleMarker plane={plane} vertex={geo.Fb} p={geo.B} q={geo.A} />
              <RightAngleMarker plane={plane} vertex={geo.Fc} p={geo.C} q={geo.A} />
              {geo.H ? <CenterDot plane={plane} p={geo.H} label="H" color="#8b45f4" /> : null}
            </>
          ) : null}
          {mode === "all" && geo.O && geo.H ? (
            <>
              <DashedLine plane={plane} a={geo.O} b={geo.H} color="#334155" />
              {advanced && N ? <CenterDot plane={plane} p={N} label="N" color="#64748b" /> : null}
            </>
          ) : null}
          <g onPointerDown={startDrag("A")}><DraggableVertex plane={plane} p={geo.A} label="A" /></g>
          <g onPointerDown={startDrag("B")}><DraggableVertex plane={plane} p={geo.B} label="B" /></g>
          <g onPointerDown={startDrag("C")}><DraggableVertex plane={plane} p={geo.C} label="C" /></g>
        </GeometryLessonCanvas>
      }
      insights={
        <InsightStack
          measurements={
            <>
              <MeasureRow label="Centroid G" value={`(${okNum(geo.G.x)}, ${okNum(geo.G.y)})`} color="#10b981" />
              {geo.O ? <MeasureRow label="Circumcenter O" value={`(${okNum(geo.O.x)}, ${okNum(geo.O.y)}) · ${circLoc}`} /> : null}
              <MeasureRow label="Incenter I" value={`(${okNum(geo.I.x)}, ${okNum(geo.I.y)})`} color="#d97706" />
              {geo.H ? <MeasureRow label="Orthocenter H" value={`(${okNum(geo.H.x)}, ${okNum(geo.H.y)}) · ${orthLoc}`} color="#8b45f4" /> : null}
              <MeasureRow label="AG : GM" value={okNum(dist(geo.A, geo.G) / dist(geo.G, geo.Ma), 2) + " : 1"} color="#10b981" />
              {geo.O ? <MeasureRow label="OA = OB = OC" value={okNum(R)} /> : null}
              <MeasureRow label="Inradius r" value={okNum(geo.r)} color="#d97706" />
              <MeasureRow label="dist(I, BC)" value={okNum(perpDistance(geo.I, geo.B, geo.C))} color="#d97706" />
              {mode === "all" ? <MeasureRow label="OG : GH" value={`${okNum(og)} : ${okNum(gh)}`} /> : null}
            </>
          }
          property={
            <p className="tri-note">
              {mode === "centroid" && "Medians meet at G and each is divided 2:1 (vertex to midpoint)."}
              {mode === "circumcenter" && `O is ${circLoc}. Acute → inside, right → hypotenuse midpoint, obtuse → outside.`}
              {mode === "incenter" && "Angle bisectors meet at I. Perpendicular distances to the sides equal the inradius."}
              {mode === "orthocenter" && `H is ${orthLoc}. Right triangles put H at the right-angle vertex.`}
              {mode === "all" && "Euler line: H, G, O are collinear with OG : GH = 1 : 2 (non-equilateral)."}
            </p>
          }
          formula={
            <FormulaCard
              title={mode === "centroid" ? "Centroid" : mode === "all" ? "Euler line" : mode}
              formula={mode === "centroid" ? "AG : GM = 2 : 1" : mode === "all" ? "OG : GH = 1 : 2" : mode === "incenter" ? "r = Area / s" : mode === "circumcenter" ? "OA = OB = OC = R" : "Altitudes concur at H"}
              why="Each center is the unique concurrence of a family of lines (medians, perp. bisectors, angle bisectors, or altitudes)."
              tryThis={mode === "circumcenter" ? "Drag to an obtuse triangle and watch O leave the triangle." : "Drag a vertex and keep the concurrence."}
            />
          }
          challenge={
            <ChallengeCard
              prompt="Move the triangle until the circumcenter lies outside."
              hint="Make one angle obtuse — O jumps outside, opposite the obtuse vertex."
              check={() => circLoc === "outside"}
              onReset={reset}
            />
          }
        />
      }
    />
  );
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { triangleLessonScene } from "../geometryLessonScene";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useRef } from "react";
import { useSearchParams } from "react-router-dom";
import { useReducedMotion } from "../../../hooks/useReducedMotion";
import { ChipRow, Field, Panel, Segmented } from "../../mockup/studioLabKit";
import { useGeoLabUi } from "../geometryLabUx";
import { readGeoSession, writeGeoSession } from "../geometryStudioSession";
import {
  EXPLORER_PRESETS,
  altitudeFoot,
  angleBisectorDir,
  clampPoint,
  defaultPlane,
  fromSvg,
  lineIntersection,
  measureTriangle,
  midpoint,
  perpendicularBisector,
  toSvg,
  triangleArea,
  triangleInequality,
  type TrianglePts,
} from "./triangleGeometry";
import {
  applyLock,
  encodeLayers,
  encodeTriangle,
  nudgePoint,
  parseLayers,
  parseSnap,
  parseTriangle,
  setSideLength,
  snapPoint,
  type LockMode,
  type SnapMode,
} from "./triangleFigureState";
import { ChallengeCard, FormulaCard, InsightStack, LabFrame, MeasureRow, Toggle, okNum } from "./triangleLabKit";
import {
  AngleArc,
  DashedLine,
  DraggableVertex,
  GridLayer,
  RightAngleMarker,
  SideMeasurement,
  SolidLine,
  bindSvgDrag,
  pointerToSvg,
  polyPoints,
} from "./triangleSvgPrimitives";

type Sub = "explore" | "area" | "angles" | "special" | "invariants";
type Base = "AB" | "BC" | "CA";

const SPECIAL: Record<string, TrianglePts> = {
  "30-60-90": { B: { x: 2, y: 1.6 }, C: { x: 2 + 4 * Math.sqrt(3), y: 1.6 }, A: { x: 2, y: 5.6 } },
  "45-45-90": { B: { x: 2.4, y: 1.6 }, C: { x: 8.4, y: 1.6 }, A: { x: 2.4, y: 7.6 } },
  "3-4-5": { B: { x: 2, y: 1.5 }, C: { x: 6, y: 1.5 }, A: { x: 2, y: 4.5 } },
};

const PRESET_IDS = ["scalene", "isosceles", "equilateral", "right", "acute", "obtuse"] as const;

function PresetThumb({ id }: { id: string }) {
  const tri = EXPLORER_PRESETS[id] ?? EXPLORER_PRESETS.scalene;
  const pts = [tri.A, tri.B, tri.C].map((p) => `${8 + p.x * 3},${40 - p.y * 3}`).join(" ");
  return (
    <span className="tri-preset-thumb">
      <svg viewBox="0 0 48 44" aria-hidden="true"><polygon points={pts} fill="#dbeafe" stroke="#147df2" strokeWidth="1.4" /></svg>
      {id[0]!.toUpperCase() + id.slice(1)}
    </span>
  );
}

export default function TriangleExplorerLab({ pulse = "observe" }: { pulse?: string }) {
  const reducedMotion = useReducedMotion();
  const ui = useGeoLabUi();
  const plane = defaultPlane();
  const svgRef = useRef<SVGSVGElement>(null);
  const drag = useRef<"A" | "B" | "C" | null>(null);
  const triRef = useRef<TrianglePts>(EXPLORER_PRESETS.scalene);
  const panDrag = useRef<{ x: number; y: number; panX: number; panY: number } | null>(null);
  const [params, setParams] = useSearchParams();
  const [tri, setTri] = useStudioState<TrianglePts>("TriangleExplorerLab:TriangleExplorerLab:tri", () => parseTriangle(params.get("t")) ?? EXPLORER_PRESETS.scalene);
  const [preset, setPreset] = useStudioState("TriangleExplorerLab:TriangleExplorerLab:preset", "scalene");
  const [sub, setSub] = useStudioState<Sub>("TriangleExplorerLab:TriangleExplorerLab:sub", "explore");
  const [base, setBase] = useStudioState<Base>("TriangleExplorerLab:TriangleExplorerLab:base", "BC");
  const [layers, setLayers] = useStudioState("TriangleExplorerLab:TriangleExplorerLab:layers", () => parseLayers(params.get("layers")) ?? {
    sides: true, angles: true, altitudes: false, median: false, bisector: false, perp: false, grid: true, coords: false, arcs: true,
  });
  const [anim, setAnim] = useStudioState("TriangleExplorerLab:TriangleExplorerLab:anim", false);
  const [areaFormula, setAreaFormula] = useStudioState("TriangleExplorerLab:TriangleExplorerLab:areaFormula", "bh");
  const [snap, setSnap] = useStudioState<SnapMode>("TriangleExplorerLab:TriangleExplorerLab:snap", () => parseSnap(params.get("snap")));
  const [lock, setLock] = useStudioState<LockMode>("TriangleExplorerLab:TriangleExplorerLab:lock", "none");
  const [selected, setSelected] = useStudioState<"A" | "B" | "C">("TriangleExplorerLab:TriangleExplorerLab:selected", "C");
  const [history, setHistory] = useStudioState<TrianglePts[]>("TriangleExplorerLab:TriangleExplorerLab:history", [parseTriangle(params.get("t")) ?? EXPLORER_PRESETS.scalene]);
  const [histIndex, setHistIndex] = useStudioState("TriangleExplorerLab:TriangleExplorerLab:histIndex", 0);
  const [coach, setCoach] = useStudioState("TriangleExplorerLab:TriangleExplorerLab:coach", () => !readGeoSession().coachDismissed);
  const [warn, setWarn] = useStudioState("TriangleExplorerLab:TriangleExplorerLab:warn", "");

  const m = useMemo(() => measureTriangle(tri.A, tri.B, tri.C), [tri]);
  const reference = useMemo(() => measureTriangle(SPECIAL["3-4-5"].A, SPECIAL["3-4-5"].B, SPECIAL["3-4-5"].C), []);
  const inequality = triangleInequality(m.sides.AB, m.sides.BC, m.sides.CA);
  const close = (a: number, b: number, tolerance = 0.15) => Math.abs(a - b) <= tolerance;
  const congruence = {
    SSS: close(m.sides.AB, reference.sides.AB) && close(m.sides.BC, reference.sides.BC) && close(m.sides.CA, reference.sides.CA),
    SAS: close(m.sides.AB, reference.sides.AB) && close(m.sides.BC, reference.sides.BC) && close(m.angles.B, reference.angles.B, 2),
    ASA: close(m.angles.A, reference.angles.A, 2) && close(m.angles.B, reference.angles.B, 2) && close(m.sides.AB, reference.sides.AB),
  };
  triRef.current = tri;
  const basePts = base === "AB" ? [tri.A, tri.B, tri.C] : base === "BC" ? [tri.B, tri.C, tri.A] : [tri.C, tri.A, tri.B];
  const foot = altitudeFoot(basePts[2], basePts[0], basePts[1]);
  const height = Math.hypot(basePts[2].x - foot.x, basePts[2].y - foot.y);
  const baseLen = Math.hypot(basePts[1].x - basePts[0].x, basePts[1].y - basePts[0].y);
  const midBC = midpoint(tri.B, tri.C);
  const footA = altitudeFoot(tri.A, tri.B, tri.C);
  const footB = altitudeFoot(tri.B, tri.A, tri.C);
  const footC = altitudeFoot(tri.C, tri.A, tri.B);
  const aSvg = toSvg(plane, tri.A);
  const bSvg = toSvg(plane, tri.B);
  const cSvg = toSvg(plane, tri.C);
  const bis = lineIntersection(tri.A, angleBisectorDir(tri.A, tri.B, tri.C), tri.B, { x: tri.C.x - tri.B.x, y: tri.C.y - tri.B.y });
  const pb = perpendicularBisector(tri.B, tri.C);
  const hover = ui?.highlight;

  const commit = (next: TrianglePts, fromHistory = false) => {
    setTri(next);
    if (fromHistory) return;
    setHistory((stack) => {
      const clipped = stack.slice(0, histIndex + 1);
      const merged = [...clipped, next].slice(-40);
      setHistIndex(merged.length - 1);
      return merged;
    });
  };

  useEffect(() => {
    setParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set("t", encodeTriangle(tri));
      next.set("layers", encodeLayers(layers));
      if (snap === "off") next.delete("snap");
      else next.set("snap", snap);
      return next;
    }, { replace: true });
  }, [layers, setParams, snap, tri]);

  useEffect(() => {
    if (!anim || reducedMotion) return;
    const origin = { ...tri.C };
    let t = 0;
    let id = 0;
    const tick = () => {
      t += 0.018;
      setTri((prev) => ({ ...prev, C: clampPoint({ x: origin.x + Math.sin(t) * 1.8, y: origin.y + Math.cos(t * 0.7) * 0.35 }) }));
      id = requestAnimationFrame(tick);
    };
    id = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(id);
  }, [anim, reducedMotion]);

  useEffect(() => {
    if (pulse === "why") setSub("area");
    if (pulse === "observe") setSub("explore");
    if (pulse === "understand") {
      setSub("angles");
      setAnim(false);
    }
    if (pulse === "try") {
      setPreset("isosceles");
      commit(EXPLORER_PRESETS.isosceles ?? EXPLORER_PRESETS.scalene);
      setAnim(false);
    }
    if (pulse === "challenge") {
      setSub("angles");
      document.getElementById("tri-challenge")?.scrollIntoView({ block: "nearest" });
    }
  }, [pulse]);

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (target && /input|textarea|select/i.test(target.tagName)) return;
      const step = event.shiftKey ? 0.4 : 0.15;
      if (event.key === "ArrowLeft") { event.preventDefault(); commit({ ...tri, [selected]: nudgePoint(tri[selected], -step, 0) }); }
      if (event.key === "ArrowRight") { event.preventDefault(); commit({ ...tri, [selected]: nudgePoint(tri[selected], step, 0) }); }
      if (event.key === "ArrowUp") { event.preventDefault(); commit({ ...tri, [selected]: nudgePoint(tri[selected], 0, step) }); }
      if (event.key === "ArrowDown") { event.preventDefault(); commit({ ...tri, [selected]: nudgePoint(tri[selected], 0, -step) }); }
      if ((event.key === "z" || event.key === "Z") && !event.ctrlKey && !event.metaKey) undo();
      if ((event.key === "y" || event.key === "Y") && !event.ctrlKey && !event.metaKey) redo();
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "z") { event.preventDefault(); undo(); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [selected, tri]);

  const applyPreset = (id: string) => {
    setPreset(id);
    setAnim(false);
    commit(EXPLORER_PRESETS[id] ?? EXPLORER_PRESETS.scalene);
  };

  const undo = () => {
    const next = Math.max(0, histIndex - 1);
    const item = history[next];
    if (!item) return;
    setHistIndex(next);
    setTri(item);
  };

  const redo = () => {
    const next = Math.min(history.length - 1, histIndex + 1);
    const item = history[next];
    if (!item) return;
    setHistIndex(next);
    setTri(item);
  };

  const startDrag = (who: "A" | "B" | "C") => (event: React.PointerEvent) => {
    event.preventDefault();
    event.stopPropagation();
    drag.current = who;
    setSelected(who);
    setPreset("custom");
    setAnim(false);
    bindSvgDrag(svgRef, (ev) => {
      const svg = svgRef.current;
      if (!svg || !drag.current) return;
      const s = pointerToSvg(svg, ev);
      const raw = snapPoint(clampPoint(fromSvg(plane, s.x, s.y)), snap, who === "C" ? triRef.current.B : triRef.current.A);
      setTri((prev) => {
        const draft = applyLock(prev, drag.current!, raw, lock);
        if (triangleArea(draft.A, draft.B, draft.C) < 0.35) {
          setWarn("That drag would collapse the triangle.");
          ui?.announce("That would collapse the triangle.");
          return prev;
        }
        setWarn("");
        return draft;
      });
    }, () => {
      drag.current = null;
      commit(triRef.current);
    });
  };

  const startPan = (event: React.PointerEvent) => {
    if ((event.target as Element).closest(".tri-vertex")) return;
    panDrag.current = { x: event.clientX, y: event.clientY, panX: ui?.panX ?? 0, panY: ui?.panY ?? 0 };
    const move = (ev: PointerEvent) => {
      if (!panDrag.current) return;
      ui?.setPan(panDrag.current.panX - (ev.clientX - panDrag.current.x), panDrag.current.panY - (ev.clientY - panDrag.current.y));
    };
    const up = () => {
      panDrag.current = null;
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", onUp);
    };
    const onUp = up;
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", onUp);
  };

  const reset = () => applyPreset("scalene");
  const zoom = ui?.zoom ?? 1;
  const vw = plane.width / zoom;
  const vh = plane.height / zoom;
  const vx = (plane.width - vw) / 2 + (ui?.panX ?? 0);
  const vy = (plane.height - vh) / 2 + (ui?.panY ?? 0);
  const showUnfold = pulse === "understand" || sub === "angles";
  const svgLabel = `Draggable triangle ABC. AB ${okNum(m.sides.AB)}, BC ${okNum(m.sides.BC)}, CA ${okNum(m.sides.CA)}. Angles ${okNum(m.angles.A, 1)}°, ${okNum(m.angles.B, 1)}°, ${okNum(m.angles.C, 1)}°.`;

  const setCoord = (who: "A" | "B" | "C", axis: "x" | "y", value: number) => {
    const next = { ...tri, [who]: { ...tri[who], [axis]: value } };
    if (triangleArea(next.A, next.B, next.C) < 0.35) {
      setWarn("Those coordinates would collapse the triangle.");
      return;
    }
    setPreset("custom");
    commit(next);
  };

  return (
    <LabFrame
      theme="explorer"
      ariaLabel="Triangle explorer"
      tools={(
        <>
          <button type="button" className="msk-soft" onClick={undo} aria-label="Undo vertex move">Undo</button>
          <button type="button" className="msk-soft" onClick={redo} aria-label="Redo vertex move">Redo</button>
        </>
      )}
      controls={
        <Panel title="Explorer controls">
          <Field label="Focus">
            <Segmented value={sub} onChange={(id) => setSub(id as Sub)} options={[
              { id: "explore", label: "Explore" },
              { id: "area", label: "Area" },
              { id: "angles", label: "Angles" },
              { id: "special", label: "Special" },
              { id: "invariants", label: "What stays true?" },
            ]} />
          </Field>
          {sub === "invariants" ? <p className="tri-note">Drag any vertex. Green checks hold for this triangle; congruence compares it with the fixed 3-4-5 reference.</p> : null}
          <Field label="Triangle type">
            <div className="tri-preset-row">
              {PRESET_IDS.map((id) => (
                <button key={id} type="button" className={preset === id ? "active" : ""} onClick={() => applyPreset(id)}>
                  <PresetThumb id={id} />
                </button>
              ))}
            </div>
          </Field>
          {sub === "special" ? (
            <Field label="Special triangles">
              <ChipRow value="" onChange={(id) => { commit(SPECIAL[id]!); setPreset("custom"); }} options={Object.keys(SPECIAL).map((id) => ({ id, label: id }))} />
            </Field>
          ) : null}
          {sub === "area" ? (
            <>
              <Field label="Base">
                <Segmented value={base} onChange={(id) => setBase(id as Base)} options={[{ id: "AB", label: "AB" }, { id: "BC", label: "BC" }, { id: "CA", label: "CA" }]} />
              </Field>
              <Field label="Area formula">
                <Segmented value={areaFormula} onChange={setAreaFormula} options={[{ id: "bh", label: "½bh" }, { id: "heron", label: "Heron" }, { id: "coord", label: "Coordinate" }]} />
              </Field>
            </>
          ) : null}
          <Field label="Snap">
            <Segmented value={snap} onChange={(id) => setSnap(id as SnapMode)} options={[
              { id: "off", label: "Free" },
              { id: "grid", label: "Grid" },
              { id: "integer", label: "Integer" },
              { id: "angle", label: "15°" },
            ]} />
          </Field>
          <Field label="Lock while dragging">
            <Segmented value={lock} onChange={(id) => setLock(id as LockMode)} options={[
              { id: "none", label: "None" },
              { id: "isosceles", label: "Isosceles at A" },
              { id: "right", label: "Right at B" },
            ]} />
          </Field>
          <Field label="Side lengths">
            {([["AB", m.sides.AB], ["BC", m.sides.BC], ["CA", m.sides.CA]] as const).map(([side, value]) => (
              <div key={side} className="tri-coord-row">
                <span>{side}</span>
                <input aria-label={`${side} length`} type="number" step="0.1" value={okNum(value)} onChange={(event) => {
                  setPreset("custom");
                  commit(setSideLength(tri, side, Number(event.target.value)));
                }} />
              </div>
            ))}
          </Field>
          <Field label="Coordinates">
            {(["A", "B", "C"] as const).map((who) => (
              <div key={who} className="tri-coord-row">
                <span>{who}</span>
                <input aria-label={`${who} x`} type="number" step="0.1" value={okNum(tri[who].x)} onChange={(event) => setCoord(who, "x", Number(event.target.value))} />
                <input aria-label={`${who} y`} type="number" step="0.1" value={okNum(tri[who].y)} onChange={(event) => setCoord(who, "y", Number(event.target.value))} />
              </div>
            ))}
          </Field>
          <Field label="Measure">
            <Toggle checked={layers.sides} onChange={(v) => setLayers({ ...layers, sides: v })}>Side lengths</Toggle>
            <Toggle checked={layers.angles} onChange={(v) => setLayers({ ...layers, angles: v })}>Angles</Toggle>
            <Toggle checked={layers.arcs} onChange={(v) => setLayers({ ...layers, arcs: v })}>Angle arcs</Toggle>
            <Toggle checked={layers.coords} onChange={(v) => setLayers({ ...layers, coords: v })}>Coordinates</Toggle>
          </Field>
          <Field label="Lines (one family at a time)">
            <Segmented value={layers.altitudes ? "altitudes" : layers.median ? "median" : layers.bisector ? "bisector" : layers.perp ? "perp" : "none"} onChange={(id) => setLayers({
              ...layers,
              altitudes: id === "altitudes",
              median: id === "median",
              bisector: id === "bisector",
              perp: id === "perp",
            })} options={[
              { id: "none", label: "None" },
              { id: "altitudes", label: "Altitudes" },
              { id: "median", label: "Median" },
              { id: "bisector", label: "Bisector" },
              { id: "perp", label: "Perp. bisector" },
            ]} />
          </Field>
          <Field label="Grid">
            <Toggle checked={layers.grid} onChange={(v) => setLayers({ ...layers, grid: v })}>Show grid</Toggle>
          </Field>
          <Toggle checked={anim} onChange={setAnim}>Move vertex C</Toggle>
          {warn ? <p className="tri-warn" role="status">{warn}</p> : null}
        </Panel>
      }
      canvas={
        <div className="tri-stage">
          {coach ? (
            <div className="tri-coach">
              <p>Drag A, B, or C. Arrow keys nudge the selected vertex.</p>
              <button type="button" className="msk-cta" onClick={() => { setCoach(false); writeGeoSession({ coachDismissed: true }); }}>Got it</button>
            </div>
          ) : null}
          <GeometryLessonCanvas onPointChange={(id, point) => { if (id === "A" || id === "B" || id === "C") setTri(current => ({ ...current, [id]: fromSvg(plane, point.x, point.y) })); }} scene={triangleLessonScene(plane, [tri], p => toSvg(plane, p))} ref={svgRef} viewBox={`${vx} ${vy} ${vw} ${vh}`} role="img" aria-label={svgLabel} className={ui?.challengeFlash ? "is-success" : ""} onPointerDown={startPan}>
            {layers.grid ? <GridLayer plane={plane} /> : null}
            <g aria-label="Triangle fill">
              <polygon points={polyPoints(plane, [tri.A, tri.B, tri.C])} fill="rgba(20,125,242,.10)" stroke="#147df2" strokeWidth="2.2" className={hover === "Perimeter" ? "is-hot" : ""} />
            </g>
            {showUnfold ? (
              <g className="tri-unfold" aria-hidden="true">
                <line x1={toSvg(plane, { x: 1.2, y: 0.55 }).x} y1={toSvg(plane, { x: 1.2, y: 0.55 }).y} x2={toSvg(plane, { x: 16.8, y: 0.55 }).x} y2={toSvg(plane, { x: 16.8, y: 0.55 }).y} stroke="#0f172a" strokeWidth="2" />
                <text x={toSvg(plane, { x: 9, y: 0.2 }).x} y={toSvg(plane, { x: 9, y: 0.2 }).y} textAnchor="middle" fill="#0b4f8a" fontSize="12" fontWeight="800">Straight angle = 180° = ∠A + ∠B + ∠C</text>
              </g>
            ) : null}
            {sub === "area" ? (
              <polygon points={polyPoints(plane, [basePts[0], basePts[1], basePts[2]])} fill="rgba(8,185,221,.16)" stroke="none" />
            ) : null}
            {layers.arcs || sub === "angles" ? (
              <g className="tri-print-hide" aria-label="Angle marks">
                <AngleArc plane={plane} vertex={tri.A} p={tri.B} q={tri.C} color="#08b9dd" label={`${okNum(m.angles.A, 1)}°`} />
                <AngleArc plane={plane} vertex={tri.B} p={tri.A} q={tri.C} color="#8b45f4" radius={18} label={`${okNum(m.angles.B, 1)}°`} />
                <AngleArc plane={plane} vertex={tri.C} p={tri.A} q={tri.B} color="#f59e0b" radius={18} label={`${okNum(m.angles.C, 1)}°`} />
              </g>
            ) : null}
            {layers.altitudes ? (
              <>
                <DashedLine plane={plane} a={tri.A} b={footA} color="#64748b" />
                <DashedLine plane={plane} a={tri.B} b={footB} color="#64748b" />
                <DashedLine plane={plane} a={tri.C} b={footC} color="#64748b" />
              </>
            ) : null}
            {(layers.altitudes || sub === "area") ? (
              <>
                <DashedLine plane={plane} a={basePts[2]} b={foot} color="#0ea5c6" />
                <RightAngleMarker plane={plane} vertex={foot} p={basePts[2]} q={basePts[1]} color="#0ea5c6" />
                <SideMeasurement plane={plane} a={basePts[2]} b={foot} text={`h=${okNum(height)}`} color="#0ea5c6" />
              </>
            ) : null}
            {layers.median ? <SolidLine plane={plane} a={tri.A} b={midBC} color="#10b981" /> : null}
            {layers.bisector && bis ? <SolidLine plane={plane} a={tri.A} b={bis} color="#8b45f4" /> : null}
            {layers.perp ? (
              <DashedLine plane={plane} a={{ x: pb.point.x - pb.dir.x * 0.04, y: pb.point.y - pb.dir.y * 0.04 }} b={{ x: pb.point.x + pb.dir.x * 0.04, y: pb.point.y + pb.dir.y * 0.04 }} />
            ) : null}
            {layers.sides ? (
              <>
                <g className={hover === "AB" ? "is-hot" : ""}><SideMeasurement plane={plane} a={tri.A} b={tri.B} text={`c=${okNum(m.sides.AB)}`} /></g>
                <g className={hover === "BC" ? "is-hot" : ""}><SideMeasurement plane={plane} a={tri.B} b={tri.C} text={`a=${okNum(m.sides.BC)}`} /></g>
                <g className={hover === "CA" ? "is-hot" : ""}><SideMeasurement plane={plane} a={tri.C} b={tri.A} text={`b=${okNum(m.sides.CA)}`} /></g>
              </>
            ) : null}
            <g onPointerDown={startDrag("A")}><DraggableVertex plane={plane} p={tri.A} label="A" active={selected === "A"} /></g>
            <g onPointerDown={startDrag("B")}><DraggableVertex plane={plane} p={tri.B} label="B" color="#0f766e" active={selected === "B"} /></g>
            <g onPointerDown={startDrag("C")}><DraggableVertex plane={plane} p={tri.C} label="C" color="#8b45f4" active={selected === "C"} /></g>
            {layers.coords ? (
              <>
                <text x={aSvg.x + 12} y={aSvg.y + 22} fill="#536381" fontSize="11">({okNum(tri.A.x)}, {okNum(tri.A.y)})</text>
                <text x={bSvg.x + 12} y={bSvg.y + 22} fill="#536381" fontSize="11">({okNum(tri.B.x)}, {okNum(tri.B.y)})</text>
                <text x={cSvg.x + 12} y={cSvg.y + 22} fill="#536381" fontSize="11">({okNum(tri.C.x)}, {okNum(tri.C.y)})</text>
              </>
            ) : null}
          </GeometryLessonCanvas>
        </div>
      }
      insights={
        <InsightStack
          measurements={
            <>
              <div className="tri-badges">
                <span className="tri-badge">By sides: {m.bySides}</span>
                <span className="tri-badge">By angles: {m.byAngles}</span>
              </div>
              <p className="tri-note">
                {m.bySides === "Equilateral" ? "All three sides match, so every angle is 60°." : m.bySides === "Isosceles" ? "Two sides match, so their opposite angles match." : "No sides are equal, so no angles are forced equal."}
                {" "}
                {m.byAngles === "Right" ? "One angle is 90°, so Pythagoras applies on the other two sides." : m.byAngles === "Obtuse" ? "One angle is greater than 90°, so the circumcenter sits outside." : "Every angle is less than 90°."}
              </p>
              <MeasureRow label="AB" value={okNum(m.sides.AB)} metric="AB" />
              <MeasureRow label="BC" value={okNum(m.sides.BC)} color="#0f766e" metric="BC" />
              <MeasureRow label="CA" value={okNum(m.sides.CA)} color="#8b45f4" metric="CA" />
              <MeasureRow label="∠A" value={`${okNum(m.angles.A, 1)}°`} color="#08b9dd" metric="∠A" />
              <MeasureRow label="∠B" value={`${okNum(m.angles.B, 1)}°`} color="#8b45f4" metric="∠B" />
              <MeasureRow label="∠C" value={`${okNum(m.angles.C, 1)}°`} color="#f59e0b" metric="∠C" />
              <MeasureRow label="Perimeter" value={okNum(m.perimeter)} metric="Perimeter" />
              <MeasureRow label="Semiperimeter s" value={okNum(m.semiperimeter)} />
              <MeasureRow label="Area" value={okNum(m.area)} metric="Area" />
            </>
          }
          property={sub === "invariants" ? <div className="tri-invariants"><strong>What stays true as you drag?</strong><p className={Math.abs(m.angleSum - 180) < 0.2 ? "tri-ok" : "tri-warning"}>Angle sum: {okNum(m.angleSum, 1)}° {Math.abs(m.angleSum - 180) < 0.2 ? "✓" : "Check"}</p>{([ ["AB + BC > CA", inequality.ab], ["BC + CA > AB", inequality.bc], ["CA + AB > BC", inequality.ca] ] as const).map(([label, check]) => <p key={label} className={check.ok ? "tri-ok" : "tri-warning"}>{label}: {okNum(check.left)} &gt; {okNum(check.right)} {check.ok ? "✓" : "Not yet"}</p>)}<strong>Congruent to the 3-4-5 reference?</strong>{Object.entries(congruence).map(([test, holds]) => <p key={test} className={holds ? "tri-ok" : "tri-note"}>{test}: {holds ? "matches ✓" : "does not match yet"}</p>)}<button type="button" className="msk-soft" onClick={() => { commit(SPECIAL["3-4-5"]); setPreset("custom"); }}>Match 3-4-5 reference</button></div> : <p className="tri-ok">∠A + ∠B + ∠C = {okNum(m.angles.A, 1)}° + {okNum(m.angles.B, 1)}° + {okNum(m.angles.C, 1)}° = {okNum(m.angleSum, 1)}°</p>}
          formula={
            <FormulaCard
              title={sub === "area" ? "Area" : "Angle sum"}
              formula={sub === "area" ? (areaFormula === "heron" ? "A = √[s(s−a)(s−b)(s−c)]" : areaFormula === "coord" ? "A = ½|x1(y2−y3)+x2(y3−y1)+x3(y1−y2)|" : "A = ½ bh") : "∠A + ∠B + ∠C = 180°"}
              why={sub === "area" ? `Base ${base} = ${okNum(baseLen)}, height = ${okNum(height)}. ½bh = ${okNum(0.5 * baseLen * height)}. Heron = ${okNum(m.heron)}.` : "A straight line is 180°. The three interior angles copy onto that line."}
              tryThis={sub === "area" ? "Switch the base and watch height change while area stays the same." : "Turn on Move vertex C and watch the sum stay 180°."}
            />
          }
          challenge={
            <ChallengeCard
              prompt="Create an isosceles triangle with apex angle 40°."
              hint="Make AB = AC (or another pair equal), then drag until the equal-side vertex is near 40°."
              check={() => m.bySides !== "Scalene" && [m.angles.A, m.angles.B, m.angles.C].some((ang, i) => {
                const equalSides = i === 0 ? Math.abs(m.sides.AB - m.sides.CA) < 0.15 : i === 1 ? Math.abs(m.sides.AB - m.sides.BC) < 0.15 : Math.abs(m.sides.BC - m.sides.CA) < 0.15;
                return equalSides && Math.abs(ang - 40) < 2.5;
              })}
              onReset={reset}
              onSuccess={() => {
                ui?.setChallengeFlash(true);
                window.setTimeout(() => ui?.setChallengeFlash(false), 1200);
                ui?.announce("Challenge complete. Matching sides stay highlighted.");
              }}
            />
          }
        />
      }
    />
  );
}

import GeometryLessonCanvas from "../GeometryLessonCanvas";
import { triangleLessonScene } from "../geometryLessonScene";
import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useRef, useState } from "react";
import { Field, Panel, Segmented, SliderRow } from "../../mockup/studioLabKit";
import {
  EXPLORER_PRESETS,
  clampPoint,
  defaultPlane,
  fromSvg,
  measureTriangle,
  ranking,
  toSvg,
  triangleArea,
  triangleInequality,
} from "./triangleGeometry";
import { useGeoLabUi } from "../geometryLabUx";
import { ChallengeCard, FormulaCard, InsightStack, LabFrame, MeasureRow, Toggle, okNum } from "./triangleLabKit";
import {
  AngleArc,
  DashedLine,
  DraggableVertex,
  SideMeasurement,
  bindSvgDrag,
  pointerToSvg,
  polyPoints,
} from "./triangleSvgPrimitives";

type Mode = "inequality" | "sides" | "exterior";

export default function TriangleInequalitiesLab({ pulse = "observe" }: { pulse?: string }) {
  const ui = useGeoLabUi();
  const plane = defaultPlane();
  const svgRef = useRef<SVGSVGElement>(null);
  const drag = useRef<"A" | "B" | "C" | null>(null);
  const [mode, setMode] = useState<Mode>("inequality");
  const [a, setA] = useStudioState("TriangleInequalitiesLab:TriangleInequalitiesLab:a", 5);
  const [b, setB] = useStudioState("TriangleInequalitiesLab:TriangleInequalitiesLab:b", 6);
  const [c, setC] = useStudioState("TriangleInequalitiesLab:TriangleInequalitiesLab:c", 7);
  const [hinge, setHinge] = useStudioState("TriangleInequalitiesLab:TriangleInequalitiesLab:hinge", 0.27);
  const [animate, setAnimate] = useStudioState("TriangleInequalitiesLab:TriangleInequalitiesLab:animate", false);
  const [tri, setTri] = useStudioState("TriangleInequalitiesLab:TriangleInequalitiesLab:tri", EXPLORER_PRESETS.scalene);

  const tests = triangleInequality(a, b, c);
  const m = measureTriangle(tri.A, tri.B, tri.C);
  const rank = ranking(tri.A, tri.B, tri.C);

  useEffect(() => {
    if (tests.degenerate) ui?.announce("Degenerate: the three sides lie on a straight line.");
  }, [tests.degenerate, ui]);

  useEffect(() => {
    if (!animate) return;
    let t = 0;
    let id = 0;
    const tick = () => {
      t += 0.02;
      setHinge(0.12 + 0.75 * (0.5 + 0.5 * Math.sin(t)));
      id = requestAnimationFrame(tick);
    };
    id = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(id);
  }, [animate]);

  const hingeGeom = useMemo(() => {
    const origin = { x: 2.6, y: 2.2 };
    const P = origin;
    const Q = { x: origin.x + c, y: origin.y };
    const maxOpen = Math.PI * 0.92;
    const ang = hinge * maxOpen;
    const R = { x: origin.x + b * Math.cos(ang), y: origin.y + b * Math.sin(ang) };
    const gap = Math.hypot(R.x - Q.x, R.y - Q.y);
    const closeCos = (b * b + c * c - a * a) / (2 * b * c);
    const closeAng = Number.isFinite(closeCos) ? Math.acos(Math.max(-1, Math.min(1, closeCos))) : null;
    return { P, Q, R, gap, ang, closeAng, meets: Math.abs(gap - a) < 0.12 };
  }, [a, b, c, hinge]);

  useEffect(() => {
    if (animate) return;
    const maxOpen = Math.PI * 0.92;
    const closeCos = (b * b + c * c - a * a) / (2 * b * c);
    if (!Number.isFinite(closeCos)) {
      setHinge(0.05);
      return;
    }
    const closeAng = Math.acos(Math.max(-1, Math.min(1, closeCos)));
    if (tests.valid) setHinge(Math.min(0.98, Math.max(0.05, closeAng / maxOpen)));
    else if (tests.degenerate) setHinge(0.02);
  }, [a, b, c, animate, tests.degenerate, tests.valid]);

  useEffect(() => {
    if (pulse === "observe") setMode("inequality");
    if (pulse === "understand") setMode("inequality");
    if (pulse === "why") setMode("sides");
    if (pulse === "try" || pulse === "challenge") {
      setMode("inequality");
      setA(3);
      setB(4);
      setC(7);
      setHinge(0.02);
    }
  }, [pulse]);

  const startDrag = (who: "A" | "B" | "C") => (event: React.PointerEvent) => {
    event.preventDefault();
    drag.current = who;
    bindSvgDrag(svgRef, (ev) => {
      const svg = svgRef.current;
      if (!svg || !drag.current) return;
      const s = pointerToSvg(svg, ev);
      const next = clampPoint(fromSvg(plane, s.x, s.y));
      setTri((prev) => {
        const draft = { ...prev, [drag.current!]: next };
        return triangleArea(draft.A, draft.B, draft.C) < 0.25 ? prev : draft;
      });
    }, () => { drag.current = null; });
  };

  const reset = () => { setA(5); setB(6); setC(7); setHinge(0.27); setTri(EXPLORER_PRESETS.scalene); setMode("inequality"); };

  const p = toSvg(plane, hingeGeom.P);
  const q = toSvg(plane, hingeGeom.Q);
  const r = toSvg(plane, hingeGeom.R);

  return (
    <LabFrame
      theme="inequalities"
      ariaLabel="Triangle inequalities laboratory"
      controls={
        <Panel title="Inequality controls">
          <Field label="Mode">
            <Segmented value={mode} onChange={(id) => setMode(id as Mode)} options={[
              { id: "inequality", label: "Triangle inequality" },
              { id: "sides", label: "Sides & angles" },
              { id: "exterior", label: "Exterior angle" },
            ]} />
          </Field>
          {mode === "inequality" ? (
            <>
              <SliderRow label="Side a (BC)" value={a} min={0.8} max={12} step={0.1} onChange={setA} />
              <SliderRow label="Side b (AC)" value={b} min={0.8} max={12} step={0.1} onChange={setB} />
              <SliderRow label="Side c (AB)" value={c} min={0.8} max={12} step={0.1} onChange={setC} />
              <SliderRow label="Hinge opening" value={hinge} min={0.05} max={1} step={0.01} onChange={setHinge} />
              <Toggle checked={animate} onChange={setAnimate}>Animate hinge</Toggle>
            </>
          ) : null}
          {mode !== "inequality" ? <p className="tri-note">Drag vertices A, B, C. Rankings update live.</p> : null}
        </Panel>
      }
      canvas={
        <GeometryLessonCanvas onPointChange={(id, point) => { if (mode !== "inequality" && (id === "A" || id === "B" || id === "C")) setTri(current => ({ ...current, [id]: fromSvg(plane, point.x, point.y) })); }} scene={triangleLessonScene(plane, mode === "inequality" ? [{ A: hingeGeom.P, B: hingeGeom.Q, C: hingeGeom.R }] : [tri], p => toSvg(plane, p))} ref={svgRef} viewBox={`0 0 ${plane.width} ${plane.height}`} role="img" aria-label={`Triangle inequality construction. ${tests.valid ? "Valid triangle." : tests.degenerate ? "Degenerate: sides form a line." : "Cannot form a triangle."}`}>
          {mode === "inequality" ? (
            <g>
              {tests.valid && hingeGeom.meets ? (
                <polygon points={polyPoints(plane, [hingeGeom.P, hingeGeom.Q, hingeGeom.R])} fill="rgba(16,185,129,.14)" stroke="#059669" strokeWidth="2.1" />
              ) : null}
              <line x1={p.x} y1={p.y} x2={q.x} y2={q.y} stroke="#147df2" strokeWidth="3" />
              <line x1={p.x} y1={p.y} x2={r.x} y2={r.y} stroke="#8b45f4" strokeWidth="3" />
              <line x1={r.x} y1={r.y} x2={q.x} y2={q.y} stroke={tests.degenerate ? "#f59e0b" : tests.valid && hingeGeom.meets ? "#059669" : "#ef4444"} strokeWidth="2.2" strokeDasharray={hingeGeom.meets && tests.valid ? "0" : "7 5"} />
              <circle cx={q.x} cy={q.y} r={a * plane.unit} fill="none" stroke="#ef444466" strokeDasharray="4 5" />
              <path d={`M ${p.x + b * plane.unit} ${p.y} A ${b * plane.unit} ${b * plane.unit} 0 0 0 ${r.x} ${r.y}`} fill="none" stroke="#8b45f433" strokeWidth="1.4" />
              <circle cx={p.x} cy={p.y} r="5" fill="#147df2" />
              <circle cx={q.x} cy={q.y} r="5" fill="#147df2" />
              <circle cx={r.x} cy={r.y} r="5" fill="#8b45f4" />
              <text x={(p.x + q.x) / 2} y={p.y + 18} fill="#147df2" fontSize="12" fontWeight="700">c={okNum(c)}</text>
              <text x={(p.x + r.x) / 2 - 18} y={(p.y + r.y) / 2} fill="#8b45f4" fontSize="12" fontWeight="700">b={okNum(b)}</text>
              <text x={(r.x + q.x) / 2 + 8} y={(r.y + q.y) / 2} fill={hingeGeom.meets && tests.valid ? "#059669" : "#ef4444"} fontSize="12" fontWeight="700">
                {hingeGeom.meets && tests.valid ? `a=${okNum(a)}` : tests.degenerate ? "degenerate" : `need a=${okNum(a)}`}
              </text>
            </g>
          ) : (
            <>
              <polygon points={polyPoints(plane, [tri.A, tri.B, tri.C])} fill="rgba(20,125,242,.10)" stroke="#147df2" strokeWidth="2.1" />
              <AngleArc plane={plane} vertex={tri.A} p={tri.B} q={tri.C} color="#08b9dd" label={`${okNum(m.angles.A, 0)}°`} />
              <AngleArc plane={plane} vertex={tri.B} p={tri.A} q={tri.C} color="#8b45f4" label={`${okNum(m.angles.B, 0)}°`} />
              <AngleArc plane={plane} vertex={tri.C} p={tri.A} q={tri.B} color="#f59e0b" label={`${okNum(m.angles.C, 0)}°`} />
              <SideMeasurement plane={plane} a={tri.B} b={tri.C} text={`a=${okNum(m.sides.BC)}`} />
              <SideMeasurement plane={plane} a={tri.A} b={tri.C} text={`b=${okNum(m.sides.CA)}`} />
              <SideMeasurement plane={plane} a={tri.A} b={tri.B} text={`c=${okNum(m.sides.AB)}`} />
              {mode === "exterior" ? (
                <>
                  <DashedLine plane={plane} a={tri.B} b={{ x: tri.C.x + (tri.C.x - tri.B.x) * 0.45, y: tri.C.y + (tri.C.y - tri.B.y) * 0.45 }} color="#64748b" />
                  <AngleArc plane={plane} vertex={tri.C} p={tri.B} q={{ x: tri.C.x + (tri.C.x - tri.B.x), y: tri.C.y + (tri.C.y - tri.B.y) }} color="#ef4444" radius={28} label="ext" />
                </>
              ) : null}
              <g onPointerDown={startDrag("A")}><DraggableVertex plane={plane} p={tri.A} label="A" /></g>
              <g onPointerDown={startDrag("B")}><DraggableVertex plane={plane} p={tri.B} label="B" /></g>
              <g onPointerDown={startDrag("C")}><DraggableVertex plane={plane} p={tri.C} label="C" /></g>
            </>
          )}
        </GeometryLessonCanvas>
      }
      insights={
        <InsightStack
          measurements={
            mode === "inequality" ? (
              <>
                <MeasureRow label="a + b ? c" value={`${okNum(tests.ab.left)} ${tests.ab.ok ? ">" : tests.ab.equal ? "=" : "≯"} ${okNum(tests.ab.right)} ${tests.ab.ok ? "✓" : tests.ab.equal ? "=" : "✗"}`} color={tests.ab.ok ? "#059669" : "#dc2626"} />
                <MeasureRow label="b + c ? a" value={`${okNum(tests.bc.left)} ${tests.bc.ok ? ">" : tests.bc.equal ? "=" : "≯"} ${okNum(tests.bc.right)} ${tests.bc.ok ? "✓" : "✗"}`} color={tests.bc.ok ? "#059669" : "#dc2626"} />
                <MeasureRow label="c + a ? b" value={`${okNum(tests.ca.left)} ${tests.ca.ok ? ">" : tests.ca.equal ? "=" : "≯"} ${okNum(tests.ca.right)} ${tests.ca.ok ? "✓" : "✗"}`} color={tests.ca.ok ? "#059669" : "#dc2626"} />
                <p className={tests.valid ? "tri-ok" : tests.degenerate ? "tri-warn" : "tri-warn"}>
                  {tests.valid ? "VALID TRIANGLE" : tests.degenerate ? "Degenerate triangle — points lie on a straight line." : "CANNOT FORM A TRIANGLE"}
                </p>
              </>
            ) : (
              <>
                <MeasureRow label="Longest side" value={`${rank.longest.name} opposite ∠${rank.longest.angle}`} />
                <MeasureRow label="Largest angle" value={`∠${rank.longest.angle} = ${okNum(rank.longest.angle === "A" ? m.angles.A : rank.longest.angle === "B" ? m.angles.B : m.angles.C, 1)}°`} color="#dc2626" />
                <MeasureRow label="Shortest side" value={`${rank.shortest.name} opposite ∠${rank.shortest.angle}`} color="#0f766e" />
                <MeasureRow label="Smallest angle" value={`∠${rank.shortest.angle}`} color="#0f766e" />
                {mode === "exterior" ? <MeasureRow label="Exterior at C" value={`${okNum(180 - m.angles.C, 1)}° > remote ∠A, ∠B`} color="#ef4444" /> : null}
              </>
            )
          }
          property={
            <p className="tri-note">
              {mode === "inequality" && "Three segments close if and only if each pair sums to more than the third."}
              {mode === "sides" && "The larger side lies opposite the larger angle. Rankings stay consistent as you drag."}
              {mode === "exterior" && "An exterior angle is greater than each remote interior angle (and equals their sum)."}
            </p>
          }
          formula={
            <FormulaCard
              title={mode === "inequality" ? "Triangle inequality" : mode === "sides" ? "Side–angle" : "Exterior angle"}
              formula={mode === "inequality" ? "a + b > c" : mode === "sides" ? "BC > AC  ⇒  ∠A > ∠B" : "∠ext > ∠remote"}
              why={mode === "inequality" ? "The shortest path between two points is the straight segment; a detour through the third vertex is longer." : "Opening an angle stretches the opposite side."}
              tryThis={mode === "inequality" ? "Set 3, 4, 7 to see the degenerate line, then 3, 4, 8 to see the gap." : "Drag C until BC is longest and confirm ∠A is largest."}
            />
          }
          challenge={
            <ChallengeCard
              prompt="Create side lengths where the triangle just becomes degenerate."
              hint="Make a + b equal c, for example 3, 4, 7."
              check={() => tests.degenerate}
              onReset={reset}
            />
          }
        />
      }
    />
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useState } from "react";
import { GeometryLabShell } from "../geometryLabUx";
import type { StudioMockupPage } from "../../mockup/studioMockupCatalog";
import CongruenceLab from "./CongruenceLab";
import SimilarityLab from "./SimilarityLab";
import TriangleCentersLab from "./TriangleCentersLab";
import TriangleExplorerLab from "./TriangleExplorerLab";
import TriangleInequalitiesLab from "./TriangleInequalitiesLab";
import TriangleModeTabs from "./TriangleModeTabs";
import "./TrianglesLab.css";
import { LearningStrip } from "./triangleLabKit";
import { useTriangleLabMode, type TriangleModeId } from "./useTriangleLabMode";

const STRIPS: Record<TriangleModeId, Array<{ title: string; text: string; action: string }>> = {
  explorer: [
    { title: "Observe", text: "Drag C and watch sides and angles update.", action: "observe" },
    { title: "Understand", text: "∠A + ∠B + ∠C stays 180°.", action: "understand" },
    { title: "Why", text: "Area = ½bh for any chosen base.", action: "why" },
