  );
  const teacher = (
    <button
      type="button"
      className={`la-tool${session.teacherMode ? " is-on" : ""}`}
      aria-pressed={session.teacherMode}
      onClick={() => writeLinearSession({ teacherMode: !session.teacherMode })}
