export { IdentitiesLab } from "./IdentitiesLab";
export { InverseTrigLab } from "./InverseTrigLab";

const COLORS = {
  sine: "#22d3ee",
  cosine: "#a78bfa",
  tangent: "#f59e0b",
  angle: "#fb923c",
  success: "#22c55e",
  ink: "#e2e8f0",
  muted: "#64748b",
} as const;

type TrigFamily = "Sine" | "Cosine" | "Tangent";

function trigName(family: TrigFamily) {
  return family === "Sine" ? "sin" : family === "Cosine" ? "cos" : "tan";
}

function trigValue(family: TrigFamily, x: number) {
  return family === "Sine" ? Math.sin(x) : family === "Cosine" ? Math.cos(x) : Math.tan(x);
}

function waveSegments(
  family: TrigFamily,
  a: number,
  b: number,
  c: number,
  d: number,
  width = 560,
  height = 400,
) {
  const segments: string[] = [];
  let current: string[] = [];
  const samples = 360;
  for (let index = 0; index <= samples; index += 1) {
    const x = -2 * Math.PI + (index / samples) * 4 * Math.PI;
    const y = a * trigValue(family, b * (x - c)) + d;
    if (!Number.isFinite(y) || Math.abs(y) > 3.8) {
      if (current.length > 1) segments.push(current.join(" "));
      current = [];
    } else {
      current.push(`${32 + (index / samples) * (width - 54)},${height / 2 - y * 42}`);
    }
  }
  if (current.length > 1) segments.push(current.join(" "));
  return segments;
}

function customWaveSegments(evaluate: (x: number) => number, width = 560, height = 400) {
  const segments: string[] = [];
  let current: string[] = [];
  let previousY: number | null = null;
  const samples = 720;
  for (let index = 0; index <= samples; index += 1) {
    const x = -2 * Math.PI + (index / samples) * 4 * Math.PI;
    let y: number;
    try { y = evaluate(x); } catch { y = Number.NaN; }
    if (!Number.isFinite(y) || Math.abs(y) > 3.8) {
      if (current.length > 1) segments.push(current.join(" "));
      current = [];
      previousY = null;
      continue;
    }
    if (previousY !== null && Math.abs(y - previousY) > 1.5) {
      if (current.length > 1) segments.push(current.join(" "));
      current = [];
    }
    current.push(`${32 + (index / samples) * (width - 54)},${height / 2 - y * 42}`);
    previousY = y;
  }
  if (current.length > 1) segments.push(current.join(" "));
  return segments;
}

function graphX(x: number, width = 560) {
  return 32 + ((x + 2 * Math.PI) / (4 * Math.PI)) * (width - 54);
}

function graphY(y: number, height = 400) {
  return height / 2 - clamp(y, -3.5, 3.5) * 42;
}

function Grid({ width = 560, height = 400 }: { width?: number; height?: number }) {
  return (
    <>
      {Array.from({ length: 9 }, (_, index) => (
        <line key={`v-${index}`} x1={32 + index * ((width - 54) / 8)} y1="20" x2={32 + index * ((width - 54) / 8)} y2={height - 22} stroke="#17304d" strokeDasharray="2 4" />
      ))}
      {Array.from({ length: 7 }, (_, index) => (
        <line key={`h-${index}`} x1="32" y1={height / 2 + (index - 3) * 42} x2={width - 22} y2={height / 2 + (index - 3) * 42} stroke="#17304d" strokeDasharray="2 4" />
      ))}
      <line x1="24" y1={height / 2} x2={width - 14} y2={height / 2} stroke="#94a3b8" />
      <line x1={graphX(0, width)} y1="14" x2={graphX(0, width)} y2={height - 16} stroke="#94a3b8" />
      {[-2, -1, 0, 1, 2].map((multiple) => (
        <text key={multiple} x={graphX(multiple * Math.PI, width)} y={height / 2 + 17} fill="#94a3b8" fontSize="10" textAnchor="middle">
          {multiple === 0 ? "0" : multiple === 1 ? "π" : multiple === -1 ? "−π" : `${multiple}π`}
        </text>
      ))}
    </>
  );
}

export function TrigGraphsLab({ page }: { page: StudioMockupPage }) {
  const [family, setFamily] = useStudioState<TrigFamily>("TrigonometryConceptLabs:TrigGraphsLab:family", "Sine");
  const [amplitude, setAmplitude] = useStudioState("TrigonometryConceptLabs:TrigGraphsLab:amplitude", 2);
  const [frequency, setFrequency] = useStudioState("TrigonometryConceptLabs:TrigGraphsLab:frequency", 1.5);
  const [phase, setPhase] = useStudioState("TrigonometryConceptLabs:TrigGraphsLab:phase", Math.PI / 6);
  const [vertical, setVertical] = useStudioState("TrigonometryConceptLabs:TrigGraphsLab:vertical", 0.5);
  const [playing, setPlaying] = useStudioState("TrigonometryConceptLabs:TrigGraphsLab:playing", false);
  const [trace, setTrace] = useStudioState("TrigonometryConceptLabs:TrigGraphsLab:trace", true);
  const [showGrid, setShowGrid] = useState(true);
  const [angleUnit, setAngleUnit] = useStudioState<"Radians" | "Degrees">("TrigonometryConceptLabs:TrigGraphsLab:angleUnit", "Radians");
  const [time, setTime] = useStudioState("TrigonometryConceptLabs:TrigGraphsLab:time", Math.PI / 3);
  const [graphSource, setGraphSource] = useStudioState<"Preset" | "Custom">("TrigonometryConceptLabs:TrigGraphsLab:graphSource", "Preset");
  const [customExpression, setCustomExpression] = useStudioState("TrigonometryConceptLabs:TrigGraphsLab:customExpression", "");
  const graphHandle = useRef<"A" | "D" | null>(null);
  const customFunction = useMemo(() => {
    if (!customExpression.trim()) return { evaluate: null, error: "Enter a function of x." };
    try {
      const expression = customExpression.replace(/^\s*f\s*\(\s*x\s*\)\s*=\s*/i, "");
      const evaluate = compileFunctionExpression(expression);
      evaluate(0); // Check syntax that the parser can only validate when evaluated.
      return { evaluate, error: "" };
    } catch (error) {
      return { evaluate: null, error: error instanceof Error ? error.message : "Invalid function." };
    }
  }, [customExpression]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => {
      setTime((value) => {
        const next = value >= 2 * Math.PI ? -2 * Math.PI : value + 0.025;
        writeTrigSession({ theta: ((next * 180 / Math.PI) % 360 + 360) % 360 });
        return next;
      });
    }, 32);
    return () => window.clearInterval(timer);
  }, [playing]);

  const reset = () => {
    setAmplitude(2);
    setFrequency(1.5);
    setPhase(Math.PI / 6);
    setVertical(0.5);
    setTime(Math.PI / 3);
    setPlaying(false);
    setGraphSource("Preset");
    setCustomExpression("");
  };

  return (
    <Phase1LabChrome page={page}>
      {(mode) => {
        const selected: TrigFamily = mode === "Sine" || mode === "Cosine" || mode === "Tangent" ? mode : family;
        const comparison = mode === "Comparison";
        const transforming = mode === "Transformations";
        const a = amplitude;
        const b = frequency;
        const c = phase;
        const d = vertical;
        const custom = graphSource === "Custom";
        const y = custom ? (customFunction.evaluate?.(time) ?? Number.NaN) : a * trigValue(selected, b * (time - c)) + d;
        const customSegments = custom && customFunction.evaluate ? customWaveSegments(customFunction.evaluate) : [];
        const period = (selected === "Tangent" ? Math.PI : 2 * Math.PI) / Math.abs(b || 1);
        const lineColor = selected === "Sine" ? COLORS.sine : selected === "Cosine" ? COLORS.cosine : COLORS.tangent;
        const circleAngle = b * (time - c);
        const circleX = 56 + Math.cos(circleAngle) * 42;
        const circleY = 64 - Math.sin(circleAngle) * 42;
        const peakX = selected === "Cosine" ? c : c + Math.PI / (2 * Math.max(0.25, b));
        const moveGraphHandle = (event: PointerEvent<SVGSVGElement>) => {
          if (!graphHandle.current) return;
          const bounds = event.currentTarget.getBoundingClientRect();
          const svgY = ((event.clientY - bounds.top) / bounds.height) * 400;
          const value = clamp((200 - svgY) / 42, -3, 3);
          if (graphHandle.current === "A") setAmplitude(clamp(Math.abs(value - vertical), 0.2, 3));
          else setVertical(clamp(value, -2, 2));
        };
        return (
          <>
            <Panel title="Function builder" className="trig-target trig-target-controls trig-target-graphs-controls">
              <Segmented label="Graph source" value={graphSource} onChange={(value) => {
                setGraphSource(value as "Preset" | "Custom");
                if (value === "Custom" && !customExpression.trim()) setCustomExpression(`${trigName(selected)}(x)`);
              }} options={[{ id: "Preset", label: "Preset controls" }, { id: "Custom", label: "Your function" }]} />
              {custom ? (
                <>
                  <Field label="Write your function y =" hint="Use x and radians">
                    <input type="text" value={customExpression} onChange={(event) => setCustomExpression(event.target.value)} placeholder="e.g. cos(2x) + 0.5sin(x)" spellCheck={false} autoComplete="off" aria-invalid={Boolean(customFunction.error)} aria-describedby="trig-custom-help trig-custom-error" />
                  </Field>
                  <p id="trig-custom-help" className="trig-target-custom-help">Try sin(x) + cos(2x), 2cos(x - pi/4), or tan(x). You can also write f(x) =. Supports +, −, ×, ÷, powers, and π.</p>
                  {customFunction.error ? <p id="trig-custom-error" className="trig-target-custom-error" role="alert">{customFunction.error}</p> : null}
                </>
              ) : null}
              {(transforming || comparison) ? (
                <Field label="Function">
                  <Segmented
                    value={selected}
                    onChange={(value) => setFamily(value as TrigFamily)}
                    options={(["Sine", "Cosine", "Tangent"] as const).map((value) => ({ id: value, label: value }))}
                  />
                </Field>
              ) : null}
              {!custom ? <p className="msk-formula trig-target-formula">
                {comparison ? `Parents y = sin x, cos x, tan x · overlay y = ${fmt(a, 1)} ${trigName(selected)}(${fmt(b, 2)}(x − ${fmt(c, 2)})) + ${fmt(d, 1)}` : `y = ${fmt(a, 1)} ${trigName(selected)}(${fmt(b, 2)}(x − ${fmt(c, 2)})) + ${fmt(d, 1)}`}
              </p> : <p className="msk-formula trig-target-formula">y = {customExpression}</p>}
              {!custom ? <>
              <div className="trig-control-amplitude"><SliderRow label="Amplitude A" value={amplitude} min={0.2} max={3} step={0.1} onChange={setAmplitude} /></div>
              <div className="trig-control-period"><SliderRow label="Period parameter B" value={frequency} min={0.25} max={5} step={0.05} onChange={setFrequency} /></div>
              <div className="trig-control-phase"><SliderRow label="Phase shift C" value={phase} min={-2 * Math.PI} max={2 * Math.PI} step={0.05} onChange={setPhase} /></div>
              <div className="trig-control-vertical"><SliderRow label="Vertical shift D" value={vertical} min={-2} max={2} step={0.1} onChange={setVertical} /></div>
              </> : null}
              {!comparison && !custom ? (
                <>
                  <Segmented value={angleUnit} onChange={(value) => setAngleUnit(value as "Radians" | "Degrees")} options={[{ id: "Radians", label: "Radians" }, { id: "Degrees", label: "Degrees" }]} />
                  <Field label="Examples">
                    <div className="msk-chips trig-target-graph-examples">
                      <button type="button" onClick={() => { setAmplitude(1); setFrequency(1); setPhase(0); setVertical(0); }}>sin(x)</button>
                      <button type="button" onClick={() => { setAmplitude(2); setFrequency(1); setPhase(0); setVertical(0); }}>2sin(x)</button>
                      <button type="button" onClick={() => { setAmplitude(1); setFrequency(2); setPhase(0); setVertical(0); }}>sin(2x)</button>
                      <button type="button" onClick={() => { setAmplitude(1.5); setFrequency(0.5); setPhase(0); setVertical(-1); }}>1.5sin(.5x) − 1</button>
                    </div>
                  </Field>
                </>
              ) : null}
              <Field label="Angle trace">
                <input
                  type="range"
                  min={-2 * Math.PI}
                  max={2 * Math.PI}
                  step={0.01}
                  value={time}
                  onChange={(event) => {
                    const next = Number(event.target.value);
                    setTime(next);
                    writeTrigSession({ theta: ((next * 180 / Math.PI) % 360 + 360) % 360 });
                  }}
                />
              </Field>
              <div className="msk-btn-row">
                <button type="button" className="msk-cta" onClick={() => setPlaying((value) => !value)}>{playing ? "Pause" : "Animate"}</button>
                <button type="button" className={trace ? "msk-soft active" : "msk-soft"} onClick={() => setTrace((value) => !value)}>Trace</button>
                <button type="button" className="msk-soft" onClick={reset}>Reset</button>
              </div>
            </Panel>

            <section className="msk-panel msk-canvas trig-target trig-target-graphs-canvas" data-trig-target-mode={mode} data-tg-mode={mode} data-custom-function={custom ? customExpression : undefined} aria-label={custom ? "Custom function graph" : `${selected} graph`}>
              {comparison ? <span className="sr-only">Compare the three graphs</span> : null}
              <svg
                className="msk-graph is-dark is-interactive trig-target-dark-graph"
                viewBox="0 0 560 400"
                role="img"
                aria-label={custom ? `Graph of y = ${customExpression}` : `${mode} trigonometric graph`}
                onPointerMove={moveGraphHandle}
                onPointerUp={() => { graphHandle.current = null; }}
                onPointerLeave={() => { graphHandle.current = null; }}
              >
                <rect width="560" height="400" rx="12" fill="#061428" />
                {showGrid ? <Grid /> : null}
                {!custom ? <g className="trig-target-circle-inset">
                  <circle cx="56" cy="64" r="42" fill="#0b2039" stroke="#7dd3fc" />
                  <line x1="10" y1="64" x2="104" y2="64" stroke="#64748b" />
                  <line x1="56" y1="16" x2="56" y2="112" stroke="#64748b" />
                  <line x1="56" y1="64" x2={circleX} y2={circleY} stroke={COLORS.cosine} strokeWidth="2" />
                  <line x1={circleX} y1={circleY} x2={circleX} y2="64" stroke={COLORS.sine} strokeDasharray="3 2" />
                  <circle cx={circleX} cy={circleY} r="4.5" fill={COLORS.angle} />
                </g> : null}
                {comparison ? (
                  <>
                    {waveSegments("Sine", 1, 1, 0, 0).map((points) => <polyline key={`s-${points.slice(0, 16)}`} points={points} fill="none" stroke={COLORS.sine} strokeWidth="2.2" />)}
                    {waveSegments("Cosine", 1, 1, 0, 0).map((points) => <polyline key={`c-${points.slice(0, 16)}`} points={points} fill="none" stroke={COLORS.cosine} strokeWidth="2.2" />)}
                    {waveSegments("Tangent", 1, 1, 0, 0).map((points) => <polyline key={`t-${points.slice(0, 16)}`} points={points} fill="none" stroke={COLORS.tangent} strokeWidth="1.8" />)}
                    {!custom ? waveSegments(selected, a, b, c, d).map((points) => <polyline key={`xf-${points.slice(0, 16)}`} points={points} fill="none" stroke={lineColor} strokeWidth="2.8" strokeDasharray="6 4" />) : null}
                  </>
                ) : (
                  <>
                    {selected !== "Tangent" ? waveSegments(selected, 1, 1, 0, 0).map((points) => <polyline key={`parent-${points.slice(0, 16)}`} points={points} fill="none" stroke="#64748b" strokeWidth="1.4" strokeDasharray="5 4" />) : null}
                    {!custom && selected === "Tangent"
                      ? Array.from({ length: 8 }, (_, index) => c + (Math.PI / 2 + (index - 4) * Math.PI) / b)
                        .filter((x) => x >= -2 * Math.PI && x <= 2 * Math.PI)
                        .map((x) => <line key={`asymptote-${x}`} x1={graphX(x)} y1="18" x2={graphX(x)} y2="378" stroke="#f59e0b" strokeOpacity=".48" strokeDasharray="5 5" />)
                      : null}
                    {!custom && selected !== "Tangent" ? (
                      <>
                        <line x1="32" y1={graphY(d)} x2="538" y2={graphY(d)} stroke={COLORS.success} strokeWidth="1.2" strokeDasharray="5 4" />
                        <text x="35" y={graphY(d) - 7} fill={COLORS.success} fontSize="10">y = {fmt(d, 1)}</text>
                        <line x1={graphX(peakX)} y1={graphY(d)} x2={graphX(peakX)} y2={graphY(a + d)} stroke={COLORS.angle} strokeWidth="1.4" strokeDasharray="4 3" />
                        <text x={graphX(peakX) - 8} y={(graphY(d) + graphY(a + d)) / 2} fill={COLORS.angle} fontSize="10" textAnchor="end">Amplitude {fmt(a, 1)}</text>
                        <line x1={graphX(-2 * Math.PI + 0.25)} y1={graphY(-2.75)} x2={graphX(-2 * Math.PI + 0.25 + period)} y2={graphY(-2.75)} stroke={COLORS.angle} strokeWidth="1.3" />
                        <text x={(graphX(-2 * Math.PI + 0.25) + graphX(-2 * Math.PI + 0.25 + period)) / 2} y={graphY(-2.75) + 16} fill={COLORS.angle} fontSize="10" textAnchor="middle">Period {fmt(period, 2)}</text>
                        {Array.from({ length: 7 }, (_, index) => c + ((index - 3) * Math.PI) / b)
                          .filter((x) => x >= -2 * Math.PI && x <= 2 * Math.PI)
                          .map((x) => <circle key={`key-${x}`} cx={graphX(x)} cy={graphY(0)} r="4.5" fill={COLORS.cosine} />)}
                      </>
                    ) : null}
                    {!custom ? waveSegments(selected, a, b, c, d).map((points) => <polyline key={points.slice(0, 18)} points={points} fill="none" stroke={lineColor} strokeWidth="2.6" />) : null}
                  </>
                )}
                {customSegments.map((points, index) => <polyline key={`custom-${index}`} data-custom-curve="true" points={points} fill="none" stroke="#f472b6" strokeWidth="3" strokeLinejoin="round" />)}
                {trace && Number.isFinite(y) && Math.abs(y) <= 3.5 ? (
                  <>
                    <line x1={graphX(time)} y1="18" x2={graphX(time)} y2="378" stroke={COLORS.angle} strokeDasharray="5 4" />
                    <circle cx={graphX(time)} cy={graphY(y)} r="6" fill={COLORS.angle} stroke="#fff" strokeWidth="1.5" />
                  </>
                ) : null}
                {transforming && !custom ? (
                  <>
                    <g className="trig-target-graph-handle" onPointerDown={(event) => { event.currentTarget.setPointerCapture(event.pointerId); graphHandle.current = "A"; }}>
                      <circle cx={graphX(peakX)} cy={graphY(a + d)} r="8" fill={COLORS.sine} stroke="#fff" strokeWidth="2" />
                      <text x={graphX(peakX)} y={graphY(a + d) + 4} fill="#061428" fontSize="10" fontWeight="900" textAnchor="middle">A</text>
                    </g>
                    <g className="trig-target-graph-handle" onPointerDown={(event) => { event.currentTarget.setPointerCapture(event.pointerId); graphHandle.current = "D"; }}>
                      <circle cx={graphX(c)} cy={graphY(d)} r="8" fill={COLORS.angle} stroke="#fff" strokeWidth="2" />
                      <text x={graphX(c)} y={graphY(d) + 4} fill="#061428" fontSize="10" fontWeight="900" textAnchor="middle">D</text>
                    </g>
                    <text x="124" y="48" fill="#cbd5e1" fontSize="10">Drag the A and D handles on the graph</text>
                  </>
                ) : null}
                <text x="124" y="31" fill={custom ? "#f472b6" : lineColor} fontSize="12">{custom ? `y = ${customExpression.slice(0, 48)}` : comparison ? "sin x · cos x · tan x" : `y = ${fmt(a, 1)} ${trigName(selected)}(${fmt(b, 2)}(x − ${fmt(c, 2)})) + ${fmt(d, 1)}`}</text>
              </svg>
              <div className="msk-canvas-tools trig-target-graph-tools">
                <button type="button" className={showGrid ? "active" : ""} onClick={() => setShowGrid((value) => !value)}>Grid</button>
                <button type="button" className={trace ? "active" : ""} onClick={() => setTrace((value) => !value)}>Trace</button>
                <button type="button" onClick={() => setTime((value) => clamp(value - 0.2, -2 * Math.PI, 2 * Math.PI))}>◀ Step</button>
                <button type="button" onClick={() => setTime((value) => clamp(value + 0.2, -2 * Math.PI, 2 * Math.PI))}>Step ▶</button>
              </div>
            </section>

            <aside className="msk-panel msk-live trig-target trig-target-right-rail trig-target-graphs-rail">
              <h2>Values &amp; Insights</h2>
              {custom ? (
                <>
                  <LiveRow color="#f472b6" label="Your function" value={`y = ${customExpression}`} />
                  <LiveRow color={COLORS.angle} label="Current x" value={`${fmt(time, 3)} rad`} />
                  <LiveRow color="#f472b6" label="Current y" value={Number.isFinite(y) ? fmt(y, 4) : "undefined"} />
                </>
              ) : comparison ? (
                <>
                  <LiveRow color={COLORS.sine} label="sin x" value="period 2π" />
                  <LiveRow color={COLORS.cosine} label="cos x" value="phase lead π/2" />
                  <LiveRow color={COLORS.tangent} label="tan x" value="period π" />
                </>
              ) : (
                <>
                  <LiveRow color={lineColor} label="Amplitude |A|" value={selected === "Tangent" ? "unbounded" : fmt(Math.abs(a), 2)} />
                  <LiveRow color={COLORS.cosine} label="Period" value={fmt(period, 4)} />
                  <LiveRow color={COLORS.tangent} label="Phase shift C" value={`${fmt(c, 3)} rad`} />
                  <LiveRow color={COLORS.success} label="Vertical shift D" value={fmt(d, 2)} />
                  <LiveRow color={COLORS.angle} label="Current x" value={`${fmt(time, 3)} rad`} />
                  <LiveRow color={lineColor} label="Current y" value={Number.isFinite(y) ? fmt(y, 4) : "undefined"} />
                  <LiveRow color="#64748b" label="Domain" value={selected === "Tangent" ? "x ≠ C + (π/2 + kπ)/B" : "(−∞, ∞)"} />
                  <LiveRow color="#64748b" label="Range" value={selected === "Tangent" ? "(−∞, ∞)" : `[${fmt(d - Math.abs(a), 1)}, ${fmt(d + Math.abs(a), 1)}]`} />
                </>
              )}
              <h2>{custom ? "Function evaluation" : "Formula substitution"}</h2>
              <p className="msk-formula">{custom ? `f(${fmt(time, 2)}) = ${Number.isFinite(y) ? fmt(y, 4) : "undefined"}` : `y = ${fmt(a, 2)} ${trigName(selected)}(${fmt(b, 2)}(${fmt(time, 2)} − ${fmt(c, 2)})) + ${fmt(d, 2)}`}</p>
              {custom ? <StatusOk>The pink curve graphs your function in radians.</StatusOk> : <StatusOk>{selected === "Tangent" ? "Breaks mark vertical asymptotes." : "The circle projection and graph point agree."}</StatusOk>}
              <ChallengeBox page={page} mode={mode} />
            </aside>
          </>
        );
      }}
    </Phase1LabChrome>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, useMemo, useState, type PointerEvent as ReactPointerEvent } from "react";
import { MockupLearningStrip } from "../MockupStudioChrome";
import type { StudioMockupPage } from "../studioMockupCatalog";
import { ChallengeBox, Field, LiveRow, Panel, Segmented, SliderRow, fmt, useLabMode } from "../studioLabKit";
import { useTrigSession, writeTrigSession } from "../trigStudioSession";

const MODES = ["Angles", "Unit Circle", "Quadrants", "Exact Values", "Reference Angles"];
const ANGLE_CHIPS = [
  { d: 0, top: "0", bot: "" },
  { d: 30, top: "π", bot: "6" },
  { d: 45, top: "π", bot: "4" },
  { d: 60, top: "π", bot: "3" },
  { d: 90, top: "π", bot: "2" },
  { d: 120, top: "2π", bot: "3" },
  { d: 135, top: "3π", bot: "4" },
  { d: 180, top: "π", bot: "" },
];

const UC_VIEWBOX = { width: 500, height: 420 } as const;
const UC_COLORS = {
  angle: "#f59e0b",
  anglePoint: "#fb923c",
  sine: "#8b5cf6",
  cosine: "#06b6d4",
  circle: "#38bdf8",
} as const;

function pointerInUnitCircle(event: ReactPointerEvent<SVGSVGElement>) {
  const box = event.currentTarget.getBoundingClientRect();
  const scale = Math.min(box.width / UC_VIEWBOX.width, box.height / UC_VIEWBOX.height);
  const renderedWidth = UC_VIEWBOX.width * scale;
  const renderedHeight = UC_VIEWBOX.height * scale;
  return {
    x: (event.clientX - box.left - (box.width - renderedWidth) / 2) / scale,
    y: (event.clientY - box.top - (box.height - renderedHeight) / 2) / scale,
  };
}

function exactish(n: number) {
  const hits: Array<[number, string]> = [
    [0, "0"], [0.5, "1/2"], [Math.SQRT1_2, "√2/2"], [Math.sqrt(3) / 2, "√3/2"], [1, "1"],
    [Math.sqrt(3) / 3, "√3/3"], [2 / Math.sqrt(3), "2√3/3"], [Math.SQRT2, "√2"], [Math.sqrt(3), "√3"], [2, "2"],
    [-0.5, "−1/2"], [-Math.SQRT1_2, "−√2/2"], [-Math.sqrt(3) / 2, "−√3/2"], [-1, "−1"],
    [-Math.sqrt(3) / 3, "−√3/3"], [-2 / Math.sqrt(3), "−2√3/3"], [-Math.SQRT2, "−√2"], [-Math.sqrt(3), "−√3"], [-2, "−2"],
  ];
  const hit = hits.find(([value]) => Math.abs(value - n) < 0.02);
  return hit ? hit[1] : fmt(n, 4);
}

function SvgExact({ x, y, value }: { x: number; y: number; value: string }) {
  const neg = value.startsWith("−") || value.startsWith("-");
  const body = neg ? value.slice(1) : value;
  if (!body.includes("/")) return <text x={x} y={y} fill="#92400e" fontSize="11">{value}</text>;
  const [top, bot] = body.split("/");
  return (
    <g>
      {neg ? <text x={x} y={y} fill="#92400e" fontSize="11">−</text> : null}
      <text x={x + (neg ? 8 : 0)} y={y - 7} fill="#92400e" fontSize="10">{top}</text>
      <line x1={x + (neg ? 6 : 0)} y1={y - 3} x2={x + (neg ? 30 : 24)} y2={y - 3} stroke="#92400e" />
      <text x={x + (neg ? 8 : 0)} y={y + 9} fill="#92400e" fontSize="10">{bot}</text>
    </g>
  );
}

function ExactFrac({ value }: { value: string }) {
  const neg = value.startsWith("−") || value.startsWith("-");
  const body = neg ? value.slice(1) : value;
  if (!body.includes("/")) return <span>{value}</span>;
  const [top, bot] = body.split("/");
  return <span className="msk-exact">{neg ? "−" : ""}<span className="msk-frac"><b>{top}</b><b>{bot}</b></span></span>;
}

function ExactRow({ color, name, exact, approx }: { color: string; name: string; exact: string; approx: string }) {
  return (
    <div className="msk-ratio uc-target-exact-row">
      <i style={{ background: color }} />
      <em>{name}</em>
      <span>=</span>
      <ExactFrac value={exact} />
      <strong>≈ {approx}</strong>
    </div>
  );
}

function wrap180(deg: number) {
  let value = deg;
  while (value > 180) value -= 360;
  while (value < -180) value += 360;
  return value;
}

function wrap360(deg: number) {
  return ((deg % 360) + 360) % 360;
}

function referenceAngle(deg: number) {
  const t = wrap360(deg);
  if (t <= 90) return t;
  if (t <= 180) return 180 - t;
  if (t < 360) return t <= 270 ? Math.abs(t - 180) : 360 - t;
  return 0;
}

const EXACT_DEGS = [0, 30, 45, 60, 90, 120, 135, 150, 180, 210, 225, 240, 270, 300, 315, 330];

function nearestExact(deg: number) {
  const t = wrap360(deg);
  return EXACT_DEGS.reduce((best, item) => {
    const dist = Math.min(Math.abs(item - t), 360 - Math.abs(item - t));
    const bestDist = Math.min(Math.abs(best - t), 360 - Math.abs(best - t));
    return dist < bestDist ? item : best;
  }, EXACT_DEGS[0]!);
}

function toSignedAngle(deg: number) {
  const t = wrap360(deg);
  return t > 180 ? t - 360 : t;
}

export default function UnitCircleLab({ page }: { page: StudioMockupPage }) {
  const { tabs, mode, setMode } = useLabMode(page, MODES);
  const session = useTrigSession();
  const units = session.units;
  const [angle, setAngle] = useStudioState("UnitCircleLab:UnitCircleLab:angle", session.theta);
  const [dir, setDir] = useStudioState<"ccw" | "cw">("UnitCircleLab:UnitCircleLab:dir", "ccw");
  const [showRef, setShowRef] = useState(true);
  const [showX, setShowX] = useState(true);
  const [showY, setShowY] = useState(true);
  const [showTan, setShowTan] = useState(true);
  const [playing, setPlaying] = useStudioState("UnitCircleLab:UnitCircleLab:playing", false);
  const [speed, setSpeed] = useStudioState("UnitCircleLab:UnitCircleLab:speed", 1);

  useEffect(() => {
    setAngle(session.theta);
  }, [session.theta]);

  useEffect(() => {
    if (mode !== "Exact Values") return;
    setAngle((current) => toSignedAngle(nearestExact(current)));
  }, [mode]);

  useEffect(() => {
    if (mode === "Reference Angles") setShowRef(true);
    if (mode === "Unit Circle") {
      setShowX(true);
      setShowY(true);
    }
  }, [mode]);

  useEffect(() => {
    if (!playing) return;
    const id = window.setInterval(() => {
      setAngle((value) => wrap180(value + (dir === "ccw" ? 1 : -1) * speed));
    }, 40);
    return () => window.clearInterval(id);
  }, [dir, playing, speed]);

  const live = useMemo(() => {
    const rad = angle * Math.PI / 180;
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);
    const tan = Math.abs(cos) < 1e-6 ? Infinity : sin / cos;
    const csc = Math.abs(sin) < 1e-6 ? Infinity : 1 / sin;
    const sec = Math.abs(cos) < 1e-6 ? Infinity : 1 / cos;
    const cot = Math.abs(sin) < 1e-6 ? Infinity : cos / sin;
    const t = wrap360(angle);
    const q = t === 0 ? 1 : Math.ceil(t / 90);
    const ref = referenceAngle(angle);
    return { rad, cos, sin, tan, csc, sec, cot, q, ref };
  }, [angle]);

  const cx = 250;
  const cy = 220;
  const r = 174;
  const px = cx + live.cos * r;
  const py = cy - live.sin * r;
  const wave = Array.from({ length: 541 }, (_, i) => {
    const t = i - 180;
    return `${40 + ((t + 180) / 540) * 420},${70 - Math.sin((t * Math.PI) / 180) * 36}`;
  }).join(" ");
  const cosWave = Array.from({ length: 541 }, (_, i) => {
    const t = i - 180;
    return `${40 + ((t + 180) / 540) * 420},${70 - Math.cos((t * Math.PI) / 180) * 36}`;
  }).join(" ");
  const waveX = 40 + ((angle + 180) / 540) * 420;

  const updateAngleFromPointer = (event: ReactPointerEvent<SVGSVGElement>) => {
    const point = pointerInUnitCircle(event);
    const raw = Math.atan2(cy - point.y, point.x - cx) * 180 / Math.PI;
    const next = mode === "Exact Values" ? toSignedAngle(nearestExact(raw)) : raw;
    setAngle(next);
    writeTrigSession({ theta: next });
  };

  const showProjections = mode === "Unit Circle" || mode === "Angles";
  const showWaves = mode === "Angles" || mode === "Unit Circle";
  const showExactTicks = mode === "Exact Values";
  const showQuadrantFill = mode === "Quadrants";
  const showRefTriangle = mode === "Reference Angles" || (mode !== "Quadrants" && showRef);
  const showExactLabels = mode === "Exact Values" || mode === "Unit Circle" || mode === "Reference Angles";

  return (
    <>
      <nav className="msk-tabs trig-target-tabs uc-target-tabs" aria-label="Unit Circle modes">
        {tabs.map((item) => (
          <button key={item} type="button" className={item === mode ? "active" : ""} aria-pressed={item === mode} onClick={() => setMode(item)}>{item}</button>
        ))}
      </nav>
      <div className="msk-lab trig-target-lab uc-target-lab" data-uc-mode={mode}>
        <Panel
          className="trig-target-controls uc-target-controls"
          title={mode === "Exact Values" ? "Special angles" : mode === "Quadrants" ? "Quadrant focus" : mode === "Reference Angles" ? "Reference angle" : "Angle Controls"}
        >
          <Field label="Angle">
            <Segmented
              value={units}
              onChange={(id) => writeTrigSession({ units: id === "rad" ? "rad" : "deg" })}
              options={[{ id: "deg", label: "Degrees (°)" }, { id: "rad", label: "Radians (rad)" }]}
            />
          </Field>
          <div className="uc-target-angle-input" aria-live="polite">
            <span>θ =</span>
            <strong>{units === "deg" ? `${fmt(angle, 0)}°` : `${fmt(live.rad, 4)} rad`}</strong>
          </div>
          <SliderRow label="θ" value={angle} min={-180} max={180} step={1} onChange={(n) => { const next = mode === "Exact Values" ? toSignedAngle(nearestExact(n)) : n; setAngle(next); writeTrigSession({ theta: next }); }} unit="°" />
          <div className="msk-preset-grid uc-target-presets">
            {ANGLE_CHIPS.map((item) => (
              <button key={item.d} type="button" className={`msk-angle-chip${angle === item.d ? " active" : ""}`} onClick={() => { setAngle(item.d); writeTrigSession({ theta: item.d }); }}>
                <b>{item.d}°</b>
                {item.bot ? <span className="msk-frac"><b>{item.top}</b><b>{item.bot}</b></span> : <span className="msk-frac"><b>{item.top}</b></span>}
              </button>
            ))}
          </div>
          <Field label="Direction">
            <Segmented value={dir} onChange={(id) => setDir(id as "ccw" | "cw")} options={[{ id: "ccw", label: "Counterclockwise" }, { id: "cw", label: "Clockwise" }]} />
          </Field>
          <p className="msk-note uc-target-section-label">Display options</p>
          {mode !== "Quadrants" && mode !== "Exact Values" ? (
            <label className="msk-toggle"><input type="checkbox" checked={showRefTriangle} onChange={(event) => setShowRef(event.target.checked)} disabled={mode === "Reference Angles"} /> Show reference triangle</label>
          ) : null}
          {mode === "Unit Circle" || mode === "Angles" ? (
            <>
              <label className="msk-toggle"><input type="checkbox" checked={showX} onChange={(event) => setShowX(event.target.checked)} /> Show x projection (cos θ)</label>
              <label className="msk-toggle"><input type="checkbox" checked={showY} onChange={(event) => setShowY(event.target.checked)} /> Show y projection (sin θ)</label>
              <label className="msk-toggle"><input type="checkbox" checked={showTan} onChange={(event) => setShowTan(event.target.checked)} /> Show tangent line</label>
            </>
          ) : null}
          {mode === "Quadrants" ? <p className="msk-note">The highlighted quadrant shows the signs of sin, cos, and tan for the current terminal ray.</p> : null}
          {mode === "Exact Values" ? <p className="msk-note">Snap θ to a special angle to read exact sine, cosine, and tangent.</p> : null}
          {mode === "Reference Angles" ? <p className="msk-note">The acute angle α to the x-axis is the reference angle. Related angles share the same exact values, with signs from the quadrant.</p> : null}
          <Field label="Animation">
            <div className="msk-btn-row">
              <button className="msk-cta" type="button" onClick={() => setPlaying((value) => !value)}>{playing ? "Pause" : "Play"}</button>
              <SliderRow label="Speed" value={speed} min={0.25} max={4} step={0.25} onChange={setSpeed} />
            </div>
          </Field>
        </Panel>

        <section className="msk-panel msk-canvas msk-uc-stage trig-target-canvas trig-target-dark uc-target-canvas">
          <svg
            className="msk-graph is-dark is-interactive uc-target-circle-figure"
            viewBox="0 0 500 420"
            role="img"
            aria-label="Unit circle"
            onPointerDown={(event) => {
              event.preventDefault();
              event.currentTarget.setPointerCapture(event.pointerId);
              updateAngleFromPointer(event);
            }}
            onPointerMove={(event) => {
              if (!event.currentTarget.hasPointerCapture(event.pointerId)) return;
              updateAngleFromPointer(event);
            }}
            onPointerUp={(event) => event.currentTarget.releasePointerCapture(event.pointerId)}
            onPointerCancel={(event) => {
              if (event.currentTarget.hasPointerCapture(event.pointerId)) {
                event.currentTarget.releasePointerCapture(event.pointerId);
              }
            }}
          >
            <rect width="500" height="420" fill="#fff5f8" />
            {[
              { q: 2, x: 18, y: 22, title: "Quadrant II", sign: "(sin +, cos −)" },
              { q: 1, x: 368, y: 22, title: "Quadrant I", sign: "(sin +, cos +)" },
              { q: 3, x: 18, y: 392, title: "Quadrant III", sign: "(sin −, cos −)" },
              { q: 4, x: 360, y: 392, title: "Quadrant IV", sign: "(sin −, cos +)" },
            ].map((item) => (
              <g key={item.q}>
                {showQuadrantFill ? (
                  <rect
                    x={item.q === 1 || item.q === 4 ? cx : cx - r}
                    y={item.q === 1 || item.q === 2 ? cy - r : cy}
                    width={r}
                    height={r}
                    fill={live.q === item.q ? "rgba(34,211,238,.22)" : "rgba(15,23,42,.18)"}
                  />
                ) : null}
                <text x={item.x} y={item.y} className={`msk-quad${live.q === item.q ? " is-on" : ""}`}>{item.title}</text>
                <text x={item.x} y={item.y + 14} className={`msk-quad-sign${live.q === item.q ? " is-on" : ""}`}>{item.sign}</text>
              </g>
            ))}
            {showExactTicks
              ? ANGLE_CHIPS.map((item) => {
                  const rad = (item.d * Math.PI) / 180;
                  const tx = cx + Math.cos(rad) * (r + 16);
                  const ty = cy - Math.sin(rad) * (r + 16);
                  return (
                    <g key={`tick-${item.d}`}>
                      <circle cx={cx + Math.cos(rad) * r} cy={cy - Math.sin(rad) * r} r={angle === item.d ? 5 : 3} fill={angle === item.d ? UC_COLORS.anglePoint : UC_COLORS.circle} />
                      <text x={tx} y={ty} fill="#92400e" fontSize="10" textAnchor="middle">{item.d}°</text>
                    </g>
                  );
                })
              : null}
            <circle cx={cx} cy={cy} r={r} fill="none" stroke={UC_COLORS.circle} strokeWidth="2" />
            <line x1={cx - r - 20} y1={cy} x2={cx + r + 28} y2={cy} stroke="#64748b" />
            <line x1={cx} y1={cy + r + 16} x2={cx} y2={cy - r - 20} stroke="#64748b" />
            <text x={cx + r + 8} y={cy - 6} fill="#475569" fontSize="11">x</text>
            <text x={cx + 8} y={cy - r - 8} fill="#475569" fontSize="11">y</text>
            <text x={cx + r - 2} y={cy + 15} fill="#475569" fontSize="10">1</text>
            <text x={cx - r - 14} y={cy + 15} fill="#475569" fontSize="10">−1</text>
            <text x={cx - 13} y={cy - r + 8} fill="#475569" fontSize="10">1</text>
            <text x={cx - 17} y={cy + r + 1} fill="#475569" fontSize="10">−1</text>
            <text x={cx + 6} y={cy + 14} fill="#475569" fontSize="10">O</text>
            {showProjections && showX ? <line className="uc-target-cosine-projection" x1={cx} y1={cy} x2={px} y2={cy} stroke={UC_COLORS.cosine} strokeWidth="2" strokeDasharray="6 4" /> : null}
            {showProjections && showY ? <line className="uc-target-sine-projection" x1={px} y1={cy} x2={px} y2={py} stroke={UC_COLORS.sine} strokeWidth="2" strokeDasharray="6 4" /> : null}
            {showProjections && showX ? <text x={(cx + px) / 2} y={cy + 16} fill={UC_COLORS.cosine} fontSize="11" textAnchor="middle">cos θ</text> : null}
            {showProjections && showY ? <text x={px - 8} y={(cy + py) / 2} fill={UC_COLORS.sine} fontSize="11" textAnchor="end">sin θ</text> : null}
            {showRefTriangle ? <polygon className="uc-target-reference-triangle" points={`${cx},${cy} ${px},${cy} ${px},${py}`} fill="rgba(168,85,247,.12)" stroke={UC_COLORS.sine} /> : null}
            {showProjections && showTan && Number.isFinite(live.tan) ? (
              <line
                className="uc-target-tangent"
                x1={cx + (live.cos < 0 ? -r : r)}
                y1={cy - Math.abs(live.tan) * r}
                x2={cx + (live.cos < 0 ? -r : r)}
                y2={cy}
                stroke={UC_COLORS.angle}
                strokeDasharray="4 4"
              />
            ) : null}
            <line className="uc-target-terminal-ray" x1={cx} y1={cy} x2={px} y2={py} stroke={UC_COLORS.angle} strokeWidth="2.5" />
            <path className="uc-target-angle-arc" d={`M ${cx + 28} ${cy} A 28 28 0 ${Math.abs(angle) > 180 ? 1 : 0} ${angle >= 0 ? 0 : 1} ${cx + 28 * Math.cos(live.rad)} ${cy - 28 * Math.sin(live.rad)}`} fill="none" stroke={UC_COLORS.angle} strokeWidth="2" />
            <circle className="uc-target-angle-point" cx={px} cy={py} r="7" fill={UC_COLORS.anglePoint} stroke="#fff7ed" strokeWidth="2" />
            {showExactLabels ? (
              <>
                <text x={px + 10} y={py - 22} fill="#92400e" fontSize="11">(cos θ, sin θ)</text>
                <SvgExact x={px + 10} y={py - 4} value={exactish(live.cos)} />
                <text x={px + 52} y={py - 4} fill="#92400e" fontSize="11">,</text>
                <SvgExact x={px + 62} y={py - 4} value={exactish(live.sin)} />
              </>
            ) : (
              <text x={px + 10} y={py - 8} fill="#92400e" fontSize="12">{mode === "Angles" ? `${fmt(angle, 0)}°` : `Q${live.q}`}</text>
            )}
            {mode === "Reference Angles" ? (
              <text x={cx + 40} y={cy - 8} fill="#c4b5fd" fontSize="12">α = {fmt(live.ref, 0)}°</text>
            ) : null}
            <text x={cx + 36} y={cy - 36} fill={UC_COLORS.angle} fontSize="13" fontWeight="700">{fmt(angle, 0)}°</text>
          </svg>
          {showWaves ? (
          <svg className="msk-graph is-dark uc-target-wave-figure" viewBox="0 0 500 140" aria-label="Sine and cosine waves">
            <rect width="500" height="140" fill="#fff5f8" />
            <text x="16" y="18" fill={UC_COLORS.sine} fontSize="11">sin θ</text>
            <text x="70" y="18" fill={UC_COLORS.cosine} fontSize="11">cos θ</text>
            <text x="8" y="38" fill="#64748b" fontSize="9">1</text>
            <text x="8" y="74" fill="#64748b" fontSize="9">0</text>
            <text x="4" y="110" fill="#64748b" fontSize="9">−1</text>
            {["−180°", "−90°", "0°", "90°", "180°", "270°", "360°"].map((label, i) => (
              <text key={label} x={40 + i * 70} y="132" textAnchor="middle" fill="#64748b" fontSize="9">{label}</text>
            ))}
            {[-180,-90,0,90,180,270,360].map(degrees=><line key={degrees} className="uc-target-wave-tick-guide" x1={40+(degrees+180)/540*420} x2={40+(degrees+180)/540*420} y1="28" y2="122" stroke="#e5cbd5" strokeDasharray="2 4" />)}
            <line x1="40" y1="70" x2="480" y2="70" stroke="#334155" />
            <polyline className="uc-target-sine-wave" points={wave} fill="none" stroke={UC_COLORS.sine} strokeWidth="1.8" />
            <polyline className="uc-target-cosine-wave" points={cosWave} fill="none" stroke={UC_COLORS.cosine} strokeWidth="1.8" />
            <line className="uc-target-wave-cursor" x1={waveX} y1="20" x2={waveX} y2="118" stroke={UC_COLORS.angle} strokeWidth="1.5" strokeDasharray="3 3" />
            <circle cx={waveX} cy={70 - live.sin * 36} r="4" fill={UC_COLORS.sine} />
            <circle cx={waveX} cy={70 - live.cos * 36} r="4" fill={UC_COLORS.cosine} />
            <text x={waveX} y="116" fill="#92400e" fontSize="10" fontWeight="700" textAnchor="middle">{fmt(angle, 0)}°</text>
          </svg>
          ) : null}
        </section>

        <aside className="msk-panel msk-live trig-target-rail uc-target-rail">
          <section className="uc-target-rail-section uc-target-angle-card">
            <h2>Angle</h2>
            <LiveRow color={UC_COLORS.angle} label="θ" value={`${fmt(angle, 1)}° = ${fmt(live.rad, 4)} rad`} />
          </section>
            <section className="uc-target-rail-section uc-target-coordinate-card">
              <h2>Coordinates on Unit Circle</h2>
              <div className="msk-ratio">
                <i style={{ background: UC_COLORS.cosine }} />
                <em>(cos θ, sin θ)</em>
                <span>=</span>
                <span className="msk-exact">(</span>
                <ExactFrac value={exactish(live.cos)} />
                <span className="msk-exact">,</span>
                <ExactFrac value={exactish(live.sin)} />
                <span className="msk-exact">)</span>
              </div>
            </section>
            <section className="uc-target-rail-section uc-target-exact-card">
              <h2>Exact Trigonometric Values</h2>
              <ExactRow color={UC_COLORS.sine} name="sin θ" exact={exactish(live.sin)} approx={fmt(live.sin, 5)} />
              <ExactRow color={UC_COLORS.cosine} name="cos θ" exact={exactish(live.cos)} approx={fmt(live.cos, 5)} />
              <ExactRow color={UC_COLORS.angle} name="tan θ" exact={Number.isFinite(live.tan) ? exactish(live.tan) : "undefined"} approx={Number.isFinite(live.tan) ? fmt(live.tan, 5) : "—"} />
            </section>
            <section className="uc-target-rail-section uc-target-signs-card">
              <h2>Signs by Quadrant</h2>
              <table className="msk-mini-table">
                <thead><tr><th></th>{["I", "II", "III", "IV"].map((q, index) => <th key={q} className={live.q === index + 1 ? "is-active" : ""}>{q}</th>)}</tr></thead>
                <tbody>
                  {[["sin", "+", "+", "−", "−"], ["cos", "+", "−", "−", "+"], ["tan", "+", "−", "+", "−"]].map((row) => (
                    <tr key={row[0]}>{row.map((value, index) => <td key={`${row[0]}-${index}`} className={index === live.q ? "is-active" : ""}>{value}</td>)}</tr>
                  ))}
                </tbody>
              </table>
              <p className="msk-note">Current quadrant: {["I", "II", "III", "IV"][live.q - 1]}</p>
            </section>
            <section className="uc-target-rail-section uc-target-reference-card">
              <h2>Reference Angle</h2>
              <LiveRow color={UC_COLORS.sine} label="α" value={`${fmt(live.ref, 1)}° (${live.ref === 45 ? "π/4" : live.ref === 30 ? "π/6" : live.ref === 60 ? "π/3" : live.ref === 90 ? "π/2" : `${fmt(live.ref * Math.PI / 180, 3)} rad`})`} />
            </section>
          <section className="uc-target-rail-section uc-target-explanation-card">
          <h2>Explanation</h2>
          <p className="msk-note">
            {mode === "Quadrants"
              ? `At ${fmt(angle, 0)}°, the terminal side is in Quadrant ${["I", "II", "III", "IV"][live.q - 1]}. Read signs from the CAST table.`
              : mode === "Exact Values"
                ? `Exact values at ${fmt(angle, 0)}°: sin = ${exactish(live.sin)}, cos = ${exactish(live.cos)}.`
                : mode === "Reference Angles"
                  ? `α = ${fmt(live.ref, 0)}° is the acute angle to the x-axis. Signs still come from Quadrant ${["I", "II", "III", "IV"][live.q - 1]}.`
                  : mode === "Angles"
                    ? `θ = ${units === "deg" ? `${fmt(angle, 1)}°` : `${fmt(live.rad, 4)} rad`}. Positive angles run counterclockwise.`
                    : `At ${fmt(angle, 0)}°, the terminal side lies in Quadrant ${["I", "II", "III", "IV"][live.q - 1]}. Use the unit circle to read exact values and signs.`}
          </p>
          </section>
          <ChallengeBox page={page} mode={mode} />
        </aside>
      </div>
      <div className="trig-target-footer uc-target-footer">
        <MockupLearningStrip page={page} mode={mode} />
      </div>
    </>
  );
}

import { useStudioState } from "../../phase1/StudioModelProvider";
import { useEffect, type ReactNode } from "react";
import { MockupLearningStrip } from "../MockupStudioChrome";
import type { StudioMockupPage } from "../studioMockupCatalog";
import { ChallengeBox, LiveRow, Panel, SliderRow, StatusOk, fmt, useLabMode } from "../studioLabKit";
import { composeWaves } from "./trigonometryTargetMath";

function Toggle({ checked, onChange, children }: { checked: boolean; onChange: (next: boolean) => void; children: ReactNode }) {
  return (
    <label className="msk-toggle trig-target-toggle">
      <input type="checkbox" checked={checked} onChange={(event) => onChange(event.target.checked)} />
      {children}
    </label>
  );
}

function wavePoints(fn: (t: number) => number, y0: number, scaleY: number) {
  return Array.from({ length: 221 }, (_, index) => {
    const t = (index / 220) * 5;
    return `${24 + index * 2.2},${y0 - fn(t) * scaleY}`;
  }).join(" ");
}

function envelopePoints(a1: number, a2: number, f1: number, f2: number, y0: number, scaleY: number, sign: 1 | -1) {
  const beat = Math.abs(f2 - f1);
  return Array.from({ length: 221 }, (_, index) => {
    const t = (index / 220) * 5;
    return `${24 + index * 2.2},${y0 - sign * (a1 + a2) * Math.cos(Math.PI * beat * t) * scaleY}`;
  }).join(" ");
}

export function WavesHarmonicsLab({ page }: { page: StudioMockupPage }) {
  const { tabs, mode, setMode } = useLabMode(page);
  const [amplitude1, setAmplitude1] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:amplitude1", 1);
  const [frequency1, setFrequency1] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:frequency1", 2);
  const [phase1, setPhase1] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:phase1", 0);
  const [vertical1, setVertical1] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:vertical1", 0);
  const [amplitude2, setAmplitude2] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:amplitude2", 0.7);
  const [frequency2, setFrequency2] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:frequency2", 3);
  const [phase2, setPhase2] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:phase2", Math.PI / 4);
  const [vertical2, setVertical2] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:vertical2", 0);
  const [secondWave, setSecondWave] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:secondWave", true);
  const [time, setTime] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:time", 1.25);
  const [standingMode, setStandingMode] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:standingMode", 3);
  const [playing, setPlaying] = useStudioState("WavesHarmonicsLab:WavesHarmonicsLab:playing", false);

  useEffect(() => {
    setSecondWave(mode !== "Simple Wave");
  }, [mode]);

  useEffect(() => {
    if (!playing) return;
    const timer = window.setInterval(() => setTime((value) => value >= 5 ? 0 : value + 0.02), 32);
    return () => window.clearInterval(timer);
  }, [playing]);

  const effectiveF2 = frequency2;
  const effectivePhase2 = mode === "Phase" || mode === "Superposition" ? phase2 : 0;
  const useSecond = mode === "Simple Wave" ? false : secondWave;
  const y1 = (t: number) => amplitude1 * Math.sin(2 * Math.PI * frequency1 * t + phase1) + vertical1;
  const y2 = (t: number) => useSecond ? amplitude2 * Math.sin(2 * Math.PI * effectiveF2 * t + effectivePhase2) + vertical2 : 0;
  const result = (t: number) => y1(t) + y2(t);
  const live = composeWaves(
    time,
    { amplitude: amplitude1, frequency: frequency1, phase: phase1, shift: vertical1 },
    { amplitude: useSecond ? amplitude2 : 0, frequency: effectiveF2, phase: effectivePhase2, shift: vertical2 },
  );
  const omega1 = 2 * Math.PI * frequency1;
  const omega2 = 2 * Math.PI * effectiveF2;
  const period1 = 1 / frequency1;
  const period2 = 1 / effectiveF2;
  const harmonics = [amplitude1, amplitude2, amplitude2 * 0.43, amplitude2 * 0.22, amplitude2 * 0.13, amplitude2 * 0.08, amplitude2 * 0.05];
  const oscillatorAngle = omega1 * time + phase1;
  const oscillatorAngle2 = omega2 * time + effectivePhase2;
  const plotHeight = mode === "Simple Wave" ? 320 : 270;

  return (
    <>
      <nav className="msk-tabs trig-target-tabs wv-target-tabs" aria-label="Waves modes">
        {tabs.map((item) => (
          <button key={item} type="button" className={item === mode ? "active" : ""} aria-pressed={item === mode} onClick={() => setMode(item)}>{item}</button>
        ))}
      </nav>
