          failLab={{ to: item.to, label: item.label }}
          onPass={() => {
            setScore((value) => value + 1);
            setIndex((value) => value + 1);
          }}
        />
      ) : (
        <p className="ns-badge is-good">Quiz complete: {score}/{QUIZ.length}. Accuracy notes are below.</p>
      )}
      {!item ? (
        <div className="ns-accuracy">
          <article>
            <h3>Rational numbers</h3>
            <MathExpression value={"\\mathbb{Q}=\\{p/q:p,q\\in\\mathbb{Z}, q\\ne 0\\}"} display />
            <p>A number is rational when it can be written as an integer fraction.</p>
            <p>0.999… = 1 exactly: both are the same rational, not a sequence that “never arrives.”</p>
          </article>
          <article>
            <h3>Irrational numbers</h3>
            <p>Non-terminating, non-repeating decimals, including √p for prime p.</p>
          </article>
        </div>
      ) : null}
      {!item ? <button type="button" className="ns-soft" onClick={() => { markLabComplete("practice"); onComplete?.(); }}>Mark practice complete</button> : null}
    </LabChrome>
  );
}

function CompleteCheck({ prompt, answer, onPass, failLab }: { prompt: string; answer: string; onPass: () => void; failLab?: { to: string; label: string } }) {
  const [value, setValue] = useStudioState("NumberSystemsLabs:CompleteCheck:value", "");
  const [status, setStatus] = useState("");
  const [failed, setFailed] = useStudioState("NumberSystemsLabs:CompleteCheck:failed", false);
  return (
    <form
      className="ns-check"
      onSubmit={(event) => {
        event.preventDefault();
        const ok = value.trim().toLowerCase() === answer;
        setStatus(ok ? "Correct." : "Not yet. Open the matching lab to see why.");
        setFailed(!ok);
        if (ok) onPass();
      }}
    >
      <p>{prompt}</p>
      <input value={value} onChange={(event) => setValue(event.target.value)} aria-label={prompt} placeholder="yes or no" />
      <button type="submit">Check</button>
      {status ? <p role="status">{status}</p> : null}
      {failed && failLab ? <Link className="ns-soft" to={failLab.to}>{failLab.label}</Link> : null}
    </form>
  );
}

import { useStudioState } from "./StudioModelProvider";
import { useEffect, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { activityLink, joinActivity, makeClassCode, pauseActivity, pushSnapshot, startActivity, type ClassroomActivity } from "./studioClassroom";

export function ClassroomBar() {
  const [params, setParams] = useSearchParams();
  const [code, setCode] = useStudioState("ClassroomBar:ClassroomBar:code", params.get("class") ?? "");
  const [nick, setNick] = useStudioState("ClassroomBar:ClassroomBar:nick", "Ada");
  const [status, setStatus] = useState("");
  const [joined, setJoined] = useStudioState<ClassroomActivity | null>("ClassroomBar:ClassroomBar:joined", null);

  useEffect(() => {
    const fromUrl = params.get("class");
    if (fromUrl) setCode(fromUrl.toUpperCase());
  }, [params]);

  useEffect(() => {
    setJoined(code ? joinActivity(code) : null);
  }, [code]);

  const start = () => {
    const next = makeClassCode();
    const href = typeof window === "undefined" ? "/" : window.location.pathname + window.location.search;
    startActivity(next, href, nick);
    pushSnapshot(href.includes("class=") ? href : activityLink(href, next), `Room ${next}`);
    setCode(next);
    setParams((prev) => {
      const copy = new URLSearchParams(prev);
      copy.set("class", next);
      return copy;
    }, { replace: true });
    setStatus(`Room ${next} · students join with this code`);
  };

  const join = () => {
    const found = joinActivity(code);
    setJoined(found);
    if (!found) {
      setStatus("No room with that code yet.");
      return;
    }
    setStatus(found.paused ? "Teacher paused. Wait." : `Joined ${found.nickname}'s room`);
    if (found.href && typeof window !== "undefined" && !found.paused) {
      window.history.replaceState(window.history.state, "", found.href.includes("class=") ? found.href : activityLink(found.href, code));
    }
  };

  return (
    <div className="msk-classroom" role="group" aria-label="Classroom activity">
      <button type="button" className="msk-soft" onClick={start}>Start activity</button>
      <input aria-label="Room code" value={code} onChange={(e) => setCode(e.target.value.toUpperCase())} placeholder="Room code" />
      <input aria-label="Nickname" value={nick} onChange={(e) => setNick(e.target.value)} placeholder="Nickname" />
      <button type="button" className="msk-soft" onClick={join}>Join</button>
      {code ? (
        <button type="button" className="msk-soft" onClick={() => { pauseActivity(code, !(joined?.paused)); setJoined(joinActivity(code)); setStatus("Pause/push sent"); }}>
          {joined?.paused ? "Push" : "Pause"}
        </button>
      ) : null}
      {status ? <small>{status}</small> : <small>Anonymous nicknames. Share ?class= and ?fig=.</small>}
    </div>
  );
}

import { useStudioState } from "./StudioModelProvider";
import { useEffect, useMemo } from "react";
import FunctionGraphCanvas, { type FunctionGraphView } from "../../components/math-lab/FunctionGraphCanvas";
import { sampleFunction } from "../../utils/mathEngine/graphSampler";

const COLORS = ["#06b6d4", "#8b5cf6", "#f59e0b", "#10b981"];
const DEFAULT_VIEW: FunctionGraphView = { xMin: -2 * Math.PI, xMax: 2 * Math.PI, yMin: -2, yMax: 2 };

type Props = {
  expressions: string[];
  labels?: string[];
  traceX?: number;
  onTraceChange?: (x: number) => void;
  view?: FunctionGraphView;
  compact?: boolean;
};

export default function StudioGraphWidget({ expressions, labels, traceX, onTraceChange, view, compact = true }: Props) {
  const preset = view ?? DEFAULT_VIEW;
  const [box, setView] = useStudioState<FunctionGraphView>("StudioGraphWidget:StudioGraphWidget:box", preset);
  const [x, setTrace] = useStudioState("StudioGraphWidget:StudioGraphWidget:x", traceX ?? 0);
  useEffect(() => {
    setView(preset);
  }, [preset.xMax, preset.xMin, preset.yMax, preset.yMin]);
  useEffect(() => {
    if (typeof traceX === "number") setTrace(traceX);
  }, [traceX]);
  const series = useMemo(() => expressions.map((input, i) => {
    const sample = sampleFunction(input, box.xMin, box.xMax, 180);
    return {
      id: `s${i}`,
      label: labels?.[i] ?? input,
      color: COLORS[i % COLORS.length] ?? "#06b6d4",
      points: sample.points,
      visible: true,
      style: "line" as const,
    };
  }), [box.xMax, box.xMin, expressions, labels]);
  return (
    <div className={`studio-graph-widget${compact ? " is-compact" : ""}`} data-studio-graph="1">
      <FunctionGraphCanvas
        series={series}
        view={box}
        showGrid
        showAxes
        traceX={x}
        onResetView={() => setView(preset)}
        onTraceChange={(next) => {
          setTrace(next);
          onTraceChange?.(next);
        }}
        onViewChange={setView}
      />
    </div>
  );
}

import { createContext, useCallback, useContext, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore, type Dispatch, type ReactNode, type SetStateAction } from "react";
import { useLocation, useSearchParams } from "react-router-dom";
import { compatibleModel, ModelLedger, serializableModel, type ModelValues } from "./modelLedger";
import { decodeFigState, encodeFigState } from "./studioKernel";

type ModelContext = { ledger: ModelLedger; exact: boolean; setExact: (value: boolean) => void; share: () => Promise<void>; status: string };
const Context = createContext<ModelContext | null>(null);
let exactPreference = false;
export const readExactPreference = () => exactPreference;

export function StudioModelProvider({ children }: { children: ReactNode }) {
  const [params, setParams] = useSearchParams();
  const { pathname } = useLocation();
  const [ledger] = useState(() => {
    const decoded = decodeFigState(params.get("fig"), { version: 1, values: {} as ModelValues });
    return new ModelLedger(decoded.version === 1 && decoded.values && serializableModel(decoded.values) ? decoded.values : {});
  });
  const [exact, setExactState] = useState(params.get("exact") === "1");
  const [status, setStatus] = useState("");
  useLayoutEffect(() => { exactPreference = exact; return () => { exactPreference = false; }; }, [exact]);
  const setExact = useCallback((value: boolean) => { exactPreference = value; setExactState(value); }, []);
  const share = useCallback(async () => {
    const updated = new URLSearchParams(window.location.search);
    updated.set("fig", encodeFigState({ version: 1, values: ledger.values }));
    if (exact) updated.set("exact", "1"); else updated.delete("exact");
    const url = `${window.location.origin}${pathname}?${updated}`;
    setParams(updated, { replace: true });
    try { await navigator.clipboard.writeText(url); setStatus("Link copied with the current model values and selected mode."); }
    catch { setStatus("Figure saved in this page URL. Copy the address to share it."); }
  }, [exact, ledger, pathname, setParams]);
  const context = useMemo(() => ({ ledger, exact, setExact, share, status }), [ledger, exact, setExact, share, status]);
  return <Context.Provider value={context}>{children}</Context.Provider>;
}

export function useStudioModel() {
  const context = useContext(Context);
  const subscribe = context?.ledger.subscribe ?? (() => () => {});
  const version = context?.ledger.version ?? (() => 0);
  useSyncExternalStore(subscribe, version, version);
  return context;
}

export function useStudioState<T>(key: string, initial: T | (() => T), enabled?: boolean): [T, Dispatch<SetStateAction<T>>];
export function useStudioState<T = undefined>(key: string): [T | undefined, Dispatch<SetStateAction<T | undefined>>];
export function useStudioState<T>(key: string, initial?: T | (() => T), enabled = true) {
  const context = useContext(Context);
  const initialRef = useRef<{ value: T | undefined } | null>(null);
  if (!initialRef.current) initialRef.current = { value: typeof initial === "function" ? (initial as () => T)() : initial };
  const defaults = initialRef.current.value;
  const [value, setValue] = useState<T | undefined>(() => enabled && context ? context.ledger.initial(key, defaults) : defaults);
  const valueRef = useRef(value);
  valueRef.current = value;
  const registered = enabled && !!context && serializableModel(defaults);
  useLayoutEffect(() => {
    if (!registered || !context) return;
    return context.ledger.register(key, defaults, valueRef.current, next => { valueRef.current = next as T; setValue(next as T); });
  }, [context?.ledger, defaults, key, registered]);
  const set = useCallback((next: SetStateAction<T | undefined>) => {
    const resolved = typeof next === "function" ? (next as (previous: T | undefined) => T)(valueRef.current) : next;
    if (registered && context && compatibleModel(defaults, resolved)) context.ledger.commit(key, resolved, true);
    else { valueRef.current = resolved; setValue(resolved); }
  }, [context?.ledger, defaults, key, registered]);
  return [value, set] as const;
}

import { useStudioState } from "../phase1/StudioModelProvider";
import { Canvas } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import { useEffect, useMemo, type ReactNode } from "react";
import * as THREE from "three";
import "./studioMath3D.css";

export type Vec3 = [number, number, number];

function v3(v: Vec3) {
  return new THREE.Vector3(v[0], v[1], v[2]);
}

export function StudioMath3D({
  children,
  label,
  camera = [7.2, 5.4, 8.4],
  compact = false,
}: {
  children: ReactNode;
  label: string;
  camera?: Vec3;
  compact?: boolean;
}) {
  const [ready, setReady] = useStudioState("studioMath3D:StudioMath3D:ready", false);
  useEffect(() => {
    setReady(true);
  }, []);
  return (
    <div className={`studio-math-3d${compact ? " is-compact" : ""}`} data-engine="three" role="img" aria-label={label}>
      {ready ? (
        <Canvas camera={{ position: camera, fov: 42 }} dpr={[1, 1.5]} gl={{ antialias: true, alpha: false }}>
          <color attach="background" args={["#f7fbff"]} />
          <ambientLight intensity={1.2} />
          <directionalLight position={[6, 9, 5]} intensity={1.45} />
          <hemisphereLight args={["#ffffff", "#c5d4ea", 0.45]} />
          <gridHelper args={[12, 12, "#94a3b8", "#e2e8f0"]} />
          <MathAxes />
          {children}
          <OrbitControls makeDefault enableDamping dampingFactor={0.12} />
        </Canvas>
      ) : (
        <p className="studio-math-3d-ssr">Three.js 3D engine · drag to orbit · scroll to zoom</p>
      )}
    </div>
  );
}

export function MathAxes({ length = 3.4 }: { length?: number }) {
  return (
    <group>
      <MathArrow from={[0, 0, 0]} to={[length, 0, 0]} color="#94a3b8" />
      <MathArrow from={[0, 0, 0]} to={[0, length, 0]} color="#94a3b8" />
      <MathArrow from={[0, 0, 0]} to={[0, 0, length]} color="#94a3b8" />
    </group>
  );
}

export function MathArrow({
  from = [0, 0, 0],
  to,
  color,
}: {
  from?: Vec3;
  to: Vec3;
  color: string;
}) {
  const geom = useMemo(() => {
    const start = v3(from);
    const end = v3(to);
    const dir = end.clone().sub(start);
    const len = dir.length();
    if (len < 1e-6) return null;
    const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
    const shaftLen = Math.max(0.05, len - 0.2);
    const mid = start.clone().add(dir.clone().setLength(shaftLen / 2));
    const tip = start.clone().add(dir.clone().setLength(shaftLen + 0.1));
    return { quat, shaftLen, mid: mid.toArray() as Vec3, tip: tip.toArray() as Vec3 };
  }, [from, to]);
  if (!geom) return null;
  return (
    <group>
      <mesh position={geom.mid} quaternion={geom.quat}>
        <cylinderGeometry args={[0.032, 0.032, geom.shaftLen, 10]} />
        <meshStandardMaterial color={color} />
      </mesh>
      <mesh position={geom.tip} quaternion={geom.quat}>
        <coneGeometry args={[0.085, 0.2, 12]} />
        <meshStandardMaterial color={color} />
      </mesh>
    </group>
  );
}

export function MathParallelogram({
  a,
  b,
  color,
}: {
  a: Vec3;
  b: Vec3;
  color: string;
}) {
  const geometry = useMemo(() => {
    const pts = [new THREE.Vector3(0, 0, 0), v3(a), v3(a).add(v3(b)), v3(b)];
    const g = new THREE.BufferGeometry().setFromPoints(pts);
    g.setIndex([0, 1, 2, 0, 2, 3]);
    g.computeVertexNormals();
    return g;
  }, [a, b]);
  return (
    <mesh geometry={geometry}>
      <meshStandardMaterial color={color} transparent opacity={0.28} side={THREE.DoubleSide} depthWrite={false} />
    </mesh>
  );
}

export function EquationPlane({
  a,
  b,
  c,
  d,
  color,
}: {
  a: number;
  b: number;
  c: number;
  d: number;
  color: string;
}) {
  const spec = useMemo(() => {
    const n = new THREE.Vector3(a, b, c);
    const mag = n.length();
    if (mag < 1e-8) return null;
    n.multiplyScalar(1 / mag);
    const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), n);
    const dist = d / mag;
    return { quat, pos: n.multiplyScalar(dist).toArray() as Vec3 };
  }, [a, b, c, d]);
  if (!spec) return null;
  return (
    <mesh position={spec.pos} quaternion={spec.quat}>
      <planeGeometry args={[8, 8]} />
      <meshStandardMaterial color={color} transparent opacity={0.32} side={THREE.DoubleSide} depthWrite={false} />
    </mesh>
  );
}

export function MathParallelepiped({
  columns,
  color = "#8b45f4",
}: {
  columns: number[][];
  color?: string;
}) {
  const c0 = columns[0] ?? [1, 0, 0];
  const c1 = columns[1] ?? [0, 1, 0];
  const c2 = columns[2] ?? [0, 0, 1];
  const e1: Vec3 = [c0[0] ?? 0, c0[1] ?? 0, c0[2] ?? 0];
  const e2: Vec3 = [c1[0] ?? 0, c1[1] ?? 0, c1[2] ?? 0];
  const e3: Vec3 = [c2[0] ?? 0, c2[1] ?? 0, c2[2] ?? 0];
  return (
    <group>
      <MathParallelogram a={e1} b={e2} color={color} />
      <MathArrow to={e1} color="#147df2" />
      <MathArrow to={e2} color="#22c55e" />
      <MathArrow to={e3} color={color} />
    </group>
  );
}

export function TransformedCube({ matrix }: { matrix: number[][] }) {
  const corners = useMemo(() => {
    const pts: Vec3[] = [];
    for (const x of [0, 1]) {
      for (const y of [0, 1]) {
        for (const z of [0, 1]) {
          pts.push(applyMat3(matrix, [x, y, z]));
        }
      }
    }
    return pts;
  }, [matrix]);
  return (
    <group>
      {corners.map((p, i) => (
        <mesh key={i} position={p}>
          <sphereGeometry args={[0.05, 10, 8]} />
          <meshStandardMaterial color="#7c3aed" />
        </mesh>
      ))}
      <MathParallelepiped columns={[[matrix[0]?.[0] ?? 1, matrix[1]?.[0] ?? 0, matrix[2]?.[0] ?? 0], [matrix[0]?.[1] ?? 0, matrix[1]?.[1] ?? 1, matrix[2]?.[1] ?? 0], [matrix[0]?.[2] ?? 0, matrix[1]?.[2] ?? 0, matrix[2]?.[2] ?? 1]]} />
    </group>
  );
}

export function SolidKind({ kind }: { kind: string }) {
  if (kind === "Spheres") {
    return (
      <mesh>
        <sphereGeometry args={[1.35, 36, 28]} />
        <meshStandardMaterial color="#147df2" transparent opacity={0.85} />
      </mesh>
    );
  }
  if (kind === "Cylinders") {
    return (
      <mesh rotation={[0, 0, 0]}>
        <cylinderGeometry args={[0.95, 0.95, 2.2, 36]} />
        <meshStandardMaterial color="#147df2" />
      </mesh>
    );
  }
  if (kind === "Cones") {
    return (
      <mesh position={[0, 0.2, 0]}>
        <coneGeometry args={[1.15, 2.2, 36]} />
        <meshStandardMaterial color="#8b45f4" />
      </mesh>
    );
  }
  if (kind === "Nets") {
    return (
      <mesh>
        <boxGeometry args={[1.6, 1.6, 1.6]} />
        <meshStandardMaterial color="#38bdf8" wireframe />
      </mesh>
    );
  }
  return (
    <group>
      <mesh>
        <cylinderGeometry args={[1, 1, 1.8, 28]} />
        <meshStandardMaterial color="#08b9dd" transparent opacity={0.7} />
      </mesh>
      <mesh rotation={[Math.PI / 3, 0, 0.2]}>
        <planeGeometry args={[3.2, 3.2]} />
        <meshStandardMaterial color="#f59e0b" transparent opacity={0.35} side={THREE.DoubleSide} />
      </mesh>
    </group>
  );
}

export function ArRoomScene({ dist, elev, scale }: { dist: number; elev: number; scale: number }) {
  const h = dist * Math.tan((elev * Math.PI) / 180) * 0.08 * scale;
  return (
    <group>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]}>
        <planeGeometry args={[10, 10]} />
        <meshStandardMaterial color="#d6cfc4" />
      </mesh>
      <mesh position={[0, h / 2, -1.2]}>
        <coneGeometry args={[1.1, Math.max(0.4, h), 5]} />
        <meshStandardMaterial color="#8b45f4" />
      </mesh>
      <mesh position={[2.2, 0.55, 0.4]}>
        <boxGeometry args={[1.2, 1.1, 1.2]} />
        <meshStandardMaterial color="#94a3b8" />
      </mesh>
    </group>
  );
}

function applyMat3(M: number[][], v: Vec3): Vec3 {
  return [
    (M[0]?.[0] ?? 0) * v[0] + (M[0]?.[1] ?? 0) * v[1] + (M[0]?.[2] ?? 0) * v[2],
    (M[1]?.[0] ?? 0) * v[0] + (M[1]?.[1] ?? 0) * v[1] + (M[1]?.[2] ?? 0) * v[2],
    (M[2]?.[0] ?? 0) * v[0] + (M[2]?.[1] ?? 0) * v[1] + (M[2]?.[2] ?? 0) * v[2],
  ];
}

export function lift2(M: number[][]): number[][] {
  return [
    [M[0]?.[0] ?? 1, M[0]?.[1] ?? 0, 0],
    [M[1]?.[0] ?? 0, M[1]?.[1] ?? 1, 0],
    [0, 0, 1],
  ];
}

export function MathPolyline({ points, color }: { points: Vec3[]; color: string }) {
  const geom = useMemo(() => new THREE.BufferGeometry().setFromPoints(points.map((p) => v3(p))), [points]);
  return (
    <line geometry={geom}>
      <lineBasicMaterial color={color} />
    </line>
  );
}

export function EulerHelix({ theta }: { theta: number }) {
  const tmax = Math.max(theta, 0.04);
  const pts = useMemo((): Vec3[] => {
    const n = 180;
    return Array.from({ length: n }, (_, i) => {
      const t = (i / (n - 1)) * tmax;
      return [Math.cos(t), t * 0.28, Math.sin(t)];
    });
  }, [tmax]);
  const tip: Vec3 = [Math.cos(tmax), tmax * 0.28, Math.sin(tmax)];
  return (
    <group>
      <MathPolyline points={pts} color="#0891b2" />
      <mesh position={tip}>
        <sphereGeometry args={[0.1, 16, 12]} />
        <meshStandardMaterial color="#f59e0b" />
      </mesh>
    </group>
  );
}

export function ElevationTriangle({ dist, height }: { dist: number; height: number }) {
  const d = Math.max(0.4, dist * 0.08);
  const h = Math.max(0.2, height * 0.08);
  return (
    <group>
      <MathArrow to={[d, 0, 0]} color="#22d3ee" />
      <MathArrow from={[d, 0, 0]} to={[d, h, 0]} color="#8b45f4" />
      <MathArrow to={[d, h, 0]} color="#f59e0b" />
    </group>
  );
}

export function ProjectilePaths({
  a,
  b,
  play,
}: {
  a: Array<{ x: number; y: number }>;
  b: Array<{ x: number; y: number }>;
  play: { x: number; y: number };
}) {
  const scale = 0.12;
  const toPts = (pts: Array<{ x: number; y: number }>): Vec3[] => pts.map((p) => [p.x * scale, p.y * scale, 0]);
  return (
    <group>
      <MathPolyline points={toPts(a)} color="#147df2" />
      <MathPolyline points={toPts(b)} color="#8b45f4" />
      <mesh position={[play.x * scale, play.y * scale, 0]}>
        <sphereGeometry args={[0.12, 12, 10]} />
        <meshStandardMaterial color="#f59e0b" />
      </mesh>
    </group>
  );
}

export function WasherSolid({
  lo,
  hi,
  inner,
  slices,
}: {
  lo: number;
  hi: number;
  inner: (x: number) => number;
  slices: number;
}) {
  const count = Math.max(8, slices);
  return (
    <group>
      {Array.from({ length: count }, (_, i) => {
        const x = lo + (i / (count - 1)) * (hi - lo);
        const rIn = Math.min(1.45, Math.abs(inner(x)) * 0.35);
        return (
          <group key={i} position={[x * 1.35, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
            <mesh>
              <cylinderGeometry args={[1.55, 1.55, 0.14, 28]} />
              <meshStandardMaterial color="#f59e0b" transparent opacity={0.28} />
            </mesh>
            <mesh>
              <cylinderGeometry args={[rIn, rIn, 0.16, 24]} />
              <meshStandardMaterial color="#e0f2fe" />
            </mesh>
          </group>
        );
      })}
    </group>
