    [shown, setShown] = useState(4),
    [playing, setPlaying] = useState(false),
    [menu, setMenu] = useState(false),
    result = ((value % mod) + mod) % mod,
    c = 180,
    r = 118,
    pts = Array.from({ length: mod }, (_, i) => {
