    if (!playing) return;
    setShown(0);
    let s = 0,
      goal = Math.abs(value);
    const id = setInterval(() => {
      s++;
      setShown(s);
      if (s >= goal) {
        clearInterval(id);
        setPlaying(false);
      }
    }, 330);
    return () => clearInterval(id);
  }, [playing, value, mod]);
  const reset = () => {
    setMod(9);
    setValue(-4);
    setShown(4);
    setPlaying(false);
    setMenu(false);
  };
  return (
    <main className="negative-mod">
      <header>
        <button onClick={() => nav(-1)} aria-label="Back to visual proofs">
          <ArrowLeft />
        </button>
        <h1>Negative Numbers Modulo n</h1>
